INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (1, 'هیچ چیزی که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، معنایی ندارد.', 'این میز هیچ معنایی ندارد.
این صندلی هیچ معنایی ندارد.
این دست هیچ معنایی ندارد.
این پا هیچ معنایی ندارد.
این قلم هیچ معنایی ندارد.

آن درهیچ معنایی ندارد.
آن بدن هیچ معنایی ندارد.
آن لامپ هیچ معنایی ندارد.
آن علامت هیچ معنایی ندارد.
آن سایه هیچ معنایی ندارد.', 'هیچ چیزی که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، معنایی ندارد.

حالا به آرامی به پیرامون خود نگاه کن و تمرین کن که این ایده را به طور بسیار اختصاصی برای هر چیزی که می‌بینی، به کار ببری: این میز هیچ معنایی ندارد. این صندلی هیچ معنایی ندارد. این دست هیچ معنایی ندارد. این پا هیچ معنایی ندارد. این قلم هیچ معنایی ندارد.

سپس توجه خود را به دورتر از محیط نزدیک خود معطوف کن و این ایده را برای موضوعات بیشتری به کار ببر: آن درهیچ معنایی ندارد. آن بدن هیچ معنایی ندارد. آن لامپ هیچ معنایی ندارد. آن علامت هیچ معنایی ندارد. آن سایه هیچ معنایی ندارد.

توجه کن که با این جملات بدون هیچ ترتیبی تمرین کنی و اجازه ندهی نوع چیزهایی که با آن‌ها کار می‌کنی تفاوتی در به کار بردن ایده ایجاد کند. هدف انجام تمرین امروز، همین است. این جمله باید صرفاً برای هر چیزی که می‌بینی به کار برود. در زمان تمرین با ایده امروز، از آن کاملاً بدون تمایز استفاده کن. تلاش نکن این ایده را برای همه چیزهایی که می‌بینی به کار ببری، زیرا تمرین‌ها نباید حالت آئینی به خود بگیرند. صرفاً مطمئن شو که هیچ چیزی را که می‌بینی، مخصوصاً حذف نکرده‌ای. مادامی که به کار بردن این ایده مد نظر باشد، هر چیزی مانند چیز دیگر است.

هر یک از سه تمرین اول نباید بیش از دو بار در روز انجام شود، ترجیحاً صبح و عصر. و هر برنامه تمرین نباید بیش از حدود یک دقیقه طول بکشد، مگر رعایت این زمان موجب احساس شتابزدگی شود. احساس راحتی و فراغ بال در انجام این تمرین‌ها اساسی است.', 'https://acim-farsi.org/workbook/lesson/1', 'https://acim-farsi.org/audio/workbook/lesson/1.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (2, 'من به هر چیزی که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، همه معنایی را که برای من دارد داده‌ام.', 'من به هر چیزی که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، همه معنایی را که برای من دارد داده‌ام.', 'من به هر چیزی که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، همه معنایی را که برای من دارد داده‌ام.

تمرین‌ها با این ایده نیز همانند تمرینها با ایده اول است. ابتدا از چیزهای نزدیک به خود آغاز کن و برای هر چیزی که به چشمت می‌خورد این ایده را به کار ببر. سپس حدود خود را گسترش بده. سر خود را بچرخان تا با هر چیزی که در دو طرف تو وجود دارد تمرین کنی. اگر ممکن باشد، برگرد و این ایده را برای هر چیزی که در پشت سرت است به کار ببر. تا حد ممکن در انتخاب سوژه‌ها برای تمرین بدون تمایز بمان. بر هیچ چیزی اختصاصاً تمرکز نکن، و تلاش نکن همه چیزهایی را که در یک محیط هستند وارد تمرین کنی زیرا موجب احساس فشار می‌شود.

صرفاً نگاه خود را به راحتی و نسبتاً سریع به پیرامونت بینداز. تلاش کن از انتخاب چیزها بر اساس اندازه، روشنی، رنگ، جنس یا اهمیت نسبی که برای تو دارند بپرهیزی. به سادگی با سوژه‌هایی که می‌بینی تمرین کن. سعی کن تمرین را با یک بدن یا یک دکمه، یک حشره یا کف زمین، یک دست یا یک سیب با سهولت یکسان انجام دهی. تنها معیار به کار بردن این ایده برای هر چیزی صرفاً این است که چشم تو به آن افتاده باشد. تلاش نکن هیچ چیز خاصی را وارد تمرین کنی، اما مطمئن شو که چیزی را مخصوصاً حذف نکرده‌ای.', 'https://acim-farsi.org/workbook/lesson/2', 'https://acim-farsi.org/audio/workbook/lesson/2.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (3, 'من هیچ چیزی را که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، درک نمی‌کنم.', 'من هیچ چیزی را که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، درک نمی‌کنم.', 'من هیچ چیزی را که در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم، درک نمی‌کنم.

با این ایده نیز مانند ایده‌های قبلی تمرین کن، بدون تمایز قایل شدن به هیچ شکلی. هر چیزی که می‌بینی یک موضوع مناسب برای به کار بردن این ایده است. مطمئن شو مناسب بودن هیچ چیزی را برای تمرین با این ایده مورد پرسش قرار نمی‌دهی. این‌ها تمرین‌هایی در مورد قضاوت نیستند. هر چیزی در صورت دیده شدن برای تمرین مناسب است. برخی از چیزهایی که می‌بینی ممکن است برای تو معنایی حاوی بار احساسی داشته باشند. سعی کن این احساس‌ها را کنار بگذاری، و صرفاً با این چیزها دقیقاً مانند هر چیز دیگر تمرین کنی.

نکته این تمرین‌ها کمک به این است که تو بتوانی ذهن خود را از تمامی تداعی‌های قبلی پاک کنی، چیزها را دقیقاً آن‌گونه ببینی که اکنون به نظرت می‌رسند، و متوجه شوی که واقعاً چه درک ناچیزی در مورد آن‌ها داری. بنابراین اساسی است که در انتخاب چیزهایی که ایده امروز را برای آن‌ها به کار می‌بری، باز بودن ذهن خود را کاملاً حفظ کنی که در بند قضاوت نباشد. برای تمرین با این ایده نیز هر چیزی مانند چیز دیگر است، همانقدر مناسب و در نتیجه همانقدر مفید.', 'https://acim-farsi.org/workbook/lesson/3', 'https://acim-farsi.org/audio/workbook/lesson/3.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (4, 'این افکار هیچ معنایی ندارند. آن‌ها مانند چیزهایی هستند که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم.', 'این فکر در مورد ــــــ هیچ معنایی ندارد.
این مثل چیزهایی است که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم.', 'این افکار هیچ معنایی ندارند. آن‌ها مانند چیزهایی هستند که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم.

برخلاف تمرین‌های پیشین، این تمرینها با ایده روز آغاز نمی‌شوند. در این دوره‌های تمرینی، با توجه کردن به افکاری که برای مدت حدود یک دقیقه به ذهنت می‌رسد، آغاز کن. سپس این ایده را برای آن‌ها به کار ببر. اگر در حال حاضر از افکار ناراحت آگاه هستی، از این افکار به عنوان سوژه تمرین استفاده کن. با این حال، فقط افکاری را انتخاب نکن که فکر می کنی «بد» هستند. اگر خود را تربیت کنی که ناظر افکار خود باشی، متوجه خواهی شد افکار چنان مخلوطی را نشان می‌دهند که به مفهومی، هیچ یک از آن‌ها را نمی‌توان «خوب» یا «بد» خواند. به همین دلیل هیچ معنایی ندارند.

درانتخاب سوژه‌های تمرین ایده امروز، صرفاً لازم است که بتوان به طور خاص روی آن‌ها کار کرد. نترس از این که با افکار «خوب» هم مانند افکار «بد» کار کنی. هیچ کدام نشانگر افکار واقعی تو نیستند، و افکار واقعی تو توسط آن‌ها پوشیده شده‌اند. افکار «خوب» صرفاً سایه‌هایی از آن چیزی هستند که ورای آن‌ها است، و سایه‌ها دیدن را دشوار می‌کنند. افکار «بد» سدهای دیدن هستند، و دیدن را غیرممکن می‌سازند. تو هیچ‌کدام را نمی‌خواهی.

این یک تمرین اساسی است، و چند بار در شکلهای نسبتاً متفاوت تکرار خواهد شد. در این‌جا قصد تربیت تو در گام‌های نخستین به سمت هدف جداسازی بی‌معنا از بامعنا است. تمرین امروز نخستین تلاش است در راستای این هدف بلند مدت که دیدن بی‌معنا را به عنوان بیرون از خود، و بامعنا را در درون خود یاد بگیری. همچنین این آغاز تربیت ذهن تو برای تشخیص این است که چه چیزی مشابه و چه چیزی متفاوت است.

برای استفاده از فکر خود برای تمرین ایده امروز، هر فکر را با شکل یا رویداد مرکزی که حاوی آن است مشخص کن؛ به عنوان نمونه: این فکر در مورد ــــــ هیچ معنایی ندارد. این مثل چیزهایی است که من در این اتاق [در این خیابان، از این پنجره، در این مکان] می‌بینم.

تو همچنین می‌توانی این ایده را برای فکر خاصی به کار ببری که تشخیص می‌دهی مضر است. این تمرین مفید است، اما جایگزین کار کردن با افکار اتفاقی‌تر که باید برای تمرین دنبال کنی، نمی‌شود. با این حال، ذهن خود را برای زمانی بیش از حدود یک دقیقه تمرین نده. تو هنوز بیش از آن نیازموده هستی که بتوانی از تمایل به مشغولیت ذهنی بیهوده پرهیز کنی.

بعلاوه، از آن‌جا که این تمرین‌ها در نوع خود نخستین هستند، تو تعلیق قضاوت در رابطه با افکار را خصوصاً مشکل خواهی یافت. این تمرینات را بیش از سه یا چهار بار در روز تکرار نکن. ما بعداً به آن‌ها برمی‌گردیم.', 'https://acim-farsi.org/workbook/lesson/4', 'https://acim-farsi.org/audio/workbook/lesson/4.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (5, 'من هرگز به دلیلی که فکر می‌کنم، آشفته نیستم.', 'من از ـــــــ به آن علتی که فکر می‌کنم، عصبانی نیستم.
من از ـــــــ به آن علتی که فکر می‌کنم، نمی‌ترسم.', 'من هرگز به دلیلی که فکر می‌کنم، آشفته نیستم.

این ایده، مانند ایده قبلی، می‌تواند با هر فرد، شرایط یا رویدادی که فکر می‌کنی موجب رنج تو است تمرین شود. آن را به طور اختصاصی برای هر چیزی که باور داری علت آشفتگی تو است به کار ببر، با استفاده از توصیف احساس خود با هر کلمه‌ای که به نظرت صحیح می‌آید. ممکن است آشفتگی تو به شکل ترس، نگرانی، افسردگی، اضطراب، خشم، نفرت حسادت یا به هر شکل‌ دیگری ظهور کند، و تو هر یک از آن‌ها را متفاوت درک کنی. این حقیقی نیست. با این همه، تا زمانی که تو بیاموزی که شکل اهمیتی ندارد، هر شکلی یک سوژه مناسب برای تمرین امروز است. تمرین با یک ایده یکسان برای همه آن‌ها به صورت جداگانه، نخستین گام در تشخیص نهایی این است که همه آن‌ها یکسان هستند.

در زمان به کار بردن ایده امروز برای علت خاص یک آشفتگی در هر شکلی که درک کرده‌ای، هم از نام شکل ظهور آشفتگی برای خودت استفاده کن، و هم از علتی که آشفتگی خود را به آن نسبت می‌دهی. برای نمونه: من از ـــــــ به آن علتی که فکر می‌کنم، عصبانی نیستم. من از ـــــــ به آن علتی که فکر می‌کنم، نمی‌ترسم.

اما باز، این نباید جایگزین زمان‌های تمرینی شود که در آن تو ابتدا ذهن خود را جستجو می‌کنی تا «منابع» آشفتگی را که به آن‌ها باور داری، و شکل‌هایی از آشفتگی را که ظاهراً پدید می‌آورند، بیابی.

در این تمرین‌ها، بیش از تمرین‌های قبل، متوجه خواهی شد که بدون تمایز بودن و پرهیز از دادن وزن بیشتر به برخی سوژه‌ها نسبت به بقیه، دشوار است. این جمله پیش از تمرین‌ها می‌تواند کمک کننده باشد: هیچ آشفتگی کوچکی وجود ندارد. همه آن‌ها به یک اندازه آرامش ذهن مرا مختل می‌کنند.

سپس ذهن خود را برای هرچه که آزارت می‌دهد، آزمون کن. صرفنظر از این که فکر می‌کنی چقدر کم یا چقدر زیاد آزارنده هستند.

همچنین ممکن است متوجه شوی که تمایل تو برای تمرین ایده امروز با برخی منابع آشفتگی که درک می‌کنی نسبت به برخی دیگر کمتر است. . اگر چنین اتفاقی افتاد، ابتدا به این فکر کن: من نمی‌توانم این شکل از آشفتگی را حفظ کنم و بقیه را رها کنم. پس برای اهداف این تمرینها، همه آن‌ها را یکسان خواهم دید.

سپس ذهن خود را برای مدت حداکثر حدود یک دقیقه جستجو کن، و تلاش کن تعدادی از شکل‌های مختلف آشفتگی را تعیین کنی که موجب آزار تو می‌شوند، صرفنظر از اهمیت نسبی که تو ممکن است به آن‌ها بدهی. ایده امروز را با هر یک از آن‌ها تمرین کن، با استفاده از نام منبع آشفتگی آن‌گونه که تو درک می‌کنی، و همچنین احساسی که تو در حال تجربه کردن آن هستی. مثال‌های بیشتر عبارتند از: من در مورد ـــــــ به آن علتی که فکر می‌کنم، نگران نیستم. من در مورد ـــــــ به آن علتی که فکر می‌کنم، افسرده نیستم. سه یا چهار بار در روز کفایت می‌کند.', 'https://acim-farsi.org/workbook/lesson/5', 'https://acim-farsi.org/audio/workbook/lesson/5.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (6, 'من آشفته هستم زیرا چیزی را می‌بینم که آن‌جا نیست.', 'من از ـــــــ عصبانی هستم زیرا چیزی را می‌بینم که آن‌جا نیست.

من در مورد ـــــــ نگران هستم زیرا چیزی را می‌بینم که آن‌جا نیست.', 'من آشفته هستم زیرا چیزی را می‌بینم که آن‌جا نیست.

تمرین با این ایده هم بسیار مشابه ایده‌های قبلی است. باز، لازم است که هم نام شکل آشفتگی (خشم، ترس، نگرانی، افسردگی و غیره) و هم منبعی که برای آن درک می‌کنیم، در هر تمرین با ایده به طور کاملاً اختصاصی ذکر شود. برای نمونه: من از ـــــــ عصبانی هستم زیرا چیزی را می‌بینم که آن‌جا نیست. من در مورد ـــــــ نگران هستم زیرا چیزی را می‌بینم که آن‌جا نیست.

ایده‌ی امروز برای به کار بردن در مورد هر چیزی که به نظر می‌رسد تو را آشفته می‌کند مفید است، و می‌تواند به نحو سودمندی در طول روز برای این منظور استفاده شود. با این همه، پیش از هر کدام از سه یا چهار برنامه تمرین که برای امروز لازم است، باید مانند تمرینات قبل به مدت حدود یک دقیقه جستجوی ذهنی انجام شود، و سپس این ایده برای هر فکر آشفته کننده‌ای که در جستجو آشکار می‌شود، به کار برده شود.

در این تمرین نیز اگر مقاومتی در برابر به کار بردن ایده امروز برای برخی افکار آشفته کننده بیش از بقیه وجود داشت، دو جمله‌ی هشدار درس قبل را به خود یادآوری کن: هیچ آشفتگی کوچکی وجود ندارد. همه‌ی آن‌ها به یک اندازه آرامش ذهن مرا مختل می‌کنند و: من نمی‌توانم این شکل از آشفتگی را حفظ کنم و بقیه را رها کنم. پس برای اهداف این تمرینات، همه‌ی آن‌ها را یکسان خواهم دید.', 'https://acim-farsi.org/workbook/lesson/6', 'https://acim-farsi.org/audio/workbook/lesson/6.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (7, 'من فقط گذشته را می‌بینم.', 'من فقط گذشته را در این مداد می‌بینم.
من فقط گذشته را در این کفش می‌بینم.
من فقط گذشته را در این دست می‌بینم.
من فقط گذشته را در آن بدن می‌بینم.
من فقط گذشته را در آن چهره می‌بینم.', 'من فقط گذشته را می‌بینم.

باور کردن این ایده مخصوصاً در ابتدا دشوار است. اما این ایده، منطق تمامی ایده‌های پیشین است. به همین دلیل است که هیچ چیزی که تو می‌بینی معنایی ندارد. به همین دلیل است که تو به هر چیزی که می‌بینی تمام معنایی را که برای تو دارد، داده‌ای. به همین دلیل است که تو هیچ چیزی را که می‌بینی، درک نمی‌کنی. به همین دلیل است که افکار تو هیچ معنایی ندارند، و آن‌ها مانند چیزهایی هستند که تو می‌بینی. به همین دلیل است که تو هرگز به آن دلیل که فکر می‌کنی، آشفته نیستی. به همین دلیل است که تو آشفته هستی زیرا چیزی را می‌بینی که آن‌جا نیست.

اعتقادات قدیمی در مورد زمان بسیار دشوار تغییر می‌کنند، زیرا هر آن‌چه تو باور داری، در زمان ریشه دارد، و وابسته به این است که تو این ایده‌های جدید را در مورد آن نیاموزی. اما دقیقاً به همین دلیل تو به ایده‌های جدید در مورد زمان نیاز داری. این ایده جدید، واقعاً آن‌طور که در ابتدا به نظر می‌رسد عجیب نیست.

مثلاً به یک فنجان نگاه کن. آیا تو یک فنجان می‌بینی؟ یا تو صرفاً در حال مرور تجربیات پیشین خود در برداشتن یک فنجان، تشنه بودن، نوشیدن از یک فنجان، احساس کردن لبه یک فنجان بر لبان خود، صبحانه خوردن یا مواردی از این دست هستی؟ آیا واکنش‌های زیباشناسانه تو به این فنجان نیز بر مبنای تجربیات قبلی تو نیست؟ در غیر این صورت آیا می‌توانستی بدانی که اگر این نوع فنجان را به زمین بیندازی می شکند یا خیر؟ تو چه چیز در مورد این فنجان می‌دانی جز آن‌چه در گذشته آموخته‌ای؟ تو اصلا نمی‌دانی که این فنجان چیست، مگر از آموخته‌های گذشته خود. آن‌گاه، آیا واقعاً آن را می‌بینی؟

به پیرامون خود نگاه کن. این موضوع به همین اندازه برای هر چیزی که تو به آن نگاه می‌کنی صحت دارد. این را با به کار بردن بدون تمایز ایده امروز برای هر چیزی که به چشمت می‌خورد، تصدیق کن. برای نمونه: من فقط گذشته را در این مداد می‌بینم. من فقط گذشته را در این کفش می‌بینم. من فقط گذشته را در این دست می‌بینم. من فقط گذشته را در آن بدن می‌بینم. من فقط گذشته را در آن چهره می‌بینم.

با هیچ چیزی به‌طور خاص مشغول نشو، اما به یاد داشته باش که چیزی را نیز به‌طور خاص حذف نکنی. به اختصار به هر سوژه نگاهی بینداز، و سپس به سراغ بعدی برو. سه یا چهار برنامه تمرین، هر یک برای حدود یک دقیقه کافی خواهد بود.', 'https://acim-farsi.org/workbook/lesson/7', 'https://acim-farsi.org/audio/workbook/lesson/7.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (8, 'ذهن من مشغول افکار گذشته است.', 'به نظر می‌رسد در مورد ـــــــ فکر می‌کنم.

به نظر می‌رسد در مورد [نام فرد] فکر می‌کنم، در مورد [نام یک شیئ] فکر می‌کنم، در مورد [نام یک احساس] فکر می‌کنم، همینطور نامیدن افکار را ادامه بده، و در پایان مرحله جستجوی ذهنی، تمرین را با این جمله به پایان برسان: اما ذهن من مشغول افکار گذشته است.', 'ذهن من مشغول افکار گذشته است.

البته دلیل این که چرا تو فقط گذشته را می‌بینی،همین ایده است. هیچ‌کس واقعاً چیزی را نمی‌بیند. هر کسی فقط افکار خود را می‌بیند که به بیرون فرافکن شده است. درگیر بودن ذهن با گذشته علت درک نادرست در مورد زمان است که دید تو از آن رنج می‌برد. ذهن تو نمی‌تواند اکنون را دریابد، که تنها زمان موجود است. بنابراین نمی‌تواند زمان را درک کند، و درواقع نمی‌تواند هیچ چیزی را درک کند.

تنها فکر حقیقی که می‌توان در مورد گذشته داشت این است که گذشته اینجا نیست. از این رو فکر کردن در مورد آن اساساً فکر کردن در مورد اوهام است. . افراد بسیار کمی متوجه شده‌اند که عملاً تجسم گذشته یا پیشگویی آینده چه چیزی را در بر دارد. ذهن در زمانی که این کار را انجام می‌دهد عملاً خالی است، زیرا واقعاً در حال تفکر در مورد چیزی نیست.

قصد از تمرین‌های امروز، آغاز تربیت ذهن تو برای تشخیص این است که چه زمانی واقعاً به هیج وجه در حال تفکر نیست. مادامی که ایده‌های بی‌فکر ذهن تو را درگیر می‌کنند، حقیقت مسدود است. تشخیص دادن این که ذهن تو صرفاً خالی بوده به جای این که باور داشته باشی با افکار واقعی پر شده است، گام نخست برای گشایش مسیر رؤیت است.

تمرینهای امروز باید با چشمان بسته انجام شود. به این دلیل که تو عملاً نمی‌توانی چیزی را ببینی، و به این ترتیب آسان‌تر تشخیص می‌دهی که مهم نیست بتوانی یک فکر را تا چه اندازه واضح تصویر کنی، تو در حال دیدن هیچ چیز نیستی. با کمترین تقلا، ذهن خود را برای همان حدود یک دقیقه جستجو کن، صرفاً متوجه افکاری شو که در آن‌جا پیدا می‌کنی. هر یک از این افکار را با تصویر یا موضوع مرکزی که حاوی آن است نام‌گذاری کن، و به بعدی برو. برنامه تمرین را با گفتن این جمله آغاز کن: به نظر می‌رسد در مورد ـــــــ فکر می‌کنم.

سپس هر یک از افکار خود را به طور اختصاصی نام‌گذاری کن. برای نمونه: به نظر می‌رسد در مورد [نام فرد] فکر می‌کنم، در مورد [نام یک شیئ] فکر می‌کنم، در مورد [نام یک احساس] فکر می‌کنم، همینطور نامیدن افکار را ادامه بده، و در پایان مرحله جستجوی ذهنی، تمرین را با این جمله به پایان برسان: اما ذهن من مشغول افکار گذشته است.

این برنامه تمرین را می‌توان چهار یا پنج مرتبه در روز انجام داد، مگر احساس کنی که موجب آزردگی تو می‌شود. اگر احساس دشواری می‌کنی، سه یا چهار مرتبه کافی است. با این حال شاید کمک کننده باشد اگر آزردگی خود یا هر احساسی را که ایده امروز می‌تواند برانگیزد، در خود مرحله جستجوی ذهنی بگنجانی.', 'https://acim-farsi.org/workbook/lesson/8', 'https://acim-farsi.org/audio/workbook/lesson/8.mp3', 'times_per_day', '[{"kind":"times_per_day","count":4},{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (9, 'من هیچ چیز را آنگونه که اکنون هست، نمی‌بینم.', 'من این ماشین تایپ را آن‌گونه که اکنون هست، نمی‌بینم.
من این تلفن را آن‌گونه که اکنون هست، نمی‌بینم.
من این بازو را آن‌گونه که اکنون هست، نمی‌بینم.

دورتر ………

من آن رخت‌آویز را آن‌گونه که اکنون هست، نمی‌بینم.
من آن در را آن‌گونه که اکنون هست، نمی‌بینم.
من آن چهره را آن‌گونه که اکنون هست، نمی‌بینم.', 'من هیچ چیز را آنگونه که اکنون هست، نمی‌بینم.

این ایده ظاهراً در پی دو ایده پیشین می‌آید. اما اگرچه شاید تو بتوانی عقلاً آن را بپذیری، بعید است که تا حال برای تو هیچ معنایی داشته باشد. البته در این مرحله، درک کردن ضروری نیست. در واقع تشخیص دادن این که تو درک نمی‌کنی، پیش‌نیاز بطلان ایده‌های نادرست تو است. قصد این تمرینها ممارست است، نه درک کردن. تو نیاز نداری در مورد چیزی که درک می‌کنی، ممارست کنی. در حقیقت این ممارست حول هدف ادراک سیر می‌کند، با این فرض که تو در حال حاضر واجد ادراک هستی.

برای ذهن تربیت نشده دشوار است که باور کند آن‌چه به نظر می‌رسد مصور شده است، آن‌جا وجود ندارد. این ایده می‌تواند نسبتاً آزارنده باشد، و ممکن است با مقاومت فعال در هر شکلی روبرو شود. اما این مقاومت مانع ازبه کار بردن آن نمی‌شود. چیزی بیش از آن برای انجام این تمرینها یا تمرینهای دیگر مورد نیاز نیست. هر گام کوچک مقدار کمی از تاریکی را کنار می‌زند، و ادراک نهایتاً تمامی گوشه‌های ذهن را که از زباله‌های تاریک کننده پاک شده است، روشن خواهد کرد.

انجام سه یا چهار دوره تمرین برای امروز کافی است. شامل نگاه کردن به اطراف و تمرین ایده روز با هرچه که می‌بینی، با به یاد داشتن عدم تمایز در به کار بردن این ایده، و قاعده اساسی حذف نکردن هیچ چیزی. برای نمونه: من این ماشین تایپ را آن‌گونه که اکنون هست، نمی‌بینم. من این تلفن را آن‌گونه که اکنون هست، نمی‌بینم. من این بازو را آن‌گونه که اکنون هست، نمی‌بینم.

با چیزهایی که به تو نزدیک‌تر هستند آغاز کن، و سپس محدوده را گسترش بده: من آن رخت‌آویز را آن‌گونه که اکنون هست، نمی‌بینم. من آن در را آن‌گونه که اکنون هست، نمی‌بینم. من آن چهره را آن‌گونه که اکنون هست، نمی‌بینم.

باز هم تأکید می‌شود در عین حال که نباید برای گنجاندن همه چیز در تمرین تلاش کرد، باید از حذف اختصاصی نیز پرهیز نمود. مطمئن شو که در انجام این تمایز با خودت صادق هستی. ممکن است وسوسه شوی که این تمایل به فرق گذاشتن را پنهان کنی.', 'https://acim-farsi.org/workbook/lesson/9', 'https://acim-farsi.org/audio/workbook/lesson/9.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (10, 'افکار من هیچ معنایی ندارند.', 'افکار من هیچ معنایی ندارند.

سپس اضافه کن:

این ایده کمک خواهد کرد که من از تمام آن‌چه اکنون باور دارم، رها شوم.

فکر من در مورد ـــــــ هیچ معنایی ندارد.
فکر من در مورد ـــــــ هیچ معنایی ندارد.', 'افکار من هیچ معنایی ندارند.

این ایده برای تمامی افکاری که از آن آگاه هستی، یا در طول برنامه‌های تمرین خود از آن‌ها آگاه می‌شوی، کاربرد دارد. ایده امروز برای همه این افکار قابل به کار بردن است زیرا آن‌ها افکار واقعی تو نیستند. ما قبلاً این را تشخیص داده‌ایم، و باز هم این کار را خواهیم کرد. تو هنوز هیچ پایه‌ای برای مقایسه نداری. زمانی که این پایه را داشته باشی، هیچ شکی نخواهی داشت که آن‌چه زمانی می‌پنداشتی افکار تو است، هیچ معنایی نداشت.

این دومین بار است که ما از چنین نوع ایده‌ای استفاده می‌کنیم. شکل این کار فقط اندکی متفاوت است. این بار این ایده با «افکار من» به جای «این افکار» مطرح می‌شود بدون این که ارتباط واضحی با چیزهای پیرامون تو ایجاد گردد. در این‌جا تأکید بر واقعیت نداشتن آن چیزی است که تو می‌پنداری که می‌اندیشی.

این جنبه از فرآیند تصحیح با این ایده آغاز شد که افکاری که تو به آن‌ها آگاه هستی بی‌معنا هستند، و بیشتر بیرونی هستند تا درونی؛ و سپس تأکید شد که پایه آن‌ها بیشتر در گذشته است تا در حال. . اکنون این نکته را برجسته می‌کنیم که حضور این افکار به این معنا است که تو در حال فکر کردن نیستی. این صرفاً شیوه‌ای دیگر برای تکرار جمله پیشین ما است که ذهن تو در واقع خالی است. تشخیص این نکته، تشخیص هیچ است زمانی که فکر می‌کنی آن را می‌بینی. به همین دلیل، این تشخیص پیش نیاز رؤیت است.

برای این تمرینها چشمان خود را بببند، و برنامه تمرین را با تکرار کردن ایده امروز به آرامی برای خودت آغاز کن. سپس اضافه کن: این ایده کمک خواهد کرد که من از تمام آن‌چه اکنون باور دارم، رها شوم. تمرینهامانند تمرینهای پیشین شامل این می‌شوند که ذهن خود را برای همه افکاری که در دسترس هستند جستجو کنی، بدون انتخاب یا قضاوت. سعی کن از دسته بندی به هر شکلی بپرهیزی. در واقع، اگر به تو کمک می‌کند، می‌توانی تصور کنی در حال تماشای یک جریان جمعی از چیزهایی هستی که به طرز عجیب و غریبی با هم جور شده‌اند، جریانی که برای تو معنای شخصی اندکی دارد یا هیچ معنایی ندارد. همین که هر یک از آن چیز‌ها به ذهنت رسید، بگو: فکر من در مورد ـــــــ هیچ معنایی ندارد. فکر من در مورد ـــــــ هیچ معنایی ندارد.

فکر امروز می‌تواند آشکارا برای هر فکری که در هر زمان موجب پریشانی تو می‌شود به کار برده شود. بعلاوه، پنج برنامه تمرینی توصیه می‌شود، هر یک شامل جستجوی ذهن برای مدتی حدود یک دقیقه یا کمتر. توصیه نمی‌شود که این زمان را ‌طولانی‌تر کنی، و این مدت باید در صورت احساس ناراحتی به نیم دقیقه یا کمتر کاهش یابد. اما به یاد داشته باش که این ایده را به آرامی پیش از به کار بردن آن به طور اختصاصی، برای خودت تکرار کنی، و همچنین اضافه کن: این ایده کمک خواهد کرد که من از تمام آن‌چه اکنون باور دارم، رها شوم.', 'https://acim-farsi.org/workbook/lesson/10', 'https://acim-farsi.org/audio/workbook/lesson/10.mp3', 'times_per_day', '[{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (11, 'افکار بی‌معنای من یک دنیای بی‌معنا را به من نشان می‌دهند.', 'افکار بی‌معنای من یک دنیای بی‌معنا را به من نشان می‌دهند.', 'افکار بی‌معنای من یک دنیای بی‌معنا را به من نشان می‌دهند.

این نخستین ایده ما است که به یک مرحله اصلی در فرآیند تصحیح ربط دارد؛ وارونه شدن تفکر ما در مورد دنیا. به نظر می‌رسد که انگار جهان تعیین می‌کند تو چه چیزی را درک کنی. ایده امروز این مفهوم را معرفی می‌کند که افکار تو، دنیایی را که می‌بینی تعیین می‌کنند. در حقیقت خوشحال باش که این ایده را در شکل ابتدایی آن تمرین می‌کنی، زیرا در این ایده است که رهایی تو تضمین می‌شود. کلید بخشایش در این ایده است.

برنامه‌های تمرین ایده امروز را باید به ‌نحوی با برنامه‌های قبلی متفاوت محسوب کرد. با چشمان بسته آغاز کن، و این ایده را به آرامی برای خودت تکرار کن. سپس چشمان خود را باز کن و به اطراف، نزدیک و دور، بالا و پایین-هر جا نگاه کن. در طول حدود یک دقیقه تمرین با این ایده، صرفاً آن را برای خودت تکرار کن، با اطمینان از این که این کار را بدون شتاب انجام می‌دهی، بدون هیچ احساسی از فوریت یا تلاش.

برای سودمندی هرچه بیشتر این تمرین‌ها، چشم‌ها باید از یک چیز به چیز دیگر نسبتاً سریع حرکت کند، زیرا نباید بر چیزی به طور خاص درنگ شود. اما از کلمه‌ها باید به شیوه‌ای بدون شتاب و حتی با آسودگی استفاده کرد. آشنایی با این ایده باید خصوصاً تا حد ممکن به صورتی غیرجدی تمرین شود. این آشنایی حاوی شالوده صلح، آرمش و رهایی از نگرانی است که تلاش می‌کنیم به دست بیاوریم. در پایان هر تمرین، چشمان خود را ببند و ایده امروز را یک بار دیگر به آرامی برای خودت تکرار کن.

امروز احتمالاً سه برنامه تمرین کافی خواهد بود. اما اگر بدون احساس ناآرامی یا با اندکی ناآرامی تمایل به تمرین بیشتری داشتی، تا پنج بار در روز می‌توانی تمرین کنی. بیش از این توصیه نمی‌شود.', 'https://acim-farsi.org/workbook/lesson/11', 'https://acim-farsi.org/audio/workbook/lesson/11.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (12, 'من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم.', 'من فکر می‌کنم که یک دنیای ترسناک، یک دنیای خطرناک می‌بینم، یک دنیای متخاصم می‌بینم، یک دنیای غمناک می‌بینم، یک دنیای پلید می‌بینم، یک دنیای دیوانه می‌بینم و غیره، با استفاده از هر کلمه توصیفی که به ذهنت می‌آید.

در پایان برنامه تمرین، اضافه کن:

اما من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم.', 'من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم.

اهمیت ایده امروز در این واقعیت نهفته است که شامل تصحیحی برای یک تحریف ادراکی عمده می‌شود. تو فکر می‌کنی که آن‌چه تو را آشفته می‌سازد یک دنیای ترسناک، یا یک دنیای غمگین، یا یک دنیای خشن، یا یک دنیای دیوانه است. . تمامی این خواص توسط تو به آن داده شده. دنیا به خودی خود معنایی ندارد.

این تمرین‌ها با چشمان باز انجام می‌شوند. به پیرامون خود نگاه کن، این بار نسبتاً آرام. سعی کن خود را آنچنان تنظیم کنی که عبور کردن آرام نگاه تو از چیزی به چیز دیگر در فواصل زمانی نسبتاً ثابتی انجام گیرد. اجازه نده زمان عبور نگاه تو مشخصاً طولانی‌تر یا کوتاه‌تر شود، بلکه در عوض تلاش کن یک زمان معین ثابت را در طول تمرین حفظ کنی. آن‌چه می‌بینی مهم نیست. تو این را به خود با دادن توجه مساوی و زمان مساوی به هر چه که نگاهت بر آن می‌ماند، آموزش می‌دهی. این نخستین گام است برای یادگیریِ دادن ارزش مساوی به همه آن‌ها.

همچنان که به پیرامونت نگاه می‌کنی با خود بگو: من فکر می‌کنم که یک دنیای ترسناک، یک دنیای خطرناک می‌بینم، یک دنیای متخاصم می‌بینم، یک دنیای غمناک می‌بینم، یک دنیای پلید می‌بینم، یک دنیای دیوانه می‌بینم و غیره، با استفاده از هر کلمه توصیفی که به ذهنت می‌آید. اگر به نظر می‌رسد کلماتی که به ذهنت می‌آید بیشتر مثبت است تا منفی، آن‌ها را نیز وارد تمرین کن. برای نمونه، ممکن است تو به «یک دنیای خوب» یا «یک دنیای خشنود کننده» فکر کنی. اگر چنین کلماتی به ذهنت می‌رسد، از این کلمات نیز به همراه بقیه استفاده کن. ممکن است اکنون متوجه نشوی که چرا این صفت‌های «مطلوب» به این تمرینات تعلق دارد، اما به یاد داشته باش که یک «دنیای خوب» اشاره دارد به یک دنیای «بد»، و یک «دنیای خشنود کننده» اشاره می‌کند به یک دنیای «ناخشنود کننده». تمام کلماتی که به ذهن تو خطور می‌کنند سوژه‌های مناسب برای تمرینات امروز هستند. کیفیت ظاهری آن‌ها اهمیتی ندارد.

مطمئن شو که فواصل زمانی را بین به کار بردن ایده امروز برای آن‌چه فکر می‌کنی خوشایند است و آن‌چه فکر می‌کنی ناخوشایند است تغییر نمی‌دهی. برای اهداف این تمرینها، هیچ تفاوتی بین آن‌ها وجود ندارد. در پایان برنامه تمرین، اضافه کن: اما من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم.

آن‌چه بی‌معنا است، نه خوب است و نه بد. پس چرا یک دنیای بی‌معنا باید تو را آشفته کند؟ اگر تو می‌توانستی بی‌معنا بودن دنیا را بپذیری و اجازه می‌دادی که برای تو حقیقت بر روی آن نوشته شود، این کار به طرز وصف ناپذیری تو را خوشحال می‌کرد. اما چون دنیا بی‌معنا است، تو سوق پیدا می‌کنی چیزی را بر روی آن بنویسی که مجبورشود آن‌گونه باشد. این آن چیزی است که تو در آن می بینی. این همان چیزی است که در حقیقت بی‌معنا است. کلام خداوند در زیر کلمات تو نوشته شده است. در حال حاضر حقیقت تو را آشفته می‌کند، اما زمانی که کلمات تو پاک شده باشند، کلمات او را خواهی دید. هدف نهایی این تمرینها همین است.

سه یا چهار برنامه تمرین برای کار با ایده امروز کافی است. برنامه‌های تمرین نباید بیش از یک دقیقه طول بکشند. ممکن است حتی همین زمان نیز برای تو طولانی باشد. هر زمان که تنش احساس کردی، تمرین را پایان بده.', 'https://acim-farsi.org/workbook/lesson/12', 'https://acim-farsi.org/audio/workbook/lesson/12.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (13, 'یک دنیای بی‌معنا آبستن ترس است.', 'یک دنیای بی‌معنا آبستن ترس است.

من در حال نگاه کردن به یک دنیای بی‌معنا هستم.

این جمله را برای خودت تکرار کن همچنان که به پیرامون نگاه می‌کنی. سپس چشمان خود را ببند و با این جمله ختم کن:

یک دنیای بی‌معنا آبستن ترس است زیرا من فکر می‌کنم در رقابت با خداوند هستم.', 'یک دنیای بی‌معنا آبستن ترس است.

ایده امروز در واقع شکل دیگری از ایده پیشین است، جز این که بر حسب احساساتی که برانگیخته می‌شود، اختصاصی‌تر است. عملاً، یک دنیای بی‌معنا ناممکن است. هیچ چیزی بدون معنا وجود ندارد. اما این مانع نمی‌شود که تو فکر نکنی که یک چیز بی‌معنا را درک می‌کنی. برعکس، تو مخصوصاً احتمال دارد فکر کنی که آن را درک می‌کنی.

تشخیص بی‌معنایی در تمامی جداشدگان اضطراب شدید را برانگیخته می‌کند. این نمایان‌گر موقعیت «رقابت» بین خداوند* و نفس با یکدیگر در این زمینه است که معنای کدام‌یک باید بر آن فضای خالی که بی‌معنایی فراهم می‌کند، نوشته شود. نفس با سرآسیمگی هجوم می‌آورد تا ایده‌های خود را در آن‌جا ثبت کند، هراسان از این که در غیر این صورت پوچی می‌تواند برای نشان دادن سستی و غیرواقعی بودن آن به کار گرفته شود. و تنها در همین یک مورد حق با اوست.

بنابراین اساسی است که تو بیاموزی بی‌معنا را تشخیص دهی، و آن را بدون ترس بپذیری. اگر هراسان باشی، مطمئناً خواصی را به دنیا اعطا می‌کنی که فاقد آن‌ها است، و آن را با تصویرهایی که وجود ندارند شلوغ می‌کنی. برای نفس، اوهام وسیلههای امنیت هستند، همان‌گونه که باید برای تو باشند اگر خود را با نفس یکی کنی.

تمرین‌های امروز را باید حدوداً سه یا چهار بار در روز برای مدتی حداکثر حدود یک دقیقه در هر بار تمرین انجام داد، و به شیوه‌ای نسبتاً متفاوت با تمرین‌های پیشین اجرا می‌شوند. با چشمان بسته، ایده امروز را برای خودت تکرار کن. سپس چشمان خود را گشوده و به پیرامونت نگاه کن در حالی که به آرامی می‌گویی: من در حال نگاه کردن به یک دنیای بی‌معنا هستم. این جمله را برای خودت تکرار کن همچنان که به پیرامون نگاه می‌کنی. سپس چشمان خود را ببند و با این جمله ختم کن: یک دنیای بی‌معنا آبستن ترس است زیرا من فکر می‌کنم در رقابت با خداوند هستم.

ممکن است برایت چنین پیش بیاید که احساس کنی پرهیز از مقاومت در شکل‌های مختلف آن در برابر این جمله پایانی دشوار است. این مقاومت هر شکلی داشته باشد، به خودت یادآور شو که تو واقعاً به دلیل «انتقام» یک «دشمن» از این فکر می‌ترسی. از تو انتظار نمی‌رود که در حال حاضر این جمله را باور کنی، و احتمالاً آن را به عنوان یک ایده نامعقول از ذهن بیرون خواهی راند. اما به دقت به هر نشانه‌ای از ترس آشکار یا پنهان که می‌تواند برانگیزد توجه کن.

این نخستین تلاش ما برای بیان یک رابطه علت و معلول واضح از نوعی است که تو در تشخیص آن بسیار بی‌تجربه هستی. با جمله پایانی مشغولیت ذهنی پیدا نکن، و سعی کن حتی به آن جز در طول برنامه‌های تمرینی خود فکر نکنی. در حال حاضر همین کفایت خواهد کرد.', 'https://acim-farsi.org/workbook/lesson/13', 'https://acim-farsi.org/audio/workbook/lesson/13.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (14, 'خداوند* یک دنیای بی‌معنا را نیافرید.', 'خداوند* آن جنگ را خلق نکرد، پس واقعی نیست.
خداوند* آن سقوط هواپیما را خلق نکرد، پس واقعی نیست.
خداوند* آن فاجعه طبیعی [مشخص کنید] را خلق نکرد، پس واقعی نیست.

در تشخیص این واقعیت، هر برنامه تمرین را با تکرار کردن ایده امروز خاتمه بده:

خداوند* یک دنیای بی‌معنا را نیافرید.', 'خداوند* یک دنیای بی‌معنا را نیافرید.

ایدهٔ امروز البته دلیل ناممکن بودن یک دنیای بی‌معنا است. آن‌چه خداوند* نیافرید وجود ندارد. و هرچیزی که وجود دارد، آن‌گونه که او* آن را آفرید وجود دارد. دنیایی که تو می‌بینی هیچ ربطی به واقعیت ندارد. آن ساخته خود تو است، و وجود ندارد.

تمرینهای امروز را باید با چشمان بسته در تمام طول تمرین انجام داد. زمان جستجوی ذهنی باید کوتاه باشد، حداکثر یک دقیقه. بیش از سه برنامه تمرین با ایده امروز نداشته باش مگر برایت راحت باشند. اگر چنین باشد، به این دلیل خواهد بود که واقعاًدرک می‌کنی این تمرینها برای چه هستند.

ایده امروز گامی دیگر است در فراگیری رها کردن افکاری که تو بر دنیا نوشته‌ای، و دیدن کلام* خداوند* در جای آن‌ها. گام‌های اولیه در این تعویض، که آن را می‌توان حقیقتاً رستگاری خواند، ممکن است نسبتاً دشوار و حتی نسبتاً دردناک باشد. برخی از آن‌ها تو را مستقیماً به درون ترس رهنمون می‌شوند. تو در آن‌جا ترک نخواهی شد. تو بسیار فراتر از آن خواهی رفت. مسیر ما به سمت امنیت کامل و صلح کامل است.

با چشمان بسته، به همهٔ وحشت‌های دنیا که به ذهنت می‌رسد فکر کن. هر یک را آنگونه که به نظرت می‌رسد نام ببر، و سپس واقعی بودن آن را رد کن. خداوند* آن را خلق نکرد، پس واقعی نیست. برای نمونه بگو: خداوند* آن جنگ را خلق نکرد، پس واقعی نیست. خداوند* آن سقوط هواپیما را خلق نکرد، پس واقعی نیست. خداوند* آن فاجعه طبیعی [مشخص کنید] را خلق نکرد، پس واقعی نیست.

سوژه‌های مناسب برای به کار بردن ایده امروز همچنین شامل هر چیزی می‌شود که تو می‌ترسی که برایت پیش بیاید، یا برای هر کسی که تو نگران او هستی. در هر مورد، «فاجعه» را نسبتاً به صورت اختصاصی نام ببر. از کلمات عمومی استفاده نکن. مثلاً نگو «خداوند* بیماری را خلق نکرد»، بلکه بگو «خداوند* سرطان را خلق نکرد»، یا حمله قلبی، یا هر چیزی که ممکن است در تو ترس برانگیزد.

تو در حال نگاه کردن به فهرست شخصی وحشت‌های خود هستی. این چیزها بخشی از دنیایی هستند که تو می‌بینی. برخی از آن‌ها اوهام مشترک هستند، و بقیه بخشی از جهنم شخصی تو هستند. اهمیتی ندارد. آن‌چه خداوند* خلق نکرد تنها می‌تواند در ذهن خود تو جدا از ذهن* او* باشد. بنابراین، هیچ معنایی ندارد. در تشخیص این واقعیت، هر برنامه تمرین را با تکرار کردن ایده امروز خاتمه بده: خداوند* یک دنیای بی‌معنا را نیافرید.

البته ایده امروز را می‌توانی علاوه بر دوره‌های تمرین، برای هر چیزی که در طول روز آزارت می‌دهد به کار ببری. در به کار بردن آن بسیار اختصاصی عمل کن. بگو: خداوند* یک دنیای بی‌معنا را نیافرید. او [شرایطی را مشخص کن که تو را آزار می‌دهد] را خلق نکرد، پس واقعی نیست.', 'https://acim-farsi.org/workbook/lesson/14', 'https://acim-farsi.org/audio/workbook/lesson/14.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (15, 'افکار من تصویرهایی هستند که من ساخته‌ام.', 'افکار من تصویرهایی هستند که من ساخته‌ام.

این ـــــــ تصویری است که من ساخته‌ام.
آن ـــــــ تصویری است که من ساخته‌ام.', 'افکار من تصویرهایی هستند که من ساخته‌ام.

آن افکار که تو می پنداری که می اندیشی، به صورت تصاویری ظاهر می‌شوند، از این رو تو تشخیص نمی‌دهی که هیچ چیز نیستند. می پنداری که آن‌ها را می اندیشی، پس فکر می‌کنی که آن‌ها را می‌بینی. «دیدن» تو این‌گونه ساخته شده است. این عملکردی است که تو به چشمان بدن خود داده‌ای. این دیدن نیست. این ساختن تصویر است. ساختنی که جای دیدن را می‌گیرد، و بینایی را با اوهام جایگزین می‌کند.

این ایده‌ی مقدماتی در مورد فرآیند ساختن تصویر که تو دیدن می‌خوانی، برای تو معنای چندانی نخواهد داشت. زمانی آغاز به درک آن خواهی کرد که لبه‌های کوچک نور را پیرامون همان اشیاء آشنا که اکنون می‌بینی، دیده باشی. آن آغاز بینایی واقعی است. می‌توانی مطمئن باشی که بینایی واقعی پس از این رویداد به سرعت پیش خواهد آمد.

همچنان که پیش می‌رویم، تو ممکن است به دفعات «رخدادهای نور» داشته باشی. آن‌ها ممکن است شکل‌های بسیار متنوعی به خود بگیرند، که برخی نسبتاً غیرمنتظره هستند. از آن‌ها نترس. آن‌ها نشانه‌های این هستند که تو سرانجام در حال گشودن چشمان خود هستی. آن‌ها ماندگار نیستند، زیرا صرفاً نمادی از ادراک درست هستند، و به معرفت ربطی ندارند. این تمرین‌ها معرفت را بر تو آشکار نمی‌کنند. اما مسیر آن را آماده می‌کنند.

در تمرین ایده‌ی امروز، ابتدا آن را برای خودت تکرار کن، و سپس آن را با هرچه پیرامون خود می‌بینی تمرین کن، با استفاده از نام آن و درنگ نگاه خود بر روی آن در حالی که می‌گویی: این ـــــــ تصویری است که من ساخته‌ام. آن ـــــــ تصویری است که من ساخته‌ام. لزومی ندارد که تعداد زیادی از سوژه‌های خاص را برای به کار بردن ایده‌ی امروز در تمرین خود بگنجانی. اما ضروری است که به نگاه کردن به هر سوژه در حال تکرار کردن این ایده برای خود ادامه دهی. ایده‌ی امروز را باید هر بار نسبتاً آرام تکرار کنی.

اگرچه تو ظاهراً قادر نیستی در طول این مدت حدود یک دقیقه که توصیه می شود ایده‌ی تمرین را برای چیزهای خیلی زیادی به کار ببری، بهتر است انتخاب سوژه‌ها تا حد ممکن تصادفی باشد. اگر احساس ناراحتی به تو دست دهد، کمتر از یک دقیقه برای برنامه تمرین کفایت می‌کند. بیشتر از سه برنامه‌ی تمرین برای ایده‌ی امروز نداشته باش مگر کاملاً با آن احساس راحتی کنی، و بیشتر از چهار نوبت انجام نده. با این حال خود ایده می‌تواند در طول روز هر چند بار که نیاز باشد به کار رود.', 'https://acim-farsi.org/workbook/lesson/15', 'https://acim-farsi.org/audio/workbook/lesson/15.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (16, 'من هیچ فکر خنثی‌ای ندارم.', 'من هیچ فکر خنثی‌ای ندارم.

این فکر در مورد ـــــــ یک فکر خنثی نیست.
آن فکر در مورد ـــــــ یک فکر خنثی نیست.', 'من هیچ فکر خنثی‌ای ندارم.

ایده‌ی امروز یک گام آغازین برای بطلان این باور است که افکار تو تأثیری ندارند. هر چیز که تو می‌بینی نتیجه‌ی افکار تو است. هیچ استثنائی برای این واقعیت وجود ندارد. افکار، بزرگ یا کوچک، قوی یا ضعیف نیستند. آن‌ها صرفاً درست یا نادرست هستند. افکاری که درست هستند مشابه خود را خلق می‌کنند. افکار نادرست نیز مشابه خود را می‌سازند.

هیچ مفهومی به اندازه‌ی مفهوم «افکار بیهوده» با خودش در تضاد نیست. چیزی که ادراک از کل یک دنیا را می‌پرورد، به سختی می‌توان بیهوده‌اش خواند. هر فکری که تو داری، به حقیقت یا به وهم کمک می‌کند؛ یا حقیقت را گسترش می‌دهد یا اوهام را تکثیر می‌کند. تو در واقع می‌توانی «هیچ» را تکثیر کنی، اما با این کار آن را گسترش نخواهی داد.

در کنار تشخیص این که افکار هرگز خنثی نیستند، رستگاری مستلزم این است که تو همچنین تشخیص دهی که هر فکری که داری، موجب صلح یا جنگ می‌شود، موجب عشق یا ترس. یک نتیجه‌ی خنثی ناممکن است زیرا یک فکر خنثی ناممکن است. چنین وسوسه‌ای وجود دارد که افکار ترسناک را غیرمهم به حساب بیاوریم، ناچیز و فاقد این ارزش که خودمان را برای آن‌ها به زحمت بیندازیم. اساسی است که تشخیص دهی همه ی آنها به یک اندازه مخرب، اما به یک اندازه غیرواقعی هستند. ما این ایده را به اشکال متعدد پیش از این که تو واقعاً درکش کنی، تمرین خواهیم کرد.

برای به کار بردن ایده‌ی امروز، ذهن خود را برای حدود یک دقیقه با چشمان بسته جستجو کن، و فعالانه بخواه که از هیچ فکر «کوچکی» که می‌تواند خود از این جستجو دور نگه دارد، چشم‌پوشی نکنی. این کار تا زمانی که تو با آن خو بگیری نسبتاً دشوار است. تو متوجه خواهی شد که هنوز قایل نشدن به تمایزهای مصنوعی برایت دشوار است. هر فکری که برایت پیش می‌آید، صرفنظر از کیفیت‌هایی که تو به آن نسبت می‌دهی، یک سوژه‌ی مناسب برای تمرین با ایده‌ی امروز است.

در برنامه‌های تمرین، ابتدا ایده‌ی امروز را برای خود تکرار کن و سپس با خطور کردن هر فکری به ذهنت، آن را در آگاهی خود نگه دار در حالی که به خودت می‌گویی: این فکر در مورد ـــــــ یک فکر خنثی نیست. آن فکر در مورد ـــــــ یک فکر خنثی نیست. طبق معمول، از ایده‌ی امروز در هر زمان که به یک فکر خاص ناآرام کننده آگاه می‌شوی، استفاده کن. شکل زیر برای این منظور پیشنهاد می‌شود: این فکر در مورد ـــــــ یک فکر خنثی نیست، زیرا من هیچ فکر خنثی‌ای ندارم.

اگر برایت نسبتاً راحت باشد، چهار یا پنج برنامه‌ی تمرین توصیه می‌شود. اگر احساس فشار کردی، سه برنامه کفایت می‌کند. در صورت احساس ناراحتی باید مدت زمان هر برنامه تمرین را نیز کاهش داد.', 'https://acim-farsi.org/workbook/lesson/16', 'https://acim-farsi.org/audio/workbook/lesson/16.mp3', 'times_per_day', '[{"kind":"times_per_day","count":4},{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (17, 'من هیچ چیز خنثی‌ای نمی‌بینم.', 'من هیچ چیز خنثی‌ای نمی‌بینم، زیرا هیچ فکر خنثی‌ای ندارم.

من یک ـــــــ خنثی نمی‌بینم، زیرا افکارم در مورد ـــــــ خنثی نیستند.

برای نمونه، من یک دیوار خنثی نمی‌بینم، زیرا افکارم در مورد دیوارها خنثی نیستند.

من یک بدن خنثی نمی‌بینم، زیرا افکارم در مورد بدن‌ها خنثی نیستند.', 'من هیچ چیز خنثی‌ای نمی‌بینم.

این ایده گامی دیگر است در راستای شناخت علت و معلول، آن‌گونه که واقعاً در دنیا عمل می‌کند. تو هیچ چیز خنثی‌ای نمی‌بینی، زیرا هیچ فکر خنثی‌ای نداری. همیشه این فکر است که در آغاز می‌آید، با وجود وسوسه برای باور این که برعکس است. این دنیا با این شیوه نمی‌اندیشد، اما تو باید بیاموزی که به همین شیوه بیندیشی. اگر چنین نبود، ادراک هیچ علتی نمی‌داشت، و خودش علت واقعیت می‌بود. با توجه به ماهیت بشدت متغیر ادراک، این بسیار بعید است.

در تمرین با ایده‌ی امروز، با چشمان باز به خودت بگو: من هیچ چیز خنثی‌ای نمی‌بینم، زیرا هیچ فکر خنثی‌ای ندارم. سپس به پیرامون خود نگاه کن، و نگاه خود را بر هر چیزی که متوجه آن می‌شوی به اندازه‌ی کافی طولانی نگه دار تا بگویی: من یک ـــــــ خنثی نمی‌بینم، زیرا افکارم در مورد ـــــــ خنثی نیستند. برای نمونه، می‌توانی بگویی: من یک دیوار خنثی نمی‌بینم، زیرا افکارم در مورد دیوارها خنثی نیستند. من یک بدن خنثی نمی‌بینم، زیرا افکارم در مورد بدن‌ها خنثی نیستند.

طبق معمول، اساسی است که هیچ تمایزی بین آن‌چه باور داری جاندار یا بیجان؛ خوشایند یا ناخوشایند است قایل نشوی. صرفنظر از هر آن‌چه ممکن است باور داشته باشی، تو هیچ چیز را که واقعاً زنده یا واقعاً لذتبخش باشد نمی‌بینی. زیرا تو هنوز نسبت به هر فکری که واقعاً درست است، و بنابراین نسبت به هر فکری که واقعاً شاد است، ناآگاه هستی.

سه یا چهار برنامه‌ی اختصاصی تمرین توصیه می‌شود، و حداقل سه برنامه برای کسب بیشترین سود از تمرین مورد نیاز است، حتی اگر مقاومت احساس کنی. اما اگر چنین احساسی داشتی، طول برنامه‌های تمرین را می‌توانی به کمتر از حدود یک دقیقه کاهش دهی.', 'https://acim-farsi.org/workbook/lesson/17', 'https://acim-farsi.org/audio/workbook/lesson/17.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (18, 'من در تجربه کردن تأثیراتِ دیدنِ خودم، تنها نیستم.', 'من در تجربه کردن تأثیراتِ چگونه دیدن ـــــــ ، تنها نیستم.

من در تجربه کردن تأثیراتِ دیدنِ خودم، تنها نیستم.', 'من در تجربه کردن تأثیراتِ دیدنِ خودم، تنها نیستم.

ایده‌ی امروز گامی دیگر است در فراگیری این که افکار پرورش دهنده‌ی آن‌چه تو می‌بینی، هرگز خنثی یا غیرمهم نیستند. این ایده همچنین بر ایده‌ی پیوند داشتن ذهن‌ها تأکید می‌کند، که بعداً به آن اهمیت بیشتری داده خواهد شد.

ایده‌ی امروز بیشتر به چگونگی دیدن تو می‌پردازد تا آن‌چه می‌بینی. بنابراین تمرین‌های امروز بر این جنبه از ادراک تو تأکید دارند. توصیه می‌شود سه یا چهار برنامه‌ی تمرین داشته باشی که به شکل زیر اجرا شوند:

به پیرامون خود نگاه کن در حالی که سوژه‌های تمرین با ایده امروز را تا حد ممکن تصادفی انتخاب می‌کنی، و نگاه خود را روی هریک برای زمانی به اندازه کافی طولانی نگه دار تا بگویی: من در تجربه کردن تأثیراتِ چگونه دیدن ـــــــ ، تنها نیستم. هر برنامه‌ی تمرین را با تکرار جمله‌ی عمومی‌تر خاتمه بده: من در تجربه کردن تأثیراتِ دیدنِ خودم، تنها نیستم. حدود یک دقیقه، یا حتی کمتر، برای هر برنامه تمرین کفایت می‌کند.', 'https://acim-farsi.org/workbook/lesson/18', 'https://acim-farsi.org/audio/workbook/lesson/18.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (19, 'من در تجربه کردن تأثیراتِ اندیشه‌های خودم، تنها نیستم.', 'من در تجربه کردن تأثیرات این اندیشه در مورد ـــــــ تنها نیستم.', 'من در تجربه کردن تأثیراتِ اندیشه‌های خودم، تنها نیستم.

ایده‌ی امروز آشکارا دلیل این است که چرا دیدن تو فقط بر خودت تأثیر نمی‌گذارد. متوجه خواهی شد که گاه ایده‌های مربوط به اندیشه پیش از ایده‌های مربوط به ادراک می‌آیند، اگر چه گاهی این ترتیب برعکس می شود. دلیل این است که این نظم اهمیت ندارد. اندیشه و نتایج آن واقعاً همزمان هستند، زیرا علت و معلول هرگز از هم جدا نیستند.

امروز دوباره در حال تأکید براین واقعیت هستیم که ذهن‌ها به هم پیوسته هستند. اغلب این ایده در ابتدا چندان خوشایند نیست، زیرا به نظر می‌رسد با خود یک احساس مسئولیت عظیم را حمل می‌کند، و ممکن است حتی یک «تجاوز به حریم خصوصی» محسوب گردد. اما این یک واقعیت است که هیچ فکر خصوصی وجود ندارد. با وجود مقاومت اولیه‌ی خود در برابر این ایده، تو درک خواهی کرد که اگر رستگاری اساساً ممکن است، این ایده باید درست باشد. و رستگاری باید ممکن باشد زیرا این ارادۀ* خداوند* است.

جستجوی ذهنی حدود یک دقیقه که تمرینهای امروز مستلزم آن است، باید با چشمان بسته انجام گیرد. ابتدا باید ایده‌ی امروز تکرار شود، و سپس باید ذهن به دقت برای افکاری که در آن زمان در آن حضور دارند، جستجو شود. متوجه هر فکری که شدی، آن را برحسب فرد یا موضوعِ محوری که دارد نامگذاری کن، و در حالی که آن را در ذهن نگه می‌داری، بگو: من در تجربه کردن تأثیرات این اندیشه در مورد ـــــــ تنها نیستم.

تو تا حال با ضرورت این که باید در انتخاب سوژه‌ها برای برنامه‌های تمرین تا حد ممکن بدون تمایز باقی بمانی، نسبتاً آشنا شده‌ای و دیگر این را هر روز تکرار نمی‌کنیم، اگرچه گاهی به عنوان یادآوری مطرح خواهد شد. اما از یاد نبر که انتخاب تصادفی سوژه‌ها برای همه‌ی برنامه‌های تمرین همواره اساسی باقی می‌ماند. فقدان ترتیب در این پیوستگی نهایتاً تشخیص فقدان ترتیب در معجزات را برای تو معنادار خواهد کرد.

علاوه بر کاربرد «در صورت لزوم» ایده‌ی امروز، حداقل سه برنامه‌ی تمرین مورد نیاز است و اگر ضروری باشد، کوتاه کردن طول زمان توصیه می‌شود. تلاش نکن که بیش از چهار برنامه‌ی تمرین داشته باشی.', 'https://acim-farsi.org/workbook/lesson/19', 'https://acim-farsi.org/audio/workbook/lesson/19.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3},{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (20, 'من مصمم به دیدن هستم.', 'من مصمم به دیدن هستم.', 'من مصمم به دیدن هستم.

ما تا حال در مورد برنامه‌های تمرین خود خیلی معمولی و بی‌تکلف بوده‌ایم. عملاً هیچ تلاشی برای تنظیم زمان انجام تمرینات نداشتیم، حداقلِ تلاش برای تمرینات لازم بود، و حتی همکاری وعلاقه‌مندی فعال درخواست نشد. این رویکرد عمدی بوده و بسیار با دقت طراحی شده است. ما نگرش مبنی بر اهمیت حیاتی وارونه کردن تفکر تو را حفظ کرده‌ایم. رستگاری دنیا وابسته به این نگرش است. اما اگر تو احساس کنی مجبور هستی، یا اگر تسلیم رنجش و مخالفت شوی، این ارتباط را نخواهی دید.

درس امروز نخستین تلاش ما برای آشنایی با ساختار است. این را به اشتباه به عنوان تلاشی برای اعمال اجبار و فشار تعبیر نکن. تو خواهان رستگاری هستی. تو می خواهی شاد باشی. تو صلح می خواهی. در حال حاضر فاقد این‌ها هستی زیرا ذهن تو کاملاً غیر منضبط است و نمی‌توانی شادی را از غم، لذت را از رنج و عشق را از ترس تشخیص دهی. اینک تو می‌آموزی که چگونه آن‌ها را از هم جدا کنی. و حقیقتاً پاداشت عظیم خواهد بود.

تصمیم تو برای دیدن، همه‌ی چیزی است که برای رؤیت ضروری است. آن‌چه می‌خواهی متعلق به تو است. اگر تلاشی که از تو خواسته می‌شود کوچک است اشتباه نکن و این را نشانه‌ی کم‌ارزش بودن هدف ما ندان. آیا رستگاری دنیا می تواند هدف ناچیزی باشد؟ و آیا دنیا می تواند نجات یابد اگر تو نجات پیدا نکنی؟ خداوند* یک فرزند* دارد، و او خود هم رستاخیز و هم حیات است. ارادۀ* او* انجام می‌شود زیرا همه‌ی قدرت در بهشت و زمین به او عطا شده است. پی‌آمد تصمیم قاطع تو برای دیدن، رؤیتی است که به تو عطا شده.

تمرین‌های امروز شامل این هستند که تو در طول روز به خودت یادآوری کنی که می‌خواهی ببینی. ایده‌ی امروز همچنین به طور ضمنی اشاره می‌کند به تشخیص این که تو در حال حاضر نمی‌بینی. بنابراین، با تکرار این ایده، بیان می‌کنی که مصمم هستی وضعیت فعلی خود را به وضعیتی بهتر تغییر دهی، به وضعیتی که واقعاً خواهانش هستی.

ایده‌ی امروز را به آرامی و با قاطعیت حداقل دو بار در هر ساعت تکرار کن، و سعی کن که تکرار این ایده را هر نیم ساعت انجام دهی. اگر انجام این کار را فراموش کردی دچار تنش نشو، اما واقعاً تلاش کن به یاد بسپاری. تکرارهای بیشتر باید برای هر شرایط، فرد یا رویدادی که تو را آشفته می‌کند به کار برده شود. تو می‌توانی رویدادها را متفاوت ببینی، و اینگونه خواهد شد. آن‌چه می‌خواهی، خواهی دید. چنین است قانون واقعی علت و معلول، آن‌گونه که در دنیای ما عمل می‌کند.', 'https://acim-farsi.org/workbook/lesson/20', 'https://acim-farsi.org/audio/workbook/lesson/20.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (21, 'من مصمم هستم چیزها را به طرز متفاوتی ببینم.', 'من مصمم هستم چیزها را به طرز متفاوتی ببینم.

من مصمم هستم که ـــــــ [نام فرد] را به طرز متفاوتی ببینم.

من مصمم هستم که ـــــــ [شرایط را مشخص کنید] را به طرز متفاوتی ببینم.

من مصمم هستم که ـــــــ [صفت را مشخص کن] را در ـــــــ [نام فرد] به طرز متفاوتی ببینم.
من مصمم هستم که ـــــــ [نام فرد] را به طرز متفاوتی ببینم.', 'من مصمم هستم چیزها را به طرز متفاوتی ببینم.

ایده امروز ظاهراً تداوم و گسترش ایده پیشین است. اما این بار دوره‌های جستجوی ذهنی ضروری هستند، بعلاوه به کار بردن این ایده برای شرایط خاصی که پیش می‌آیند. پنج برنامه تمرین توصیه می‌شود و اجازه بده هرکدام یک دقیقه طول بکشد.

برنامه‌های تمرین را با تکرار ایده برای خود آغاز کن. سپس چشمانت را ببند و ذهنت را به دقت برای شرایطی در گذشته و حال یا شرایط قابل پیش بینی که می‌توانند خشم تو را برانگیزند، جستجو کن. این خشم می تواند شکل هر واکنشی را به خود بگیرد، از تحریک پذیری ملایم تا خشونت. درجه‌بندی احساسی که تجربه می‌کنی اهمیتی ندارد. تو به طور فزاینده‌ای آگاه خواهی شد که یک سوزش ناچیز از رنجش چیزی نیست جز پرده‌ای که خشم شدید را پوشانده است.

پس، بکوش، تا مگذاری که «خرده» افکار خشم در خلال تمرین‌ها از توجه تو دور بمانند. به یاد داشته باش که تو واقعاً تشخیص نمی‌دهی چه چیزی خشم تو را برمی‌انگیزد، و هیچ یک از چیزهایی که در این رابطه به آن باور داری معنایی ندارد. تو احتمالاً وسوسه خواهی شد به برخی از شرایط یا اشخاص بیش از دیگر موارد بپردازی، بر این مبنای فریبنده که آن‌ها «آشکارتر» هستند. چنین نیست. این صرفاً مثالی از این باور است که برخی شکل‌های حمله موجه‌تر از بقیه هستند.

همچنان که ذهن خود را برای تمام شکل‌هایی که افکار حمله خود را در آن نمایان می‌کنند، جستجو می‌کنی، هر یک را در ذهن نگه دار، در حالی که به خودت می‌گویی: من مصمم هستم که ـــــــ [نام فرد] را به طرز متفاوتی ببینم. من مصمم هستم که ـــــــ [شرایط را مشخص کنید] را به طرز متفاوتی ببینم.

سعی کن تا حد ممکن صریح باشی. ممکن است برای نمونه تو خشم خود را بر صفت خاصی در یک شخص خاص متمرکز کنی، با این باور که خشمت به این جنبه محدود می‌شود. اگر ادراک تو از این شکل تحریف رنج می‌برد، بگو: من مصمم هستم که ـــــــ [صفت را مشخص کن] را در ـــــــ [نام فرد] به طرز متفاوتی ببینم.', 'https://acim-farsi.org/workbook/lesson/21', 'https://acim-farsi.org/audio/workbook/lesson/21.mp3', 'times_per_day', '[{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (22, 'آنچه که من می‌بینم شکلی از انتقام است.', 'من فقط زودگذر را می‌بینم.
من هیچ چیزی را نمی‌بینم که ماندگار خواهد بود.
چیزی که من می‌بینم واقعی نیست.
چیزی که من می‌بینم شکلی از انتقام است.

آیا این دنیایی است که من واقعاً می‌خواهم ببینم؟', 'آنچه که من می‌بینم شکلی از انتقام است.

ایدهٔ امروز با دقت شیوه‌ای را وصف می‌کند که هر کس افکار حمله را در ذهن نگه می‌دارد قطعاً دنیا را این‌گونه می‌بیند. با فرافکندن خشم خود بر دنیا، انتقام را می‌بیند که در‌آستانهٔ حمله‌ور شدن به او است. پس حملهٔ خودش به عنوان دفاع از خود ادراک می‌شود. این به یک چرخه شرورانه فزاینده تبدیل می‌شود تا زمانی که او اراده کند چگونگی نگاهش را تغییر دهد. در غیر این صورت، افکار حمله و ضدحمله ذهن او و مردمان تمام دنیایش را به خود مشغول خواهد کرد. آن‌وقت کدام آرامش ذهن برای او ممکن است؟

از این تخیلات وحشیانه است که تو می‌خواهی فرار کنی. آیا این خبر خوشحال کننده نیست که بشنوی این واقعی نیست؟ آیا این کشف شادمانه نیست که دریابی تو می‌توانی فرار کنی؟ آن‌چه که می خواهی ویران کنی، خودت ساختی؛ تمام چیزهایی که از آن‌ها نفرت داری، و می‌خواهی به آن‌ها حمله کنی و آن‌ها را بکشی. همه‌ی چیزی که از آن می‌ترسی، وجود ندارد.

امروز به دنیای پیرامون خود حداقل پنج بار و هربار حداقل به مدت یک دقیقه نگاه کن. همینطور که چشمانت به آرامی از یک شیء به شیء دیگر، از بدنی به بدن دیگرگذر می‌کنند به خودت بگو: من فقط زودگذر را می‌بینم. من هیچ چیزی را نمی‌بینم که ماندگار خواهد بود. چیزی که من می‌بینم واقعی نیست. چیزی که من می‌بینم شکلی از انتقام است. در پایان هر برنامه تمرین از خودت بپرس: آیا این دنیایی است که من واقعاً می‌خواهم ببینم؟ پاسخ مطمئناً واضح است.', 'https://acim-farsi.org/workbook/lesson/22', 'https://acim-farsi.org/audio/workbook/lesson/22.mp3', 'times_per_day', '[{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (23, 'من با رها کردن افکار حمله می‌توانم از دنیایی که می‌بینم فرار کنم.', 'من با رها کردن افکار حمله می‌توانم از دنیایی که می‌بینم فرار کنم.

من می‌توانم از دنیایی که می‌بینم با رها کردن افکار حمله درمورد ـــــــ فرار کنم.', 'من با رها کردن افکار حمله می‌توانم از دنیایی که می‌بینم فرار کنم.

ایده امروز شامل تنها راه خروج از ترس می‌شود که امکان موفقیت خواهد داشت. هیچ راه دیگری جواب نخواهد داد؛ هر چیز دیگری بی‌معنا است. اما این روش نمی‌تواند شکست بخورد. هر فکری که تو داری، قطعه ای از دنیایی را که می‌بینی می‌سازد. پس اگر قرار باشد ادراک تو از جهان تغییر کند، باید با افکار تو کار کنیم.

اگر علت دنیایی که تو می‌بینی افکار حمله است، باید بیاموزی این افکار هستند که تو نمی‌خواهی. زاری کردن برای دنیا هیچ فایده‌ای ندارد. تلاش برای تغییر دادن دنیا هیچ فایده‌ای ندارد. آن قابل تغییر نیست چون صرفا یک معلول است. اما تغییر دادن افکارت دربارهٔ دنیا قطعاً فایده دارد. در این جا تو در حال تغییر دادن علت هستی. معلول خود به خود تغییر خواهد کرد.

دنیایی که تو می‌بینی یک دنیای پر از کینه است، و هر چیزی که در آن وجود دارد نمادی از کینه است. هر یک از ادراکات تو از «واقعیت بیرونی»، یک نمود تصویری از افکار حمله خود تو است. به خوبی می‌توان این پرسش را مطرح کرد که آیا صحیح است این را دیدن بخوانیم؟ آیا تخیل یک کلمه بهتر برای چنین فرآیندی نیست، و توهم اصطلاحی مناسب‌تر برای نتیجه‌ای که پیش می‌آید؟

تو دنیایی را می‌بینی که ساخته‌ای، اما خودت را به عنوان سازنده تصویر نمی‌بینی. تو نمی‌توانی از دنیا محافظت شوی، اما می‌توانی از علت آن فرار کنی. این معنای رستگاری است، زیرا جهانی که تو می‌بینی کجاست اگر علت آن حذف شده باشد؟ خود رؤیت جایگزینی برای همه چیزهایی خواهد بود که تو اکنون فکر می‌کنی که می‌بینی. دلپذیری می‌تواند تصویرهای تو را روشن کند، و از این طریق آن‌ها را چنان تغییر دهد که تو به آن‌ها عشق خواهی ورزید، اگرچه آنها قبلا از نفرت ساخته باشند. زیرا تو در ساختن آنها تنها نخواهی بود.

ایده امروز این فکر را معرفی می‌کند که تو در دنیایی که می‌بینی به دام نیفتاده‌ای، زیرا علت آن می‌تواند تغییر کند. این تغییر مستلزم این است که ابتدا علت مشخص شود و بعد رها گردد، تا بتواند جایگزین شود. دو گام نخست در این فرآیند به همکاری تو نیازمند است. گام نهایی چنین نیست. تصویرهای تو در آن زمان جایگزین شده خواهند بود. با برداشتن دو گام اول تو خواهی دید که چنین می‌شود.

در کنار استفاده از ایده امروز در طول روز در صورت نیاز، پنج برنامه تمرین برای به کار بردن این ایده لازم است. در حالی که به پیرامون خود نگاه می‌کنی، ایده امروز را به آرامی برای خود تکرار کن، و سپس چشمان خود را ببند و حدود یک دقیقه صرف کن برای جستجو کردن ذهن خود برای هر تعداد افکار حمله که برایت روی می‌دهد. همچنان که هر یک از این افکار به ذهنت می‌آید بگو: من می‌توانم از دنیایی که می‌بینم با رها کردن افکار حمله درمورد ـــــــ فرار کنم. هر فکر حمله را در ذهنت مادامی که این جمله را می‌گویی نگه دار، و سپس آن فکر را رها کن و به سراغ فکر بعدی برو.

در برنامه‌های تمرین مطمئن شو که هم افکار خود را از حمله کردن و هم از حمله شدن می‌گنجانی. تاثیرات آن‌ها کاملا مشابه هستند زیرا آن‌ها کاملا مشابه هستند. تو هنوز این را تشخیص نمی‌دهی، و در این مرحله از تو تنها خواسته می‌شود که در برنامه‌های تمرین امروز با آن‌ها مشابه یکدیگر برخورد کنی. ما هنوز در مرحله تعیین علت دنیایی هستیم که تو می‌بینی. وقتی نهایتاً آموختی که افکار مربوط به حمله و مورد حمله قرار گرفتن با یکدیگر متفاوت نیستند، آماده خواهی بود که علت را رها کنی.', 'https://acim-farsi.org/workbook/lesson/23', 'https://acim-farsi.org/audio/workbook/lesson/23.mp3', 'times_per_day', '[{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (24, 'من بهترین مصالح خودم را درک نمی‌کنم.', 'من بهترین مصالح خودم را درک نمی‌کنم.

در شرایط شامل ـــــــ، من دوست دارم ـــــــ اتفاق بیفتد، و ـــــــ اتفاق بیفتد،... و همین طور الی آخر.
در شرایط شامل ـــــــ، من دوست دارم ـــــــ اتفاق بیفتد، و ـــــــ اتفاق بیفتد،... و همین طور الی آخر.

در شرایط شامل ـــــــ، من دوست دارم ـــــــ اتفاق بیفتد، و ـــــــ اتفاق بیفتد،... و همین طور الی آخر.

من بهترین مصالح خودم را در این شرایط درک نمی‌کنم. و به سراغ بعدی برو.', 'من بهترین مصالح خودم را درک نمی‌کنم.

در هیچ یک از شرایطی که پیش می‌آید تو تشخیص نمی‌دهی که چه نتیجه‌ای خوشحالت می‌کند. بنابراین تو هیچ راهنمایی برای عمل مناسب نداری، و هیچ شیوه‌ای برای قضاوت کردن در مورد نتیجه. آن‌چه تو انجام می‌دهی توسط ادراک تو از شرایط تعیین می‌شود، و آن ادراک نادرست است. پس، این بدیهی است، که تو به بهترین مصالح خود خدمت نخواهی کرد. اگرچه آن‌ها تنها هدف تو در هر شرایطی هستند که به خوبی ادراک شود. در صورت ادراک نادرست، تو تشخیص نخواهی داد این مصالح چه هستند.

اگر تو تشخیص می‌دادی که بهترین مصالح خود را درک نمی‌کنی، می‌‌شد به تو آموخت که آن‌ها چه هستند. اما با وجود این یقین که تو می‌دانی آن‌ها چه هستند، نمی‌توانی بیاموزی. ایده امروز گامی است به سوی باز کردن ذهن تو تا آموختن بتواند آغاز شود.

تمرینات امروز صداقت بسیار بیشتری را از آن‌چه تو به استفاده از آن خو گرفته‌ای، می‌طلبند. در هر یک از پنج برنامه تمرین لازم برای امروز، باید به چند سوژه با صداقت و دقت توجه شود و این مفیدتر از آزمون کردن سرسری تعداد زیادی سوژه خواهد بود. دو دقیقه برای هر مرحله جستجوی ذهنی در هر تمرین توصیه می‌شود.

برنامه‌های تمرین باید با تکرار کردن ایده امروز آغاز شود، و در پی آن جستجوی ذهنی با چشمان بسته برای شرایط حل نشده‌ای که تو در حال حاضر دلواپس آن هستی. تأکید باید بر آشکار کردن نتیجه‌ای باشد که تو می‌خواهی. به سرعت متوجه خواهی شد که تعدادی از اهداف را به عنوان بخشی از نتیجه دلخواه در ذهن داری، و نیز این که این اهداف در سطوح مختلف هستند و اغلب با یکدیگر تعارض دارند.

در تمرین با ایده امروز هر موقعیتی را که به ذهنت می‌رسد نام گذاری کن، و سپس هر تعداد اهداف ممکن را که دوست داری با حل آن‌ها به دست بیاوری به دقت برشمار. شکل هرتمرین باید به طور تقریبی مانند مثال زیر باشد: در شرایط شامل ـــــــ، من دوست دارم ـــــــ اتفاق بیفتد، و ـــــــ اتفاق بیفتد،... و همین طور الی آخر. سعی کن هر چند نوع مختلف از نتایج را که صادقانه ممکن است به ذهنت برسد در این جملات جای بدهی، حتی اگر برخی از آن‌ها ظاهراً ربط مستقیمی با این موقعیت نداشته باشند، یا حتی به نظر نیاید که اصلاً در آن وجود دارند.

اگر این تمرینات به درستی انجام شوند، تو به سرعت تشخیص خواهی داد که در حال ساخت تعداد زیادی از خواسته‌ها از شرایطی هستی که هیچ ربطی به آن ندارند. تو همچنین تشخیص خواهی داد که بسیاری از اهداف تو با یکدیگر تضاد دارند، این که هیچ نتیجه واحدی در ذهن نداری، و این که تو باید ناکامی را در ارتباط با برخی از اهدافت تجربه کنی، حال شرایط به هر سویی برود.

پس از کار کردن با فهرست هر تعداد ممکن از اهداف آرزویی خود، برای هر شرایط حل نشده‌ای که به ذهنت خطور می‌کند به خودت بگو: من بهترین مصالح خودم را در این شرایط درک نمی‌کنم. و به سراغ بعدی برو.', 'https://acim-farsi.org/workbook/lesson/24', 'https://acim-farsi.org/audio/workbook/lesson/24.mp3', 'times_per_day', '[{"kind":"times_per_day","count":5}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (25, 'من نمی‌دانم هر چیزی برای چیست.', 'من نمی‌دانم هر چیزی برای چیست.

من نمی‌دانم این صندلی برای چیست.
من نمی‌دانم این مداد برای چیست.
من نمی‌دانم این دست برای چیست.', 'من نمی‌دانم هر چیزی برای چیست.

هدف معنا است. ایده امروز شرح می‌دهد که چرا هیچ یک از چیزهایی که تو می‌بینی هیچ معنایی ندارد. تو نمی‌دانی که برای چیست. بنابراین برای تو بی‌معنا است. همه چیزها برای بهترین مصالح تو هستند. برای همین هم هستند، هدف آن‌ها این است؛ معنای آن‌ها این است. در شناخت این موضوع است که اهداف تو به وحدت می‌رسند. در شناخت این موضوع است که به آن‌چه می‌بینی، معنا داده می‌شود.

تو دنیا و همه چیزهایی را که در آن هست برحسب اهداف نفس، معنی‌دار درک می‌کنی. این اهداف هیچ کاری با بهترین مصالح تو ندارند، زیرا تو نفس نیستی. این مطابقت نادرست، تو را در درک کردن هدف همه چیز ناتوان می‌کند. و در نتیجه ناگزیر می‌شوی از آن‌ها به نادرستی استفاده کنی. وقتی این باور را داری، تو تلاش خواهی کرد اهدافی را که نسبت به دنیا داری کنار بگذاری، به جای تلاش کردن برای تقویت این اهداف.

شیوه دیگر برای توصیف اهدافی که تو در حال حاضر درک می‌کنی این است که بگوییم همه آن‌ها مربوط به مصالح «شخصی» هستند. از آن‌جا که تو هیچ مصالح شخصی نداری، اهداف تو واقعاً به هیچ چیز مربوط نیستند. بنابراین با پروردن آن‌ها، تو اصلاً هیچ هدفی نداری. و از این رو نمی‌دانی که هر چیزی برای چیست.

پیش از آن که بتوانی هر فهمی از تمرینات امروز داشته باشی، یک فکر دیگر نیز لازم است. در سطحی‌ترین لایه‌ها، تو هدف را تشخیص می‌دهی. اما نمی‌توان هدف را در این لایه‌ها درک کرد. برای نمونه، تو درک می‌کنی که یک تلفن برای قصد صحبت کردن با فردی است که از نظر جسمانی در دسترس مستقیم تو نیست. آن‌چه که درک نمی‌کنی این است که به چه دلیلی می‌خواهی به او دسترسی پیدا کنی. و این است که تماس تو را با او بی‌معنا یا بامعنا می‌کند.

برای آموختن بسیار حیاتی است که تو اراده‌مند باشی اهدافی را که برای هر چیزی تثبیت کرده‌ای، رها کنی. تشخیص این که این اهداف بی‌معنا هستند و نه «خوب» یا «بد»، تنها راه دستیابی به این مقصود است. ایده امروز گامی در این مسیر است.

شش برنامه تمرین، هریک به مدت دو دقیقه لازم است. هر برنامه تمرین باید با تکرار آرام ایده امروز آغاز شود، و سپس به پیرامون خود نگاه کن و اجازه بده نگاه تو بر هر چیزی که چشمت به آن می‌افتد درنگ کند، نزدیک یا دور، «مهم» یا «غیرمهم»، «انسان» یا «غیرانسان». در حالی که نگاهت را بر روی هر سوژه که به این صورت انتخاب می‌کنی نگه داشته‌ای، مثلاً بگو: من نمی‌دانم این صندلی برای چیست. من نمی‌دانم این مداد برای چیست. من نمی‌دانم این دست برای چیست. این را نسبتاً به آرامی بگو، بدون این که چشم خود را تا کامل کردن جمله در مورد هر سوژه از روی آن برداری. سپس به سوژه بعدی حرکت کن، و ایده امروز را مانند قبلی به کار ببر.', 'https://acim-farsi.org/workbook/lesson/25', 'https://acim-farsi.org/audio/workbook/lesson/25.mp3', 'times_per_day', '[{"kind":"times_per_day","count":6}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (26, 'افکار حمله‌ی من، به آسیب‌ناپذیری من حمله می‌کنند.', 'افکار حمله‌ی من، به آسیب‌ناپذیری من حمله می‌کنند.

من درباره‌ی _____دلواپس هستم.

من می‌ترسم ـــــــ اتفاق بیفتد.

پس از نامگذاریِ هر نتیجه‌ای که از آن می‌ترسی، به خودت بگو:

این فکر، حمله‌ای است به خودم.

افکار حمله‌ی من، به آسیب‌ناپذیری من حمله می‌کنند.', 'افکار حمله‌ی من، به آسیب‌ناپذیری من حمله می‌کنند.

مطمئناً واضح است که اگر می‌توان به تو حمله کرد، پس آسیب‌ناپذیر نیستی. تو حمله را به عنوان یک تهدید واقعی می‌بینی. به این دلیل که باور داری می‌توانی واقعاً حمله کنی. و آنچه می‌تواند از طریق تو تأثیر بگذارد، باید بتواند بر تو نیز اثر بگذارد. همین قانون نهایتاً از تو محافظت خواهد کرد، اما تو اکنون در حال استفاده‌ی نادرست از آن هستی. بنابراین باید یاد بگیری که چگونه این قانون می‌تواند برای بهترین مصالح تو استفاده شود، نه علیه آن‌ها.

از آن‌جا که افکار حمله‌ی تو فرافکن خواهند شد، از حمله خواهی ترسید. و اگر از حمله بترسی، باور خواهی کرد که آسیب‌ناپذیر نیستی. بنابراین افکار حمله تو را در ذهن خود، یعنی جایی که این افکار هستند، آسیب‌پذیر می‌کنند. افکار حمله و آسیب‌ناپذیری را نمی‌توان همراه با یکدیگر پذیرفت. آن‌ها با هم متناقض هستند.

ایده‌ی امروز این فکر را معرفی می‌کند که تو همیشه اول به خودت حمله می‌کنی. از آنجا که افکار حمله این باور را در خود دارند که تو آسیب‌پذیر هستی، تأثیر آن‌ها ضعیف کردن تو در نظر خودت است. پس این افکار به ادراک تو از خودت حمله می‌کنند. و از آن‌جا که آن‌ها را باور داری، دیگر نمی‌توانی خودت را باور کنی. تصویر نادرستی از خودت، جای آن‌چه هستی را گرفته است.

تمرین با ایده‌ی امروز به تو کمک خواهد کرد بفهمی که آسیب‌پذیری یا آسیب‌ناپذیری نتیجه‌ی افکار خود تو است. هیچ چیز جز افکارت نمی‌تواند به تو حمله کند. هیچ چیز جز افکارت نمی‌تواند موجب شود که تو فکر کنی آسیب‌پذیر هستی. و هیچ چیز جز افکارت نمی‌تواند به تو اثبات کند که چنین نیست.

برای به کار بردن ایده‌ی امروز شش برنامه‌ی تمرین مورد نیاز است. برای هر برنامه‌ی تمرین باید دو دقیقه کامل صرف شود، اگرچه در صورت احساس ناراحتی بسیار شدید می‌توان این زمان را به یک دقیقه کاهش داد. زمان هر برنامه را بیش از این کاهش نده.

برنامه‌ی تمرین باید با تکرار کردن ایده‌ی امروز آغاز شود، سپس چشمان خود را ببند و مسائل حل نشده‌ای را مرور کن که نتایج آن‌ها تو را دلواپس می‌کند. این دلواپسی ممکن است شکل افسردگی، نگرانی، خشم، احساسی از تحمیل، ترس، پیش‌بینی بد یا مشغولیت ذهنی را به خود بگیرد. هر مسئله‌ای که تاکنون حل نشده باشد و بتواند به افکار تو در طول روز برگردد، سوژه‌ای مناسب است. شما قادر نخواهی بود که در هر برنامه‌ی تمرین روی تعداد زیادی سوژه کار کنی، زیرا مجبور می‌شوی زمانی طولانی‌تر از معمول را برای هر برنامه صرف کنی. ایده‌ی امروز باید به روش زیر تمرین شود:

ابتدا، موقعیت را نامگذاری کن: من درباره‌ی _____دلواپس هستم. سپس تمام پیامدهای ممکن را که در این ارتباط برای تو پیش آمده‌اند و موجب دلواپسی تو شده‌اند مرور کن، و در حالی که به طور اختصاصی به هر یک اشاره می‌کنی بگو: من می‌ترسم ـــــــ اتفاق بیفتد.

اگر به خوبی تمرین را انجام دهی، باید حدود پنج یا شش احتمال ناخوشایند و احتمالاً بیشتر از این را برای هر موقعیتی که با آن کار می‌کنی در دسترس داشته باشی. بسیار مفیدتر است که با چند موقعیت به خوبی کار کنی تا این که تعداد زیادی موقعیت را فقط لمس کنی. با ادامه‌ی فهرست کردن نتایج قابل پیش بینی برای هر موقعیت، احتمالاً متوجه خواهی شد که برخی از آن‌ها، خصوصاً آن‌ها که در اواخر به ذهن تو می‌رسند، برایت کمتر پذیرفتنی هستند. اما سعی کن تا حد ممکن با همه‌ی آن‌ها یکسان برخورد کنی.

پس از نامگذاریِ هر نتیجه‌ای که از آن می‌ترسی، به خودت بگو: این فکر، حمله‌ای است به خودم. هر برنامه‌ی تمرین را با یک بار دیگر تکرار کردن ایده‌ی امروز برای خودت پایان بده.', 'https://acim-farsi.org/workbook/lesson/26', 'https://acim-farsi.org/audio/workbook/lesson/26.mp3', 'times_per_day', '[{"kind":"times_per_day","count":6}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (27, 'بالاتر از هرچیز دیگر، من می‌خواهم ببینم.', 'بالاتر از هرچیز دیگر، من می‌خواهم ببینم.

اگر نبود استثنائی که در این ایده درج است موجب ناراحتی تو می‌شود، اضافه کن:

رؤیت برای هیچکس هزینه‌ای ندارد.

اگر ترس از دست دادن هنوز باقی بود، باز اضافه کن:

آن فقط می‌تواند برکت دهد.', 'بالاتر از هرچیز دیگر، من می‌خواهم ببینم.

ایده‌ی امروز چیزی قوی‌تر از صِرف مصمم بودن را بیان می‌کند. این تمرین به بینش در بین خواسته‌های تو، اولویت می‌دهد. ممکن است در استفاده از این ایده احساس تردید کنی، بر این اساس که مطمئن نیستی منظورت واقعاً همین است. مهم نیست. هدف تمرینات امروز، اندکی به جلو انداختن زمانی است که این ایده کاملاً حقیقت پیدا کند.

ممکن است وسوسه‌ی بسیار زیادی برای این باور وجود داشته باشد که وقتی می‌گویی بالاتر از هر چیز می‌خواهی ببینی، نوعی قربانی از تو خواسته می‌شود. اگر نبود استثنائی که در این ایده درج است موجب ناراحتی تو می‌شود، اضافه کن: رؤیت برای هیچکس هزینه‌ای ندارد. اگر ترس از دست دادن هنوز باقی بود، باز اضافه کن: آن فقط می‌تواند برکت دهد.

ایده‌ی امروز برای بیشترین فایده، نیاز به تکرار بسیار زیاد دارد. باید دست‌کم هر نیم ساعت از آن استفاده کنی، و در صورت امکان بیشتر. باید تلاش کنی هر پانزده یا بیست دقیقه این تکرار را انجام دهی. توصیه می‌شود که یک فاصله‌ی زمانی معین را برای استفاده از این ایده، زمانی که بیدار می‌شوی یا با فاصله کوتاهی پس از آن تعیین کنی و سعی کنی در طول روز آن را رعایت نمایی. انجام این کار دشوار نخواهد بود، حتی اگر مشغول مکالمه باشی، یا در آن زمان به شکل دیگری درگیر باشی. در این حال هم می‌توانی یک جمله‌ی کوچک را بدون تداخل با هیچ کاری تکرار کنی.

پرسش واقعی این است که تو با چه فراوانی به یاد خواهی آورد؟ تو چقدر می‌خواهی که ایده‌ی امروز حقیقت داشته باشد؟ اگر به یکی از این پرسش‌ها پاسخ دهی، به پرسش دیگر پاسخ داده‌ای. احتمالاً چندین تمرین را از دست خواهی داد، و شاید تعداد زیادی را از دست بدهی. از این موضوع آشفته نشو، اما واقعاً تلاش کن برنامه‌ی خود را از آن به بعد رعایت کنی. اگر فقط یک بار در طول روز احساس کردی که کاملاً در زمان تکرار کردن ایده‌ی امروز صادق بوده‌ای، می‌توانی مطمئن باشی که سال‌های زیادی تلاش را برای خودت ذخیره کرده‌ای.', 'https://acim-farsi.org/workbook/lesson/27', 'https://acim-farsi.org/audio/workbook/lesson/27.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (28, 'بالاتر از هرچیز دیگر، من می‌خواهم چیزها را به طرز متفاوتی ببینم.', 'بالاتر از هرچیز دیگر، من می‌خواهم چیزها را به طرز متفاوتی ببینم.

بالاتر از هرچیز دیگر، من می‌خواهم این ـــــــ را به طرز متفاوتی ببینم.', 'بالاتر از هرچیز دیگر، من می‌خواهم چیزها را به طرز متفاوتی ببینم.

امروز ما واقعاً در حال کاربردی کردن ایده‌ی دیروز به صورت اختصاصی هستیم. در این برنامه‌های تمرین، تو مجموعه‌ای از تعهدات مشخص را خواهی پذیرفت. اینجا این پرسش که آیا در آینده به آن‌ها پایبند خواهی بود یا خیر، مورد نظر ما نیست. اگر در حال حاضر حداقل تصمیم داری این تعهدات را بپذیری، مسیر پایبندی به آن‌ها را آغاز کرده‌ای. و ما هنوز در سرآغاز هستیم.

ممکن است تعجب کنی که چرا مهم است مثلاً بگویی: «بالاتر از هرچیز دیگر، من می‌خواهم این میز را به طرز متفاوتی ببینم.» به خودی خود، این اصلاً مهم نیست. اما به خودی خود چیست؟ و «به خودی خود» چه معنایی دارد؟ تو تعداد زیادی چیزهای جداگانه پیرامون خود می‌بینی، و این واقعاً بدین معنا است که اصلاً در حال دیدن نیستی. تو یا می‌بینی یا نمی‌بینی. زمانی که یک چیز را متفاوت دیده باشی، همه چیز را متفاوت خواهی دید. نوری که در هر یک از آن‌ها خواهی دید، همان نوری است که در همه‌ی آن‌ها خواهی دید.

زمانی که می‌گویی: «بالاتر از هرچیز دیگر، من می‌خواهم این میز را به طرز متفاوتی ببینم»، در حال متعهد شدن به این هستی که ایده‌های پیش‌باورانه‌ی خود را در مورد میز رها کنی، و ذهن خود را برای این باز کنی که چه هست، و برای چیست. تو در حال تعریف آن به شکل قبل نیستی. تو در حال پرسیدن هستی که آن چیست، به جای اینکه به آن بگویی که چیست. معنای آن را به تجربه‌ی ناچیز خود از میزها مقید نمی‌کنی، و همچنین هدف آن را به افکار شخصی کوچکت محدود نمی‌کنی.

تو چیزی را که قبلاً تعریفش کرده‌ای مورد پرسش قرار نخواهی داد. و هدف از این تمرینات، پرسیدن پرسش‌ها و دریافت پاسخ‌ها است. در گفتن «بالاتر از هرچیز دیگر، من می‌خواهم این میز را به طرز متفاوتی ببینم»، تو خود را به دیدن متعهد می‌کنی. این یک تعهد انحصاری نیست. این تعهدی است که برای میز به اندازه‌ی هر چیز دیگری کاربرد دارد، نه کمتر و نه بیشتر.

در واقع تو می‌توانستی رؤیت را از همان میز به دست آوری، اگر همه‌ی ایده‌های خود از آن را رها می‌کردی، و با یک ذهن کاملاً باز به آن نظر می‌انداختی. این میز چیزی برای نشان دادن به تو دارد؛ چیزی زیبا و پاکیزه و دارای ارزش نامتناهی، سرشار از شادی و امید. هدف واقعیِ آن در زیر همه‌ی ایده‌های تو در موردش پنهان است، و در این هدف با تمامی کائنات شریک است.

بنابراین در استفاده از میز به عنوان سوژه‌ای برای تمرین با ایده‌ی امروز، تو واقعاً در حال درخواست برای دیدن هدف کائنات هستی. همین درخواست را در مورد هر سوژه‌ای خواهی داشت که امروز با آن تمرین می‌کنی. و تو به هر یک از آن‌ها متعهد خواهی شد که اجازه دهی هدفش بر تو آشکار شود، به جای این که قضاوت خود را بر آن بیفکنی.

امروز ما شش برنامه‌ی تمرین دو دقیقه‌ای خواهیم داشت. در هر تمرین ابتدا ایده‌ی روز را بیان کن، و سپس برای هر چیزی که پیرامونت می‌بینی به کار ببر. نه فقط سوژه‌ها را باید به طور تصادفی انتخاب کنی، بلکه باید در تمرین ایده‌ی امروز با هر یک احساس نزدیکی یکسانی به خرج دهی. این یعنی تلاش برای تصدیق ارزش یکسان همه‌ی آن‌ها در یاری کردن به دیدن تو.

طبق معمول، در تمرینات باید نام سوژه‌ای را که چشمانت به آن افتاده است ذکر کنی، و باید نگاه خود را بر روی آن نگه داری در حالی که می‌گویی: بالاتر از هرچیز دیگر، من می‌خواهم این ـــــــ را به طرز متفاوتی ببینم. هر تمرین باید تا حد ممکن آهسته باشد، و تا حد ممکن متفکرانه. هیچ شتابزدگی در کار نیست.', 'https://acim-farsi.org/workbook/lesson/28', 'https://acim-farsi.org/audio/workbook/lesson/28.mp3', 'times_per_day', '[{"kind":"times_per_day","count":6}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (29, 'خداوند* در همه‌ی چیزهایی که من می‌بینم هست.', 'خداوند* در همه‌ی چیزهایی که من می‌بینم هست.

خداوند* در این رخت‌آویز است.
خداوند* در این مجله است.
خداوند* در این انگشت است .
خداوند* در این لامپ است.
خداوند* در آن بدن است.
خداوند* در آن در است.
خداوند* در آن سبد زباله است.', 'خداوند* در همه‌ی چیزهایی که من می‌بینم هست.

ایده‌ی امروز توضیح می‌دهد که چرا تو می‌توانی همه‌ی قصد را در همه چیز ببینی. این ایده توضیح می‌دهد که چرا هیچ چیز جدا از دیگری، برای خودش یا به خودی خود نیست. و این ایده توضیح می‌دهد که چرا هیچ چیزی که تو می‌بینی معنایی ندارد. در واقع این ایده همه‌ی ایده‌هایی را که ما تا حال استفاده کرده‌ایم و نیز همه‌ی ایده‌های بعدی را توضیح می‌دهد. ایده‌ی امروز پایه‌ای کامل برای رؤیت است.

احتمالاً تو درک این ایده را در حال حاضر بسیار دشوار بدانی. ممکن است آن را احمقانه، نامناسب، بی‌معنی، مسخره و حتی قابل اعتراض بیابی. مثلاً مطمئن هستی آنگونه که تو می‌بینی، خداوند* در یک میز نیست. اما ما دیروز تأکید کردیم که یک میز در قصد کائنات سهیم است. و آنچه در قصد کائنات سهیم است، در قصد آفریدگار* آن نیز سهیم است.

پس امروز تلاش کن تا یادگیریِ چگونه نگاه کردن به همه چیز را با عشق، پذیرش و ذهن باز آغاز کنی. تو در حال حاضر آن‌ها را نمی بینی. آیا می‌خواهی بدانی چه چیز در آن‌ها هست؟ هیچ چیز آنطور که به نظر تو می‌رسد نیست. قصد مقدس همه چیز فراتر از حدود کوچک تو قرار گرفته. وقتی رؤیت، آن تقدس را به تو نشان دهد که دنیا را درخشان می‌کند، آنگاه به طور کامل ایده‌ی امروز را درخواهی یافت. و آن زمان دیگر درک نخواهی کرد که چگونه اصلاً می‌توانستی آن را دشوار بدانی.

شش برنامه‌ی تمرین دو دقیقه‌ای امروز ما باید از الگویی پیروی کند که اینک برای تو آشنا است: با تکرار کردن ایده برای خود آغاز کن، و سپس آن را با سوژه‌های پیرامونت که تصادفی انتخاب می‌شوند تمرین کن، در حالی که هر یک را به طور اختصاصی نامگذاری می‌کنی. سعی کن از تمایل به انتخاب خودساخته پرهیز نمایی. این نحوه انتخاب ممکن است خصوصاً در ارتباط با ایده‌ی امروز وسوسه کننده باشد، زیرا این ایده ماهیتی کاملاً بیگانه دارد. به یاد داشته باش که اگر تو هر ترتیبی را اعمال کنی، به همان اندازه با واقعیت بیگانه است.

پس فهرست سوژه‌های تو باید تا حد ممکن از خودانتخابگری رها باشد. برای مثال یک فهرست مناسب ممکن است موارد زیر را در بر گیرد: خداوند* در این رخت‌آویز است. خداوند* در این مجله است. خداوند* در این انگشت است . خداوند* در این لامپ است. خداوند* در آن بدن است. خداوند* در آن در است. خداوند* در آن سبد زباله است. علاوه بر برنامه‌های تمرین تعیین شده، ایده‌ی امروز را حداقل یک بار در هر ساعت تکرار کن، در این زمان در حالی که کلمات را بدون شتاب به خودت می‌گویی، به آرامی به پیرامونت نگاه کن. حداقل یک یا دو بار باید احساس آرامش را با انجام این کار تجربه کنی.', 'https://acim-farsi.org/workbook/lesson/29', 'https://acim-farsi.org/audio/workbook/lesson/29.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (30, 'خداوند* در تمام چیزهایی که من می‌بینم هست، زیرا خداوند* در ذهن من است.', 'خداوند* در تمام چیزهایی که من می‌بینم هست، زیرا خداوند* در ذهن من است.', 'خداوند* در تمام چیزهایی که من می‌بینم هست، زیرا خداوند* در ذهن من است.

ایده‌ی امروز تخته‌ی پرش برای رؤیت است. بعد از این ایده دنیا پیش روی تو گشوده خواهد شد، و به آن نظر خواهی کرد، و چیزی را در آن خواهی دید که قبلاً هرگز ندیده‌ای. و آنچه قبلاً دیده‌ای حتی اندکی برایت قابل دیدن نخواهد بود.

امروز ما تلاش می‌کنیم از نوع جدید «فرافکنی» استفاده کنیم. ما سعی نمی‌کنیم از چیزی که نمی‌خواهیم، با دیدن آن در بیرون خلاص شویم. بلکه تلاش می‌کنیم در این دنیا آنچه را که در ذهنمان است ببینیم، و آنچه می‌خواهیم بشناسیم در ذهن وجود دارد. از این طریق ما سعی می‌کنیم به آنچه می‌بینیم بپیوندیم، به جای این که آن را جدا از خود بدانیم. این تفاوت بنیادین بین رؤیت و شیوه‌ی دیدن تو است.

ایده‌ی امروز را باید به هر تعداد ممکن در طول روز تمرین کنی. هر زمان که لحظه‌ای فرصت داشتی، در حالی که به پیرامونت نگاه می‌کنی، آن را آرام برای خودت تکرار کن. همزمان سعی کن تشخیص دهی که این ایده هم برای همه‌ی چیزهایی که اکنون می‌بینی کاربرد دارد، و هم برای چیزهایی که ممکن بود اکنون ببینی، اگر در محدوده‌ی بینایی تو بودند.

رؤیت واقعی به مفاهیمی مانند «نزدیک» و «دور» محدود نمی‌شود. برای یاری به خود در آغازِ خو گرفتن به این ایده، در حالی که ایده‌ی امروز را به کار می‌بری، سعی کن علاوه بر آن چیزهایی که عملاً می‌توانی ببینی در مورد چیزهایی فکر کنی که فراتر از محدوده‌ی دید فعلی تو هستند.

رؤیت واقعی نه تنها محدود به ‌فضا و فاصله نیست، بلکه به هیچ وجه وابسته به چشمان بدن نیز نیست. تنها منبع آن ذهن است. برای کمک در خو گرفتن بیشتر با این ایده، چندین برنامه‌ی تمرینی را به تمرین ایده‌ی امروز با چشمان بسته اختصاص بده، با استفاده از هر سوژه‌ای که به ذهنت می‌آید، و با نگاه کردن به درون به جای نگاه کردن به بیرون. ایده‌ی امروز به طور مساوی برای هر دو استفاده می‌شود.', 'https://acim-farsi.org/workbook/lesson/30', 'https://acim-farsi.org/audio/workbook/lesson/30.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (31, 'من قربانی دنیایی که می‌بینم نیستم.', 'من قربانی دنیایی که می‌بینم نیستم.', 'من قربانی دنیایی که می‌بینم نیستم.

درس امروز، مقدمۀ بیانیۀ تو برای رهایی است. این ایده را نیز باید هم با دنیایی که در بیرون می‌بینی تمرین کنی، و هم با دنیایی که در درون می‌بینی. در تمرین با این ایده با شیوه‌ای کار می‌کنیم که پس از این بیشتر و بیشتر از آن استفاده خواهیم کرد، و در صورت لزوم تغییراتی را در آن ایجاد می‌کنیم. به طور کلی، این شیوه دو جنبه را در بر می‌گیرد: در یکی از این جنبه‌ها تو ایده را با استمرار بیشتری استفاده خواهی کرد، و جنبۀ دیگر شامل تمرین‌های مکرر با ایده در طول روز می‌شود.

امروز دو برنامه‌ی تمرین طولانی‌تر با ایده‌ی روز ضروری است، یکی در صبح و دیگری در شب. سه تا پنج دقیقه برای هر تمرین توصیه می‌شود. در طول این زمان آرام به پیرامون خود نگاه کن، در حالی که ایده را دو یا سه بار تکرار می‌کنی. سپس چشمان خود را ببند و همین ایده را با دنیای درونی تمرین کن. تو از هر دوی آنها با هم نجات خواهی یافت، زیرا دنیای درونی علت دنیای بیرونی است.

در حالی که دنیای درونی خود را می‌کاوی، صرفاً اجازه بده هر فکری که به ذهنت خطور می کند به درون آگاهی‌ات بیاید، به هر یک به اندازه‌ی یک لحظه توجه کن و سپس آن را با بعدی جایگزین کن. سعی کن هیچ‌گونه سلسله مراتبی بین آن‌ها ایجاد نکنی. تا حد ممکن بدون هیجان، آمد و رفت افکار را تماشا کن. با هیچکدام به صورت خاص مشغول نشو، اما سعی کن اجازه دهی که این جریان به صورتی مداوم و آرام بدون هیچگونه تداخل خاصی از سوی تو حرکت کند. در حالی که نشسته‌ای و در سکوت افکارت را تماشا می‌کنی، ایده‌ی امروز را برای خودت به دلخواه بارها تکرار کن، اما بدون احساس شتاب.

بعلاوه، ایده‌ی امروز را به دفعات ممکن در طول روز تکرار کن. به خودت یادآور شو که تو در حال ایجاد بیانیه‌ی استقلال به نام آزادی خود هستی. و در آزادی تو، آزادی این دنیا نهفته است.

ایده‌ی امروز همچنین ایده‌ای خصوصاً مفید برای استفاده در پاسخ به هر نوع وسوسه‌ای است که ممکن است برانگیخته شود. این بیانیه‌ای است حاکی از این که مطیع آن وسوسه نخواهی شد و تو را به بند نخواهد کشید.', 'https://acim-farsi.org/workbook/lesson/31', 'https://acim-farsi.org/audio/workbook/lesson/31.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (32, 'من دنیایی را که می‌بینم، اختراع کرده‌ام.', 'من دنیایی را که می‌بینم، اختراع کرده‌ام.', 'من دنیایی را که می‌بینم، اختراع کرده‌ام.

امروز کار کردن با موضوع علت و معلول را ادامه می‌دهیم. تو قربانی این دنیایی که می‌بینی نیستی، زیرا آن را اختراع کرده‌ای. می‌توانی به همان آسانی که آن را ساخته‌ای، رهایش کنی. بسته به میل تو خواهد بود که آیا بخواهی آن را ببینی یا نبینی. تا زمانی که آن را می‌خواهی، آن را خواهی دید. وقتی دیگر آن را نخواهی، دیگر وجود نخواهد داشت تا بتوانی آن را ببینی.

ایده‌ی امروز نیز مانند ایده‌های پیشین، هم برای دنیای درون و هم برای دنیای بیرون کاربرد دارد، دنیاهایی که عملاً با هم یکی هستند. اما از آنجا که تو آن‌ها را متفاوت می‌بینی، برنامه‌های تمرین امروز شامل دو مرحله خواهند بود: یکی دربرگیرندۀ آن دنیا که تو بیرون از خود می‌بینی، و دیگری دربرگیرندۀ آن دنیا که تو در ذهن خود می‌بینی. در تمرینات امروز سعی کن با این اندیشه آشنا شوی که هردوی این دنیاها در تصور خود تو هستند.

ما دوباره برنامه‌های تمرین صبح و عصر را با دو یا سه مرتبه تکرار کردن ایده‌ی امروز آغاز می‌کنیم، در حال نگاه کردن به پیرامون، به دنیایی که تو آن را دنیای بیرون از خودت می‌بینی. سپس چشمانت را ببند و به پیرامونِ دنیای درونیِ خود نگاه کن. سعی کن با هردوی آن‌ها در حد ممکن یکسان برخورد کنی. ایده‌ی امروز را بدون شتاب به هر تعداد ممکن که مایل هستی تکرار کن، در حالی که به تصاویری نگاه می‌کنی که تصور تو به آگاهی‌ات ارائه می‌کند.

برای دو برنامه‌ی تمرین طولانی‌تر، زمان سه تا پنج دقیقه توصیه می‌شود و لازم است کمتر از سه دقیقه نباشد. می‌توان بیش از پنج دقیقه تمرین کرد، اگر احساس آرامش داشته باشی. برای تسهیل آرامش خود زمانی را برای تمرین انتخاب کن که پیش‌بینی می‌کنی کمترین مزاحمت وجود دارد، و زمانی که خودت احساس می‌کنی واقعاً آماده هستی.

تمرینات همچنین باید در طول روز به دفعات ممکن ادامه یابند. تمرینات کوتاه‌تر شامل تکرار کردن ایده‌ی امروز به آرامی می‌شوند، در حالی که دنیای درونی یا بیرونی خود را کاوش می‌کنی. تفاوتی ندارد که کدام را انتخاب می‌کنی.

ایده‌ی امروز همچنین باید در هر شرایطی که ممکن است تو را آشفته کند، بلافاصله استفاده شود. از این ایده با گفتن جمله زیر به خودت استفاده کن: من این شرایط را خلق کرده‌ام، همین‌گونه که آن را می‌بینم.', 'https://acim-farsi.org/workbook/lesson/32', 'https://acim-farsi.org/audio/workbook/lesson/32.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (33, 'شیوۀ دیگری برای نگاه کردن به این دنیا وجود دارد.', 'شیوۀ دیگری برای نگاه کردن به این وجود دارد.', 'شیوۀ دیگری برای نگاه کردن به این دنیا وجود دارد.

ایده‌ی امروز تلاشی است برای تشخیص این که تو می‌توانی ادراکت را از این دنیا هم از جنبه درونی و هم از جنبه بیرونی آن تغییر دهی. باید پنج دقیقه‌ی کامل را به تمرینات صبح و عصر خود اختصاص دهی. در این برنامه‌های تمرین، باید ایده را به دفعاتی که با آن راحت هستی تکرار کنی، اگرچه نداشتن شتاب در انجام تمرینات اساسی است. کاوش ادراکات بیرونی و درونی خود را با هم جابجا کن، اما بدون یک احساس ناگهانیِ تغییر و جابجایی.

صرفاً عادی به پیرامون این دنیایی که دنیای بیرون از خود درک می‌کنی، نگاه بینداز، سپس چشمانت را ببند و افکار درونی خود را همانطور معمولی کاوش کن. سعی کن با هر دو به یک اندازه غیردرگیر باقی بمانی، و این فاصله را در تمرینات مکرر امروز خود با ایده‌ی روز، حفظ کنی.

برنامه‌های تمرین کوتاه‌تر را باید به دفعات ممکن انجام دهی. استفاده از ایده‌ی امروز همچنین در شرایط خاص، هر زمان شرایطی بروز کند که می‌تواند تو را دچار تنش سازد، باید بلافاصله انجام شود. برای این استفاده بگو: شیوۀ دیگری برای نگاه کردن به این وجود دارد.

به یاد داشته باش که از ایده‌ی امروز در لحظه‌ای که از وجود تنش آگاه می‌شوی استفاده کنی. ممکن است لازم باشد حدود یک دقیقه ساکت بنشینی و این ایده را چندین بار برای خودت تکرار کنی. بستن چشمان می‌تواند به این شیوه تمرین کمک کند.', 'https://acim-farsi.org/workbook/lesson/33', 'https://acim-farsi.org/audio/workbook/lesson/33.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (34, 'من می‌توانم صلح را به جای این ببینم.', 'من می‌توانم در این شرایط صلح را ببینم، به جای چیزی که اکنون در آن می‌بینم.

من می‌توانم احساس‌های افسردگی، اضطراب، نگرانی [یا افکارم در مورد این شرایط، شخصیت یا رویداد] را با صلح جایگزین کنم.', 'من می‌توانم صلح را به جای این ببینم.

ایده‌ی امروز آغاز به توضیح شرایطی می‌کند که در شیوه‌ی دیگرِ دیدن برتری دارد. واضح است که آرامش ذهن یک موضوع درونی است. این آرامش باید با اندیشه‌های خود تو آغاز شود، و سپس به بیرون گسترش یابد. از صلح ذهن تو است که ادراک صلح‌آمیزی از این دنیا ظهور می‌کند.

امروز سه برنامه‌ی طولانی‌تر تمرین مورد نیاز است. یکی در صبح و یکی در عصر، با یک برنامه‌ی اضافه که باید بین این دو تمرین اجرا شود، هر زمان که به نظر می‌رسد بیشترین آمادگی وجود دارد. لازم است که همه‌ی تمرینات را با چشمان بسته انجام دهی. این دنیای درونی تو است که کاربرد ایده امروز باید برای آن انجام شود.

در برنامه‌های طولانی‌تر تمرین باید حدود پنج دقیقه را به کاوش ذهنی اختصاص دهی. ذهنت را جستجو کن، برای پندارهای ترسناک، شرایط اضطراب‌انگیز، شخصیت‌ها یا رویدادهای «رنجاننده»، یا هر چیز دیگری که در مورد آن افکار غیرعاشقانه را می‌پروری. به همه‌ی آن‌ها به صورت عادی توجه کن، و ایده‌ی امروز را به آرامی تکرار کن در حالی که ظهور این پندارها را در ذهنت تماشا می‌کنی، و هر یک را رها کن تا با بعدی جایگزین شود.

اگر در اندیشیدن به سوژه‌های خاصی احساس دشواری کردی، به تکرار بدون شتاب ایده برای خود ادامه بده، بدون کاربرد آن برای هیچ چیزی به طورخاص . اما مطمئن شو که هیچ چیز را نیز مخصوصاً حذف نمی‌کنی.

کاربرد‌های کوتاه‌تر باید مکرر باشند و هرگاه که احساس می‌کنی صلح ذهنت به هر شکلی تهدید می‌شود، انجام شوند. هدف این تمرینات، حفاظت از خود در برابر وسوسه در طول روز است. اگر به ظهور شکل خاصی از وسوسه در خود آگاه شدی، تمرین تو باید به این شکل باشد: من می‌توانم در این شرایط صلح را ببینم، به جای چیزی که اکنون در آن می‌بینم.

اگر اخلال در آرامش ذهن تو شکل احساسات ناخوشایند عمومی‌تر مانند افسردگی اضطراب یا نگرانی را به خود گرفت، از ایده‌ی امروز در شکل اصلی آن استفاده کن. اگر متوجه شدی که برای کمک به تغییر ذهن خود در یک موقعیت خاص به بیش از یک نوبت تمرین با این ایده نیاز داری، سعی کن چندین دقیقه وقت بگذاری و در این زمان ایده را تکرار کنی، تا وقتی که به نوعی احساس تسکین دست یابی. کمک کننده خواهد بود اگر به خودت به طور اختصاصی بگویی: من می‌توانم احساس‌های افسردگی، اضطراب، نگرانی [یا افکارم در مورد این شرایط، شخصیت یا رویداد] را با صلح جایگزین کنم.', 'https://acim-farsi.org/workbook/lesson/34', 'https://acim-farsi.org/audio/workbook/lesson/34.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (35, 'ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.', 'ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.

من خودم را مجبور می‌بینم.
من خودم را افسرده می‌بینم.
من خودم را شکست خورده می‌بینم.
من خودم را در خطر می‌بینم.
من خودم را بی‌پناه می‌بینم.
من خودم را پیروزمند می‌بینم.
من خودم را گمشده می‌بینم.
من خودم را قابل تحسین می‌بینم.
من خودم را خبره می‌بینم.

پس از نامگذاری هر یک از آن‌ها اضافه کن:

اما ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.', 'ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.

ایده‌ی امروز شیوه‌ای را توصیف نمی‌کند که تو اکنون خودت را می‌بینی. اما توصیف می‌کند که رؤیت، چه چیزی را به تو نشان خواهد داد. برای هر کسی که می‌پندارد در این دنیا حضور دارد، باور کردن این اندیشه در مورد خودش دشوار است. اما دلیل این که می‌پندارد در این دنیا است، همین است که این اندیشه را باور ندارد.

تو باور می‌کنی بخشی از جایی هستی که می‌پنداری در آنجا حضور داری. دلیل این است که خودت را با محیطی که می‌خواهی، احاطه می‌کنی. و از آن محیط می‌خواهی که تصویر ساختگی تو از خودت را محافظت کند. این تصویر، بخشی از این محیط است. آنچه تو می‌بینی، تا زمانی که باور داری در آن حضور داری، از طریق چشمان این تصویر دیده می‌شود. این رؤیت نیست. تصاویر نمی‌توانند ببینند.

ایده‌ی امروز نمایانگر یک منظر بسیار متفاوت از خود تو است. با استوار کردن سرچشمۀ* تو، هویت* تو را استوار می‌کند، و تو را چنان وصف می‌کند که باید واقعاً در حقیقت استقرار یابی. امروز نوع نسبتاً متفاوتی از تمرین با ایده‌ی روز را مورد استفاده قرار خواهیم داد، زیرا امروز تأکید بیشتر بر ادراک کننده است تا چیزی که او درک می‌کند.

امروز هریک از سه برنامه‌ی تمرین پنج دقیقه‌ای خود را با تکرار کردن ایده‌ی روز برای خودت آغاز کن، و سپس چشمان خود را ببند و ذهنت را برای انواع مختلف واژه‌های توصیفی که خودت را در آن‌ها می‌بینی جستجو کن. شامل همه خصوصیاتِ نفس-پایه که تو به خودت نسبت می‌دهی، مثبت یا منفی، دلخواه یا غیردلخواه، بزرگ‌منشانه یا حقیرانه. همه‌ی آن‌ها به یکسان غیرواقعی هستند زیرا تو به خودت از درون چشمان مقدس‌بین نگاه نمی‌کنی.

در بخش ابتدایی مرحله‌ی کاوش ذهنی، احتمالاً بر آنچه که منفی‌ترین ادراکات تو از خودت است تأکید خواهی کرد. اما با ادامه دادن تمرین و رفتن به بخش بعدی، کلمات توصیفی نفس‌پرور بیشتر به ذهن می‌رسند. سعی کن تشخیص دهی که مسیر تخیلات تو درمورد خودت اهمیتی ندارد. واقعیت این است که اوهام هیچ مسیری ندارند. آن‌ها صرفاً حقیقی نیستند.

یک فهرست مناسب فارق از انتخاب برای به کار بردن ایده‌ی امروز ممکن است مانند مثال زیر باشد: من خودم را مجبور می‌بینم. من خودم را افسرده می‌بینم. من خودم را شکست خورده می‌بینم. من خودم را در خطر می‌بینم. من خودم را بی‌پناه می‌بینم. من خودم را پیروزمند می‌بینم. من خودم را گمشده می‌بینم. من خودم را قابل تحسین می‌بینم. من خودم را خبره می‌بینم.

نباید به این واژه‌ها به صورت مجرد فکر کنی. در طی تمرین متوجه می‌شوی که آن‌ها به صورت شرایط، شخصیت‌ها و رویدادهای مختلفی برای تو پیش می‌آیند. هر شرایط خاصی را که به ذهنت می‌رسد انتخاب کن، واژه یا واژگان توصیفی را که احساس می‌کنی در مورد واکنش‌های تو نسبت به آن شرایط مصداق دارند مشخص کن، و ایده‌ی روز را با آن‌ها تمرین کن. پس از نامگذاری هر یک از آن‌ها اضافه کن: اما ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.

در طول برنامه‌های تمرین طولانی‌تر، احتمالاً زمان‌هایی خواهد بود که هیچ چیز خاصی به ذهنت نمی‌رسد. به خودت فشار نیاور که به چیزهای خاصی برای پر کردن این زمان فکر کنی، بلکه صرفاً راحت باش و ایده‌ی امروز را به آرامی تکرار کن تا چیزی به ذهنت برسد. اگرچه نباید هیچ چیزی را که به ذهنت می‌رسد از تمرین حذف کنی، هیچ چیزی را نباید با تقلا «کندوکاو» کنی. نه اجبار باید استفاده شود و نه تمایز.

به دفعات ممکن در طول روز، یک صفت یا صفات خاصی را که به خودت نسبت می‌دهی انتخاب کن و در هر نوبت، ایده‌ی روز را با آن تمرین کن، با اضافه کردن این ایده در شکل ذکر شده به هر یک از آن‌ها. اگر هیچ چیز خاصی به ذهنت نرسید، صرفاً ایده را با چشمان بسته تکرار کن.', 'https://acim-farsi.org/workbook/lesson/35', 'https://acim-farsi.org/audio/workbook/lesson/35.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (36, 'قداست من همه‌ی چیزهایی را که می‌بینم، در بر می‌گیرد.', 'دوره‌های تمرین کوتاه‌تر:

قداست من همه‌ی چیزهایی را که می‌بینم، در بر می‌گیرد.

دوره‌های تمرین طولانی‌تر:

قداست من آن فرش را در بر می‌گیرد.
قداست من آن دیوار را در بر می‌گیرد.
قداست من این انگشتان را در بر می‌گیرد.
قداست من آن صندلی را در بر می‌گیرد.
قداست من آن بدن را در بر می‌گیرد.
قداست من این قلم را در بر می‌گیرد.', 'قداست من همه‌ی چیزهایی را که می‌بینم، در بر می‌گیرد.

ایده‌ی امروز، ایده‌ی دیروز را از درک کننده به درک شونده گسترش می‌دهد. تو قدسی هستی، زیرا ذهن تو بخشی از ذهن* خداوند* است. و چون قدسی هستی، دید تو نیز باید قدسی باشد. «بی‌گناه» یعنی بدون گناه. تو نمی‌توانی کمی بدون گناه باشی. یا بی‌گناه هستی، یا نیستی. اگر ذهن تو بخشی از ذهن* خداوند* است، ناگزیر هستی بی‌گناه باشی، یا اینکه بخشی از ذهن* او* گناهکار است. دید تو به قداست او مربوط می‌شود، نه به نفس تو، و بنابراین به بدنت ربطی ندارد.

امروز به چهار برنامه‌ی تمرین سه تا پنج دقیقه‌ای نیاز است. سعی کن این تمرین‌های را در طول روز تقریباَ به طور منظم پخش کنی و تمرینات کوتاه‌تر را به صورت مکرر انجام دهی، تا در سراسر روز از امنیت خود حفاظت کنی. برنامه‌های تمرین طولانی‌تر باید این شکل را داشته باشند:

ابتدا چشمانت را ببند و ایده‌ی روز را به آرامی چند بار تکرار کن. سپس چشمان خود را بگشای، نسبتاً آرام به پیرامونت نگاه کن و ایدهٔ امروز را به طور خاص با هر چیزی که با نگاه معمولی خود متوجه می‌شوی، تمرین کن. مثلاً بگو: قداست من آن فرش را در بر می‌گیرد. قداست من آن دیوار را در بر می‌گیرد. قداست من این انگشتان را در بر می‌گیرد. قداست من آن صندلی را در بر می‌گیرد. قداست من آن بدن را در بر می‌گیرد. قداست من این قلم را در بر می‌گیرد. در طول این برنامه‌های تمرین، چندین بار چشمانت را ببند و ایده‌ی روز را برای خودت تکرار کن. سپس چشمانت را باز کن و مانند قبل ادامه بده.

برای برنامه‌های کوتاه‌تر تمرین چشمانت را ببند و ایده را تکرار کن، سپس در حالی که به پیرامون خود نگاه می‌کنی دوباره آن را تکرار کن، و با یک بار دیگر تکرار کردن ایده با چشمان بسته، به تمرین پایان بده. البته همه‌ی تمرین‌ها باید تا حد ممکن به آرامی و بدون تلاش و شتاب انجام شوند.', 'https://acim-farsi.org/workbook/lesson/36', 'https://acim-farsi.org/audio/workbook/lesson/36.mp3', 'times_per_day', '[{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (37, 'قداست من دنیا را متبرک می‌کند.', 'دوره‌های تمرین کوتاه‌تر:

قداست من دنیا را متبرک می‌کند.

دوره‌های تمرین طولانی‌تر:

قداست من این صندلی را متبرک می‌کند.
قداست من آن پنجره را متبرک می‌کند.
قداست من این بدن را متبرک می‌کند.

سپس چشمانت را ببند و این ایده را با هرکس که به ذهنت می‌رسد تمرین کن، در حالی که از نام او استفاده می‌کنی و می‌گویی:

قداست من تو را متبرک می‌کند، [نام].', 'قداست من دنیا را متبرک می‌کند.

این ایده حاوی نخستین تابش‌های ضعیف وظیفهٔ حقیقی تو در دنیا، یا چرایی بودن تو در اینجا است. قصد تو این است که دنیا را از طریق قداست خود ببینی. در این صورت تو و دنیا با هم متبرک می‌شوید. هیچ‌کسی نمی‌بازد؛ هیچ‌چیز از هیچ‌کس سلب نمی‌شود؛ همگان از طریق رؤیت قدسی تو بهره می‌برند. این حاکی از پایانِ قربانی دادن است، زیرا ارج کامل هرکس را به او ارزانی می‌کند. و او مستحق همه‌چیز است زیرا به عنوان یک فرزند* خداوند* این حق طبیعی‌اش است.

هیچ راه دیگری وجود ندارد تا از آن طریق بتوان عقیده‌ی قربانی کردن را از اندیشه‌ی این دنیا حذف کرد. هر طریق دیگری برای دیدن، ناگزیر از شخصی یا چیزی درخواست پرداخت بها خواهد کرد. در نتیجه، ادراک کننده دچار باخت خواهد شد. در حالی که هیچ ایده‌ای از علت باخت خود ندارد. اما از طریق رؤیت تو، یکپارچگی‌اش به آگاهی وی بازمی‌گردد. قداست تو او را بدون هیچگونه درخواستی متبرک می‌کند. آنان که خود را یکپارچه می‌بینند، هیچ درخواستی ندارند.

قداست تو همان رستگاری این دنیا است. این قداست به تو اجازه می‌دهد به این دنیا بیاموزی که با تو یگانه است، نه با موعظه کردن، نه با گفتن هیچ چیزی به آن، بلکه صرفاً با تشخیص بی‌صدای این که در قداست تو همه چیز به همراهت متبرک می‌شود.

امروز چهار تمرین طولانی‌تر سه تا پنج دقیقه‌ای خواهی داشت. با تکرار ایده‌ی روز آغاز کن، و سپس برای یک دقیقه به پیرامونت نگاه کن در حالی که این ایده را با هرچه می‌بینی، تمرین می‌کنی: قداست من این صندلی را متبرک می‌کند. قداست من آن پنجره را متبرک می‌کند. قداست من این بدن را متبرک می‌کند. سپس چشمانت را ببند و این ایده را با هرکس که به ذهنت می‌رسد تمرین کن، در حالی که از نام او استفاده می‌کنی و می‌گویی: قداست من تو را متبرک می‌کند، [نام].

تو می‌توانی برنامه‌ی تمرین را با چشمان بسته ادامه دهی، می‌توانی چشمانت را دوباره بگشایی و در صورت تمایل ایده‌ی روز را با دنیای بیرونی خود تمرین کنی، می‌توانی بین تمرین کردن ایده با آنچه پیرامونت می‌بینی و کسانی که در افکارت هستند جابجایی انجام دهی، یا می‌توانی هر ترکیبی از این دو مرحله را که ترجیح می‌دهی، مورد استفاده قرار دهی. برنامه‌ی تمرین باید با یک تکرار ایده‌ی امروز با چشمان بسته و بلافاصله یک تکرار دیگر با چشمان باز، پایان یابد.

تمرینات کوتاه‌تر شامل تکرار کردن ایده است به دفعاتی که برایت امکان دارد. خصوصاً مفید است که این ایده را با هرکس که ملاقات می‌کنی در سکوت تمرین کنی، در حالی که از نامش استفاده می‌کنی. اساسی است که این ایده را با هر کسی که به نظر می‌رسد در تو واکنشی ناخوشایند را موجب می‌شود، تمرین کنی. تبرکِ قداست خود را بلافاصله نثار او کن، تا بتوانی حفظ آن را در آگاهی خود بیاموزی.', 'https://acim-farsi.org/workbook/lesson/37', 'https://acim-farsi.org/audio/workbook/lesson/37.mp3', 'times_per_day', '[{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (38, 'هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.', 'دوره‌های تمرین کوتاه‌تر:

هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.

دوره‌های تمرین طولانی‌تر:

در شرایط شامل ...که من خودم را درگیر آن می‌بینم، هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.
در شرایط شامل ... که ... خودش را درگیر آن می‌بیند، هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.

هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد زیرا قدرت خداوند* در آن قرار دارد.', 'هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.

قداست تو همه‌ی قوانین این دنیا را معکوس می‌کند. قداست تو فراتر از هر محدودیت زمان، مکان، فاصله و هرگونه حدود است. قدرت قداست تو کاملاً نامحدود است، زیرا جایگاه تو را به عنوان فرزند* خداوند* استوار می‌کند، در یگانگی با ذهن* آفریدگارش*.

از طریق قداست تو، قدرت خداوند* به ظهور می‌رسد. از طریق قداست تو، قدرت خداوند* قابل دسترسی می‌شود. و هیچ کاری وجود ندارد که قدرت خداوند* در انجامش ناتوان باشد. پس قداست تو می‌تواند تمامی دردها را برطرف کند، می‌تواند به تمامی غم‌ها پایان بخشد، و می‌تواند تمامی مسائل را حل کند. قداست تو می‌تواند این کارها را در ارتباط با خود تو و در ارتباط با هرکس دیگری انجام دهد. به هرکسی با همان قدرت کمک می‌کند، زیرا قدرت آن برای نجات همگان یکسان است.

اگر تو قدسی هستی، پس هر چیزی که خداوند* آفریده این‌چنین است. تو قدسی هستی زیرا همه‌ی چیزهایی که او* آفریده است، قدسی هستند. و همه‌ی چیزهایی که او* آفریده قدسی هستند، زیرا تو چنین هستی. در تمرین‌های امروز، ما قدرت قداست تو را با همه‌ی مسائل، مشکلات و رنج‌ها تمرین می‌کنیم، در هر شکلی که به نظر شما می‌آیند، در خودت یا در هر کس دیگری. ما بین این‌ها هیچ تمایزی قایل نیستیم، زیرا هیچ تمایزی وجود ندارد.

امروز چهار برنامه‌ی تمرین طولانی‌تر خواهیم داشت که هر یک ترجیحاً پنج دقیقه‌ی کامل طول می‌کشد. در هر تمرین، ایده‌ی امروز را تکرار کن، چشمانت را ببند، و سپس ذهن خود را برای هر احساس فقدان یا ناشادمانی از هر نوعی که به نظرت می‌آید جستجو کن. سعی کن کمترین تمایز ممکن را بین شرایطی که برای تو دشوار است و شرایطی که برای فرد دیگری دشوار است، قایل شوی. شرایط را به صورت خاص مشخص کن، و نیز نام فردی را که درگیر آن شرایط است. از این شکل برای تمرین کردن ایده امروز استفاده کن: در شرایط شامل ...که من خودم را درگیر آن می‌بینم، هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد. در شرایط شامل ... که ... خودش را درگیر آن می‌بیند، هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.

ممکن است گاهی بخواهی این شیوه را تغییر دهی و برخی اندیشه‌های مربوط را از سوی خودت اضافه کنی. مثلاً ممکن است بخواهی اندیشه‌هایی مانند این را در تمرین بگنجانی: هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد زیرا قدرت خداوند* در آن قرار دارد. از هر ترکیبی که به نظرت مناسب می‌رسد استفاده کن. اما تمرکز تمرینات بر این موضوع را حفظ کن: «هیچ کاری وجود ندارد که قداست من در انجامش ناتوان باشد.» هدف تمرینات امروز، آغاز کردن القاء این حس است که تو برحسب ماهیت وجودی خودت، بر همه چیز تسلط داری.

در تمرینات کوتاه‌تر مکرر، از ایده‌ی امروز در شکل اصلی آن استفاده کن مگر مشکل خاصی مربوط به تو یا فرد دیگری بروز کند یا به ذهنت برسد. در این صورت شکل اختصاصی‌تر ایده را برای کار کردن با آن مشکل استفاده کن.', 'https://acim-farsi.org/workbook/lesson/38', 'https://acim-farsi.org/audio/workbook/lesson/38.mp3', 'times_per_day', '[{"kind":"times_per_day","count":4}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (39, 'قداست من، رستگاری من است.', 'تمرین کوتاه‌تر:

قداست من، رستگاری من است.
اگر احساس گناه جهنم است، متضاد آن چیست؟
قداست من، رستگاری من از این است.

تمرین طولانی‌تر:

افکار ناخوشایند من درمورد...، مرا در جهنم نگاه می‌دارند.
قداست من رستگاری من است.


اگر احساس گناه جهنم است، متضاد آن چیست؟', 'قداست من، رستگاری من است.

اگر احساس گناه جهنم است، متضاد آن چیست؟ مانند «متن» که اساس این درسنامه است، ایده‌های مورد استفاده برای تمرینات نیز بسیار ساده، بسیار شفاف و کاملاً بدون ابهام هستند. دغدغه‌ی ما شاهکارهای عقلانی یا بازیچه‌های منطقی نیست. ما فقط با آنچه بسیار آشکار است سر و کار داریم، که در ابرهای پیچیدگی که تو می‌پنداری در آن‌ها فکر می‌کنی، نادیده گرفته شده است.

اگر احساس گناه جهنم است، متضاد آن چیست؟ مطمئناً این دشوار نیست. درنگی که ممکن است تو در پاسخ دادن احساس کنی، ناشی از ابهام در پرسش نیست. اما آیا تو باور داری که احساس گناه، جهنم است؟ اگر چنین باور داشتی، بی‌درنگ می‌دیدی که «متن» چقدر مستقیم و ساده است، و اصلاً نیازی به یک درسنامه نمی‌داشتی. هیچکس برای دستیابی به آنچه پیشاپیش از آن او است، نیازی به تمرین ندارد.

ما قبلاً گفتیم که قداست تو رستگاری این دنیا است. اما رستگاری خود تو چه می‌شود؟ تو نمی‌توانی چیزی را بدهی که نداری. یک نجات دهنده باید نجات یافته باشد. اگرنه چگونه می‌تواند رستگاری را آموزش دهد؟ تمرینات امروز را با خودت انجام خواهی داد، با تشخیص دادن این که رستگاری تو برای رستگاری این دنیا حیاتی است. وقتی این تمرین‌ها را با دنیای خود کار می‌کنی، همه‌ی دنیا به پا می‌خیزد تا بهره‌مند شود.

قداست تو پاسخ به همه‌ی پرسش‌هایی است که تا حال پرسیده شده، اکنون پرسیده می‌شود، یا در آینده پرسیده خواهد شد. قداست تو به معنای پایان احساس گناه است، و این یعنی پایان جهنم. قداست تو یعنی رستگاری این دنیا و خودت. چگونه تو که صاحب قداست هستی ممکن است از آن برکنار بمانی؟ خداوند* هیچ عدم قداست را نمی‌شناسد. آیا ممکن است که او* فرزند* خود* را نشناسد؟

پنج دقیقه‌ی کامل برای چهار تمرین طولانی‌تر امروز توصیه می‌شود و تو را تشویق می‌کنیم تا برنامه‌های تمرین طولانی‌تر و به دفعات بیشتر داشته باشی. اگر می‌خواهی از حداقل نیاز برنامه‌ی امروز فراتر بروی، افزایش تعداد تمرینات بهتر از افزایش زمان است، اگرچه هر دو توصیه می‌شوند.

برنامه‌های تمرین را مانند معمول آغاز کن، با تکرار کردن ایده‌ی امروز برای خودت. سپس با چشمان بسته افکار ناخوشایند خود را در هر شکلی که ظاهر می‌شوند، جستجو کن: ناخرسندی، افسردگی، خشم، ترس، نگرانی، حمله، ناامنی و غیره. این افکار هر شکلی که به خود بگیرند ناخوشایند هستند، و بنابراین ترسناک. پس تو نیاز داری که از آن‌ها نجات یابی.

شرایط، رویدادها یا شخصیت‌های خاصی که تو با افکار ناخوشایند از هر نوع همراه می‌دانی، سوژه‌های مناسب برای تمرینات امروز هستند. برای رستگاری تو ضروری است که آنها را با دید متفاوتی ببینی. و متبرک کردن آن‌ها توسط تو است که نجاتت خواهد داد و به تو رؤیت را عطا می‌کند.

به آرامی، بدون گزینش خودآگاهانه و بدون تأکید بی‌جا بر روی هریک به طور خاص، ذهنت را برای همه‌ی افکاری جستجو کن که بین تو و رستگاری تو قرار گرفته‌اند. ایده‌ی امروز را با هریک از آن‌ها به شکل زیر تمرین کن: افکار ناخوشایند من درمورد...، مرا در جهنم نگاه می‌دارند. قداست من رستگاری من است.

برای آسان‌تر کردن این برنامه‌های تمرین می‌توانی در بین تمرینات خود، چندین تمرین کوتاه انجام دهی، در تمرینات کوتاه صرفاً ایده‌ی امروز را به آرامی چند بار برای خودت تکرار کن. همچنین ممکن است مفید باشد که چند وقفه‌ی کوتاه داشته باشی که در این فواصل فقط راحت باشی و گویی به چیزی فکر نمی‌کنی. تمرکز کردن مدام در ابتدا بسیار دشوار است . با انضباط بیشتر ذهن و پراکندگی کمتر آن، بسیار آسان‌تر خواهد شد.

در عین حال، باید این احساس را داشته باشی که در ایجاد تغییرات دلخواه خود در برنامه‌ی تمرین آزاد هستی. اما با ایجاد تغییر در شیوه‌ی تمرین، خود ایده را تغییر نده. آن را به هر شکلی که درمی‌آوری، باید ایده را چنان بیان کنی که معنای آن این واقعیت باشد که قداست تو رستگاری تو است. هر برنامه تمرین را با یک بار دیگر تکرار کردن ایده در شکل اصلی آن پایان بده و اضافه کن: اگر احساس گناه جهنم است، متضاد آن چیست؟

در تمرینات کوتاه‌تر که باید هر ساعت حدود سه تا چهار مرتبه و در صورت امکان بیشتر انجام شود، می‌توانی این پرسش را از خودت بپرسی، ایده‌ی امروز را تکرار کنی، و ترجیحاً هر دو کار را انجام دهی. اگر وسوسه بروز کرد، یک شکل خصوصاً مفید از این ایده چنین است: قداست من، رستگاری من از این است.', 'https://acim-farsi.org/workbook/lesson/39', 'https://acim-farsi.org/audio/workbook/lesson/39.mp3', 'times_per_hour', '[{"kind":"interval","minutes":15},{"kind":"interval","minutes":20}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (40, 'من به عنوان یک فرزند* خداوند* متبرک هستم.', 'من به عنوان یک فرزند* خداوند* متبرک هستم.
من شاد، در صلح، عاشق و راضی هستم.

یک برنامه‌ی تمرین دیگر ممکن است به این شکل باشد:

من به عنوان یک فرزند* خداوند* متبرک هستم.
آرام، ساکت، مطمئن و دارای عزت نفس هستم.

اگر فقط زمان کوتاهی برای تمرین داری، صرفاً این که به خود بگویی تو به عنوان یک فرزند* خداوند* متبرک هستی، کفایت می‌کند.', 'من به عنوان یک فرزند* خداوند* متبرک هستم.

ما امروز اظهار کردن برخی از چیزهای شادی را آغاز می‌کنیم که تو، همین‌گونه که هستی، مستحق آنها هستی. امروز نیازی به تمرینات طولانی‌تر نداری، اما تمرینات کوتاه‌تر بسیار ضروری هستند. انجام یک تمرین کوتاه در هر ده دقیقه بسیار مطلوب است. از تو خواسته می‌شود برای حفظ این روند تلاش کنی و هرزمان که ممکن باشد به آن پایبند بمانی. اگر فراموش کردی، دوباره تلاش کن. اگر وقفه‌های طولانی پیش آمد، دوباره تلاش کن. هرزمان که به یاد آوردی، دوباره تلاش کن.

نیازی نیست که چشمانت را برای برنامه‌های تمرین ببندی، گرچه شاید انجام این کار به تو کمک کند. اما ممکن است برخی شرایط در طول روز پیش بیاید که بستن چشمان میسر نباشد. هیچ برنامه تمرینی را به خاطر این از دست نده. تو می‌توانی به خوبی تحت هر شرایطی تمرین کنی، اگر واقعاً بخواهی.

برای تمرینات امروز زمان کمی صرف می‌شود و هیچ تقلایی لازم نیست. ایده‌ی امروز را تکرار کن، سپس چند صفت را که تو با فرزند* خداوند* بودن همراه می‌دانی اضافه کن، و آن‌ها را به خودت نسبت بده. یک برنامه‌ی تمرین می‌تواند مثلاً شامل جمله زیر باشد: من به عنوان یک فرزند* خداوند* متبرک هستم. من شاد، در صلح، عاشق و راضی هستم. یک برنامه‌ی تمرین دیگر ممکن است به این شکل باشد: من به عنوان یک فرزند* خداوند* متبرک هستم. آرام، ساکت، مطمئن و دارای عزت نفس هستم. اگر فقط زمان کوتاهی برای تمرین داری، صرفاً این که به خود بگویی تو به عنوان یک فرزند* خداوند* متبرک هستی، کفایت می‌کند.', 'https://acim-farsi.org/workbook/lesson/40', 'https://acim-farsi.org/audio/workbook/lesson/40.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (41, 'هرجا که می‌روم، خداوند* با من می‌آید.', 'هرجا که می‌روم، خداوند* با من می‌آید.', 'هرجا که می‌روم، خداوند* با من می‌آید.

ایده‌ی امروز نهایتاً به طور کامل بر حس تنهایی و ترک شدگی که همه‌ی افراد جداشده تجربه می‌کنند، غلبه خواهد کرد. افسردگی یکی از نتایج ناگزیر جداشدگی است. همینطور اضطراب، نگرانی، یک حس عمیق درماندگی، بدبختی، رنج و ترس شدیدِ از دست دادن.

جداشدگان «علاج‌های» بسیاری را برای آنچه به عنوان «بیماری‌های این دنیا» باور دارند، ابداع کرده‌اند. اما آن کاری که انجام نمی‌دهند، پرسش در مورد واقعیت داشتن مشکل است. در این وضعیت معلول را نمی‌توان علاج کرد، زیرا مشکل، واقعی نیست. ایده‌ی امروز این قدرت را دارد که همه‌ی این حماقت را برای همیشه پایان دهد. و این وضعیت حماقت است، با وجود تمامی اشکال جدی و حزن‌انگیزی که می‌تواند به خود بگیرد.

در ژرفای تو همه چیز هست و همه چیز بی‌نقص است، آماده برای درخشش از طریق تو و به درون این دنیا. این درخشش همه‌ی غم و درد و ترس را شفا خواهد داد. زیرا ذهنی را علاج خواهد کرد که می‌پنداشت این چیزها واقعی هستند، و به دلیل وفاداری به آن‌ها رنج می‌کشید.

تو هرگز نمی‌توانی از قداست کامل خود محروم باشی، زیرا سرچشمۀ* آن، هرجا بروی با تو می‌آید. تو هرگز نمی‌توانی رنج بکشی زیرا سرچشمۀ* همۀ سرور، هرجا بروی با تو می‌آید. تو هرگز نمی‌توانی تنها باشی زیرا سرچشمۀ* همۀ زندگی، هرجا بروی با تو می‌آید. هیچ چیز نمی‌تواند صلح ذهن تو را ویران کند، زیرا خداوند* هرجا بروی با تو می‌آید.

ما درک می‌کنیم که تو همه این‌ها را باور نداری. چگونه می‌توانی؟ وقتی حقیقت در ژرفای درون پنهان شده، در زیر ابر سنگینی از پندارهای دیوانه‌وار، متراکم و پوشاننده، پندارهایی که در عین حال همه‌ی آنچه را که تو می‌بینی بازنمایی می‌کنند. امروز نخستین تلاش واقعی خود را برای عبور از این ابر تیره و سنگین و عبور از آن به سوی نور فراسو به عمل خواهیم آورد.

امروز فقط یک برنامه‌ی تمرین طولانی خواهد بود. صبح، در صورت امکان به محض بیدار شدن، ساکت برای حدود سه تا پنج دقیقه با چشمان بسته بنشین. در آغاز تمرین، ایده‌ی امروز را بسیار آرام تکرار کن. سپس هیچ کوششی نکن که به چیزی فکر کنی. در عوض تلاش کن تا حسی از متوجه شدن به درون را دریافت کنی، با عبور از همه‌ی افکار واهی این دنیا. سعی کن خیلی ژرف به درون ذهن خود وارد شوی، در حالی که آن را از هر پنداری که می‌تواند توجه تو را منحرف کند، پاک نگاه می‌داری.

اگر برایت مفید است، گاه به گاه می‌توانی ایده را تکرار کنی. اما بیشتر سعی کن به عمق و درون بروی، دور از این دنیا و همه‌ی پندارهای احمقانه آن. تو در حال تلاش برای عبور از همه‌ی این چیزها هستی. تو در حال تلاش برای ترک کردن ظواهر و دستیابی به واقعیت هستی.

دستیابی به خداوند* آواقعاً ممکن است. در حقیقت بسیار آسان است، زیرا طبیعی‌ترین چیز در این دنیا است. حتی می‌توانی بگویی که تنها چیز طبیعی در این دنیا است. راه گشوده خواهد شد، اگر تو باور کنی که ممکن است. تمرین امروز می‌تواند نتایج تکان دهنده‌ای داشته باشد، حتی از نخستین بار که برای انجام آن تلاش می‌کنی، و دیر یا زود همیشه موفقیت آمیز می‌شود. ما در ادامه به جزئیات بیشتری در مورد این تمرین خواهیم پرداخت. اما این تمرین هرگز با شکست کامل روبرو نمی‌شود، و توفیق آنی با آن ممکن است.

در طول روز با ایده‌ی امروز مکرراً کار کن، آن را بسیار آرام تکرار کن، ترجیحاً با چشمان بسته. به آنچه می‌گویی بیندیش؛ این واژه‌ها چه معنایی دارند. بر قداستی که این کلمات در مورد تو بیان می‌کنند، تمرکز کن؛ بر این همراهی بدون شکست که از آن تو است، بر این محافظت کامل که تو را در بر گرفته است.

در حقیقت تو می‌توانی به اینجا برسی که به پندارهای ترس بخندی، با به یاد آوردن این که خداوند* هرجا که می‌روی، با تو می‌آید.', 'https://acim-farsi.org/workbook/lesson/41', 'https://acim-farsi.org/audio/workbook/lesson/41.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (42, 'خداوند* قدرت من است. رؤیت موهبت او* است.', 'خداوند* قدرت من است. رؤیت موهبت او* است.

رؤیت باید ممکن باشد. خداوند* حقیقتاً آن را عطا می‌کند، یا:
خداوند* حقیقتاً آن را عطا می‌کند، یا:
موهبت‌های خداوند* برای من باید از آن من باشند، زیرا او* آن‌ها را به من عطا کرده است.', 'خداوند* قدرت من است. رؤیت موهبت او* است.

ایده‌ی امروز دو اندیشه‌ی بسیار قدرتمند را با هم می‌آمیزد، که هر دو اهمیت عمده‌ای دارند. این ایده همچنین یک رابطه‌ی علت و معلول را بیان می‌کند که توضیح می‌دهد چرا کوشش‌های تو برای دستیابی به هدف این دوره، قطعاً موفق می‌شود. تو خواهی دید، زیرا این ارادۀ* خداوند* است. این نیروی او* است که به تو قدرت می‌دهد، نه نیروی خودت. و این بیشتر موهبت او* است که رؤیت را به تو عطا می‌کند، تا موهبت خود تو.

خداوند* حقیقتاً قدرت تو است، و آنچه او* عطا می‌کند حقیقتاً داده می‌شود. این یعنی تو می‌توانی موهبت خداوند* را هر زمان و در هر مکان دریافت کنی، هرجا که هستی، و در هر شرایطی که خود را می‌یابی. گذر تو در زمان و مکان، تصادفی نیست. تو نمی‌توانی جز در مکان درست در زمان درست باشی. قدرت خداوند* چنین است. موهبت‌های او* چنین هستند.

امروز ما دو برنامه‌ی تمرین سه تا پنج دقیقه‌ای خواهیم داشت. یکی پس از بیدار شدن به محض این که ممکن باشد، و دیگری تا حد ممکن نزدیک به زمان خوابیدن تو. اما بهتر است تا وقتی که بتوانی در سکوت و تنهایی بنشینی صبر کنی، تا زمانی که بیشتر احساس می‌کنی آماده هستی و کمتر نگران زمان هستی.

این برنامه‌های تمرین را با تکرار کردن ایده‌ی امروز به آرامی آغاز کن، با چشمان باز، در حالی که به پیرامونت نگاه می‌کنی. سپس چشمان خود را ببند و ایده را دوباره تکرار کن، بسیار آرام‌تر از پیش. سپس تلاش کن به هیچ چیز جز افکاری که در ارتباط با ایده‌ی امروز به ذهنت می‌رسد نیندیشی. مثلاً ممکن است چنین بیندیشی: رؤیت باید ممکن باشد. خداوند* حقیقتاً آن را عطا می‌کند، یا: موهبت‌های خداوند* برای من باید از آن من باشند، زیرا او* آن‌ها را به من عطا کرده است.

هر فکر که ارتباط آشکاری با ایده‌ی امروز داشته باشد، مناسب است. در واقع تو ممکن است از حجم ادراک مربوط به این دوره در محتوای برخی از اندیشه‌هایت شگفت‌زده شوی. اجازه بده اندیشه‌ها بدون ویرایش عمدی برایت پیش بیایند، مگر متوجه شوی که ذهنت صرفاً در حال سرگردانی است و تو اجازه داده‌ای تا اندیشه‌هایی آشکارا نامربوط وارد ذهن شوند. همچنین ممکن است به نقطه‌ای برسی که به نظر برسد اصلاً هیچ فکری به ذهنت نمی‌رسد. اگر چنین تداخلی پیش آمد، چشمانت را بگشای و ایده را یک بار دیگر تکرار کن در حالی که آرام به پیرامون نگاه می‌کنی؛ چشمانت را ببند، ایده را دوباره تکرار کن، و سپس به جستجوی اندیشه‌های مربوط در ذهنت ادامه بده.

اما به یاد داشته باش که در تمرینات امروز از تو خواسته نمی‌شود به جستجوی فعال برای اندیشه‌های مربوط بپردازی. سعی کن صرفاً عقب بکشی و اجازه دهی تا اندیشه‌ها به ذهنت بیایند. اگر این برای تو دشوار است، ترجیحاً در برنامه‌های تمرین، تکرارهای آرام ایده با چشمان باز و سپس با چشمان بسته را به تناوب انجام بده. این بهتر از فشار آوردن به خود برای یافتن اندیشه‌های مناسب است.

امروز محدودیتی برای تعدد برنامه‌های تمرین کوتاه مدت مفید وجود ندارد. ایده‌ی امروز یک گام آغازین در گردآوری کردن اندیشه‌ها است، و آموختن این مطلب به تو که در حال فراگیری یک سیستم فکری یکپارچه هستی، سیستمی که دارای همه‌ی چیزهای مورد نیاز هست، و هیچ چیز متضاد یا بی‌ربطی در آن نیست.

هرچه به دفعات بیشتر این ایده را در طول روز تکرار کنی، به دفعات بیشتر به خود یادآور می‌شوی که هدف این دوره برای تو مهم است، و این که هدف را فراموش نکرده‌ای.', 'https://acim-farsi.org/workbook/lesson/42', 'https://acim-farsi.org/audio/workbook/lesson/42.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (43, 'خداوند* سرچشمهٔ* من است. من نمی‌توانم جدا از او ببینم.', 'تمرین کوتاه‌تر:

خداوند* سرچشمۀ* من است. من نمی‌توانم این را جدا از او ببینم.

تمرین طولانی‌تر:

خداوند* سرچشمهٔ* من است. من نمی‌توانم جدا از او ببینم.
خداوند* سرچشمۀ* من است. من نمی توانم این میز را جدا از او* ببینم.
خداوند سرچشمۀ* من است. من نمی توانم آن تصویر را جدا از او* ببینم.
خداوند* سرچشمهٔ* من است. من نمی‌توانم جدا از او ببینم.

من از درون چشمان بخشایش می‌بینم.
من این دنیا را متبرک می‌بینم.
این دنیا می‌تواند خودم را به من نشان دهد.
من اندیشه‌های خودم را می‌بینم، که مانند اندیشه‌های خداوند* هستند.', 'خداوند* سرچشمهٔ* من است. من نمی‌توانم جدا از او ببینم.

ادراک، یک ویژگی منسوب به خداوند* نیست. قلمروی او*، قلمروی معرفت است. پس او* روح‌القدس* را به عنوان واسطۀ* بین ادراک و معرفت آفریده است. بدون این پیوند با خداوند*، ادراک ممکن بود برای همیشه در ذهن تو جای معرفت را بگیرد. با این پیوند با خداوند*، ادراک چنان تغییر می‌یابد و خالص می‌شود که به معرفت رهنمون خواهد شد. این عملکردِ ادراک است، آنگونه که روح‌القدس* می‌بیند. پس در حقیقت وظیفه‌ی ادراک همین رهنمون شدن به معرفت است.

در خداوند* تو نمی‌توانی ببینی. ادراک هیچ عملکردی در خداوند* ندارد، و موجودیت ندارد. اما در رستگاری، که فروپاشیِ همه‌ی آن چیزی است که هرگز وجود نداشته است، ادراک دارای قصدی قدرتمند است. ادراک که توسط فرزند* خداوند* برای قصدی غیرقدسی ساخته شده، باید به وسیله‌ای برای بازگرداندن قداستش به آگاهی او تبدیل گردد. ادراک هیچ معنایی ندارد. اما روح‌القدس* معنایی را به آن عطا می‌کند که بسیار نزدیک به معنای اعطایی خداوند* است. ادراکِ شفا یافته به وسیله‌ای تبدیل می‌شود که توسط آن فرزند* خداوند* برادرش را می‌بخشد، و بدین‌سان خودش را می‌بخشد.

تو نمی‌توانی جدا از خداوند* ببینی زیرا نمی‌توانی جدا از خداوند* باشی. هرچه انجام می‌دهی، در او* انجام می‌دهی، زیرا به هرچه می‌اندیشی، با ذهن* او* می‌اندیشی. گر رؤیت واقعی باشد، آنگاه تو نمی‌توانی جدا از خداوند* ببینی. و رؤیت تا آن حدی که در آن با قصد روح‌القدس* اشتراک دارد، واقعی است.

امروز سه تمرین پنج دقیقه‌ای لازم است، یکی تا حد ممکن در صبح زود و دیگری تا حد ممکن نزدیک‌تر به پایان روز. تمرین دیگر باید در آسوده‌ترین و مناسب‌ترین زمان که شرایط مناسب و آمادگی وجود دارد انجام شود. در آغاز این برنامه‌های تمرین، ایده‌ی امروز را با چشمان باز برای خودت تکرار کن. سپس برای زمان کوتاهی به اطراف خود نگاه بینداز، در حالی که ایده را به صورت اختصاصی با چیزهایی که می‌بینی تمرین می‌کنی. چهار یا پنج سوژه برای این مرحله از برنامه‌ی تمرین کفایت می کند. مثلاً می‌توانی بگویی: خداوند* سرچشمۀ* من است. من نمی توانم این میز را جدا از او* ببینم. خداوند سرچشمۀ* من است. من نمی توانم آن تصویر را جدا از او* ببینم.

اگرچه این بخش از برنامه‌ی تمرین باید نسبتاً کوتاه باشد، مطمئن شو که سوژه‌ها را برای این مرحله از تمرین، بدون تمایز انتخاب می‌کنی، بدون حذف یا اضافه کردن سوگیرانه. برای مرحله‌ی طولانی‌تر دوم، چشمانت را ببند، ایده‌ی امروز را دوباره تکرار کن، و سپس اجازه بده هر اندیشه‌ی مربوطی که به ذهنت می‌رسد، با شیوه‌ی شخصی تو به این ایده اضافه شود. اندیشه‌هایی مانند: من از درون چشمان بخشایش می‌بینم. من این دنیا را متبرک می‌بینم. این دنیا می‌تواند خودم را به من نشان دهد. من اندیشه‌های خودم را می‌بینم، که مانند اندیشه‌های خداوند* هستند. هر اندیشه‌ای که کمابیش مستقیماً با ایده‌ی امروز مربوط باشد، مناسب است. نیازی نیست که اندیشه‌ها ارتباط آشکاری با این ایده داشته باشند، اما نباید در مخالفت با آن باشند.

اگر متوجه شدی که ذهنت سرگردان است؛ اگر آغاز کردی به آگاه شدن از اندیشه‌هایی که آشکارا فارغ از همراهی با ایده امروز هستند، یا به نظرت رسید که توانایی فکر کردن به هیچ چیز را نداری، چشمانت را باز کن، مرحله‌ی اول برنامه‌ی تمرین را تکرار کن، و سپس دوباره برای مرحله دوم تلاش کن. اجازه نده فاصله‌ی طولانی ایجاد شود که در آن با افکار نامربوط مشغول شوی. جهت پیشگیری از این موضوع، هر چند بار که لازم باشد به مرحله‌ی اول تمرینات برگرد.

برای تمرین با ایده‌ی امروز در برنامه‌های کوتاه‌تر، شکل تمرین می‌تواند بر حسب موقعیت‌ها و شرایطی که در طول روز برای تو پیش می‌آیند، تغییر کند. مثلاً وقتی با شخص دیگری همراه هستی، سعی کن به یاد داشته باشی که در سکوت به او بگویی: خداوند* سرچشمۀ* من است. من نمی‌توانم تو را جدا از او* ببینم. این شکل از تمرین با غریبه‌ها هم به اندازه کسانی که می‌پنداری به تو نزدیک‌تر هستند، کاربرد دارد. درواقع، سعی کن چنین نوع تمایزی را اصلاً به کار نبری.

ایده‌ی امروز را همچنین باید در طول روز با شرایط و رویدادهای مختلفی که ممکن است بروز کنند، تمرین کنی. خصوصاً با شرایط و رویدادهایی که به نظر می‌رسد تو را به هر شکلی آشفته می‌کنند. برای این منظور، با این شکل از ایده تمرین کن: خداوند* سرچشمۀ* من است. من نمی‌توانم این را جدا از او ببینم.

اگر زمانی هیچ مورد خاصی در آگاهی تو خود را نشان نداد، صرفا ایده امروز را در شکل اصلی آن تکرار کن. تلاش کن که اجازه ندهی مدت زمانی طولانی بدون به یاد داشتن ایده امروز و در نتیجه به یاد داشتن وظیفه‌ات، سپری شود.', 'https://acim-farsi.org/workbook/lesson/43', 'https://acim-farsi.org/audio/workbook/lesson/43.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (44, 'خداوند* آن نور است که من در آن می‌بینم.', 'خداوند* آن نور است که من در آن می‌بینم.', 'خداوند* آن نور است که من در آن می‌بینم.

ما امروز ایده‌ی دیروز را ادامه می‌دهیم، با اضافه کردن یک بُعد دیگر به آن. تو نمی‌توانی در تاریکی ببینی، و نمی‌توانی نور را بسازی. می‌توانی تاریکی بسازی و سپس فکر کنی که در آن می‌بینی. اما نور، زندگی را بازتاب می‌دهد و از این رو جنبه‌ای از آفرینش است. آفرینش و تاریکی نمی‌توانند همزیستی کنند، اما نور و زندگی باید باهم باشند، در حالی که فقط جنبه‌های متفاوتی از آفرینش هستند.

برای دیدن، باید تشخیص دهی که نور در درون است، نه بیرون. تو بیرون از خودت را نمی‌بینی، و نیز افزار برای دیدن، بیرون از تو نیست. بخشی اساسی از این افزار، نور است که دیدن را میسر می‌کند. نور همیشه با تو است، و در هر شرایطی رؤیت را ممکن می‌سازد.

امروز ما تلاش خواهیم کرد تا به آن نور دست یابیم. برای این منظور، شکلی از تمرین را مورد استفاده قرار خواهیم داد که قبلاً مطرح شده است، و در ادامه‌ی دوره بیشتر از آن استفاده می‌کنیم. این شکل خصوصاً برای ذهن غیرمنضبط دشوار است، و هدف عمده‌ای را در تربیت ذهن نشان می‌دهد. این شکل تمرین دقیقاً به چیزی نیاز دارد که ذهن تربیت نشده فاقد آن است. اما اگر می‌خواهی ببینی، باید این تربیت به انجام برسد.

امروز حداقل سه برنامه‌ی تمرین داشته باش، هریک به مدت سه تا پنج دقیقه. قویاً توصیه می‌کنیم که زمان بیشتری صرف کنی، اما فقط در صورتی که زمان با احساس کمترین فشار یا بدون احساس فشار برایت سپری می‌شود. امروز شکل تمرین مورد استفاده‌ی ما، طبیعی‌ترین و آسان‌ترین شکل موجود در دنیا برای ذهن تربیت شده است. درست به همان اندازه که این شکل تمرین برای ذهن تربیت نشده، غیرطبیعی‌ترین و سخت‌ترین شکل به نظر می‌رسد.

دیگر ذهن تو یک ذهن کاملاً تربیت نشده نیست. تو برای آموختن این شکل از تمرین که ما امروز استفاده می‌کنیم، به خوبی آماده هستی، اما ممکن است متوجه شوی که با مقاومتی شدید روبرو خواهی شد. دلیل آن بسیار ساده است. در حالی که به این شیوه تمرین می‌کنی، همه‌ی چیزهایی را که اینک باور داری و همه پندارهایی را که ساخته‌ای، پشت سر می‌گذاری. به بیان کامل، این رهایی از جهنم است. اما با ادراک از طریق چشمان نفس، این از دست دادن هویت و سقوط به داخل جهنم محسوب می‌شود.

اگر بتوانی حتی اندکی از نفس کناره بگیری، هیچ دشواری در تشخیص این که مخالفت و ترس‌های آن بی‌معنا هستند نخواهی داشت. ممکن است برایت مفید باشد که گاه به گاه به خود یادآوری کنی که رسیدن به نور، نجات از تاریکی است، با وجود هر باور تو که مخالف این ایده باشد. خداوند* آن نور است که تو در آن می‌بینی. در تلاش هستی تا به او* برسی.

برنامه‌های تمرین را با تکرار کردن ایده‌ی امروز برای خودت با چشمان باز آغاز کن، و سپس آن‌ها را آرام ببند، در حالی که ایده را چندین بار دیگر تکرار می‌کنی. سپس سعی کن به درون ذهنت فرو بروی، و هرگونه تداخل و نفوذ افکار را با ساکت فرو رفتن بیشتر در ذهن، رها کنی. ذهن تو را نمی‌توان از این کار بازداشت، مگر اراده کنی آن را متوقف کنی. ذهن صرفاً مسیر طبیعی خود را می‌رود. سعی کن افکار گذرای خود را بدون درگیر شدن مشاهده کنی، و در سکوت از آن‌ها عبور کنی.

گرچه هیچ رویکرد خاصی را برای این شکل از تمرین توصیه نمی‌کنیم، آنچه ضروری می‌دانیم احساس اهمیت داشتن کاری است که در حال انجام آن هستی؛ ارزش غیر قابل تخمین آن برای تو، و این آگاهی که در تلاش برای انجام کاری بسیار قدسی هستی. رستگاری، شادترین دستاورد تو است. رستگاری همچنین تنها دستاوردی است که معنایی دارد، زیرا تنها دستاوردی است که اصلاً فایده‌ای واقعی برای تو دارد.

اگر مقاومت در هر شکلی برانگیخته شد، به اندازه‌ی کافی درنگ کن تا ایده‌ی امروز را تکرار کنی، در حالی که چشمانت را بسته‌ای، مگر دچار ترس شوی. در این شرایط، شاید برایت اطمینان‌بخش‌تر باشد که چشمانت را برای مدت کوتاهی بگشایی. اما سعی کن هرچه زودتر به تمرین با چشمان بسته بازگردی.

اگر صحیح تمرین کنی، باید احساسی از آرامش را تجربه کنی، و حتی احساسی از این که در حال دستیابی به نور هستی، حتی اگر عملاً به آن وارد نشوی. سعی کن به نور بیندیشی، بی‌شکل و بدون محدودیت، در حالی که از افکار این دنیا عبور می‌کنی. و از یاد نبر که این افکار نمی‌توانند تو را بسته به این دنیا نگه دارند، مگر تو قدرت انجام این کار را به آن‌ها بدهی.

در طول روز این ایده را به دفعات تکرار کن، با چشمان باز یا بسته، هر یک که در آن زمان مناسب به نظر آید. اما از یاد نبر. بالاتر از هر چیز، امروز متعهد شو که از یاد نبری.', 'https://acim-farsi.org/workbook/lesson/44', 'https://acim-farsi.org/audio/workbook/lesson/44.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (45, 'خداوند* آن ذهن* است که من با آن می‌اندیشم.', 'خداوند* آن ذهن* است که من با آن می‌اندیشم.

اندیشه‌های واقعی من در ذهنم هستند. من می‌خواهم آن‌ها را بیابم.', 'خداوند* آن ذهن* است که من با آن می‌اندیشم.

ایده‌ی امروز کلید این را در خود دارد که اندیشه‌های واقعی تو چه هستند. آن‌ها اصلاً چیزی نیستند که تو می‌پنداری می‌اندیشی، دقیقاً همانطور که هیچ چیزی که می‌پنداری می‌بینی، به هیچ وجه ربطی به رؤیت ندارد. هیچ ارتباطی بین آنچه واقعی است و آنچه تو می‌پنداری واقعی است وجود ندارد. هیچ یک از چیزهایی که تو می‌پنداری اندیشه‌های واقعی تو هستند، از هیچ جنبه‌ای با اندیشه‌های واقعی تو همانند نیستند. هیچ‌یک از چیزهایی که تو می‌پنداری می‌بینی، هیچ تشابهی با آنچه رؤیت به تو نشان خواهد داد، ندارد.

تو با ذهن* خداوند* می‌اندیشی. بنابراین اندیشه‌های خود را با او* سهیم هستی، همانطور که او* اندیشه‌هایش* را با تو سهیم است. آن‌ها اندیشه‌هایی یکسان هستند، زیرا توسط ذهن* یکسانی اندیشیده می‌شوند. سهیم شدن یعنی مشابه کردن، یا یکی کردن. آن افکار که تو با ذهن* خداوند* می‌اندیشی، ذهنت را ترک نمی‌کنند، زیرا اندیشه‌ها سرچشمۀ خود را ترک نمی‌کنند. از این رو، اندیشه‌های تو در ذهن متعال خداوند هستند، همانطور که تو هستی. آن‌ها در ذهن تو نیز هستند، جایی که او* هست. همانطور که تو بخشی از ذهن* او* هستی، اندیشه‌های تو نیز بخشی از ذهن* او* هستند.

پس اندیشه‌های واقعی تو کجا هستند؟ امروز تلاش خواهیم کرد تا به آن‌ها برسیم. ما ناچار خواهیم بود که آن‌ها را در ذهن تو جستجو کنیم، زیرا آنجا هستند. باید هنوز آنجا باشند، زیرا نمی‌توانند سرچشمۀ خود را ترک کرده باشند. آنچه توسط ذهن* خداوند* اندیشیده می‌شود ابدی است، بخشی از آفرینش است.

سه تمرین پنج دقیقه‌ای امروز ما همان شکل کلی را خواهند داشت که در تمرین با ایده‌ی دیروز استفاده کردیم. تلاش خواهیم کرد غیرواقعی را رها کنیم و واقعی را بجوییم. ما این دنیا را به طرفداری از حقیقت، تکذیب می‌کنیم. به پندارهای این دنیا اجازه نخواهیم داد تا ما را عقب نگه دارند. به باورهای این دنیا اجازه نخواهیم داد تا به ما بگویند آنچه خداوند می‌خواهد که ما انجام دهیم، ناممکن است. به جای آن، ما سعی می‌کنیم تشخیص دهیم که فقط آنچه خداوند* می‌خواهد که ما انجام دهیم، ممکن است.

همچنین سعی می‌کنیم بفهمیم فقط آنچه خداوند* می‌خواهد که ما انجام دهیم، چیزی است که ما انجامش را می‌خواهیم. و ما همچنین تلاش خواهیم کرد به یاد بیاوریم که قطعاً در انجام آنچه او می‌خواهد، شکست نمی‌خوریم. همه‌ی دلایل موجود به ما اطمینان می‌دهند که امروز موفق خواهیم شد. این ارادۀ* خداوند* است.

تمرینات امروز را با تکرار ایده برای خودت آغاز کن، در حالی که چشمانت را می‌بندی. سپس زمان کوتاهی را صرف اندیشیدن به چند فکر مرتبطی کن که از خود تو است، و در این زمان ایده را در ذهن نگه دار. پس از اضافه کردن چهار یا پنج اندیشه از خودت به ایده‌ی امروز، آن را دوباره تکرار کن و با ملایمت به خودت بگو: اندیشه‌های واقعی من در ذهنم هستند. من می‌خواهم آن‌ها را بیابم. سپس سعی کن از همه‌ی پندارهای غیرواقعی که در ذهنت حقیقت را می‌پوشانند عبور کنی و به سوی آنچه جاوید است بروی.

در زیر همه‌ی اندیشه‌های بی‌معنا و ایده‌های دیوانه‌وار که تو ذهن خود را با آن‌ها شلوغ کرده‌ای، اندیشه‌هایی هستند که در آغاز همراه با خداوند* اندیشیده‌ای. آن‌ها اکنون در ذهنت وجود دارند، کاملاً بدون تغییر. آن‌ها همیشه در ذهنت خواهند بود، دقیقاً همانگونه که همیشه بودند. هر چیزی که تو از آن زمان به بعد اندیشیده‌ای، تغییر خواهد کرد، اما آن بنیان* که اندیشه بر آن استوار است، کاملاً بی‌تغییر است.

جهت‌گیری تمرینات امروز به سوی همین بنیان* است. در اینجا ذهن تو با ذهن* خداوند* پیوند می‌خورد. در اینجا اندیشه‌های تو با اندیشه‌های* او* یکی می‌شود. برای این نوع تمرین تنها یک چیز ضروری است؛ چنان به آن نزدیک شو که گویی به محرابی نزدیک می‌شوی که در ملکوت* به خداوند* پدر* و به خداوند* فرزند* اختصاص داده شده است. زیرا در تلاش هستی به چنین مکانی برسی. شاید هنوز توان تشخیص این را نداشته‌ای که سعی داری چقدر بالا بروی. اما حتی با درک اندکی که تا حال پیدا کرده‌ای، باید بتوانی به خود یادآوری کنی که این یک بازی پوچ نیست، بلکه تمرین قداست است و کوششی برای دستیابی به قلمروی* ملکوت*.

در تمرینات کوتاه‌تر امروز، سعی کن به یاد داشته باشی چقدر برایت مهم است که قداست آن ذهن را که همراه با خداوند* می‌اندیشد، درک کنی. در طول روز در زمان‌های یک تا دو دقیقه‌ای ایده‌ی امروز را تکرار کن، تا قداست ذهنت را بپذیری. از همۀ پندارهایی که برای او* که تو میزبان وی* هستی ناشایسته هستند، ولو برای مدت کوتاه، کنار بکش. و از او* بابت آن اندیشه‌ها* که او* با تو می‌اندیشد سپاسگزاری کن.', 'https://acim-farsi.org/workbook/lesson/45', 'https://acim-farsi.org/audio/workbook/lesson/45.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (46, 'خداوند* آن عشق* است که من در آن می‌بخشم.', 'تمرین کوتاه‌تر:

خداوند* آن عشق* است که من در آن می‌بخشم.
خداوند* آن عشق* است که من در آن تو را می‌بخشم.

تمرین طولانی‌تر:

خداوند* آن عشق* است که من در آن تو را می‌بخشم، [نام].
خداوند* آن عشق* است که من در آن خودم را می‌بخشم.', 'خداوند* آن عشق* است که من در آن می‌بخشم.

خداوند* نمی‌بخشد زیرا او* هرگز محکوم نکرده است. و پیش از نیاز به بخشایش باید محکومیت وجود داشته باشد. بخشایش نیاز بزرگ این دنیا است، اما تنها به این دلیل که این یک دنیای اوهام است. کسانی که می‌بخشند به این ترتیب خود را از اوهام رها می‌کنند، در حالی که کسانی که از بخشایش سر باز می‌زنند، خود را به آن‌ها پایبند می‌کنند. همان‌گونه که تو تنها خودت را محکوم می‌کنی، همان‌گونه نیز تنها خودت را می‌بخشی.

اما گرچه خداوند* نمی‌بخشد، باز عشق* او* بنیان بخشایش است. ترس محکوم می‌کند و عشق می‌بخشاید. بدین ترتیب بخشایش آنچه را که ترس تولید کرده خنثی می‌کند، و ذهن را به آگاهی از خداوند* بازمی‌گرداند. به همین دلیل، می‌توان بخشایش را حقیقتاً رستگاری خواند. این وسیله‌ای است که اوهام توسط آن ناپدید می‌شوند.

تمرین درس امروز مستلزم دست کم سه برنامه‌ی تمرین با زمان پنج دقیقه‌ی کامل است، و به هر تعداد ممکن تمرینات کوتاه‌تر. طبق معمول برنامه‌های تمرین طولانی‌تر را با تکرار ایده‌ی امروز برای خود آغاز کن. در حالی که چنین می‌کنی چشمانت را ببند، و یک یا دو دقیقه را صرف جستجوی ذهنت برای کسانی کن که نبخشیده‌ای. مهم نیست که «چقدر» آنان را نبخشیده‌ای. تو یا آن‌ها را کاملاً بخشیده‌ای، یا اصلاً نبخشیده‌ای.

اگر تمرین را به خوبی انجام دهی، باید در یافتن تعدادی از افراد که نبخشیده‌ای مشکل نداشته باشی. یک قاعدهٔ ساده این که هر کسی که تو دوستش نداری، یک سوژهٔ مناسب است. هریک را با نام به ذهن بیاور، و بگو: خداوند* آن عشق* است که من در آن تو را می‌بخشم، [نام].

قصد مرحله‌ی اول برنامه‌های تمرین امروز، گذاشتن تو در وضعیتی است که خودت را ببخشی. پس از تمرین کردن ایده با همه‌ی آنان که به ذهنت می‌آیند، به خودت بگو: خداوند* آن عشق* است که من در آن خودم را می‌بخشم. سپس بقیه‌ی برنامه‌ی تمرین را صرف اضافه کردن ایده‌های مرتبط کن، مانند: خداوند* آن عشق* است که من با آن به خودم عشق می‌ورزم. خداوند* آن عشق* است که من در آن متبرک می‌شوم.

شکل تمرین کردن می‌تواند تغییرات قابل توجهی پیدا کند، اما ایده‌ی مرکزی نباید از نظر دور شود. مثلاً ممکن است بگویی: من نمی‌توانم گناهکار باشم زیرا فرزند* خداوند* هستم. من پیشاپیش بخشوده هستم. در ذهنی که محبوب خداوند* است، هیچ ترسی ممکن نیست. نیازی به حمله وجود ندارد زیرا عشق مرا بخشیده است. اما برنامه‌ی تمرین را باید با تکرار ایده‌ی امروز در شکل اصلی آن پایان دهی.

برنامه‌های تمرین کوتاه‌تر می‌توانند شامل تکرار ایده‌ی روز در شکل اصلی یا در شکل تغییر یافته باشند، آنگونه که تو ترجیح می‌دهی. اما مطمئن شو که تمرینات اختصاصی‌تر را در صورت لزوم انجام می‌دهی. این تمرینات هر زمان در طول روز که تو از هرگونه واکنش منفی در برابر هر کسی آگاه می‌شوی، چه حاضر و چه غایب مورد نیاز خواهند بود. در این شرایط، در سکوت به او بگو: خداوند* آن عشق* است که من در آن تو را می‌بخشم.', 'https://acim-farsi.org/workbook/lesson/46', 'https://acim-farsi.org/audio/workbook/lesson/46.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (47, 'خداوند* آن قدرت است که من به آن اعتماد می‌کنم.', 'خداوند* آن قدرت است که من به آن اعتماد می‌کنم.', 'خداوند* آن قدرت است که من به آن اعتماد می‌کنم.

اگر به قدرت خودت اعتماد کنی، همه‌ی دلایل را برای نگرانی، اضطراب و هراس داری. تو چه چیز را می‌توانی پیش‌بینی یا کنترل کنی؟ چه چیزی در تو وجود دارد که بتوان روی آن حساب کرد؟ چه چیزی این توانایی را به تو می‌دهد که بتوانی از همه‌ی جنبه‌های یک مسئله آگاه باشی، و مسائل را به چنان روشی حل کنی که فقط ختم به خیر شوند؟ چه چیزی در تو وجود دارد که توانایی تشخیص راه حل درست را به تو می‌دهد، و توفیق در آن را تضمین می‌کند؟

تو نمی‌توانی هیچ‌یک از این کارها را از خودت انجام دهی. باور داشتن به این که تو می‌توانی، گذاشتن اعتماد خود در جایی است که اعتماد تضمین نشده است و موجه دانستن ترس، اضطراب، افسردگی، خشم و اندوه است. چه کسی می‌تواند ایمان خود را در ضعف قرار دهد و احساس امنیت کند؟ ,ولی باز چه کسی می‌تواند ایمان خود را در قدرت قرار دهد و احساس ضعف کند؟

خداوند* در هر شرایطی امنیت تو است. آوای* او* از سوی او* سخن می‌گوید، در هر موقعیت و در همه‌ی جنبه‌های هر موقعیت، و به ما می‌گوید که دقیقاً چه کنیم تا توان و حفاظت متعالش را فرابخوانیم. هیچ استثنایی وجود ندارد زیرا خداوند* هیچ استثنایی قایل نمی‌شود. و آن آوا* که برای او* سخن می‌گوید، همچون او* می‌اندیشد.

امروز ما سعی خواهیم کرد تا از ضعف‌های خود عبور کرده به سوی سرچشمۀ* قدرت واقعی برویم. امروز چهار برنامه‌ی تمرین پنج‌دقیقه‌ای ضروری است، و توصیه می‌کنیم تمرینات طولانی‌تر و به تعداد بیشتر انجام دهی. چشمانت را ببند و طبق معمول با تکرار کردن ایده‌ی امروز آغاز کن. سپس یک یا دو دقیقه را برای جستجوی موقعیت‌هایی در زندگی‌ات که ترس تو را فراگرفته است صرف کن، و هریک از این موقعیت‌ها را با گفتن جمله‌ی زیر به خودت رها کن: خداوند* آن قدرت است که من به آن اعتماد می‌کنم.

سپس سعی کن تا از همه‌ی نگرانی‌های مرتبط با احساس بی‌کفایتی خود عبور کنی. آشکار است که هر موقعیتی که موجب نگرانی تو می‌شود با احساس بی‌کفایتی همراه است، زیرا در غیر این صورت باور می‌کردی که می‌توانی با شرایط برخورد پیروزمند داشته باشی. تو با اعتماد کردن به خودت اعتماد به خویشتن را به دست نخواهی آورد. اما قدرت خداوند* در تو، در همه‌ی کارها پیروز است.

تشخیص شکنندگی خودت گامی ضروری در تصحیح خطاهای تو است، اما برای دادن اعتماد به خویشتنِ مورد نیاز تو کفایت نمی‌کند، اعتمادی که برای تو مقرر شده است. باید این هشیاری را نیز به دست آوری که اعتماد به قدرت واقعی تو در هر زمینه و در همه‌ی شرایط کاملاً موجه است.

در مرحله‌ی پایانی برنامه‌ی تمرین، سعی کن به ژرفای درون ذهنت بروی، به مکانی از امنیت واقعی. زمانی که احساس آرامش عمیق داشته باشی، ولو به مدت کوتاه، تشخیص خواهی داد که به آنجا رسیده‌ای. همه‌ی چیزهای بی‌ارزشی را که بر سطح ذهنت موج می‌زنند و کف می‌کنند را رها کن، و ژرف‌تر از آن‌ها به قلمروی* ملکوت* برس. مکانی در تو وجود دارد که در آنجا صلحِ کامل نهفته است. مکانی در تو وجود دارد که در آنجا هیچ چیز ناممکن نیست. مکانی در تو وجود دارد که در آنجا قدرت خداوند* سکونت دارد.

در طول روز، ایده را به دفعات تکرار کن. از آن به عنوان پاسخ خود به هر آشفتگی استفاده کن. به یاد داشته باش که صلح حق تو است، زیرا اعتماد خود را به قدرت خداوند* می‌سپاری.', 'https://acim-farsi.org/workbook/lesson/47', 'https://acim-farsi.org/audio/workbook/lesson/47.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (48, 'هیچ چیز برای ترسیدن وجود ندارد.', 'هیچ چیز برای ترسیدن وجود ندارد.', 'هیچ چیز برای ترسیدن وجود ندارد.

ایده‌ی امروز یک واقعیت ساده را بیان می‌کند. برای آنان که اوهام را باور دارند، این یک واقعیت نیست، اما اوهام، واقعیت نیستند. در حقیقت هیچ چیز برای ترسیدن وجود ندارد. تشخیص این بسیار آسان است. اما این تشخیص برای آنان که می‌خواهند اوهام حقیقت داشته باشند، بسیار دشوار است.

تمرینات امروز بسیار کوتاه ، بسیار ساده و بسیار متعدد هستند. صرفاً ایده را به دفعات ممکن تکرار کن. می‌توانی از آن با چشمان باز در هر زمان و هر موقعیتی استفاده کنی. اما قویاً توصیه می‌کنیم که هر زمان ممکن باشد، حدود یک دقیقه چشمانت را ببندی و به آرامی چند مرتبه ایده را برای خودت تکرار کنی. خصوصاً مهم است که هر زمان چیزی صلح ذهنت را آشفته کرد، بلافاصله از این ایده استفاده کنی.

حضور ترس، نشانه‌ای دقیق از این است که تو در حال اعتماد کردن به قدرت خودت هستی. این آگاهی که هیچ چیز برای ترس وجود ندارد نشان می‌دهد که جایی در ذهنت، اگرچه شاید الزاماً مکانی نباشد که تا حال می‌شناختی، تو خداوند* را به یاد داری، و اجازه می‌دهی تا قدرت او* جای ضعف تو را بگیرد. لحظه‌ای که تو این را اراده کنی، حقیقتاً هیچ چیز برای ترسیدن وجود ندارد.', 'https://acim-farsi.org/workbook/lesson/48', 'https://acim-farsi.org/audio/workbook/lesson/48.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (49, 'آوای* خداوند* در تمام روز با من سخن می‌گوید.', 'آوای* خداوند* در تمام روز با من سخن می‌گوید.', 'آوای* خداوند* در تمام روز با من سخن می‌گوید.

کاملاً ممکن است که بتوانی به آوای* خداوند* در تمام طول روز بدون هیچگونه تداخل در فعالیت‌های معمول خود گوش فرادهی. آن بخش از ذهنت که حقیقت در آنجا ساکن است، در ارتباط دائم با خداوند* است، چه از آن آگاه باشی و چه نباشی. بخش دیگر ذهن تو در این دنیا عمل می‌کند و از قوانین این دنیا اطاعت می‌کند. این بخش است که مدام پراکنده، نابسامان و بشدت نامطمئن است.

آن بخش که به آوای* برای خداوند* گوش فرا می‌دهد آرام است، همواره در آسایش و کاملاً مطمئن. این واقعاً تنها بخشی است که وجود دارد. آن بخش دیگر یک وهم آشفته است، ناآرام و پریشان، اما بدون هر نوع واقعیت. امروز سعی کن به آن گوش فرا ندهی. سعی کن با آن بخش از ذهنت آشنا شوی که در آنجا سکون و صلح برای همیشه حکمفرمایی می‌کند. سعی کن آوای* خداوند* را بشنوی که عاشقانه تو را می‌خواند، و به یادت می‌آورد که آفریدگار* تو فرزندش* را فراموش نکرده است.

امروز حداقل به چهار برنامه‌ی تمرین پنج دقیقه‌ای و در صورت امکان بیش از این نیاز خواهیم داشت. عملاً تلاش خواهیم کرد تا آوای* خداوند* را بشنویم، آوایی* که او* و خویشتن* تو را به یادت می‌آورد. ما با اطمینان به این شادترین و قدسی‌ترین اندیشه دست خواهیم یافت، با دانستن این که در انجام این کار ارادهٔ خود را به ارادهٔ* خداوند* پیوند می‌زنیم. او* از تو می‌خواهد آوایش* را بشنوی. او* این آوا* را برای این که بشنوی به تو عطا کرده است.

در سکوت ژرف گوش فرابده. بسیار ساکن بمان و ذهنت را بگشای. از همه‌ی فریادهای گوشخراش و تصورهای بیمارگونه که اندیشه‌های واقعی تو را می‌پوشانند و پیوند ابدی تو با خداوند* را پنهان می‌کنند، عبور کن. عمیقاً به درون آن صلح فرو برو که فراتر از پندارها و تصاویر و صداهای برآشفته و آشوبگرانه‌ی این دنیای دیوانه‌وار، انتظارت را می‌کشد. تو اینجا زندگی نمی‌کنی. ما در تلاش برای رسیدن به منزل واقعی تو هستیم‌. ما در تلاش برای رسیدن به آن مکانی هستیم که آنجا حقیقتاً از تو استقبال می‌شود. ما در تلاش برای رسیدن به خداوند* هستیم.

از یاد نبر که ایده‌ی امروز را به دفعات بسیار زیاد تکرار کنی. در صورت لزوم این کار را با چشمان باز انجام بده، اما هر زمان ممکن باشد با چشم بسته تمرین کن. و مطمئن شو هر زمان که می‌توانی ساکت می‌نشینی و ایده‌ی امروز را تکرار می‌کنی، چشمانت را به روی این دنیا می‌بندی، و تصدیق می‌کنی که در حال دعوت کردن آوای* خداوند* هستی تا با تو سخن بگوید.', 'https://acim-farsi.org/workbook/lesson/49', 'https://acim-farsi.org/audio/workbook/lesson/49.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (50, 'من توسط عشق* خداوند* نگهداری می‌شوم.', 'من توسط عشق* خداوند* نگهداری می‌شوم.', 'من توسط عشق* خداوند* نگهداری می‌شوم.

این پاسخی است به هر مشکلی که با آن روبرو می‌شوی، امروز و فردا و در طول زمان. در این دنیا، تو باور می‌کنی که توسط هر چیزی جز خداوند* نگهداری می‌شوی. به ناچیزترین و بیخردانه‌ترین نمادها ایمان داری: قرص، پول، لباسِ «محافظ»، تاثیرگذاری بر دیگران، شأن، محبوب بودن، شناختن آدم‌هایِ «درست» و فهرستی بی‌پایان از صورت‌های ناموجود، که تو به آن‌ها قدرت‌های جادویی اعطا می‌کنی.

همه‌ی این چیزها، جایگزین‌های تو برای عشق* خداوند* هستند. تمام این‌ها برای تضمین یکی دانستن تو با بدنت پرورده می‌شوند. این‌ها نغمه‌های ستایش نفس هستند. به چیزهای بی‌ارزش ایمان نداشته باش. چیزهای بی‌ارزش از تو نگهداری نمی‌کنند.

تنها عشق* خداوند* در همهٔ شرایط از تو محافظت خواهد کرد. آن تو را از هر آزمونی بیرون خواهد کشید، و تو را بر فراز تمام خطرهای ادراک شدهٔ این دنیا، به درون اقلیمی از صلح و امنیت کامل خواهد برد. تو را به درون یک وضعیت ذهنی منتقل خواهد کرد که هیچ چیز نمی‌تواند تهدید کند، هیچ چیز نمی‌تواند آزار دهد، و جایی که هیچ چیز نمی‌تواند مزاحم آرامش ابدی فرزند* خداوند* شود.

به اوهام ایمان نداشته باش. آن‌ها تو را ناکام می‌کنند. همه‌ی ایمان خود را به عشق* خداوند* در درونت بده؛ جاوید، بدون تغییر و همیشه شکست‌ناپذیر. امروز، این پاسخ هر چیزی خواهد بود که با تو رویارو می‌شود. از طریق عشق* خداوند* در درونت، می‌توانی همه‌ی مشکلاتی را که به نظرت می‌رسد، بدون تلاش و با اطمینان کامل حل کنی. امروز این را به دفعات زیاد به خودت بگو. این بیانیه‌ی رهایی از باور داشتن به خدایان دروغین است. این تصدیق حقیقت در مورد تو توسط خودت است.

امروز در دو برنامه‌ی تمرین ده دقیقه‌ای صبح و عصر، اجازه بده ایده‌ی روز عمیقاً در خودآگاهی تو نفوذ کند. آن را تکرار کن، در موردش فکر کن، اجازه بده افکار مرتبط به ذهنت بیایند تا در تشخیص حقیقی بودن آن کمک کنند، و اجازه بده تا صلح مانند پوششی از محافظت و اطمینان برفراز تو جاری شود. اجازه‌ی ورود به پندارهای پوچ و احمقانه نده، تا ذهن مقدس فرزند* خداوند* را مختل نکنند. قلمروی* ملکوت* چنین است. چنین است آن مکان آسایش که پدرت* برای همیشه تو را در آن اسکان داده است.', 'https://acim-farsi.org/workbook/lesson/50', 'https://acim-farsi.org/audio/workbook/lesson/50.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (51, 'مرور (۱ تا ۵)', '(۱) هیچ چیزی که من می‌بینم هیچ معنایی ندارد.
(۲) من به آنچه می‌بینم همه‌ی معنایی را که برای من دارد داده‌ام.
(۳) من هیچ چیزی را که می‌بینم، درک نمی‌کنم.
(۴) این افکار هیچ معنایی ندارند.
(۵) من هرگز به آن دلیلی که فکر می‌کنم، آشفته نیستم.', 'مرور امروز ایده‌های زیر را در بر می‌گیرد:

(۱) هیچ چیزی که من می‌بینم هیچ معنایی ندارد. به این دلیل چنین است که من هیچ چیزی را نمی‌بینم، و هیچ چیز معنایی ندارد. ضروری است که من این را تشخیص بدهم، تا بتوانم دیدن را بیاموزم. آنچه می‌پندارم اکنون می‌بینم، جایگزین رؤیت می‌شود. من باید با تشخیص این که هیچ معنایی ندارد، آن را رها کنم تا رؤیت بتواند جایگزینش شود.

(۲) من به آنچه می‌بینم همه‌ی معنایی را که برای من دارد داده‌ام. من همه‌ی چیزهایی را که به چشمم می‌خورد قضاوت کرده‌ام، و من این و فقط همین را می‌بینم. این رؤیت نیست. این صرفاً وهمی از واقعیت است، زیرا قضاوت‌های من کاملاً جدا از واقعیت انجام شده‌اند. من اراده‌مندم تا فقدان اعتبار در قضاوتم را تشخیص دهم، زیرا می‌خواهم ببینم. قضاوت‌هایم مرا آزار داده‌اند، و من نمی‌خواهم برحسب آن‌ها ببینم.

(۳) من هیچ چیزی را که می‌بینم، درک نمی‌کنم. چگونه می‌توانم آنچه را که می‌بینم درک کنم، وقتی آن را به غلط قضاوت کرده‌ام؟ آنچه می‌بینم فرافکنی خطاهای فکری خودم است. من آنچه را که می‌بینم درک نمی‌کنم زیرا قابل درک نیست. تلاش برای درک آن هیچ مفهومی ندارد. اما همه‌ی دلایل وجود دارند که من آن را رها کنم، و جا را برای آنچه می‌توان دید و درک کرد و به آن عشق ورزید باز کنم. من می‌توانم آن را تنها با مایل بودن به انجام آن، جایگزین چیزی کنم که اکنون می‌بینم. آیا این انتخابی بهتر از آنچه قبلاً انجام داده‌ام نیست؟

(۴) این افکار هیچ معنایی ندارند. افکاری که من از آن‌ها آگاه هستم هیچ معنایی ندارند، زیرا من در تلاش هستم بدون خداوند بیندیشم. آنچه من اندیشه‌های «خودم» می‌خوانم، اندیشه‌های واقعی من نیستند. اندیشه‌های واقعی من همان اندیشه‌هایی هستند که با خداوند می‌اندیشم. من از آن‌ها آگاه نیستم زیرا پندارهایم را جایگزین آن‌ها کرده‌ام. من مایلم که تشخیص دهم که افکارم هیچ معنایی ندارند، و رهایشان کنم. من انتخاب می‌کنم که آن‌ها با آنچه که قرار بود جایش را بگیرند، جایگزین شوند. افکار من بی‌معنا هستند، اما همه‌ی آفرینش در اندیشه‌هایی حضور دارد که من با خداوند می‌اندیشم.

(۵) من هرگز به آن دلیلی که فکر می‌کنم، آشفته نیستم. من هرگز به آن دلیلی که فکر می‌کنم آشفته نیستم، زیرا مدام در تلاش برای توجیه افکارم هستم. مدام در تلاش هستم تا آن‌ها را حقیقی کنم. من همه چیز را دشمن خودم می‌کنم تا خشمم توجیه شود و حملاتم مجوز داشته باشند. من درک نکرده‌ام که با اعطای این نقش به هر چیز که می‌بینم، چقدر از آن‌ها نادرست استفاده کرده‌ام. من این کار را برای دفاع از آن سیستم فکری انجام داده‌ام که آزارم داده است، آن سیستم فکری که دیگر نمی‌خواهم. من مایلم که آن را رها کنم.', 'https://acim-farsi.org/workbook/lesson/51', 'https://acim-farsi.org/audio/workbook/lesson/51.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (52, 'مرور (۶ تا ۱۰)', '(۶) من آشفته هستم زیرا چیزی را می‌بینم که وجود ندارد.
(۷) من فقط گذشته را می‌بینم.
(۸) ذهن من درگیر پندارهای گذشته است.
(۹) من هیچ چیز را آنگونه که اکنون هست نمی‌بینم.
(۱۰) افکار من هیچ معنایی ندارند.', 'مرور امروز شامل ایده‌های زیر می‌شود:

(۶) من آشفته هستم زیرا چیزی را می‌بینم که وجود ندارد. واقعیت هرگز ترسناک نیست. ممکن نیست که بتواند من را آشفته کند. واقعیت فقط صلح کامل را با خود می‌آورد. وقتی من آشفته هستم، همیشه به این دلیل است که واقعیت را با اوهامی جایگزین کرده‌ام که خودم ساخته‌ام. اوهام آشفته کننده هستند زیرا من به آن‌ها واقعیت داده‌ام، و اینچنین است که واقعیت را یک وهم قلمداد می‌کنم. این سردرگمی من هیچ چیز را در آفرینش خداوند* به هیچ طریقی تحت تاثیر قرار نمی‌دهد. من همیشه توسط هیچ چیز آشفته هستم.

(۷) من فقط گذشته را می‌بینم. با نگاه کردن به پیرامون، من این دنیا را که مشاهده می‌کنم محکوم می‌کنم. من این را دیدن می‌خوانم. من گذشته را برعلیه همه کس و همه چیز حفظ می‌کنم، در حالی که آنان را دشمن خود می‌سازم. وقتی خودم را بخشیده باشم و به یاد آورده باشم چه کسی هستم، همه کس و همه چیز را که می‌بینم متبرک خواهم کرد. هیچ گذشته‌ای نخواهد بود، و بنابراین دشمنی وجود نخواهد داشت. و من با عشق به همه آنچه که قبلاً نمی‌توانستم ببینم، نگاه خواهم کرد.

(۸) ذهن من درگیر پندارهای گذشته است. من فقط پندارهای خودم را می‌بینم، و ذهنم درگیر گذشته است. پس من چه چیز را می‌توانم آنگونه که هست ببینم؟ بگذار به یاد داشته باشم که به گذشته نگاه می‌کنم تا از طلوع حال بر ذهنم جلوگیری کنم. بگذار بفهمم که در تلاش هستم تا از زمان بر علیه خداوند* استفاده کنم. بگذار بیاموزم که گذشته را رها کنم و بفهمم که با انجام این کار، من هیچ چیز را رها می‌کنم.

(۹) من هیچ چیز را آنگونه که اکنون هست نمی‌بینم. اگر من هیچ چیز را آنگونه که اکنون هست نمی‌بینم، حقیقتاً می‌توان گفت که هیچ چیز را نمی‌بینم. من فقط می‌توانم آنچه را که اکنون هست ببینم. انتخاب در این نیست که آیا گذشته را ببینم یا حال را، انتخاب صرفاً در این است که آیا ببینم یا نبینم. آنچه انتخاب کرده‌ام ببینم، به بهای رؤیت من تمام شده است. اینک می‌خواهم دوباره انتخاب کنم، تا بتوانم ببینم.

(۱۰) افکار من هیچ معنایی ندارند. من هیچ فکر خصوصی ندارم. اما من فقط از افکار خصوصی آگاه هستم. این افکار چه معنایی می‌توانند داشته باشند؟ آن‌ها وجود ندارند، پس هیچ معنایی ندارند. اما ذهن من بخشی از آفرینش است و بخشی از آفریدگار* آن. آیا بهتر نیست به تفکر کائنات بپیوندم، به جای آن که همه‌ی آنچه را که واقعاً از آن من است در پس افکار رقت‌انگیز و بی‌معنای «خصوصی» خود پنهان کنم؟', 'https://acim-farsi.org/workbook/lesson/52', 'https://acim-farsi.org/audio/workbook/lesson/52.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (53, 'مرور (۱۱ تا ۱۵)', '(۱۱) افکار بی‌معنای من، یک دنیای بی‌معنا را به من نشان می‌دهند.
(۱۲) من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم.
(۱۳) یک دنیای بی‌معنا آبستن ترس است.
(۱۴) خداوند* یک دنیای بی‌معنا را نیافرید.
(۱۵) افکار من تصویرهایی هستند که من ساخته‌ام.', 'امروز ایده‌های زیر را مرور می‌کنیم:

(۱۱) افکار بی‌معنای من، یک دنیای بی‌معنا را به من نشان می‌دهند. از آنجا که افکاری که من از آن‌ها آگاه هستم هیچ معنایی ندارند، دنیایی که آنها را به تصویر درمی‌آورد نیز نمی‌تواند هیچ معنایی داشته باشد. آنچه این دنیا را تولید می‌کند دیوانه‌وار است، و آنچه تولید می‌شود نیز چنین است. واقعیت دیوانه‌وار نیست، و من افکار واقعی دارم، همانگونه که افکار دیوانه‌وار دارم. پس می‌توانم یک دنیای واقعی را ببینم، اگر به افکار واقعی خودم به عنوان راهنمای دیدن نظر کنم.

(۱۲) من آشفته هستم زیرا یک دنیای بی‌معنا را می‌بینم. افکار دیوانه‌وار، آشفته کننده هستند. آنها دنیایی را تولید می‌کنند که در هیچ جای آن هیچ نظمی نیست. بر آن دنیایی که یک تفکر آشوبگر را متجلی می‌سازد، فقط آشوب حاکمیت می‌کند، و آشوب هیچ قانونی ندارد. من نمی‌توانم در چنین دنیایی در صلح زندگی کنم. سپاسگزارم که این دنیا واقعی نیست، و من نیازی ندارم که اصلاً آن را ببینم، مگر انتخاب کنم که برایش ارزش قائل شوم. و انتخاب من این نیست که برای چیزی که کاملاً دیوانه‌وار است و هیچ معنایی ندارد، ارزش قائل شوم.

(۱۳) یک دنیای بی‌معنا آبستن ترس است. وجودی کاملاً دیوانه، ترس پدید می‌آورد، زیرا کاملاً غیر قابل اتکا است و هیچ زمینه‌ای برای اطمینان ارائه نمی‌کند. هیچ چیزی در دیوانگی قابل اتکا نیست. هیچ امنیت و هیچ امیدی در بر ندارد. اما چنین دنیایی واقعی نیست. من به آن وهمِ واقعی بودن را داده‌ام، و از باور خودم به آن رنج برده‌ام. اینک انتخاب می‌کنم این باور را رها کنم، و به واقعیت اعتماد کنم. با این انتخاب، من از همه‌ی تأثیرات این دنیایِ ترس فرار خواهم کرد، زیرا تشخیص می‌دهم که وجود ندارد.

(۱۴) خداوند* یک دنیای بی‌معنا را نیافرید. چگونه یک دنیای بی‌معنا می‌تواند وجود داشته باشد، اگر خداوند* آن را نیافرید؟ او سرچشمهٔ* همه‌ی معناها است، و همه‌ی چیزهایی که واقعی هستند، در ذهن* او* هستند. در ذهن من نیز هستند، زیرا او مرا با آن‌ها خلق کرد. چرا من باید به رنج بردن از تأثیرات افکار دیوانه‌وار خودم ادامه دهم، زمانی که منزل من کمال آفرینش است؟ بگذار قدرت تصمیم خودم را به یاد داشته باشم، و جایی را که واقعاً در آن سکونت دارم تشخیص دهم.

(۱۵) افکار من تصویرهایی هستند که من ساخته‌ام. هر چیزی که من می‌بینم، افکارم را بازتاب می‌دهد. افکارم هستند که به من می‌گویند کجا هستم و چه هستم. این واقعیت که دنیایی را می‌بینم که در آن رنج و فقدان و مرگ هست، به من نشان می‌دهد که فقط در حال دیدن تجلی افکار دیوانه‌وار خودم هستم و اجازه نمی‌دهم که افکار واقعی من نور سودمند خویش را بر آنچه که می‌بینم بتابانند. اما طریق خداوند* قطعی است. تصویرهایی که من ساخته‌ام نمی‌توانند بر او* غالب شوند، زیرا اراده‌ام این نیست که چنین کنند. اراده‌ی من از آنِ او* است، و هیچ خدای دیگری را بر او* مقدم نمی‌شمارم.', 'https://acim-farsi.org/workbook/lesson/53', 'https://acim-farsi.org/audio/workbook/lesson/53.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (54, 'مرور (۱۶ تا ۲۰)', '(۱۶) من هیچ فکر خنثی‌ای ندارم.
(۱۷) من هیچ چیز خنثی‌ای نمی‌بینم.
(۱۸) من در تجربه کردن تأثیرات دیدن خودم تنها نیستم.
(۱۹) من در تجربه کردن تأثیرات افکار خودم تنها نیستم.
(۲۰) من مصمم هستم که ببینم.', 'این‌ها ایده‌های مرور امروز هستند:

(۱۶) من هیچ فکر خنثی‌ای ندارم. افکار خنثی ناممکن هستند زیرا همه‌ی افکار قدرت دارند. آن‌ها یا یک دنیای دروغین می‌سازند، یا مرا به یک دنیای واقعی هدایت می‌کنند. اما افکار نمی‌توانند بدون تأثیر باشند. همانطور که دنیایی که می‌بینم از خطاهای تفکر من سرچشمه می‌گیرد، با اجازه دادن به تصحیح خطاهایم، دنیای واقعی پیش چشمان من ظهور خواهد کرد. افکار من نمی‌توانند نه درست باشند، و نه نادرست. باید یا درست باشند، یا نادرست. آن‌چه می‌بینم به من نشان می‌دهد که آن‌ها کدام هستند.

(۱۷) من هیچ چیز خنثی‌ای نمی‌بینم. آن‌چه من می‌بینم شاهد بر آن چیزی است که می‌اندیشم. اگر من نمی‌اندیشیدم، وجود نمی‌داشتم، زیرا زندگی اندیشه است. بگذار به دنیایی که می‌بینم به عنوان نمود وضعیت ذهنی خودم نگاه کنم. من می‌دانم که وضعیت ذهنیم می‌تواند تغییر کند. و بنابراین این را هم می‌دانم که دنیایی که می‌بینم نیز می‌تواند اینچنین تغییر کند.

(۱۸) من در تجربه کردن تأثیرات دیدن خودم تنها نیستم. اگر من هیچ فکر خصوصی ندارم، نمی‌توانم یک دنیای خصوصی را ببینم. حتی ایده‌ی دیوانه‌وار جدایی نیز ناچار بود تسهیم شود پیش از این که بتواند بنیان دنیایی را که من می‌بینم شکل دهد. اما آن سهیم شدن، سهیم شدن در هیچ بود. من می‌توانم افکار واقعی خودم را نیز فراخوانی کنم، که همه چیز را با همه کس سهیم می‌شوند. همچنان که افکار جدایی من افکار جدایی دیگران را فرامی‌خوانند، افکار واقعی من نیز افکار واقعی را در آن‌ها بیدار می‌کنند. و دنیایی که افکار واقعی من به من نشان می‌دهند، بر بینایی آن‌ها نیز همانند بینایی من طلوع خواهد کرد.

(۱۹) من در تجربه کردن تأثیرات افکار خودم تنها نیستم. من در هیچ چیز تنها نیستم. همه‌ی چیزهایی که من فکر می‌کنم یا می‌گویم یا انجام می‌دهم به همه‌ی کائنات آموزش می‌دهند. یک فرزند* خداوند* نمی‌تواند پوچ بیندیشد یا سخن بگوید یا عمل کند. او نمی‌تواند در هیچ چیزی تنها باشد. پس در قدرت من است که همه‌ی ذهن‌ها را به همراه ذهن خودم تغییر دهم، زیرا ذهن من قدرت خداوند* است.

(۲۰) من مصمم هستم که ببینم. با تشخیص طبیعت مشترک افکار ما، من مصمم هستم که ببینم. می‌خواهم به آن شواهدی نگاه کنم که به من نشان می‌دهند تفکر دنیا تغییر کرده است. من می‌خواهم آن گواه را مشاهده کنم که آنچه از طریق من انجام شده، عشق را قادر ساخته است تا جایگزین ترس شود، خنده جایگزین اشک و فراوانی جایگزین فقدان. من می‌خواهم به دنیای واقعی نگاه کنم، و اجازه دهم به من بیاموزد که ارادهٔ من و ارادهٔ* خداوند* یکی هستند.', 'https://acim-farsi.org/workbook/lesson/54', 'https://acim-farsi.org/audio/workbook/lesson/54.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (55, 'مرور (۲۱ تا ۲۵)', '(۲۱) من مصمم هستم چیزها را به طرز متفاوتی ببینم.
(۲۲) چیزی که من می‌بینم، شکلی از کینه است.
(۲۳) من می‌توانم با رها کردن افکار حمله از این دنیا نجات یابم.
(۲۴) من بهترین مصالح خودم را درک نمی‌کنم.
(۲۵) من نمی‌دانم که قصد هرچیز، چیست.', 'مرور امروز شامل ایده‌های زیر می‌شود:

(۲۱) من مصمم هستم چیزها را به طرز متفاوتی ببینم. آنچه من اکنون می‌بینم تنها نشانه‌های بیماری، مصیبت و مرگ هستند. این نمی‌تواند چیزی باشد که خداوند* برای فرزند* عزیزش* آفرید. همین واقعیت که من چنین چیزهایی را می‌بینم، گواه این است که خداوند* را نمی‌فهمم. بنابراین فرزند* او* را نیز نمی‌فهمم. آنچه می‌بینم به من می‌گوید که نمی‌دانم چه کسی هستم. من مصمم هستم شواهد حقیقت درونم را ببینم، نه شواهدی را که به من وهمی از خودم را نشان می‌دهند.

(۲۲) چیزی که من می‌بینم، شکلی از کینه است. این دنیا که من می‌بینم بعید است که تجلی پندارهای عاشقانه باشد. این تصویری است از حمله‌ی همه چیز به همه چیز. این هر چیز هست جز بازتابی از عشق* خداوند* و عشق فرزند* او*. پندارهای حمله‌ی خود من هستند که این تصویر از آن‌ها برمی‌خیزد. اندیشه‌های عاشقانهٔ من مرا از این ادراک از دنیا نجات خواهند داد، و آن صلح را که خداوند* برایم مقرر کرده به من عطا خواهند کرد.

(۲۳) من می‌توانم با رها کردن افکار حمله از این دنیا نجات یابم. رستگاری در اینجا مستقر است، و نه در هیچ جای دیگر. بدون افکار حمله من نمی‌توانم دنیایی از حمله را ببینم. همچنان که بخشایش به عشق اجازه می‌دهد تا به آگاهی من بازگردد، دنیایی از صلح، امنیت و سرور را خواهم دید. و این است که من انتخاب می‌کنم ببینم، به جای آنچه که اکنون نظاره‌اش می‌کنم.

(۲۴) من بهترین مصالح خودم را درک نمی‌کنم. چگونه می‌توانم بهترین مصالح خودم را تشخیص دهم، زمانی که نمی‌دانم کیستم؟ آنچه می‌پندارم بهترین مصالح من است، صرفاً مرا محکم‌تر به این دنیای اوهام بسته می‌کند. من اراده می‌کنم از آن راهنمای متعال که خداوند* به من عطا کرده پیروی کنم تا دریابم بهترین مصالح من چه هستند، و تشخیص دهم که خودم نمی‌توانم آن‌ها را درک کنم.

(۲۵) من نمی‌دانم که قصد هرچیز، چیست. از نظر من، قصد همه‌ی چیزها این است که اثبات کنند اوهام من در مورد خودم واقعی هستند. من تلاش دارم از همه کس و همه چیز برای این مقصود استفاده کنم. من باور دارم که این دنیا برای همین است. بنابراین نمی‌توانم قصد واقعی آن را تشخیص دهم. قصدی که من به این دنیا داده‌ام، منجر به تصویری هراس‌انگیز از آن شده است. باشد تا با رها کردن قصدی که برای این دنیا قایل شده‌ام و با آموختن حقیقت در مورد آن، ذهنم را به قصد واقعی این دنیا بگشایم.', 'https://acim-farsi.org/workbook/lesson/55', 'https://acim-farsi.org/audio/workbook/lesson/55.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (56, 'مرور (۲۶ تا ۳۰)', '(۲۶) افکار حمله‌ی من به آسیب‌ناپذیری من حمله می‌کنند.
(۲۷) بالاتر از همه چیزهای دیگر، من می‌خواهم ببینم.
(۲۸) بالاتر از همه چیز دیگر، من می‌خواهم به طرز متفاوتی ببینم.
(۲۹) خداوند* در همه‌ی چیزهایی که من می‌بینم، هست.
(۳۰) خداوند* در همه‌ی چیزهایی که من می‌بینم هست، زیرا خداوند* در ذهن من است.', 'مرور امروز ما شامل ایده‌های زیر می‌شود:

(۲۶) افکار حمله‌ی من به آسیب‌ناپذیری من حمله می‌کنند. من چگونه می‌توانم بدانم چه کسی هستم زمانی که خودم را تحت حمله‌ی مداوم می‌بینم؟ به نظر می‌رسد که درد، بیماری، فقدان، کهنسالی و مرگ مرا تهدید می‌کنند. همه‌ی امیدها و آرزوها و نقشه‌های من ظاهراً تحت فرمان دنیایی هستند که نمی‌توانم کنترل کنم. اما میراث من امنیت کامل و اغنای تمام است. من تلاش کرده‌ام میراث خود را برای مبادله با دنیایی که می‌بینم هزینه کنم. اما خداوند* میراث مرا برایم در امان نگاه داشته است. افکار واقعی خودم به من خواهند آموخت که آن میراث چیست.

(۲۷) بالاتر از همه چیزهای دیگر، من می‌خواهم ببینم. با تشخیص دادن این که آنچه می‌بینم بازتاب چیزی است که می‌اندیشم هستم، من تشخیص می‌دهم که رؤیت والاترین نیازم است. دنیایی که من می‌بینم گواه ماهیت ترسناک خودانگاره‌ای است که ساخته‌ام. اگر می‌خواهم به یاد بیاورم که چه کسی هستم، اساسی است که این تصویر از خودم را رها کنم. وقتی این تصویر با حقیقت جایگزین شود، رؤیت مطمئناً به من عطا خواهد شد. و با این رؤیت، من به دنیا و به خودم با خیرخواهی و عشق نظر خواهم کرد.

(۲۸) بالاتر از همه چیز دیگر، من می‌خواهم به طرز متفاوتی ببینم. دنیایی که من می‌بینم، خودانگاره‌ی ترسناکِ مرا در جای خود نگاه می‌دارد، و تداوم آن را تضمین می‌کند. مادامی که دنیا را این‌گونه می‌بینم، حقیقت نمی‌تواند به آگاهی من وارد شود. من می‌خواهم اجازه دهم که آن درب موجود در پس این دنیا برایم گشوده شود، تا بتوانم در ورای آن به دنیایی نظر کنم که عشق* خداوند* را بازتاب می‌دهد.

(۲۹) خداوند* در همه‌ی چیزهایی که من می‌بینم، هست. در پس هر تصویری که من ساخته‌ام، حقیقت بدون تغییر باقی می‌ماند. در پس هر حجابی که من بر روی چهره‌ی عشق انداخته‌ام، نور آن با همان درخشش باقی است. فراتر از همه‌ی آرزوهای دیوانه‌وار من، اراده‌ام حضور دارد، در اتحاد با ارادهٔ* پدرم*. خداوند* همچنان در همه جا و در همه چیز برای همیشه هست. و ما که پاره‌ای از او* هستیم، باز هم به ورای همه‌ی ظواهر نگاه خواهیم کرد، و حقیقتی را که فراتر از همه‌ی آن‌ها هست تشخیص خواهیم داد.

(۳۰) خداوند* در همه‌ی چیزهایی که من می‌بینم هست، زیرا خداوند* در ذهن من است. در ذهن من، در پس همه‌ی افکار دیوانه‌وار جدایی و حمله‌ام، این معرفت حضور دارد که همه چیز برای همیشه یگانه است. من این معرفت را که چه کسی هستم از دست نداده‌ام، اگرچه آن را از یاد برده‌ام. این معرفت در ذهن* خداوند* برایم نگهداری شده است، خدایی* که اندیشه‌هایش* را ترک نکرده است. و من که در بین این اندیشه‌ها هستم، با آن‌ها و با او* یگانه هستم.', 'https://acim-farsi.org/workbook/lesson/56', 'https://acim-farsi.org/audio/workbook/lesson/56.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (57, 'مرور (۳۱ تا ۳۵)', '(۳۱) من قربانی دنیایی که می‌بینم نیستم.
(۳۲) من دنیایی را که می‌بینم اختراع کرده‌ام.
(۳۳) شیوه‌ی دیگری برای نگاه کردن به این دنیا وجود دارد.
(۳۴) من می‌توانم صلح را به جای این ببینم.
(۳۵) ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم.', 'امروز ایده‌های زیر را مرور می‌کنیم:

(۳۱) من قربانی دنیایی که می‌بینم نیستم. من چگونه می‌توانم قربانی دنیایی باشم که می‌تواند کاملاً باطل شود اگر من چنین انتخاب کنم؟ زنجیرهای من باز شده‌اند. من می‌توانم آن‌ها را صرفاً با خواست خودم فروافکنم. درب زندان باز است. من می‌توانم به سادگی با گام برداشتن به بیرون آن را ترک کنم. هیچ چیز مرا در این دنیا نگاه نمی‌دارد. تنها آرزوی من برای ماندن است که مرا یک زندانی نگه می‌دارد. من می‌خواهم خواسته‌های دیوانه‌وار خودم را رها کنم و بالاخره به درون نور خورشید گام بردارم.

(۳۲) من دنیایی را که می‌بینم اختراع کرده‌ام. من زندانی را ساخته‌ام که خودم را در آن می‌بینم. همه‌ی آنچه به انجامش نیاز دارم شناختن این موضوع است و آزاد می‌شوم. من خودم را با این باور که زندانی کردن فرزند* خداوند* ممکن است، فریب داده‌ام. من با این باور اشتباه تلخی مرتکب شده‌ام، و دیگر آن را نمی‌خواهم. فرزند* خداوند* باید برای همیشه آزاد باشد. او آنگونه است که خداوندش* آفرید، و نه آن چیزی که من می‌خواهم از او بسازم. او آنجا است که خداوند* می‌خواهد باشد، و نه آنجا که من می‌پنداشتم در زندان نگاهش می‌دارم.

(۳۳) شیوه‌ی دیگری برای نگاه کردن به این دنیا وجود دارد. از آنجا که قصد این دنیا همان قصدی نیست که من به آن نسبت داده‌ام، باید شیوه‌ی دیگری برای نگاه کردن به آن وجود داشته باشد. من همه چیز را وارونه می‌بینم، و پندارهای من برخلاف حقیقت هستند. من این دنیا را همچون زندانی برای فرزند* خداوند* می‌بینم. در نتیجه این دنیا واقعاً باید مکانی باشد که او می‌تواند آزاد شود. من می‌خواهم به دنیا چنان که هست نظر کنم، و آن را همچون مکانی ببینم که آنجا فرزند* خداوند* آزادی خود را می‌یابد.

(۳۴) من می‌توانم صلح را به جای این ببینم. زمانی که من این دنیا را همچون مکانی برای آزاد شدن ببینم، تشخیص می‌دهم که بازتاب دهندهٔ قانون‌های خداوند* است، نه قواعدی که من برایش ساخته‌ام تا از آن‌ها اطاعت کند. خواهم فهمید که صلح، و نه جنگ، در آن سکنی دارد. و درک خواهم کرد که صلح همچنین در قلب‌های همه‌ی آنان که این مکان را با من سهیم هستند، ساکن است.

(۳۵) ذهن من بخشی از ذهن* خداوند* است. من بسیار مقدس هستم. همچنان که صلح این دنیا را با برادرانم سهیم می‌شوم، درک این را آغاز می‌کنم که این صلح از ژرفای درون خودم می‌آید. دنیایی که من به آن نظر می‌کنم نور بخشایش مرا دریافت می‌کند، و بخشایش را به من تابش می‌دهد. در این نور، آغاز می‌کنم به دیدن آنچه اوهامم در مورد خودم پنهان کرده‌اند. آغاز می‌کنم به فهمیدن قداست همه‌ی چیزهای موجود، از جمله خودم، و یگانگی آن‌ها با من.', 'https://acim-farsi.org/workbook/lesson/57', 'https://acim-farsi.org/audio/workbook/lesson/57.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (58, 'مرور (۳۶ تا ۴۰)', '(۳۶) قداست من همه‌ی چیزهایی را که می‌بینم در بر می‌گیرد.
(۳۷) قداست من دنیا را متبرک می‌کند.
(۳۸) هیچ کاری نیست که قداست من نتواند انجام دهد.
(۳۹) قداست من، رستگاری من است.
(۴۰) من به عنوان فرزند* خداوند* متبرک هستم.', 'این ایده‌ها برای مرور امروز هستند:

(۳۶) قداست من همه‌ی چیزهایی را که می‌بینم در بر می‌گیرد. از قداست من ادراک دنیای واقعی سرچشمه می‌گیرد. با بخشایش، دیگر خودم را گناهکار نمی‌بینم. می‌توانم بی‌گناهی را که درباره‌ی من حقیقت است بپذیرم. اگر این دنیا را از درون چشمانی فهیم ببینم، فقط قداست آن را می‌بینم. زیرا من فقط می‌توانم پندارهایی را تصویر کنم که آن‌ها را در مورد خودم نگه می‌دارم.

(۳۷) قداست من دنیا را متبرک می‌کند. ادراک قداستم، فقط مرا به تنهایی متبرک نمی‌کند. همه کس و همه‌ی چیزهایی که من در نور آن می‌بینم، در سروری که این قداست برایم به ارمغان می‌آورد سهیم هستند. هیچ چیزی از این سرور جدا نیست، زیرا هیچ چیزی نیست که در قداست من سهیم نباشد. همچنان که قداستم را تشخیص می‌دهم، قداست دنیا چنان تابش می‌کند تا همگان آن را ببینند.

(۳۸) هیچ کاری نیست که قداست من نتواند انجام دهد. قدرت شفادهی قداست من نامحدود است، زیرا قدرت نجات‌بخشی آن نامحدود است. چه چیز جز اوهام وجود دارد که باید از آن نجات یافت؟ و همه‌ی اوهام چه هستند جز ایده‌های نادرست در مورد خودم؟ قداستم همه‌ی آن‌ها را با حمایت از حقیقت در مورد من فرومی‌ریزد. در حضور قداستم که من آن را با خود* خداوند* سهیم هستم، همه‌ی خدایان دروغین محو می‌شوند.

(۳۹) قداست من، رستگاری من است. از آنجا که قداستم مرا از همه‌ی احساس‌های گناه نجات می‌دهد، تشخیص قداستم، تشخیص رستگاری من است. تشخیص قداست من، تشخیص رستگاری این دنیا نیز هست. به محض این که قداست خودم را بپذیرم، هیچ چیز نمی‌تواند مرا بترساند. و وقتی من نترس باشم، همه ناگزیر می‌شوند در فهم من سهیم شوند، فهمی که هدیه‌ی خداوند* به من و به این دنیا است.

(۴۰) من به عنوان فرزند* خداوند* متبرک هستم. در اینجا طلب من برای همه‌ی خیر و فقط خیر نهفته است. من به عنوان فرزند* خداوند* متبرک هستم. همه‌ی چیزهای خیر از آن من هستند، زیرا خداوند* آن‌ها را برای من قصد کرده است. من به دلیل آن‌کسی* که هستم، نمی‌توانم از هیچ فقدان یا محرومیت یا دردی رنج ببرم. پدرم* از من حمایت می‌کند، از من حفاظت می‌کند، و مرا در همه کار هدایت می‌کند. توجه او* به من بیکران است، و همیشه با من است. من تا ابد به عنوان فرزند* او* متبرک هستم.', 'https://acim-farsi.org/workbook/lesson/58', 'https://acim-farsi.org/audio/workbook/lesson/58.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (59, 'مرور (۴۱ تا ۴۵)', '(۴۱) هر جا می‌روم، خداوند* با من می‌آید.
(۴۲) خداوند* قدرت من است. رؤیت موهبت او* است.
(۴۳) خداوند* سرچشمه* من است. من نمی‌توانم جدا از او* ببینم.
(۴۴) خداوند* آن نور است که من در آن می‌بینم.
(۴۵) خداوند* آن ذهن* است که من با آن می‌اندیشم.', 'ایده‌های زیر برای مرور امروز هستند:

(۴۱) هر جا می‌روم، خداوند* با من می‌آید. چگونه می‌توانم تنها باشم زمانی که خداوند* همیشه با من می‌آید؟ چگونه می‌توانم به خودم شکاک و نامطمئن باشم زمانی که یقینِ کامل در او* سکنی دارد؟ چگونه می‌توانم توسط چیزی آشفته شوم زمانی که او* در من در صلح مطلق آرمیده است؟ چگونه می‌توانم رنج ببرم زمانی که عشق و سرور از طریق او* مرا احاطه کرده است؟ بگذار در مورد خودم اوهام را نپرورم. من کامل هستم زیرا خداوند* هر جا که می‌روم، با من می‌آید.

(۴۲) خداوند* قدرت من است. رؤیت موهبت او* است. باشد تا امروز برای دیدن، با چشمان خودم نگاه نکنم. باشد تا اراده کنم اوهام رقت‌انگیزم را که می‌بینم، با رؤیتی جایگزین کنم که توسط خداوند* عطا می‌شود. رؤیت مسیحایی* موهبت او* است، و او* آن را به من عطا کرده است. باشد تا امروز این هدیه را فرا بخوانم، آنچنان که این روز بتواند به من کمک کند جاودانگی را بفهمم.

(۴۳) خداوند* سرچشمه* من است. من نمی‌توانم جدا از او* ببینم. من می‌توانم چیزی را ببینم که خداوند* می‌خواهد ببینم. من نمی‌توانم چیز دیگری را ببینم. ورای ارادهٔ* او* فقط اوهام حضور دارند. وقتی می‌پندارم که می‌توانم جدا از او* ببینم، این اوهام را انتخاب می‌کنم. وقتی تلاش می‌کنم تا از طریق چشمان بدن ببینم، این اوهام را انتخاب می‌کنم. اما رؤیت مسیحایی* به من داده شده تا جایگزین این اوهام شود. من انتخاب می‌کنم که از طریق این رؤیت ببینم.

(۴۴) خداوند* آن نور است که من در آن می‌بینم. من نمی‌توانم در تاریکی ببینم. خداوند* تنها نور است. پس اگر می‌خواهم ببینم، باید از طریق او* باشد. من تلاش کرده‌ام دیدن را تعریف کنم، و اشتباه کرده‌ام. اینک به من عطا شده که بفهمم خداوند* آن نور است که من در آن می‌بینم. باشد تا از رؤیت و آن دنیای شاد که به من نشان خواهد داد، استقبال کنم.

(۴۵) خداوند* آن ذهن* است که من با آن می‌اندیشم. من هیچ اندیشه‌ای ندارم که با خداوند* سهیم نباشم. من هیچ اندیشه‌ای جدا از او* ندارم، زیرا من هیچ ذهنی جدا از ذهن* او* ندارم. به عنوان بخشی از ذهن* او*، اندیشه‌های من از آن او* هستند، و اندیشه‌هایش* از آن من است.', 'https://acim-farsi.org/workbook/lesson/59', 'https://acim-farsi.org/audio/workbook/lesson/59.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (60, 'مرور (۴۶ تا ۵۰)', '(۴۶) خداوند* آن عشق است که من در آن می‌بخشم.
(۴۷) خداوند* آن قدرت است که من به آن اعتماد می‌کنم.
(۴۸) هیچ چیزی برای ترسیدن وجود ندارد.
(۴۹) آوای* خداوند* در تمام طول روز با من سخن می‌گوید.
(۵۰) من توسط عشق* خداوند* نگهداری می‌شوم.', 'این ایده‌ها برای مرور امروز هستند:

(۴۶) خداوند* آن عشق است که من در آن می‌بخشم. خداوند* نمی‌بخشد زیرا هرگز محکوم نکرده است. بی‌عیب نمی‌تواند عیب‌جویی کند، و آنان که بی‌گناهی خود را پذیرفته باشند، هیچ چیزی برای بخشایش نمی‌بینند. اما بخشایش همان وسیله است که من توسط آن بی‌گناهی خودم را خواهم شناخت. آن بازتاب عشق* خداوند* بر روی زمین است. آن مرا به اندازه‌ی کافی به ملکوت* نزدیک خواهد کرد، آنچنان که عشق* خداوند* بتواند به من دست یابد و مرا به سوی او* بالا ببرد.

(۴۷) خداوند* آن قدرت است که من به آن اعتماد می‌کنم. از طریق قدرت خودم نیست که من می‌بخشم. بخشایش من از طریق قدرت خداوند* در من است، من با بخشیدن، آن قدرت را به یاد می‌آورم. در حالی که دیدن را آغاز می‌کنم، بازتاب او* را بر روی زمین تشخیص می‌دهم. من همه‌ی چیزها را می‌بخشم، زیرا جوشش قدرت او* را در خودم احساس می‌کنم. و من آغاز می‌کنم آن عشق* را به یاد بیاورم که انتخاب کردم فراموشش کنم، عشقی که اما مرا فراموش نکرده است.

(۴۸) هیچ چیزی برای ترسیدن وجود ندارد. این دنیا زمانی که بتوانم آن را ببینم، چقدر به نظرم امن خواهد بود! این دنیا اصلاً شبیه چیزی نخواهد بود که من اکنون دیدنش را تصور می‌کنم. همه کس و همه چیز که می‌بینم به سویم خم خواهند شد تا مرا متبرک کنند. من در هر کسی عزیزترین دوستم را خواهم شناخت. در دنیایی که من آن را بخشیده‌ام و آن دنیا نیز مرا بخشیده است، چه چیزی برای ترسیدن می‌تواند وجود داشته باشد؟

(۴۹) آوای* خداوند* در تمام طول روز با من سخن می‌گوید. حتی یک لحظه وجود ندارد که در آن آوای* خداوند* قطع شود، آوایی که مرا به بخشایش برای نجات خودم می‌خواند. حتی یک لحظه وجود ندارد که در آن آوای* او* جهت دادن به افکار من، راهنمایی کردن اعمال من و هدایت پاهای من را متوقف کند. من با گام‌های استوار به سوی حقیقت حرکت می‌کنم . نمی‌توانم به هیچ جای دیگری بروم، زیرا آوای* خداوند* تنها آوا و تنها راهنمایی است که به فرزند* او* عطا شده است.

(۵۰) من توسط عشق* خداوند* نگهداری می‌شوم. با گوش فرا دادن به آوای* خداوند*، من توسط عشق* او* نگهداری می‌شوم. با گشودن چشمانم، عشق او این دنیا را برایم روشن می‌کند تا ببینم. با بخشیدن، عشق او به یادم می‌آورد که فرزند* او* بی‌گناه است. و با نظر کردن به این دنیا با رؤیتی که او* به من عطا کرده، به یاد می‌آورم که من فرزند* او* هستم.', 'https://acim-farsi.org/workbook/lesson/60', 'https://acim-farsi.org/audio/workbook/lesson/60.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (61, 'من نور این دنیا هستم.', 'من نور این دنیا هستم. این تنها وظیفه‌ی من است. به این دلیل من اینجا هستم.', 'من نور این دنیا هستم.

چه کسی نور این دنیا است جز فرزند* خداوند*؟ پس این جمله صرفاً بیان حقیقت در مورد خود تو است. این جمله در نقطه‌ی مقابل بیان غرور، تکبر یا خودفریبی است. این جمله وصف کننده‌ی مفهومی نیست که تو از خودت ساخته‌ای. این جمله به هیچ‌یک از خصوصیاتی که تو به خدایان دروغین خود عطا کرده‌ای، اشاره نمی‌کند. این جمله به تو اشاره می‌کند، آنچنان که توسط خداوند* آفریده شدی. این جمله به سادگی حقیقت را بیان می‌کند.

برای نفس، ایده‌ی امروز نمونه‌ی خود-ستایشگری است. اما نفس، تواضع را نمی‌فهمد و آن را با خود-خوارگری اشتباه می‌گیرد. تواضع عبارت است از پذیرش نقشت در رستگاری و نپذیرفتن نقشی دیگر. این تواضع نیست که اصرار کنی نمی‌توانی نور این دنیا باشی، در صورتی که خداوند* این وظیفه را برای تو مقرر کرده باشد. فقط گستاخی است که می‌خواهد اعلام کند این وظیفه نمی‌تواند برای تو باشد، گستاخی همیشه متعلق به نفس است.

تواضع حقیقی مستلزم این است که ایده‌ی امروز را بپذیری، زیرا آوای* خداوند* حقیقی بودن این ایده را به تو اعلام می‌کند. این ایده یک گام آغازین در پذیرش وظیفه‌ی واقعی تو بر زمین است. یک قدم عظیم به سوی این است که تو جایگاه درست خود را در رستگاری اشغال کنی. اعلام قاطع حق تو برای نجات یافتن است، و تصدیق آن قدرتی است که به تو عطا شده تا دیگران را نجات دهی.

تو خواهی خواست که امروز به هر تعداد دفعات ممکن در مورد این ایده بیندیشی. این ایده پاسخ بی‌نقص برای همه‌ی اوهام است، و نیز برای همه‌ی وسوسه‌ها. این ایده تمامی تصویرهایی را که در مورد خودت ساخته‌ای به پیشگاه حقیقت می‌آورد، و به تو کمک می‌کند تا در صلح رهسپار شوی، سبکبار و مطمئن از قصد خود.

امروز باید به هر تعداد ممکن برنامه‌ی تمرین انجام شود، گرچه نیازی نیست هریک بیشتر از یک یا دو دقیقه طول بکشد. تمرینات باید با گفتن این جمله به خودت آغاز شوند: من نور این دنیا هستم. این تنها وظیفه‌ی من است. به این دلیل من اینجا هستم. سپس در مورد این جملات برای مدت کوتاهی فکر کن، ترجیحاً اگر شرایط اجازه دهد با چشمان بسته. اجازه بده چند فکر مربوط به ذهنت بیاید، و اگر ذهن از فکر محوری پراکنده شد، ایده را برای خودت تکرار کن.

مطمئن شو که روز را با یک برنامه‌ی تمرین آغاز می‌کنی و با یک برنامه‌ی تمرین به پایان می‌بری. در این صورت تو با تصدیق حقیقت در مورد خودت بیدار خواهی شد، آن را در طول روز تقویت خواهی کرد، و در حالی به خواب خواهی رفت که بر وظیفه‌ی خود و تنها قصد خود در اینجا تأکید می‌کنی. این دو برنامه‌ی تمرین می‌توانند از بقیه طولانی‌تر باشند، در صورتی که احساس کنی مفید هستند و تمایل به طولانی کردن آن‌ها داشته باشی.

ایده‌ی امروز بسیار فراتر از دیدگاه‌های بی‌ارزش نفس در این مورد که تو که هستی و قصدت چیست خواهد رفت. به عنوان پیش‌درآمد رستگاری، این ایده یک ضرورت آشکار است. این نخستین گام از تعدادی گام‌های عظیم است که ما در چند هفته‌ی آینده برخواهیم داشت. امروز تلاش کن ساختن یک بنیان محکم برای این پیشرفت‌ها را آغاز کنی. تو نور این دنیا هستی. خداوند* نقشه‌ی خود را برای رستگاری فرزندش*، بر تو بنا کرده است.', 'https://acim-farsi.org/workbook/lesson/61', 'https://acim-farsi.org/audio/workbook/lesson/61.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (62, 'بخشایش وظیفه‌ی من به عنوان نور این دنیا است.', 'بخشایش وظیفهٔ من به عنوان نور این دنیا است. من می‌خواهم وظیفه‌ام را به انجام برسانم تا بتوانم شاد باشم.

اگر توجه تو منحرف شد، ایده را تکرار کن و اضافه کن:

من می‌خواهم این را به یاد داشته باشم، زیرا می‌خواهم شاد باشم.', 'بخشایش وظیفه‌ی من به عنوان نور این دنیا است.

بخشایشِ تو است که این دنیای تاریکی را به نور می‌رساند. این بخشایشِ تو است که به تو اجازه می‌دهد آن نور را تشخیص دهی که در آن می‌بینی. بخشایش برهان این است که تو نور این دنیا هستی. از طریق بخشایش تو، حقیقت در مورد خودت به یاد تو باز می‌گردد. بنابراین، رستگاری‌ات در بخشایش تو نهفته است.

اوهام در مورد خودت و این دنیا یکی هستند. به همین دلیل تمامی بخشایش، هدیه‌ای به خودت است. هدف تو کشف این است که چه کسی هستی، در حالی که هویت* خود را با حمله به آفرینش و آفریدگار* آن نادیده گرفته‌ای. اینک در حال آموختن هستی که چگونه حقیقت را به یاد بیاوری. زیرا این حمله باید با بخشایش جایگزین شود، آنچنان که اندیشه‌های زندگی بتوانند جایگزین پندارهای مرگ شوند.

به یاد داشته باش که در هر حمله، تو ضعف خود را فرا می‌خوانی، و در عین حال هر زمان که می‌بخشی، قدرت مسیحای* درونت را فراخوانی می‌کنی. آیا اینک نمی‌خواهی فهمیدن این را آغاز کنی که بخشایش برای تو چه خواهد کرد؟ بخشایش همه‌ی حس ضعف، فشار و خستگی را از ذهنت برخواهد داشت. بخشایش تمامی ترس و احساس گناه و درد را برطرف خواهد کرد. بخشایش آسیب‌ناپذیری و قدرتی را که خداوند* به فرزند* خود* عطا کرد، به آگاهی تو بازخواهد گرداند.

بیایید از آغاز کردن و پایان دادن این روز با تمرین ایده‌ی امروز خرسند شویم، و از آن در طول روز به دفعات ممکن استفاده کنیم. این کار کمک خواهد کرد که امروز را به همان اندازه که خداوند* می‌خواهد برای خودت شاد کنی. و این کار به آنان که پیرامون تو هستند کمک خواهد کرد، همینطور به همه‌ی آن‌ها که در مکان و زمان دور به نظر می‌رسند، تا این شادمانی را با تو سهیم شوند

امروز به هر تعداد دفعات ممکن که می‌توانی، در صورت امکان با چشمان بسته به خود بگو: بخشایش وظیفهٔ من به عنوان نور این دنیا است. من می‌خواهم وظیفه‌ام را به انجام برسانم تا بتوانم شاد باشم. سپس یک یا دو دقیقه را برای توجه کردن به وظیفه‌ی خود و آن شادمانی و آسایشی که برای تو به ارمغان خواهد آورد صرف کن. اجازه بده اندیشه‌های مرتبط آزادانه به ذهنت بیایند، زیرا قلبت این کلمات را تشخیص خواهد داد، و در ذهنت این آگاهی حضور دارد که آن‌ها درست هستند. اگر توجه تو منحرف شد، ایده را تکرار کن و اضافه کن: من می‌خواهم این را به یاد داشته باشم، زیرا می‌خواهم شاد باشم.', 'https://acim-farsi.org/workbook/lesson/62', 'https://acim-farsi.org/audio/workbook/lesson/62.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (63, 'نور این دنیا از طریق بخشایش من برای همه‌ی ذهن‌ها صلح به ارمغان می‌آورد.', 'نور این دنیا از طریق بخشایش من برای تمامی ذهن‌ها صلح به ارمغان می‌آورد. من آن وسیله هستم که خداوند* برای رستگاری این دنیا منصوب کرده است.', 'نور این دنیا از طریق بخشایش من برای همه‌ی ذهن‌ها صلح به ارمغان می‌آورد.

تو چقدر قدسی هستی که قدرتِ به ارمغان آوردن صلح برای همه‌ی ذهن‌ها را داری! تو چقدر متبرک هستی که می‌توانی تشخیص دادن وسایلی را بیاموزی برای اجازه دادن به این که این مهم از طریق تو انجام پذیرد! چه هدفی می‌توانستی داشته باشی که بتواند شادمانی عظیم‌تری را برایت به ارمغان بیاورد؟

تو به راستی با چنین وظیفه‌ای، نور این دنیا هستی. فرزند* خداوند* برای رستگاری خود به تو نظر می‌کند. این رستگاری از آن تو است تا به او عطا کنی، زیرا به تو تعلق دارد. به جای آن، هیچ هدف بی‌ارزش یا خواسته‌ی بی‌معنایی را نپذیر. زیرا در این صورت وظیفه‌ی خود را از یاد خواهی برد و فرزند* خداوند* را در جهنم رها خواهی کرد. این تقاضای بیهوده‌ای نیست که از تو خواسته می‌شود. از تو خواسته می‌شود که رستگاری را بپذیری تا بتواند برای عطا کردن، از آن تو شود.

با تشخیص اهمیت این وظیفه، ما امروز خوشحال خواهیم شد که آن را به دفعات بسیار به یاد بیاوریم. ما روز را با تصدیق این وظیفه آغاز خواهیم کرد، و با داشتن اندیشه‌ی آن در آگاهی خود به پایان خواهیم برد. و در طول روز آن را به دفعات ممکن تکرار خواهیم کرد: نور این دنیا از طریق بخشایش من برای تمامی ذهن‌ها صلح به ارمغان می‌آورد. من آن وسیله هستم که خداوند* برای رستگاری این دنیا منصوب کرده است.

اگر چشمانت را ببندی، احتمالاً اجازه دادن به اندیشه‌های مرتبط را برای آمدن به ذهنت آسان‌تر خواهد بود و باید یک یا دو دقیقه را برای توجه به این اندیشه‌ها اختصاص دهی. اما با این حال، برای چنین فرصتی منتظر نمان. برای تقویت ایده‌ی امروز، هیچ فرصتی نباید از دست برود. به یاد داشته باش که فرزند* خداوند* برای رستگاری خود به تو نظر می‌کند. و چه کسی جز خویشتن* تو باید فرزند* او* باشد؟', 'https://acim-farsi.org/workbook/lesson/63', 'https://acim-farsi.org/audio/workbook/lesson/63.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (64, 'باشد تا من وظیفه‌ام را فراموش نکنم.', 'باشد تا من وظیفه‌ام را فراموش نکنم. باشد تا تلاش نکنم وظیفهٔ خودم را جایگزین وظیفهٔ خداوند* کنم. باشد تا ببخشم و شاد باشم.

این دنیایی است که وظیفهٔ من نجات آن است.', 'باشد تا من وظیفه‌ام را فراموش نکنم.

ایدهٔ امروز صرفاً شیوه‌ای دیگر برای گفتن این است «باشد تا من در وسوسه سرگردان نشوم.» قصد این دنیا که تو می‌بینی پنهان کردن وظیفهٔ تو برای بخشایش است، و فراهم آوردن توجیهی برای تو تا آن را از یاد ببری. این وسوسه‌ای است برای ترک گفتن خداوند* و فرزندش* با گرفتن ظاهری جسمانی. این همان چیز است که چشمان بدن به آن می‌نگرند.

هیچ چیزی که به نظر می‌رسد چشمان بدن می‌بینند، نمی‌تواند جز شکلی از وسوسه باشد، زیرا این قصد وجودی خود بدن بوده است. اما ما آموخته‌ایم که روح‌القدس* استفاده‌ای دیگر برای همه‌ی اوهامی دارد که تو ساخته‌ای، و اینچنین او قصد دیگری را در آن‌ها می‌بیند. برای روح‌القدس*، این دنیا مکانی است که تو می‌آموزی خود را از بابت آنچه گناهانت می‌پنداری، ببخشی. در این ادراک، ظاهر جسمانیِ وسوسه، به تشخیص معنوی رستگاری تبدیل می‌شود.

اگر بخواهیم این چند درس آخر را مرور کنیم، وظیفهٔ تو در اینجا این است که نور دنیا باشی، وظیفه‌ای که توسط خداوند* به تو عطا شده است. فقط تکبر نفس است که تو را به زیر سوال بردن این موضوع هدایت می‌کند، و فقط ترس نفس است که موجب می‌شود تو خودت را برای وظیفه‌ای که توسط خود خداوند* برایت مقرر شده است، ناشایسته ببینی. رستگاری این دنیا در انتظار بخشایش تو است، زیرا از این طریق فرزند* خداوند* از تمامی اوهام، و بنابراین همهٔ وسوسه‌ها نجات می‌یابد. فرزند* خداوند*، تو هستی.

تنها با انجام آن وظیفه‌ای که خداوند* به تو داده است، شاد خواهی بود. این به این دلیل است که وظیفهٔ تو شاد بودن است با استفاده از ابزاری که توسط آن شادمانی اجتناب‌ناپذیر می‌شود. هیچ راه دیگری وجود ندارد. پس، هر زمان تو انتخاب می‌کنی که آیا وظیفهٔ خود را انجام بدهی یا نه، واقعاً انتخاب می‌کنی که آیا شاد باشی یا نه.

بیایید امروز این را به یاد داشته باشیم. بیایید در صبحگاه و دوباره در شامگاه، و نیز در تمام طول روز این را به خودمان یادآوری کنیم. خود را پیشاپیش برای همه‌ی تصمیماتی که خواهی گرفت آماده کن، با به یاد داشتن این که تمامی آن‌ها در واقع بسیار ساده هستند. هر یک از این تصمیمات یا به شادمانی و یا به ناشادمانی منجر خواهد شد. آیا گرفتن چنین تصمیم ساده‌ای واقعاً می تواند دشوار باشد؟ اجازه نده شکل ظاهری تصمیم فریبت دهد. پیچیده بودن شکل ظاهری نشانگر پیچیده بودن محتوی نیست. ناممکن است که هیچ تصمیمی بر زمین بتواند محتوایی متفاوت با همین یک انتخاب ساده داشته باشد. این تنها انتخابی است که روح‌القدس* می‌بیند. بنابراین، تنها انتخابی است که وجود دارد.

پس، بیایید امروز، با این اندیشه‌ها تمرین کنیم: باشد تا من وظیفه‌ام را فراموش نکنم. باشد تا تلاش نکنم وظیفهٔ خودم را جایگزین وظیفهٔ خداوند* کنم. باشد تا ببخشم و شاد باشم. امروز حداقل در یک نوبت ده تا پانزده دقیقه را برای اندیشیدن به این ایده با چشمان بسته اختصاص بده. افکار مرتبط برای کمک کردن به تو خواهند آمد، اگر تو اهمیت تعیین کننده‌ی وظیفه‌ی خود را برای خودت و برای این دنیا به یاد داشته باشی.

در تمرینات مکرر ایده‌ی امروز در طول روز، چند دقیقه را به مرور این اندیشه‌ها و سپس اندیشیدن در مورد آن‌ها و نه در مورد هیچ چیز دیگر، اختصاص بده. این کار دشوار خواهد بود، خصوصاً در آغاز، زیرا تو در انضباط ذهنی که مستلزم این نوع اندیشیدن است خبره نیستی. ممکن است نیاز داشته باشی برای کمک به تمرکز خود جمله‌ی «باشد تا من وظیفه‌ام را فراموش نکنم» را بارها تکرار کنی.

دو شکل از برنامه‌های کوتاه‌تر تمرین کوتاه لازم است. گاه تمرین‌ها را با چشمان بسته انجام بده، با تلاش برای تمرکز بر روی افکاری که به کار می‌بری. در نوبت‌های دیگر تمرین، چشمانت را پس از مرور افکار گشوده نگه دار، سپس به آرامی و بدون انتخاب به پیرامونت نگاه کن در حالی که به خودت می‌گویی: این دنیایی است که وظیفهٔ من نجات آن است.', 'https://acim-farsi.org/workbook/lesson/64', 'https://acim-farsi.org/audio/workbook/lesson/64.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (65, 'تنها وظیفه‌ی من، آن است که خداوند* به من عطا کرد.', 'تمرین کوتاه‌تر:

تنها وظیفه‌ی من، آن وظیفه است که خداوند* به من عطا کرد. من هیچ وظیفه‌ی دیگری نمی‌خواهم و هیچ وظیفه‌ی دیگری ندارم.

تمرین طولانی‌تر:

تنها وظیفه‌ی من، آن وظیفه است که خداوند* به من عطا کرد.

افکار را مشاهده کن ………

این فکر هدفی را منعکس می‌کند که مرا از پذیرش تنها وظیفه‌ام باز ‌می‌دارد.

باشد تا بر این لوح پاک، وظیفه‌ی حقیقی من برایم نوشته شود.', 'تنها وظیفه‌ی من، آن است که خداوند* به من عطا کرد.

ایده‌ی امروز، تعهد تو را برای رستگاری باز تصریح می‌کند. همچنین به تو یادآوری می‌کند که هیچ وظیفه‌ای غیر از این نداری. آشکار است که هر دوی این اندیشه‌ها برای یک تعهد کامل ضروری هستند. مادامی که تو هنوز اهداف دیگری را می‌پروری، رستگاری نمی‌تواند تنها هدفی باشد که حفظ می‌کنی. پذیرش کاملِ رستگاری به عنوان تنها وظیفه‌ی تو الزاماً شامل دو مرحله می‌شود: تشخیص رستگاری به عنوان وظیفه‌ی خود، و صرفنظر کردن از همه‌ی اهداف دیگری که برای خودت ابداع کرده‌ای.

این تنها شیوه‌ای است که تو از طریق آن می‌توانی جایگاه شایسته خود را در بین نجات دهندگان این دنیا بدست آوری. این تنها شیوه‌ای است که تو از طریق آن می‌توانی چنین بگویی و چنین بخواهی که «تنها وظیفه‌ی من، آن است که خداوند* به من عطا کرد.» این تنها شیوه‌ای است که تو از طریق آن می‌توانی صلح درون را بیابی.

امروز و در چند روز آینده، ده تا پانزده دقیقه را برای یک برنامه‌ی تمرین مداوم اختصاص بده، در آن برنامه‌ی تمرین تلاش کن بفهمی و بپذیری که ایده‌ی آن روز واقعاً چه معنایی دارد. ایده‌ی امروز به تو گریز از همه‌ی دشواری‌هایی که ادراک می‌کنی، عرضه می‌کند. این ایده کلید را بر دروازه‌ی صلح می‌گذارد، دروازه‌ای که تو با دستان خود به روی خودت بسته‌ای. این ایده پاسخ همه‌ی جستجوهایی را که از آغاز زمان انجام داده‌ای، به تو عطا می‌کند.

در صورت امکان تلاش کن تا برنامه‌های طولانی‌تر تمرین روزانه را هر روز تقریباَ در همان زمان انجام دهی. همچنین سعی کن این زمان را پیشاپیش مشخص کنی و سپس به آن تا اندازه‌ی ممکن متعهد شوی. قصد این است که روز خود را چنان تنظیم کنی که در کنار همه‌ی مقاصد و اهداف ناچیزی که دنبال خواهی کرد، زمانی را برای خداوند* کنار گذاشته باشی. این بخشی از آن تعلیم منضبط درا‌ز‌مدت است که ذهن تو نیاز دارد. آنچنان که روح‌القدس* بتواند برای قصدی که با تو سهیم است، بطور مداوم از آن استفاده کند.

برای تمرین‌های طولانی‌تر، با مرور ایده‌ی روز آغاز کن. سپس چشمانت را ببند، ایده را یک بار دیگر برای خود تکرار کن، و با دقت ذهنت را نظاره کن تا بتوانی هر فکری را که از آن می‌گذرد دریابی. ابتدا هیچ تلاشی برای تمرکز بر پندارهای مرتبط با ایده‌ی روز به عمل نیاور. در عوض، سعی کن هر فکری را که در تداخل با آن برانگیخته می‌شود، آشکار کنی. به هر یک زمانی که برایت پیش می‌آید توجه کن، با درگیری یا نگرانیِ تا حد ممکن اندک، و هر یک را با گفتن جمله‌ی زیر به خودت رها کن: این فکر هدفی را منعکس می‌کند که مرا از پذیرش تنها وظیفه‌ام باز ‌می‌دارد.

پس از مدت کوتاهی، یافتن افکار مداخله‌گر سخت‌تر خواهد شد. اما تلاش کن حدود یک دقیقه بیشتر ادامه دهی، در حالی که سعی می‌کنی تعدادی از افکار بیهوده را که قبلاً از توجه تو گریخته‌اند، دریابی، اما در این کار به خودت فشار نیاور یا تلاش غیرضروری به خرج نده. سپس به خودت بگو: باشد تا بر این لوح پاک، وظیفه‌ی حقیقی من برایم نوشته شود. نیازی نیست که دقیقاً از این کلمات استفاده کنی، اما سعی کن به احساس اراده‌مندی برای این مهم دست پیدا کنی که اوهام تو در مورد هدف، با حقیقت جایگزین شوند.

در پایان، ایده‌ی امروز را یک بار دیگر تکرار کن و باقی برنامه‌ی تمرین را به تلاش برای تمرکز بر اهمیت این ایده برای خودت اختصاص دهی، بر تسکینی که پذیرش این ایده برایت به ارمغان خواهد آورد متمرکز شو، تسکینی که نتیجه‌ی حل کردن تعارض‌های تو یکباره و برای همیشه است، و با وجود ایده‌های احمقانه‌ی مخالفی که داری، بر شدت واقعی خواست خود برای رستگاری متمرکز شو.

در برنامه‌های کوتاه‌تر تمرین، که حداقل باید یک نوبت در هر ساعت انجام شود، از این شکل در تمرین با ایده‌ی امروز استفاده کن: تنها وظیفه‌ی من، آن وظیفه است که خداوند* به من عطا کرد. من هیچ وظیفه‌ی دیگری نمی‌خواهم و هیچ وظیفه‌ی دیگری ندارم. در زمان تمرین با این ایده، گاه چشمانت را ببند و گاه آن‌ها را بگشای و به پیرامون خود نگاه کن. این چیزی که اکنون می‌بینی، همان است که وقتی ایده‌ی امروز را کاملاً بپذیری، به کلی تغییر خواهد کرد.', 'https://acim-farsi.org/workbook/lesson/65', 'https://acim-farsi.org/audio/workbook/lesson/65.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (66, 'شادمانی‌ام و وظیفه‌ام یکی هستند.', 'تمرین کوتاه‌تر:

شادمانی و وظیفهٔ من یکی هستند، زیرا خداوند* هر دو را به من عطا کرده است.

تمرین طولانی‌تر:

خداوند* به من تنها شادمانی عطا می‌کند.
او* وظیفه‌ام را به من عطا کرده است.
پس وظیفهٔ من باید شادمانی باشد.', 'شادمانی‌ام و وظیفه‌ام یکی هستند.

مطمئناً در طول این درس‌های اخیر، متوجه تأکید ما بر اتصال بین به انجام رساندن وظیفه‌ی خود و دستیابی به شادمانی شده‌ای. دلیل این است که تو واقعاً این اتصال را نمی‌بینی. اما چیزی بیش از اتصال بین این دو وجود دارد: آن‌ها با هم یکی هستند. شکل آن‌ها متفاوت است، اما محتوایشان کاملاً یکی است.

نفس بر سر این پرسش بنیادین که وظیفهٔ تو چیست با روح‌القدس* مدام در نبرد است. و همین‌گونه بر سر این که شادمانی تو چیست با روح‌القدس* مدام در نبرد است. این یک نبرد دوطرفه نیست. نفس حمله می‌کند و روح‌القدس* پاسخ نمی‌دهد. او* می‌داند که وظیفهٔ تو چیست. او* می‌داند که آن شادمانی تو است.

امروز ما تلاش خواهیم کرد تا از این نبرد کاملاً بی‌معنا عبور کنیم و به حقیقت در مورد وظیفه‌ی تو دست یابیم. ما خود را در مشاجرات احمقانه در مورد این که این وظیفه چیست درگیر نخواهیم کرد. ما خود را نومیدانه به تعریف کردن شادمانی و تعیین کردن وسایل دستیابی به آن مشغول نخواهیم کرد. ما با گوش کردن به حملات نفس برعلیه حقیقت، آن را نخواهیم پرورد. ما صرفاً خوشحال خواهیم بود از این که می‌توانیم کشف کنیم حقیقت چیست.

امروز قصد برنامه‌های طولانی‌تر تمرین ما، پذیرش این واقعیت توسط تو است که نه تنها یک اتصال بسیار واقعی بین وظیفه‌ای که خداوند* به تو عطا کرد و شادمانی تو وجود دارد، بلکه آن‌ها عملاً یکی هستند. خداوند* به تو فقط شادمانی عطا می‌کند. پس وظیفه‌ای که او* به تو عطا کرد نیز باید شادمانی باشد، حتی اگر ظاهراً متفاوت باشد. تمرین‌های امروز تلاشی هستند برای فراتر رفتن از این تفاوت‌های ظاهری، و تشخیص دادن یک محتوای مشترک که در حقیقت وجود دارد.

برنامهٔ تمرین ده تا پانزده دقیقه‌ای را با مرور این اندیشه‌ها آغاز کن: خداوند* به من تنها شادمانی عطا می‌کند. او* وظیفه‌ام را به من عطا کرده است. پس وظیفهٔ من باید شادمانی باشد. سعی کن منطق را در این ترتیب ببینی، حتی اگر هنوز نتیجه را نمی‌پذیری. تنها در صورتی که دو اندیشهٔ نخست نادرست باشند، نتیجه می‌تواند نادرست باشد. پس، بیایید، در حالی که تمرین می‌کنیم، مدت کوتاهی در مورد این فرض‌ها بیندیشیم.

فرض اول این است که خداوند* به تو فقط شادمانی عطا می‌کند. البته این می‌توانست نادرست باشد، اما برای نادرست بودن آن لازم است خداوند* را چیزی تعریف کنیم که نیست. عشق نمی‌تواند شر عطا کند، و آنچه شادمانی نیست شر است. خداوند* نمی‌تواند چیزی را عطا کند که ندارد، و نمی‌تواند چیزی را داشته باشد که نیست. اگر اینگونه نباشد که خداوند* به تو فقط شادمانی می‌دهد، او* باید شر باشد. و اگر تو نخستین فرض را نپذیری، به این تعریف از او* باور داری.

فرض دوم این است که خداوند* وظیفه‌ی تو را به تو عطا کرده است. ما دیده‌ایم که فقط دو بخش در ذهن تو وجود دارد. یک بخش توسط نفس حکمفرمایی می‌شود، و از اوهام ساخته شده است. بخش دیگر منزلگاه روح‌القدس* است، که حقیقت در آن سکنی دارد. هیچ راهنمایی جز این دو برای برگزیدن وجود ندارد. و هیچ نتیجه‌ای در ازای انتخاب تو ممکن نیست جز دو نتیجه: ترس که همیشه نفس آبستن آن است، و عشق که روح‌القدس* برای جایگزین کردن ترس به تو عرضه‌اش می‌کند.

از این رو باید چنین باشد که وظیفه‌ی تو یا توسط خداوند* از طریق آوای* او* استوار می‌شود، یا توسط نفس که تو آن را جایگزین خداوند* کرده‌ای ساخته می‌شود. کدام یک حقیقت است؟ اگر خداوند* وظیفه‌ی تو را به تو نداد، این وظیفه باید هدیه‌ی نفس باشد. آیا نفس واقعاً هدیه ای برای دادن دارد، در حالی که خودش یک وهم است و تنها وهم را برای هدیه دادن دارد؟

امروز در طول برنامه‌های تمرین طولانی‌تر در این مورد بیندیش. همچنین در مورد شکل‌های متعددی که وهم تو در مورد وظیفه‌ات در ذهن به خود می‌گیرد، و نیز در مورد شیوه‌های متعدد تلاش خود برای یافتن رستگاری با هدایت نفس. آیا آن را یافتی؟ آیا شادمان بودی؟ آیا این شیوه‌ها برایت صلح در پی داشته‌اند؟ امروز نیاز به صداقت بسیار زیادی داریم. نتایج را خوب به یاد بیاور، و نیز توجه کن که آیا اصلاً منطقی بوده است که از هیچ چیزی که نفس پیشنهاد می‌کند، انتظار شادمانی داشته باشی. اما نفس تنها جایگزین برای آوای* روح‌القدس* است.

تو یا به دیوانگی گوش خواهی داد یا حقیقت را خواهی شنید. سعی کن این انتخاب را در حالی انجام دهی که در مورد فرض‌هایی که استنتاج ما بر آن‌ها استوار است می‌اندیشی. ما می‌توانیم در این استنتاج سهیم شویم، اما نه در هیچ استنتاج دیگری. زیرا خود خداوند* آن را با ما سهیم می‌شود. ایده‌ی امروز یک گام غول‌‌آسای دیگر در ادراک کردن مشابه به عنوان مشابه و متفاوت به عنوان متفاوت است در یک طرف همه‌ی اوهام ایستاده‌اند. همه‌ی حقیقت در سوی دیگر ایستاده‌ است. بیایید امروز تلاش کنیم تشخیص دهیم که تنها حقیقت حقیقی است.

امروزدر برنامه‌های کوتاه‌تر تمرین، که مفیدتر خواهد بود اگر دو نوبت در هر ساعت انجام شود، این شکل از تمرین را پیشنهاد می‌شود: شادمانی و وظیفهٔ من یکی هستند، زیرا خداوند* هر دو را به من عطا کرده است. بیش از یک دقیقه طول نخواهد کشید و شاید حتی کم‌تر، که این کلمات را به آرامی تکرار کنی و در مورد آن‌ها زمانی که آن‌ها را می‌گویی برای مدت کوتاهی بیندیشی.', 'https://acim-farsi.org/workbook/lesson/66', 'https://acim-farsi.org/audio/workbook/lesson/66.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (67, 'عشق مرا همانند خودش آفرید.', 'تمرین کوتاه‌تر:

عشق مرا همانند خودش آفرید.

تمرین طولانی‌تر:

قداست، مرا قدسی آفرید.
مهربانی مرا مهربان آفرید.
شفقت مرا شفیق آفرید.
کمال مرا کامل آفرید.', 'عشق مرا همانند خودش آفرید.

ایده‌ی امروز بیان کامل و دقیق چیزی است که تو هستی. به این علت است که تو نور دنیا هستی. به این علت است که خداوند* تو را به عنوان نجات دهنده‌ی دنیا منصوب کرد. به این علت است که فرزند* خداوند* برای رستگاری خویش به تو می‌نگرد. او توسط آنچه تو هستی نجات می‌یابد. ما امروز تمام تلاش خود را به کار خواهیم برد تا به این حقیقت درمورد تو برسیم ، و کاملاً تشخیص دهیم، حتی برای یک لحظه، که این حقیقت است.

در برنامه‌های طولانی‌تر تمرین، ما درمورد واقعیت تو و ماهیت تماماً تغییر نیافته و تغییرناپذیر آن خواهیم اندیشید. ما با تکرار کردن این حقیقت درباره‌ی تو آغاز خواهیم کرد، و سپس چند دقیقه را برای اضافه کردن برخی اندیشه‌های مرتبط صرف خواهیم نمود، مانند اندیشه‌های زیر: قداست، مرا قدسی آفرید. مهربانی مرا مهربان آفرید. شفقت مرا شفیق آفرید. کمال مرا کامل آفرید. هر صفتی که با خداوند* همراه است و او* خود را آنگونه تعریف می‌کند، برای استفاده مناسب است. ما امروز تلاش می‌کنیم تا تعریف تو را از خداوند* فروبریزیم و آن را با تعریف خود او* جایگزین کنیم. همچنین ما در تلاش هستیم تأکید کنیم که تو بخشی از تعریف او* از خودش هستی.

پس از این که چندین اندیشه‌ی اینچنینی مرتبط را مرور کردی، سعی کن همه‌ی اندیشه‌ها را برای فاصله‌ی زمانی کوتاه آمادگی خود رها کنی، و سپس سعی کن از همه‌ی تصویرها و پیش‌درک‌ها درمورد خودت به سمت حقیقت درونت عبور کنی. اگر عشق تو را همانند خودش آفرید، این خویشتن* باید در تو وجود داشته باشد. و این خویشتن* جایی در ذهنت برای تو هست، تا آن* را بیابی.

ممکن است برای تو ضروری باشد که ایده‌ی امروز را گهگاه تکرار کنی، تا جایگزین پندارهای آشفته شود. همچنین ممکن است متوجه شوی که این کافی نیست، و تو نیاز داری با اضافه کردن اندیشه‌های دیگرِ مرتبط با حقیقت در مورد خودت، به تمرین ادامه دهی. اما احتمالاً موفق خواهی شد تا از آن عبور کنی، و از درون فاصله‌ی بی‌فکری به آگاهی از نور درخشنده ای برسی که در آن خودت را همچون عشقی می‌شناسی که تو را آفرید. مطمئن شو که امروز تلاش زیادی خواهی کرد تا آن آگاهی را نزدیک‌تر بیاوری، چه احساس موفقیت داشته باشی و چه نداشته باشی‌.

خصوصاً امروز مفید است که با ایده‌ی روز به هر تعداد دفعات ممکن کار کنی. تو نیاز داری که حقیقت را درمورد خودت به دفعات ممکن بشنوی، زیرا ذهن تو بسیار با خود-انگاره‌های باطل مشغول است. چهار یا پنج مرتبه در هر ساعت، و شاید حتی بیشتر، بسیار مفید خواهد بود اگر به خودت یادآور شوی که عشق تو را همانند خودش آفرید. حقیقت را در مورد خودت در این جمله بشنو.

در برنامه‌های تمرین کوتاه‌تر تلاش کن تشخیص دهی که این آوای ناچیز منفرد تو نیست که این جمله را به تو می‌گوید . این آوای* برای خداوند* است، که پدرت* و خویشتن* تو را به یادت می‌آورد. این آوای* حقیقت است، که همه‌ی چیزهایی را که نفس به تو درمورد خودت می‌گوید، با حقیقت ساده در مورد فرزند* خداوند* جایگزین می‌کند. تو توسط عشق همانند خودش آفریده شدی.', 'https://acim-farsi.org/workbook/lesson/67', 'https://acim-farsi.org/audio/workbook/lesson/67.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (68, 'عشق هیچ گلایه‌ای را نگه نمی‌دارد.', 'تمرین کوتاه‌تر:

برای افکار گلایه‌آمیز: عشق هیچ گلایه‌ای را نگه نمی‌دارد. بگذار خویشتن* خود را فریب ندهم.

چند بار در هر ساعت: عشق هیچ گلایه‌ای را نگه نمی‌دارد. من می‌خواهم با کنار گذاشتن همه‌ی گلایه‌هایم و بیدار شدن در او*، به خویشتنم* بیدار شوم.

تمرین طولانی‌تر:

من می‌خواهم تو را دوست خودم ببینم، تا بتوانم به یاد داشته باشم تو بخشی از من هستی و خودم را بشناسم.

عشق هیچ گلایه‌ای را نگه نمی‌دارد. زمانی که همه‌ی گلایه‌هایم را رها کنم خواهم دانست که کاملاً در امنیت هستم.', 'عشق هیچ گلایه‌ای را نگه نمی‌دارد.

تو که توسط عشق همانند خودش آفریده شدی، نمی‌توانی در عین نگه داشتن هرگونه گلایه‌ای، خویشتن* خود را بشناسی. نگه داشتن یک گلایه یعنی از یاد بردن این که تو چه کسی هستی. نگه داشتن یک گلایه یعنی دیدن خودت به عنوان یک بدن. نگه داشتن یک گلایه یعنی اجازه دادن به نفس تا بر ذهن تو حکمفرمایی کند، و محکوم کردن بدن به مرگ. احتمالاً تو هنوز به طور کامل تشخیص نمی‌دهی که نگه داشتن گلایه‌‌ها دقیقاً با ذهنت چه می‌کند. به نظر می‌رسد که این کار تو را از سرچشمهٔ* تو جدا کرده و با او* ناهمانند می‌کند. این کار باعث می‌شود باور کنی که او* همانند آن چیزی است که تو می‌پنداری به آن تبدیل شده‌ای، زیرا هیچکس نمی‌تواند آفریدگارش* را ناهمانند با خودش ادراک کند.

با گسستن از خویشتن* خود، که از همانندی با آفریدگارش* آگاه می‌ماند، به نظر می‌رسد که خویشتن* تو در خواب است. در حالی که آن بخش از ذهن تو که اوهام را در خواب خود می‌بافد، ظاهراً بیدار است. آیا همه‌ی این‌ها می‌توانند از نگه داشتن گلایه‌ها ایجاد شوند؟ آه، بله! زیرا آن کس که گلایه‌ها را نگه می‌دارد، نادیده می‌گیرد که توسط عشق آفریده شده، و آفریدگارش* برای او در رؤیای نفرتش، ترسناک گشته است. چه کسی می‌تواند در رؤیای نفرت باشد و از خداوند* نترسد؟

یقین داریم آنان که گلایه‌ها را نگه می‌دارند، خداوند* را در تصویر ذهنی خود بازتعریف می‌کنند، به همان اندازه که مطمئن هستیم خداوند* آنان را مانند خودش* آفرید، و آنان را به عنوان بخشی از خودش* تعریف کرد. یقین داریم آنان که گلایه‌ها را نگه می‌دارند از احساس گناه رنج خواهند برد، به همان اندازه که مطمئن هستیم آنان که می‌بخشند صلح را خواهند یافت. یقین داریم آنان که گلایه‌ها را نگه می‌دارند از یاد خواهند برد که چه کسی هستند، به همان اندازه که مطمئن هستیم آنان که می‌بخشند این را به یاد خواهند آورد.

اگر باور داشته باشی که تمام آنچه گفتیم صحیح است، آیا اراده نمی‌کنی که گلایه‌های خود را رها کنی؟ احتمالاً فکر نمی‌کنی که می‌توانی گلایه‌های خود را رها کنی. اما موضوع ساده‌ی انگیزه در میان است. امروز تلاش خواهیم کرد تا دریابیم تو بدون این گلایه‌ها چه احساسی خواهی داشت. اگر حتی کوچک‌ترین توفیقی داشته باشی، دیگر هرگز با انگیزه‌ی خود هیچ مشکلی نخواهی داشت.

برنامه‌ی تمرین طولانی‌تر امروز را با جستجو کردن ذهنت برای کسانی آغاز کن که تو از آنان، آنچه را که گلایه عمیق می‌دانی نگه داشته‌ای. برخی از این افراد بسیار آسان پیدا می‌شوند. سپس در مورد گلایه‌های ظاهراً کوچک خود از آنان که دوستشان داری و حتی می‌پنداری که عاشقشان هستی، بیندیش. سریعاً آشکار خواهد شد که هیچکس وجود ندارد که تو از او به نحوی گلایه‌هایی را نپرورده باشی. این تو را در همه‌ی این کائنات که در ادراک تو از خودت وجود دارد، تنها رها کرده است.

اینک مصمم شو که همه‌ی این افراد را به عنوان دوست ببینی. به همه‌ی آن‌ها بگو، در حالی که به هر یک به نوبت می‌اندیشی: من می‌خواهم تو را دوست خودم ببینم، تا بتوانم به یاد داشته باشم تو بخشی از من هستی و خودم را بشناسم. باقی برنامه‌ی تمرین را با تلاش برای اندیشیدن به خودت در صلح کامل با همه کس و همه چیز صرف کن، با احساس امنیت در دنیایی که از تو محافظت می‌کند و به تو عشق می‌ورزد، و تو متقابلاً به آن عشق می‌ورزی. سعی کن امنیتی را احساس کنی که تو را احاطه می‌کند، برفراز تو شناور است و تو را بالا نگه می‌دارد. سعی کن باور کنی، ولو برای مدتی کوتاه، که هیچ چیز نمی‌تواند به هیچ شکلی به تو آسیب برساند. در پایان برنامه‌ی تمرین به خود بگو: عشق هیچ گلایه‌ای را نگه نمی‌دارد. زمانی که همه‌ی گلایه‌هایم را رها کنم خواهم دانست که کاملاً در امنیت هستم.

برنامه‌های تمرین کوتاه مدت باید شامل تمرین سریعی با ایده‌ی امروز در شکل زیر باشد، در هر زمان که هر فکری از گلایه در مورد هر کسی که ممکن است حضور داشته باشد یا خیر، پیش بیاید: عشق هیچ گلایه‌ای را نگه نمی‌دارد. بگذار خویشتن* خود را فریب ندهم. بعلاوه ایده‌ی امروز را هر ساعت چندین بار در این شکل تکرار کن: عشق هیچ گلایه‌ای را نگه نمی‌دارد. من می‌خواهم با کنار گذاشتن همه‌ی گلایه‌هایم و بیدار شدن در او*، به خویشتنم* بیدار شوم.', 'https://acim-farsi.org/workbook/lesson/68', 'https://acim-farsi.org/audio/workbook/lesson/68.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (69, 'گلایه‌های من نور این دنیا را در من پنهان می‌کنند.', 'گلایه‌های من، نور این دنیا را در من پنهان می‌کنند. من نمی‌توانم چیزی را ببینم که پنهان کرده‌ام. اما می‌خواهم اجازه دهم بر من آشکار شود، برای رستگاری خودم و رستگاری این دنیا.

اگر این گلایه را نگه دارم، نور دنیا از من پنهان خواهد ماند، اگر امروز وسوسه شدی که چیزی را علیه ‌کسی نگه داری.

اگر این گلایه را نگه دارم، نور دنیا از من پنهان خواهد ماند، اگر امروز وسوسه شدی که چیزی را علیه ‌کسی نگه داری.', 'گلایه‌های من نور این دنیا را در من پنهان می‌کنند.

هیچ‌کس نمی‌تواند به آنچه گلایه‌های تو پنهان می‌کنند، نظر کند. زیرا گلایه‌های تو نور این دنیا را در تو پنهان می‌کنند، هرکس در تاریکی می‌ایستد، و تو در کنار او می‌ایستی. اما زمانی که حجاب گلایه‌های تو برداشته شود، تو به همراه او رها می‌شوی. اینک رستگاری خود را با او سهیم شو، او که زمانی که در جهنم بودی، کنارت ایستاد. او در نور این دنیا برادر تو است، نوری که هردوی شما را نجات می‌دهد.

بیایید امروز تلاش واقعی دیگری داشته باشیم برای رسیدن به نور در تو. پیش از آن که در برنامه‌های تمرین طولانی‌تر خود به این بپردازیم، بیایید چند دقیقه را به تفکر در مورد کاری اختصاص دهیم که برای انجامش تلاش می‌کنیم. ما دقیقاً در تلاش هستیم تا رستگاری این دنیا را لمس کنیم. ما در تلاش هستیم تا از پس پرده‌ی تیرگی که آن را مخفی نگه می‌دارد، ببینیم. ما در تلاش هستیم اجازه دهیم تا این حجاب برداشته شود، و ببینیم که اشک‌های فرزند* خداوند* در نور خورشید ناپدید می‌شوند.

بیایید امروز برنامه‌های طولانی‌تر تمرین را با درک کامل این موضوع آغاز کنیم که چنین است، با تصمیم واقعی برای رسیدن به آن‌چه برای ما از همه چیز دیگر عزیزتر است. رستگاری تنها نیاز ما است. اینجا هیچ هدف دیگر و هیچ وظیفه‌ی دیگری برای به انجام رساندن وجود ندارد. آموختن رستگاری تنها هدف ما است. بیایید امروز این جستجوی دیرین را با یافتن نور در درونمان، و با برافراشتن آن برای هر کسی که با ما در جستجو است به پایان ببریم، تا آنان نیز به آن نظر کنند و به وجد بیایند.

حال در سکوت عمیق، با چشمان بسته، سعی کن همه‌ی آن محتوایی را که معمولاً خودآگاهی‌ات را اشغال می‌کند، رها کنی. به ذهن خود مانند یک حلقه‌ی عظیم بیندیش، که توسط لایه‌ای از ابرهای سنگین تیره احاطه شده است. تو تنها می‌توانی ابرها را ببینی زیرا به نظر می‌رسد که بیرون از حلقه و کاملاً جدا از آن ایستاده‌ای.

از جایی که تو ایستاده‌ای، هیچ دلیلی نمی‌بینی که باور کنی نور درخشانی توسط ابرها پنهان شده است. به نظر می‌رسد که ابرها تنها واقعیت هستند. به نظر می‌رسد که آن‌ها تنها چیزهایی هستند که برای دیدن وجود دارند. بنابراین، تو سعی نمی‌کنی از آن‌ها عبور کنی و بگذری، و این واقعاً تنها روش برای قانع کردن تو به این است که آن‌ها فاقد ماهیت هستند. ما امروز این تلاش را به عمل خواهیم آورد.

درباره‌ی اهمیت کاری که سعی داری برای خودت و دنیا انجام دهی، اندیشه کن، سپس تلاش کن در سکون کامل آرام بگیری، و فقط به یاد بیاوری که امروز چقدر دلت می‌خواهد که به نور درونت برسی، همین حالا! مصمم شو که از ابرها عبور کنی. در ذهنت به آن‌ها برس و لمسشان کن. آن‌ها را با دست خود کنار بزن؛ همچنان که از درون آن‌ها عبور می‌کنی، تماسشان را با گونه‌ها و پیشانی و پلک‌های خود احساس کن. پیش برو؛ ابرها نمی‌توانند تو را متوقف کنند.

اگر این تمرین‌ها را به خوبی انجام دهی، آغاز خواهی کرد به داشتن حسی از بالا کشیده شدن و به پیش برده شدن. تلاش اندک و تصمیم کوچک تو، قدرت کائنات را برای کمک به تو فرامی‌خواند، و خود* خداوند* تو را از تاریکی به درون نور بالا خواهد کشید. تو در هماهنگی با ارادهٔ* او* هستی. قطعاً شکست نمی‌خوری، زیرا اراده‌ی تو به او* تعلق دارد.

امروز به پدر* خود* اعتماد کن، و مطمئن باش که او* تو را شنیده است و به تو پاسخ می‌دهد. ممکن است هنوز پاسخ او* را نشناسی، اما حقیقتاً می‌توانی مطمئن باشی که به تو عطا شده و سرانجام آن را دریافت می‌کنی. حالی که در تلاش برای گذشتن از درون ابرها به سوی نور هستی، سعی کن این اعتماد را در ذهن خود نگه داری. سعی کن به یاد داشته باشی که تو سرانجام در حال اتصال ارادهٔ خود به ارادهٔ* خداوند* هستی. سعی کن این اندیشه را به وضوح در ذهن داشته باشی که آن‌چه به همراه خداوند* بر عهده می‌گیری، قطعاً موفق می‌شود. پس اجازه بده که قدرت خداوند* در تو و از طریق تو کار کند، و ارادهٔ* او* و تو عملی شود.

در برنامه‌های تمرین کوتاه‌تر، که با توجه به اهمیت ایده‌ی امروز برای خود و شادمانی‌ات مایل خواهی بود به دفعات ممکن تکرار کنی، به خودت یادآوری کن که گلایه‌های تو در حال پنهان کردن نور این دنیا از آگاهی تو هستند. همچنین به خودت یادآور شو که تو در جستجوی آن نور تنها نیستی، و این که واقعاً می‌دانی کجا به دنبالش بگردی. سپس بگو: گلایه‌های من، نور این دنیا را در من پنهان می‌کنند. من نمی‌توانم چیزی را ببینم که پنهان کرده‌ام. اما می‌خواهم اجازه دهم بر من آشکار شود، برای رستگاری خودم و رستگاری این دنیا. همچنین، مطمئن شو که به خودت می‌گویی: اگر این گلایه را نگه دارم، نور دنیا از من پنهان خواهد ماند، اگر امروز وسوسه شدی که چیزی را علیه ‌کسی نگه داری.', 'https://acim-farsi.org/workbook/lesson/69', 'https://acim-farsi.org/audio/workbook/lesson/69.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (70, 'رستگاری من از من سرچشمه می‌گیرد.', 'تمرین کوتاه‌تر:

رستگاری من از من سرچشمه می‌گیرد. هیچ چیزی بیرون از من نمی‌تواند مانع من شود. در درون من، رستگاری دنیا و رستگاری خودم حضور دارد.

تمرین طولانی‌تر:

رستگاری من از من سرچشمه می‌گیرد. رستگاری من نمی‌تواند از هیچ جای دیگری سرچشمه بگیرد.

برخی از جاهای بیرونی را که در آن‌ها به دنبال رستگاری بوده‌ای مرور کن ………

رستگاری من نمی‌تواند از هیچ‌یک از این چیزها سرچشمه بگیرد.
رستگاری من از من و فقط از من سرچشمه می‌گیرد.', 'رستگاری من از من سرچشمه می‌گیرد.

همه‌ی وسوسه‌ها چیزی نیستند جز شکل‌هایی از یک وسوسه‌ی بنیادین که ایده‌ی امروز را باور نکنی. چنین به نظر می‌رسد که رستگاری از جایی جز تو سرچشمه می‌گیرد. اینچنین، نیز، خاستگاه احساس گناه به نظر می‌رسد. تو هم احساس گناه و هم رستگاری را به عنوان چیزی در ذهن خود می‌بینی و نه در هیچ جای دیگر. زمانی که بفهمی همه‌ی احساس گناه صرفاً ابداع ذهن تو است، این را نیز می‌فهمی که احساس گناه و رستگاری باید در یک مکان واحد باشند. با درک این موضوع، تو نجات می‌یابی.

ظاهراً هزینه‌ی پذیرش ایده‌ی امروز این است: این ایده بدین معنا است که هیچ چیزی بیرون از خودت نمی‌تواند تو را نجات دهد؛ هیچ چیزی بیرون از خودت نمی‌تواند به تو صلح عطا کند. اما این ایده بدین معنا نیز هست که هیچ چیزی بیرون از خودت نمی‌تواند تو را آزار دهد، یا صلح تو را برهم زند، یا به هر شکلی تو را آشفته کند. ایده‌ی امروز جایگاه مسئول کائنات را به تو می‌دهد، جایی که تو به دلیل آنچه هستی، به آن تعلق داری. این نقشی نیست که بتواند به طور نسبی پذیرفته شود. و تو مطمئناً باید آغاز کنی به دیدن این که پذیرش این نقش، رستگاری است.

با این حال، شاید برای تو روشن نباشد که چرا تشخیص اینکه احساس گناه در ذهن خود تو است، موجب فهم این است که رستگاری نیز همانجا است. خداوند* هرگز چاره برای بیماری را در جایی قرار نمی‌دهد که نتواند کمک کند. این همان شیوه‌ای است که ذهن تو با آن عمل کرده است، اما ذهن* او* هرگز به این شکل عمل نمی‌کند. او* می‌خواهد که تو شفا یابی، بنابراین سرچشمهٔ* شفا را در جایی نگه داشته است که نیاز به شفا نهفته است.

تو با انجام هرگونه تلاش برای جدا کردن شفا از آن بیماری که شفا برایش مقرر شده، و بدین ترتیب حفظ بیماری از این طریق، سعی کرده‌ای تا درست خلاف این عمل کنی، هرچند این تلاش‌ها مغشوش و خیالی بوده‌اند. قصد تو این بوده که اطمینان یابی شفا رخ ندهد. قصد خداوند* این بوده که اطمینان یابد آن رخ دهد.

امروز ما این فهم را تمرین می‌کنیم که ارادهٔ* خداوند* و ارادهٔ ما در این مورد واقعاً یکی هستند. خداوند* می‌خواهد که ما شفا یابیم، و ما واقعاً نمی‌خواهیم که ناخوش باشیم، زیرا این ما را ناشاد می‌کند. بنابراین در پذیرش ایده‌ی امروز، ما واقعاً در توافق با خداوند* هستیم. او* نمی‌خواهد که ما ناخوش باشیم. ما هم نمی‌خواهیم. او* می‌خواهد که ما شفا یابیم. ما نیز همین را می‌خواهیم.

امروز برای دو برنامه‌ی تمرین طولانی‌تر آماده هستیم، که هر یک از این برنامه‌ها باید حدود ده تا پانزده دقیقه طول بکشد. اما، در عین حال، ما به تو اجازه می‌دهیم که برای زمان انجام تمرینات تصمیم بگیری. ما این شیوه‌ی تمرین را برای تعدادی از درس‌ها دنبال خواهیم کرد، و دوباره مناسب خواهد بود که پیشاپیش تصمیم بگیری بهتر است چه زمانی را به انجام هر تمرین اختصاص دهی، و سپس به تصمیمات خود تا حد ممکن پایبند بمانی.

این برنامه‌های تمرین را با تکرار کردن ایده‌ی امروز آغاز کن، با اضافه کردن جمله‌ای که حاکی از فهم تو در مورد این است که رستگاری از هیچ چیزی بیرون از خودت سرچشمه نمی‌گیرد. می‌توانی به این شیوه آن را بیان کنی: رستگاری من از من سرچشمه می‌گیرد. رستگاری من نمی‌تواند از هیچ جای دیگری سرچشمه بگیرد. سپس چند دقیقه را با چشمان بسته به مرور برخی از جاهای بیرونی اختصاص بده که قبلاً در آن‌ها به دنبال رستگاری گشته‌ای: - در افراد دیگر، در تملک‌ها، در شرایط و رویدادهای گوناگون، و در تصورات تو از خودت که برای واقعی نمودن آن‌ها تلاش کرده‌ای. تشخیص بده که رستگاری در آنجا وجود ندارد، و به خودت بگو: رستگاری من نمی‌تواند از هیچ‌یک از این چیزها سرچشمه بگیرد. رستگاری من از من و فقط از من سرچشمه می‌گیرد.

اینک ما دوباره تلاش خواهیم کرد تا به نور در درون تو دست یابیم، جایی که رستگاری تو هست. تو نمی‌توانی آن را درون ابرهایی که نور را احاطه می‌کنند بیابی، و درون آن‌ها به دنبالش گشته‌ای. در آنجا نیست. در آن سوی ابرها و در نورِ ورای آن‌ها است. به یاد داشته باش پیش از آن که بتوانی به نور برسی، ناگزیر هستی که از ابرها عبور کنی. اما این را نیز به یاد داشته باش که تو هرگز هیچ چیزی را در الگوهای ابرآلود نیافته‌ای، چیزهایی که تصور کردی این الگوها در خود دارند، یا چیزهایی که تو خواسته‌ای.

از آنجا که همه‌ی اوهام تو در مورد رستگاری شکست خورده‌اند، پس مطمئناً نمی‌خواهی در ابرها باقی بمانی، و آنجا بیهوده در پی خدایان دروغین بگردی، در حالی که بسیار آسان می‌توانی به درون نور رستگاری واقعی گام برداری. سعی کن با هر وسیله‌ای که دلخواه تو است از ابرها عبور کنی. اگر این کمکت می‌کند، به من بیندیش که دستت را گرفته‌ام و تو را هدایت می‌کنم. و من به تو اطمینان می‌دهم که این یک تخیل پوچ نخواهد بود.

امروز برای برنامه‌های تمرین کوتاه و مکرر، به خودت یادآور شو که رستگاری تو از تو سرچشمه می‌گیرد، و هیچ چیز جز پندارهای خودت نمی‌تواند مانع پیشرفت تو شود. تو از همه‌ی تداخلات بیرونی آزاد هستی. تو مسئول رستگاری‌ات هستی. تو مسئول رستگاری این دنیا هستی. پس، بگو: رستگاری من از من سرچشمه می‌گیرد. هیچ چیزی بیرون از من نمی‌تواند مانع من شود. در درون من، رستگاری دنیا و رستگاری خودم حضور دارد.', 'https://acim-farsi.org/workbook/lesson/70', 'https://acim-farsi.org/audio/workbook/lesson/70.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (71, 'تنها نقشهٔ خداوند* برای رستگاری به نتیجه خواهد رسید.', 'تمرین کوتاه‌تر:

نگه داشتن گلایه‌ها مخالف نقشهٔ خداوند* برای رستگاری است. و فقط نقشهٔ او* به نتیجه می‌رسد.

تمرین طولانی‌تر:

تو می‌خواهی که من چکار کنم ؟
تو می‌خواهی که من کجا بروم ؟
تو می‌خواهی که من چه بگویم، و به چه کسی ؟', 'تنها نقشهٔ خداوند* برای رستگاری به نتیجه خواهد رسید.

تو ممکن است تشخیص ندهی که نفس نقشه‌ای برای رستگاری در تضاد با نقشهٔ خداوند* کشیده است. تو به نقشه‌ی نفس باور داری. از آنجا که این نقشه در تضاد با نقشهٔ خداوند* است، تو به این نیز باور داری که پذیرش نقشهٔ خداوند* به جای نقشه‌ی نفس یعنی جهنمی شدن. البته این به نظر نامعقول می‌آید. اما پس از بررسی دقیق این که نقشه‌ی نفس چیست، احتمالاً خواهی فهمید که به آن باور داری، هر اندازه که نامعقول باشد.

نقشه‌ی نفس برای رستگاری گردِ مرکز نگه داشتن گلایه‌ها شکل می‌گیرد. این نقشه مدعی است که اگر شخص دیگری به طرز متفاوت سخن می‌گفت یا عمل می‌کرد، اگر برخی شرایط یا رویدادهای بیرونی تغییر می‌کردند، تو می‌توانستی نجات یابی. با این شیوه، خاستگاه رستگاری دائماً بیرون از خودت ادراک می‌شود. هر گلایه‌ای که تو نگه می‌داری یک بیانیه است، و اظهار نظری که به آن باور داری، که می‌گوید، «اگر این تغییر می‌کرد، من نجات می‌یافتم.» به این شیوه تغییر ذهن ضروری برای رستگاری از هرکس و هر چیز خواسته می‌شود، جز خودت.

پس در این نقشه، نقشی که برای ذهن خودت تعیین می‌شود به سادگی این است که تعیین کند چه چیزی غیر از خودش برای نجات تو باید تغییر کند. بر طبق این نقشه‌ی دیوانه‌وار، هر خاستگاهی که برای رستگاری ادراک می‌شود، در صورتی قابل قبول است که اثبات شده باشد به نتیجه نمی‌رسد. این تضمین می‌کند که جستجوی بی‌حاصل ادامه خواهد یافت، زیرا وهم اصرار دارد که اگرچه این امید همیشه شکست خورده است، اما هنوز زمینه‌های امید در مکان‌ها و چیزهای دیگر وجود دارد. هنوز فرد دیگری می‌تواند مفیدتر باشد؛ هنوز شرایط دیگری هست که توفیق را عرضه کند.

نقشه‌ی نفس برای رستگاری تو چنین است. مطمئناً می‌توانی ببینی که این نقشه چه همراهی محکمی با نظریه‌ی بنیادین نفس دارد: «بجوی اما نیاب.» زیرا مطمئن‌ترین تضمین برای یافت نشدن رستگاری توسط تو این است که همه‌ی تلاش خودت را بر جستجوی آن در جایی که نیست متمرکز کنی.

نقشهٔ خداوند* برای رستگاری به سادگی به نتیجه خواهد رسید زیرا با پیروی از هدایت او*، تو رستگاری را در جایی جستجو می‌کنی که وجود دارد. اما اگر می‌خواهی که توفیق یابی، آنگونه که خداوند* نویدش را داد، باید اراده کنی که فقط آنجا را جستجو کنی. در غیر این صورت، قصد تو تقسیم می‌شود و تلاش خواهی کرد تا برای رستگاری دو نقشه را دنبال کنی. دو نقشه که شدیداً از همه لحاظ با هم متضاد هستند. این فقط می‌تواند سردرگمی، احساس بدبختی و یک احساس عمیق شکست و نومیدی به ارمغان بیاورد.

چگونه می‌توانی از همه‌ی این‌ها نجات یابی؟ بسیار ساده. ایده‌ی امروز پاسخ این پرسش است. تنها نقشهٔ خداوند* برای رستگاری به نتیجه می‌رسد. در این مورد هیچ تعارض واقعی نمی‌تواند وجود داشته باشد، زیرا هیچ جایگزین احتمالی برای نقشهٔ خداوند* وجود ندارد که تو را نجات دهد. نقشهٔ او* تنها نقشه است که نتیجه‌ی مطمئن دارد. نقشهٔ او* تنها نقشه‌ای است که قطعاً موفق می‌شود.

بیایید امروز تشخیص قطعیت این موضوع را تمرین کنیم. و بیایید از این شادمانی کنیم که پاسخی برای تعارضی وجود دارد که به نظر می‌رسد هیچ راه‌حل ممکنی ندارد. همه چیز برای خداوند* ممکن است. رستگاری به خاطر نقشهٔ او* که شکست‌ناپذیر است، باید از آن تو باشد.

دو تمرین طولانی‌تر امروز را با اندیشیدن پیرامون ایده‌ی روز آغاز کن، با تشخیص این که ایده شامل دو بخش است، و هر یک از این دو بخش در کلیت ایده سهمی برابر دارند. نقشهٔ* خداوند* به نتیجه می‌رسد، و نقشه‌های دیگر بی‌نتیجه هستند. به خودت اجازه نده که از بخش دوم غمگین یا خشمگین شوی؛ این بخش در بخش اول نهاده است. و در بخش اول رهایی تو از همه‌ی تلاش‌های بیخردانه و طرح‌های دیوانه‌وار خودت برای آزادی وجود دارد. این تلاش‌ها و طرح‌ها منجر به غم و خشم شده‌اند، اما نقشهٔ* خداوند* پیروز خواهد شد. نقشهٔ خداوند* به رهایی و سرور می‌انجامد.

با به یاد داشتن این مطالب، بیایید باقیمانده‌ی برنامه‌های طولانی‌تر تمرین را به پرسش از خداوند* بپردازیم تا نقشه‌ خود* را برای ما آشکار کند. از او* پرسش‌های بسیار اختصاصی بپرس: تو می‌خواهی که من چکار کنم ؟ تو می‌خواهی که من کجا بروم ؟ تو می‌خواهی که من چه بگویم، و به چه کسی ؟ در ادامه‌ی برنامه‌ی تمرین به او* اختیار تام بده و بگذار به تو بگوید که نیاز است در نقشهٔ او* برای رستگاری خود چه کاری انجام دهی. او* متناسب با ارادهٔ تو برای شنیدن آوایش*، به تو پاسخ خواهد داد. نشنیدن را کنار بگذار. همین واقعیت که تو در حال تمرین هستی اثبات می‌کند که اراده‌ای برای گوش دادن داری. این برای اینکه خواست خود را برای پاسخ خداوند* تحکیم کنی، کافی است.

در تمرین‌های کوتاه‌تر، به دفعات به خود بگو که نقشهٔ خداوند* برای رستگاری، و فقط نقشهٔ او* به نتیجه خواهد رسید. امروز به همه‌ی وسوسه‌های نگه داشتن گلایه‌ها هشیار باش، و به آن‌ها با این شکل از ایده‌ی امروز پاسخ بده: نگه داشتن گلایه‌ها مخالف نقشهٔ خداوند* برای رستگاری است. و فقط نقشهٔ او* به نتیجه می‌رسد. سعی کن ایده‌ی امروز را حدوداً شش یا هفت مرتبه در ساعت به یاد بیاوری. بهترین شیوه این است که آن زمان نیم دقیقه یا کمتر را با یادآوری سرچشمهٔ* رستگاری خود بگذرانی، و با دیدن این که آن* کجا است.', 'https://acim-farsi.org/workbook/lesson/71', 'https://acim-farsi.org/audio/workbook/lesson/71.mp3', 'times_per_hour', '[{"kind":"interval","minutes":8},{"kind":"interval","minutes":10}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (72, 'نگه داشتن گلایه‌ها حمله‌ای به نقشهٔ خداوند* برای رستگاری است.', 'تمرین کوتاه‌تر:

نگه داشتن گلایه‌ها حمله‌ای است به نقشهٔ خداوند* برای رستگاری. بگذار به جای حمله، من این نقشه را بپذیرم. رستگاری چیست، پدر*؟

تمرین طولانی‌تر:

رستگاری چیست، پدر*؟ من نمی‌دانم. به من بگو، تا بتوانم بفهمم.', 'نگه داشتن گلایه‌ها حمله‌ای به نقشهٔ خداوند* برای رستگاری است.

اگرچه ما تشخیص داده‌ایم که نقشهٔ نفس برای رستگاری متضاد با نقشهٔ خداوند* است، اما هنوز تأکید نکرده‌ایم که این نقشه حمله‌ای فعال برعلیه نقشه‌ی او*، و تلاشی عمدی برای تخریب آن است. در این حمله، به خداوند* صفاتی نسبت داده می‌شود که واقعاً با نفس همراه هستند، در حالی که به نظر می‌رسد نفس صفات خداوند* را به خود می‌گیرد.

آرزوی بنیادین نفس این است که جایگزین خداوند* شود. در واقع، نفس تجسد جسمی همین آرزو است. زیرا در این آرزو به نظر می‌رسد که ذهن با یک بدن احاطه شده، ذهن جدا و تنها نگه داشته می‌شود، و از دسترسی به ذهن‌های دیگر ناتوان است، مگر از طریق بدن که برای زندانی کردن آن ساخته شده. محدودیت ارتباط نمی‌تواند بهترین وسیله برای گسترش دادن ارتباط باشد. اما نفس می‌خواهد تو باور کنی که بهترین وسیله است.

اگرچه تلاش برای حفظ محدودیت‌هایی که یک بدن اِعمال می‌کند در اینجا آشکار است، احتمالاً چندان آشکار نیست که چرا نگه داشتن گلایه‌ها حمله‌ای به نقشهٔ خداوند* برای رستگاری است. اما بیایید به انواع چیزهایی که تو مایل به نگه داشتن گلایه‌ها در مورد آن‌ها هستی توجه کنیم. آیا آن‌ها همیشه با کاری که یک بدن انجام می‌دهد، همراه نیستند؟ کسی چیزی می‌گوید که تو دوست نداری. او کاری می‌کند که تو ناراحت می‌شوی. او افکار دشمنانه را در رفتارش «آشکار می‌کند».

تو اینجا با آنچه آن شخص هست سروکار نداری. برعکس، تو صرفاً با آنچه او در یک بدن انجام می‌دهد روبرو هستی. تو صرفاً در کمک کردن به او در آزاد شدن از محدودیت‌های بدن شکست خورده‌ای. تو با اشتباه گرفتن بدنش با او و قضاوت در مورد آن‌ها مانند یک وجود واحد، در حال تلاش فعال برای متصل کردن او به بدنش هستی. اینجا است که به خداوند* حمله می‌شود، زیرا اگر فرزند* او* فقط یک بدن است، او نیز باید یک بدن باشد. یک آفریدگار کاملاً نامشابه با آفریده‌اش، قابل درک نیست.

اگر خداوند* یک بدن است، نقشه‌ی او* برای رستگاری چه باید باشد؟ این نقشه چه می‌تواند باشد جز مرگ؟ اگر تلاش کند خودش* را به عنوان خالق* زندگی معرفی کند و نه مرگ، حتماً دروغگو و فریبکار است، پر از وعده‌های غلط و ارائه دهنده‌ی اوهام به جای حقیقت. واقعیت ظاهری بدن، این منظره از خداوند* را کاملاً باورپذیر می‌کند. در واقع، اگر این بدن واقعی بود، گریختن از این استنتاج به راستی دشوار می‌شد. و هر گلایه‌ای که تو نگه می‌داری، اصرار دارد که این بدن واقعی است. هر گلایه‌ای کاملاً نادیده می‌گیرد که برادر تو چیست. این باورِ تو را تقویت می‌کند که او یک بدن است، و به همین دلیل او را محکوم می‌کند. و هر گلایه‌ای تصدیق می‌کند که رستگاری او حتماً مرگ است، با فرافکندن حمله‌ی خود بر خداوند*، و مسئول دانستن او* برای مرگ.

به این میدان با دقت ساخته شده، که در آن ددان خشمگین در جستجوی طعمه هستند و شفقت نمی‌تواند به آن راه یابد، نفس وارد می‌شود تا تو را نجات دهد: خداوند* تو را یک بدن ساخت. بسیار خوب. بیایید این را بپذیریم و خوشحال باشیم. به عنوان یک بدن، به خودت اجازه نده که از آنچه این بدن عرضه می‌کند محروم شوی. آن چیز کوچکی را به دست بیاور که می‌توانی بگیری. خداوند* هیچ چیز به تو نداد. این بدن تنها نجات دهندهٔ تو است. این یعنی مرگ خداوند* و رستگاری تو.

این باور جهانیِ دنیایی است که تو می‌بینی. برخی از بدن متنفر هستند، و سعی می‌کنند آن را آزار دهند و تحقیر کنند. برخی دیگر عاشق بدن هستند، و تلاش می‌کنند آن را تکریم و ستایش کنند. اما مادامی که بدن در مرکزِ مفهوم تو از خویشتن قرار دارد، تو در حال حمله کردن به نقشهٔ خداوند* برای رستگاری و نگه داشتن گلایه‌های خود برعلیه او* و آفرینش او* هستی، تا بتوانی آوای* حقیقت را نشنوی و مانند یک دوست* از آن استقبال نکنی. نجات دهنده‌ای که انتخاب کرده‌ای جای خداوند* را می‌گیرد. این نجات دهنده دوست تو می‌شود، و خداوند* را دشمن می‌پنداری.

امروز ما تلاش می‌کنیم حمله‌های بی‌معنی به رستگاری را متوقف کنیم. سعی خواهیم کرد که در عوض، از رستگاری استقبال کنیم. ادراک وارونه‌ی تو برای صلح ذهنت تخریب کننده بوده است. تو خودت را در یک بدن دیده‌ای و حقیقت را بیرون از خود، و بواسطه محدودیت‌های این بدن دور از آگاهی خود تصور کرده‌ای. حال ما تلاش می‌کنیم تا این را متفاوت ببینیم.

نور حقیقت در درون ما است، آنجا که توسط خداوند* نهاده شده. این بدن است که از ما بیرون است، و نگرانی ما نیست. بدون بدن بودن یعنی این که در حالت طبیعی خودمان هستیم. اگر نور حقیقت را در درونمان بشناسیم، یعنی خود را همانگونه که هستیم شناخته‌ایم. اگر خویشتن* خود را از این بدن جدا ببینیم، حمله به نقشهٔ خداوند* برای رستگاری پایان می‌یابد، و نقشهٔ خداوند* به جای حمله به آن، پذیرفته می‌شود. و هرجا که نقشه‌ی او* پذیرفته شود، پیشاپیش به نتیجه رسیده است.

امروز هدف تمرینات طولانی‌تر ما، آگاه شدن به این است که نقشهٔ خداوند* برای رستگاری پیشاپیش در ما به نتیجه رسیده است. برای دستیابی به این هدف، ما باید پذیرش را جایگزین حمله کنیم. تا زمانی که به نقشهٔ خداوند* حمله می‌کنیم، نمی‌توانیم بفهمیم که آن نقشه برای ما چیست. در این صورت به چیزی حمله می‌کنیم که آن را نمی‌شناسیم. حال در تلاش هستیم تا قضاوت را کنار بگذاریم، و بپرسیم که نقشهٔ خداوند* برای ما چیست: رستگاری چیست، پدر*؟ من نمی‌دانم. به من بگو، تا بتوانم بفهمم. سپس در سکوت برای پاسخ او* صبر خواهیم کرد. ما به نقشهٔ خداوند* برای رستگاری حمله کرده‌ایم، بدون آن که منتظر باشیم تا بشنویم این نقشه چیست. ما گلایه‌های خود را چنان بلند فریاد زده‌ایم تا نتوانیم به آوای* او* گوش فرادهیم. ما از گلایه‌های خود برای بستن چشمان و گوش‌هایمان استفاده کرده‌ایم.

حال می‌خواهیم ببینیم و بشنویم و بیاموزیم. «رستگاری چیست، پدر*؟» بپرس و به تو پاسخ داده خواهد شد. بجوی و خواهی یافت. ما بیش از این از نفس نخواهیم پرسید که رستگاری چیست و آن را کجا می‌توان یافت. ما این را از حقیقت می‌پرسیم. پس مطمئن باش پاسخ حقیقی خواهد بود، به خاطر آنکه* از او* می‌پرسی.

هر زمان احساس کردی که اعتمادت کاهش یافته و امیدت به توفیق کم فروغ شده یا محو می‌گردد، پرسش و درخواست خود را تکرار کن، و به یاد بیاور که در حال پرسش از آفریدگارِ* بی‌کران بی‌کرانگی هستی، که تو را همانند خودش* آفرید: رستگاری چیست، پدر*؟ من نمی‌دانم. به من بگو، تا بتوانم بفهمم. او* پاسخ خواهد داد. مصمم باش که بشنوی.

امروز یک یا شاید دو تمرین کوتاه‌تر در هر ساعت کافی خواهد بود، زیرا این تمرینات مقداری طولانی‌تر از تمرینات کوتاه‌تر معمول هستند. این تمرینات باید با این آغاز شوند: نگه داشتن گلایه‌ها حمله‌ای است به نقشهٔ خداوند* برای رستگاری. بگذار به جای حمله، من این نقشه را بپذیرم. رستگاری چیست، پدر*؟ سپس حدود یک دقیقه در سکوت صبر کن، ترجیحاً با چشمان بسته، و برای پاسخ او* گوش فرا بده.', 'https://acim-farsi.org/workbook/lesson/72', 'https://acim-farsi.org/audio/workbook/lesson/72.mp3', 'times_per_hour', '[{"kind":"interval","minutes":30},{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (73, 'من اراده می‌کنم که نور باشد.', 'تمرین کوتاه‌تر:

من اراده می‌کنم که نور باشد. تاریکی اراده‌ی من نیست.

تمرین طولانی‌تر:

من اراده می‌کنم که نور باشد. باشد تا من نور را مشاهده کنم که ارادهٔ* خداوند* و مرا بازتاب می‌دهد.', 'من اراده می‌کنم که نور باشد.

امروز ما به اراده‌ای توجه می‌کنیم که تو آن را با خداوند* سهیم هستی. این اراده با خواسته‌های پوچ نفس یکی نیست، که از درون آن‌ها تاریکی و نابودی برمی‌‌خیزد. آن اراده که با خداوند* سهیم هستی، همه‌ی قدرت آفرینش را در خود دارد. خواسته‌های پوچ نفس تسهیم نشده هستند، پس اصلاً هیچ قدرتی ندارند. خواسته‌های نفس به این معنا پوچ نیستند که می‌توانند دنیایی از اوهام را بسازند که باور تو به آن می‌تواند بسیار نیرومند باشد. اما این خواسته‌ها از این نظر پوچ هستند که در واقع نمی‌آفرینند. آن‌ها هیچ چیز واقعی نمی‌سازند.

خواسته‌های پوچ و گلایه‌ها، در به تصویر کشیدن این دنیایی که می‌بینی با هم شراکت یا همکاری می‌کنند. خواسته‌های نفس این دنیا را پدید آوردند، و نیاز نفس به گلایه‌ها، که برای حفظ آن ضروری هستند، این دنیا را با شمایل‌هایی پر می‌کند که ظاهراً به تو حمله می‌کنند، و قضاوت «حق‌طلبانه» را درخواست می‌کنند. این شمایل‌ها به واسطه‌هایی تبدیل می‌شوند که به نفس برای آوردن گلایه‌ها به دنیای تو خدمت می‌کنند. این شمایل‌ها میان آگاهی تو و واقعیتِ برادرت می‌ایستند. با نظر کردن به آن‌ها، تو برادران‌ خود یا خویشتن* خودت را نمی‌شناسی.

در این داد و ستد عجیب، اراده‌ای که تو برای خود داری گم می‌شود، در این داد و ستد، مدام احساس گناهکاری مبادله می‌گردد، و با هر مبادله گلایه‌ها افزون می‌شوند. آیا چنین دنیایی می‌تواند توسط آن اراده* که فرزند* خداوند* با پدرش* سهیم می‌شود آفریده شده باشد؟ آیا خداوند* برای فرزند* خود* فاجعه خلق کرد؟ آفرینش، ارادهٔ* خداوند* و فرزندش* هردو با هم است. آیا خداوند* خواست دنیایی بیافریند که خودش* را نابود می‌کند؟

امروز یک بار دیگر تلاش می‌کنیم تا به آن دنیا برسیم که با ارادهٔ تو همراه است. در آن دنیا نور هست، زیرا با ارادهٔ* خداوند* ضدیت نمی‌کند. آن دنیا بهشت* نیست، اما نور بهشت* بر آن می‌تابد. تاریکی محو می‌شود. خواسته‌های پوچ نفس کنار گذاشته می‌شوند. اما نوری که بر آن دنیا می‌تابد، بازتاب اراده‌ی تو است، پس نوری که ما جستجو می‌کنیم باید درون تو باشد.

تصویر تو از دنیا فقط می‌تواند آنچه را که در درون است بازتاب دهد. نه خاستگاه نور و نه خاستگاه تاریکی، هیچ‌یک را نمی‌توان در بیرون یافت. گلایه‌ها ذهنت را تاریک می‌کنند، و تو یک دنیای تاریک را مشاهده خواهی کرد. بخشایش تاریکی را از میان برمی‌دارد، اراده‌ی تو را دوباره متجلی می‌کند، و اجازه می‌دهد که دنیایی از نور را مشاهده کنی. ما بارها تأکید کرده‌ایم که به آسانی می‌توان از سد گلایه‌ها عبور کرد، و این سد قادر نیست بین تو و رستگاری تو قرار گیرد. دلیل آن بسیار ساده است. آیا تو واقعاً می‌خواهی در جهنم باشی؟ آیا تو واقعاً می‌خواهی غمگین باشی و رنج بکشی و بمیری؟

ادعاهای نفس را فراموش کن که در صدد است اثبات کند که همهٔ این واقعاً بهشت* است. تو می‌دانی که چنین نیست. خواسته‌ی تو برای خودت نمی‌تواند این باشد. نقطه‌ای وجود دارد که اوهام نمی‌توانند از آن فراتر بروند. رنج بردن شادمانی نیست، و تو واقعاً شادمانی را می‌خواهی. اراده‌ی تو در حقیقت چنین است. و به همین دلیل رستگاری نیز اراده‌ی تو است. تو می‌خواهی در آنچه امروز برای انجامش تلاش می‌کنیم، موفق ‌شوی. ما در این تلاش، تبرک و همراهی شاد تو را داریم.

اگر امروز به یاد داشته باشی که خواسته‌ی تو برای خودت رستگاری است، ما موفق خواهیم شد. تو نقشه‌ی خداوند* را می‌پذیری زیرا در آن سهیم هستی. تو مالک هیچ اراده‌ای نیستی که واقعاً بتواند با این نقشه ضدیت کند، و چنین ضدیتی را نمی‌خواهی. رستگاری برای تو است. فراتر از هر چیز دیگر، تو آن آزادی را می‌خواهی که به یاد بیاوری واقعاً چه کسی هستی. امروز این نفس است که ناتوان در مقابل اراده‌ی تو می‌ایستد. اراده‌ی تو آزاد است و هیچ چیز نمی‌تواند بر آن غالب شود.

پس تمرین‌های امروز را در شادمانی انجام می‌دهیم، مطمئن از این که آنچه یافتنش اراده‌ی تو است را خواهیم یافت، و آنچه به یاد آوردنش اراده‌ی تو است را به یاد خواهیم آورد. هیچ خواسته‌ی پوچی نمی‌تواند ما را بازدارد، یا با وهمی از قدرت فریبمان دهد. امروز اجازه بده اراده‌ی تو عملی شود، و برای همیشه به این باور دیوانه‌وار پایان بده که به جای بهشت*، جهنم را انتخاب کرده‌ای.

ما تمرینات طولانی‌تر را با فهم این آغاز می‌کنیم که تنها و تنها نقشهٔ خداوند* برای رستگاری کاملاً در همراهی با اراده‌ی تو است. این قصدِ یک قدرت بیگانه نیست که تو را بدون اراده به جلو براند. اینجا قصد واحدی هست که تو و پدرت* در آن همراهی کامل دارید. امروز موفق خواهی شد، این زمان برای رهایی فرزند* خداوند* از جهنم و از خواسته‌های پوچ مقرر شده است. اینک ارادهٔ او به آگاهی‌اش بازگردانده می‌شود. او اراده می‌کند که همین امروز به نور درونش نظر کند و نجات یابد.

پس از این یادآوری به خود و مصمم شدن به این که اراده‌ی خویش را به روشنی در ذهنت حفظ کنی، با متانتی همراه با آرامش و اطمینانی در سکوت به خودت بگو: من اراده می‌کنم که نور باشد. باشد تا من نور را مشاهده کنم که ارادهٔ* خداوند* و مرا بازتاب می‌دهد. سپس اجازه بده اراده‌ی تو در اتصال با قدرت خداوند* و در وحدت با خویشتن* تو خودش را ابراز کند. هدایت باقی برنامه‌ی تمرین را به قدرت خداوند* و خویشتن* خود بسپار. آنگونه که آن‌ها* مسیر را هدایت می‌کنند به آن‌ها* بپیوند.

در تمرینات کوتاه‌تر، دوباره آنچه را که واقعاً خواسته‌ی تو است اعلام کن. بگو: من اراده می‌کنم که نور باشد. تاریکی اراده‌ی من نیست. این کار باید در هر ساعت چندین نوبت تکرار شود. اما بسیار مهم است که هر زمان برای حفظ گلایه از هر نوعی وسوسه شدی، بلافاصله با ایده‌ی امروز در این شکل تمرین کنی. این به تو کمک می‌کند تا گلایه‌های خود را رها کنی، به جای این که آن‌ها را بپروری و در تاریکی پنهان کنی.', 'https://acim-farsi.org/workbook/lesson/73', 'https://acim-farsi.org/audio/workbook/lesson/73.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (74, 'هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد.', 'تمرین کوتاه‌تر:

هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد‌. من امروز صلح او* را می‌طلبم .

تمرین طولانی‌تر:

هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. من نمی‌توانم در تعارض باشم.

افکار مرتبطی اضافه کن، مانند:

من در صلح هستم .
هیچ چیز نمی‌تواند مرا آشفته کند. اراده‌ی من از آن خداوند* است .
ارادۀ من و ارادهٔ* خداوند* یکی هستند.
خداوند* برای فرزند* خود* صلح را اراده می‌کند.

برای افکار تعارض‌آمیزی که ممکن است از ذهنت بگذرند:

هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. این پندارهای تعارض بی‌معنا هستند.

برای مواردی که به‌طور خاص دشوارند، به خودت بگو:

هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. من در اراده‌اش* با او* سهیم می‌شوم. تعارض‌های من در مورد ........ نمی‌توانند واقعی باشند.', 'هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد.

ایده‌ی امروز را می‌توان آن اندیشه‌ی مرکزی به حساب آورد که همه‌ی تجربیات ما به سوی آن جهت‌گیری می‌کنند. ارادهٔ* خداوند* تنها اراده است. وقتی این را تشخیص دهی، تشخیص می‌دهی که اراده‌ی تو از آن خداوند* است. این باور که تعارض ممکن است، از بین می‌رود. صلح جایگزین این ایده‌ی عجیب می‌شود که تو توسط اهداف متعارض تکه و پاره شده‌ای. به عنوان یک تجلی از ارادهٔ* خداوند*، تو هیچ هدفی جز هدف او* نداری.

صلح عظیمی در ایده‌ی امروز وجود دارد، و تمرینات امروز در راستای یافتن آن هستند. خود این ایده کاملاً حقیقی است. بنابراین نمی‌تواند اوهام را پدید بیاورد. بدون اوهام، تعارض ناممکن است. بیایید امروز این را تشخیص دهیم، و صلحی را که این تشخیص به ارمغان می‌آورد تجربه کنیم‌.

برنامه‌های تمرین طولانی‌تر را با چند مرتبه تکرار این اندیشه‌ها به آرامی و با تصمیم قاطع برای درک معنای آن‌ها، و در ذهن داشتن آن‌ها آغاز کن: هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. من نمی‌توانم در تعارض باشم. سپس چند دقیقه زمان صرف کن تا برخی افکار مرتبط را اضافه کنی، مانند: من در صلح هستم . هیچ چیز نمی‌تواند مرا آشفته کند. اراده‌ی من از آن خداوند* است . ارادۀ من و ارادهٔ* خداوند* یکی هستند. خداوند* برای فرزند* خود* صلح را اراده می‌کند. در این مرحله‌ی ابتدایی، مطمئن شو که با هر پندار تعارضی که به ذهنت می‌رسد سریعاً برخورد کنی. بلافاصله به خود بگو: هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. این پندارهای تعارض بی‌معنا هستند.

اگر یک عرصهٔ تعارض وجود دارد که به نظر می‌رسد حل آن خصوصاً دشوار است‌، آن را برای توجه ویژه کنار بگذار. به آن مختصر و بسیار ویژه بیندیش، شخص یا اشخاص و شرایط ویژه‌ی درگیر را مشخص کن، و به خود بگو: هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. من در اراده‌اش* با او* سهیم می‌شوم. تعارض‌های من در مورد ........ نمی‌توانند واقعی باشند.

پس از پاکسازی ذهن با این شیوه، چشمانت را ببند و سعی کن آن آرامش را که واقعیت تو به آن رهنمون می‌شود تجربه کنی. در آن غوطه‌ور شو و احساس کن که پیرامونت را فرا می‌گیرد. ممکن است برخی وسوسه‌ها وجود داشته باشد که این تلاش‌ها را با کناره‌گیری اشتباه بگیری، اما تفاوت به سادگی قابل ردیابی است. اگر در حال توفیق هستی، عمیقاً احساس سرور و افزایش هشیاری خواهی کرد، نه خواب‌آلودگی و سستی.

سرور خصوصیت صلح است. با این تجربه تو تشخیص خواهی داد که به آن رسیده‌ای. اگر احساس کردی که در حال لغزش به کناره‌جویی هستی، سریعاً ایدهٔ امروز را تکرار کرده و دوباره تلاش کن. این کار را به هر تعداد دفعات لازم انجام بده. در امتناع از عقب‌نشینی به کناره‌جویی سود قطعی وجود دارد، حتی اگر تو آن صلح را که می‌جویی تجربه نکنی.

در تمرینات کوتاه‌تر، که امروز باید در فواصل منظم و از پیش تعیین شده انجام شوند، به خودت بگو: هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد‌. من امروز صلح او* را می‌طلبم . سپس تلاش کن تا آنچه را که می‌جویی، بیابی. برای انجام این تمرین هر نیم‌ساعت یک تا دو دقیقه را صرف کن، در صورت امکان با چشمان بسته.', 'https://acim-farsi.org/workbook/lesson/74', 'https://acim-farsi.org/audio/workbook/lesson/74.mp3', 'interval', '[{"kind":"interval","minutes":15}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (75, 'نور آمده است.‌', 'تمرین کوتاه‌تر:

سپاسگزاری کن و سپس بگو:

نور آمده است. من این دنیا را بخشیده‌ام.

هر زمان وسوسه شدی، به هر کسی که به نظر می‌رسد تو را به درون تاریکی می‌کشاند بگو:

نور آمده است. من تو را بخشیده‌ام.

تمرین طولانی‌تر:

نور آمده است. من این دنیا را بخشیده‌ام.', 'نور آمده است.‌

نور آمده است. تو شفا می‌یابی و می‌توانی شفا دهی. نور آمده است. تو نجات می‌یابی و می‌توانی نجات دهی. تو در صلح هستی و می‌توانی هرجا که می‌روی صلح را با خود ببری. تاریکی و نابسامانی و مرگ محو شده‌اند. نور آمده است.

امروز ما فرجام شادمان رؤیای طولانی تو از فاجعه را جشن می‌گیریم. اینک هیچ رؤیای تاریکی وجود ندارد. نور آمده است. امروز دوران نور برای تو و همگان آغاز می‌شود. این یک عصر جدید است، که در آن دنیایی نو زاده می‌شود. دنیای کهنه در گذرش هیچ ردّی بر آن باقی نگذاشته است. امروز ما دنیایی متفاوت را می‌بینیم، زیرا نور آمده است.

تمرین‌های امروز ما شاد خواهند بود، و ما در آن‌ها از پایان یافتن کهنه و آغازِ نو سپاسگزاری می‌کنیم. هیچ سایه‌ای از گذشته باقی نمی‌ماند تا دید ما را تاریک گرداند و آن دنیا را که بخشایش به ما عرضه می‌کند، پنهان سازد. امروز ما دنیای نو را به عنوان آنچه دیدنش را طلب می‌کنیم، خواهیم پذیرفت. آنچه می‌خواهیم به ما عطا خواهد شد. ما اراده می‌کنیم که نور را ببینیم؛ نور آمده است.

تمرین‌های طولانی‌تر ما به نظاره کردن آن دنیایی اختصاص دارد که بخشایش ما به ما نشان می‌دهد. این و تنها همین، چیزی است که ما می‌خواهیم ببینیم. یگانه بودن قصد ما، رسیدن به هدفمان را ناگزیر می‌کند. امروز دنیای واقعی در شادمانی مقابل ما ظهور خواهد کرد، تا سرانجام دیده شود. به ما بینایی داده شده، حال که نور آمده است.

امروز نمی‌خواهیم سایه‌ی نفس را بر این دنیا ببینم. ما نور را می‌بینیم، و در آن بازتاب بهشت* را می‌بینیم که بر روی این دنیا گسترده شده است. برنامه‌های تمرین طولانی‌تر را با گفتن نوید رهایی به خودت آغاز کن: نور آمده است. من این دنیا را بخشیده‌ام.

امروز در گذشته ساکن نباش. ذهنت را کاملاً باز نگه دار، شسته از همه‌ی ایده‌های گذشته و پاک از هر مفهومی که تو ساخته‌ای. امروز تو این دنیا را بخشیده‌ای. تو اینک می‌توانی چنان به آن نظر کنی، گویی قبلاً هرگز آن را ندیده‌ای. تو هنوز نمی‌دانی که چگونه به نظر می‌رسد. صرفاً صبر کن تا به تو نشان داده شود . در حال انتظار ، چند بار آرام و در صبوری کامل تکرار کن: نور آمده است. من این دنیا را بخشیده‌ام.

بدان که بخشایش تو را مستحق رؤیت می‌کند. درک کن که روح‌القدس* قطعاً موهبت بینایی را به بخشندگان عطا می‌کند. باور کن که او* اکنون تو را نومید نمی‌کند. تو این دنیا را بخشیده‌ای. همچنان که نظاره و صبر می‌کنی، او* با تو خواهد بود. او* به تو نشان خواهد داد که رؤیت حقیقی چه چیز را می‌بیند. این ارادهٔ* او* است، و تو به او متصل شده‌ای. صبورانه منتظر او* باش. او* آنجا خواهد بود. نور آمده است. تو این دنیا را بخشیده ای.

به او* بگو که می‌دانی نومید نمی‌شوی ، زیرا به او* ایمان داری. و به خودت بگو که در اطمینان، برای نظر کردن به آن دنیا که او وعده‌اش را داد، منتظر می‌مانی. از این زمان به بعد تو متفاوت خواهی دید. امروز نور آمده است. و آن دنیا را خواهی دید که وعده‌اش از آغاز زمان داده شد، دنیایی که در آن پایان یافتن زمان مسجل است.

تمرین‌های کوتاه‌تر نیز یادآور سرورآمیز رهایی تو خواهند بود. حدوداً هر یک ربع ساعت به یاد خود بیاور که امروز زمان جشنی ویژه است. از شفقت و عشق* خداوند* سپاسگزاری کن. در قدرت بخشایش شادمانی کن تا بینایی تو کاملاً شفا یابد. مطمئن باش که در امروز، آغازی نو وجود دارد. بدون تیرگی گذشته بر چشمانت، امروز قطعاً خواهی دید. و آنچه می‌بینی چنان مطبوع خواهد بود که امروز را به همیشه بسط خواهی داد.

پس بگو: نور آمده است. من این دنیا را بخشیده‌ام. هر زمان وسوسه شدی، به هر کسی که به نظر می‌رسد تو را به درون تاریکی می‌کشاند بگو: نور آمده است. من تو را بخشیده‌ام.

ما امروز را برای آرامشی وقف می‌کنیم که خداوند* برای تو می‌خواهد. امروز آن را در آگاهی خود داشته باش و در همه جا ببین، همچنان که ما آغاز رؤیت تو و دیدن آن دنیای واقعی را جشن می‌گیریم، که آمده است تا جایگزین آن دنیای نابخشوده شود که تو واقعی می‌پنداشتی.', 'https://acim-farsi.org/workbook/lesson/75', 'https://acim-farsi.org/audio/workbook/lesson/75.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (76, 'من تحت هیچ قانونی جز قانون‌های خداوند* نیستم.', 'من تحت هیچ قانونی جز قانون‌های خداوند* نیستم.', 'من تحت هیچ قانونی جز قانون‌های خداوند* نیستم.

ما قبلاً مشاهده کرده‌ایم که چه بسیار چیزهای بی‌معنا برای تو رستگاری به نظر رسیده‌اند. هر یک از این چیزها تو را با قانون‌هایی به اندازهٔ خودشان بی‌معنا، به بند کشیده‌اند. تو اسیر آن‌ها نیستی. اما برای آن که بفهمی چنین است، باید نخست تشخیص دهی که رستگاری آنجا حضور ندارد. تا زمانی که می‌خواهی آن را در چیزهایی بجویی که هیچ معنایی ندارند، خودت را اسیر قانون‌هایی کرده‌ای که هیچ معنایی ندارند. از این طریق می‌خواهی اثبات کنی رستگاری جایی هست که وجود ندارد.

امروز ما شادمان خواهیم بود از این که تو نمی‌توانی این را اثبات کنی. زیرا اگر می‌توانستی، همیشه رستگاری را جایی می‌جستی که وجود ندارد، و هرگز آن را نمی‌یافتی. ایده‌ی امروز بار دیگر به تو می‌گوید که رستگاری چقدر ساده است. آن را در جایی بجوی که در انتظار تو است، و آنجا یافت می‌شود. هیچ جای دیگری را جستجو نکن، زیرا هیچ جای دیگری نیست.

به آن آزادی بیندیش که در این تشخیص وجود دارد، تشخیص این که تو اسیر این همه قانون‌های عجیب و مغشوش که برای نجات خودت ساخته‌ای نیستی. تو واقعاً می‌پنداری که قحطی خواهی کشید مگر پشته‌ای از نوارهای کاغذی سبز و توده‌ای از صفحه‌های دایره‌ای فلزی داشته باشی. تو واقعاً می‌پنداری که یک حبهٔ کوچک گِرد یا مایعی که از طریق یک سوزن تیز به درون وریدهای تو وارد می‌شود، بیماری و مرگ را دفع خواهد کرد. تو واقعاً می‌پنداری تنها هستی مگر بدن دیگری با تو باشد.

دیوانگی است که به این چیزها می‌اندیشد. تو آن‌ها را قانون می‌خوانی، و تحت نام‌های مختلف در یک فهرست طولانی از مناسک قرارشان می‌دهی که هیچ استفاده‌ای برای خدمت به هیچ هدفی ندارند. تو می‌پنداری که باید از «قانون‌های» پزشکی، اقتصاد و سلامتی اطاعت کنی. از بدن محافظت کنی، و نجات خواهی یافت.

این‌ها قانون نیستند، بلکه دیوانگی هستند. بدن توسط ذهنی که به خودش آسیب می‌زند، به خطر می‌افتد. بدن فقط به این منظور رنج می‌کشد که ذهن نتواند ببیند که قربانیِ خودش است. رنج بدن آن صورتک است که ذهن بالا نگه می‌دارد تا آنچه را که واقعاً رنج می‌برد، پنهان کند. ذهن نمی‌خواهد بفهمد که دشمنِ خودش است؛ که به خودش حمله می‌کند و می‌خواهد بمیرد. «قانون‌های» تو می‌خواهند بدن را از این نجات دهند. به این دلیل است که تو می‌پنداری یک بدن هستی.

هیچ قانونی جز قانون‌های خداوند* وجود ندارد. این باید تکرار شود، بارها و بارها، تا زمانی که بفهمی این ایده برای همه‌ی چیزهایی که تو در مخالفت با ارادهٔ* خداوند* ساخته‌ای، کاربرد دارد. جادوی تو هیچ معنایی ندارد. آنچه که جادوی تو می‌خواهد نجاتش دهد، وجود ندارد. فقط آن چیزی که می‌خواهد پنهان کند تو را نجات خواهد داد.

قانون‌های خداوند* را هرگز نمی‌توان جایگزین کرد. ما امروز را به جشن گرفتن این موضوع اختصاص می‌دهیم. این دیگر حقیقتی نیست که بخواهیم پنهانش کنیم. در عوض ما تشخیص می‌دهیم این حقیقتی است که آزادی ما را برای همیشه حفظ می‌کند. جادو به اسارت می‌گیرد، اما قانون‌های خداوند* آزاد می‌کنند. نور آمده است زیرا هیچ قانونی جز قانون‌های او* وجود ندارد.

ما تمرین‌های طولانی‌تر امروز را با مرور کوتاه انواع مختلف «قانون‌ها» آغاز می‌کنیم که باور داریم باید از آن‌ها اطاعت کنیم. این‌ها عبارتند از مثلاً : «قانون‌های» تغذیه، مصون سازی، مصرف دارو، و حفاظت از بدن به روش‌های بی‌شمار. به فراتر بیندیش؛ تو به «قانون‌های» دوستی، روابط «خوب» و تعامل باور داری. احتمالاً تو حتی می‌پنداری که قانون‌هایی وجود دارند که آنچه را از آن خداوند* است و آنچه را از آن تو است از هم جدا می‌کنند. بسیاری از «مذهب‌ها» بر این بنیان بنا شده‌اند. آن‌ها نجات نمی‌دهند، بلکه به نام بهشت*، دوزخ را می‌سازند. اما قانون‌های آن‌ها نیز عجیب‌تر از «قانون‌های» دیگری نیست که تو خود را ملزم به اطاعت از آن‌ها می‌دانی تا به تو امنیت بدهند.

هیچ قانونی جز قانونهای خداوند* وجود ندارد. امروز همه‌ی باورهای جادویی احمقانه را کنار بگذار ، و ذهنت را در سکوت برای شنیدن آن آوا* که با تو از حقیقت سخن می‌گوید، آماده نگه دار. تو به آن یگانه* گوش فرا خواهی داد‌ که می گوید تحت قانون‌های خداوند* هیچ از دست دادنی وجود ندارد. هزینه نه داده می‌شود و نه گرفته می‌شود. تبادل نمی‌تواند انجام شود؛ هیچ جایگزینی وجود ندارد؛ و هیچ چیزی با چیز دیگر جایگزین نمی‌شود. قانون‌های خداوند* همیشه می‌دهند و هرگز نمی‌گیرند.

او* را بشنو که این سخنان را به تو می‌گوید، و تشخیص بده «قانون‌هایی» که می‌پنداشتی دنیای تصوری تو را استوار می‌کنند، چقدر احمقانه هستند. سپس بیشتر گوش فرا بده. او* به تو بیشتر خواهد گفت. از عشقی* که پدرت* به تو دارد. از سرور بی‌پایانی که او* به تو عرضه می‌کند. از میلی که او* به فرزند* خود* دارد، که وی* را به عنوان کانال آفرینش خویش* آفرید، فرزندی* که او* را با باور خود به جهنم انکار می‌کند.

بیایید امروز کانال‌های خداوند* را به رویش باز کنیم، و اجازه دهیم اراده‌‌اش* از طریق ما تا او* گسترش یابد. از این طریق آفرینش افزایشی نامحدود می‌یابد. آوای* او* با ما از این سخن خواهد گفت، و نیز از سرورهای بهشت که قانون‌های او* برای همیشه نامحدود نگه می‌دارند. ما ایده‌ی امروز را تا آنجا تکرار خواهیم کرد که بشنویم و بفهمیم که هیچ قانونی جز قانون‌های خداوند* وجود ندارد. سپس به عنوان آن تعهدی که به برنامه‌ی تمرین پایان می‌دهد به خودمان می‌گوییم: من تحت هیچ قانونی جز قانون‌های خداوند* نیستم.

امروز به دفعات ممکن این تعهد را تکرار خواهیم کرد؛ حداقل چهار یا پنج نوبت درهر ساعت، همچنین در طول روز در پاسخ به هر وسوسه برای تجربه کردن خودمان به عنوان تأثیرپذیر از قانونهای دیگر. این بیانیه آزادی ما از همه‌ی خطرها و همهٔ ستمگری است. اینگونه ما تصدیق می‌کنیم که خداوند*، پدر* ما است، و فرزند* او* نجات یافته است.', 'https://acim-farsi.org/workbook/lesson/76', 'https://acim-farsi.org/audio/workbook/lesson/76.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (77, 'من مستحق معجزات هستم.', 'من مستحق معجزات هستم.

هر زمان که وسوسه شدی، سریعاً به خودت بگو:

من معجزات را با گلایه‌ها مبادله نخواهم کرد. من فقط آنچه را که متعلق به من است، می‌خواهم. خداوند* معجزات را به عنوان حق برای من مقرر کرده است.', 'من مستحق معجزات هستم.

تو به دلیل آنچه هستی، مستحق معجزات هستی. تو معجزات را دریافت خواهی کرد به دلیل آنچه خداوند* هست. و تو معجزات را عرضه خواهی کرد زیرا با خداوند* یگانه هستی. باز، چقدر رستگاری ساده است! رستگاری صرفاً بیانی از هویت حقیقی تو است. ما امروز این را جشن خواهیم گرفت.

طلب تو برای معجزات در اوهام تو در مورد خودت حضور ندارد. این طلب به هیچ قدرت جادویی که تو به خودت نسبت می‌دهی وابسته نیست، و نیز به هیچ‌ یک از مناسکی که ابداع کرده‌ای. این طلب در حقیقتِ آنچه که تو هستی ذاتی است. این طلب در آنچه که خداوند*، پدر* تو هست، نهفته است. این طلب در آفرینش تو حتمی شده، و توسط قانون‌های خداوند* تضمین می‌گردد.

ما امروز آن معجزات را که حق تو است طلب خواهیم کرد، زیرا به تو تعلق دارند. به تو نوید رهایی کامل از این دنیا که ساختی داده شده است. به تو این تضمین داده شده که ملکوت* خداوند*، در درونت است، و هرگز گم نمی‌شود. ما بیش از آنچه که در حقیقت متعلق به ما است را نمی‌خواهیم. اما، امروز همچنین اطمینان خواهیم یافت که خودمان را به کمتر از این راضی نمی‌کنیم.

تمرینات طولانی‌تر را با گفتن این ایده به خودت با کمال اطمینان آغاز کن که تو مستحق معجزات هستی. با بستن چشمانت به خودت یادآور شو که تو تنها چیزی را می‌خواهی که به حق از آن تو است. همچنین به خودت یادآور شو که معجزات هرگز از کسی گرفته نمی‌شوند تا به دیگری داده شوند، و این که در طلب حقوق خود، تو از حقوق همه حمایت می‌کنی. معجزات از قانون‌های این دنیا اطاعت نمی‌کنند، آن‌ها صرفاً از قانون‌های خداوند* پیروی می‌کنند.

پس از این مرحله‌ی مقدماتی مختصر، برای اطمینان از این که خواسته‌ی تو برآورده می‌شود، در سکوت منتظر بمان. تو تقاضای رستگاری این دنیا و خودت را داشته‌ای. خواسته‌ای به تو وسایلی داده شود که توسط آن‌ها به این مقصود برسی. تو نمی‌توانی در اطمینان یافتن از این شکست بخوری. تو فقط می‌خواهی که ارادهٔ* خداوند* انجام شود.

در انجام این امر، تو واقعاً چیزی را نمی‌‌خواهی. واقعیتی را بیان می‌کنی که نمی‌توان نادیده‌اش گرفت. روح‌القدس* تنها می‌تواند به تو اطمینان دهد که خواسته تو برآورده می‌شود. آن واقعیت که پذیرفته‌ای باید چنین باشد. امروز جایی برای تردید و بی‌اطمینانی وجود ندارد. ما سرانجام در حال پرسیدن یک پرسش واقعی هستیم. پاسخ، بیانی ساده از یک واقعیت ساده است. تو آن دلگرمی را که می‌طلبی، دریافت خواهی کرد.

تمرین‌های کوتاه‌تر ما پرشمار خواهند بود، و آن‌ها نیز به یادآوری یک واقعیت ساده اختصاص دارند. امروز مکرر به خودت بگو: من مستحق معجزات هستم. هر زمان شرایطی پیش آمد که نیاز به معجزه داشتی، معجزات را بخواه. تو این شرایط را تشخیص خواهی داد. و از آنجا که به خودت در یافتن معجزه تکیه نمی‌کنی، کاملاً مستحق دریافت آن هر زمان که می‌خواهی، هستی.

همچنین به یاد داشته باش که به چیزی غیر از پاسخ کامل رضایت ندهی. هر زمان که وسوسه شدی، سریعاً به خودت بگو: من معجزات را با گلایه‌ها مبادله نخواهم کرد. من فقط آنچه را که متعلق به من است، می‌خواهم. خداوند* معجزات را به عنوان حق برای من مقرر کرده است.', 'https://acim-farsi.org/workbook/lesson/77', 'https://acim-farsi.org/audio/workbook/lesson/77.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (78, 'باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند.', 'تمرین کوتاه‌تر:

باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند.

تمرین طولانی‌تر:

بگذار من نجات دهندهٔ خود را در این فرد ببینم که تو* برایم به عنوان کسی مقرر کرده‌ای تا از او بخواهم مرا به آن نور قدسی که در آن ایستاده است هدایت کند، باشد تا به او ملحق شوم.', 'باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند.

شاید هنوز برایت کاملاً روشن نباشد که هر تصمیمی می‌گیری، تصمیم بین یک گلایه و یک معجزه است. هر گلایه‌ای مانند یک سپر تیره از نفرت در برابر معجزه‌ای است که می‌خواهد پنهانش کند. و وقتی تو آن را پیش چشم خود برمی‌افرازی، معجزهٔ ورای آن را نخواهی دید. اگرچه تمام این مدت در نور انتظارت را می‌کشد، اما تو به جای آن، گلایه‌های خود را می‌بینی.

امروز ما به ورای گلایه‌ها خواهیم رفت، تا به جای آن به معجزه نظر کنیم. ما روش دیدن تو را وارونه خواهیم کرد، با اجازه ندادن به توقف بینایی، تا زمانی که ببینی. ما در برابر سپر نفرت، منتظر نخواهیم ماند، بلکه آن را زمین می‌گذاریم و با ملایمت در سکوت چشمانمان را به بالا می‌دوزیم تا به فرزند* خداوند* نظر کنیم.

او در پس همه‌ی گلایه‌هایت انتظار تو را می‌کشد. و با زمین گذاشتن آن‌ها، او در نور درخشنده‌ای که پیش روی هر کسی هست، ظاهر خواهد شد. زیرا هر گلایه، سدی در برابر بینایی است، و با از میان برخاستن آن، تو فرزند* خداوند* را در جایی که همیشه بوده است، خواهی دید. او در نور می‌ایستد، اما تو در تاریکی بودی. هر گلایه‌ای این تاریکی را ژرف‌تر می‌کرد، و تو نمی‌توانستی ببینی.

امروز ما تلاش خواهیم کرد تا فرزند* خداوند* را ببینیم. ما نخواهیم گذاشت که به او نابینا باشیم؛ ما به گلایه‌های خود نظر نخواهیم کرد. اینچنین، دیدن دنیا وارونه می‌شود، همچنان که ما به سوی حقیقت می‌نگریم به دور از ترس. ما یک نفر را انتخاب خواهیم کرد که تو به عنوان هدف گلایه‌های خود از او استفاده کرده‌ای، و گلایه‌ها را کنار خواهیم گذاشت و به او نگاه خواهیم کرد. کسی که شاید از او می‌ترسی و حتی نفرت داری؛ کسی که می‌پنداری به او عشق می‌ورزی و تو را خشمگین کرده است؛ کسی که تو او را یک دوست می‌خوانی اما گاهی او را سخت می‌دانی یا کسی می‌دانی که به سختی راضی می‌شود، طلبکار است، سوهان روح است یا نسبت به آرمان‌هایی که ادعای پذیرش آن‌ها را دارد ناصادق است، بر حسب نقشی که تو به او می‌دهی.

تو می‌دانی چه کسی را انتخاب کنی؛ نام او پیشاپیش به ذهنت رسیده است. او کسی خواهد بود که از او می‌خواهیم فرزند* خداوند* به تو نشان داده شود. از طریق دیدنش ورای گلایه‌هایی که بر علیه او نگه داشته‌ای، تو خواهی آموخت که آنچه پنهان است در حالی که تو او را نمی‌دیدی، در همه وجود دارد، و می‌تواند دیده شود. او که دشمن بود بیش از یک دوست است، وقتی آزاد شود تا بتواند نقش مقدسی را که روح‌القدس* به او عطا کرده ایفا کند. بگذار امروز او منجی تو باشد. چنین است نقش او در نقشهٔ خداوند* پدر* تو.

تمرینات طولانی‌تر امروز ما، او را در این نقش خواهند دید. تو تلاش خواهی کرد تا او را در ذهن داشته باشی، ابتدا آنگونه که اکنون او را در نظر داری. خطاهای او را مرور خواهی کرد، سختی‌هایی را که با او داشته‌ای، رنجی را که به تو داده است، بی‌تفاوتی او و همه‌ی آزارهای کوچک و بزرگی که به تو داده. تو بدن او را با نقایص و نیز نکات خوبش خواهی دید، و به اشتباهات و حتی «گناهان» او فکر خواهی کرد.

سپس بیایید از او* که این فرزند* خداوند* را با واقعیت و حقیقتش می‌شناسد بپرسیم، تا بتوانیم به او به شیوه‌ای متفاوت بنگریم و نجات دهندهٔ خود را درخشنده در نور بخشایش حقیقی ببینیم، نوری که به ما عطا شده است. ما به نام* مقدس خداوند* و فرزندش* که مانند خودش* مقدس است از او* خواهیم خواست: بگذار من نجات دهندهٔ خود را در این فرد ببینم که تو* برایم به عنوان کسی مقرر کرده‌ای تا از او بخواهم مرا به آن نور قدسی که در آن ایستاده است هدایت کند، باشد تا به او ملحق شوم. چشمان بدن بسته هستند، و همچنان که به او که تو را گلایه‌مند کرده می‌اندیشی، بگذار نور درونش از ورای گلایه‌های تو به ذهنت نشان داده شود.

نمی‌توان آنچه را که تو خواسته‌ای نادیده گرفت. نجات دهنده‌ی تو زمانی طولانی برای این لحظه صبر کرده است. او می‌خواهد آزاد شود، و آزادی خود را از آن تو کند. روح‌القدس* از طرف او به سوی تو متمایل است، و در فرزند* خداوند* هیچ جدایی نمی‌بیند. و آنچه تو از طریق روح‌القدس* می‌بینی هر دوی شما را آزاد خواهد کرد. اینک بسیار ساکت باش، و به نجات دهنده‌ی درخشان خود نظر کن. هیچ گلایه‌ تیره ای منظره‌ی دیدن او را نمی‌پوشاند. تو به روح‌القدس* اجازه داده‌ای از طریق او نقشی را که خداوند* به وی عطا کرده بود متجلی کند، تا تو بتوانی نجات یابی.

خداوند* از تو برای این زمان‌های ساکتی که امروز صرف می‌کنی تا تصویرهای خود را کنار بگذاری تشکر می‌کند، زمان‌هایی که در آن‌ها به معجزهٔ عشقی نظر می‌کنی که روح‌القدس* به جای این تصویرها به تو نشان می‌دهد. این دنیا و ملکوت* در سپاس از تو به هم می‌پیوندند، زیرا حتی یک اندیشهٔ* خداوند* نیست مگر اینکه باید با نجات تو شادی آفرینی کند، و‌ نیز با نجات همهٔ این دنیا به همراه تو.

ما در طول روز این را به یاد خواهیم داشت، و نقشی را که به عنوان بخشی از نقشهٔ خداوند* برای رستگاری، و نه نقشهٔ خود ما، به ما عطا شده ایفا خواهیم کرد. وسوسه فرو می‌ریزد زمانی که اجازه می‌دهیم هر کسی که ملاقات می‌کنیم، نجاتمان دهد، و از پنهان کردن نور او در پس گلایه‌های خود سر بر می‌تابیم. اجازه بده که به هر کسی که ملاقات می‌کنی و به کسانی که به آن‌ها می‌اندیشی یا از گذشته به یاد می‌آوری، نقش نجات دهنده داده شود، تا بتوانی این نقش را با او سهیم شوی. ما برای هر دوی شما، و همچنین همهٔ نابینایان، دعا می‌کنیم: باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند.', 'https://acim-farsi.org/workbook/lesson/78', 'https://acim-farsi.org/audio/workbook/lesson/78.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (79, 'باشد تا من مشکل را تشخیص دهم تا بتواند حل شود.', 'باشد تا این مشکل را تشخیص دهم تا بتواند حل شود.', 'باشد تا من مشکل را تشخیص دهم تا بتواند حل شود.

یک مشکل را نمی‌توان حل کرد اگر ندانی که چیست. حتی اگر آن مشکل واقعاً حل شده باشد تو هنوز مشکل خواهی داشت، زیرا تشخیص نخواهی داد که حل شده است. این وضعیت این دنیا است. مشکل جدایی که واقعاً تنها مشکل است، پیشاپیش حل شده است. اما حل شدن آن فهمیده نمی‌شود زیرا مشکل فهمیده نشده است.

به نظر می‌رسد که هر کسی در این دنیا مشکلات خاص خود را دارد. اما همه‌ی این مشکلات با هم یکی هستند. و اگر قرار باشد یگانه راه‌حلی که همهٔ آن‌ها را حل می‌کند پذیرفته شود، باید یکی بودن آن‌ها تشخیص داده شود. چه کسی می‌تواند ببیند که یک مشکل حل شده است اگر فکر کند که مشکل چیز دیگری است؟ حتی اگر پاسخ به او داده شود، نمی‌تواند ربط آن را بیابد.

این موقعیت تو در حال حاضر است. پاسخ را داری، اما هنوز مطمئن نیستی که مشکل چیست. ظاهراً مجموعه‌ای طولانی از مشکلات مختلف با تو رودررو هستند، و به محض این که یکی فروکش می‌کند بعدی و بعدی بروز می‌کنند. به نظر می‌رسد که پایانی بر آن‌ها نیست. هیچ زمانی وجود ندارد که تو در آن زمان کاملاً احساس کنی بدون مشکل و در صلح هستی.

وسوسهٔ دیدن مشکلات به این تعداد، وسوسهٔ حل نشده نگه داشتن مشکل جدایی است. ظاهراً این دنیا تعداد زیادی مشکل را به تو ارائه می‌کند، که هریک نیازمند پاسخی متفاوت است. این ادراک تو را در موقعیتی قرار می‌دهد که در آن مهارت حل مشکل تو باید ناکافی باشد، و شکست اجتناب‌ناپذیر است.

هیچ‌کس نمی‌تواند همه‌ی مشکلاتی را حل کند که این دنیا ظاهراً در خود دارد. به نظر می‌رسد که آن‌ها در سطوح بسیار مختلفی هستند، در چنان شکل‌های مختلف با چنان محتوای گوناگون که تو را با یک شرایط ناممکن روبرو می‌کنند. زمانی که به آن‌ها نظر می‌کنی، نگرانی و افسردگی ناگزیر هستند. به محض این که فکر کنی مشکلات قبلی را حل کرده‌ای، برخی مشکلات به صورت غیرمنتظره ظهور می‌کنند. برخی دیگر از مشکلات زیر ابری از انکار، حل نشده باقی می‌مانند، و هرازگاهی می‌آیند تا تسخیرت کنند، تنها برای این که دوباره پنهان شوند، آن هم حل نشده.

همهٔ این پیچیدگی تنها تلاشی نومیدانه برای تشخیص ندادن مشکل است، و بنابراین تلاشی است برای اجازه ندادن به حل آن. اگر می‌توانستی تشحیص دهی که تنها مشکل تو جدایی است، فارغ از هر شکلی که به خود می‌گیرد، می‌توانستی پاسخ را بپذیری زیرا ربط آن را می‌دیدی. با درک پیوستگی زمینه‌ای در همهٔ مشکلاتی که به نظر می‌رسد با تو رودررو هستند، می‌فهمی که وسیلهٔ حل همهٔ آن‌ها را داری. در صورت درک این پیوستگی، از آن وسیله استفاده می‌کنی، زیرا مشکل را می‌شناسی.

امروز در برنامه‌های تمرین طولانی‌تر خود، ما خواهیم پرسید که مشکل چیست، و پاسخ به آن چیست. ما فرض نخواهیم کرد که پیشاپیش آن را می‌دانیم. سعی خواهیم کرد ذهن‌هایمان را از همهٔ انواع مختلف مشکلاتی که فکر می‌کنیم داریم، آزاد کنیم. ما سعی خواهیم کرد تشخیص دهیم که تنها یک مشکل داریم، که نتوانسته‌ایم آن را بشناسیم. ما خواهیم پرسید که آن مشکل چیست، و برای پاسخ صبر خواهیم کرد. به ما گفته خواهد شد. سپس راه حل آن را خواهیم خواست. و به ما گفته خواهد شد.

تمرین‌های امروز تا آن زمان موفق خواهند بود که تو بر تعریف کردن مشکل پافشاری نکنی. شاید موفق نشوی همهٔ نظریه‌های پیش‌فرض خود را رها کنی، اما این ضروری نیست. همه‌ی آنچه ضروری است، پذیرش نوعی شک در مورد واقعیت داشتن درک تو از ماهیت مشکلات خودت است. تو در تلاش هستی تشخیص دهی که با شناختن مشکل، پاسخ به تو داده شده است، آن‌چنان که مشکل و پاسخ می‌توانند نزد هم آورده شوند، و تو می‌توانی در صلح باشی.

تمرین‌های کوتاه‌تر امروز بر حسب زمان تنظیم نخواهند شد، بلکه بر حسب نیاز اجرا می‌شوند. امروز مشکلات زیادی را خواهی دید، که هر یک نیازمند پاسخ هستند. تلاش‌های ما در این راستا خواهند بود که تشخیص دهیم فقط یک مشکل و یک پاسخ وجود دارد. با این تشخیص همهٔ مشکلات حل می‌شوند. در این تشخیص صلح وجود دارد.

امروز با شکل مشکلات فریب نخور. هر زمان که ظاهراً یک‌ دشواری بروز می‌کند، سریعاً به خودت بگو: باشد تا این مشکل را تشخیص دهم تا بتواند حل شود. سپس سعی کن همهٔ قضاوت خود را در مورد این که مشکل چیست تعلیق کنی. در صورت امکان، چشمانت را برای یک لحظه ببند و بپرس که آن چیست. تو شنیده خواهی شد و به تو پاسخ داده خواهد شد.', 'https://acim-farsi.org/workbook/lesson/79', 'https://acim-farsi.org/audio/workbook/lesson/79.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (80, 'باشد تا تشخیص دهم که مشکلات من حل شده‌اند.', 'باشد تا تشخیص دهم که این مشکل حل شده است.', 'باشد تا تشخیص دهم که مشکلات من حل شده‌اند.

اگر اراده ‌کنی که مشکلات خود را بفهمی، خواهی فهمید که هیچ مشکلی نداری. تنها مشکل اصلی تو پاسخ داده شده است، و مشکل دیگری نداری. پس باید در صلح باشی. و رستگاری به تشخیص همین مشکل واحد بستگی دارد، و فهمیدن این که این مشکل حل شده است. یک مشکل، یک راه حل. رستگاری به دست می‌آید. آزادی از تعارض به تو عطا شده است. این واقعیت را بپذیر، و آنگاه برای دریافت جایگاه درست خود در نقشهٔ خداوند* برای رستگاری آماده هستی.

تنها مشکل تو حل شده است! امروز این را بارها وبارها با قدرشناسی و اعتقاد برای خود تکرار کن. تو تنها مشکل خود را تشخیص داده‌ای، و راه را برای روح‌القدس* گشوده‌ای تا او* پاسخ خداوند* را به تو عطا کند. تو فریب خوردگی را کنار گذاشته‌ای، و نور حقیقت را دیده‌ای. تو با آوردن مشکل به نزد پاسخ، رستگاری را برای خودت پذیرفته‌ای. و می‌توانی پاسخ را تشخیص دهی، زیرا مشکل فهمیده شده است.

امروز تو مستحق صلح هستی. مشکلی که حل شده است نمی‌تواند آزارت دهد. فقط مطمئن شو از یاد نمی‌بری که همه‌ی مشکلات یکی هستند. مادامی که این را به یاد داری، شکل‌های بسیار آن‌ها تو را فریب نمی‌دهند. یک مشکل، یک راه حل. صلحی را که این جمله ساده به ارمغان می‌آورد بپذیر.

امروز در تمرین‌های طولانی‌تر، ما آن صلح را طلب خواهیم کرد که وقتی مشکل و راه حل نزد هم آورده می‌شوند، باید از آن ما گردد. مشکل باید از بین برود، زیرا پاسخ خداوند* قطعی است. با تشخیص یکی، دیگری را تشخیص داده‌ای. پاسخ در مشکل درج است. به تو پاسخ داده می‌شود، و پاسخ را پذیرفته‌ای. تو نجات می‌یابی.

حال اجازه بده که پذیرش تو صلح را برایت به ارمغان بیاورد. چشمانت را ببند و پاداش خود را دریافت کن. تشخیص بده که مشکلات تو حل شده‌اند. تشخیص بده که خارج از تعارض هستی؛ آزاد و در صلح. بالاتر از همه، به یاد داشته باش که یک مشکل داری، و این مشکل یک راه حل دارد. سادگی رستگاری در همین نکته است. همین دلیل است که، به نتیجه رسیدن آن را تضمین می‌کند.

امروز بارها به خودت اطمینان بده که مشکلات تو حل شده‌اند. این ایده را با اعتقاد ژرف تکرار کن، به هر تعداد دفعات ممکن. و خصوصاً مطمئن شو که ایده‌ی امروز را با هر مشکل خاصی که پیش می‌آید، تمرین می‌کنی. سریعاً بگو: باشد تا تشخیص دهم که این مشکل حل شده است.

بیایید امروز مصمم شویم که گلایه‌ها را گردآوری نکنیم. بیایید مصمم شویم که از مشکلاتی که وجود ندارند، آزاد باشیم. وسیلهٔ ما، صداقت ساده است. خودت را در این مورد که مشکل چیست، فریب نده، و باید تشخیص دهی که مشکل حل شده است.', 'https://acim-farsi.org/workbook/lesson/80', 'https://acim-farsi.org/audio/workbook/lesson/80.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (81, 'مرور (۶۱ و ۶۲)', '(۶۱) من نور این دنیا هستم.
۶۲) بخشایش وظیفهٔ من به عنوان نور این دنیا است.

برخی از شکل‌های اختصاصی برای استفاده از این ایده در زمان بروز ظاهری مشکلات خاص می‌توانند چنین باشند:
باشد تا نور این دنیا را در درونم پوشیده نسازم.
باشد تا نور این دنیا از طریق این تجلی تابش کند.
این سایه در برابر نور محو خواهد شد.

شکل‌های اختصاصی برای استفاده از این ایده ممکن است مانند این باشد:
باشد تا این به من کمک کند بیاموزم که معنای بخشایش چیست.
باشد تا من وظیفه‌ام را از اراده‌ام جدا نبینم.
من از این برای یک قصد بیگانه استفاده نخواهم کرد.', 'امروز ایده‌های ما برای مرور این‌ها هستند:

(۶۱) من نور این دنیا هستم. من چه سان قدسی هستم، آن‌کس که وظیفهٔ نورانی کردن دنیا به او عطا شده است. باشد تا در برابر قداست خود آرام باشم. باشد تا در نور آرامش‌بخش آن، همه تعارض‌های من ناپدید شوند. باشد تا در صلح آن به یاد بیاورم چه* کسی* هستم.

برخی از شکل‌های اختصاصی برای استفاده از این ایده در زمان بروز ظاهری مشکلات خاص می‌توانند چنین باشند: باشد تا نور این دنیا را در درونم پوشیده نسازم. باشد تا نور این دنیا از طریق این تجلی تابش کند. این سایه در برابر نور محو خواهد شد.

۶۲) بخشایش وظیفهٔ من به عنوان نور این دنیا است. من از طریق پذیرش وظیفه‌ام، نور را در درونم خواهم دید. و در این نور، وظیفهٔ من پیش رویم روشن و بدون ابهام خواهد شد. پذیرش من به تشخیص این که وظیفه‌ام چیست بستگی ندارد، زیرا من هنوز بخشایش را درک نکرده‌ام. اما به آن اعتماد خواهم کرد، در نور، من آن را چنان که هست خواهم دید.

شکل‌های اختصاصی برای استفاده از این ایده ممکن است مانند این باشد: باشد تا این به من کمک کند بیاموزم که معنای بخشایش چیست. باشد تا من وظیفه‌ام را از اراده‌ام جدا نبینم. من از این برای یک قصد بیگانه استفاده نخواهم کرد.', 'https://acim-farsi.org/workbook/lesson/81', 'https://acim-farsi.org/audio/workbook/lesson/81.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (82, 'مرور (۶۳ و ۶۴)', '(۶۳) نور این دنیا از طریق بخشایش من برای همهٔ ذهن‌ها صلح به ارمغان می‌آورد.
(۶۴) باشد تا من وظیفه‌ام را از یاد نبرم.

پیشنهادها برای شکل خاص تمرین با این ایده این‌ها هستند:
باشد تا صلح از ذهن من به ذهن تو گسترش یابد (نام).
من نور این دنیا را با تو سهیم می‌شوم (نام).
از طریق بخشایش، من می‌توانم این را آنگونه که هست ببینم.

شکل‌های خاص مناسب این ایده عبارتند از:
باشد تا از این برای پنهان کردن وظیفه‌ام از خودم استفاده نکنم.
من می‌خواهم از این به عنوان فرصتی برای به انجام رساندن وظیفه‌ام استفاده کنم.
این ممکن است نفس مرا تهدید کند، اما به هیچ وجه نمی‌تواند وظیفه‌ام را تغییر دهد.', 'امروز این ایده‌ها را مرور خواهیم کرد:

(۶۳) نور این دنیا از طریق بخشایش من برای همهٔ ذهن‌ها صلح به ارمغان می‌آورد. بخشایش من آن وسیله است که توسط آن نور دنیا از طریق من تجلی می‌یابد. بخشایش من آن وسیله است که توسط آن، من از حضور نور دنیا در خودم آگاه می‌شوم. بخشایش من آن وسیله است که توسط آن، دنیا شفا می‌یابد، همراه با خود من. پس باشد تا من دنیا را ببخشم، تا این دنیا بتواند همراه با من شفا یابد.

پیشنهادها برای شکل خاص تمرین با این ایده این‌ها هستند: باشد تا صلح از ذهن من به ذهن تو گسترش یابد (نام). من نور این دنیا را با تو سهیم می‌شوم (نام). از طریق بخشایش، من می‌توانم این را آنگونه که هست ببینم.

(۶۴) باشد تا من وظیفه‌ام را از یاد نبرم. من نمی‌خواهم وظیفه‌ام را فراموش کنم، زیرا می‌خواهم خویشتنم* را به یاد بیاورم. من نمی‌توانم وظیفه‌ام را به انجام برسانم اگر آن را از یاد ببرم. و تا زمانی که وظیفه‌ام را به انجام نرسانم، آن سرور را که خداوند* برایم در نظر دارد تجربه نخواهم کرد.

شکل‌های خاص مناسب این ایده عبارتند از: باشد تا از این برای پنهان کردن وظیفه‌ام از خودم استفاده نکنم. من می‌خواهم از این به عنوان فرصتی برای به انجام رساندن وظیفه‌ام استفاده کنم. این ممکن است نفس مرا تهدید کند، اما به هیچ وجه نمی‌تواند وظیفه‌ام را تغییر دهد.', 'https://acim-farsi.org/workbook/lesson/82', 'https://acim-farsi.org/audio/workbook/lesson/82.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (83, 'مرور (۶۵ و ۶۶)', '(۶۵) تنها وظیفهٔ من آن است که خداوند* به من عطا کرد.
(۶۶) شادمانی‌ام و وظیفه‌ام یکی هستند.

استفاده‌های اختصاصی‌تر از این ایده می‌توانند به این شکل‌ها باشند:
ادراک من از این، وظیفه‌ام را تغییر نمی‌دهد.
این وظیفه‌ای جز آنچه خداوند* به من عطا کرد، به من نمی‌دهد.
باشد تا از این برای توجیه وظیفه‌ای که خداوند* به من عطا نکرد، استفاده نکنم.

برخی شکل‌های مفید برای استفادهٔ اختصاصی از این ایده عبارتند از:
این نمی‌تواند شادمانی مرا از وظیفه‌ام جدا کند.
یگانگیِ شادمانی‌ام و وظیفه‌ام کاملا بی‌تأثیر از این باقی می‌ماند.
هیچ چیز، از جمله این، نمی‌تواند وهم جدا بودن شادمانی من از وظیفه‌ام را توجیه کند.', 'بیایید امروز این ایده‌ها را مرور کنیم:

(۶۵) تنها وظیفهٔ من آن است که خداوند* به من عطا کرد. من هیچ وظیفه‌ای جز آنچه خداوند* به من عطا کرد ندارم. این تشخیص مرا از همهٔ تعارض‌ها رها می‌کند، زیرا بدین معنا است که من نمی‌توانم اهدافی متعارض با یکدیگر داشته باشم. با داشتن یک قصد یگانه، من همیشه مطمئن هستم که چه کنم، چه بگویم و چه بپندارم. همهٔ تردیدها باید ناپدید شوند هنگامی که من تصدیق کنم که تنها وظیفه‌ام، آن است که خداوند* به من عطا کرد.

استفاده‌های اختصاصی‌تر از این ایده می‌توانند به این شکل‌ها باشند: ادراک من از این، وظیفه‌ام را تغییر نمی‌دهد. این وظیفه‌ای جز آنچه خداوند* به من عطا کرد، به من نمی‌دهد. باشد تا از این برای توجیه وظیفه‌ای که خداوند* به من عطا نکرد، استفاده نکنم.

(۶۶) شادمانی‌ام و وظیفه‌ام یکی هستند. همهٔ چیزهایی که از سوی خداوند* می‌آیند یگانه هستند. آن‌ها از یگانگی* می‌آیند، و باید به صورت یگانه دریافت شوند. به انجام رساندن وظیفهٔ من، شادمانی من است زیرا هر دو از یک خاستگاه* سرچشمه می‌گیرند. و من باید بیاموزم که تشخیص دهم چه چیزی مرا شاد می‌کند، اگر می‌خواهم شادمانی را بیابم.

برخی شکل‌های مفید برای استفادهٔ اختصاصی از این ایده عبارتند از: این نمی‌تواند شادمانی مرا از وظیفه‌ام جدا کند. یگانگیِ شادمانی‌ام و وظیفه‌ام کاملا بی‌تأثیر از این باقی می‌ماند. هیچ چیز، از جمله این، نمی‌تواند وهم جدا بودن شادمانی من از وظیفه‌ام را توجیه کند.', 'https://acim-farsi.org/workbook/lesson/83', 'https://acim-farsi.org/audio/workbook/lesson/83.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (84, 'مرور (۶۷ و ۶۸)', '(۶۷) عشق مرا همانند خودش آفرید.
(۶۸) عشق هیچ گلایه‌ای را نگه نمی‌دارد.

ممکن است این شکل‌های اختصاصی در تمرین با این ایده برای تو مفید باشند:
باشد تا وهمی از خودم را در این نبینم.
با نگریستن به این، باشد تا آفریدگارم* را به یاد بیاورم.
آفریدگارم* این را آن‌گونه که من می‌بینم نیافرید.

این شکل‌های اختصاصی در تمرین با این ایده مفید هستند:
این توجیهی برای انکار خویشتنم* نیست.
من از این برای حمله به عشق استفاده نخواهم کرد.
بگذار این مرا وسوسه نکند که به خودم حمله کنم.', 'این‌ها ایده‌های مرور امروز هستند:

(۶۷) عشق مرا همانند خودش آفرید. من در همانندی با آفریدگارم* هستم. من نمی‌توانم رنج بکشم، نمی‌توانم فقدان را تجربه کنم و نمی‌توانم بمیرم. من یک بدن نیستم. امروز می‌خواهم واقعیتم را بشناسم. من هیچ خدای دروغینی را پرستش نخواهم کرد، و خودپنداره‌ام را جایگزینِ خویشتنم* نخواهم کرد. من در همانندی با آفریدگارم* هستم. عشق مرا همانند خودش آفرید.

ممکن است این شکل‌های اختصاصی در تمرین با این ایده برای تو مفید باشند: باشد تا وهمی از خودم را در این نبینم. با نگریستن به این، باشد تا آفریدگارم* را به یاد بیاورم. آفریدگارم* این را آن‌گونه که من می‌بینم نیافرید.

(۶۸) عشق هیچ گلایه‌ای را نگه نمی‌دارد. گلایه‌ها کاملاً با عشق بیگانه‌اند. گلایه‌ها به عشق حمله می‌کنند و نور آن را پنهان می‌سازند. اگر من گلایه‌ها را نگه دارم در حال حمله به عشق هستم، پس در حال حمله به خویشتنم* هستم. در این صورت خویشتنم* برایم بیگانه می‌شود. من مصمم هستم که امروز به خویشتنم* حمله نکنم، تا بتوانم به یاد بیاورم که چه کسی* هستم.

این شکل‌های اختصاصی در تمرین با این ایده مفید هستند: این توجیهی برای انکار خویشتنم* نیست. من از این برای حمله به عشق استفاده نخواهم کرد. بگذار این مرا وسوسه نکند که به خودم حمله کنم.', 'https://acim-farsi.org/workbook/lesson/84', 'https://acim-farsi.org/audio/workbook/lesson/84.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (85, 'مرور (۶۹ و ۷۰)', '(۶۹) گلایه‌های من، نور این دنیا را در درونم پنهان می‌کنند.
(۷۰) رستگاری من از من سرچشمه می‌گیرد.

این ایده را می‌توان در شکل‌های زیر به صورت اختصاصی به کار برد:
باشد تا از این به عنوان سدی برای رؤیت استفاده نکنم.
نور دنیا با درخشش خود همهٔ این را بر طرف خواهد کرد.
من نیازی به این ندارم. من می‌خواهم ببینم.

این شکل‌های ایده برای استفاده‌های اختصاصی‌تر مناسب هستند:
باشد تا این مرا وسوسه نکند که در بیرون از خودم به دنبال رستگاری باشم.
من اجازه نخواهم داد که این با آگاهی من از خاستگاه* رستگاری‌ام تداخل کند.
این هیچ قدرتی برای دور کردن رستگاری از من ندارد.', 'مرور امروز درس‌های زیر را در بر می‌گیرد:

(۶۹) گلایه‌های من، نور این دنیا را در درونم پنهان می‌کنند. گلایه‌های من چیزی را به من نشان می‌دهند که وجود ندارد، و چیزی را که می‌خواهم ببینم از من پنهان می‌کنند. با این شناخت، من گلایه‌هایم را برای چه می‌خواهم؟ آن‌ها مرا در تاریکی نگه می‌دارند و نور را پنهان می‌کنند. گلایه‌ها و نور نمی‌توانند همراه با هم باشد، اما نور و رؤیت باید برای دیدن من به هم بپیوندند. برای دیدن، باید گلایه‌ها را کنار بگذارم. من می‌خواهم ببینم، و این همان وسیله خواهد بود که من با آن توفیق خواهم یافت.

این ایده را می‌توان در شکل‌های زیر به صورت اختصاصی به کار برد: باشد تا از این به عنوان سدی برای رؤیت استفاده نکنم. نور دنیا با درخشش خود همهٔ این را بر طرف خواهد کرد. من نیازی به این ندارم. من می‌خواهم ببینم.

(۷۰) رستگاری من از من سرچشمه می‌گیرد. من امروز تشخیص خواهم داد که رستگاری‌ام در کجا است. در من است، زیرا خاستگاه* آن در آنجا است. رستگاری خاستگاه* خود را ترک نکرده است، پس نمی‌تواند ذهن مرا ترک کرده باشد. من به دنبال آن در بیرون از خودم نخواهم گشت. در بیرون یافت نمی‌شود که به درون آورده شود. اما از درون من به ورای من خواهد رسید، و همهٔ چیزهایی که من می‌بینم فقط بازتاب آن نور خواهند بود که در من و در خود آن‌ها تابش می‌کند.

این شکل‌های ایده برای استفاده‌های اختصاصی‌تر مناسب هستند: باشد تا این مرا وسوسه نکند که در بیرون از خودم به دنبال رستگاری باشم. من اجازه نخواهم داد که این با آگاهی من از خاستگاه* رستگاری‌ام تداخل کند. این هیچ قدرتی برای دور کردن رستگاری از من ندارد.', 'https://acim-farsi.org/workbook/lesson/85', 'https://acim-farsi.org/audio/workbook/lesson/85.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (86, 'مرور (۷۱ و ۷۲)', '(۷۱) تنها نقشهٔ خداوند* برای رستگاری به نتیجه خواهد رسید.
(۷۲) نگه داشتن گلایه‌ها، حمله‌ای به نقشهٔ خداوند* برای رستگاری است.

این‌ها برخی شکل‌های پیشنهادی برای تمرین اختصاصی با این ایده هستند:
نقشهٔ خداوند* برای رستگاری مرا از این ادراکم نجات خواهد داد.
این هیچ مورد استثنایی در نقشهٔ خداوند* برای رستگاری من نیست.
باشد تا این را تنها در نور نقشهٔ خداوند* برای رستگاری ادراک کنم.

استفاده‌های اختصاصی از این ایده ممکن است به این شکل‌ها باشند:
زمانی که به این نگاه می‌کنم، در حال انتخاب بین ادراک نادرست و رستگاری هستم.
اگر من زمینه‌های گلایه را در این ببینم، زمینه‌های رستگاری را نخواهم دید.
این نیازمند رستگاری است، نه حمله.', 'این ایده‌ها برای مرور امروز هستند:

(۷۱) تنها نقشهٔ خداوند* برای رستگاری به نتیجه خواهد رسید. برای من احمقانه است که این‌سو و آن‌سو سرگردان به دنبال رستگاری بگردم. من آن را در بسیاری از افراد و بسیاری از چیزها دیده‌ام، اما وقتی به آن رسیدم، فهمیدم که آنجا نیست. من در مورد این که رستگاری در کجا است اشتباه کردم. من در مورد این که رستگاری چیست اشتباه کردم. من دیگر جستجوی بیهوده‌ای انجام نخواهم داد. تنها نقشهٔ خداوند* برای رستگاری به نتیجه خواهد رسید. و من شاد خواهم شد زیرا نقشهٔ او* هرگز شکست نمی‌خورد.

این‌ها برخی شکل‌های پیشنهادی برای تمرین اختصاصی با این ایده هستند: نقشهٔ خداوند* برای رستگاری مرا از این ادراکم نجات خواهد داد. این هیچ مورد استثنایی در نقشهٔ خداوند* برای رستگاری من نیست. باشد تا این را تنها در نور نقشهٔ خداوند* برای رستگاری ادراک کنم.

(۷۲) نگه داشتن گلایه‌ها، حمله‌ای به نقشهٔ خداوند* برای رستگاری است. نگه داشتن گلایه‌ها تلاشی است برای اثبات این که نقشهٔ خداوند* برای رستگاری به نتیجه نخواهد رسید. اما تنها نقشه او* است که به نتیجه می‌رسد. پس با نگه داشتن گلایه‌ها، من می‌خواهم تنها امیدم را به رستگاری از آگاهی خودم حذف کنم. من دیگر نمی‌خواهم با بهترین مصالح خود به این شیوه‌ی دیوانه‌وار ستیز کنم. می‌خواهم نقشهٔ خداوند* برای رستگاری را بپذیرم، و شاد باشم.

استفاده‌های اختصاصی از این ایده ممکن است به این شکل‌ها باشند: زمانی که به این نگاه می‌کنم، در حال انتخاب بین ادراک نادرست و رستگاری هستم. اگر من زمینه‌های گلایه را در این ببینم، زمینه‌های رستگاری را نخواهم دید. این نیازمند رستگاری است، نه حمله.', 'https://acim-farsi.org/workbook/lesson/86', 'https://acim-farsi.org/audio/workbook/lesson/86.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (87, 'مرور (۷۳ و ۷۴)', '(۷۳) من اراده می‌کنم که نور باشد.
(۷۴) هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد.

این شکل‌های ایده برای استفادهٔ اختصاصی مفید خواهند بود:
این نمی‌تواند آن نور را که من اراده می‌کنم ببینم، پنهان کند.
تو به همراه من در نور می‌ایستی، [نام].
در نور، این متفاوت دیده خواهد شد.

این‌ها برخی شکل‌های مفید این ایده برای استفاده‌ی اختصاصی هستند:
باشد تا ادراک کنم که این در همراهی با ارادهٔ* خداوند* است.
این ارادهٔ* خداوند* است که تو فرزند* او* باشی [نام]، و ارادهٔ من نیز همین است.
این بخشی از ارادهٔ* خداوند* برای من است، هر چقدر که من بتوانم ببینم.', 'مرور امروز ما شامل ایده‌های زیر می‌شود:

(۷۳) من اراده می‌کنم که نور باشد. من امروز از قدرت اراده‌ام استفاده خواهم کرد. ارادهٔ من این نیست که در تاریکی مانند یک کور سرگردان باشم، هراسان از سایه‌ها و وحشت‌زده از چیزهای نادیدنی و غیرواقعی. امروز نور هدایت‌گر من خواهد بود. من از آن پیروی می‌کنم، به آنجا که مرا هدایت می‌کند، و فقط به چیزی نگاه خواهم کرد که آن به من نشان می‌دهد. در این روز من صلحِ ادراک درست را تجربه خواهم کرد.

این شکل‌های ایده برای استفادهٔ اختصاصی مفید خواهند بود: این نمی‌تواند آن نور را که من اراده می‌کنم ببینم، پنهان کند. تو به همراه من در نور می‌ایستی، [نام]. در نور، این متفاوت دیده خواهد شد.

(۷۴) هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. امروز من در امنیت هستم زیرا هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد. من تنها زمانی می‌توانم هراسان شوم که باور کنم اراده‌ای دیگر وجود دارد. من فقط زمانی برای حمله تلاش می‌کنم که هراسان باشم. و فقط زمانی که برای حمله تلاش می‌کنم، می‌توانم باور کنم که امنیت جاوید من تهدید می‌شود. امروز من تشخیص خواهم داد که همه‌ی این‌ها هرگز رخ نداده است. من در امنیت هستم زیرا هیچ اراده‌ای جز ارادهٔ* خداوند* وجود ندارد.

این‌ها برخی شکل‌های مفید این ایده برای استفاده‌ی اختصاصی هستند: باشد تا ادراک کنم که این در همراهی با ارادهٔ* خداوند* است. این ارادهٔ* خداوند* است که تو فرزند* او* باشی [نام]، و ارادهٔ من نیز همین است. این بخشی از ارادهٔ* خداوند* برای من است، هر چقدر که من بتوانم ببینم.', 'https://acim-farsi.org/workbook/lesson/87', 'https://acim-farsi.org/audio/workbook/lesson/87.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (88, 'مرور (۷۵ و ۷۶)', '(۷۵) نور آمده است.
(۷۶) من تحت هیچ قانونی جز قانون‌های خداوند* نیستم.

این‌ها می‌توانند شکل‌های مفید برای استفاده‌ی اختصاصی از این ایده باشند:
این نمی‌تواند تاریکی را به من نشان دهد، زیرا نور آمده است.
نور درون تو همهٔ چیزی است که من می‌خواهم ببینم [نام].
من می‌خواهم فقط آن چیزی را در این ببینم که وجود دارد.

این شکل‌های اختصاصی می‌توانند برای کار با این ایده مفید باشند:
ادراکم از این به من نشان می‌دهد به قانون‌هایی باور دارم که وجود ندارند.
من فقط قانون‌های خداوند* را در این جاری می‌بینم.
باشد تا اجازه دهم قانون‌‌های خداوند* در این جاری شوند، و نه قانون‌های خود من.', 'ما امروز این ایده‌ها را مرور خواهیم کرد:

(۷۵) نور آمده است. در انتخاب کردن رستگاری به جای حمله، من صرفاً انتخاب می‌کنم چیزی را تشخیص دهم که پیشاپیش وجود دارد. رستگاری تصمیمی است که پیشاپیش گرفته شده است. حمله و گلایه‌ها وجود ندارند پس نمی‌توانند انتخاب شوند. به این دلیل است که من همیشه بین حقیقت و وهم انتخاب می‌کنم؛ بین آنچه وجود دارد و آنچه وجود ندارد. نور آمده است. من فقط می‌توانم نور را انتخاب کنم، زیرا نور هیچ جایگزینی ندارد. نور جایگزین تاریکی شده، و تاریکی رفته است.

این‌ها می‌توانند شکل‌های مفید برای استفاده‌ی اختصاصی از این ایده باشند: این نمی‌تواند تاریکی را به من نشان دهد، زیرا نور آمده است. نور درون تو همهٔ چیزی است که من می‌خواهم ببینم [نام]. من می‌خواهم فقط آن چیزی را در این ببینم که وجود دارد.

(۷۶) من تحت هیچ قانونی جز قانون‌های خداوند* نیستم. این بیانیهٔ کامل آزادی من است. من تحت هیچ قانونی جز قانون‌های خداوند* نیستم. من مدام وسوسه می‌شوم تا قانون‌های دیگری بسازم و قدرت حاکمیت بر خودم را به آن‌ها بدهم. تنها دلیل رنج بردن من این است که به آن‌ها باور دارم. آن‌ها اصلاً هیچ تأثیر واقعی بر من ندارند. من کاملاً از تأثیر همهٔ قانون‌ها جز قانون‌های خداوند* آزاد هستم. و قانون‌های* او*، قانون‌‌های آزادی هستند.

این شکل‌های اختصاصی می‌توانند برای کار با این ایده مفید باشند: ادراکم از این به من نشان می‌دهد به قانون‌هایی باور دارم که وجود ندارند. من فقط قانون‌های خداوند* را در این جاری می‌بینم. باشد تا اجازه دهم قانون‌‌های خداوند* در این جاری شوند، و نه قانون‌های خود من.', 'https://acim-farsi.org/workbook/lesson/88', 'https://acim-farsi.org/audio/workbook/lesson/88.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (89, 'مرور (۷۷ و ۷۸)', '(۷۷) من سزاوار معجزات هستم.
(۷۸) باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند.

می‌توانی از این پیشنهادها برای تمرین اختصاصی با ایده استفاده کنی:
در پس این، معجزه‌ای هست که برای من مقرر شده است.
باشد تا گلایه‌ای را بر علیه تو نگه ندارم [نام]، بلکه آن معجزه را به تو عرضه کنم که به جای این متعلق به تو است.
باشد تا گلایه‌ای را بر علیه تو نگه ندارم [نام]، بلکه آن معجزه را به تو عرضه کنم که به جای این متعلق به تو است.
اگر حقیقتاً ببینم، این معجزه‌ای را به من عرضه می‌کند.

شکل‌های اختصاصی مفید برای تمرین با این ایده عبارتند از:
من نمی‌خواهم جدا از رستگاری خودم، این گلایه را نگه دارم.
بگذار گلایه‌های ما با معجزه جایگزین شوند [نام].
ورای این، آن معجزه‌ حضور دارد که جایگزین همهٔ گلایه‌های من می‌شود.', 'این‌ها ایده‌هایی هستند که امروز مرور می‌کنیم:

(۷۷) من سزاوار معجزات هستم. من سزاوار معجزات هستم زیرا تحت هیچ قانونی جز قانون‌های خداوند* نیستم. قانون‌های او* مرا از همهٔ گلایه‌ها رها می‌کنند و آن‌ها را با معجزات جایگزین می‌سازند. و من می‌خواهم معجزات را به جای گلایه‌ها بپذیرم، گلایه‌ها فقط اوهامی هستند که معجزاتِ ورای خود را پنهان می‌کنند. اینک من می‌خواهم فقط چیزی را بپذیرم که قانون‌های خداوند* آن را برای من مقرر کرده‌اند، تا بتوانم از آن به سود وظیفه‌ای استفاده کنم که او* به من عطا کرده است.

می‌توانی از این پیشنهادها برای تمرین اختصاصی با ایده استفاده کنی: در پس این، معجزه‌ای هست که برای من مقرر شده است. باشد تا گلایه‌ای را بر علیه تو نگه ندارم [نام]، بلکه آن معجزه را به تو عرضه کنم که به جای این متعلق به تو است. اگر حقیقتاً ببینم، این معجزه‌ای را به من عرضه می‌کند.

(۷۸) باشد تا معجزات جایگزین همهٔ گلایه‌ها شوند. من توسط این ایده، اراده‌ام را با ارادهٔ* روح‌القدس* یگانه می‌کنم، و ادراک می‌کنم که آن‌ها یکی هستند. من توسط این ایده، آزادیم از جهنم را می‌پذیرم. من توسط این ایده، اراده‌ام را برای جایگزین کردن همهٔ اوهام خود با حقیقت اعلام می‌کنم، بر حسب نقشهٔ خداوند* برای رستگاریم. من می‌خواهم هیچ استثنا و هیچ جایگزینی نداشته باشم. من همهٔ بهشت* و فقط بهشت* را می‌خواهم، آنچنان که ارادهٔ* خداوند* بر آن قرار گرفته است.

شکل‌های اختصاصی مفید برای تمرین با این ایده عبارتند از: من نمی‌خواهم جدا از رستگاری خودم، این گلایه را نگه دارم. بگذار گلایه‌های ما با معجزه جایگزین شوند [نام]. ورای این، آن معجزه‌ حضور دارد که جایگزین همهٔ گلایه‌های من می‌شود.', 'https://acim-farsi.org/workbook/lesson/89', 'https://acim-farsi.org/audio/workbook/lesson/89.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (90, 'مرور (۷۹ و ۸۰)', '(۷۹) باشد تا مشکل را تشخیص دهم تا بتواند حل شود.
(۸۰) باشد تا تشخیص دهم که مشکلات من حل شده‌اند.

استفاده‌های اختصاصی از این ایده می‌توانند به شکل‌های زیر باشند:
این مشکلی را به من نشان می‌دهد که می‌خواهم حل کرده باشم.
معجزهٔ ورای این گلایه، آن را برای من حل خواهد کرد.
پاسخ این مشکل، آن معجزه است که این مشکل پنهانش می‌کند.

این شکل‌های ایده برای استفاده‌های اختصاصی مفید خواهند بود:
من نیازی ندارم انتظار بکشم تا این حل شود.
پاسخ این مشکل پیشاپیش به من داده شده است، اگر بخواهم آن را بپذیرم.
زمان نمی‌تواند این مشکل را از راه حل آن جدا کند.', 'برای مرور امروز، ما از ایده‌های زیر استفاده خواهیم کرد:

(۷۹) باشد تا مشکل را تشخیص دهم تا بتواند حل شود. باشد تا امروز تشخیص دهم که مشکل همیشه شکلی از گلایه است که من می‌خواهم بپرورم. باشد تا این را نیز درک کنم که راه حل همیشه معجزه‌ای است که اجازه می‌دهم جایگزین گلایه‌ گردد. من امروز می‌خواهم با تقویت این درس که یک مشکل و یک راه حل وجود دارد، ساده بودن رستگاری را به یاد بیاورم. مشکل یک گلایه است؛ راه حل یک معجزه است. و من راه حل را دعوت می‌کنم که از طریق بخشایش گلایه‌ها و استقبال من از آن معجزات که جایگزین آن‌ها می‌شوند، به سویم بیاید.

استفاده‌های اختصاصی از این ایده می‌توانند به شکل‌های زیر باشند: این مشکلی را به من نشان می‌دهد که می‌خواهم حل کرده باشم. معجزهٔ ورای این گلایه، آن را برای من حل خواهد کرد. پاسخ این مشکل، آن معجزه است که این مشکل پنهانش می‌کند.

(۸۰) باشد تا تشخیص دهم که مشکلات من حل شده‌اند. به نظر می‌رسد که مشکلات من فقط به دلیل استفاده‌ی نامناسب از زمان وجود دارند. من باور دارم که ابتدا مشکل پیش می‌آید، و سپس باید زمان بگذرد تا بتوان آن را حل کرد. من ظهور مشکل و پاسخ را همزمان نمی‌بینم. زیرا هنوز تشخیص نمی‌دهم که خداوند* پاسخ را در کنار مشکل قرار داده است، آنچنان که زمان نمی‌تواند آن‌ها را از هم جدا کند. روح‌القدس* این را به من خواهد آموخت، اگر من بخواهم که به او اجازه دهم. و درک خواهم کرد که ناممکن است بتوانم مشکلی داشته باشم که پیشاپیش حل نشده باشد.

این شکل‌های ایده برای استفاده‌های اختصاصی مفید خواهند بود: من نیازی ندارم انتظار بکشم تا این حل شود. پاسخ این مشکل پیشاپیش به من داده شده است، اگر بخواهم آن را بپذیرم. زمان نمی‌تواند این مشکل را از راه حل آن جدا کند.', 'https://acim-farsi.org/workbook/lesson/90', 'https://acim-farsi.org/audio/workbook/lesson/90.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (91, 'معجزات در نور دیده می‌شوند.', 'تمرین کوتاه‌تر:

معجزات در نور دیده می‌شوند. باشد تا به خاطر این چشمانم را نبندم.

تمرین طولانی‌تر:

معجزات در نور دیده می‌شوند.
چشمان بدن نور را ادراک نمی‌کنند.
اما من یک بدن نیستم. من چه هستم؟', 'معجزات در نور دیده می‌شوند.

مهم است به یاد داشته باشیم که معجزات و رؤیت الزاماً با هم هستند. این نیاز به تکرار دارد، و تکرار بسیار. این یک ایدهٔ محوری در سیستم فکری جدید تو و آن ادراک است که این سیستم جدید فکری ایجاد می‌کند. معجزه همیشه آنجا وجود دارد. رؤیت تو علت حضور معجزه نیست؛ و ناکامی تو در دیدن موجب غیاب آن نمی‌شود. فقط آگاهی تو از معجزات است که تحت تأثیر قرار می‌گیرد. تو معجزات را در روشنایی می‌بینی، و آن‌ها را در تاریکی نمی‌بینی.

پس برای تو نور بسیار مهم است. تا زمانی که در تاریکی می‌مانی، معجزه نادیده باقی می‌ماند. پس تو قانع می‌شوی که وجود ندارد. این نتیجهٔ همان فرضیات است که تاریکی از آن‌ها برآمده است. انکار نور منجر به شکست در ادراک آن می‌شود. شکست در ادراک نور یعنی ادراک تاریکی. آنگاه نور برای تو بی‌فایده خواهد بود، حتی اگر آنجا وجود داشته باشد. نمی‌توانی از آن استفاده کنی، زیرا حضورش برای تو ناشناخته است. و واقعیت داشتن ظاهری تاریکی، ایده‌ی نور را بی‌معنا می‌کند.

گفتن این که چیزی که تو نمی‌بینی وجود دارد، مانند دیوانگی به نظر می‌رسد. بسیار سخت است که قانع شویم آنچه دیوانگی است، ندیدن چیزی است که وجود دارد، و به جای آن دیدن چیزی که وجود ندارد. تو تردیدی نداری که چشمان بدن می‌توانند ببینند. تردیدی نداری که تصویرهایی که به تو نشان می‌دهند، واقعیت هستند. تو به تاریکی ایمان داری، نه به نور. چگونه می‌توان این را وارونه کرد؟ برای تو این ناممکن است، اما در این کار تنها نیستی.

تلاش‌های تو، هرچند کوچک، با قدرت حمایت می‌شوند. اگر فقط تشخیص می‌دادی که این قدرت چقدر عظیم است، تردیدهای تو ناپدید می‌شدند. امروز ما خود را وقف این تلاش خواهیم کرد که به تو اجازه دهیم این قدرت را احساس کنی. زمانی که قدرت را در خود احساس کرده باشی، و همهٔ معجزات به آسانی در دسترس تو قرار گیرند، دیگر هیچ تردیدی نخواهی داشت. با احساس کردن قدرت در درونت، آن معجزات که احساس ضعف از تو پنهان می‌کند، به آگاهی تو خواهند رسید.

امروز در سه نوبت، حدود ده دقیقه را به داشتن یک زمان ساکت اختصاص بده که در آن تلاش می‌کنی ضعف خود را پشت سر بگذاری. این بسیار ساده به انجام می‌رسد، هنگامی که به خودت بیاموزی که یک بدن نیستی. ایمان به سویی که می‌خواهی می‌رود، و تو در ارتباط با آن ذهن خود را آموزش می‌دهی. اراده‌ی تو آموزگار تو باقی خواهد ماند، و اراده‌ی تو همه‌ی قدرت انجام خواسته‌ی خود را دارد. اگر انتخاب کنی می‌توانی از بدن بگریزی. می‌توانی قدرت را در درونت تجربه کنی.

برنامه‌های طولانی‌تر تمرین را با این بیان حقیقی در مورد روابط علت و معلولی آغاز کن: معجزات در نور دیده می‌شوند . چشمان بدن نور را ادراک نمی‌کنند. اما من یک بدن نیستم. من چه هستم؟ پرسش پایانی برای تمرین‌های امروز ما ضروری است. آنچه تو می‌پنداری هستی، باوری است که باید فروریزد. اما آنچه واقعاً هستی، باید بر تو آشکار گردد. این باور که تو یک بدن هستی نیاز به تصحیح دارد، زیرا یک اشتباه است. حقیقت آنچه تو هستی، قدرت درونت را فرا می‌خواند تا چیزی را که این اشتباه پنهانش می‌ساخت، به آگاهی تو برساند.

اگر تو یک بدن نیستی، چه هستی؟ تو نیاز داری از آنچه روح‌القدس* استفاده می‌کند تا جایگزین تصویر بدن در ذهنت گردد، آگاه شوی. وقتی دیگر به بدن ایمان نداشته باشی، نیاز داری چیزی را احساس کنی که به آن ایمان بیاوری. نیاز به تجربهٔ واقعی چیز دیگری داری، چیزی محکم‌تر و مطمئن‌تر؛ شایسته‌تر برای ایمان تو، و واقعاً موجود.

اگر تو یک بدن نیستی، چه هستی؟ با خلوص بپرس، و سپس چند دقیقه را به این اختصاص بده که بگذاری پندارهای اشتباه تو در مورد خصلت‌هایت تصحیح شوند، و متضاد آن‌ها جایشان را بگیرد. مثلاً بگو: من ضعیف نیستم، بلکه قوی هستم. من درمانده نیستم، بلکه قدرتمند هستم. من محدود نیستم، بلکه نامحدود هستم. من مردد نیستم، بلکه مطمئن هستم. من یک وهم نیستم، بلکه واقعیت هستم. من نمی‌توانم در تاریکی ببینم، اما در نور می‌توانم.

در مرحلهٔ دوم برنامهٔ تمرین، سعی کن این حقایق را در مورد خودت تجربه کنی. خصوصاً بر تجربهٔ قدرت تمرکز کن. به یاد داشته باش که همهٔ حس ضعف با این باور همراه می‌شود که تو یک بدن هستی، باوری که اشتباه است و ارزش ایمان را ندارد. سعی کن ایمانت را از آن برداری، حتی اگر فقط برای یک لحظه. در ادامهٔ کار خواهی آموخت که به چیزهای باارزش‌تری در درونت ایمان داشته باشی.

در ادامه‌ی برنامه تمرین آسوده باش و مطمئن باش که تلاشت، هرچند ناچیز، از سوی خداوند* و تمامی اندیشه‌هایش* کاملاً حمایت می‌شود. قدرت تو از آن‌ها* خواهد آمد. از طریق حمایت قدرتمندانهٔ آن‌ها* است که تو قدرت را در درونت احساس خواهی کرد. آن‌ها* در این برنامهٔ تمرین با تو متحد هستند، که در آن تو قصدی مانند قصد خود* آن‌ها* را سهیم هستی. قصد آن‌ها* آن نور است که تو در پرتوی آن معجزات را خواهی دید، زیرا قدرتشان* از آن تو است. قدرت آن‌ها* به چشمان تو تبدیل می‌شود، تا بتوانی ببینی.

در هر ساعت پنج یا شش نوبت، ترجیحاً در فاصله‌های ثابت به خودت یادآوری کن که معجزات در نور دیده می‌شوند. همچنین مطمئن شو که با ایدهٔ امروز با وسوسه‌ها روبرو می‌شوی. شکل زیر می‌تواند برای این کاربرد اختصاصی مفید باشد: معجزات در نور دیده می‌شوند. باشد تا به خاطر این چشمانم را نبندم.', 'https://acim-farsi.org/workbook/lesson/91', 'https://acim-farsi.org/audio/workbook/lesson/91.mp3', 'times_per_hour', '[{"kind":"interval","minutes":10},{"kind":"interval","minutes":12}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (92, 'معجزات در نور دیده می‌شوند، و نور و قدرت یکی هستند.', 'معجزات در نور دیده می‌شوند، و نور و قدرت یکی هستند.', 'معجزات در نور دیده می‌شوند، و نور و قدرت یکی هستند.

ایدهٔ امروز گسترشی از ایدهٔ پیشین است. تو به نور بر حسب قدرت، و به تاریکی بر حسب ضعف نمی‌اندیشی. زیرا عقیدهٔ تو در مورد معنای دیدن، به بدن و چشمان آن و مغز مربوط می‌شود. اینچنین تو باور داری که می‌توانی با گذاشتن قطعات کوچکی از شیشه در پیش چشمانت، آنچه را که می‌بینی تغییر دهی. این یکی از باورهای جادویی بسیاری است که از یقین تو به بدن بودن سرچشمه می‌گیرد، و این یقین که چشمان بدن می‌توانند ببینند.

تو همچنین باور داری که مغزِ بدن می‌تواند بیاندیشد. اگر فقط درک می‌کردی که ماهیت اندیشه چیست، به این ایدهٔ نامعقول فقط می‌خندیدی. مانند این است که فکر کنی کبریتی داری که خورشید را روشن می‌کند و همهٔ گرمایش را به آن می‌دهد؛ یا فکر کنی که دنیا را در دست خود گرفته‌ای، سفت و سخت تا زمانی که رهایش کنی. اما این احمقانه‌تر از این نیست که باور داشته باشی چشمان بدن می‌توانند ببینند؛ مغز می‌تواند بیندیشد.

قدرت خداوند* در تو آن نور است که در آن می‌بینی، همانگونه که ذهن* او* است که با آن می‌اندیشی. قدرت او*، ضعف تو را تکذیب می‌کند. این ضعف تو است که از طریق چشمان بدن می‌بیند، خیره به پیرامون در تاریکی تا همانند خودش را مشاهده کند؛ کوچک‌ها، ضعیفان، بیماران و میرندگان، نیازمندان، درماندگان و وحشت‌زدگان، غمگینان، فقیران، قحطی‌زدگان و ناکامان. این‌ها از درون چشمانی دیده می‌شوند که نمی‌توانند ببینند و نمی‌توانند متبرک کنند.

قدرت، این چیزها را با دیدن آنچه ‌که ورای ظواهر است نادیده می‌گیرد. قدرت، نگاه ثابت خود را به نور می‌افکند که ورای آن‌ها قرار گرفته است. قدرت با نور یگانه می‌شود، که بخشی از آن است. قدرت خودش را می‌بیند. نوری را می‌آورد که در آن، خویشتن* تو پدیدار می‌شود. در تاریکی تو آن خودی را ادراک می‌کنی که وجود ندارد. قدرت، حقیقت در مورد تو است؛ ضعف خدایی دروغین است که به نادرستی پرستش و نیایش شده تا بتوان قدرت را دفع کرد، تا تاریکی بتواند آن جایی حاکمیت کند که خداوند* مقرر کرده است نور باید باشد.

قدرت از حقیقت می‌آید، و با نوری که خاستگاهش* به آن داده تابش می‌کند؛ ضعف، تاریکی سازندهٔ آن را بازتاب می‌دهد. سازنده‌ای که بیمار است و به بیماری نظر می‌کند، که همانند خود او است. حقیقت نجات‌بخش است و فقط می‌تواند شادی و صلح را برای همگان اراده کند. حقیقت، قدرتش را به هر کسی که تقاضا کند می‌دهد، به اندازهٔ نامحدود. حقیقت می‌بیند که فقدان در هر کسی، فقدان در همه می‌شود. پس نورش را ارزانی می‌کند تا همه بتوانند یگانه با هم ببینند و بهره‌مند شوند. همه در قدرت آن سهیم می‌شوند، تا بتواند برای همگان آن معجزه را بیاورد که در آن با هم در هدف و بخشایش و در عشق یگانه خواهند شد.

ضعف، که به تاریکی می‌نگرد، نمی‌تواند هدفی را در بخشایش و عشق ببیند. ضعف همه را با خودش متفاوت می‌بیند، و هیچ چیزی را در دنیا نمی‌بیند که بخواهد آن را سهیم شود. ضعف، قضاوت و محکوم می‌کند، اما عشق نمی‌ورزد. در تاریکی می‌ماند تا خودش را پنهان کند، و رؤیا می‌پرورد که قوی و فاتح است، پیروز بر محدودیت‌هایی که فقط در تاریکی به اندازه‌ای عظیم رشد می‌کنند.

ضعف می‌ترسد و حمله می‌کند و از خودش متنفر است، و تاریکی همهٔ چیزهایی را که می‌بیند احاطه می‌کند، و رؤیاهای آن را به اندازهٔ خودش هراسناک می‌سازد. هیچ معجزه‌ای در اینجا نیست، بلکه فقط نفرت هست. ضعف، خود را از آنچه می‌بیند جدا می‌کند، در حالی که نور و قدرت، خود را یگانه ادراک می‌کنند. نورِ قدرت آن نوری نیست که تو می‌بینی. آن تغییر نمی‌کند و کم‌سو نمی‌شود و خاموش نمی‌شود. از شب به روز تغییر نمی‌کند، و‌ باز به تاریکی نمی‌گراید تا زمانی که صبح دوباره برگردد.

نورِ قدرت ثابت است، مطمئن مانند عشق، همیشه شادمان از نثار کردن خود، زیرا نمی‌تواند جز به خودش نثار کند. سهیم شدن در نگاه آن نمی‌تواند برای هیچکس بی‌حاصل باشد، و هیچ کسی که به منزلگاه آن وارد می‌شود نمی‌تواند بدون معجزه‌ای در پیش چشمانش، و قدرت و نوری که در قلبش منزل می‌کند، آنجا را ترک کند.

قدرت درونت نور را به تو عرضه خواهد کرد، و رؤیت تو را هدایت می‌کند تا در سایه‌های پوچ که چشمان بدن برای فریب خود فراهم می‌سازند، استقرار نیابی. قدرت و نور در تو به یگانگی می‌رسند، و آنجا که این دو به هم می‌رسند، خویشتن* تو آماده می‌ایستد تا تو را به عنوان خودش در آغوش بگیرد. ما امروز سعی می‌کنیم چنین مکان ملاقاتی را بیابیم و در آن مستقر شویم، زیرا صلح خداوند* در جایی است که خویشتن* تو، فرزند* او*، اکنون آنجا منتظر است تا دوباره با خودش ملاقات کند، و به یگانگی برسد.

بیایید امروز دو تمرین بیست دقیقه‌ای را به پیوستن به این ملاقات اختصاص دهیم. به خودت اجازه بده که به نزد خویشتن* خود آورده شوی. قدرت آن، نوری خواهد بود که در آن موهبت رؤیت به تو عطا می‌شود. پس امروز برای زمان کوتاهی تاریکی را ترک کن، و ما دیدن در نور را تمرین خواهیم کرد، بستن چشمان بدن و درخواست از حقیقت تا به ما نشان دهد چگونه مکان ملاقات خودمان را با خویشتن* خود بیابیم، جایی که نور و قدرت یگانه هستند.

صبح و عصر بدین گونه تمرین خواهیم کرد. پس از ملاقات صبحگاهی، ما روز را در اعتماد برای آمادگی جهت شب و زمان ملاقات دوباره استفاده خواهیم کرد. بیایید ایده امروز را تا جایی که می‌توانیم بار‌ها تکرار کنیم، و تشخیص دهیم که ما در حال آماده شدن برای بینایی هستیم، و از تاریکی بسوی نور هدایت می‌شویم جایی ‌که فقط معجزات می‌توانند ادراک شوند.', 'https://acim-farsi.org/workbook/lesson/92', 'https://acim-farsi.org/audio/workbook/lesson/92.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (93, 'نور و سرور و صلح در من ساکن است.', 'نور و سرور و صلح در من ساکن است.
بی‌گناهی من توسط خداوند* تضمین می‌شود.

نور و سرور و صلح در من ساکن است.
بی‌گناهی من توسط خداوند* تضمین می‌شود.

برای موقعیت‌های آشفته‌کننده، یا اگر خشمگین شدی:
نور و سرور و صلح در تو ساکن است.
بی‌گناهی تو توسط خداوند* تضمین می‌شود.', 'نور و سرور و صلح در من ساکن است.

تو می‌پنداری که جایگاه شرارت، تاریکی و گناه هستی. می‌پنداری که هر کسی اگر می‌توانست حقیقت را در مورد تو ببیند، زده می‌شد و از تو مانند یک مار زهرآگین رو بر می‌تابید. می‌پنداری که اگر آنچه درمورد تو حقیقت دارد برایت آشکار می‌شد، با چنان وحشت شدیدی از خود زده می‌شدی که می‌خواستی به دست خود در مرگت تعجیل کنی، و پس از ناممکن دیدن این کار به حیات خود ادامه دهی.

این باورها چنان محکم تثبیت شده‌اند که کمک کردن به تو برای دیدن این که این باورها در هیچ بنا شده‌اند، دشوار است. این‌ که مرتکب اشتباه شده‌ای آشکار است. آشکار است که رستگاری را به شیوه‌هایی عجیب جستجو کرده‌ای؛ فریب خورده‌ای، فریب خورده و هراسان از تخیلات احمقانه و رؤیاهای وحشیانه؛ و در برابر خدایان دروغین ساخته شده از غبار تعظیم کرده‌ای، -- همه‌ی این‌ها در مورد باورهای فعلی تو حقیقت دارند.

امروز ما این را مورد پرسش قرار خواهیم داد، نه از دیدگاه آنچه تو می‌پنداری، بلکه از یک دیدگاه بسیار متفاوت، با این دید که این پندارهای باطل، بی‌معنا هستند. این پندارها در همراهی با ارادهٔ* خداوند* نیستند. او* این باورهای عجیب و غریب را با تو سهیم نمی‌شود. همین کافی است که نادرستی آن‌ها را اثبات کند، اما تو آن را چنین ادراک نمی‌کنی.

چرا چنان فراوان مسرور نشوی وقتی به تو اطمینان داده می‌شود که همه‌ی شرارتی که می‌پنداشتی انجام داده‌ای، هرگز انجام نشده است. اطمینان داده می‌شود که همه‌ی گناهان تو هیچ هستند، که تو به همان اندازه‌ی زمان آفریده شدن خود خالص و قدسی هستی، و این که نور و سرور و صلح در تو ساکن است؟ انگاره‌ی تو از خودت نمی‌تواند در برابر ارادهٔ* خداوند* ایستادگی کند. تو فکر می‌کنی که این مرگ است، اما این زندگی است. تو می‌پنداری که تخریب می‌شوی، اما نجات می‌یابی.

آن خودی که تو ساخته‌ای، فرزند* خداوند* نیست. پس این خود اصلاً وجود ندارد. و هر چه که ظاهراً انجام می‌دهد و می‌پندارد، هیچ معنایی ندارد. نه بد است و نه خوب. غیرواقعی است، و هیچ چیزی بیش از این نیست. خود ساختگی با فرزند* خداوند* ستیز نمی‌کند. به آن آسیب نمی‌‌رساند، و به صلح وی حمله نمی‌کند. خود ساختگی، آفرینش را تغییر نداده، یا بی‌گناهی جاوید را به گناهکاری و عشق را به نفرت تنزل نداده است. این خود که تو ساخته‌ای، چه قدرتی می‌تواند داشته باشد، وقتی می‌خواهد با ارادهٔ* خداوند* ضدیت کند؟

بی‌گناهی تو توسط خداوند* تضمین می‌شود. این باید بارها و بارها تکرار شود، تا وقتی پذیرفته شود. این حقیقت است. بی‌گناهی تو توسط خداوند تضمین می‌شود. هیچ چیزی نمی‌تواند آن را لمس کند، یا آنچه را که خداوند ابدی خلق کرده است، تغییر دهد. آن خودی که تو ساخته‌ای، شرور و پر از گناه، معنایی ندارد. بی‌گناهی تو توسط خداوند تضمین می‌شود، و نور و سرور و صلح در تو ساکن است.

رستگاری فقط به پذیرش یک اندیشه نیازمند است؛-تو آنگونه هستی که خداوندت آفرید، نه آن چیزی که از خودت ساخته‌ای. هر قدر اعمال خود را شرورانه بدانی، تو آنگونه هستی که خداوندت آفرید. هر خطایی انجام داده باشی، حقیقت در مورد تو تغییر نمی‌کند. آفرینش ابدی و تغییرناپذیر است. بی‌گناهی تو توسط خداوند تضمین می‌شود. تو برای همیشه دقیقاً آنگونه هستی و خواهی بود که آفریده شدی. نور و سرور و صلح در تو ساکن است، زیرا خداوند آنها را آنجا نهاده است.

امروز در برنامه‌های تمرین طولانی‌تر، که بهتر است در پنج دقیقه‌ی نخست همه‌ی ساعات بیداری انجام شود، با بیان حقیقت در مورد آفرینش خود آغاز کن: نور و سرور* و صلح در من ساکن است. بی‌گناهی من توسط خداوند* تضمین می‌شود. سپس خود-انگاره‌های احمقانه خود را کنار بگذار، و باقی برنامه‌ی تمرین را به تلاش برای تجربه کردن آنچه خداوند* به تو داده است اختصاص بده، به جای آنچه برای خودت تصور کرده‌ای.

تو یا آن هستی که خداوند* آفرید، یا آن هستی که خودت ساخته‌ای. خویشتن* یگانه* حقیقت دارد؛ آن دیگری وجود ندارد. سعی کن یکپارچگی خویشتن* یگانهٔ* خود را تجربه کنی. سعی کن قداست* آن و عشقی را که این خویشتن* از آن آفریده شده، بپذیری. سعی کن مانع آن خویشتن* که خداوند* تو را آن آفرید نشوی، و شکوه آن را در پس خدایان دروغین ناچیز شرارت و گناهکاری که برای جایگزین کردنش ساختی، پنهان نسازی. بگذار آن* به خویشتن* خود برسد. تو اینجا هستی؛ این* تو هستی. و نور و سرور و صلح در تو ساکن است زیرا چنین است.

ممکن است نخواهی یا حتی قادر نباشی پنج دقیقه‌ی نخست هر ساعت را به تمرین اختصاص دهی. اما سعی کن هر وقت می‌توانی این کار را انجام دهی. حداقل به یاد داشته باش که هر ساعت این اندیشه‌ها را تکرار کنی: نور و سرور و صلح در من ساکن است. بی‌گناهی من توسط خداوند* تضمین می‌شود. سپس برای حداقل حدود یک دقیقه چشمانت را ببند و تشخیص بده که این جملات حقیقت را در مورد تو بیان می‌کنند.

هر زمان شرایط ظاهراً آشفته کننده‌ای پیش بیاید، سریعاً با تکرار مجدد همین اندیشه‌ها، وهم ترس را برطرف کن. اگر وسوسه شدی از کسی خشمگین شوی، در سکوت به او بگو: نور و سرور و صلح در تو ساکن است. بی‌گناهی تو توسط خداوند* تضمین می‌شود. امروز می‌توانی کار بزرگی برای رستگاری دنیا انجام دهی. امروز می‌توانی کار بزرگی برای نزدیک‌تر شدن به نقش خود در رستگاری که خداوند* برایت مقرر کرد انجام دهی. و امروز می‌توانی کار بزرگی برای ایجاد این یقین در ذهنت انجام دهی که ایده‌ی امروز به راستی حقیقت است.', 'https://acim-farsi.org/workbook/lesson/93', 'https://acim-farsi.org/audio/workbook/lesson/93.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (94, 'من آنگونه هستم که خداوند* مرا آفرید.', 'من آنگونه هستم که خداوند* مرا آفرید.
من تا ابد ‌فرزند* او* هستم.

من آنگونه هستم که خداوند* مرا آفرید.
من تا ابد فرزند* او* هستم .

و مطمئن شو که خطاب به هر کسی که ظاهراً تو را برانگیخته می‌کند با این کلمات پاسخ می‌دهی :
تو آنگونه هستی که خداوند* تو را آفرید.
تو تا ابد فرزند* او* هستی.', 'من آنگونه هستم که خداوند* مرا آفرید.

امروز ما کار با آن ایده را ادامه می‌دهیم که رستگاری کامل را عطا می‌کند؛ تک جمله‌ای که همه‌ی شکل‌های وسوسه را ناتوان می‌کند؛ آن اندیشه‌ای که نفس را ساکت می‌کند و کاملاً فرو می‌ریزد. تو آنگونه هستی که خداوند* تو را آفرید. توسط همین یک ایده صداهای این دنیا ساکت می‌شوند، تصاویر این دنیا ناپدید شده، و تمام افکاری که این دنیا به هر شکلی با خود دارد برای همیشه پاک می‌شوند. در اینجا به رستگاری می‌رسیم. در اینجا خرد باز می‌گردد.

نور حقیقی قدرت است، و قدرت بی‌گناهی است. اگر همانگونه که خداوند* تو را آفرید باقی بمانی، باید قوی باشی و نور باید درون تو باشد. او* که بیگناهی تو را قطعی می‌کند، باید تضمین قدرت و نور نیز باشد. تو آنگونه هستی که خداوند* تو را آفرید. تاریکی نمی‌تواند شکوه فرزند* خداوند* را پنهان کند. تو در نور می‌ایستی، مقتدر در بی‌گناهی که در آن آفریده شدی، و در طول ابدیت در آن باقی خواهی ماند.

امروز دوباره پنج دقیقه‌ی ابتدای هر ساعت بیداری خود را به تلاش برای احساس کردن حقیقت در تو اختصاص خواهیم داد. این زمان‌های جستجو را با این کلمات آغاز کن: من آنگونه هستم که خداوند* مرا آفرید. من تا ابد ‌فرزند* او* هستم. حال سعی کن تا به فرزند* خداوند* در خودت برسی. این همان خویشتن* است که هرگز گناه نکرد، و هرگز تصویری را نساخت تا جایگزین واقعیت شود. این همان خویشتن* است که هرگز منزل خود را نزد خداوند* ترک نکرد تا نامطمئن در این دنیا گام بردارد. این همان خویشتن* است که نه ترسی می‌شناسد، نه می‌تواند فقدان یا رنج مرگ را درک کند.

برای رسیدن به این هدف از تو هیچ انتظاری نمی‌رود جز کنار گذاشتن همه‌ی خدایان دروغین و خودانگاره‌ها؛ فرا رفتن از فهرست صفت‌ها، چه خوب و چه بد، که به خودت نسبت می‌دهی؛ و صبر کردن در انتظاری ساکت برای حقیقت. خود* خداوند* وعده داده است که حقیقت برای همه‌ی کسانی که خواهان آن باشند، آشکار خواهد شد. اینک تو در حال درخواست هستی. تو هرگز شکست نمی‌خوری زیرا او هرگز شکست نمی‌خورد.

اگر نتوانستی ملزومات تمرین در پنج دقیقه‌ی اول هر ساعت را فراهم کنی، حداقل هر ساعت به خودت یادآوری کن: من آنگونه هستم که خداوند* مرا آفرید. من تا ابد فرزند* او* هستم . امروز بارها به خودت بگو که تو آنگونه هستی که خداوند* تو را آفرید. و مطمئن شو که خطاب به هر کسی که ظاهراً تو را برانگیخته می‌کند با این کلمات پاسخ می‌دهی : تو آنگونه هستی که خداوند* تو را آفرید. تو تا ابد فرزند* او* هستی. امروز نهایت تلاش خود را به عمل بیاور که هر ساعت تمرین کنی. با هر بار انجام این تمرین گامی عظیم به سوی رهایی خود برمی‌داری، و هر تکرار گامی است در در آموختن سیستم فکری که این دوره بر آن بنا شده.', 'https://acim-farsi.org/workbook/lesson/94', 'https://acim-farsi.org/audio/workbook/lesson/94.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (95, 'من خویشتن* یگانه* هستم، یگانه با آفریدگارم*.', 'من خویشتن* یگانه هستم، یگانه با آفریدگارم*، یگانه با هر جنبه از آفرینش، و نامحدود در قدرت و صلح.

چشم‌هایت را ببند:
من خویشتن* یگانه هستم.

مطمئن شو که امروز با هر کسی که ملاقات می‌کنی مژدهٔ ایدهٔ روز را به او بدهی و به او بگویی:
تو با من یک خویشتن* یگانه هستی، یگانه با آفریدگارمان* در این خویشتن*.
من به تو افتخار می‌کنم به خاطر آنچه* که هستم، و آنچه* که او هست، او* که به هر دوی ما به عنوان یک وجود یگانه، عشق می‌ورزد.
من به تو افتخار می‌کنم به خاطر آنچه* که هستم، و آنچه* که او هست، او* که به هر دوی ما به عنوان یک وجود یگانه، عشق می‌ورزد.', 'من خویشتن* یگانه* هستم، یگانه با آفریدگارم*.

ایدهٔ امروز تو را به درستی آن‌چنان که خداوند* آفرید توصیف می‌کند. تو در درونت یگانه هستی، و یگانه با او*. یگانگی تو، وحدت همهٔ آفرینش است. وحدت کامل تو، تغییر در تو را ناممکن می‌سازد. تو این را نمی‌پذیری و نمی‌توانی تشخیص دهی که باید چنین باشد، فقط به این دلیل که باور داری پیشاپیش خودت را تغییر داده‌ای.

تو خود را یک تقلید مضحک در آفرینش خداوند* می‌بینی؛ ضعیف، پلید، زشت و گناهکار، مفلوک و به ستوه آمده از درد. چنین است نگرش تو به خودت؛ خودی تقسیم شده به بسیاری بخش‌های متعارض، جدا از خداوند*، که به طرزی نابسنده توسط سازندهٔ سرگردان و دمدمی مزاج خود گردآوری شده، و تو به او دعا می‌کنی. او دعاهای تو را نمی‌شنود، زیرا ناشنوا است. او یگانگی را در تو نمی‌بیند، زیرا کور است. او نمی‌فهمد که فرزند* خداوند* هستی، زیرا فاقد شعور است و هیچ چیزی را درک نمی‌کند.

ما امروز تلاش خواهیم کرد تا فقط از چیزی آگاه باشیم که می‌تواند بشنود و ببیند، و چیزی‌ که شعور کامل دارد. ما دوباره تمرین‌های خود را در راستای رسیدن تو به خویشتن* یگانهٔ خویش جهت می‌دهیم، که با افریدگارش* یگانه است. در شکیبایی و در امید، امروز دوباره خواهیم کوشید.

استفاده از پنج دقیقهٔ اول هر ساعت بیداری برای تمرین کردن ایدهٔ امروز، مزیت‌های ویژه در این مرحله از آموزش برای تو دارد. اگر به تمرین‌های طولانی بپردازی، در این مرحله دشوار است که به ذهنت اجازهٔ سرگردانی ندهی. حتماً تا کنون متوجه این موضوع شده‌ای. تو شدت فقدان انضباط ذهنی‌ات و نیاز خود به تربیت ذهن را دیده‌ای. ضروری است که به این مطلب آگاه باشی، زیرا این به راستی مانعی برای پیشرفت تو است.

برنامه‌های تمرین مکرر اما کوتاه‌تر در این زمان مزایای دیگری نیز برای تو دارد. علاوه بر شناختن مشکلاتت با حفظ کردن توجه، تو باید تا حال متوجه شده باشی که اگرچه قصد خود را مکرراً یادآوری می‌کنی، اما احتمال دارد آن را برای زمان‌های طولانی از یاد ببری. تو اغلب نمی‌توانی تمرین‌های کوتاه ایده را در طول روز به خاطر داشته باشی، و تا کنون عادت استفاده از ایده را به عنوان پاسخی خودکار در برابر وسوسه در خود شکل نداده‌ای.

پس ساختار در این زمان برای تو ضروری است، که طراحی می‌شود تا به یاد آوردن مکرر هدف و تلاش‌های منظم تو برای دستیابی به آن را در بر گیرد. نظم برحسب زمان، ضرورت ایده‌آل برای سودمندترین شکل از تمرین برای رستگاری نیست. اما برای آنان که انگیزشِ فاقد انسجام دارند و آنان که حالت دفاعی سخت در برابر آموختن را حفظ می‌کنند، سودمند است.

پس ما سعی خواهیم کرد به برنامه‌های تمرین پنج دقیقه در هر ساعت برای مدتی وفادار بمانیم، و تو را ترغیب می‌کنیم که تا حد ممکن تعداد کمی از تمرینات را حذف کنی. استفاده از پنج دقیقه‌ی اول هر ساعت خصوصاً مفید خواهد بود، زیرا این کار ساختار محکم‌تری را می‌سازد. اما لغزش‌های خود را از این برنامه بهانه نکن و هر زمان که توانستی دوباره بلافاصله به آن برگرد. همچنین ممکن است وسوسه شوی که روز را از دست رفته بدانی زیرا در انجام آنچه ضروری بوده توفیق نیافته‌ای. اما این را باید صرفاً آنگونه که هست بفهمی؛ امتناع از این که خطای تو اصلاح شود، و بی‌تمایلی برای تلاش مجدد.

روح‌القدس* آموزش خود را با خطاهای تو به تاخیر نمی‌اندازد. او* فقط با عدم تمایل تو به رها کردن این خطاها به عقب زده می‌شود. پس بیایید خصوصاً برای یک هفته یا بیشتر مصمم شویم اراده کنیم تا خودمان را برای لغزش‌هایمان در کوشش پیوسته، و شکست‌هایمان در پیروی از دستورالعمل‌های تمرین ایدهٔ روز ببخشیم. این صبوری ما در مقابل ضعف، ما را قادر خواهد کرد بر آن مسلط شویم، و به آن قدرت ندهیم تا آموختن ما را به تاخیر بیندازد. اگر به آن قدرت دهیم چنین کاری کند، آن را توانا محسوب خواهیم کرد، و توانایی را با ضعف اشتباه خواهیم گرفت.

اگر نتوانی الزامات این دوره را برآورده کنی، صرفاً یک خطا انجام داده‌ای. این نیاز به تصحیح دارد، و هیچ نیاز دیگری ندارد. اجازه دادن به یک خطا تا ادامه یابد یعنی ارتکاب خطاهای بیشتر، بر مبنای خطای اول و در تقویت آن. این فرآیند است که باید کنار گذاشته شود، زیرا این فقط شیوه‌ای دیگر است برای تو تا از اوهام در مقابل حقیقت دفاع کنی.

اجازه بده همه‌ی این خطاها با تشخیص ماهیت آنها رها شوند. آنها تلاش‌هایی هستند برای ناآگاه نگه داشتن تو از این که خویشتن* یگانه هستی، یگانه با آفریدگارت*، یگانه با هر جنبه از آفرینش، و نامحدود در قدرت و صلح. این حقیقت است و هیچ چیز دیگری حقیقت نیست. امروز ما دوباره این حقیقت را تصدیق خواهیم کرد، و سعی خواهیم کرد در تو به آن مکان دست یابیم که در آنجا هیچ تردیدی وجود ندارد که فقط این حقیقی است.

امروز برنامه‌های تمرین را با این دلگرمی آغاز کن، و آن را با تمام اطمینانی که می‌توانی به ذهنت ارائه کن: من خویشتن* یگانه هستم، یگانه با آفریدگارم*، یگانه با هر جنبه از آفرینش، و نامحدود در قدرت و صلح. سپس چشمانت‌را ببند و دوباره جملهٔ زیر را به خود بگو، آهسته و اندیشناک، در حالی که تلاش می‌کنی اجازه دهی معنای کلمات به درون ذهنت رسوخ کند و جایگزین ایده‌های باطل گردد: من خویشتن* یگانه هستم. این را چنین بار تکرار کرده و سپس تلاش کن معنایی را که کلمات در بر دارند، احساس کنی.

تو خویشتن* یگانه هستی، یگانه و ایمن در نور و شادی و صلح. تو فرزند* خداوند* هستی، خویشتن* یگانه، با یک آفریدگار* و یک هدف؛ آوردن آگاهی از این یگانگی به همهٔ ذهن‌ها، تا آفرینش حقیقی بتواند دربرگیری کل و وحدت خداوند* را گسترش دهد. تو خویشتن* یگانه هستی، کامل و شفایافته و تمام، با قدرت برداشتن حجاب تاریکی از این دنیا، و اجازه دادن به نور درونت تا ظهور کند تا به این دنیا حقیقت را در مورد خودت بیاموزد.

تو خویشتن قدسی یگانه هستی، در هماهنگی کامل با همه‌ی آنچه وجود دارد، و همه‌ی آنچه وجود خواهد داشت. تو خویشتن* یگانه هستی، فرزند* مقدس خداوند*، یگانه با برادرانت در آن خویشتن*؛ یگانه با پدرت* و ارادهٔ* او*. این خویشتن* یگانه را در خود احساس کن، و اجازه بده تا با تابش خود همهٔ اوهام و تردیدهای تو را برطرف سازد. این خویشتن* تو است، فرزند* خود* خداوند*، بی‌گناه همچون آفریدگارش*، با قدرت او* در درونت و عشق* او* برای همیشه از آن تو. تو خویشتن* یگانه هستی، و به تو عطا شده تا این خویشتن* را درونت احساس کنی، و تمامی اوهام خود را از این ذهن* یگانه که این خویشتن* است، از حقیقت مقدس درون، بیرون برانی.

امروز از یاد نبر. ما به کمک تو نیاز داریم، به نقش کوچک تو در آوردن شادمانی به همهٔ این دنیا. و ملکوت* به تو می‌نگرد، با اطمینان به این که امروز تلاش خواهی کرد. پس در یقین آن سهیم شو زیرا از آن تو است. هوشیار باش. امروز از یاد نبر. در طول روز هدف خود را فراموش نکن. ایدهٔ امروز را بارهای ممکن تکرار کن، با این درک که هر زمان چنین می‌کنی کسی آوای امید را می‌شنود، نجوای ظریف حقیقت را درون ذهنش، خش خش ملایم بال‌های صلح را.

تصدیق خود تو در مورد این که خویشتن* یگانه هستی، یگانه با پدرت*، فراخواندن همهٔ این دنیا است تا با تو یگانه باشند. مطمئن شو که امروز با هر کسی که ملاقات می‌کنی مژدهٔ ایدهٔ روز را به او بدهی و به او بگویی: تو با من یک خویشتن* یگانه هستی، یگانه با آفریدگارمان* در این خویشتن*. من به تو افتخار می‌کنم به خاطر آنچه* که هستم، و آنچه* که او هست، او* که به هر دوی ما به عنوان یک وجود یگانه، عشق می‌ورزد.', 'https://acim-farsi.org/workbook/lesson/95', 'https://acim-farsi.org/audio/workbook/lesson/95.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (96, 'رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد.', 'رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد. اندیشه‌های* او از آن من هستند تا از آن‌ها استفاده کنم.', 'رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد.

اگر چه تو یک خویشتن* یگانه هستی، اما خودت را دوگانه تجربه می‌کنی؛ هم خیر و هم شر، هم عاشق و هم متنفر، هم ذهن و هم بدن. این حس شکافته شدن به دو متضاد، احساس‌های تعارض حاد و مداوم را ایجاد می‌کند، و منجر به تلاش‌های خشونت‌آمیز برای آشتی دادن جنبه‌های متضاد این ادراک از خود می‌شود. تو چنین راه‌حل‌هایی را بسیار جسته‌ای، و هیچ‌یک از آن‌ها به نتیجه نرسیده است. تضادهایی که تو در خودت می‌بینی، هرگز با هم سازگار نخواهند شد. فقط یکی از آن‌ها وجود دارد.

اگر می‌خواهی نجات یابی، باید این امر مسلم را بپذیری که حقیقت و وهم نمی‌توانند آشتی کنند، فارغ از این که چگونه تلاش کنی، از چه وسیله‌ای استفاده کنی و مشکل را در کجا ببینی. تا زمانی که این را نپذیرفته باشی، برای فهرست بی‌پایانی از اهداف تلاش خواهی کرد که نمی‌توانی به آن‌ها برسی؛ فهرست بی‌معنایی از هزینه کردن زمان و تلاش، امیدواری و تردید، که هر یک به اندازه‌ی تلاش قبلی پوچ و توخالی هستند، و مطمئناً مانند تلاش بعدی شکست می‌خورند.

مشکلاتی را که هیچ معنایی ندارند، نمی‌توان در داخل چهارچوبی حل کرد که پیش آمده‌اند. دو خویشتن متعارض را نمی‌توان حل کرد، و خیر و شر در هیچ مکانی به هم نمی‌رسند. آن خود که تو ساخته‌ای هرگز نمی‌تواند خویشتن* تو باشد، و خویشتن* تو نیز هرگز نمی‌تواند دوپاره شود، و باز همان باشد که هست و همیشه باید باشد. ذهن و بدن نمی‌توانند هر دو وجود داشته باشند. تلاش نکن تا این دو را با هم آشتی دهی، زیرا هر یک واقعی بودن آن دیگری را انکار می‌کند. اگر جسم هستی، ذهنت از خودانگارهٔ تو حذف می‌شود، زیرا هیچ مکانی ندارد که بتواند در آن واقعاً بخشی از تو باشد. اگر روح هستی، آنگاه بدن باید برای واقعیت تو بی‌معنا باشد.

روح از ذهن به عنوان وسیله‌ای برای ظهور یافتن خویشتن* خود استفاده می‌کند. و آن ذهن که به روح خدمت می‌کند، در صلح و سرشار از سرور است. قدرت آن از روح سرچشمه می‌گیرد، و به شادمانی وظیفه‌ی خود را در اینجا ایفا می‌کند. اما ذهن همچنین می‌تواند خود را جدا شده از روح ببیند، و خود را درون بدنی ادراک کند که آن را با خودش اشتباه می‌گیرد. بدون وظیفه‌اش، ذهن هیچ صلحی ندارد، و شادمانی برای پندارهای او بیگانه است.

اما ذهنی که از روح جدا است نمی‌تواند بیندیشد. او خاستگاه* اقتدارش را انکار کرده است، و خود را درمانده، محدود و ضعیف می‌بیند. آنگاه منفصل از وظیفه‌اش، می‌پندارد که تنها و جدا است، زیر حملهٔ ارتش‌هایی که علیه او گرد می‌آیند و او در حفاظ شکنندهٔ بدن پنهان می‌شود. اینک او باید نامشابه را با مشابه آشتی دهد، زیرا می‌پندارد که قصد وجودی‌اش همین است.

دیگر وقت خود را برای این تلف نکن. چه کسی می‌تواند تعارض بی‌معنایی را که یک رؤیا عرضه می‌کند، حل کند؟ حل کردن در حوزه‌ی حقیقت چه معنایی می‌تواند داشته باشد؟ به چه هدفی می‌تواند خدمت کند؟ قصد آن چیست؟ رستگاری نمی‌تواند اوهام را به واقعیت تبدیل کند، و نمی‌تواند مسئله‌ای را حل کند که وجود ندارد. شاید امید داشته باشی که بتواند. اما آیا تو می‌خواهی که نقشهٔ خداوند* برای فرزند* دلبندش، او را به درد بیاورد؟ و در آزاد کردن او شکست بخورد؟

خویشتن* تو اندیشه‌هایش را حفظ می‌کند، و این اندیشه‌ها در ذهن تو و در ذهن* خداوند* باقی می‌مانند. روح‌القدس* از رستگاری در ذهنت مراقبت می‌کند، و راه صلح را به ذهن عرضه می‌کند. رستگاری آن اندیشه است که تو با خداوند* سهیم هستی، زیرا آوای* او آن را برای تو پذیرفت و به نام تو پاسخ داد که رستگاری به انجام رسیده است. چنین است که رستگاری درون اندیشه‌هایی* که خویشتن* تو عزیز می‌دارد و برای تو می‌پرورد، حفظ می‌شود.

امروز تلاش خواهیم کرد تا این اندیشه را بیابیم، اندیشه‌ای که حضور آن در ذهن تو توسط او* که از خویشتن* یگانهٔ تو با تو سخن می‌گوید، تضمین می‌شود. تمرینات پنج دقیقه‌ای ما در هر ساعت جستجویی خواهد بود برای او* در ذهن شما. رستگاری از این خویشتن* یگانه سرچشمه می‌گیرد، از طریق او* که پل بین ذهن تو و این خویشتن* است. صبورانه منتظر بمان، و اجازه بده که او* با تو از خویشتنت* سخن بگوید، و این که ذهنت چه می‌تواند انجام دهد تا به او* بازگردد و برای خدمت به اراده‌اش* آزاد باشد.

با گفتن این جملات آغاز کن: رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد. اندیشه‌های* او از آن من هستند تا از آن‌ها استفاده کنم. سپس اندیشه‌های* او* را جستجو کن، و اعلام کن که آن‌ها اندیشه‌های خود تو هستند. این‌ها اندیشه‌های واقعی تو هستند که انکارشان کرده‌ای، و اجازه داده‌ای که ذهنت در دنیایی از رؤیاها سرگردان شود، تا اوهام را به جای آن‌ها بیابد. اندیشه‌های تو همین‌جا هستند، تنها اندیشه‌هایی که داری. رستگاری در میان آن‌ها است؛ آن را همین‌جا بیاب.

اگر توفیق یابی، اندیشه‌هایی که برایت پیش می‌آیند به تو خواهند گفت که نجات یافته هستی، و ذهن تو وظیفه‌ای را که می‌خواست گُم کند، یافته است. خویشتن* تو از آن استقبال خواهد کرد و به آن صلح را خواهد داد. با بازیابی قدرت، ذهن دوباره از روح جریان خواهد یافت به سوی روح در همه‌ی چیزهایی که روح * به عنوان خودش* آفرید. ذهن تو همه چیز را متبرک خواهد کرد. سردرگمی محو می‌شود، تو نجات می‌یابی، زیرا خویشتن* خود را می‌یابی.

خویشتن* تو می‌داند که امروز شکست نخواهی خورد. شاید ذهن تو فقط برای مدت کوتاهی نامطمئن بماند. اجازه نده این تو را ناامید کند. آن سروری که خویشتن* تو تجربه می‌کند برایت حفظ خواهد شد، و در آگاهی کامل از آن تو خواهد ماند. هر زمان تو پنج دقیقه از ساعت را صرف یافتن او* می‌کنی که ذهنت را با خویشتن* تو پیوند می‌زند، گنجینه‌ای دیگر را به ذهن عرضه می‌کنی تا برای تو حفظ کند.

امروز هر زمان بتوانی به ذهن خشمگین خود بگویی که رستگاری از خویشتن* یگانهٔ تو سرچشمه می‌گیرد، گنجینه‌ای دیگر را در انبار در حال بزرگ شدن خود می‌گذاری. و همهٔ این گنجینه‌ها به تمامی آنان که خواهانش هستند و این موهبت را خواهند پذیرفت، داده می‌شود. پس بیندیش که امروز چقدر از طریق تو نثار می‌شود، تا به تو داده شود!', 'https://acim-farsi.org/workbook/lesson/96', 'https://acim-farsi.org/audio/workbook/lesson/96.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (97, 'من روح هستم.', 'من روح هستم، فرزند* مقدس خداوند*، آزاد از همهٔ محدودیت‌ها، ایمن و شفایافته و تمام، آزاد برای بخشایش، و آزاد برای نجات دادن دنیا.', 'من روح هستم.

ایده‌ی امروز به تو هویت خویشتن* یگانه‌ات را عطا می‌کند. این ایده هیچ هویت دو‌پاره‌ای را نمی‌پذیرد، و نیز تلاش نمی‌کند عوامل متضاد را در اتحاد به هم ببافد. صرفاً حقیقت را بیان می‌کند. امروز این حقیقت را به هر تعداد دفعاتی که می‌توانی تمرین کن، زیرا ذهن تو را از تعارض به سوی عرصه‌های ساکت صلح خواهد آورد. هیچ تکان ناشی از ترس نمی‌تواند وارد این عرصه‌ها شود، زیرا ذهن تو از دیوانگی بری می‌شود، و اوهامِ یک هویت دوپاره را رها می‌کند.

ما دوباره حقیقت را در مورد خویشتن* تو بیان می‌کنیم، فرزند* مقدس خداوند* که در تو حضور دارد، و ذهن او به عقلانیت بازگردانده شده. تو آن روح هستی که همهٔ عشق* و صلح و سرور پدرت*، عاشقانه به تو ارزانی شده است. تو آن روح هستی که خودش* را به کمال می‌رساند، و در رسالت او* به عنوان آفریدگار* سهیم می‌شود. آفریدگار* همیشه با ‌تو است، همانطور که تو با او* هستی.

امروز ما سعی می‌کنیم واقعیت را باز هم بیشتر به ذهنت نزدیک کنیم. هر زمان که تمرین می کنید، آگاهی دست‌کم اندکی به تو نزدیک‌تر می‌شود؛ گاه هزار سال یا بیشتر پیش می‌افتی. دقایقی که تو صرف می‌کنی چند برابر و چند برابر می‌شوند، زیرا معجزه از زمان استفاده می‌کند، اما زمان بر آن حکم نمی‌راند. رستگاری یک معجزه است، نخستین و فرجامین معجزه؛ نخستین معجزه‌ای که همان فرجامین معجزه است، زیرا تنها معجزه است.

تو آن روح هستی که در ذهنش معجزه سکونت دارد، معجزه‌ای که در آن همهٔ زمان ساکن می‌ماند؛ معجزه‌ای که در آن صرف کردن یک دقیقه برای استفاده از این ایده‌ها به زمانی تبدیل می‌شود که حدی ندارد و هیچ پایانی ندارد. پس این دقیقه‌ها را با ارادهٔ خود صرف کن، و به او* اعتماد کن که وعده داد بی‌زمانی را در کنار دقایق تو قرار می‌دهد. او* همهٔ قدرت خود* را به هر تلاش کوچکی که تو می‌کنی نثار خواهد کرد. امروز دقایقی را به او* بده که به آن‌ها نیاز دارد، تا به تو کمک کند همراه با او* بفهمی آن روح هستی که در او* سکونت داری، روحی که همهٔ چیزهای موجود را به آوای* او* فرامی‌خواند؛ بینایی او* را به هر کسی که درخواست کند عرضه می‌کند، خطا را با حقیقت ساده جایگزین می‌سازد.

روح‌القدس* خوشنود خواهد شد که در هر ساعت پنج دقیقه را از دستان تو دریافت کند، و این دقایق را به سراسر این دنیای دردناکی نثار کند که به نظر می‌رسد رنج و فلاکت بر آن حکم می‌راند. او* هیچ ذهن گشاده‌ای را که موهبت‌های شفابخش این دقایق را می‌پذیرد، نادیده نخواهد گرفت، و این هدایای شفابخش را هرجا که بداند از آن‌ها استقبال می‌شود، خواهد نهاد. و قدرت شفابخشی این هدایا هر زمان کسی به عنوان اندیشه‌هایش آن‌ها را قبول می‌کند و برای شفا مورد استفاده قرار می‌دهد، افزون می‌گردد.

اینچنین، هر هدیه به او* هزار و ده‌ها هزار برابر می‌شود. و وقتی به تو برمی‌گردد، توان آن بسیار فراتر از توان هدیهٔ کوچکی است که تو عرضه کرده‌ای، به همان اندازه که در برابر تابش خورشید، روشنایی ضعیف یک کرم شب‌تاب نامطمئن شده و محو می‌گردد. درخشش استوار این نور باقی می‌ماند و تو را به بیرون از تاریکی رهنمون می‌شود، و تو دوباره قادر نخواهی بود که مسیر را از یاد ببری.

این تمرین‌های شاد را با کلماتی آغاز کن که روح‌القدس* به تو می‌گوید، و اجازه بده این کلمات از طریق او* در سراسر دنیا طنین اندازد: من روح هستم، فرزند* مقدس خداوند*، آزاد از همهٔ محدودیت‌ها، ایمن و شفایافته و تمام، آزاد برای بخشایش، و آزاد برای نجات دادن دنیا. با ظهور از طریق تو، روح‌القدس* این موهبت را که از او* دریافت کرده‌ای خواهد پذیرفت، قدرت آن را افزون کرده و به تو باز خواهد گرداند.

امروز هر تمرین خود را شادمان به او* نثار کن. و او* با تو سخن خواهد گفت، به تو یادآوری می‌کند که روح هستی، یگانه با او* و با خداوند*، با برادرانت، و خویشتنت*. امروز هرگاه کلماتی را که او* به تو عطا می‌کند به زبان می‌آوری، به اطمینان‌بخشی او* گوش فرا ده و بگذار او* به ذهنت بگوید که این کلمات حقیقی هستند. از این کلمات در برابر وسوسه‌ها استفاده کن و از نتایج غم‌انگیز پذیرش این باور که تو چیز دیگری هستی نجات یابی. امروز روح‌القدس* صلح را نثار تو خواهد کرد. کلام او* را دریافت کن، و آن کلام را به او* پیشکش کن.', 'https://acim-farsi.org/workbook/lesson/97', 'https://acim-farsi.org/audio/workbook/lesson/97.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (98, 'من نقش خودم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.', 'من نقش خودم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.', 'من نقش خودم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.

امروز روزی است برای ارادت خاص. امروز ما انتخاب می‌کنیم که فقط در یک سو بایستیم. ما در کنار حقیقت می‌ایستیم و اوهام را رها می‌کنیم. ما در بین این دو مردد نخواهیم بود، بلکه جایگاهی قوی در کنار یگانه‌* را انتخاب می‌کنیم. امروز ما همانگونه که خداوند* در نقشه‌اش مقرر کرد، خودمان را به حقیقت و به رستگاری پیشکش می‌کنیم. ما جدل نخواهیم کرد که رستگاری چیز دیگری است. ما آن را در جایی که وجود ندارد جستجو نخواهیم کرد. آن را در شادمانی آنگونه که هست می‌پذیریم، و نقشی را که خداوند* برایمان تعیین کرده است قبول می‌کنیم.

چقدر شاد است مطمئن بودن! امروز ما همه‌ی تردیدهایمان را کنار می‌گذاریم، و در جایگاه خود با اطمینان از هدف می‌ایستیم، و با سپاس از این که تردید سپری شده و اطمینان فرارسیده است. ما یک هدف قدرتمند برای برآورده شدن داریم، و همهٔ چیزهایی که نیاز داریم تا با آن‌ها به هدف برسیم، به ما داده شده‌اند. حتی یک خطا در مسیر ما نمی‌ایستد. زیرا از خطاها مبرا شده‌ایم. همهٔ گناهان ما با تشخیص این که آن‌ها صرفاً اشتباهات ما بوده‌اند، پاک می‌شوند.

بی‌گناهان هیچ ترسی ندارند، زیرا در امنیت هستند و امن بودن خود را تشخیص می‌دهند. آنان تمایلی به جادو ندارند، و راه‌های گریز از تهدیدهای بدون واقعیت را نمی‌جویند. آنان در اطمینانی ساکن بر این امر باقی می‌مانند که آنچه را انجامش برای ایشان مقرر شده انجام می‌دهند. آنان به توانایی خود تردید نمی‌کنند زیرا می‌دانند که وظیفه‌ی ایشان در زمان و مکانی بی‌نقص تکمیل می‌شود. آنان در جایی ایستاده‌اند که ما امروز خواهیم ایستاد. تا بتوانیم در اطمینان آن‌ها سهیم شویم و اینچنین با پذیرشِ خودمان، آن را افزون کنیم.

بی‌گناهان با ما خواهند بود؛ همه‌ی آنان که در جایگاه امروز ما ایستاده‌اند، با خشنودی همه‌ی آنچه را که آموخته‌اند و همه‌ی دستاوردهای خود را به ما نثار می‌کنند. آنان که هنوز نامطمئن هستند نیز به ما خواهند پیوست، و با وام گرفتن از اطمینان ما، آن را باز قوی‌تر خواهند کرد. در حالی که آنان که هنوز متولد نشده‌اند، فراخوانی را که ما شنیده‌ایم خواهند شنید، و زمانی که آمده باشند که دوباره انتخاب کنند به آن پاسخ خواهند داد. ما امروز فقط برای خودمان انتخاب نمی‌کنیم.

آیا ارزش ندارد که در هر ساعت از وقت خود، پنج دقیقه را به توانایی پذیرفتن آن شادمانی اختصاص دهی که خداوند* به تو ارزانی داشته است؟ آیا ارزش ندارد که در هر ساعت پنج دقیقه را به شناختن وظیفه‌ی خاص خود در اینجا اختصاص دهی؟ آیا نثار پنج دقیقه در برابر پاداشی چنان عظیم که قابل اندازه‌گیری نیست، فقط درخواستی کوچک محسوب نمی‌شود؟ تو تاکنون دست‌کم هزار معاملهٔ زیان‌آور انجام داده‌ای.

این پیشنهاد، ضمانت رهایی کامل از هرگونه رنج را به تو عرضه می‌کند، و آن شادمانی را به تو عطا می‌کند که در این دنیا وجود ندارد. تو می‌توانی بخش کوچکی از زمان خود را برای صلح ذهن و اطمینان به هدف مبادله کنی، با وعده توفیق کامل. و از آنجا که زمان هیچ معنایی ندارد، از تو خواسته می‌شود که هیچ چیز را در قبال همه چیز بپردازی. این معامله‌ای است که تو هرگز در آن زیان نمی‌کنی. و آنچه به دست می‌آوری حقیقتا ًبی‌حد است!

امروز در هر ساعت خود فقط پنج دقیقه‌ی کوچک را به او* هدیه کن. او* به کلامی که تو در تمرین با ایدهٔ امروز استفاده می‌کنی، یقین ژرف و اطمینانی را که فاقد آن هستی عطا می‌کند. کلام او* به کلام تو می‌پیوندد و هر تکرار ایدهٔ امروز را به یک ارادت کامل تبدیل می‌کند، ارادتی با ایمان، بی‌نقص و قطعی همانند ارادت او به تو. اطمینان او* به تو نور را به همهٔ کلامی که می‌گویی عطا خواهد کرد، و تو به ورای صدای کلمات، به معنای واقعی کلام خواهی رفت. امروز با او* تمرین می‌کنی، در حالی که می‌گویی: من نقش خودم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.

در هر پنج دقیقه که با او* می‌گذرانی، او* کلام تو را خواهد پذیرفت و آن کلام را درخشنده با ایمان و اطمینانی چنان قوی و پایدار به تو باز خواهد گرداند که این دنیا را با امید و شادمانی نورانی می‌کند. حتی یک فرصت را برای دریافت شادمان موهبت‌های او* از دست نده، تا امروز بتوانی این موهبت‌ها را به این دنیا نثار کنی.

کلمات را به او* بده، و او* بقیه را انجام خواهد داد. او* به تو را قادر خواهد کرد تا وظیفهٔ خاص خود را بفهمی. او* طریق به سوی شادمانی را خواهد گشود، و صلح و اطمینان هدایای او* خواهند بود؛ پاسخ او* به کلمات تو. او* با همهٔ ایمان و سرور و اطمینان خود پاسخ خواهد داد که آنچه که تو می‌گویی حقیقی است. و آنگاه تو به او* اطمینان خواهی کرد که وظیفهٔ تو بر زمین و نیز در ملکوت* را می‌داند. او* در هر برنامه‌ی تمرین که با او* سهیم می‌شوی با تو خواهد بود، در حالی که هر لحظه از زمان را که نثارش می‌کنی با بی‌زمانی و صلح مبادله می‌کند.

در طول هر ساعت، اجازه بده که زمان تو در آماده شدن شادمان برای پنج دقیقهٔ بعدی سپری شود‌ که دوباره با او* خواهی گذراند. ایده‌ی امروز را زمانی که در انتظار زمان شادمان بعدی هستی، مدام تکرار کن. این ایده را بارهای زیاد تکرار کن، و هر زمان که تکرار می‌کنی از یاد نبر که در حال آماده کردن ذهن خود برای زمان شادمان بعدی هستی.

و وقتی یک ساعت سپری می‌شود و او* دوباره آنجا است تا زمان کوتاهی را با تو بگذراند، سپاسگزار باش و همهٔ وظایف زمینی را رها کن، همه‌ی پندارهای کوچک و ایده‌های محدود را، و دوباره زمانی شاد را با وی* بگذران. دوباره به او* بگو که نقش خود را می‌پذیری تا او* آن را به تو بسپارد و در انجامش به تو کمک کند، و او* به تو اطمینان خواهد داد که خواهان این انتخاب هستی، انتخابی که او* همراه با تو انجام داده و تو همراه با او*.', 'https://acim-farsi.org/workbook/lesson/98', 'https://acim-farsi.org/audio/workbook/lesson/98.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (99, 'رستگاری تنها وظیفهٔ من در اینجا است.', 'رستگاری تنها وظیفهٔ من در اینجا است.
رستگاری و بخشایش، یکی هستند.

و در فاصلهٔ میان زمان‌هایی که پنج دقیقه اختصاص می‌دهی، این را به خود یادآوری کن:
رستگاری تنها وظیفهٔ من در اینجا است،

اگر وسوسه شدی که تردید و ترس را باور کنی:
رستگاری تنها وظیفهٔ من در اینجا است. خداوند* همواره عشق* است، و این ارادهٔ* او* نیست.', 'رستگاری تنها وظیفهٔ من در اینجا است.

رستگاری و بخشایش، یکی هستند. هر دوی آن‌ها به این دلالت می‌کنند که اشتباهی رخ داده است؛ چیزی که باید از آن نجات یافت، از بابت آن بخشیده شد؛ چیزی نادرست که نیاز به تغییر اصلاحی دارد؛ چیزی جدا یا متفاوت از ارادهٔ* خداوند*. بنابراین هر دو اصطلاح به چیزی دلالت دارند که ناممکن است اما با این حال اتفاق افتاده، و منجر به حالتی از تعارض شده است که بین آنچه هست و آنچه هرگز نمی‌توانست باشد، دیده می‌شود.

در این حالت حقیقت و اوهام هر دو مساوی هستند، زیرا هر دو رخ داده‌اند. ناممکن به آن چیز تبدیل می‌شود که تو برایش نیاز به بخشایش داری و نیاز داری از آن رستگار شوی. در این حالت رستگاری به سرزمین مرزی بین حقیقت و وهم تبدیل می‌شود. رستگاری حقیقت را بازتاب می‌دهد، زیرا وسیله‌ای است که تو با آن می‌توانی از اوهام نجات یابی. اما این هنوز خود حقیقت نیست، زیرا چیزی را خنثی می‌کند که هرگز انجام نشده است.

چگونه در ذهنی که در آن هم زمین و هم بهشت* موجودیت دارند، اصلاً مکانی برای تلاقی این دو می‌تواند وجود داشته باشد؟ ذهنی که اوهام را می‌بیند، آن‌ها را واقعی می‌پندارد. موجودیت اوهام در این است که پندار هستند. اما آن‌ها واقعی نیستند، زیرا ذهنی که این پندارها را می‌اندیشد از خداوند* جدا است.

چه چیزی این ذهن و اندیشه‌های جدا شده را، با ذهن* و اندیشه‌ای* که برای همیشه یگانه* هستند پیوند می‌زند؟ کدام نقشه می‌تواند حقیقت را مصون نگه دارد، در عین حال نیازی را که اوهام پیش می‌آورند بشناسد، و وسیله‌ای را عطا کند که توسط آن بدون حمله و بدون هیچ گونه رنجی، اوهام خنثی شوند؟ این نقشه چه می‌تواند باشد جز یک اندیشهٔ* خداوند*، که توسط آن از آنچه هرگز انجام نشده است چشم‌پوشی می‌شود، و گناهانی که هرگز واقعی نبوده‌اند فراموش می‌شوند؟

روح‌القدس*، این نقشهٔ خداوند* را دقیقاً آنگونه حفظ می‌کند که از او* درون ذهن* خداوند* و در ذهن خود تو دریافت شده است. این نقشه فارغ از زمان است زیرا خاستگاهش* بی‌زمان است. اما این نقشه در زمان عمل می‌کند، به دلیل این باور تو که زمان واقعی است. روح‌القدس* بدون لغزش به آنچه تو می‌بینی می‌نگرد؛ به گناهکاری و رنج و مرگ، به غم و جدایی و به فقدان. با این حال او* می‌داند که یک چیز باید کماکان حقیقی باشد؛ خداوند* همواره عشق* است، و این ارادهٔ* او* نیست.

این اندیشه* است که اوهام را به پیشگاه حقیقت می‌آورد، و آن‌ها را به عنوان ظواهری می‌بیند که در پس آن‌ها آنچه بدون تغییر و قطعی است قرار دارد. این همان اندیشه* است که نجات می‌دهد و می‌بخشد، زیرا به آنچه توسط آن خاستگاه* که او می‌شناسد آفریده نشده باشد، هیچ ایمانی ندارد. این همان اندیشه‌* است که وظیفه‌اش نجات تو با اعطای این وظیفه به تو است تا آن را وظیفهٔ خود بدانی. رستگاری وظیفهٔ تو است، همراه با آن یگانه* که نقشه به او* عطا شد. اینک این نقشه به تو سپرده شده، همراه با او*. او یک پاسخ به همههٔ ظواهر دارد؛ فارغ از شکل آن‌ها، اندازهٔ آن‌ها، عمق آن‌ها یا هر صفتی که به نظر می‌رسد دارند: رستگاری تنها وظیفهٔ من در اینجا است، خداوند* همواره عشق* است، و این ارادهٔ* او* نیست.

تو که می‌خواهی معجزات را کار کنی، مطمئن شو که با ایدهٔ امروز خوب تمرین می‌کنی. سعی کن قدرت را در آنچه می‌گویی ادراک کنی، زیرا این‌ها کلماتی هستند که آزادی تو در آن‌ها قرار دارد. پدرت* به تو عشق می‌ورزد. همهٔ این دنیای رنج ارادهٔ* او* نیست. خودت را از بابت این اندیشه که خداوند* این را برایت خواسته است ببخش. سپس بگذار تا آن اندیشه‌* که او همهٔ خطاهای تو را با آن جایگزین می‌کند، به مکان‌های تاریک شدهٔ ذهنت وارد شود، ذهنی که پندارهایی را می‌اندیشید که هرگز ارادهٔ* او* نبوده است.

این بخش متعلق به خداوند* است، همانطور که بقیه به او* تعلق دارند. این بخش پندارهای منفرد خود را نمی‌اندیشد، و آن‌ها را با پنهان کردنشان از او* به واقعیت تبدیل نمی‌کند. بگذار نور وارد شود، و آنگاه هیچ مانعی در برابر آنچه او* برایت اراده کرد نخواهی یافت. رازهای خود را به روی نور مهربان او* بگشای، و ببین که این نور چگونه همواره درخشان در تو می‌تابد.

امروز اندیشهٔ* او* را تمرین کن و بگذار نور او* درون را جستجو کند، همهٔ نقاط تاریک را روشن کند، و از طریق آن‌ها بتابد تا آنان را به بقیه بپیوندد. این ارادهٔ* خداوند* است که ذهن تو با ذهن* او* یگانه شود. این ارادهٔ* خداوند* است که تنها یک فرزند* داشته باشد. این ارادهٔ* خداوند* است که یگانه فرزند* او* تو باشی. امروز به این چیزها در تمرین‌های خود بیندیش، و درسی را که امروز می‌آموزیم با این دستورالعمل در طریق حقیقت آغاز کن: رستگاری تنها وظیفهٔ من در اینجا است. رستگاری و بخشایش یکی هستند. سپس به او* رو کن که اینجا در وظیفهٔ تو سهیم است و بگذار او* به تو بیاموزد که به آموختن چه چیز نیاز داری تا بتوانی همهٔ ترس‌ها را رها کنی، و خویشتن* خود را به عنوان آن عشق* بشناسی که در تو هیچ‌گونه متضادی ندارد.

همه پندارهایی را که با حقیقت کمال، وحدت و صلح تو مقابله می‌کنند را ببخش. تو نمی‌توانی موهبت‌هایی را که پدرت* به تو عطا کرده است از دست بدهی. تو نمی‌خواهی خویشتنِ دیگری باشی. تو هیچ وظیفه‌ای نداری که متعلق به خداوند* نباشد. خودت را از بابت وظیفه‌ای که می‌پنداری ساخته‌ای، ببخش. بخشایش و رستگاری یکی هستند. آنچه را که ساخته‌ای ببخش و نجات می‌یابی.

برای امروز پیام ویژه‌ای وجود دارد که قدرت برطرف کردن همهٔ شکل‌های تردید و ترس را از ذهن تو برای همیشه در خود دارد. اگر وسوسه شدی این تردیدها و ترس‌ها را حقیقی بپنداری، به یاد بیاور که ظواهر نمی‌توانند در برابر حقیقتی که در کلمات قدرتمند زیر است ایستادگی کنند: رستگاری تنها وظیفهٔ من در اینجا است. خداوند* همواره عشق* است، و این ارادهٔ* او* نیست.

تنها وظیفهٔ تو به تو می‌گوید که یگانه هستی. این را در بین تمرین‌های پنج دقیقه‌ای خود در هر ساعت به خود یادآوری کن، دقایقی که با او* که نقشهٔ خداوند* را با تو سهیم است به اشتراک می‌گذاری. به خودت یادآور شو: رستگاری تنها وظیفهٔ من در اینجا است. اینچنین، بخشایش را در ذهن خود مستقر کن و اجازه بده همهٔ ترس‌ها با ملایمت کنار گذاشته شوند تا عشق بتواند مکان شایستهٔ خود را در تو بیابد و به تو نشان دهد که فرزند* خداوند* هستی.', 'https://acim-farsi.org/workbook/lesson/99', 'https://acim-farsi.org/audio/workbook/lesson/99.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (100, 'نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است.', 'نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است.', 'نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است.

درست همانطور که فرزند* خداوند* پدر* خویش را تکمیل می‌کند، نقش تو در نقشه‌ی پدرت* این نقشه را تکمیل می‌کند. رستگاری باید باور دیوانه‌وار به افکار جداگانه و بدن‌های جداگانه را معکوس کند، باوری که به زندگی‌های جداگانه و رفتن از مسیرهای جداگانهٔ آن‌ها می‌انجامد. وظیفه‌‌ای یگانه‌ که ذهن‌های جداگانه در آن سهیم هستند، آن‌ها را در یک هدف متحد می‌کند، زیرا هر یک از این ذهن‌ها به اندازهٔ مساوی برای همهٔ آن‌ها اساسی است.

ارادهٔ* خداوند* برای تو شادمانی کامل است. چرا باید انتخاب کنی که برخلاف اراده‌‌اش* حرکت کنی؟ آن نقش که خداوند* برای تو حفظ کرده تا در اجرا شدن نقشهٔ او* ایفا کنی، به تو عطا شده است تا بتوانی به آنچه او* اراده می‌کند بازگردی. این نقش، همان اندازه برای نقشهٔ او* اساسی است، که برای شادمانی تو. شادمانی تو باید کامل باشد تا اجازه دهی آنانی که تو را به سویشان می‌فرستد نقشهٔ او* را بفهمند. آنان وظیفهٔ خود را در چهرهٔ درخشان تو خواهند دید، و در خندهٔ شاد تو خواهند شنید که خداوند* آن‌ها را فرا می‌خواند.

تو مسلماً برای نقشهٔ خداوند* اساسی هستی. بدون سرور تو، سرور او ناکامل است. بدون لبخند تو، دنیا را نمی‌توان نجات داد. مادامی که تو غمگین باشی، نوری که خود* خداوند* به عنوان وسیله برای نجات دنیا مقرر کرد، تیره و کم‌نور است، و هیچ‌کس نمی‌خندد زیرا همهٔ خنده‌ها فقط می‌توانند خندهٔ تو را بازتاب دهند.

تو مسلماً برای نقشهٔ خداوند* اساسی هستی. درست همانگونه که نور تو هر نور تابنده در بهشت* را افزون می‌کند، سرور تو بر روی زمین همهٔ ذهن‌ها را فرا می‌خواند تا غم‌های خود را رها کنند، و نقش خود را کنار تو در نقشهٔ خداوند* ایفا کنند. پیام‌آوران خداوند* مسرور هستند، و سرور آنان غم و ناامیدی را شفا می‌دهد. آن‌ها گواه این هستند که خداوند* شادمانی کامل را برای همهٔ کسانی اراده می‌کند که موهبت‌های پدرشان* را از آن خود می‌دانند.

امروز ما به خود اجازه نخواهیم داد که غمگین باشیم. زیرا اگر چنین کنیم، در ایفای نقش خود که در نقشهٔ خداوند* و نیز در دورنمای ذهنی خود ما اساسی است، شکست می‌خوریم. غم نشانهٔ این است که تو در حال ایفای نقش دیگری هستی، به جای آن نقشی که خداوند* برای تو مقرر کرده است. این‌چنین تو نمی‌توانی به دنیا نشان دهی که آن شادی که او* برایت اراده کرده چقدر عظیم است. و بنابراین تشخیص نمی‌دهی که این شادی متعلق به خودت است.

امروز ما تلاش خواهیم کرد بفهمیم که شادمانی وظیفهٔ ما در اینجا است. اگر تو غمگین باشی، نقشت ایفا نمی‌شود، و در این صورت همهٔ دنیا همراه با تو از سرور محروم می‌شود. خداوند* از تو می‌خواهد که شاد باشی، تا دنیا بتواند ببیند که او* چه اندازه فرزند* خود* را دوست می‌دارد، و اراده می‌کند که هیچ غمی سرور وی را آشفته نسازد؛ هیچ ترسی او را برانگیخته نکند تا صلح خود را از دست بدهد. امروز تو پیام‌آور خداوند* هستی. تو شادمانی او را به همهٔ کسانی نثار می‌کنی که می‌بینی؛ صلح او* را به همهٔ کسانی عطا می‌کنی که به تو می‌نگرند و پیامش* را در چهرهٔ شاد تو می‌بینند.

ما امروز در طول برنامه‌های تمرین پنج دقیقه‌ای، خود را برای این آماده خواهیم کرد، با احساس کردن آن شادی که طبق ارادهٔ* پدرمان* و خود ما، در ما برانگیخته می‌شود. تمرین‌ها را با اندیشه‌ای آغاز کن که ایده‌ی امروز حاوی آن است. سپس به ذهن بیاور که نقش تو شاد بودن است. از تو یا هر کس دیگری که می‌خواهد در بین پیام‌آوران خداوند* جایی داشته باشد، فقط همین خواسته می‌شود. بیندیش که این چه معنایی دارد. تو مسلماً در این باور که از تو درخواست قربانی می‌شود اشتباه کرده‌ای. تو برطبق نقشهٔ خداوند* فقط دریافت می‌کنی، و هرگز از دست نمی‌دهی یا قربانی نمی‌کنی یا نمی‌میری.

حال بیایید تلاش کنیم آن شادی را بیابیم که ارادهٔ* خداوند* برای ما را به خودمان و به همهٔ این دنیا اثبات می‌کند. این وظیفهٔ تو است که آن را در اینجا بیابی، و همین اکنون آن را بیابی. تو برای این آمده‌ای. بگذار امروز همان روزی باشد که موفق می‌شوی! عمیقاً به درون خود نگاه کن، در حالی که شجاعانه از همهٔ افکار کوچک و اهداف احمقانه عبور می‌کنی تا صعود کرده و مسیحا* را در درونت ملاقات کنی.

او* آنجا خواهد بود. و تو می‌توانی اکنون به او* دست یابی. به چه چیزی ترجیح می‌دهی بنگری جز به او* که* منتظر است تا به او* بنگری؟ چه پندار ناچیزی قدرت این را دارد که تو را عقب نگه دارد؟ کدام هدف احمقانه می‌تواند تو را از توفیق بازدارد وقتی آن‌کس* که تو را می‌خواند خود* خداوند* است؟

او* آنجا خواهد بود. تو برای نقشهٔ او* اساسی هستی. امروز تو پیام‌آور او* هستی. و باید دریابی که او* می‌خواهد تو چه چیزی را بدهی. ایدهٔ امروز را در فاصلهٔ میان تمرین‌های پنج دقیقه‌ای هر ساعت، از یاد نبر. این خویشتن* تو است که امروز تو را می‌خواند. و تو به او* پاسخ می‌گویی، هر زمان به خود می‌گویی که در نقشهٔ خداوند* برای رستگاری این دنیا اساسی هستی.', 'https://acim-farsi.org/workbook/lesson/100', 'https://acim-farsi.org/audio/workbook/lesson/100.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (101, 'ارادهٔ* خداوند* برای من، شادمانی کامل است.', 'ارادهٔ* خداوند* برای من، شادمانی کامل است.
هیچ گناهی وجود ندارد؛ هیچ عقوبتی نیست.

امروز این را به یاد داشته باش و به دفعات ممکن به خودت بگو:
ارادهٔ* خداوند* برای من شادمانی کامل است.
این حقیقت است، زیرا هیچ گناهی وجود ندارد.', 'ارادهٔ* خداوند* برای من، شادمانی کامل است.

امروز با موضوع شادمانی ادامه خواهیم داد. این ایده‌ای کلیدی در فهم معنای رستگاری است. تو هنوز باور داری که رستگاری مستلزم رنج بردن و عقوبت «گناهانت» است. چنین نیست. اما تو ناگزیر هستی مادامی که باور داری گناه واقعیت است و فرزند* خداوند* می‌تواند گناه کند، بپنداری که چنین است.

اگر گناه واقعیت باشد، آنگاه مجازات عادلانه است و نمی‌توان از آن گریخت. در این صورت رستگاری را نمی‌توان جز با رنج بردن به دست آورد. اگر گناه واقعی باشد، آنگاه شادمانی باید وهم باشد، زیرا این هردو نمی‌توانند حقیقی باشند. گناهکاران فقط مرگ و درد را تصدیق می‌کنند، و خواهان این هستند. زیرا می‌دانند مرگ و درد انتظار ایشان را می‌کشند، و آن‌ها را خواهند جست و در جایی آن‌ها را پیدا خواهند کرد، زمانی، در شکلی که بدهی آن‌ها به خداوند* را صاف خواهند کرد. گناهکاران می‌خواهند در ترسشان از خداوند* بگریزند. و با این حال او* تعقیب خواهد کرد، و آنان نمی‌توانند بگریزند.

اگر گناه واقعی باشد، رستگاری باید درد باشد. درد بهای گناه است، و هرگز نمی‌توان از رنج بردن گریخت، اگر گناه واقعی باشد. باید از رستگاری ترسید، زیرا خواهد کشت، اما به آهستگی، که همه چیز را می‌گیرد پیش از آن که لطف خوشایند مرگ را به قربانیان عطا کند، قربانیانی که پیش از خشنود شدن رستگاری چیزی بیش از استخوان نیستند. قهر رستگاری بی‌حد، سنگدل، اما کاملاً عادلانه است.

چه کسی می‌خواهد چنین مجازات خشمگینانه‌ای را طلب کند؟ چه کسی می‌خواهد که از رستگاری نگریزد، و تلاش نکند به هر طریقی که می‌تواند آن آوا* را که رستگاری را به وی عرضه می‌کند، خاموش گرداند؟ چر او بخواهد که تلاش کند تا پیشکش آن آوا* را گوش دهد و بپذیرد؟ اگر گناه واقعی باشد، پیشکش آن مرگ است، و به شکل بی‌رحمانه تعیین می‌شود تا با آرزوهای پلیدی که خاستگاه گناه هستند، مطابق باشد. اگر گناه واقعی باشد، رستگاری به دشمن جانی تو تبدیل می‌شود، لعنتی از خداوند* بر تو که فرزند* او* را مصلوب کرده‌ای.

تو به تمرین‌های امروز نیاز داری. این تمرین‌ها به تو می‌آموزند که گناه واقعی نیست، و همهٔ آنچه باور داری نتیجهٔ گناه است، هرگز رخ نخواهد داد زیرا علتی ندارد. آمرزش* را با ذهنی باز بپذیر، ذهنی که دیگر این باور تردید‌آمیز را هرگز نمی‌پرورد که تو از فرزند* خداوند* یک شیطان ساخته‌ای. هیچ گناهی وجود ندارد. ما امروز با این اندیشه به دفعات ممکن تمرین خواهیم کرد، زیرا مبنای ایدهٔ امروز است.

ارادهٔ* خداوند* برای تو شادمانی کامل است زیرا گناه وجود ندارد، و رنج بردن بی‌علت است. سرور عادلانه است، و درد فقط نشانه‌ای است از این که تو خودت را درست نشناخته‌ای. از ارادهٔ* خداوند* نهراس. بلکه در اطمینان به آن رو کن تا تو را از همهٔ نتایجی که گناه در تخیلات تب‌دار خود ساخته است، آزاد کند. بگو: ارادهٔ* خداوند* برای من، شادمانی کامل است. هیچ گناهی وجود ندارد؛ هیچ عقوبتی نیست. باید اینگونه برنامهٔ تمرین خود را آغاز کنی، و سپس دوباره تلاش کنی آن سروری را که این افکار به ذهنت ارائه می‌کنند، دریافت کنی.

این پنج دقیقه را با شادی نثار کن، تا آن بار سنگینی را که با باور دیوانه‌وار واقعی بودن گناه به خود تحمیل کردی، از دوش برداری. امروز از دیوانگی بگریز. تو بر طریق آزادی هستی، و اینک ایدهٔ امروز به تو بال می‌دهد تا سرعت بگیری، و امید می‌دهد تا بازهم سریع‌تر به سوی هدف محتوم صلح حرکت کنی. هیچ گناهی وجود ندارد. امروز این را به یاد داشته باش و به دفعات ممکن به خودت بگو: ارادهٔ* خداوند* برای من شادمانی کامل است. این حقیقت است، زیرا هیچ گناهی وجود ندارد.', 'https://acim-farsi.org/workbook/lesson/101', 'https://acim-farsi.org/audio/workbook/lesson/101.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (102, 'من در ارادهٔ* خداوند* برای شادمانی‌ام سهیم هستم.', 'من در ارادهٔ* خداوند* برای شادمانی‌ام سهیم هستم، و اینک آن را به عنوان وظیفه‌ام می‌پذیرم.

در کنار این توقف‌های پنج دقیقه‌ای در هر ساعت، امروز بارها درنگ کن، تا به خودت بگویی که اینک شادمانی را به عنوان تنها وظیفهٔ خود پذیرفته‌ای.', 'من در ارادهٔ* خداوند* برای شادمانی‌ام سهیم هستم.

تو نمی‌خواهی رنج بکشی. ممکن است بپنداری که این می‌تواند سودی برای تو داشته باشد، و ممکن است هنوز اندکی باور داشته باشی آنچه را که می‌خواهی برایت خریداری می‌کند. اما مطمئناً این باور اکنون تکان خورده است، حداقل به اندازهٔ کافی برای این که اجازه دهد تو آن را زیر سؤال ببری، و به این شک کنی که واقعاً معنایی ندارد. آن باور هنوز نرفته است،اما دیگر فاقد آن ریشه‌هایی است که زمانی آن را به مکانهای تاریک و نهان شده و مخفی ذهنت محکم نگه می‌داشت.

امروز ما سعی می‌کنیم لنگرهای ضعیف این باور را باز هم بیشتر تضعیف کنیم، و تشخیص دهیم که رنج بی‌هدف است، بدون علت و بدون هیچ قدرتی برای رسیدن به چیزی. با رنج نمی‌توان به هیچ وجه چیزی را خرید. هیچ ثمری ندارد و وجود ندارد. و همه‌ی چیزهایی که فکر می‌کنی به تو می‌دهد وجود ندارند، مانند خودش. تو بردهٔ هیچ بوده‌ای. باشد تا امروز رها باشی تا به ارادهٔ* شادمان خداوند* بپیوندی.

ما در چند روز آینده به طور مداوم برنامه‌های تمرین خود را به انجام تمرین‌هایی اختصاص خواهیم داد که برای یاری به تو در دستیابی به آن شادی که ارادهٔ* خداوند* در تو قرار داده است، طراحی شده‌اند. اینجا خانه‌ی تو است، و امنیت تو در اینجا است. صلح تو اینجا است، و در اینجا هیچ ترسی وجود ندارد. رستگاری اینجا است. آسایش سرانجام اینجا است.

امروز برنامه‌های تمرینت را با این پذیرش ارادهٔ* خداوند* برای خود آغاز کن: من در ارادهٔ* خداوند* برای شادمانی‌ام سهیم هستم، و اینک آن را به عنوان وظیفه‌ام می‌پذیرم. سپس این وظیفه را در ذهن خود عمیقاً جستجو کن، زیرا در آنجا است، فقط در انتظار انتخاب تو. زمانی که بیاموزی این انتخاب تو است، و تو در ارادهٔ* خداوند* سهیم هستی، قطعاً آن را می‌یابی.

شاد باش، زیرا تنها وظیفهٔ تو در اینجا شادمانی است. تو نیاز نداری که کمتر از او* به فرزند* خداوند* عشق بورزی که عشق* او*، او را به اندازه خودش* عاشق آفرید. در کنار این توقف‌های پنج دقیقه‌ای در هر ساعت، امروز بارها درنگ کن، تا به خودت بگویی که اینک شادمانی را به عنوان تنها وظیفهٔ خود پذیرفته‌ای. و مطمئن باش که در انجام این کار به ارادهٔ* خداوند* می‌پیوندی.', 'https://acim-farsi.org/workbook/lesson/102', 'https://acim-farsi.org/audio/workbook/lesson/102.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (103, 'خداوند* که عشق* است، شادمانی نیز هست.', 'خداوند* که عشق* است، شادمانی نیز هست.
هراس از او*، هراسان بودن از شادمانی است.

در طول روز به دفعات بر این توقع تأکید کن، و همه‌ی ترس‌های خود را با این توکل رحیمانه و تماماً حقیقی، آرام کن:
خداوند* که عشق* است، شادمانی نیز هست.
و من امروز شادمانی را می‌جویم.
من قطعاً شکست نمی‌خورم، زیرا حقیقت را ‌می‌جویم.', 'خداوند* که عشق* است، شادمانی نیز هست.

شادمانی یک صفتِ عشق است. نمی‌تواند از آن جدا باشد. و نمی‌تواند جایی که عشق نیست تجربه شود. عشق هیچ حدودی ندارد، همه جا هست. و بنابراین شادمانی نیز همه جا هست. اما ذهن می‌تواند انکار کند که چنین است، با این باور که شکاف‌هایی در عشق هست که گناه می‌تواند به آن‌ها وارد شود، و رنج را به جای شادمانی بیاورد. این باورِ غریب می‌خواهد شادمانی را توسط بازتعریف کردن عشق به عنوان چیزی محدود، محدود کند، و تضاد را در چیزی وارد کند که هیچ ‌مرز و هیچ ضدی ندارد.

آنگاه ترس با عشق همراه می‌شود، و نتایج ترس به میراث ذهن‌هایی تبدیل می‌شوند که می‌پندارند آنچه ساخته‌اند، واقعی است. این تصویرهای ذهنی، بدون هیچ واقعیت حقیقی، حامل گواه برای ترس از خداوند* هستند، با از یاد بردن این که خداوند* که عشق* است باید سرور باشد. امروز دوباره سعی خواهیم کرد این خطای بنیادین را نزد حقیقت بیاوریم، و به خودمان بیاموزیم: خداوند* که عشق* است، شادمانی نیز هست. هراس از او*، هراسان بودن از شادمانی است. دوره‌های تمرین امروز خود را با این تداعی آغاز کن، که این باور نادرست را که خداوند* ترس است، تصحیح می‌کند. این تداعی همچنین تأکید می‌کند که شادمانی به تو تعلق دارد، به خاطر آنچه که او* هست.

امروز در همهٔ ساعت‌های بیداری اجازه بده که این تصحیح در ذهنت استقرار یابد. سپس از همهٔ آن شادمانی که جایگزینی حقیقت به جای ترس با خود می‌آورد استقبال کن و سرور، آن چیزی می‌شود که انتظار داری جایگزین رنج گردد. خداوند* که عشق* است، آن را به تو ارزانی می‌کند. در طول روز به دفعات بر این توقع تأکید کن، و همه‌ی ترس‌های خود را با این توکل رحیمانه و تماماً حقیقی، آرام کن: خداوند* که عشق* است، شادمانی نیز هست. و من امروز شادمانی را می‌جویم. من قطعاً شکست نمی‌خورم، زیرا حقیقت را ‌می‌جویم.', 'https://acim-farsi.org/workbook/lesson/103', 'https://acim-farsi.org/audio/workbook/lesson/103.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (104, 'من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است.', 'من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است.
من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است، و سرور و صلح میراث من هستند.

تا جایی که می‌توانی:
من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است.
موهبت‌های خداوندی از سرور و صلح همهٔ چیزی هستند که من می‌خواهم.', 'من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است.

ایدهٔ امروز با این اندیشه ادامه می‌یابد که سرور و صلح، فقط رؤیاهایی بی‌اساس نیستند. آن‌ها حق تو هستند، به دلیل آنچه که هستی. آن‌ها از خداوند* به سوی تو می‌آیند، او* که قطعاً در عطا کردن آنچه اراده می‌کند، توفیق می‌یابد. اما باید مکانی آماده شده باشد تا موهبت‌های او* دریافت شوند. ذهنی که به جای دریافت کردن موهبت‌های او*، خودش جایگزین‌هایی برای آن‌ها می‌سازد، از این هدایا با شادمانی استقبال نمی‌کند.

امروز ما می‌خواهیم همه‌ی هدایای بی‌معنی و خود ساخته را که بر محراب مقدس متعلق به موهبت‌های خداوند* قرار داده‌ایم، برداریم. موهبت‌های او* هدایایی هستند که در حوزه‌ی حقیقت متعلق به خود ما هستند. موهبت‌های او* هدایایی هستند که ما پیش از وجود زمان به ارث برده‌ایم، و همواره از آن ما خواهند بود وقتی زمان به ابدیت پیوسته باشد. موهبت‌های او* هدایایی هستند که اکنون درون ما وجود دارند، زیرا بی‌زمان هستند. و ما نیازی نداریم برای داشتن آن‌ها انتظار بکشیم. آن‌ها امروز متعلق به ما هستند.

بنابراین ما انتخاب می‌کنیم که اکنون آن‌ها را داشته باشیم، و بدانیم که با انتخاب آن‌ها به جای آنچه خودمان ساخته‌ایم، ما فقط ارادهٔ خود را با آنچه خداوند* اراده کرده است متحد می‌کنیم، و تشخیص می‌دهیم که آن دو با هم یگانه هستند. تمرینات طولانی‌تر امروز ما، که طی آن‌ها در هر ساعت به مدت پنج دقیقه به رستگاری خود حقیقت می‌بخشیم، باید با این جمله‌ها آغاز شوند: من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است، و سرور و صلح میراث من هستند. سپس تعارض‌های دنیا را کنار بگذار؛ تعارض‌هایی که هدایای دیگر و اهداف دیگر ساخته شده از اوهام را عرضه می‌کنند، از منظر اوهام دیده می‌شوند، و فقط در دنیای رؤیاها طلبیده می‌شوند.

ما همه‌ی این‌ها را کنار می‌گذاریم، و در عوض آن چیزی را می‌طلبیم که حقیقتاً متعلق به ما است، زمانی که می‌خواهیم تشخیص دهیم خداوند* به ما چه داده است. ما در پیشگاه محراب او* مکانی مقدس را در ذهن خود پاک می‌کنیم، جایی که در آن از موهبت‌های صلح و سرور او* استقبال می‌شود، و به آنجا می‌آییم تا آنچه را که او* به ما عطا کرده است، بیابیم. امروز ما با اطمینان می‌آییم، آگاه از این که آنچه در حقیقت به ما تعلق دارد، آن است که او* عطا می‌کند. و ما نمی‌خواهیم هیچ چیز دیگری را آرزو کنیم، زیرا هیچ چیز دیگری در حقیقت به ما تعلق ندارد.

پس امروز ما راه را برای او* پاک می‌کنیم، با این تشخیص ساده که ارادهٔ* او* پیشاپیش به عمل آمده است، و این که سرور و صلح به عنوان موهبت‌های ابدی او*، متعلق به ما هستند. در بین زمان‌هایی که آن موهبت‌ها را در جایگاهی می‌جوییم که خداوند* آن‌ها را نهاده است، ما به خودمان اجازه نخواهیم داد که نگاه کردن به آن‌ها را گم کنیم. جمله‌های زیر را برای یادآوری به دفعات ممکن در ذهن تکرار می‌کنیم: من فقط چیزی را می‌طلبم که در حقیقت متعلق به من است. موهبت‌های خداوندی از سرور و صلح همهٔ چیزی هستند که من می‌خواهم.', 'https://acim-farsi.org/workbook/lesson/104', 'https://acim-farsi.org/audio/workbook/lesson/104.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (105, 'صلح و سرور خداوند* از آن من هستند.', 'برادرم، من صلح و سرور را نثار تو می‌کنم، باشد تا بتوانم صلح و سرور خداوند* را از آن خود گردانم.', 'صلح و سرور خداوند* از آن من هستند.

صلح و سرور خداوند* از آن تو هستند. امروز ما آن‌ها را خواهیم پذیرفت، با دانستن این که آن‌ها از آن ما هستند. و سعی خواهیم کرد بفهمیم که این موهبت‌ها با دریافت شدن توسط ما افزون می‌شوند. آن‌ها مانند هدایایی نیستند که این دنیا می‌تواند عرضه کند، که در آن دهنده با دادن هدیه از دست می‌دهد؛ و گیرنده با از دست دادن او غنی‌تر می‌شود. چنین چیزهایی هدیه نیستند، بلکه دادوستدهایی هستند که با احساس گناه انجام می‌شوند. هدیه‌ای که حقیقتاً داده شود، موجب هیچ از دست دادنی نمی‌شود. ناممکن است که کسی بتواند چیزی را به دست بیاورد به این دلیل که دیگری چیزی را از دست می‌دهد. این نشان‌دهندهٔ یک محدودیت و یک نارسایی است.

در چنین صورتی هیچ هدیه‌ای داده نمی‌شود. چنین «هدایایی» فقط معامله‌ای هستند برای یک بازپرداخت ارزشمندتر؛ وامی که سود آن باید به طور کامل پرداخت شود؛ یک قرض موقتی، که قرار است گروی وامی باشد که باید بیش از آنچه توسط گیرندهٔ هدیه دریافت شده است، بازپرداخت شود. این تحریف غریب از معنای دادن، در تمام سطوح این دنیایی که تو می‌بینی، نافذ است. این تحریف، همهٔ معنا را از هدایایی که تو می‌دهی سلب می‌کند، و در آن هدایا که دریافت می‌کنی هیچ معنایی را باقی نمی‌گذارد.

یک هدف مهم آموختن در این دوره، وارونه کردن نگرش تو به دادن است، تا بتوانی دریافت کنی. زیرا دهندگی به خاستگاهی برای ترس تبدیل شده است، و آنگاه تو از تنها وسیله‌ای که توسط آن می‌توانی دریافت کنی، پرهیز می‌کنی. صلح و سرور خداوند* را بپذیر، و آنگاه تو شیوه‌ای متفاوت را برای نگاه کردن به یک هدیه خواهی آموخت. هدایای خداوند* زمانی که داده می‌شوند، هرگز کاهش نمی‌یابند. بلکه از این طریق افزایش می‌یابند.

همانطور که وقتی صلح و سرور ملکوت* را به عنوان هدایای خداوند* برای خود می‌پذیری، آن‌ها تقویت می‌شوند، سرور آفریدگارت* نیز آن زمان که تو سرور و صلح او* را متعلق به خود می‌دانی، افزایش می‌یابد. دهندگی حقیقی، آفریدن است. دهندگی حقیقی، نامحدود را به محدود نشده، ابدیت را به بی‌زمانی، و عشق را به خودش گسترش می‌دهد. دهندگی حقیقی همهٔ آنچه را که پیشاپیش کامل است، افزون می‌کند، نه برحسب کلمات سادهٔ افزون شدن، زیرا آن کلمات اشاره می‌کنند که قبلاً کاستی وجود داشته است. دهندگی حقیقی به آنچه نمی‌تواند در خود بماند اجازه می‌دهد تا هدفش را در نثار کردن همهٔ چیزی که دارد، برآورده کند، تا آن را همیشه برای خود محفوظ بدارد.

امروز صلح و سرور خداوند* را به عنوان صلح و سرور خود بپذیر. بگذار او* خودش* را کامل کند همانگونه که خود* کامل شدن را تعریف می‌کند. تو خواهی فهمید که آنچه او* را کامل می‌کند فرزند* او* را نیز کامل می‌کند. او* نمی‌تواند از طریق فقدان نثار کند. تو نیز از این پس نمی‌توانی. امروز هدایای سرور و صلح او* را دریافت کن، و او* از هدیه‌ای که به او می‌دهی، سپاسگزاری خواهد کرد.

امروز تمرین‌های ما کمی متفاوت آغاز خواهند شد. امروز را با اندیشیدن به آن برادرانی آغاز کن که تو آنان را از آن صلح و سروری که تحت قوانین عدالت خداوندی حق ایشان است، محروم کرده‌ای. در اینجا تو صلح و سرور را از خودت دریغ کرده‌ای. و در اینجا باید بازگردی و خواستار شوی که آن‌ها از آن تو شوند.

مدت کوتاهی در مورد «دشمنان» خود بیندیش، و به هریک زمانی که به ذهنت می‌رسند بگو: برادرم، من صلح و سرور را نثار تو می‌کنم، باشد تا بتوانم صلح و سرور خداوند* را از آن خود گردانم. اینچنین تو خود را آماده می‌کنی تا هدایای خداوند* را که به تو داده می‌شود، تشخیص دهی، و اجازه دهی ذهنت از همهٔ آنچه امروز می‌تواند مانع توفیق تو شود، آزاد گردد. اینک تو آماده پذیرش هدیه‌ی صلح و سرور هستی که خداوند به تو عطا کرده است. اینک تو آماده هستی تا سرور و صلحی را که از خودت دریغ کرده‌ای تجربه کنی. اینک تو می‌توانی بگویی، «صلح و سرور خداوند* از آن من است،» زیرا آنچه که می‌خواهی دریافت کنی را داده‌ای.

امروز قطعاً موفق می‌شوی، اگر ذهنت را آنگونه آماده کنی که ما توصیه می‌کنیم. زیرا در این صورت تو اجازه می‌دهی تا تمام موانع صلح و سرور برداشته شوند، و آنچه از آن تو است سرانجام می‌تواند به سوی تو بیاید. پس به خودت بگو، «صلح و سرور خداوند* از آن من است،» و برای زمان کوتاهی چشمانت را ببند، و اجازه بده آوای* او* به تو اطمینان دهد که این کلمات که می‌گویی، حقیقی هستند.

امروز هر زمان که می‌توانی پنج دقیقه از زمان خود را اینچنین با خداوند* سپری کن، اما نپندار که اگر نتوانی وقت بیشتری بگذاری، کمتر از این زمان برای تمرین بی‌ارزش است. دست‌کم هر ساعت به یاد داشته باش کلماتی را بگویی برای خواندن خداوند*، تا او* آنچه را که اراده می‌کند، به تو عطا کند، و اراده کند که تو دریافتش کنی. امروز مصمم باش که در آنچه او* اراده می‌کند، مداخله نکنی. و اگر زمانی به نظرت رسید که برادری تو را وسوسه می‌کند تا او را از دریافت هدیهٔ خداوند* محروم کنی، این را فقط فرصت دیگری ببین برای اجازه دادن به خودت تا هدیه خداوند* را از آن خود کنی. سپس سپاسگزارانه برادر* خود را متبرک کن و بگو: برادرم، من صلح و سرور را نثار تو می‌کنم، باشد تا بتوانم صلح و سرور خداوند* را از آن خود گردانم.', 'https://acim-farsi.org/workbook/lesson/105', 'https://acim-farsi.org/audio/workbook/lesson/105.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (106, 'بگذار من آرام باشم و به حقیقت گوش بسپارم.', 'من آرام خواهم بود و به حقیقت گوش فرا خواهم داد.
دادن و دریافت کردن چه معنایی دارد؟

و هر چند بار که ممکن است:
بگذار من ساکن بمانم و به حقیقت گوش فرادهم.
امروز من پیام‌آور خداوند* هستم، آوای من متعلق به او* است، تا آنچه را که دریافت می‌کنم نثار کنم.
امروز من پیام‌آور خداوند* هستم، آوای من متعلق به او* است، تا آنچه را که دریافت می‌کنم نثار کنم.', 'بگذار من آرام باشم و به حقیقت گوش بسپارم.

اگر آوای نفس را کنار بگذاری، هر چند که به نظر می‌رسد با صدای بلند تو را می‌خواند، اگر هدایای ناچیز آن را نپذیری، هدایایی که به تو هیچ چیزی را نمی‌دهند که واقعاً می‌خواهی؛ اگر با یک ذهن باز گوش فرادهی، ذهنی که خودش به تو نگفته است رستگاری چیست؛ آنگاه آوای* نیرومند حقیقت را خواهی شنید، در عین قدرتمندی ساکت، مقتدر در سکوت، و کاملاً مطمئن در پیام‌های خود*.

گوش فرابده و بشنو که پدرت* از طریق آوای* مقرر خود* با تو سخن می‌گوید، که غرش بی‌معناها را خاموش می‌سازد، و طریق صلح را به آنان که نمی‌توانند ببینند نشان می‌دهد. امروز آرام باش و به حقیقت گوش فرا بده. با آوای مردگان فریب نخور که به تو می‌گویند خاستگاه زندگی را یافته‌اند و به تو عرضه‌اش می‌کنند تا آن را باور کنی. به آن‌ها توجه نکن، بلکه به حقیقت گوش فرابده.

امروز هیچ نترس از این که توسط صداهای این دنیا محاصره شوی. به سَبُکی از ترغیب بی‌معنای این صداها عبور کن. آن‌ها را نشنو. امروز ساکن بمان و به حقیقت گوش فرابده. از همه‌ی چیزهایی که از او* سخن نمی‌گویند عبور کن، او* که* شادمانی تو را در دستانش* دارد، آغوش خود را با استقبال و در عشق برای تو گشاده است. امروز تنها او* را بشنو، و بیش از این منتظر نمان تا به او* برسی. امروز یگانه آوا* را بشنو.

امروز وعدهٔ کلام* خداوند* ایفا می‌شود. بشنو و ساکت بمان. او* می‌خواهد با تو سخن بگوید. او* با معجزاتی می‌آید هزاران بار شادمان‌تر و شگفت‌انگیزتر از آنچه تو هرگز در رؤیاهای خود دیده‌ای یا آرزو کرده‌ای. معجزات او* حقیقی هستند. این معجزات با پایان یافتن رؤیا محو نخواهند شد. برعکس، آن‌ها به رؤیا پایان می‌دهند؛ و برای همیشه ادامه می‌یابند، زیرا از سوی خداوند* برای فرزند* دلبندش آمده‌اند، که نام دیگرِ این فرزند* تو هستی. امروز خود را برای معجزات آماده کن. امروز اجازه بده میثاق دیرین پدرت* با تو و همهٔ برادرانت، به عمل درآید.

امروز او* را بشنو، و به کلامی* که حجابِ افکنده شده بر روی زمین را کنار می‌زند گوش فرابده، کلامی* که همه‌ی آنان را که در خوابند و نمی‌توانند ببینند، بیدار می‌کند. خداوند* از طریق تو آن‌ها را فرامی‌خواند. او برای سخن گفتن با آنان به آوای تو نیاز دارد، زیرا چه کسی می‌تواند به فرزند* خداوند* دست یابد جز پدرش*، که از طریق خویشتن* تو او* را می‌خواند؟ امروز خداوند* را بشنو، و آوای خود را به او عرضه کن تا با آن با همهٔ جماعتی که در انتظار شنیدن آن کلام* هستند که او* امروز خواهد گفت، سخن بگوید.

برای رستگاری آماده باش. رستگاری در اینجا است، و امروز به تو عطا خواهد شد. و تو وظیفهٔ خود را از آن یگانه‌* خواهی آموخت که به نام پدرت* آن وظیفه را برای تو انتخاب کرد. امروز گوش فرابده، و آن آوا* را خواهی شنید که از طریق تو در سراسر دنیا طنین می‌اندازد. آورندهٔ همهٔ معجزات نیاز دارد که تو ابتدا آن معجزات را دریافت کنی، و از این طریق به دهندهٔ شاد آنچه دریافت کرده‌ای، تبدیل شوی.

اینچنین رستگاری آغاز می‌شود و اینچنین پایان می‌یابد؛ وقتی همه چیز از آن تو است و همه چیز نثار می‌شود، همه چیز برای همیشه با تو باقی خواهد ماند. و درس آموخته شده است. امروز ما دهندگی را تمرین می‌کنیم، نه به آن شیوه که تو اکنون درک می‌کنی، بلکه آنگونه که هست. هر تمرین در هر ساعت باید با این درخواست برای روشن‌شدگی تو آغاز گردد: من آرام خواهم بود و به حقیقت گوش فرا خواهم داد. دادن و دریافت کردن چه معنایی دارد؟

بپرس و منتظر پاسخ بمان. پاسخ درخواست تو مدت‌ها در انتظار بوده تا توسط تو دریافت شود. این پاسخ، مأموریتی را آغاز خواهد کرد که تو برای آن آمده‌ای، و دنیا را از این پندار آزاد خواهد کرد که دهندگی راهی برای از دست دادن است. و اینچنین دنیا آماده می‌شود که بفهمد و دریافت کند.

امروز ساکن بمان و به حقیقت گوش فرابده. در هر پنج دقیقه‌ای که تو در گوش فرادادن می‌گذرانی، هزار ذهن رو به حقیقت باز می‌شود، و آنان آن کلام* را که تو می‌شنوی، خواهند شنید. و زمانی که یک ساعت سپری شود، تو دوباره هزار ذهن دیگر را آزاد می‌کنی که همراه با تو، متوقف می‌شوند و درخواست می‌کنند که حقیقت به آنها داده شود.

امروز کلام* خداوند* از طریق دریافت تو برای هدیه دادن آن محقق می‌شود، تا تو بتوانی با گوش فرادادن و آموختن آن از خداوند*، به دنیا بیاموزی که دهندگی چه معنایی دارد. امروز فراموش نکن که انتخاب خود را برای شنیدن و دریافت کردن کلام* با این یادآوری تقویت کنی، و آن را به دفعات ممکن در طول روز به خودت نثار کنی: بگذار من ساکن بمانم و به حقیقت گوش فرادهم. امروز من پیام‌آور خداوند* هستم، آوای من متعلق به او* است، تا آنچه را که دریافت می‌کنم نثار کنم.', 'https://acim-farsi.org/workbook/lesson/106', 'https://acim-farsi.org/audio/workbook/lesson/106.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (107, 'حقیقت همهٔ خطاها را در ذهن من تصحیح خواهد کرد.', 'حقیقت همهٔ خطاها را در ذهن من تصحیح خواهد کرد، و من در او* که خویشتن* من است، آرام خواهم گرفت.', 'حقیقت همهٔ خطاها را در ذهن من تصحیح خواهد کرد.

چه چیزی می‌تواند اوهام را تصحیح کند، جز حقیقت؟ و خطاها چه هستند جز اوهامی که به دلیل وهم بودن ناشناخته باقی می‌مانند؟ جایی که حقیقت وارد شود، خطاها ناپدید می‌شوند. آن‌ها صرفاً محو می‌شوند، حتی هیچ ردپایی باقی نمی‌گذارند تا توسط آن به یاد بیایند. خطاها محو می‌شوند زیرا بدون باور، حیاتی ندارند. و اینچنین آن‌ها ناپدید شده و هیچ می‌شوند، تا به هیچی که از آن آمده‌اند بازگردند. خطاها از خاک به خاک می‌آیند و می‌روند، زیرا فقط حقیقت است که می‌ماند.

آیا می‌توانی تصور کنی که حالت یک ذهن بدون اوهام چیست؟ چگونه احساس می‌کند؟ سعی کن آنگاه را به یاد بیاوری که زمانی بوده - شاید یک دقیقه و حتی کمتر - که در آن زمان هیچ چیزی پیش نیامده است تا صلح تو را مختل کند؛ زمانی که مطمئن بودی به تو عشق ورزیده می‌شود و در امنیت هستی. سپس سعی کن مجسم کنی شبیه چه می‌تواند‌ باشد که گستردگی آن لحظه را تا به پایان زمان و تا ابدیت داشته باشی. سپس اجازه بده این حس سکوتی که احساس کردی صد برابر شود، و بار دیگر صد برابر شود.

و اینک تو یک نشانه داری، نه چیزی بیش از صرفاً یک تقلید ضعیف از وضعیتی که ذهن تو زمانی که حقیقت آمده باشد در آن قرار خواهد گرفت. بدون اوهام هیچ ترس، هیچ تردید و هیچ حمله‌ای نمی‌تواند باشد. زمانی که حقیقت آمده باشد همهٔ درد پایان می‌یابد، زیرا دیگر جایی برای پندارهای گذرا و اعتقادات مرده وجود ندارد تا در ذهن تو باقی بمانند. حقیقت ذهنت را کاملاً اشغال می‌کند، و تو را از همهٔ باورها به چیزهای زودگذر آزاد می‌کند. این باورها هیچ جایی ندارند زیرا حقیقت آمده است، و آن‌ها هیچ جا نیستند. این باورها دیگر نمی‌توانند یافت شوند، زیرا اینک حقیقت در همه جا و برای همیشه هست.

زمانی که حقیقت آمده باشد، برای مدتی کوتاه نمی‌ماند، تا ناپدید شود یا به چیز دیگر تغییر یابد. صورتِ حقیقت تغییر و تبدیل نمی‌یابد، نمی‌آید و نمی‌رود و باز نمی‌رود و نمی‌آید. باقی می‌ماند دقیقاً همانگونه که همیشه بوده، تا برای هر نیازی به آن اتکا شود، و در همه‌ی دشواری‌های ظاهری و تردیدهایی که ظواهر این دنیا آبستن آن‌ها است ، به آن کاملاً اعتماد شود. این دشواری‌ها و تردیدها صرفاً ناپدید خواهند شد، زمانی که حقیقت خطاها را در ذهن تو تصحیح کند.

زمانی که حقیقت آمده باشد، در بال‌هایش از موهبت ثبات کامل حفاظت می‌کند، و عشق که در روبرو شدن با درد به خود نمی‌لرزد، بلکه به ورای آن می‌نگرد، استوار و مطمئن است. این موهبتِ شفا است، زیرا حقیقت نیاز به هیچ دفاعی ندارد، و بنابراین هیچ حمله‌ای ممکن نیست. اوهام را می‌‌توان به نزد حقیقت آورد تا تصحیح شوند. اما حقیقت بسیار فراتر از اوهام می‌ایستد، و نمی‌تواند به نزد آن‌ها آورده شود تا ایشان را به حقیقت تبدیل کند.

حقیقت نمی‌آید و نمی‌رود و تبدیل نمی‌شود و تغییر نمی‌کند، گاه در این ظاهر و گاه در یک ظاهر ِدیگر، گریزان از دسترسی و فراری از درک. حقیقت پنهان نمی‌شود. در نور روشن می‌ایستد، در دسترسی ِآشکار. ناممکن است که کسی بتواند خالصانه آن را جستجو کند و توفیق نیابد. امروز متعلق به حقیقت است. به حقیقت ارج آن را بده، و حقیقت به تو ارج تو را خواهد داد. تو بنا نبود رنج ببری و بمیری. پدرت* اراده می‌کند که رؤیاها محو شوند. بگذار حقیقت همهٔ آن‌ها را تصحیح کند.

ما آنچه را که نداریم طلب نمی‌کنیم. ما صرفاً آن چیزی را طلب می‌کنیم که به ما تعلق دارد، تا بتوانیم تشخیص دهیم که از آنِ ما است. امروز ما نشانهٔ شادمان اطمینان را که زاییدهٔ حقیقت است تمرین می‌کنیم. امروز به گام‌های لرزان و نااستوار وهم رو نمی‌کنیم. ما به همان اندازه به موفقیت مطمئن هستیم که اطمینان داریم زندگی می‌کنیم و آرزو می‌کنیم و نفس می‌کشیم و می‌اندیشیم. امروز ما تردید نمی‌کنیم که همراه با حقیقت گام برمی‌داریم، و فرض را بر این می‌گذاریم که حقیقت به همه‌ی تمرین‌هایی که امروز انجام می‌دهیم، وارد می‌شود.

تمرینات خود را با تقاضا کردن از او* آغاز کن که* در این طریق همراه تو می‌آید، با پذیرش این که او* در آگاهیِ تو حضور داشته باشد، همچنان که تو با او* می‌روی. تو از گوشت و خون و استخوان ساخته نشدی، بلکه دقیقاً توسط همان اندیشه‌* آفریده شدی که به او* نیز موهبت حیات را عطا کرد. او برادر* تو است، و چنان همانند به تو که پدرتان* می‌داند که شما* هردو* یکی هستید. این خویشتن* تو است که طلب می‌کنی با تو بیاید، و چگونه در جایی که تو هستی او* می‌تواند غایب باشد؟

حقیقت همهٔ خطاها را در ذهنت تصحیح خواهد کرد که به تو می‌گویند می‌توانی از او* جدا باشی. امروز با او* سخن می‌گویی، و عهد می‌بندی که اجازه دهی تا وظیفه‌اش* از طریق تو محقق شود. سهیم شدن در وظیفهٔ او*، سهیم شدن در سرور او* است. اطمینان او* به همراه تو است، زمانی که می‌گویی: حقیقت همهٔ خطاها را در ذهن من تصحیح خواهد کرد، و من در او* که خویشتن* من است، آرام خواهم گرفت. سپس به او* اجازه بده به نرمی تو را به سوی حقیقت هدایت کند، که تو را در بر خواهد گرفت و چنان صلح ژرف و تسکین‌بخشی به تو خواهد داد که با بی‌میلی به دنیای آشنای خود برخواهی گشت.

و با این حال خشنود خواهی بود که دوباره به این دنیا نگاه کنی. زیرا تو با خود وعدهٔ تغییراتی را خواهی آورد که حقیقتِ همراه با تو، به این دنیا حمل خواهد کرد. این تغییرات با هر پنج دقیقهٔ کوچکی که تو نثار می‌کنی افزون می‌شوند، و خطاهایی که این دنیا را فرا گرفته با اجازه دادن تو برای تصحیح آن‌ها در ذهنت، تصحیح خواهند شد.

امروز وظیفهٔ خود را فراموش نکن. هر زمان تو با اطمینان به خودت می‌گویی، «حقیقت همهٔ خطاها را در ذهن من تصحیح خواهد کرد،» از سوی همهٔ دنیا و از سوی خداوند* که می‌خواهد دنیا را آزاد کند سخن می‌گویی، همچنان که او* تو را آزاد می‌کند.', 'https://acim-farsi.org/workbook/lesson/107', 'https://acim-farsi.org/audio/workbook/lesson/107.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (108, 'دادن و دریافت کردن در حقیقت یکی هستند.', 'دادن و دریافت کردن در حقیقت یکی هستند. من آنچه را که اکنون می‌دهم، دریافت خواهم کرد.

به همه _____ را عرضه می‌کنم. برای نمونه: به همه آرامش را عرضه می‌کنم.
من صلحِ ذهن را به همگان نثار می‌کنم.
من لطافت را به همگان نثار می‌کنم.', 'دادن و دریافت کردن در حقیقت یکی هستند.

رؤیت به ایدهٔ امروز بستگی دارد. در این ایده نور هست، زیرا همهٔ آن چیزهایی را که ظاهراً متضاد هستند، با هم آشتی می‌دهد. و نور چیست جز این آشتی؟ که از صلح زاده می‌شود، آشتی کردنِ همهٔ تعارضات و افکار اشتباه تو و تبدیل آن‌ها به یک مفهوم که کاملاً حقیقی است. حتی همین یک مفهوم نیز محو خواهد شد، زیرا آن اندیشه‌* که در پس این مفهوم است ظهور خواهد کرد تا جایش را بگیرد. و آنگاه تو برای همیشه در صلح هستی، زیرا دیگر رؤیا به پایان می‌رسد.

نور حقیقی که رؤیت حقیقی را ممکن می‌سازد، آن نور نیست که چشمان بدن مشاهده می‌کنند. یک حالت ذهنی است، حالتی آنچنان یکپارچه که در آن دیگر به هیچ وجه نمی‌توان تاریکی را ادراک کرد. و در این صورت آنچه یکسان است، یگانه دیده می‌شود، در حالی که آنچه یکسان نیست نادیده می‌ماند، زیرا وجود ندارد.

همین نور است که اصلاً متضادها را نشان نمی‌دهد، و رؤیت که شفا یابد، قدرت شفا دادن را دارد. این نور است که آرامش ذهن تو را به ذهن‌های دیگر نثار می‌کند تا در آن سهیم شوند، و شادمان باشند از این که با تو و با خودشان یگانه هستند. این نور است که شفا می‌دهد زیرا ادراک واحدی را عرضه می‌کند، بر مبنای یک چارچوب مرجع واحد، که از آن یک معنای واحد حاصل می‌شود.

در اینجا هم دادن و هم دریافت کردن، جنبه‌های متفاوت اندیشهٔ* واحدی دیده می‌شوند که حقیقت آن به این که کدام‌ یک به عنوان رتبه اول دیده می‌شود بستگی ندارد، و نیز به این که کدام ظاهراً در رتبه‌ی دوم است. در اینجا فهمیده می‌شود که هر دو با هم رخ می‌دهند تا آن اندیشه‌*، کامل باقی بماند. و در این فهم بنیانِ آشتی همهٔ متضادها هست، زیرا آن‌ها از یک چارچوب مرجع واحد ادراک می‌شوند که این اندیشه‌* را یکپارچه می‌کند.

یک اندیشه که کاملاً یکپارچه شده باشد، کمک خواهد کرد تا تمامی اندیشه یکپارچه شود. این سخن مانند این است که گفته شود یک تصحیح برای تصحیح همه چیز کفایت می‌کند، یا بخشایش یک برادر به طور کامل، برای نثار رستگاری به همهٔ ذهن‌ها کافی است. زیرا این‌ها صرفاً برخی موارد خاص از یک قانون هستند که برای همهٔ انواع آموختن صادق است، اگر توسط آن یگانه‌* که* دانای حقیقت است هدایت شود.

آموختن این که دادن و دریافت کردن با هم یکی هستند فایده‌‌های خاصی دارد، زیرا امتحان کردن آن آسان است و حقیقی دیده می‌شود. و وقتی این مورد خاص اثبات شود همیشه عمل می‌کند، در همهٔ شرایطی که امتحان شود، اندیشهٔ موجود در پس آن می‌تواند به عرصه‌های دیگرِ تردید و دوگانه‌بینی تعمیم یابد. و از آنجا گسترش خواهد یافت، و نهایتاً به آن اندیشهٔ* یگانه* که بنیان همهٔ این یکپارچگی‌ها است، می‌رسد.

امروز ما با این مورد خاصِ دادن و دریافت کردن تمرین می‌کنیم. ما از این درس ساده آشکارا به این دلیل استفاده خواهیم کرد که نتایج آن را نمی‌توان نادیده گرفت. دادن همان دریافت کردن است. امروز ما تلاش خواهیم کرد تا صلح را به همگان نثار کنیم، و ببینیم که صلح با چه سرعتی به ما بر می‌گردد. نور، تسکین است، و در آن صلح است که رؤیت به ما عطا می‌شود، و می‌توانیم ببینیم.

پس تمرین‌های امروز را با راهنمایی روز آغاز کرده و می‌گوییم: دادن و دریافت کردن در حقیقت یکی هستند. من آنچه را که اکنون می‌دهم، دریافت خواهم کرد. سپس چشمانت را ببند، و برای پنج دقیقه به آن چیزی بیندیش که می‌خواهی به همگان نثار کنی، تا آن را از آن خود گردانی. تو ممکن است مثلاً بگویی: من آرامش را به همگان نثار می‌کنم. من صلحِ ذهن را به همگان نثار می‌کنم. من لطافت را به همگان نثار می‌کنم.

هر جمله را به آرامی بگو و سپس لختی درنگ کن، و در انتظار دریافت هدیه‌ای که داده‌ای بمان. و به تو در همان اندازه‌ای که آن را داده‌ای برخواهد گشت. متوجه خواهی شد که دقیقاً به همان میزان به تو برمی‌گردد، زیرا درخواست تو این است. ممکن است این نیز مفید باشد که به یک نفر بیندیشی تا هدایای خود را به او بدهی. او نماینده‌ی دیگران است، و از طریق او تو به همه نثار می‌کنید.

درس بسیار سادهٔ امروز ما، به تو بسیار خواهد آموخت. از این پس معلول و علت بسیار بهتر درک خواهند شد، و پیشرفت ما سرعت بسیار بیشتری خواهد یافت. تمرین‌های امروز را پیشرفت‌های سریعی در آموختن خود بدان، که هر زمان تو می‌گویی، «دادن و دریافت کردن در حقیقت یکی هستند،» سریع‌تر و قطعی‌تر می‌شود.', 'https://acim-farsi.org/workbook/lesson/108', 'https://acim-farsi.org/audio/workbook/lesson/108.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (109, 'من نزد خداوند* آرام می‌گیرم.', 'من نزد خداوند* آرام می‌گیرم.', 'من نزد خداوند* آرام می‌گیرم.

امروز ما تقاضای آسودگی می‌کنیم، و آرامشی که توسط ظواهر این دنیا آشفته نمی‌شود. ما درخواست صلح و سکون می‌کنیم، در میانهٔ همهٔ آشوبِ زاده شده از رؤیاهای متضاد. ما درخواست امنیت و شادمانی می‌کنیم، اگرچه به نظر ما چنین می‌رسد که خطر و غم را مشاهده می‌کنیم. و ما اندیشه‌ای را داریم که به درخواست ما پاسخ خواهد داد، با آنچه که می‌طلبیم.

«من نزد خداوند* آرام می‌گیرم.» این اندیشه برای تو آسایش و آرامش، صلح و سکون را به ارمغان خواهد آورد، و آن امنیت و آن شادمانی که می‌طلبی. «من نزد خداوند* آرام می‌گیرم.» این اندیشه قدرت بیدار کردن حقیقت خفته در تو را دارد، حقیقتی که رؤیت آن ورای ظواهر را می‌بیند و به آن حقیقت واحد نظر می‌کند که در همه کس و در همه چیز وجود دارد. در اینجا پایان رنج همهٔ دنیا حاضر است، و پایان رنج همهٔ آنان که تا حال آمده‌اند و از این پس خواهند آمد تا مدت زمانی را بمانند. در اینجا اندیشه‌ای حاضر است که در آن فرزند* خداوند* دوباره زاده می‌شود، تا خویشتنِ خویش را بشناسد.

«من نزد خداوند* آرام می‌گیرم.» کاملاً بدون هراس، این اندیشه تو را از درون توفان‌ها و کشمکش‌ها، به ورای محنت و درد، به ورای فقدان و مرگ عبور خواهد داد، و به سوی اطمینان خداوندی* هدایت خواهد کرد. هیچ رنجی نیست که این اندیشه نتواند شفا دهد. هیچ مشکلی نیست‌ که نتواند آن را حل کند. و هیچ ظاهری نمی‌تواند پیش چشمان تو که نزد خداوند* آرام گرفته‌ای، به حقیقت تبدیل نشود.

امروز روز صلح است. تو نزد خداوند* آرام می‌گیری، و در حالی که این دنیا توسط بادهای نفرت تکه و پاره می‌شود آسایش تو کاملاً دست نخورده باقی می‌ماند. آسایش تو آسایش حقیقت است. ظواهر نمی‌توانند مزاحم تو شوند. تو همگان را فرا می‌خوانی تا در آسایشت به تو بپیوندند، و آنان خواهند شنید و به سویت خواهند آمد زیرا تو نزد خداوند* آرام می‌گیری. آنان آوای دیگری جز آوای تو را نخواهند شنید زیرا تو آوای خود را به خداوند* تقدیم کردی، و اینک نزد او* آرام می‌گیری و اجازه می‌دهی تا او* از طریق تو سخن بگوید.

نزد او* تو هیچ نگرانی و هیچ دلواپسی، هیچ تحمیلی، هیچ اضطرابی، هیچ دردی، هیچ ترسی از آینده و هیچ پشیمانی از گذشته نداری. در بی‌زمانی آرام می‌گیری، در حالی که زمان بدون اثرش بر تو سپری می‌شود، زیرا آرامش تو هرگز نمی‌تواند به هیچ طریقی تغییری کند. امروز تو آرام می‌گیری. و با بستن چشمانت، به درون سکون فرو برو. اجازه بده تا این دوره‌های آرامش و استراحت به ذهن تو اطمینان دهند که همهٔ تخیلات شوریدهٔ آن صرفاً رؤیاهای تب‌آلودی بودند که سپری شده‌اند. بگذار آن آرام باشد و با سپاسگزاری شفایش را بپذیرد. دیگر رؤیای ترسناکی نخواهی داشت، اینک که نزد خداوند* می‌آسایی. امروز زمان صرف کن تا از رؤیاها کناره بگیری و به صلح برسی.

در هر ساعتی که تو آرام می‌گیری، ذهن خسته‌ای ناگهان شاد می‌شود، پرنده‌ای با بال‌های شکسته آغاز به خواندن می‌کند، جویباری که مدت‌ها خشک بوده دوباره جاری می‌شود. هر زمان تو آرام می‌گیری، دنیا دوباره متولد می‌شود، و هر ساعت به یاد بیاور که تو آمدی تا صلح خداوند* را به درون دنیا بیاوری، تا بتواند همراه با تو آرام گیرد.

با هر پنج دقیقه که امروز تو آرام می‌گیری، این دنیا به بیداری نزدیک‌تر می‌شود. و آن زمان که در آن آسودگی تنها حالِ موجود باشد، به همهٔ ذهن‌های فرسوده و خسته نزدیک‌تر می‌شود، ذهن‌هایی که اکنون فرسوده‌تر از آن هستند که به تنهایی راه خود را بپیمایند. و آنان خواهد شنید که پرنده آغاز به خواندن می‌کند، و خواهند دید که جویبار دوباره جاری می‌شود، با امیدی که از نو زاده می‌شود و توانی که به پاهای خسته بازمی‌گردد تا با گام‌هایی سبک در طریق گام بردارند، طریقی که ناگهان طی آن آسان‌تر به نظر می‌آید.

امروز تو در صلح خداوندی* آرام می‌گیری، و از این آسودگی برادران خود را فرا می‌خوانی تا همراه با تو، آنان نیز به آسودگی خود برسند. امروز تو به اعتماد خود وفادار خواهی ماند، هیچ‌کس را فراموش نخواهی کرد، همگان را به درون حلقهٔ بیکران صلح خود خواهی آورد، آن پناهگاه مقدس که تو در آن آرام می‌گیری. درهای معبد را بگشای و اجازه بده که آنان از دوردست‌های این دنیا و نیز از نزدیک بیایند؛ برادران تو از دوردست و نزدیک‌ترین دوستانت؛ از همهٔ آنان بخواه که به اینجا وارد شوند و همراه با تو آرام گیرند.

امروز تو در صلح خداوندی* آرام می‌گیری، ساکت و بی‌هراس. هر برادری می‌آید تا خود آرام بگیرد، و آن را به تو نثار کند. ما اینجا در کنار هم آرام می‌گیریم، زیرا اینچنین آسودگی ما کامل می‌شود، و آنچه که امروز می‌دهیم پیشاپیش دریافت کرده‌ایم. زمان از آنچه ما امروز نثار می‌کنیم، نگاهبانی نمی‌کند. ما این آسودگی را به آنان که هنوز زاده نشده‌اند و به آنان که این دنیا را ترک گفته‌اند نثار می‌کنیم، به هر اندیشهٔ* خداوند*، و به آن ذهن* که این اندیشه‌ها* در آن زاده شدند و نزد آن آرام می‌گیرند. و ما هر زمان که به خود می‌گوییم، «من نزد خداوند* آرام می‌گیرم»، مکان آسودگی ایشان را یادآور می‌شویم.', 'https://acim-farsi.org/workbook/lesson/109', 'https://acim-farsi.org/audio/workbook/lesson/109.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (110, 'من آنگونه هستم که خداوند* مرا آفرید.', 'من آنگونه هستم که خداوند* مرا آفرید. فرزند* او* نمی‌تواند از هیچ چیزی رنج ببرد. و من فرزند* او* هستم.

و هر چند بار که ممکن است:
من آنگونه هستم که خداوند* مرا آفرید.', 'من آنگونه هستم که خداوند* مرا آفرید.

ما ایدهٔ امروز را گاه به گاه تکرار خواهیم کرد. زیرا این یگانه اندیشه می‌تواند برای نجات تو و این دنیا کافی باشد، اگر باور کنی که حقیقت است. حقیقت این اندیشه بدین معنا است که تو هیچ تغییر واقعی را نه در خودت و نه در کائنات ایجاد نکرده‌ای، تا آنچه که خداوند* آفرید با ترس و شرارت، فلاکت و مرگ جایگزین شود. اگر تو آنگونه که خداوندت* آفرید باقی بمانی، ترس هیچ معنایی ندارد، شرارت واقعی نیست، و فلاکت و مرگ وجود ندارد.

بنابراین ایدهٔ امروز همه‌ی چیزی است که تو به آن نیاز داری تا بتوانی به تصحیحِ کامل اجازه دهی ذهنت را شفا دهد، و رؤیت کامل را به تو عطا کند، که همه‌ی خطاهایی را که هر ذهن در هر زمان یا مکان انجام داده است، شفا خواهد داد. این ایده برای شفای گذشته و آزاد کردن آینده کفایت می‌کند. این ایده کافی است تا به حال اجازه دهیم آنگونه که هست پذیرفته شود. این ایده کافی است تا اجازه دهیم زمان وسیله‌ای باشد برای تمام دنیا، تا بیاموزد که چگونه از زمان و از هر تغییری که به نظر می‌رسد زمان با گذر خود پدید می‌آورد، نجات یابد.

اگر تو آنگونه که خداوندت* آفرید باقی بمانی، ظواهر نمی‌توانند جانشین حقیقت شوند، سلامتی نمی‌تواند به بیماری تبدیل شود، و مرگ نمی‌تواند جایگزین زندگی گردد، یا ترس جایگزین عشق. همه‌ی این‌ها رخ نداده‌اند، اگر تو آنگونه که خداوندت* آفرید باقی بمانی. تو نیاز به هیچ اندیشه‌ای جز همین یک اندیشه نداری، تا اجازه دهی رستگاری این دنیا را روشن کند و آن را از گذشته آزاد گرداند.

در این یگانه اندیشه، همهٔ گذشته فرو می‌ریزد؛ حال نجات می‌یابد تا در سکون تا آینده‌ای بی‌زمان گسترش یابد. اگر تو آنگونه باشی که خداوندت* آفرید، آنگاه هیچ جدایی بین ذهن تو و ذهن او* وجود نداشته، هیچ جدایی بین ذهن تو و ذهن‌های دیگر، و فقط یکپارچگی درون خود تو بوده که وجود داشته است.

قدرت شفاگرِ ایدهٔ امروز بی‌حد است. این ایده زادگاه همهٔ معجزات است، بازگردانندهٔ عظیم حقیقت به آگاهیِ این دنیا. ایدهٔ امروز را سپاسگزارانه تمرین کن. این همان حقیقت است که می‌آید تا تو را آزاد گرداند. این همان حقیقت است که خداوند* به تو وعده داده است. این همان کلام* است که در آن همهٔ غم‌ها پایان می‌یابند.

برای تمرین‌های پنج دقیقه‌ای خود، با این جمله‌ها از متن آغاز کن: من آنگونه هستم که خداوند* مرا آفرید. فرزند* او* نمی‌تواند از هیچ چیزی رنج ببرد. و من فرزند* او* هستم.

سپس با تأکید بر این جمله در ذهن خود، سعی کن در ذهنت آن خویشتن* را که فرزند* خود* خداوند* است، کشف کنی.

در درون خود او* را جستجو کن که مسیحای* درون است، فرزند* خداوند* و برادر این دنیا است؛ آن منجی* که برای همیشه نجات یافته است، با قدرت نجات دادن هر کسی که او را لمس می‌کند، در عین حال به آهستگی، درخواست آن کلام* را می‌کند که به او می گوید برادر او* است.

تو آنگونه هستی که خداوندت* آفرید. امروز خویشتن* خود را گرامی بدار. امروز به خود اجازه نده تصویرهای دروغینی را که تراشیدی تا جایگزین ماهیتِ فرزند* خداوند* شوند، پرستش شوند. در عمق ذهنت، مسیحای* مقدس درون تو در انتظار است تا تو او را به عنوان ماهیت خود تصدیق کنی. و تو تا زمانی که او* را تصدیق نکرده و نمی‌شناسی، گم شده‌ای و خودت را نمی‌شناسی.

امروز او* را بطلب، و او* را بیاب. او منجی* تو از همهٔ خدایان دروغینی خواهد شد که ساخته‌ای. زیرا زمانی که او* را بیابی، خواهی فهمید که این خدایان دروغین تو چقدر بی‌ارزش هستند، و آن تصویرهایی که باور داشتی تو هستند چه اندازه باطل هستند. امروز ما پیشرفت عظیمی به سوی حقیقت خواهیم داشت، با رها کردن خدایان دروغین، و گشودن دستان و قلب‌ها و ذهن‌هایمان به خداوند*.

ما در تمام طول روز با قلب‌های سپاسگزار و اندیشه‌های عاشقانه برای همهٔ آنان که امروز ملاقاتشان می‌کنیم، خداوند* را به یاد خواهیم آورد. زیرا او* را بدین شیوه در یاد می‌آوریم. و چنین خواهیم گفت، تا فرزند* او*، خویشتن* مقدس ما، مسیحای* درون هر یک از ما بتواند به یاد آورده شود: من آنگونه هستم که خداوند* مرا آفرید. بیایید این حقیقت را بارهای ممکن تکرار کنیم. این همان کلام* خداوند* است که تو را آزاد می‌کند. این همان کلید است که دروازهٔ بهشت* را می‌گشاید، و به تو اجازه می‌دهد به صلح خداوندی* و جاودانگی او* وارد شوی.', 'https://acim-farsi.org/workbook/lesson/110', 'https://acim-farsi.org/audio/workbook/lesson/110.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (111, 'مرور (۹۱ و ۹۲)', 'سر هر ساعت:
معجزات در نور دیده می‌شوند.

سر هر نیم ساعت:
معجزات در نور دیده می‌شوند، و نور و قدرت یگانه هستند.', 'برای مرور صبح و شامگاه:

(۹۱) - معجزات در نور دیده می‌شوند. من نمی‌توانم در تاریکی ببینم. باشد تا نور قداست و حقیقت، ذهن مرا روشن گرداند، و باشد تا من معصومیت درونم را ببینم.

(۹۲) - معجزات در نور دیده می‌شوند، و نور و قدرت یگانه هستند. من از طریق قدرت، موهبتِ خداوند* برای من را می‌بینم. ضعف من آن تاریکی است که موهبت او* بر طرفش می‌کند، با عطا کردن قدرت خود* به من تا جایگزین آن گردد.

سر هر ساعت: معجزات در نور دیده می‌شوند. سر هر نیم ساعت: معجزات در نور دیده می‌شوند، و نور و قدرت یگانه هستند.', 'https://acim-farsi.org/workbook/lesson/111', 'https://acim-farsi.org/audio/workbook/lesson/111.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (112, 'مرور (۹۳ و ۹۴)', 'سر هر ساعت:
نور و سرور و صلح در من ساکن هستند.

سر هر نیم ساعت:
من آنگونه هستم که خداوند* مرا آفرید.', 'برای مرور صبح و عصر:

(۹۳) - نور و سرور و صلح در من ساکن هستند. من منزلگاه نور و سرور و صلح هستم. من از ورود آن‌ها به منزلگاهی که با خداوند* سهیم هستم. استقبال می‌کنم، زیرا من بخشی از او* هستم .

(۹۴) من آنگونه هستم که خداوند* مرا آفرید. من همیشه همان‌گونه خواهم ماند که بودم، آفریده شده توسط آن بی‌تغییر*، همچون خود* او*. و من با او* یگانه هستم، و او* با من.

سر هر ساعت: نور و سرور و صلح در من ساکن هستند. سر هر نیم ساعت: من آنگونه هستم که خداوند* مرا آفرید.', 'https://acim-farsi.org/workbook/lesson/112', 'https://acim-farsi.org/audio/workbook/lesson/112.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (113, 'مرور (۹۵ و ۹۶)', 'سر هر ساعت:
من یک خویشتن* هستم، یگانه با آفریدگارم*.

سر هر نیم ساعت:
رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد.', 'برای مرور صبح و شامگاه:

(۹۵) من یک خویشتن* هستم، یگانه با آفریدگارم*. آرامش و صلح کامل از آن من است، زیرا من یک خویشتن* یگانه هستم، کاملاً خالص، یگانه با تمامی آفرینش و با خداوند*.

(۹۶) رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد. از خویشتن* یگانه‌ام، که معرفت او* همچنان در ذهن من باقی است، می‌بینم که نقشهٔ کامل خداوند* برای رستگاری‌ام کاملاً به انجام می‌رسد.

سر هر ساعت: من یک خویشتن* هستم، یگانه با آفریدگارم*. سر هر نیم ساعت: رستگاری از خویشتن* یگانهٔ من سرچشمه می‌گیرد.', 'https://acim-farsi.org/workbook/lesson/113', 'https://acim-farsi.org/audio/workbook/lesson/113.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (114, 'مرور (۹۷ و ۹۸)', 'سر هر ساعت:
من روح هستم.

سر هر نیم ساعت:
من نقشم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.', 'برای مرور صبح و عصر:

(۹۷) من روح هستم. من فرزند* خداوند* هستم. هیچ بدنی نمی‌تواند روح مرا محصور کند، یا محدودیتی را به من تحمیل کند که خداوند* نیافریده است.

(۹۸) من نقشم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت. وظیفهٔ من چه می‌تواند باشد جز پذیرش کلام* خداوند*،‌ او* که مرا برای آنچه هستم و همواره خواهم بود آفریده است؟

سر هر ساعت: من روح هستم. سر هر نیم ساعت: من نقشم را در نقشهٔ خداوند* برای رستگاری خواهم پذیرفت.', 'https://acim-farsi.org/workbook/lesson/114', 'https://acim-farsi.org/audio/workbook/lesson/114.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (115, 'مرور (۹۹ و ۱۰۰)', 'سر هر ساعت:
رستگاری تنها وظیفهٔ من در اینجا است.

سر هر نیم ساعت:
نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است.', 'برای مرور صبح و عصر:

(۹۹) رستگاری تنها وظیفهٔ من در اینجا است. وظیفه‌ی من در اینجا بخشایش این دنیا است برای همه‌ی خطاهایی که انجام داده‌ام. زیرا اینچنین من همراه با همهٔ دنیا از این خطاها آزاد می‌شوم.

(۱۰۰) نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است. من در نقشهٔ خداوند* برای رستگاری دنیا، اساسی هستم. زیرا او* نقشه‌اش را به من عطا کرد تا بتوانم این دنیا را نجات دهم.

سر هر ساعت: رستگاری تنها وظیفهٔ من در اینجا است. سر هر نیم ساعت: نقش من در نقشهٔ خداوند* برای رستگاری، اساسی است.', 'https://acim-farsi.org/workbook/lesson/115', 'https://acim-farsi.org/audio/workbook/lesson/115.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (116, 'مرور (۱۰۱ و ۱۰۲)', 'سر هر ساعت:
ارادهٔ* خداوند* برای من شادمانی کامل است.

سر هر نیم ساعت:
من در ارادهٔ* خداوند* برای شادمانی خودم سهیم هستم.', 'برای مرور صبح و عصر:

(۱۰۱) ارادهٔ* خداوند* برای من شادمانیِ کامل است. ارادهٔ* خداوند* شادمانیِ کامل برای من است. و من تنها می‌توانم از این باور رنج ببرم که اراده‌ای جدا از ارادهٔ* او* وجود دارد.

(۱۰۲) من در ارادهٔ* خداوند* برای شادمانی خودم سهیم هستم. من که فرزند* او* هستم، در ارادهٔ* پدرم* برای خودم سهیم هستم. آنچه او* به من داده است همهٔ چیزی است که می‌خواهم. آنچه او* به من داده است همهٔ چیزی است که وجود دارد.

سر هر ساعت: ارادهٔ* خداوند* برای من شادمانی کامل است. سر هر نیم ساعت: من در ارادهٔ* خداوند* برای شادمانی خودم سهیم هستم.', 'https://acim-farsi.org/workbook/lesson/116', 'https://acim-farsi.org/audio/workbook/lesson/116.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (117, 'مرور (۱۰۳ و ۱۰۴)', 'سر هر ساعت:
خداوند* که عشق است، شادمانی نیز هست.

سر هر نیم ساعت:
من فقط چیزی را می‌طلبم که در حقیقت آز آن من است.', 'برای مرور صبح و عصر:

(۱۰۳) خداوند* که عشق است، شادمانی نیز هست. باشد تا من به یاد داشته باشم که عشق، شادمانی است، و هیچ چیز دیگری شادمانی نمی‌آورد. پس من انتخاب می‌کنم که هیچ جانشینی را به جای عشق نپرورم.

(۱۰۴) من فقط چیزی را می‌طلبم که در حقیقت از آن من است. عشق میراثِ من است، و شادمانی همراه با آن. این‌ها موهبت‌هایی هستند که پدرم* به من عطا کرد. من همهٔ آنچه را که در حقیقت از آن من است، می‌پذیرم.

سر هر ساعت: خداوند* که عشق است، شادمانی نیز هست. سر هر نیم ساعت: من فقط چیزی را می‌طلبم که در حقیقت آز آن من است.', 'https://acim-farsi.org/workbook/lesson/117', 'https://acim-farsi.org/audio/workbook/lesson/117.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (118, 'مرور (۱۰۵ و ۱۰۶)', 'سر هر ساعت:
صلح و سرور خداوند* از آن من هستند.

سر هر نیم ساعت:
باشد تا من آرام باشم و به حقیقت گوش فرا دهم.', 'برای مرور صبح و عصر:

(۱۰۵) صلح و سرور خداوند* از آن من هستند. امروز من صلح و سرور خداوند* را خواهم پذیرفت، و آن‌ها را با خوشحالی جایگزین همهٔ چیزهایی می‌کنم که به جای شادمانی و صلح ساخته‌ام.

(۱۰۶) باشد تا من آرام باشم و به حقیقت گوش فرا دهم. بگذار آوای ضعیف من آرام باشد، و بگذار من آوای* نیرومند خود* حقیقت* را بشنوم که به من اطمینان می‌دهد فرزند* کامل خداوند* هستم.

سر هر ساعت: صلح و سرور خداوند* از آن من هستند. سر هر نیم ساعت: باشد تا من آرام باشم و به حقیقت گوش فرا دهم.', 'https://acim-farsi.org/workbook/lesson/118', 'https://acim-farsi.org/audio/workbook/lesson/118.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (119, 'مرور (۱۰۷ و ۱۰۸)', 'سر هر ساعت:
حقیقت* همهٔ خطاها را در ذهن من تصحیح خواهد کرد.

سر هر نیم ساعت:
دادن و دریافت کردن در حقیقت یکی هستند.', 'برای مرور صبح و عصر:

(۱۰۷) حقیقت* همهٔ خطاها را در ذهن من تصحیح خواهد کرد. من در اشتباه هستم زمانی که می‌پندارم به طریقی ممکن است آسیب ببینم. من فرزند* خداوند* هستم، که خویشتن* او با امنیت در ذهن* خداوند* آرام می‌گیرد.

(۱۰۸) دادن و دریافت کردن در حقیقت یکی هستند. من امروز همهٔ چیزها را خواهم بخشید، تا بتوانم بیاموزم که چگونه حقیقتِ درونم را بپذیرم، و به شناختن بی‌گناهی خودم نائل گردم.

سر هر ساعت: حقیقت* همهٔ خطاها را در ذهن من تصحیح خواهد کرد. سر هر نیم ساعت: دادن و دریافت کردن در حقیقت یکی هستند.', 'https://acim-farsi.org/workbook/lesson/119', 'https://acim-farsi.org/audio/workbook/lesson/119.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (120, 'مرور (۱۰۹ و ۱۱۰)', 'سر هر ساعت:
من نزد خداوند آرام می‌گیرم.

سر هر نیم ساعت:
من آنگونه هستم که خداوند* مرا آفرید.', 'برای مرور صبح و عصر:

(۱۰۹) من نزد خداوند* آرام می‌گیرم. امروز من نزد خداوند* آرام می‌گیرم، و اجازه می‌دهم که او* در من و از طریق من عمل کند، در حالی که من نزد او*، در سکوت و در اطمینان کامل آرام می‌گیرم.

(۱۱۰) من آنگونه هستم که خداوند* مرا آفرید. من فرزند* خداوند* هستم. امروز من همهٔ اوهام بیمارگونهٔ خود را کنار می‌گذارم، و اجازه می‌دهم پدرم* به من بگوید که واقعاً چه کسی* هستم.

سر هر ساعت: من نزد خداوند آرام می‌گیرم. سر هر نیم ساعت: من آنگونه هستم که خداوند* مرا آفرید.', 'https://acim-farsi.org/workbook/lesson/120', 'https://acim-farsi.org/audio/workbook/lesson/120.mp3', 'interval', '[{"kind":"interval","minutes":30}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (121, 'بخشایش کلید شادمانی است.', 'بخشایش کلید شادمانی است. من از این رؤیا بیدار خواهم شد که میرا، خطاکار و سرشار از گناه هستم، و خواهم دانست که فرزند* کامل خداوند* هستم.', 'بخشایش کلید شادمانی است.

در اینجا پاسخ جستجوی تو برای صلح وجود دارد. در اینجا کلید معنا در دنیایی ظاهراً بی‌معنا وجود دارد. در اینجا طریق به سوی امنیت در خطرهای ظاهری حضور دارد، خطرهایی که به نظر می‌رسد در هر پیچ تو را تهدید می‌کنند، خطرهایی که همه‌ی امیدهای تو را به این که زمانی بتوانی سکوت و صلح را بیابی، دچار بی‌اطمینانی می‌کنند. در اینجا همهٔ پرسش‌ها پاسخ می‌گیرند؛ در اینجا سرانجام همهٔ بی‌اطمینانی به پایان می‌رسد.

ذهنی که نمی‌بخشد سرشار از ترس است، و هیچ جایی را به عشق نمی‌دهد تا خودش باشد؛ هیچ جایی را به عشق نمی‌دهد تا بتواند بال‌هایش را در صلح بگشاید و بر فراز آشفتگی این دنیا اوج بگیرد. ذهنی که نمی‌بخشد غمگین است، بدون امید استراحت و رهایی از درد. این ذهن رنج می‌برد و در فلاکت ساکن است، جستجوگر در تاریکی، بدون این که ببیند، اما مطمئن به این که در آنجا خطر کمین کرده است.

ذهنی که نمی‌بخشد با تردیدها از هم دریده شده، سردرگم در مورد خودش و همهٔ آنچه می‌بیند؛ هراسان و خشمگین، ضعیف و پرهیاهو، هراسان از پیش رفتن، هراسان از ماندن، هراسان از بیدار شدن یا به خواب رفتن، هراسان از هر صدا، اما بیشتر هراسان از سکوت؛ وحشت‌زده از تاریکی، اما بیشتر وحشت‌زده از آمدن نور است. ذهنی که نمی‌بخشد چه چیز را می‌تواند ادراک کند جز عذاب‌های دوزخی خود؟ چه چیز را می‌تواند ببیند جز اثبات این که همهٔ گناهانش واقعی هستند؟

ذهنی که نمی‌بخشد اشتباهات را نمی‌بیند، فقط گناهان را می‌بیند. این ذهن به دنیا با چشمان نابینا نظر می‌کند، و زمانی که فرافکنی‌های خود را می‌بیند که قیام می‌کنند تا به مضحکهٔ فلاکت‌بار زندگی او حمله کنند، فریاد می‌کشد. این ذهن زندگی کردن را می‌خواهد، اما آرزو می‌کند که ای‌کاش مرده بود. این ذهن بخشایش را می‌خواهد، اما هیچ امیدی نمی‌بیند. این ذهن گریز را می‌خواهد، اما راه گریزی نمی‌یابد زیرا گناهکاران را همه جا می‌بیند.

ذهنی که نمی‌بخشد ناامید است، بدون امید به آینده‌ای که چیزی جز ناامیدی بیشتر به آن نمی‌تواند عرضه کند. اما این ذهن، قضاوتش را در مورد دنیا تغییرناپذیر می‌پندارد، و نمی‌بیند که خودش را به این ناامیدی محکوم کرده است. این ذهن می‌پندارد که نمی‌تواند تغییر کند، زیرا آنچه می‌بیند، گواهی می‌دهد که قضاوتش صحیح است. این ذهن نمی‌پرسد، زیرا می‌پندارد که می‌داند. هیچ‌چیز را مورد پرسش قرار نمی‌دهد، با این یقین که حق با او است.

بخشایش اکتسابی است. بخشایش برای ذهن ذاتی نیست، زیرا ذهن نمی‌تواند گناه کند. همانطور که گناهکاری یک عقیده است که تو به خودت آموزش داده‌ای، بخشایش را نیز باید بیاموزی، اما از آموزگاری* جز خودت، آموزگاری* که خویشتن* دیگر را در تو به ظهور می‌رساند. از طریق او* تو می‌آموزی که چگونه آن خود را که می‌پنداری ساخته‌ای، ببخشی، و اجازه دهی تا ناپدید شود. اینچنین تو ذهن خود را یگانه به او* باز می‌گردانی، به او/ که خویشتن* تو است، او* که هرگز نمی‌تواند گناه کند.

هر ذهن نابخشنده به تو فرصتی هدیه می‌دهد تا به ذهن خودت بیاموزی که چگونه‌ خودش را ببخشد. هر کدام از آن‌ها منتظر رهایی از دوزخ از طریق تو است، و ملتمسانه به تو رو می‌کند برای ملکوت* در اینجا و اکنون. ذهن نابخشنده امیدی ندارد، اما تو امید آن می‌شوی. و به عنوان امید آن، تو امید خودت می‌شوی. ذهن نابخشنده باید از طریق بخشایش تو بیاموزد که از دوزخ نجات یافته است. همانگونه که رستگاری را آموزش می‌دهی، آن را می‌آموزی. اما همهٔ آموزش دادن و آموختن تو از تو نخواهد بود، بلکه از آن آموزگار* است که به تو عطا شد تا طریق را به تو نشان دهد.

امروز ما آموختن بخشایش را تمرین می‌کنیم. اگر مصمم باشی، امروز می‌توانی دریافت کلید شادمانی را بیاموزی، و از آن به سود خودت استفاده کنی. ما امروز ده دقیقه را در صبحگاه و ده دقیقه دیگر را در شامگاه به تمرین اختصاص خواهیم داد، به آموختن این که چگونه بخشایش را عرضه کنیم، و نیز چگونه بخشایش را دریافت کنیم.

ذهنی که نمی‌بخشد باور نمی‌کند که دادن و دریافت کردن با هم یکی هستند. اما ما امروز سعی خواهیم کرد بیاموزیم که این دو با هم یکی هستند، از طریق تمرین بخشایش در مورد کسی که تو به او به عنوان یک دشمن می‌اندیشی، و کسی که تو او را یک دوست می‌دانی. و همچنان که تو می‌آموزی هر دوی آنان را با هم یکی ببینی، ما این درس را به خود تو گسترش خواهیم داد، و خواهیم دید که نجات آنان، نجات تو را نیز شامل می‌شود.

تمرین‌های طولانی‌تر را با اندیشیدن به کسی آغاز کن که دوستش نداری، کسی که به نظر می‌رسد تو را آشفته می‌کند، یا اگر مجبور باشی با او ملاقات کنی موجب پشیمانی تو می‌شود؛ کسی که تو فعالانه از او رویگردان هستی، یا صرفاً سعی می‌کنی نادیده‌اش بگیری. مهم نیست خشم تو چه شکلی به خود می‌گیرد. احتمالاً او را پیشاپیش انتخاب کرده‌ای. او انتخاب مناسبی خواهد بود.

حال چشمان خود را ببند و او را در ذهنت ببین، و مدت کوتاهی به او نگاه کن. سعی کن نوری را جایی در درونش ادراک کنی؛ تابشی کوچک که قبلاً هرگز متوجه آن نشده بودی. سعی کن اخگر کوچکی از روشنایی را بیابی که از درونِ تصویر زشتی که از او در ذهن داری، می‌تابد. به این تصویر نگاه کن تا زمانی که نوری را جایی درون آن ببینی، و سپس سعی کن اجازه دهی این نور گسترش یابد تا او را در بر گیرد، و این تصویر را زیبا و خوب کند.

زمان کوتاهی به این ادراک تغییر یافته نگاه کن، و سپس ذهنت را به یک نفر معطوف کن که او را دوست می‌خوانی. سعی کن نوری را که آموختی پیرامون «دشمن» قبلی خود ببینی، به او انتقال دهی. حال او را برای خود بیش از یک دوست ادراک کن، زیرا در آن نور، قداست او نجات دهندهٔ تو را نشانت می‌دهد، نجات یافته و نجات دهنده، شفا یافته و تمام.

سپس به او اجازه بده تا نوری را که در او می‌بینی به تو نثار کند، و بگذاری تا «دشمن» و دوستت در تبرک کردن تو با آنچه داده‌ای، با یکدیگر متحد شوند. اینک تو با آن‌ها یگانه هستی، و آن‌ها با تو. اینک تو توسط خودت بخشیده‌ شده‌ای. در طول روز، نقشی را که بخشایش در نثار کردن شادمانی به همهٔ ذهن‌های نابخشنده ایفا می‌کند از یاد نبر، و ذهن تو در بین این ذهن‌ها است. هر ساعت به خودت بگو: بخشایش کلید شادمانی است. من از این رؤیا بیدار خواهم شد که میرا، خطاکار و سرشار از گناه هستم، و خواهم دانست که فرزند* کامل خداوند* هستم.', 'https://acim-farsi.org/workbook/lesson/121', 'https://acim-farsi.org/audio/workbook/lesson/121.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (122, 'بخشایش همه‌ی چیزهایی را که من می‌خواهم عرضه می‌کند.', 'بخشایش همه‌ی چیزهایی را که من می‌خواهم عرضه می‌کند.
امروز من این را به عنوان حقیقت پذیرفته‌ام.
امروز من هدایای خداوند* را دریافت کرده‌ام.', 'بخشایش همه‌ی چیزهایی را که من می‌خواهم عرضه می‌کند.

تو چه چیزی را می‌توانی بخواهی که بخشایش نتواند عرضه کند؟ آیا صلح می‌خواهی؟ بخشایش آن را عرضه می‌کند. آیا شادمانی می‌خواهی، یک ذهن آرام، اطمینان به هدف، و حسی از ارزشمندی و زیبایی که از این دنیا فراتر رود؟ آیا مراقبت و امنیت می‌خواهی، و گرمای همیشگیِ یک حفاظت اطمینان بخش؟ آیا آرامشی می‌خواهی که نتوان آن را مختل کرد، ملایمتی که هرگز نتوان آزارش داد، یک راحتی عمیق مستقر، و آرامشی چنان کامل که هرگز نتواند آشفته شود؟

همهٔ این‌ها را بخشایش به تو عرضه می‌کند، و بیشتر از این. بخشایش زمانی که بیدار می‌شوی در چشمانت می‌درخشد، و به تو سرور می‌بخشد تا با آن روز را ملاقات کنی. بخشایش پیشانی تو را زمانی که در خواب هستی نوازش می‌کند، و بر پلک‌های تو می‌آرامد تا تو هیچ رؤیایی از ترس و شرارت، بدخواهی و حمله نبینی. و زمانی که تو دوباره بیدار شوی، بخشایش روز دیگری از شادمانی و صلح را به تو ارزانی می‌دارد. همهٔ این‌ها را بخشایش به تو عرضه می‌کند، و بیشتر از این.

بخشایش اجازه می‌دهد که حجاب برداشته شود، حجابی که چهرهٔ مسیحای* درون را از کسانی که با چشمان نابخشنده به این دنیا نظر می‌کنند، پنهان می‌کند. بخشایش به تو اجازه می‌دهد تا فرزند* خداوند* را بشناسی، و حافظهٔ تو را از همهٔ افکار مرده پاک می‌کند، چنان که یادآوریِ پدرت* بتواند از آستانهٔ ذهنت طلوع کند. تو چه چیزی را می‌خواهی که بخشایش نتواند نثار کند؟ چه موهبت‌هایی جز این‌ها، ارزشِ طلبیدن را دارند؟ کدام ارزش خیالی، تأثیر ناچیز یا عهد گذرا که هرگز پایدار نمی‌ماند، می‌تواند امیدی بیش از آنچه بخشایش به ارمغان می‌آورد، در خود داشته باشد؟

چرا بخواهی پاسخی را بطلبی غیر از آن پاسخ که به همه چیز پاسخ خواهد داد؟ پاسخ کامل در اینجا است، که به پرسش‌های ناکامل، درخواست‌های بی‌معنا، اراده‌های نصف و نیمه برای شنیدن، و تلاش اندک و اعتماد نسبی پاسخ می‌دهد. پاسخ در اینجا است! دیگر آن را جستجو نکن. هیچ پاسخ دیگری را به جای این نخواهی یافت.

نقشهٔ خداوند* برای رستگاری تو هرگز تغییر نمی‌کند، و هرگز شکست نمی‌خورد. سپاسگزار باش که این نقشه دقیقاً همانگونه باقی می‌ماند که او* طراحی کرد. این نقشه بدون تغییر پیش روی تو قرار می‌گیرد، مانند یک دروازه‌ی گشوده، با آوایی گرم و خوشامدگو که از ورای دروازه تو را می‌خواند، و از تو می‌خواهد که وارد شوی و آنجا را منزل خود بدانی، جایی که به آن تعلق داری.

پاسخ اینجا است! آیا می‌خواهی بیرون بایستی در حالی که همهٔ بهشت* در درون منتظر تو است؟ ببخش و بخشیده شو. همانگونه که می‌دهی، دریافت خواهی کرد. جز این هیچ نقشهٔ دیگری برای رستگاری فرزند* خداوند* وجود ندارد. بیایید امروز خوشحال باشیم که این‌چنین است، زیرا در اینجا ما یک پاسخ داریم، پاسخی صریح و روشن، فراتر از فریب در سادگی خود. همه پیچیدگی‌هایی که این دنیا با تارهای عنکبوت شکننده تنیده است در برابر قدرت و عظمت این بیان بسیار سادهٔ حقیقت ناپدید می‌شوند.

پاسخ اینجا است! دوباره در سرگردانی بی‌هدف رویگردان نشو. اکنون رستگاری را بپذیر. رستگاری موهبت خداوند* است، نه دنیا. دنیا نمی‌تواند هیچ هدیهٔ با ارزشی به ذهنی بدهد که آنچه را که خداوند* متعلق به آن مقرر کرده را دریافت کرده است. خداوند* اراده می‌کند که رستگاری امروز دریافت شود، و پیچیدگی‌های رؤیاهای تو بیش از این هیچ بودن آن‌ها را از تو پنهان نکنند.

امروز چشمان خود را بگشای و به دنیای شاد امنیت و صلح نظر کن. بخشایش وسیله‌ای است که توسط آن، این دنیای شاد جایگزین دوزخ می‌شود. در آرامش برمی‌خیزد تا چشمان باز تو را خوش‌آمد گوید، و قلب تو را همانند حقایق دیرین با آسودگی پُر کند، برای همیشه تازه متولد شده، طلوع کرده در آگاهی تو. سپس آنچه که به خاطر خواهی آورد هرگز نمی‌تواند توصیف شود. اما بخشایش تو آن را به تو عرضه می‌کند.

با یادآوری موهبت‌هایی که بخشایش عرضه می‌کند، تمرین‌های امروز را با این امید و ایمان انجام می‌دهیم که این روزی است که رستگاری از آن ما خواهد شد. با آگاهی از اینکه کلید را در دست خود داریم، با پذیرفتن پاسخ بهشت* به دوزخی که ایجاد کردیم اما نمی‌خواهیم بیش از این در آن بمانیم، با شوق و شادمانی امروز به دنبال رستگاری خواهیم بود.

صبح و عصر با شادمانی ربع ساعت را به جستجویی اختصاص می‌دهیم که قطعاً به دوزخ پایان می‌دهد. با امید آغاز کن، زیرا ما در نقطهٔ عطف آسان شدن راه هستیم. و اینک راه کوتاهی است که ما هنوز سفر می‌کنیم. ما واقعا به پایان مقرر شده‌ی این رؤیا نزدیک هستیم.

با شروع این دوره‌های تمرین در شادمانی غرقه شو، زیرا آن‌ها دربردارنده پاداش‌های مطمئن از پرسش‌های پاسخ داده و آنچه پذیرش این پاسخ‌ها از سوی تو به ارمغان می‌آورد، هستند. امروز مقرر شده است که تو صلحی را که بخشایش عرضه می‌کند احساس کنی، و سروری را که برداشته شدن حجاب برای تو در بر دارد.

در برابر نوری که امروز دریافت خواهی کرد این دنیا کم‌رنگ می‌شود تا ناپدید شود، و تو دنیای دیگری خواهی دید که طلوع می‌کند، دنیایی که کلامی برای به تصویر کشیدن آن نداری. اینک ما مستقیماً به درون نور گام برمی‌داریم و موهبت‌هایی را دریافت می‌کنیم که از آغاز زمان برای ما نگهداری شده‌اند و در انتظار امروز مانده‌اند.

بخشایش همهٔ چیزهایی را که تو می‌خواهی عرضه می‌کند. امروز همه‌ی چیزهایی که می‌خواهی به تو داده شده‌اند. امروز وقتی که به ملاقات دنیای تغییرات متناوب و ظواهر غم‌افزا برمی‌گردی اجازه نده هدایای تو در طول روز دور شوند. هدایای خود را در آگاهی روشن حفظ کن، زیرا تو تغییرناپذیر را در قلب تغییر می‌بینی؛ و نور حقیقت را ورای ظواهر.

وسوسه نشو که اجازه دهی تا هدایای تو لغزیده و به درون فراموشی رانده شوند، اما آن‌ها را در ذهن خود محکم نگه‌دار با تلاش برای فکر کردن به آن‌ها دست کم یک دقیقه از هر ربع ساعت که می‌گذرد. با این ذکر به خودت یادآوری کن که این هدایا چقدر گران‌بها هستند، ذکری که قدرت نگه داشتن هدایای تو در آگاهی‌ات را در طول روز دارد: بخشایش همهٔ چیزهایی را که من می‌خواهم عرضه می‌کند. امروز من این را به عنوان حقیقت پذیرفته‌ام. امروز من هدایای خداوند* را دریافت کرده‌ام.', 'https://acim-farsi.org/workbook/lesson/122', 'https://acim-farsi.org/audio/workbook/lesson/122.mp3', 'interval', '[{"kind":"interval","minutes":15}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (123, 'من از پدرم* برای هدایایش* که به من داده، سپاسگزارم.', 'من از پدرم* برای هدایایش* که به من داده، سپاسگزارم.', 'من از پدرم* برای هدایایش* که به من داده، سپاسگزارم.

امروز بیاید سپاسگزار باشیم. ما به مسیرهای ملایم‌تر و جاده‌های هموار‌تری رسیده‌ایم. هیچ اندیشه‌ی بازگشتی وجود ندارد، و هیچ مقاومت تسکین‌ناپذیری در برابر حقیقت. مقداری تزلزل باقی می‌ماند، برخی مخالفت‌های کوچک و کمی تردید، اما تو می‌توانی به خوبی برای دستاوردهای خود شکرگزار باشی، که بسیار عظیم‌تر از آن هستند که اکنون تشخیص می‌دهی.

اینک یک روز که وقف سپاسگزاری شود، این منفعت را خواهد افزود که تو نگرشی به وسعت واقعی همهٔ دستاوردهایی که داشته‌ای، پیدا کنی؛ به هدایایی که دریافت کرده‌ای. امروز خوشحال باش، در شکرگزاری عاشقانه، پدرت* تو را به حال خود رها نکرده است، و نگذاشته است که تو به تنهایی در تاریکی سرگردان شوی. سپاسگزار باش که او تو را از آن خودی که فکر می‌کردی ساخته‌ای تا جای او و خلقتش را بگیرد، نجات داد. امروز او را شکر کن.

شکرگزاری کن که او* تو را ترک نکرده است، و عشق* او* برای همیشه بر تو تابنده خواهد ماند، برای همیشه بی‌تغییر. همچنین شکر کن که تو بی‌تغییر هستی، زیرا آن فرزند* که آفریدگارش* به او* عشق می‌ورزد، مانند خودش* بی‌تغییر است. سپاسگزار باش که نجات یافته‌ای. شاد باش که وظیفه‌ای در رستگاری داری که باید به انجام برسانی. شکرگزار باش که ارزشت بسیار فراتر از هدایای نحیف و قضاوت‌های بی‌ارزشت در مورد فرزند* تعیین شده توسط خداوند* است.

امروز ما در سپاسگزاری، قلب‌های خود را فراتر از نومیدی می‌افرازیم، و چشمان شکرگزار خود را به بالا می‌دوزیم، و دیگر به پایین، به دنیای خاکی نگاه نمی‌کنیم. امروز ما سرود شکرگزاری را می‌خوانیم، به افتخار آن خویشتن* که خداوند* اراده کرده هویت* حقیقی ما در او* باشد. امروز به روی همهٔ آنان که می‌بینیم لبخند می‌زنیم، با گام‌هایی سبک قدم برمی‌داریم در حالی که می‌رویم کاری را انجام دهیم که انجامش برای ما مقرر شده است.

ما تنها نمی‌رویم. و شکر می‌کنیم که در تنهایی ما، یک دوست* آمده است تا کلام* نجات‌بخش خداوند* را با ما بگوید. و سپاس از تو که به او* گوش فرا می‌دهی. اگر کلام* او* شنیده نشود، صدایی ندارد. با سپاسگزاری از او*، از تو نیز سپاسگزاری می‌شود. یک پیام ناشنیده این دنیا را نجات نخواهد داد، هر اندازه که آن آوای* سخنگو قدرتمند باشد، و هر اندازه که آن پیام عاشقانه باشد.

سپاس از تو که شنیدی، زیرا تو به پیام‌آوری تبدیل می‌شوی که آوای* او* را با خود حمل می‌کند، و اجازه می‌دهد که آن آوا* در سراسر این دنیا پژواک کند. امروز سپاس خداوند* را بپذیر، در حالی که او* را شکر می‌کنی. زیرا او می‌خواهد سپاسی را که به او* عرضه می‌کنی به تو تقدیم کند، زیرا او* هدایای تو را با سپاسی عاشقانه می‌پذیرد، و آن‌ها را هزار و صدهزار برابر بیش از آنچه عرضه شده، بازتقدیم می‌‌کند. او* هدایایت را با سهیم شدن آن‌ها با تو، متبرک خواهد کرد. و اینچنین، توان و قدرت این هدایا رشد می‌کند، تا زمانی که این دنیا را با شادمانی و با سپاسگزاری سرشار کنند.

امروز در دو نوبت و در هر نوبت به مدت پانزده دقیقه سپاس او* را بپذیر و سپاس خود را به او* تقدیم کن. و متوجه خواهی شد که به چه وجودی* سپاس خود را تقدیم می‌کنی، و او* در حالی که او* را شکر می‌کنی از چه وجودی سپاسگزاری می‌کند. این نیم ساعت مقدس که به او* تقدیم می‌کنی، برای هر ثانیه به اندازه سال‌ها به تو باز خواهد گشت، قدرت نجات این دنیا با سپاسگزاری تو از او*، دوره‌های زمانی زیادی به جلو خواهد افتاد.

سپاس او* را دریافت کن، و درک خواهی کرد که او* چه عاشقانه تو را در ذهنش* نگاه داشته است، محبت او* به تو چقدر عمیق و نامحدود است، قدردانی او* از تو چقدر کامل است. هر ساعت به یاد بیاور که به او* بیندیشی، و او را برای همه چیز که به فرزند* خود* داده شکر کن، تا او بتواند به فراتر از این دنیا ببالد، با به یاد آوردن پدرش* و خویشتنش*.', 'https://acim-farsi.org/workbook/lesson/123', 'https://acim-farsi.org/audio/workbook/lesson/123.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (124, 'باشد تا به یاد داشته باشم که من با خداوند* یگانه هستم.', 'باشد تا به یاد بیاورم که با خداوند* یگانه هستم، یگانه با تمامی برادرانم و با خویشتنم*، در قداست و صلح ابدی.', 'باشد تا به یاد داشته باشم که من با خداوند* یگانه هستم.

امروز ما دوباره از هویت* خود در خداوند*، شکرگزاری می‌کنیم. منزل ما امن است، در همه کار که انجام می‌دهیم بدون شک محافظت می‌شویم، در همه‌ی مسئولیت‌های خود توان و قدرت را در دسترس داریم. ما ممکن نیست در هیچ کاری شکست بخوریم. هرچه که ما لمس می‌کنیم نور درخشانی می‌گیرد که متبرک می‌کند و شفا می‌دهد. در یگانگی با خداوند* و با جهان، ما مسرور به راه خود می‌رویم، با این اندیشه که خود* خداوند* همه جا با ما می‌آید.

چقدر ذهن‌های ما قدسی هستند! و هرچه که ما می‌بینیم، قداست را درون آن ذهنی منعکس می‌کند که با خداوند* و با خودش یگانه است. خطاها چقدر آسان محو می‌گردند، و مرگ جای خود را به حیات جاوید می‌دهد. ردپاهای درخشان ما به راه به سوی حقیقت اشاره می‌کنند، زیرا در حال گام برداشتن در این دنیا برای این مدت کوتاه، خداوند* با ما همراه است. و آنان که برای پیروی از ما می‌آیند راه را تشخیص خواهند داد زیرا نوری که با خود حمل می‌کنیم در پس ما می‌ماند، اگرچه هنوز در مسیری که می‌پیماییم با ما باقی می‌ماند.

آنچه ما دریافت می‌کنیم، هدیه‌ی ابدی ما به کسانی است که پس از این راه را دنبال می‌کنند، و کسانی که قبلاً از راه عبور کرده‌اند یا زمان کوتاهی را با ما بوده‌اند. و خداوند*، که به اندازهٔ همان عشقی که در آن آفریده شدیم به ما عشق می‌ورزد، به ما لبخند می‌زند و آن شادمانی را که نثار کرده‌ایم، به ما تقدیم می‌کند.

امروز ما به عشق او* به خودمان شک نخواهیم کرد، و محافظت و لطف او* را مورد پرسش قرار نخواهیم داد. هیچ اضطراب بی‌معنایی نمی‌تواند بین ایمان ما و آگاهی ما از حضور او* قرار گیرد. امروز ما با او* در تشخیص و یادآوری یگانه هستیم. ما او* را در قلب خود احساس می‌کنیم. ذهن‌های ما حاوی اندیشه‌های* او* هستند؛ چشمان ما در هرچه به آن می‌نگریم، نظاره‌گر زیبایی او* می‌شوند. امروز ما فقط آنچه را که عاشق و عشق‌ورزیدنی است می‌بینیم.

ما این عشق‌ورزی را در بروز دردها می‌بینیم، و درد جای خود را به صلح می‌دهد. ما این عشق‌ورزی را در انسان‌های آشفته، انسان‌های غمگین و افراد دردمند، انسان‌های تنها و هراسان می‌بینیم، که به آن آرامش و صلح ذهنی که در آن آفریده شدند، بازگردانده می‌شوند. و ما این عشق‌ورزی را در افراد در حال مرگ و مردگان نیز می‌بینیم، که آنان را به زندگی بازمی‌گرداند. ما همه‌ی این‌ها را می‌بینیم زیرا ابتدا عشق‌ورزی را در خودمان مشاهده کرده‌ایم.

هیچ معجزه‌ای هرگز از آنان که می‌دانند با خداوند* یگانه هستند، دریغ نمی‌شود. هیچ اندیشه‌ای از آنان نیست، جز اینکه توان شفابخشی همهٔ شکل‌های رنج را در همگان دارد، در زمان‌های گذشته و زمان‌هایی که هنوز فرا نرسیده‌اند، به همان آسانی که اینک همراهان آنان را شفا می‌بخشد. اندیشه‌های ایشان بی‌زمان است، و از فاصله و از زمان جدا است.

ما در این آگاهی مشارکت می‌کنیم زمانی که می‌گوییم با خداوند* یگانه هستیم. زیرا در این کلمات که ما نیز می‌گوییم، نجات و شفا می‌یابیم؛ و از این رو می‌توانیم نجات و شفا را تقدیم کنیم. ما با پذیرش دریافت کرده‌ایم، و اکنون می‌خواهیم نثار کنیم. زیرا می‌خواهیم هدایایی را که پدرمان* به ما داده، حفظ کنیم. امروز ما می‌خواهیم یگانگی خودمان با او* را تجربه کنیم، تا این دنیا بتواند در تشخیص واقعیت توسط ما سهیم شود. در تجربهٔ ما، این دنیا آزاد می‌شود. در حالی که ما جدایی خود از پدرمان* را انکار می‌کنیم، این دنیا در همراهی با ما شفا می‌یابد.

امروز صلح نثار تو باد. صلح خود را با تمرین این آگاهی که با پدر* خود* یگانه هستی همانگونه که او* با تو یگانه است، تضمین کن. امروز در زمان‌هایی، هر زمان که به نظرت بهتر باشد، نیم ساعت را برای این اندیشه وقف کن که با خداوند* یگانه هستی. این نخستین تلاش ما برای دوره زمانی طولانی است که در آن به تو قواعد یا کلمات خاصی داده نخواهد شد تا مراقبه تو را هدایت کند. ما امروز به آوای* خداوند* اعتماد خواهیم کرد که هرگونه او* مناسب ببیند سخن می‌گوید، با این اطمینان که او* هرگز شکست نمی‌خورد. برای نیم ساعت با او* ساکن شو. بقیه کار را او* انجام خواهد داد.

اگر باور داشته باشی که هیچ اتفاقی نمی‌افتد، منفعت تو کمتر نخواهد شد. ممکن است تو امروز برای دریافت این دستاورد آماده نباشی. اما در زمانی، در مکانی، این دستاورد به سوی تو خواهد آمد، و آنگاه تو قطعاً آن را تشخیص خواهی داد، که با یقین بر ذهنت طلوع می‌کند. این نیم ساعت قاب طلا گرفته خواهد شد، و هر دقیقه مانند الماسی است نصب شده پیرامون آینه‌ای که این تمرین به تو تقدیم خواهد کرد. و تو از درون آن چهرهٔ مسیحا* را خواهی دید، در بازتابی از چهرهٔ خودت.

شاید امروز، شاید فردا، تو تغییر چهرهٔ خود را در آبگینه‌ای که این نیم ساعت قدسی به تو تقدیم خواهد کرد تا به خودت بنگری، خواهی دید. زمانی که آماده باشی، آن را آنجا خواهی یافت، درون ذهنت و در انتظار برای یافت شدن. آنگاه آن اندیشه را که این نیم ساعت‌ را نثارش کردی، به یاد خواهی آورد، با سپاسگزاری، آگاه از این که هیچ زمانی را بهتر از این سپری نکرده‌ای.

شاید امروز، شاید فردا، تو درون این آبگینه نگاه خواهی کرد، و درک خواهی کرد که آن نور معصوم که می‌بینی به تو تعلق دارد؛ آن زیبایی که مشاهده می‌کنی متعلق به خود تو است. این نیم ساعت را هدیه خودت به خداوند* محسوب کن، در این یقین که بازگشت او* حسی عاشقانه خواهد بود که تو نمی‌توانی درک کنید، سروری چنان عمیق که نمی‌توانی فهمش کنی، منظره‌ای بیش از آن قدسی که چشمان بدن بتوانند ببینند. و با این حال تو می‌توانی مطمئن باشی که روزی، شاید امروز، شاید فردا، درک خواهی کرد و فهم خواهی کرد و خواهی دید.

و جواهرات بیشتری را به آن قاب طلایی اضافه کن که امروز آینه‌ی تقدیمی به تو را در بر می‌گیرد، با تکرار عبارات زیر در هر ساعت برای خودت: باشد تا به یاد بیاورم که با خداوند* یگانه هستم، یگانه با تمامی برادرانم و با خویشتنم*، در قداست و صلح ابدی.', 'https://acim-farsi.org/workbook/lesson/124', 'https://acim-farsi.org/audio/workbook/lesson/124.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (125, 'در سکوت، من امروز کلام* خداوند* را دریافت می‌کنم.', 'در سکوت، من امروز کلام* خداوند* را دریافت می‌کنم.', 'در سکوت، من امروز کلام* خداوند* را دریافت می‌کنم.

باشد تا امروز، روز سکون و گوش فرادادن در سکوت باشد. پدر* تو اراده می‌کند که امروز کلام* او* را بشنوی. و اینچنین او* از عمق درونِ ذهنت تو را می‌خواند، آنجا که سکنی دارد. امروز او* را بشنو. هیچ صلحی ممکن نیست تا زمانی که کلام* او* در سراسر این دنیا شنیده شود؛ تا زمانی که ذهن تو، در سکوتی شنوا، پیامی را بپذیرد که این دنیا باید برای به وجود آوردن دورانی ساکت از صلح، آن را بشنود.

این دنیا از طریق تو تغییر خواهد یافت. هیچ وسیله‌ی دیگری نمی‌تواند نجاتش دهد، زیرا نقشهٔ خداوند* به سادگی این است: فرزند* خداوند* آزاد است تا خودش را نجات دهد، کلام* خداوند* به او داده می‌شود تا راهنمایش باشد، همواره در ذهنش و خیرخواه او، تا او را در امنیت با ارادهٔ خودش به منزل پدرش* رهنمون گردد، اراده‌ای که همواره مانند ارادهٔ* خداوند* آزاد است. او با جبر راهنمایی نمی‌شود، بلکه فقط عشق راهنمای او است. در موردش قضاوت نمی‌شود، بلکه فقط آمرزیده می‌شود.

ما امروز در سکون، آوای* خداوند* را خواهیم شنید. بدون مزاحمت افکارِ ناچیزمان، بدون امیالِ شخصی، و بدون هیچگونه قضاوتی در مورد کلام* قدسی او*. امروز ما خودمان را قضاوت نخواهیم کرد، زیرا آنچه که ما هستیم را نمی‌توان قضاوت کرد. ما برکنار از همهٔ قضاوت‌هایی خواهیم ایستاد که این دنیا بر فرزند* خداوند* هموار کرده است. این دنیا از او هیچ نمی‌داند. امروز ما به این دنیا گوش نمی‌کنیم، بلکه در سکوت برای کلام* خداوند* منتظر می‌مانیم.

بشنو، فرزند* مقدسِ خداوند*! پدرت* سخن می‌گوید. آوای* او*، کلام* مقدسش* را به تو عطا می‌کند، تا در سراسر این دنیا، بشارتِ رستگاری و دوران مقدس صلح را منتشر کنی. امروز ما در کنار اورنگِ خداوند* گرد می‌آییم، آن مکان ساکت درون ذهن که او* برای همیشه در آنجا منزل دارد، در قداستی که او* آفریده و هرگز ترکش نخواهد کرد.

او* منتظر نمانده است تا زمانی که تو ذهنت را به سویش برگردانی تا کلامش* را به تو عطا کند. او* خودش* را از تو پنهان نکرده است، در حالیکه که تو برای زمان کوتاهی دور از او* سرگردان بوده‌ای. او* اوهامی را که تو در مورد خودت باور داری، نمی‌پرورد. او* فرزند* خود* را می‌شناسد، و اراده می‌کند که او به عنوان بخشی از او* باقی بماند، فارغ از رؤیاهایش، فارغ از این دیوانگی‌اش که اراده‌اش را متعلق به خودش نمی‌داند.

امروز او* با تو سخن می‌گوید. آوای* او* سکوت تو را انتظار می‌کشد، زیرا کلامش* نمی‌تواند شنیده شود تا زمانی که ذهنت لَختی ساکت شده باشد، و امیالِ بی‌معنا متوقف شده باشند. در سکوت، منتظرِ کلام* او* بمان. صلحی در درونِ تو وجود دارد که باید امروز فراخوانده شود، تا به آماده شدنِ مقدس‌ترین ذهنِ تو یاری کند، برای شنیدن آوایی* که برای آفریدگارش* سخن می‌گوید.

امروز سه مرتبه در مناسب‌ترین زمان‌ها برای سکوت، هر بار ۱۰ دقیقه از گوش دادن به این دنیا کناره بگیر، و در عوض انتخاب کن که به آرامی به کلام* خداوند* گوش فرادهی. او* از جایی نزدیک‌تر از قلبت با تو سخن می‌گوید. آوای* او* از دستت به تو نزدیک‌تر است. عشق او همهٔ چیزی است که تو هستی و خود* او* است؛ همسان با تو، و تو همسان با او*.

همچنان که او* با تو سخن می‌گوید، این آوای تو است که بدان گوش می‌دهی. این کلام تو است که او* می‌گوید. این کلامِ* آزادی و صلح، کلامِ وحدتِ اراده و هدف است، بدون هیچگونه جدایی و هیچ شکافی در ذهنِ* یگانهٔ پدر* و فرزند*. امروز در سکوت به خویشتنت* گوش فرا بده، و بگذار او* به تو بگوید که خداوند* هرگز فرزندش* را ترک نکرده، و تو هرگز خویشتن* خود را ترک نکرده‌ای.

فقط ساکت باش. تو به هیچ قاعده‌ی دیگری نیاز نخواهی داشت، تا اجازه دهی تمرینِ امروزت تو را به ورای اندیشیدن به این دنیا بالا ببرد، و رؤیتِ تو را از چشمانِ بدن آزاد کند. تنها آرام باش و گوش فرا بده. تو کلامی* را خواهی شنید که در آن ارادهٔ* خداوند* فرزند* به ارادهٔ* پدرش* می‌پیوندد، با آن یگانه می‌شود، بدون این که هیچ وهمی درون آنچه به تمامی تقسیم‌ناشدنی و حقیقی است مداخله کند. امروز با هر ساعتی که می‌گذرد، لحظه‌ای آرام باش و به خودت یادآوری کن که برای این روز قصد خاصی داری؛ دریافت کلامِ* خداوند* در سکوت.', 'https://acim-farsi.org/workbook/lesson/125', 'https://acim-farsi.org/audio/workbook/lesson/125.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (126, 'همهٔ آنچه که من می‌دهم، به من داده می‌شود.', 'همه‌ی آنچه که من می‌دهم، به من داده می‌شود. آن کمک* که برای آموختن حقیقتِ این سخن نیاز دارم، اکنون با من است. و من به او* اعتماد خواهم کرد.', 'همهٔ آنچه که من می‌دهم، به من داده می‌شود.

ایدهٔ امروز کاملاً برای نفس و برای اندیشهٔ این دنیا بیگانه است، این ایده برای وارونگی اندیشه که این دوره به بار می‌آورد، اهمیتی حیاتی دارد. اگر تو این سخن را باور داشتی، هیچ مشکلی در بخشایشِ کامل، یقین به هدف و استواری در مسیر نمی‌داشتی. وسیله‌ای را که رستگاری توسط آن به سویت می‌آید درک می‌کردی، و هم‌اکنون در استفاده از آن درنگ نمی‌کردی.

بیایید ملاحظه کنیم که تو به جای این ایده، به چه چیز باور داری. به نظر می‌رسد که مردمانِ دیگر از تو جدا هستند، و قادر هستند به روش‌هایی رفتار کنند که هیچ ربطی به اندیشه‌های تو ندارد، و نیز رفتار تو به اندیشه‌های آنان. بنابراین، نگرش‌های تو اثری بر آنان ندارد، و درخواست‌های آنان برای کمک به هیچ روی به درخواست خودِ تو مربوط نیست. تو همچنین می‌اندیشی که دیگران می‌توانند گناه کنند بدون این که بر ادراکِ تو از خودت اثر بگذارند، در حالی که تو می‌توانی گناهِ آنان را قضاوت کنی، اما همچنان از نکوهش برکنار و در صلح بمانی.

زمانی که تو یک گناه را «می‌بخشی»، مستقیماً هیچ دستاوردی نداری. به یک فردِ نالایق صدقه می‌دهی، صرفاً از این رو که خاطرنشان کنی تو بهتر هستی، از آن کسی که می‌بخشی در مرتبهٔ بالاتری هستی. او به مدارای نیکوکارانهٔ تو دست نیافته، و تو این مدارا را وقفِ کسی می‌کنی که شایستهٔ این موهبت نیست، زیرا گناهانش او را پست‌تر از یک برابریِ حقیقی با تو به پایین کشیده. او هیچ حقی برای بخشایشِ تو ندارد. بخشایشِ تو، هدیه‌ای را به او می‌دهد، اما به ندرت تو را بهره‌مند می‌کند.

اینچنین است که بخشایش، اساساً نامعقول به نظر می‌رسد؛ یک هوسِ نیکوکارانه، سخاوتمندانه اما برای فردی نالایق، هدیه‌ای که گاه وقف می‌شود، و در زمان‌هایی دیگر دریغ می‌گردد. بدون استحقاق، دریغ کردن عادلانه است، و نیز منصفانه نیست که تو ناگزیر شوی زمانی که دریغ می‌کنی، زجر بکشی. آن گناه که تو می‌بخشی، متعلق به خودِ تو نیست. فردی جدا از تو مرتکبِ آن شده است. و اگر تو آنقدر با او بخشنده هستی که آنچه را شایسته‌اش نیست به او می‌دهی، این هدیه دیگر متعلق به تو نیست، همانطور که گناهِ او به خودش تعلق دارد.

اگر این‌ها حقیقت داشته باشد، بخشایش هیچ بنیانی ندارد که بر آن قابل اتکا و استوار بماند. در این صورت بخشایش اقدامی غیرعادی است که در آن تو گاهی انتخاب می‌کنی با تساهل، تعویقِ مجازاتی را به یک فرد نالایق عطا کنی. اما این حقِ تو باقی می‌ماند که اجازه ندهی گناهکار از کیفرِ عادلانه برای گناهش بگریزد. آیا تو فکر می‌کنی که خداوندِ* بهشت* اجازه می‌دهد تا رستگاریِ این دنیا بر این مبنا استوار شود؟ آیا محبتِ او* به تو حقیقتاً اندک نمی‌بود، اگر رستگاریِ تو به یک هوس وابسته می‌شد؟

تو بخشایش را درک نمی‌کنی. از دیدِ تو، بخشایش چیزی نیست جز یک وقفه پیش از حملهٔ علنی، بدون نیاز به این که چیزی را در ذهنت تصحیح کنی. آنگونه که تو درکش می‌کنی، بخشایش نمی‌تواند به تو صلح عطا کند. این بخشایش وسیله‌ای برای تو نیست که با آن بتوانی از آنچه در فردی غیر از خودت می‌بینی، رها شوی. این بخشایش هیچ قدرتی ندارد که بتواند یگانگیِ تو را با آن فرد، به آگاهیِ تو بازگرداند. این بخشایش، آن چیزی نیست که خداوند* مقرر کرد برای تو باشد.

اگر هدیه‌ای را که او* از تو می‌خواهد به او نداده باشی، نمی‌توانی هدایای او* را تشخیص دهی، و می‌پنداری که او*، آن‌ها را به تو عطا نکرده است. اما آیا خداوند هدیه‌ای را از تو طلب می‌کند مگر اینکه آن هدیه برای خود تو باشد؟ آیا او* با اداهای توخالی، خرسند می‌شود و چنین هدایای بی‌ارزشی را شایستهٔ فرزندش* به شمار می‌آورد؟ رستگاری، هدیه‌ای بهتر از این است. و بخشایشِ حقیقی، به عنوان وسیله‌ای برای دستیابی به رستگاری، ناگزیر است آن ذهنی را که نثارش می‌کند شفا بخشد، زیرا دادن همان دریافت کردن است. آنچه که دریافت نشده باقی می‌ماند، داده نشده است، اما آنچه داده شده است، باید دریافت شده باشد.

امروز ما تلاش می‌کنیم این حقیقت را بفهمیم که دهنده و دریافت کننده با هم یکی هستند. تو برای معنا دادن به این سخن، نیاز به کمک خواهی داشت، زیرا این سخن با اندیشه‌هایی که تو به آنها خو گرفته‌ای بسیار بیگانه است. اما آن کمک* که بدان نیاز داری، حاضر است. امروز ایمانِ خود را به او* بسپار، و از او* بخواه که امروز در تمرینِ تو برای درکِ حقیقت مشارکت کند. و اگر تو فقط نظری اجمالی و کوتاه به آن رهایی که در ایدهٔ تمرینِ امروز نهفته است بیفکنی، امروز برای این دنیا روزِ شکوهمندی است.

امروز دو تمرین پانزده دقیقه‌ای را به تلاش برای فهمیدن ایدهٔ روز اختصاص بده. این اندیشه‌ای است که توسط آن، بخشایش جایگاهِ شایستهٔ خود را در بین اولویت‌های تو پیدا می‌کند. این اندیشه‌ای است که ذهن تو را از همه‌ی موانعی که بر سر راهِ معنای بخشایش هستند، رها می‌کند. و به تو اجازه می‌دهد تا ارزشِ بخشایش برای خودت را درک کنی.

در سکوت، چشمانت را به روی دنیایی که بخشایش را نمی‌فهمد، ببند، و به آن مکانِ ساکتی پناه ببر که در آنجا اندیشه‌ها تغییر می‌کنند و باورهای نادرست کنار گذاشته می‌شوند. ایدهٔ امروز را تکرار کن، و برای فهمیدن معنای واقعیِ آن، کمک بخواه. مصمم باش که بیاموزی. از شنیدن آوای* حقیقت و شفا که با تو سخن می‌گوید، شادمان باش. و تو کلماتی را که او* می‌گوید خواهی فهمید، و تشخیص خواهی داد که کلماتِ خودت را به تو می‌گوید.

به دفعاتِ ممکن، به خودت یادآوری کن که امروز یک هدف داری؛ هدفی که به این روز برای تو و برای همهٔ برادرانت ارزشی ویژه می‌بخشد. اجازه نده که ذهنت این هدف را برای مدتی طولانی فراموش کند، بلکه به خودت بگو: همه‌ی آنچه که من می‌دهم، به من داده می‌شود. آن کمک* که برای آموختن حقیقتِ این سخن نیاز دارم، اکنون با من است. و من به او* اعتماد خواهم کرد. سپس لحظه‌ای را در سکوت بگذران، در حالی که ذهنت را به اصلاحِ او* و به عشقِ* او* می‌گشایی. و آنچه که از او* می‌شنوی، باور خواهی کرد. زیرا آنچه او* می‌دهد توسط تو دریافت خواهد شد.', 'https://acim-farsi.org/workbook/lesson/126', 'https://acim-farsi.org/audio/workbook/lesson/126.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (127, 'هیچ عشقی جز عشقِ* خداوند* وجود ندارد.', 'من تو را متبرک می‌کنم برادر، با عشقِ* خداوند*، که می‌خواهم آن را با تو سهیم گردم. زیرا می‌توانم این درسِ خجسته را یاد بگیرم که هیچ عشقی جز عشقِ خداوند و عشقِ تو، و عشقِ من، و عشقِ همگان وجود ندارد.', 'هیچ عشقی جز عشقِ* خداوند* وجود ندارد.

شاید تو می‌اندیشی که انواع مختلفِ عشق ممکن است. شاید تو می‌اندیشی که نوعی از عشق برای این و نوعی از عشق برای آن وجود دارد، شیوه‌ای برای عشق ورزیدن به یکی و شیوه‌ای دیگر برای عشق ورزیدن به دیگری. عشق یگانه است. دارای بخش‌های جداگانه و درجات نیست؛ دارای انواع و سطوح نیست، دارای تنوع وتمایز نیست. عشق مانندِ خودش است، به تمامی تغییرناپذیر. عشق هرگز با فرد یا شرایط عوض نمی‌شود. عشق قلب* خداوند* است، و نیز قلب فرزند* او*.

معنای عشق بر هر کسی که می‌اندیشد عشق می‌تواند تغییر کند، پوشیده است. چنین فردی نمی‌بیند که عشقِ متغیّر باید ناممکن باشد. و اینچنین او می‌اندیشد که قادر است زمان‌هایی عشق بورزد و زمان‌هایی دیگر نفرت ابراز کند. او همچنین می‌اندیشد که عشق می‌تواند به کسی ارزانی شود و اگرچه از دیگران دریغ می‌شود، باز خودش باقی بماند. باور داشتن به این چیزها درمورد عشق یعنی نفهمیدنِ آن. اگر عشق می‌توانست چنین تمایزهایی را قائل شود، بایستی میانِ محق و گناهکار قضاوت می‌کرد، و فرزند* خداوند* را به صورت بخش‌های جداگانه ادراک می‌نمود.

عشق نمی‌تواند قضاوت کند. از آنجایی که خودش یگانه است، همه را یگانه می‌بیند. معنای عشق در یگانگی نهفته است. و ناگزیر است از ذهنی بگریزد که آن را نسبی یا قابل تقسیم می‌پندارد. هیچ عشقی جز عشقِ* خداوند* وجود ندارد، و همه‌ی عشق از آنِ او است . هیچ اصل دیگری وجود ندارد که حکم کند عشق در جایی نباشد. عشق قانونی است بدون متضاد . تمامیتِ آن، قدرتی است که همه چیز را یگانه نگاه می‌دارد، پیوند بین خداوند* و فرزندش*، که هردوی آنان را برای همیشه یکسان نگه می‌دارد.

هیچ دوره‌ای که قصدش این باشد که به تو بیاموزد آنچه واقعاً هستی را به یاد آوری، نمی‌تواند بر این نکته تأکید نکند که هرگز نمی‌تواند تفاوتی میان آنچه تو واقعاً هستی و آنچه عشق است وجود داشته باشد. معنای عشق، معنای خود تو است، و خود* خداوند* نیز در آن سهیم است. زیرا آنچه تو هستی، همان است که او* هست. هیچ عشقی جز عشقِ او* وجود ندارد، و آنچه که او* هست، همهٔ آن چیزی است که هست. هیچ محدودیتی بر خود* او* اِعمال نمی‌شود، و اینچنین تو نیز نامحدود هستی.

هیچ قانونی که این دنیا از آن تابعیت می‌کند، نمی‌تواند به تو کمک کند تا معنای عشق را دریابی. آنچه که این دنیا باور می‌کند، برای پنهان کردنِ معنای عشق ساخته شد، و تاریک و رازآلود نگه داشتنِ آن. این دنیا حتی از یک اصل حمایت نمی‌کند که حقیقتِ وجودیِ عشق را نقض نکند، و نیز حقیقتِ وجودیِ تو را.

درونِ این دنیا را برای یافتن خویشتن* خودت جستجو نکن . عشق در تاریکی و مرگ یافت نمی‌شود. اما کاملاً برای چشمانی که می‌بینند و گوش‌هایی که آوای* عشق را می‌شنوند، آشکار است. امروز ما تمرین می‌کنیم تا ذهن تو را از همهٔ قوانینی که می‌اندیشی ناگزیر هستی از آن‌ها تبعیت کنی، آزاد کنیم؛ از همهٔ محدودیت‌هایی که تو تحت آن‌ها زندگی می‌کنی، و همه‌ی تغییراتی که تو می‌اندیشی بخشی از سرنوشتِ بشر هستند. امروز ما بزرگترین تک گامی را که این دوره از تو برای پیشرفت به سوی هدفِ تعیین شدهٔ خود می‌طلبد، بر خواهیم داشت.

اگر تو امروز به کمترین تابشی از معنای عشق دست یابی، در رهاییِ خود به فاصله‌ای غیرقابل اندازه‌گیری و برای مدت زمانی فراتر از شمارشِ سالیان پیشرفت کرده‌ای. پس باشد تا ما امروز در کنارِ هم، از نثار بخشی از زمانِ خود به خداوند* شادمان باشیم. و بفهمیم که برای زمان، هیچ استفاده‌ای بهتر از این وجود ندارد.

امروز دو بار برای پانزده دقیقه از تمام قوانینی که اکنون به آن‌ها باور داری، بگریز. ذهنت را بگشای و آرام بگیر. گریز از دنیایی که ظاهراً تو را در بندِ خود نگاه داشته، توسط هر کسی که آن را عزیز ندارد، ممکن است. همهٔ ارزشی را که برای داده‌های ناچیز و هدایای بی‌معنای آن قائل شده‌ای، رها کن، و اجازه بده تا موهبتِ خداوند* جایگزین همهٔ آن‌ها شود.

پدرت* را بخوان، با یقین به این که آوای* او* پاسخ خواهد داد. او* خودش* چنین وعده‌ای داده است. و او* خودش اخگری از حقیقت را در ذهن تو خواهد نشاند، در هر جایی که یک باورِ باطل، وهمی تاریک از واقعیتِ خودت و از معنای عشق را رها کنی. امروز او* بر پندارهای بیهودهٔ تو خواهد تابید، و به تو کمک خواهد کرد تا حقیقتِ عشق را بفهمی. با ملایمتی عاشقانه، او* با تو همراه خواهد ماند، مادامی که اجازه می‌دهی آوای* او* معنای عشق را به ذهنِ پاکیزه و گشودهٔ تو بیاموزد. و او* این درس را با عشقِ* خویش*، متبرک خواهد کرد.

امروز سال‌های فراوانِ انتظار کشیدنِ تو برای رستگاری در آینده، پیش روی بی‌زمانیِ آنچه که می‌آموزی، ناپدید خواهند شد. بیایید امروز شکرگزار باشیم که آینده‌ای مانندِ گذشته را فروگذاشته‌ایم. امروز ما گذشته را پشت سر می‌گذاریم، تا هرگز به یاد آورده نشود. و چشمانِ خود را به روی زمان حالی جدید می‌افرازیم، جایی که آینده‌ای طلوع می‌کند بدونِ هیچگونه شباهت به گذشته.

این دنیای نوزاد، تازه متولد شده است. ما رشد آن را در سلامتی و قدرت ناظر خواهیم بود، و تبرکش را به همهٔ کسانی نثار می‌کنیم که می‌آیند تا بیاموزند دنیایی را دور بیندازند که می‌پنداشتند در نفرت ساخته شده تا دشمنِ عشق باشد. اینک همه‌ی آنان آزاد می‌شوند، همراه با ما. اینک همه‌ی آنان برادران ما در عشقِ* خداوند* هستند.

ما آنان را در طولِ روز به یاد خواهیم داشت، زیرا اگر می‌خواهیم خویشتن* خود را بشناسیم، نمی‌توانیم بخشی از خود را بیرون از عشقمان رها کنیم. حداقل سه مرتبه در هر ساعت به فردی بیندیش که با تو در سفر است، کسی که آمده تا بیاموزد آنچه را که تو ناگزیر هستی بیاموزی. و زمانی که او به ذهنت آمد، این پیام را از خویشتن* خود به او بده: من تو را متبرک می‌کنم برادر، با عشقِ* خداوند*، که می‌خواهم آن را با تو سهیم گردم. زیرا می‌توانم این درسِ خجسته را یاد بگیرم که هیچ عشقی جز عشقِ خداوند و عشقِ تو، و عشقِ من، و عشقِ همگان وجود ندارد.', 'https://acim-farsi.org/workbook/lesson/127', 'https://acim-farsi.org/audio/workbook/lesson/127.mp3', 'times_per_day', '[{"kind":"times_per_day","count":2}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (128, 'این دنیا که من می‌بینم هیچ چیزی را که من می‌خواهم در خود ندارد.', 'این دنیا که من می‌بینم هیچ چیزی را که من می‌خواهم در خود ندارد.

و زمانی که فکر می‌کنی در یک جنبه یا یک تصویر از این دنیا، گونه‌ای ارزش را می‌بینی، از گذاشتنِ این زنجیر بر ذهنت خودداری کن، بلکه فقط با اطمینانی آرام به خودت بگو:
این مرا وسوسه نخواهد کرد که خودم را به تأخیر بیندازم. این دنیا که من می‌بینم هیچ چیزی را که من می‌خواهم در خود ندارد.', 'این دنیا که من می‌بینم هیچ چیزی را که من می‌خواهم در خود ندارد.

این دنیا که تو می‌بینی، هیچ چیزی را که می‌خواهی برای عرضه به تو ندارد: هیچ چیزی که تو بتوانی به نحوی از آن استفاده کنی، یا هیچ چیزی که اصلاً بتواند به شادمانیِ تو خدمت کند. این اندیشه را باور کن، و از سال‌ها فلاکت نجات می‌یابی، از ناکامی‌های بی‌شمار، و از امیدهایی که به غبار تلخِ نومیدی تبدیل می‌شوند. هر کسی فقط ناگزیر است حقیقی بودنِ این اندیشه را باور کند، اگر بخواهد این دنیا را پشت سر بگذارد و از محدودهٔ ناچیز و مقیاس‌های کوچکِ آن فراتر برود.

هر چیزی‌ که تو اینجا ارزشمند می‌دانی فقط زنجیری است که تو را به این دنیا چسبیده نگه می‌دارد، و به هیچ هدف دیگری جز این خدمت نمی‌کند. زیرا هر چیزی قطعاً به آن قصدی خدمت می‌کند که تو به آن داده‌ای، تا زمانی که تو قصد متفاوتی در آنجا ببینی. تنها قصدی که برای ذهنِ تو در این دنیا ارزش دارد، عبور کردن از آن است، بدون این که تأخیر کنی تا قدری امید بیابی، در جایی که وجود ندارد. دیگر فریب نخور! این دنیا که می‌بینی، هیچ چیزی را که تو می‌خواهی در خود ندارد.

امروز بگریز، از زنجیرهایی که بر ذهنت نهادی، آن زمان که تصور کردی رستگاری در اینجا است. زیرا تو در زمان درک کردنِ خودت، آنچه را که باارزش می‌دانی به بخشی از خود تبدیل می‌کنی. همهٔ چیزهایی که تو در حوزهٔ بینایی خود طلب می‌کنی تا ارزشت را افزون کنند، شأن تو را از خودت پنهان می‌کنند، و یک سدِ دیگر را در مقابل دری می‌سازند که تو را به آگاهیِ حقیقی از خویشتنت* رهنمون می‌شود.

نگذار هیچ چیزی که به افکارِ بدن مربوط می‌شود، پیشرفتِ تو را به سوی رستگاری به تأخیر بیندازد، و نیز اجازه نده تا وسوسهٔ این باور که این دنیا هیچ چیزی را که تو می‌خواهی در خود دارد، تو را عقب نگه دارد. هیچ چیزی برای گرامی داشتن در اینجا وجود ندارد. هیچ چیزی در اینجا ارزشِ یک لحظه تأخیر و درد را ندارد؛ یک لحظه بی‌اطمینانی و تردید. بی‌ارزش هیچ چیزی عرضه نمی‌کند. قطعیتِ ارزشمندی را نمی‌توان در بی‌ارزشی یافت.

امروز ما تمرین می‌کنیم تا همهٔ افکار در مورد ارزش‌هایی را که به این دنیا داده‌ایم، رها کنیم. ما این دنیا را از قصدهایی که برای نمودها، برای مسیرها و برای رؤیاهای آن قائل شده‌ایم، آزاد می‌کنیم. ما این دنیا را درونِ ذهنمان بدون قصد خواهیم دانست. و آن را از همهٔ آنچه آرزو داشتیم آنگونه باشد، رها می‌کنیم. اینچنین، ما زنجیرهایی را برمی‌داریم که درِ به سوی آزادی از این دنیا را مسدود می‌کنند، و به فراتر از همهٔ ارزش‌های ناچیز و هدف‌های حقیرِ آن می‌رویم.

لحظه‌ای بازایست و آرام باش، و ببین زمانی که ذهنت را از زنجیرها رها می‌کنی، و به آن اجازه می‌دهی تا به سطحی برسد که آنجا خودش را در منزل می‌یابد، تا چه اندازه بر فراز این دنیا اوج می‌گیری. ذهنت برای لحظه‌ای آزادی، سپاسگزار خواهد بود. او می‌داند که به کجا تعلق دارد. فقط بال‌های او را آزاد کن، و او در اطمینان و سرور پرواز خواهد کرد تا به قصدِ مقدسش بپیوندد. بگذار تا نزد آفریدگارش* آرام بگیرد، آنجا که به عقلانیت، آزادی و عشق بازگردانده می‌شود.

امروز سه مرتبه برای ده دقیقه به ذهنت آرامش نثار کن. و زمانی که پس از تمرین چشمان خود را می‌گشایی، دیگر برای هیچ چیزی که می‌بینی به اندازهٔ قبل ارزش قائل نخواهی شد. دیدگاه کلیِ تو به این دنیا فقط کمی دگرگون خواهد شد، هر زمانی که به ذهنت اجازه دهی از زنجیرهایش بگریزد. این دنیا جایی نیست که ذهنِ تو به آن تعلق دارد. و تو به جایی تعلق داری که ذهنت می‌خواهد باشد، و جایی که وقتی تو از این دنیا آزادش می‌کنی، به آنجا می‌رود تا آرام بگیرد. راهنمای* تو قابل اعتماد است. ذهنت را به او* بگشای. آرام باش و بیاسای.

در طول روز نیز از ذهنت محافظت کن. و زمانی که فکر می‌کنی در یک جنبه یا یک تصویر از این دنیا، گونه‌ای ارزش را می‌بینی، از گذاشتنِ این زنجیر بر ذهنت خودداری کن، بلکه فقط با اطمینانی آرام به خودت بگو: این مرا وسوسه نخواهد کرد که خودم را به تأخیر بیندازم. این دنیا که من می‌بینم هیچ چیزی را که من می‌خواهم در خود ندارد.', 'https://acim-farsi.org/workbook/lesson/128', 'https://acim-farsi.org/audio/workbook/lesson/128.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (129, 'فراتر از این دنیا، دنیایی وجود دارد که من می‌خواهم.', 'این دنیا که من می‌بینم، هیچ چیزی را که من می‌خواهم در خود ندارد. فراتر از این دنیا، دنیایی وجود دارد که من می‌خواهم.', 'فراتر از این دنیا، دنیایی وجود دارد که من می‌خواهم.

این اندیشه پیرو اندیشه‌ای است که ما دیروز با آن تمرین کردیم. تو نمی‌توانی در این ایده توقف کنی که این دنیا بی‌ارزش است. زیرا تا زمانی که نبینی چیز دیگری وجود دارد که باید آن را آرزو کرد، تو فقط افسرده خواهی شد. تأکید ما بر رها کردنِ این دنیا نیست، بلکه بر مبادله کردن آن با چیزی است که بسیار بیشتر اقناع کننده، سرشار از سرور و توانا برای عرضه کردن صلح به تو است. آیا می‌اندیشی که این دنیا می‌تواند این‌ها را به تو عرضه کند؟

شاید ارزش داشته باشد که زمان کوتاهی را دوباره در مورد ارزش این دنیا بیندیشیم. احتمالاً تو نیز خواهی پذیرفت که رها کردن همهٔ افکار در مورد ارزش چیزها در اینجا، هیچ خسارتی نیست. این دنیا که تو می‌بینی واقعاً سنگدل است، بی‌ثبات، بیرحم، بی‌توجه به تو، سریع انتقام می‌گیرد و در نفرت بدون ترحم است. این دنیا فقط می‌دهد تا سلب کند، و همه‌ی چیزهایی را که تو برای مدتی گرامی داشته‌ای از تو می‌رباید. هیچ عشقِ پایداری یافت نمی‌شود، زیرا در اینجا وجود ندارد. این دنیای زمان است، جایی که همهٔ چیزها پایان دارند.

آیا این خسارت است که به جایش دنیایی را بیابیم که در آن از دست دادن ناممکن است؛ جایی که عشق تا ابد پایدار است، نفرت نمی‌تواند وجود داشته باشد و انتقام معنایی ندارد؟ آیا این خسارت است که تو همهٔ چیزهایی را که واقعاً می‌خواهی بیابی، و بدانی که آن‌ها هیچ پایان ندارند و دقیقاً در طول زمان آنگونه باقی می‌مانند که تو همواره می‌خواستی؟ اما حتی آن‌ها سرانجام مبادله خواهند شد، با آنچه نمی‌توانیم از آن سخن بگوییم. زیرا تو از آنجا به جایی می‌روی که در آن کلمات کاملاً عاجز هستند، به درونِ سکوتی که در آن زبان به سخن گفته نمی‌شود اما دقیقاً فهم می‌شود.

ارتباط، بدونِ ابهام و واضح همچون روز، بدونِ محدودیت، جاودان باقی می‌ماند. و خود* خداوند* با فرزند* خویش* سخن می‌گوید، همانگونه که فرزندش* با او* صحبت می‌کند. زبان آنان* هیچ کلامی ندارد، زیرا آنچه ایشان* می‌گویند را نمی‌توان به نشانه تبدیل کرد. معرفت ِآنان* مستقیم است و به تمامی تسهیم می‌شود و به تمامی واحد است. چقدر تو از این دور هستی که هنوز به این دنیا چسبیده‌ای. و با این حال چقدر نزدیک هستی، زمانی که این دنیا را با دنیایی که می‌خواهی مبادله می‌کنی.

اینک گامِ آخر قطعی است؛ اینک تو فقط به اندازهٔ یک لحظه با بی‌زمانی فاصله داری. اینجا تو فقط می‌توانی به پیش بنگری و هرگز به عقب نگاه نکنی تا دنیایی را ببینی که آن را نمی‌خواهی. اینجا دنیایی است که می‌آید تا جایگزینِ آن شود، همچنان که تو ذهنت را از چیزهای کوچکی که این دنیا پیش می‌کشد تا زندانت کند، رها می‌کنی. به آنها بها نده، و ناپدید خواهند شد. اگر آنها را بپروری، به نظرت واقعی خواهند رسید.

این انتخاب چنین است. تو ممکن است چه چیزی را از دست بدهی اگر انتخاب کنی که به «هیچ چیز» بها ندهی؟ این دنیا هیچ چیزی را که تو واقعاً می‌خواهی در خودش ندارد، اما چیزی را که تو به جای این انتخاب می‌کنی حقیقتاً می‌خواهی! بگذار تا امروز به تو عطا شود. آن دنیا فقط منتظر تو است که انتخابش کنی، تا جایگزین همه‌ی چیزهایی شود که تو می‌طلبی، اما نمی‌خواهی.

مصمم بودن خود را برای ایجاد این تغییر، ده دقیقه در صبح و در شب و نیز یک نوبت در این بین تمرین کن. اینگونه آغاز کن: فراتر این دنیا، دنیایی وجود دارد که من می‌خواهم. من انتخاب می‌کنم که آن دنیا را به جای این دنیا ببینم، زیرا در اینجا هیچ چیزی وجود ندارد که من واقعاً می‌خواهم. سپس چشمانت را به روی این دنیایی که می‌بینی ببند، و در تاریکی و سکوت، تماشا کن که نورهایی که به این دنیا تعلق ندارند یکی یکی روشن می‌شوند، تا آنجا که آغاز شدنِ یکی با پایانِ دیگری معنا می‌بازد و آنها با هم آمیخته و یکی می‌شوند.

امروز نورهای بهشت* به سوی تو خم می‌شوند، تا بر پلک‌های تو بتابند زمانی که در ورای این دنیای تاریکی آرام می‌گیری. در اینجا نوری است که چشمان تو نمی‌تواند آن را مشاهده کند. اما ذهن تو می‌تواند آن را به وضوح ببیند، و می‌تواند آن را بفهمد. امروز، روزی از فیض به تو عطا شده است، و ما شکرگزار هستیم. در این روز ما متوجه می‌شویم که آنچه تو می‌ترسیدی از دست بدهی، خودش خسارت بود.

این زمان ما واقعاً می‌فهمیم که هیچ خسارتی وجود ندارد. زیرا سرانجام، ضدِ آن را دیده‌ایم. و شکرگزار هستیم که این انتخاب انجام می‌شود. هر ساعت انتخاب خود را به یاد بیاور، و لحظه‌ای را صرف کن تا انتخابت را تصدیق کنی، با کنار گذاشتنِ هر فکری که داری، و درنگ مختصر فقط بر این: این دنیا که من می‌بینم، هیچ چیزی را که من می‌خواهم در خود ندارد. فراتر از این دنیا، دنیایی وجود دارد که من می‌خواهم.', 'https://acim-farsi.org/workbook/lesson/129', 'https://acim-farsi.org/audio/workbook/lesson/129.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (130, 'ناممکن است که بتوان دو دنیا را دید.', 'ناممکن است که بتوان دو دنیا را دید. باشد تا من قدرتی را بپذیرم که خداوند* به من عطا می‌کند و هیچ ارزشی را در این دنیا نبینم، تا بتوانم آزادی و رستگاریِ خودم را بیابم.

هر زمان وسوسه پدیدار شد، با گفتن این جمله آن را کنار بگذار:
ناممکن است که بتوان دو دنیا را دید. من آزادی و رستگاریِ خودم را می‌طلبم، و این بخشی از آنچه که من می‌خواهم نیست.', 'ناممکن است که بتوان دو دنیا را دید.

ادراک، یکپارچه است. چیزی که تو می‌بینی تفکرت را بازتاب می‌دهد. و تفکر تو، فقط انتخاب تو را از آنچه که می‌خواهی ببینی، بازتاب می‌دهد. ارزش‌های تو این را تعیین می‌کنند زیرا آنچه که ارزشمند می‌دانی، ناگزیر هستی دیدنِ آن را بخواهی، با این باور که آنچه می‌بینی واقعاً وجود دارد. هیچ‌کس نمی‌تواند دنیایی را ببیند که ذهنش برای آن ارزش قائل نشده است. و هر کسی قطعاً به چیزی نظر می‌کند که باور دارد خواهانِ آن است.

اما چه کسی می‌تواند واقعاً همزمان نفرت و عشق بورزد؟ چه کسی می‌تواند به چیزی میل داشته باشد که نمی‌خواهد واقعیت داشته باشد؟ و چه کسی می‌تواند انتخاب کند دنیایی را ببیند که از آن می‌ترسد؟ ترس ناگزیر است که کور کند، زیرا این اسلحهٔ ترس است: آنچه که از دیدنش می‌ترسی، نمی‌توانی ببینی. اینچنین عشق و ادراک دست در دستِ هم می‌روند، اما ترس آنچه را که وجود دارد، در تاریکی پنهان می‌کند.

پس آنگاه ترس چه چیزی را می‌تواند بر این دنیا فرافکند؟ چه چیزی را می‌توان در تاریکی دید که واقعی باشد؟ ترس، حقیقت را پسِ خود پنهان می‌کند، و آنچه باقی می‌ماند فقط تخیلات است. اما چه چیز می‌تواند در تخیلاتِ کورِ زادهٔ وحشت، واقعی باشد؟ چه چیزی را که ممکن است بخواهی، به تو نشان می‌دهد؟ چه چیزی را ممکن است آرزو کنی، در چنین رؤیایی حفظ ‌گردد؟

ترس، همهٔ آنچه را که تو می‌پنداری که می‌بینی، ساخته است. همهٔ جدایی، همهٔ تمایزها، و این پرشمار تفاوت‌ها که تو باور داری این دنیا را می‌سازند. این‌ها وجود ندارند. دشمنِ عشق این‌ها را ساخته است. اما عشق نمی‌تواند هیچ دشمنی داشته باشد. پس این‌ها هیچ علت، هیچ موجودیت و هیچ معلولی ندارند. می‌توان به آن‌ها ارزش داد، اما غیرواقعی باقی می‌مانند. آن‌ها می‌توانند طلب شوند، اما نمی‌توانند یافت شوند. امروز ما آن‌ها را طلب نمی‌کنیم، و نیز این روز را برای طلب کردنِ آنچه که نمی‌توان یافت، تلف نمی‌کنیم.

ناممکن است بتوان دو دنیا را دید که هیچگونه تداخلی با هم ندارند. اگر یکی را بطلبی، دیگری ناپدید می‌گردد. فقط یکی می‌ماند. این دو دنیا، دامنه‌ای از انتخاب هستند که تصمیمِ تو نمی‌تواند به فراتر از آن برود. واقعی و غیرواقعی به تمامی اینجا هستند تا تو بین آن‌ها انتخاب کنی، و هیچ چیزی بیش از این وجود ندارد.

امروز تلاش نخواهیم کرد که سازشکار باشیم، در حالی که سازشکاری ممکن نیست. این دنیا که می‌بینی، گواهِ این است که تو پیشاپیش یک انتخاب تمام عیار بر ضد این اندیشه انجام داده‌ای. آنچه امروز می‌خواهیم بیاموزیم، بیش از این درس است که تو نمی‌توانی دو دنیا را ببینی. این را نیز فرا می‌گیریم که دنیایی که تو می‌بینی، از آن نقطه نظری که تو مشاهده‌اش می‌کنی کاملاً یکپارچه است. تمامیِ آن یک قطعه است زیرا از یک احساس سرچشمه می‌گیرد، و سرچشمهٔ خود را در همهٔ چیزهایی که تو می‌بینی بازتاب می‌دهد.

ما امروز در شش نوبت، با سپاس و قدردانی، شادمانه پنج دقیقه را برای این اندیشه صرف می‌کنیم که به همهٔ سازشکاری‌ها و تردیدها پایان می‌دهد، و فراتر از همه‌ی آن‌ها یکجا می‌رویم. ما هزار تمایزِ بی‌معنا انجام نخواهیم داد، و نیز تلاش نخواهیم کرد که بخشِ کوچکی از غیرواقعی را با خود بیاوریم، همچنان که ذهن خود را فقط برای یافتنِ آنچه که حقیقی است وقف می‌کنیم.

جستجو برای آن دنیای دیگر را با تقاضای قدرتی فراتر از قدرتِ خود آغاز کن، و تشخیص دادنِ این که تو طالبِ چه هستی. تو اوهام را نمی‌خواهی. و تو به این تمرین‌های پنج دقیقه‌ای می‌آیی در حالی که دستان خود را از همه‌ی گنجینه‌های ناچیزِ این دنیا خالی می‌کنی. صبر کن تا خداوند* یاری‌ات کند، در حالی که می‌گویی: ناممکن است که بتوان دو دنیا را دید. باشد تا من قدرتی را بپذیرم که خداوند* به من عطا می‌کند و هیچ ارزشی را در این دنیا نبینم، تا بتوانم آزادی و رستگاریِ خودم را بیابم.

خداوند* حضور خواهد داشت. زیرا تو آن قدرتِ شکست‌ناپذیر عظیم را فراخوانده‌ای که این گام غول‌آسا را با قدردانی همراه با تو بر خواهد داشت. تو قطعاً سپاسِ او* را از خودت که به صورتِ ادراکی قابل لمس و به صورتِ حقیقت ابراز می‌شود، دریافت خواهی کرد. تو به آنچه مشاهده خواهی کرد تردید نخواهی داشت، زیرا اگرچه ادراک است، از آن نوع مشاهده نیست که تا حال فقط با چشمانِ خود دیده‌ای. و تو خواهی دانست که با انجامِ این انتخاب، قدرتِ خداوند* از تو حمایت می‌کند.

امروز به سادگی از وسوسه‌هایی که پیش می‌آید دوری کن، صرفاً با به یاد آوردن حدودِ انتخابت. غیرواقعی یا واقعی، غیرحقیقی یا حقیقی آن چیزی است که تو می‌بینی و فقط همین را می‌بینی. ادراک با انتخابِ تو یکپارچه است، و یا دوزخ یا بهشت*، یکی نصیب تو می‌شود.

کافی است بخش کوچکی از جهنم را واقعی بدانی، و در این صورت چشمانت را لعنت و دیدنت را نفرین می‌کنی، و آنچه مشاهده خواهی کرد در حقیقت جهنم خواهد بود. اما رهاییِ بهشت* همچنان در دامنهٔ انتخابِ تو باقی می‌ماند، تا جایگزینِ همهٔ آن چیزی بشود که دوزخ می‌خواهد به تو نشان بدهد. همهٔ آنچه که نیاز داری به هر بخش از دوزخ بگویی، هر شکلی که به خود بگیرد، به سادگی این است: ناممکن است که بتوان دو دنیا را دید. من آزادی و رستگاریِ خودم را می‌طلبم، و این بخشی از آنچه که من می‌خواهم نیست.', 'https://acim-farsi.org/workbook/lesson/130', 'https://acim-farsi.org/audio/workbook/lesson/130.mp3', 'times_per_day', '[{"kind":"times_per_day","count":6}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (131, 'هر کس که طالب رسیدن به حقیقت است، نمی‌تواند شکست بخورد.', 'من می‌طلبم که دنیای متفاوتی ببینم، و اندیشه‌هایی متفاوت از آن‌هایی که ساخته ام بیاندیشم. من به تنهایی دنیایی را که می‌طلبم نساخته‌ام، افکاری را که می‌خواهم بیاندیشم از آن خود من نیستند.

و بارها به یاد بیاور:
امروز من همهٔ آنچه را که می‌خواهم می‌جویم و‌ می‌یابم.
تنها قصد من، آن را به من عرضه می‌کند.
هر کس که می‌طلبد به حقیقت برسد هرگز نمی‌تواند شکست بخورد.', 'هر کس که طالب رسیدن به حقیقت است، نمی‌تواند شکست بخورد.

شکست برای تو زمانی رخ می‌دهد که در جستجوی هدف‌هایی باشی که نمی‌توان به آن‌ها دست یافت. تو به دنبال یافتن پایداری در آن چیزی هستی که ناپایدار است، به دنبال عشق در جایی که هیچ عشقی وجود ندارد، به دنبال امنیت در میانهٔ خطر؛ و به دنبال فناناپذیری در درون تاریکیِ رؤیای مرگ. چه کسی می‌تواند موفق شود در حالیکه تضاد مبنای جستجوی اوست و همچنین مبنای مکانی است که او به آنجا آمده است تا ثبات را بیابد؟

هدف‌هایی که بی‌معنا هستند به دست نمی‌آیند. هیچ راهی برای رسیدن به آن‌ها وجود ندارد، زیرا وسایلی که با آن‌ها برای رسیدن به آن هدف‌ها می‌کوشی همانند آن‌ها بی‌معنا هستند. چه کسی می‌تواند این ابزارهای احمقانه را بکار برد و امیدوار باشد که از طریق آن‌ها به منفعتی برسد؟ آن‌ها به کجا می‌توانند هدایت کنند؟ و به چه چیزی می‌توانند دست یابند که امیدی برای واقعی بودن پیشکش کند؟ دنبال کردن تصورات به مرگ هدایت می‌کند زیرا آن جستجو برای نیستی است، و در حالیکه در جستجوی زندگی هستی مرگ را می‌طلبی. تو به دنبال سلامت و امنیت هستی در حالیکه در قلبت برای خطر و حفاظت از رؤیای کوچکی که ساخته‌ای، دعا می‌کنی.

با این وجود اینجا جستجو ناگزیر است. برای این تو آمدی، و مطمئنا آنچه را که برایش آمدی انجام خواهی داد. اما دنیا نمی‌تواند هدفی را که برای آن جستجو می‌کنی دیکته کند، مگر اینکه تو به آن قدرت بدهی تا چنین کند. در غیر این صورت تو هنوز آزاد هستی تا هدفی را انتخاب کنی که فراتر از دنیا و هر اندیشهٔ دنیوی قرار دارد، هدفی که از ایده‌ای ترک شده اما به یاد آورده شده، کهن و اما نوین به سمت تو می‌آید؛ بازتابی از یک میراث فراموش شده، اما دربردارندهٔ هر آنچه که واقعاً می‌خواهی.

خوشحال باش که باید جستجو کنی. همچنین خوشحال باش که می‌آموزی در جستجوی بهشت* هستی، و باید هدفی را که واقعاً می‌خواهی پیدا کنی. هیچ‌کس در خواستن این هدف و سرانجام رسیدن به آن، نمی‌تواند شکست بخورد. فرزند* خداوند* نمی‌تواند بیهوده جستجو کند، هرچند بکوشد که تأخیر ایجاد کند، خودش را فریب دهد، و فکر کند که دوزخ است که او می‌جوید. زمانی که او در اشتباه است، تصحیح را می‌یابد. وقتی که سرگردان می‌شود، به وظیفهٔ مقرر شده‌اش بازگردانده و هدایت می‌شود.

هیچ‌کس در دوزخ نمی‌ماند، زیرا هیچ‌کس نمی‌تواند آفریدگار* خود را ترک کند، و نیز نمی‌تواند بر عشق کامل، بی‌زمان، و تغییرناپذیر او* اثر بگذارد. تو بهشت* را خواهی یافت. جز این هر چیزی‌ که جستجو می‌کنی محو خواهد شد. اما نه به این دلیل که از تو گرفته شده باشد. آن از بین می‌رود زیرا آن را نمی‌خواهی. همانطور که خداوند* تو را در بی‌گناهی آفرید، تو مطمئناً به آن هدفی که واقعاً می‌خواهی، خواهی رسید،

چرا در انتظار بهشت بمانی؟ بهشت امروز اینجا است. زمان، وهم عظیم است، یا گذشته است یا در آینده است. اما این گونه نمی‌تواند باشد، اگر بهشت* آنجایی هست که خداوند* اراده کرده که فرزندش* آنجا باشد. ارادهٔ* خداوند* چگونه‌ می‌تواند در گذشته باشد یا در انتظار رخ دادن؟ آنچه که او* اراده می‌کند اکنون است، بدون هیچ گذشته‌ای و تماماً بدون آینده. ارادهٔ* خداوند* بسیار متفاوت از زمان است به همان اندازه که یک شمع کوچک از یک ستاره در دوردست، یا آنچه که انتخاب کردی از آنچه که ‌واقعا می‌خواهی، متفاوت است.

بهشت* به عنوان یگانه جایگزین تو باقی می‌ماند، جایگزینی برای این دنیای غریب که ساخته‌ای و همهٔ طریق‌های آن؛ الگوهای متغیر آن و هدف‌های نامطمئن آن، لذت‌های دردناک آن و شادمانی‌های غم‌انگیزش. خداوند* تضادها را نساخت. آنچه که وجود خود را انکار می‌کند و به خودش حمله می‌کند از خداوند* نیست. او دو ذهن را نساخت، با بهشت* به عنوان اثر شادمانهٔ یکی و زمین به عنوان نتیجهٔ تأسف‌بار دیگری که از هر جهت ضد بهشت* است.

خداوند* از تعارض رنج نمی‌برد. و نیز آفرینش* او* به دو تکه تقسیم نشده است. چگونه ممکن بود فرزندش* می‌توانست در جهنم باشد در حالیکه خود* خداوند* او را در بهشت* قرار داده است؟ آیا او می‌توانست آنچه را که ارادهٔ* ابدی* به او داده تا منزلش باشد را از دست بدهد؟ بگذارید دیگر تلاش نکنیم تا ارادهٔ بیگانه‌ای را بر تنها قصد خداوند* تحمیل کنیم. او* اینجا است زیرا او* اراده می‌کند که اینجا باشد، و آنچه که او* اراده می‌کند اکنون حاضر است، ورای دسترسی زمان.

امروز یک تضاد را به جای حقیقت انتخاب نخواهیم کرد. فرزند* خداوند* چگونه می‌تواند برای غصب ارادهٔ* خداوند* زمانی بسازد؟ او اینگونه خودش را انکار می‌کند و با چیزی ضدیت می‌کند که هیچ متضادی ندارد. او می‌پندارد که دوزخی ساخته که ضد بهشت* است، و باور دارد که در چیزی که وجود ندارد، سکونت می‌کند، در حالیکه بهشت* مکانی است او نمی‌تواند پیدا کند.

امروز پندارهای احمقانه مانند این را رها کن‌، و به جای آن ذهنت را به سمت ایده‌های درست هدایت کن. هرکس که می‌طلبد به حقیقت برسد هرگز نمی‌تواند شکست بخورد، و امروز ما حقیقت را می‌طلبیم تا به آن برسیم. امروز سه بار در روز ده دقیقه را به رسیدن به این هدف اختصاص می‌دهیم، و می‌طلبیم که طلوع دنیای حقیقی را ببینیم که جایگزین تصویرهای احمقانه‌ای می‌شود که آنها را عزیز می‌داریم، همراه با ایده‌های درست که طلوع می‌کنند به جای پندارهایی که هیچ معنا، اثر، و نیز هیچ سرچشمه و استحکامی در حقیقت ندارند.

با شروع زمانهای تمرین خود این را تصدیق می‌کنیم. با این آغاز کن: من می‌طلبم که دنیای متفاوتی ببینم، و اندیشه‌هایی متفاوت از آن‌هایی که ساخته ام بیاندیشم. من به تنهایی دنیایی را که می‌طلبم نساخته‌ام، افکاری را که می‌خواهم بیاندیشم از آن خود من نیستند. برای چندین دقیقه، اگرچه چشمانت بسته‌اند،ذهن خود را مشاهده کن‌ و این دنیای بی‌معنا را که می‌پنداری واقعی است ببین. و نیز افکاری را مرور کن که با چنین دنیایی سازگارند و فکر می‌کنی که درست هستند. سپس بگذار بروند، و در زیر آن‌ها در ژرفا به مکان مقدسی برو که آن افکار نمی‌توانند وارد شوند. در زیر آن‌ها در ذهن تو دری هست، که تو نتوانستی آن را کاملا قفل کنی تا آنچه را که در آنسو قرار دارد پنهان کند.

آن در را جستجو کن و بیاب. اما پیش از آنکه تلاش کنی‌ که آن در را باز کنی، به خودت یادآوری کن که هرکس که می‌طلبد به حقیقت برسد نمی‌تواند شکست بخورد. و این همان چیزی است که امروز درخواست می‌کنی. اینک هیچ چیزی جز این هیچ معنایی ندارد؛ به هیچ هدف دیگری بها داده نمی‌شود و طلبیده نمی‌شود، تو هیچ چیزی را که قبل از این در است واقعاً نمی‌خواهی، و تنها آنچه را که آن‌سوی آن قرار دارد را می‌طلبی.

دستانت را دراز کن و بنگر که چگونه به آسانی این در می‌چرخد و باز می‌شود، با یگانه قصد تو برای رفتن به آن‌سوی آن. فرشتگان طریق را نورانی می‌کنند، بگونه‌ای که همهٔ تاریکی ناپدید می‌شود و تو در نوری چنان روشن و شفاف می‌ایستی که می‌توانی همهٔ چیزهایی را که می‌بینی درک کنی. ممکن است لحظه‌ای ناچیز از شگفتی باعث شود تا درنگ کنی، پیش از آنکه دنیایی را که در مقابلت می‌بینی در نور بازتاب دهندهٔ حقیقت درک کنی، حقیقتی که می‌شناختی و در سرگردانی درون رؤیاها کاملا آن را فراموش نکردی.

تو امروز نمی‌توانی شکست بخوری. با تو آن روح* گام بر می‌دارد که بهشت* آن را فرستاده است، تا تو روزی به این در نزدیک شوی، و از طریق کمک او* بدون زحمت به ورای این در به سوی نور بروی. امروز آن روز فرا رسیده است. امروز خداوند* به وعده‌ی دیرین خود به فرزندش* وفا می‌کند، همانطور که فرزندش* وعدهٔ خود به او* را بیاد می‌آورد. این روز، روز شادمانی است، زیرا به زمان و مکان تعیین شده‌ای می‌رسیم که تو هدف همهٔ جستجوهای خود را در اینجا، و نیز هدف همهٔ جستجوهای دنیا را خواهی یافت، که با هم به پایان می‌رسند، هنگامی که تو به آن‌سوی این در بگذری.

بارها بیاد بیاور که امروز باید زمانی برای شادمانی ویژه، خودداری از افکار پریشان و تأسف خوردن‌های بی‌معنا باشد. زمان رستگاری فرا رسیده است. امروز توسط خود* بهشت* مقرر شده است که زمان فیض برای تو و برای دنیا باشد. اگر این واقعیت شادمانه را فراموش کردی، اینگونه به خودت یادآوری کن: امروز من همهٔ آنچه را که می‌خواهم می‌جویم و‌ می‌یابم. تنها قصد من، آن را به من عرضه می‌کند. هر کس که می‌طلبد به حقیقت برسد هرگز نمی‌تواند شکست بخورد.', 'https://acim-farsi.org/workbook/lesson/131', 'https://acim-farsi.org/audio/workbook/lesson/131.mp3', 'times_per_day', '[{"kind":"times_per_day","count":3}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (132, 'من دنیا را از همهٔ چیزهایی که می‌پنداشتم هست آزاد می‌کنم.', 'من دنیا را از هر آنچه که می‌پنداشتم هست رهایی می‌بخشم و به جای آن واقعیت خودم را انتخاب می‌کنم.

عبارت بالا را در طول روز و هر زمان که وسوسه شدی بگو.', 'من دنیا را از همهٔ چیزهایی که می‌پنداشتم هست آزاد می‌کنم.

چه چیز دنیا را در زنجیرها نگه می‌دارد جز باورهای تو؟ و چه چیزی می‌تواند دنیا را نجات دهد جز خویشتن* تو؟ براستی که باور قدرتمند است. افکاری که نگه می‌داری نیرومند هستند و اوهام به اندازهٔ حقیقت در اثرات خود قوی هستند‌. یک دیوانه فکر می‌کند که دنیایی که می‌بیند واقعی است و دربارهٔ آن تردید نمی‌کند. و نیز نمی توان او را با زیر سئوال بردن اثرات افکارش تکان داد. تنها زمانی که سرچشمهٔ آن‌ها مورد پرسش قرار می‌گیرد است که امید به آزادی سرانجام برای او‌ فرا می‌رسد.

با این وجود رستگاری به آسانی به انجام می‌رسد، زیرا هر کسی آزاد است تا ذهن خود را تغییر دهد و همراه با آن همهٔ افکارش تغییر می‌کنند. اینک سرچشمهٔ افکار تغییر داده شده است، زیرا تغییر ذهن به این معناست که تو سرچشمهٔ همه‌ی ایده‌هایی که می‌اندیشی یا تاکنون می‌اندیشیده‌ای یا خواهی اندیشید را تغییر داده‌ای. تو گذشته را از آنچه پیش‌تر می‌پنداشتی آزاد می‌کنی. تو آینده را از همه‌ی افکار دیرینِ جستجوی آنچه نمی‌خواهی بیابی، آزاد می‌کنی.

اینک زمان اکنون، به عنوان تنها زمان موجود باقی می‌ماند. اینجا در زمانِ اکنون دنیا آزاد می‌شود. زیرا وقتی که اجازه می‌دهی گذشته برداشته شود و آینده را از ترس‌های دیرین خود رها می‌کنی، رهایی را می‌یابی و آن را به دنیا می‌دهی. تو دنیا را با همه‌ی ترس‌ها و تردیدها و بیچارگی‌ها و درد و اشک خود به بردگی گرفته‌ای و همه‌ی غم‌های تو بر آن فشار می‌آورند، و دنیا را زندانی باورهایت نگه می‌دارند. مرگ همه جا به آن ضربه می‌زند زیرا تو پندارهای تلخ مرگ را درون ذهنت نگه می‌داری.

دنیا به خودی خود هیچ است. ذهن تو باید به آن معنا بدهد. و آنچه در آن مشاهده می‌کنی، خواسته‌های تو هستند که در آن به انجام می‌رسند تا تو به آنها نگاه کنی و بپنداری که واقعی هستند. شاید می‌پنداری که تو این دنیا را نساخته‌ای، و برخلاف میل خود به دنیایی که از پیش ساخته شده آمده‌ای، دنیایی که چندان منتظر نبود تا افکار تو به آن معنا بدهند‌. ولی در حقیقت زمانی که تو آمدی چیزی که دقیقاً به دنبالش بودی را یافتی.

هیچ دنیایی جدا از آنچه تو آرزو کرده‌ای وجود ندارد، و در این رهایی قطعی تو نهفته است. فقط ذهنت را دربارهٔ آنچه می‌خواهی ببینی تغییر بده و آنگاه همهٔ دنیا مطابق آن تغییر خواهد کرد. ایده‌ها سرچشمهٔ خود را ترک نمی‌کنند. این موضوع اصلی، اغلب در متن دوره بیان شده است، و اگر می‌خواهی درس امروز را بفهمی باید در ذهن تثبیت شود. این تکبر نیست که به تو می‌گوید این دنیا را که می‌بینی تو ساخته‌ای، و آن با تغییر ذهنیت تو تغییر می‌کند.

اما این تکبر است که استدلال می‌کند تو به دنیایی کاملاً جدا از خودت آمده‌ای، تاثیرناپذیر از آنچه می‌اندیشی، کاملا جدا از آنچه بتوانی دربارهٔ چیستی آن بیاندیشی. هیچ دنیایی وجود ندارد! این اندیشهٔ اصلی است که دوره می‌کوشد آموزش دهد. همه آمادهٔ پذیرش آن نیستند، و هر کس باید تا آنجا که می‌تواند به خود اجازهٔ هدایت شدن در مسیر به سوی حقیقت را بدهد، پیش برود. گاه برمی‌گردد و باز بیشتر پیش می‌رود، یا شاید مدتی به عقب گام بردارد و سپس دوباره بر‌گردد.

اما شفا موهبت کسانی است که آماده هستند تا بیاموزند که هیچ دنیایی وجود ندارد، و اکنون می‌توانند این درس را بپذیرند. آمادگی آن‌ها، این درس را در شکلی که آن را بتوانند درک کنند و تشخیص دهند برای آن‌ها به ارمغان خواهد آورد. برخی آن را ناگهان در لحظهٔ مرگ می‌بینند، و بر می‌خیزند تا آن را آموزش دهند. دیگران آن را در تجربه‌ای که از این دنیا نیست می‌یابند، که به آن‌ها نشان می‌دهد که این دنیا وجود ندارد زیرا آنچه آن‌ها مشاهده می‌کنند باید حقیقت باشد، و با این حال آشکارا با این دنیا در تضاد است.

برخی آن را در این دورهٔ آموزشی و در تمرین‌هایی که امروز انجام می‌دهیم خواهند یافت. ایده امروز درست است زیرا دنیا وجود ندارد. و اگر دنیا براستی تصور خودت است، می‌توانی با تغییر همهٔ افکاری که به آن این ظواهر را داد، آن را از همهٔ آنچه که می‌پنداشتی هست آزاد کنی. بیماران شفا می‌یابند اگر همهٔ افکار بیماری را کنار بگذاری، و مردگان برمی‌خیزند وقتی که اجازه بدهی اندیشه‌های زندگی جایگزین همهٔ پندارهایی شوند که تا بحال از مرگ نگه داشته‌ای.

درسی که پیش از این یکبار تکرار شده بود اینک دوباره باید تأکید شود، زیرا آن در بردارندهٔ بنیان محکم برای ایدهٔ امروز است. تو آنگونه هستی که خداوند* تو را آفرید. هیچ مکانی وجود ندارد که در آن تو بتوانی رنج ببری و هیچ زمانی وجود ندارد که بتواند در وضعیت ابدی تو تغییر ایجاد کند. چگونه یک دنیای مکان و زمان می‌تواند وجود داشته باشد، اگر تو آنگونه مانده‌ای که خداوند* تو را آفرید؟

درس امروز چیست جز روش دیگری برای گفتن اینکه شناختن خویشتن* تو رستگاری دنیا است؟ آزاد ساختن دنیا از هر گونه درد فقط تغییر ذهنت دربارهٔ خودت است. هیچ دنیایی جدا از ایده‌های تو وجود ندارد زیرا ایده‌ها سرچشمهٔ خود را ترک نمی‌کنند، و تو دنیا را درون ذهنت در فکر نگهداری می‌کنی.

اما اگر تو آنگونه هستی که خداوند* تو را آفرید، آنگاه تو نمی‌توانی جدا از او* بیاندیشی، و نیز نمی‌توانی چیزی بسازی که بی‌زمانی و عشق* او* را تسهیم نمی‌کند. آیا این‌ها در این دنیا که می‌بینی ذاتاً وجود دارند؟ آیا این دنیا همانند او* می‌آفریند؟ تا زمانی که چنین نکند، واقعی نیست و نمی‌تواند هرگز واقعی باشد. اگر تو واقعی هستی، دنیایی که می‌بینی باطل است، زیرا آفرینش خداوند در همه جهات ناهمسان با این دنیا است. و همانگونه که اندیشهٔ* او* بود که تو را آفرید، دنیا را نیز افکار تو ساخت و افکار تو نیر باید آن را آزاد کند، تا بتوانی اندیشه‌هایی را که با خداوند* سهیم هستی بشناسی.

دنیا را رهایی بخش! آفرینش‌های واقعی تو در انتظار این هستند تا به تو پدر* بودن را عطا کنند، نه در اوهام، بلکه همانند خداوند* در حقیقت. خداوند* پدر* بودن خود را با تویی که فرزندش* هستی سهیم می‌شود، زیرا خداوند* تفاوتی میان آنچه خودش* است و آنچه که هنوز خودش* می‌باشد، قائل نیست. آنچه که او* می‌آفریند از او* جدا نیست و جایی نیست که خداوند* به پایان رسد، و فرزندش* به عنوان چیزی جدا از او* آغاز شود.

هیچ دنیایی وجود ندارد زیرا آن اندیشه‌ای جدا از خداوند* است، که ساخته شده تا پدر* و فرزندش* را جدا کند، و بخشی از خود* خداوند* را از او جدا کند و اینگونه تمامیت او* را از بین ببرد. آیا دنیایی که از این ایده سرچشمه می‌گیرد می‌تواند واقعی باشد؟ آیا می تواند در جایی باشد؟ اوهام را انکار کن، فقط حقیقت را بپذیر. انکار کن که سایه‌ای هستی که برای مدتی کوتاه بر روی دنیایی در حال مرگ نهاده شده است. ذهنت را رهایی بخش، و آنگاه به دنیایی آزاد شده نظر خواهی کرد.

امروز قصد ما آزاد کردن دنیا از همهٔ افکار بیهوده‌ای است که تا کنون درباره‌ی آن داشته‌ایم، و دربارهٔ همه‌ی چیزهای زنده‌ای که در آن می‌بینیم. آن‌ها ‌نمی‌توانند آنجا باشند. ما نیز نمی‌توانیم آنجا باشیم. زیرا ما به همراه آنها، در منزلی هستیم که پدرمان* برای ما مقرر کرده است. و ما که همانگونه‌ هستیم که او* ما را آفرید می‌خواهیم در این روز دنیا را از تک تک اوهام خود آزاد کنیم، تا بتوانیم آزاد شویم.

تمرین پانزده دقیقه‌ای را که امروز دوبار‌ انجام می‌دهیم با این آغاز کن: من که همانگونه مانده‌ام که خداوند* مرا آفرید، می‌خواهم دنیا را از هر آنچه که می‌پنداشتم بود رهایی بخشم. زیرا من واقعی هستم و این دنیا واقعی نیست، و من می‌خواهم واقعیت خودم را بدانم. آنگاه صرفاً آرام بگیر و هشیار باش بی هیچ فشاری، و اجازه بده ذهنت در سکون تغییر داده شود تا دنیا به همراه تو آزاد شود.

تو نیاز به فهمیدن نداری که با فرستادن این افکار برای متبرک کردن دنیا، شفا بسوی بسیاری از برادران در دورترین نقاط دنیا می‌آید، همانطور که شامل کسانی می‌شود که در نزدیکی ‌خود می‌بینی. اما تو رهایی خود را احساس خواهی کرد، اگر چه ممکن است هنوز بطور کامل درک نکنی که تو هرگز نمی‌توانستی به تنهایی رهایی یابی.

در طول روز، آزادی را که از طریق ایده‌های تو به همهٔ دنیا فرستاده شده افزایش بده، و هرگاه وسوسه شدی که قدرت تغییر سادهٔ ذهنت را انکار کنی، بگو: من دنیا را از هر آنچه که می‌پنداشتم هست رهایی می‌بخشم و به جای آن واقعیت خودم را انتخاب می‌کنم.', 'https://acim-farsi.org/workbook/lesson/132', 'https://acim-farsi.org/audio/workbook/lesson/132.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (133, 'من برای آنچه که بی‌ارزش است ارزش قائل نخواهم شد.', 'من برای آنچه که بی‌ارزش است ارزش قائل نخواهم شد، زیرا آنچه ارزشمند است به من تعلق دارد.', 'من برای آنچه که بی‌ارزش است ارزش قائل نخواهم شد.

گاهی در آموزش دادن سودمند است که دانش‌آموز را به جنبه‌های عملی بازگردانیم، بویژه پس از آنکه تو آنچه را که به نظر تئوری و کاملا دور از چیزی است که دانش آموز پیشاپیش آموخته را از سر گذرانده باشی. امروز ما این کار را انجام خواهیم داد. ما از ایده‌های متعالی و جهان‌شمول سخن نخواهیم گفت بلکه به منفعت‌ها برای تو می‌پردازیم.

تو درباره‌ی زندگی بسیار نمی‌پرسی، جز اندکی. هنگامی که اجازه می‌دهی که ذهنت به سمت دغدغه‌های بدن کشیده شود، به سمت چیزهایی که می‌خری، به سمت بزرگی آنگونه که دنیا به آن بها می‌دهد، تو اندوه را می‌طلبی، نه شادمانی را. این دوره نمی‌کوشد که اندک چیزی را که داری از تو بگیرد. سعی نمی‌کند تا ایده‌های آرمانگرایانه را جایگزین رضایتمندی‌هایی کند که دنیا در بر دارد. هیچ رضایتمندی در این دنیا وجود ندارد.

امروز ما آن معیار واقعی را معرفی‌ می‌کنیم که با آن همه‌ی چیزهایی که فکر می‌کنی می‌خواهی آزموده می‌شوند. اگر این نیازمندیهای معتبر را برآورده نکنند، آنها به هیچ روی ارزش خواستن ندارند، زیرا آنها فقط می‌توانند جایگزین چیزی باشند که بیشتر عرضه می‌کند. قانون‌هایی که بر انتخاب حکومت می‌کنند را تو نمی‌توانی بسازی، همانطور که نمی‌توانی جایگزین‌هایی را بسازی که از میان آنها انتخاب می‌کنی. تو می‌توانی انتخاب کردن را انجام دهی؛ در واقع، باید انجام دهی. اما عاقلانه است که هنگام انتخاب کردن، قانون‌هایی که به حرکت درآورده‌ای را بیاموزی و این که از میان چه جایگزین‌هایی انتخاب می‌کنی.

ما پیشاپیش تأکید کرده‌ایم که تنها دو انتخاب وجود دارد، اگرچه به نظر رسد انتخاب‌های بسیاری وجود دارند. بازه‌ی انتخاب مقرر شده است و ما نمی‌توانیم این را تغییر دهیم. برای تو ناسخاوتمندانه‌ترین کار این است که اجازه داده شود گزینه‌ها نامحدود باشند، و اینگونه انتخاب نهایی تو به تأخیر افتد تا زمانی که تو همه‌ی آن‌ گزینه‌ها را در زمان بررسی کرده باشی؛ و بطور واضح به آن جایی نرسیده باشی که تنها یک انتخاب برای انجام دادن مانده باشد.

قانون مهربانانه و مرتبط دیگر این است که هیچ سازش‌پذیری در آنچه که انتخاب تو در پی دارد، وجود ندارد. آن نمی‌تواند به تو فقط اندکی بدهد‌، زیرا هیچ حد وسطی ندارد. هر انتخابی که تو انجام می‌دهی یا همه ‌چیز را به تو می‌دهد یا هیچ ‌چیز را. بنابراین اگر آزمون‌هایی را یاد بگیری که با آنها می‌توانی همه ‌چیز را از هیچ ‌چیز تشخیص دهی، آنگاه انتخاب بهتری انجام خواهی داد.

نخست اینکه اگر چیزی که انتخاب می‌کنی برای همیشه دوام ندارد، آنگاه آنچه انتخاب می‌کنی بی‌ارزش است. یک ارزش گذرا دارای هیچ ارزشی نیست. زمان هرگز نمی‌تواند ارزشی را که واقعی است از میان ببرد. آنچه که زوال می‌یابد و می‌میرد هرگز وجود نداشته است، و هیچ چیزی به کسی که انتخابش می‌کند عرضه نمی‌کند. او توسط هیچ ‌چیز در شکلی که فکر می‌کند دوستش دارد فریب خورده است.

دیگر اینکه، اگر انتخاب کنی که چیزی را از شخص دیگری بگیری، آنگاه هیچ چیز برای تو باقی نخواهد ماند. این به این دلیل است که وقتی حق او را برای همه چیز انکار می‌کنی، حق خود را برای همه چیز انکار کرده‌ای. بنابراین تو با انکار وجود داشتن آنها، چیزهایی را که واقعاً داری تشخیص نخواهی داد. کسی که بدنبال ستاندن است با توهّم اینکه زیان می‌تواند سود پیشکش کند، فریب خورده است. ولی زیان قطعا زیان پیشکش می‌کند، و نه چیزی بیشتر.

ملاحظه‌ی بعدی تو آن چیزی است که دیگر ملاحظات هم بر آن استوارند. چرا انتخابی که می‌کنی برایت ارزشمند است؟ چه چیز ذهن تو را به آن جذب می‌کند؟ آن به چه قصدی خدمت می‌کند؟ اینجا این آسان‌ترین راه برای فریب خوردن است. زیرا نفس در تشخیص آنچه که می‌خواهد شکست می‌خورد. آن حتی حقیقت را درباره‌ی آنچه می‌خواهد، آنگونه که درک می‌کند نمی‌گوید، زیرا نیاز دارد تا آن هاله‌ای را نگه دارد که از آن برای محافظت کردن از هدف‌هایش در برابر لکه‌دار شدن و زنگار گرفتن استفاده می‌کند، تا تو بتوانی ببینی که آن چقدر «معصوم» است.

اما پنهان‌کاری نفس تنها یک پوشش نازک است، که تنها می‌تواند آنانی را فریب دهد که از فریب خوردن خوشنودند. هدفهای آن بر هرکسی که به جستجوی آنها اهمیت می‌دهد، آشکار هستند. اینجا فریب دو برابر می‌شود، زیرا آنکه فریب خورده است درک نخواهد کرد که فقط در سود بردن شکست خورده است. او باور خواهد کرد که به هدفهای پنهان نفس خدمت کرده است.

اما اگرچه او می‌کوشد که هاله‌ی آن را واضح در دید خود داشته باشد، هنوز باید لبه‌های تیره‌ی آن و هسته‌ی زنگار گرفته‌اش را درک کند. اشتباهات بی‌نتیجه‌اش برای او گناهان به نظر می‌رسند، زیرا او آن تیرگی را همانند تیرگی خود می‌بیند؛ زنگار را نشانه‌ای از بی‌ارزش بودن عمیق در درون خود. آن‌کس که هنوز می‌خواهد از هدف‌های نفس حفاظت کند و به آنها همانند هدفهای خودش خدمت کند،طبق آنچه که راهنمایش دیکته می‌کند، اشتباه نمی‌کند. این راهنمایی آموزش می‌دهد که باور داشتن به اینکه گناهان فقط اشتباهات هستند، نادرست است، زیرا چه کسی بخاطر گناهان خود رنج می‌برد اگر این چنین بود؟

و اینگونه ما به آن معیار انتخاب می‌رسیم که دشوارترین برای باور کردن است‌، زیرا آشکار بودن آن با سطوح بسیاری از ابهام پوشانده شده است. اگر درباره‌ی انتخاب خود هرگونه احساس گناهی داری، تو به هدفهای نفس اجازه داده‌ای که در بین گزینه‌های واقعی قرار گیرند. و بنابراین درک نمی‌کنی که تنها دو گزینه وجود دارد، و گزینه‌ای که فکر می‌کنی انتخاب کرده‌ای ترسناک به نظر می‌رسد، و بسیار خطرناک‌تر از آن که آن هیچی باشد که واقعاً هست.

همه‌ی چیزها یا دارای ارزشند یا بی‌ارزش هستند، یا شایسته‌ی طلبیدن هستند و یا به هیچ روی شایسته طلبیدن نیستند، به تمامی خواستنی یا فاقد ارزش کمترین تلاشی برای بدست آوردن. به این دلیل انتخاب کردن آسان است. پیچیدگی چیزی جز پرده‌ای از دود نیست، که این واقعیت بسیار ساده را پنهان می کند که هیچ تصمیمی نمی‌تواند دشوار باشد. سود تو در آموختن این چیست؟ سود آن بسیار بیشتر از این است که فقط به تو اجازه دهد به آسانی و بدون درد انتخاب کنی.

بهشت* خودش با دستان خالی و ذهن‌های باز بدست می‌آید، که با هیچ‌ چیز می‌آیند تا همه چیز را بیابند و آن را از آن خود اعلام کنند. امروز سعی می‌کنیم به این حالت برسیم، با خودفریبی که کنار نهاده شده، و با اراده‌مندی صادقانه برای این که فقط برای آنچه که حقیقتا ارزشمند و واقعی است، ارزش قائل شویم. هر کدام از دو زمان تمرین طولانی‌تر و پانزده دقیقه‌ای ما با این شروع می‌شوند: من برای آنچه که بی‌ارزش است، ارزش قائل نخواهم شد، و من فقط آن چیزی را می‌طلبم که دارای ارزش است، زیرا من میل دارم فقط آن را بیابم.

و سپس آن‌چیزی را دریافت کن که در انتظار هر کسی است که سبکبار به دروازه‌ی بهشت می‌رسد، دروازه‌ای که به محض رسیدن او باز می‌شود. اگر آغاز به این کردی که به خودت اجازه دهی که برخی بارهای غیرضروری را گردآوری کنی، یا باور کنی که برخی تصمیم‌های دشوار را در مقابلت می‌بینی، با این اندیشه‌ی ساده در پاسخ دادن سریع باش: من برای آنچه که بی‌ارزش است ارزش قائل نخواهم شد، زیرا آنچه ارزشمند است به من تعلق دارد.', 'https://acim-farsi.org/workbook/lesson/133', 'https://acim-farsi.org/audio/workbook/lesson/133.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (134, 'بگذار من بخشایش را آنگونه که هست ادراک کنم.', 'در طول روز و هر زمان که معنای بخشایش را فراموش کردی:

بگذار من بخشایش را آنگونه که هست ادراک کنم. آیا من خودم را برای انجام این متهم می‌کردم؟ من این زنجیر را برخودم نمی‌افکنم.

در زمان انجام هر کاری این را به یاد داشته باش:
هیچ کس به تنهایی مصلوب نمی‌شود، پس هیچ‌کس نمی‌تواند خودش تنها به بهشت* وارد شود.', 'بگذار من بخشایش را آنگونه که هست ادراک کنم.

بگذار معنای «بخشایش» را مرور کنیم، زیرا این معنا مستعد تحریف شدن و ادراک شدن به عنوان چیزی که منجر به قربانی کردن ناعادلانهٔ یک خشم عادلانه می‌شود، یک هدیهٔ ناعادلانه که به فردی نامستحق داده می‌شود، و انکار کامل حقیقت. در چنین دیدگاهی، بخشایش باید یک خطای گمراهانه محسوب شود، و به نظر برسد که این دوره رستگاری را به یک هوس وابسته کرده است.

زمانی که تو بتوانی این واقعیت را بپذیری که برای آنچه حقیقی است، بخشش درخواست نمی‌شود، این نگرش تحریف شده به معنای بخشایش به آسانی تصحیح می‌شود. بخشایش فقط باید به آنچه غیرحقیقی است محدود گردد. بخشایش فقط و فقط به اوهام مربوط است. حقیقت آفرینش خداوند* است، و بخشش آن بی‌معنا است. تمام حقیقت از آن او* است. قانون‌های او* را بازتاب می‌دهد و عشق* او* را می‌تاباند. آیا این نیازی به بخشش دارد؟ تو چگونه می‌توانی بی‌گناه و لطیف ابدی را ببخشی؟

دشواری اصلی که تو درمورد بخشایش خالصانه از سوی خودت داری این است که تو هنوز باور داری که باید حقیقت را ببخشی، و نه اوهام را. تو بخشش را به عنوان تلاشی بیهوده برای عبور کردن از آنچه وجود دارد درک می‌کنی؛ تلاشی برای چشم‌پوشی از حقیقت، و به این ترتیب سعی می‌کنی با حقیقی کردن یک وهم خودت را فریب دهی. این نظرگاه نادرست صرفاً باقی ماندن ایدهٔ گناه را در ذهن تو بازتاب می‌دهد زمانی که به خودت نگاه می‌کنی.

از آنجا که تو می‌پنداری گناهانت واقعی هستند، بخشش را یک فریب می‌بینی. زیرا ناممکن است گناه را حقیقت بدانی و باور نداشته باشی که بخشایش یک دروغ است. به این صورت بخشایش واقعاً یک گناه است مانند همهٔ گناهان دیگر. این دیدگاه می‌گوید حقیقت غیرحقیقی است، و به مفسدان لبخند می‌زند گویی که آن‌ها مانند گیاه بی‌عیب هستند، همانند برف سفید. در آنچه که ‌فکر می‌کند می‌تواند به انجام رساند، دچار توهّم است. این دیدگاه آنچه که بطور واضح نادرست است را درست می‌داند؛ نفرت‌انگیز را خوب.

در چنین دیدگاهی بخشایش راه فرار نیست. در این دیدگاه بخشایش صرفاً نشان دیگری است از این که گناه نابخشودنی است، و در بهترین حالت باید مخفی شود، انکار گردد یا به نام دیگری خوانده شود، زیرا بخشش خیانت به حقیقت است. احساس گناه را نمی‌توان بخشید. اگر گناه کنی، احساس گناه تو ابدی است. آنان که از این منظر بخشیده شده‌اند که گناهانشان واقعی هستند به طرز رقت‌انگیزی تمسخر شده و دو برابر محکوم می‌شوند؛ نخست توسط خودشان به خاطر آنچه که فکر می‌کنند انجام دادند، و دوباره توسط کسانی که آنها را می‌بخشند.

غیرواقعی بودن گناه است که موجب می‌شود بخشایش طبیعی و کاملا عاقلانه باشد، یک تسکین عمیق برای آنان که عرضه‌اش می‌کنند؛ یک تبرک ساکت در هر کجا که دریافت شود. بخشایش از اوهام پشتیبانی نمی‌کند بلکه به نرمی آنها را جمع‌آوری می‌کند، با خنده‌ای کوچک، و به آرامی آنها را در پای حقیقت می‌گذارد. و در آنجا، اوهام به تمامی ناپدید می‌شوند.

بخشایش تنها چیزی است که از حقیقت در اوهام دنیا محافظت می‌کند. بخشایش هیچ بودن آنها را می‌بیند، و مستقیماً از طریق هزاران شکلی که آنها ممکن است به خود بگیرند نگاه می‌کند. بخشایش به دروغها نظر می‌کند، اما فریب نمی‌خورد. بخشایش اعتنایی به جیغ‌های خود‌سرزنشگرانهٔ گناهکاران که با احساس گناه دیوانه شده‌اند نمی‌کند. بخشایش به آنان با چشمان ساکت می‌نگرد، و صرفا به آنان می‌گوید، «برادر من، آنچه تو می‌اندیشی حقیقت نیست.»

قدرت بخشایش در صداقت آن است، که آنچنان شرافتمند است که اوهام را اوهام می‌بیند، نه حقیقت. به این دلیل است که در مواجهه با دروغ‌ها فریب دهنده نیست؛ بازگردانندهٔ بزرگ حقیقت ساده. با توانایی خود برای صرف نظر کردن از آنچه وجود ندارد، بخشایش راه حقیقت را می‌گشاید، راهی که با رؤیاهای احساس گناه مسدود شده است. اینک تو آزاد هستی تا راهی را که بخشایش حقیقی تو برایت گشوده دنبال کنی. زیرا اگر یک برادر این موهبت را از تو دریافت کند، این در بروی خودت باز است.

یک راه بسیار ساده برای یافتن درب به سوی بخشایش حقیقی، و درک کردن گشایش و استقبال آن وجود دارد. زمانی که احساس می‌کنی وسوسه می‌شوی کسی را برای گناه به هر شکلی متهم کنی، اجازه نده ذهنت بر آنچه می‌اندیشی او انجام داده است متمرکز شود، زیرا این خود‌فریبی است. در عوض بپرس، «آیا من خودم را به انجام این کار متهم می‌کنم؟»

اینگونه تو گزینه‌هایی برای انتخاب خواهی دید که انتخاب را معنادار می‌کند، و ذهنت را از احساس گناه و درد آزاد نگه‌ می‌داری، همانطور که خداوند* قصد داشت که باشد، و همانطور که در حقیقت است. فقط دروغ‌ها هستند که می‌خواهند محکوم کنند. در حقیقت بی‌گناهی تنها چیزی است که وجود دارد. بخشایش بین اوهام و حقیقت ایستاده است؛ بین دنیایی که تو می‌بینی و دنیایی که ورای آن است؛ بین دوزخ احساس گناه و دروازهٔ بهشت*.

در آن سوی این پل، با قدرت عشق که تبرکش را نثار کرده است، همه‌ی رؤیاهای شر و نفرت و حمله در سکوت به نزد حقیقت آورده می‌شوند. آن‌ها حفظ نمی‌شوند تا تورم کنند و منفجر شوند، و رؤیابینندهٔ نادانی را که به آن‌ها باور دارد به وحشت بیاندازند. او به آرامی از رؤیای خود بیدار می‌شود، با درک این که آنچه می‌پنداشت می‌بیند هرگز وجود نداشته است. و اینک او نمی‌تواند احساس کند که همهٔ راه‌های فرار از او دریغ شده‌اند.

او نیاز ندارد بجنگد تا خودش را نجات دهد. او نیاز ندارد اژدهایانی را که می‌پنداشت تعقیبش می‌کنند، بکشد. و نیاز ندارد دیوارهای سنگین از سنگ و درب‌های آهنی که می‌اندیشید به او امنیت می‌دهند را بر پا کند. او می‌تواند زره‌های سنگین و بی‌استفاده‌ای که ساخته شدند تا ذهن او را به زنجیر ترس و بیچارگی بکشند را بردارد. گام‌های او سبک است، و همانطور که پایش را بلند می‌کند و به جلو گام برمی‌دارد، ستاره‌ای پشت سرش می‌ماند، تا راه را به آنانی که او را دنبال می‌کنند نشان دهد.

بخشایش باید تمرین شود، زیرا دنیا نمی‌تواند معنای آن را درک کند، و راهنمایی را ارائه کند که به تو سودمندی آن را آموزش دهد. در همهٔ دنیا هیچ اندیشه‌ای نیست که به هرگونه فهمی از قانون‌های دنبال شده توسط بخشایش هدایت کند، و نه به اندیشه‌ای که آن بازتاب می‌دهد. بخشایش به همان اندازه برای دنیا بیگانه است که واقعیت خودت برای آن بیگانه است. و با این حال بخشایش با واقعیت در تو به ذهن تو می‌پیوندد.

امروز ما بخشایش حقیقی را تمرین می‌کنیم، تا زمان پیوستن بیش از این به تأخیر نیافتد. زیرا ما می‌خواهیم در آزادی و صلح با واقعیت خود ملاقات کنیم. تمرین ما آن گام‌ها می‌شود که راه را برای همه‌ی برادرانمان روشن می‌کنند، که ما را بسوی واقعیتی که با آنها سهیم هستیم دنبال خواهند کرد. برای به انجام رساندن این، بگذارید امروز دو بار و هر بار یک ربع ساعت را اختصاص دهیم، و این زمان را با آن راهنما* بگذرانیم که معنای بخشایش را می‌داند و برای ما فرستاده شده تا آن را آموزش دهد. بگذارید از او* بپرسیم: بگذار من بخشایش را آنگونه که هست ادراک کنم.

سپس یک برادر خود را آنگونه که او هدایت می‌کند انتخاب کن، و «گناهان» او را همانطور که به ذهنت می‌رسند یکی یکی بشمار. مطمئن شو که بر هیچ یک از آنها تمرکز نمی‌کنی، اما تشخیص بده که تو از «حملات» او فقط برای نجات دادن دنیا از همه اعتقادات مربوط به گناه استفاده می‌کنی. بطور مختصر همه چیزهای شرورانه را که دربارهٔ او می‌پنداشتی مرور کن، و هر بار از خودت بپرس، «آیا من خودم را برای انجام این محکوم می‌کردم؟»

بگذار او از همه افکاری که تو درمورد گناهانش داشتی آزاد شود. و اینک تو برای آزادی آماده هستی. اگر درست تمرین کرده باشی، آغاز به احساس صعود می‌کنی، سبکی وزن در سینه، یک احساس عمیق از تسکین. زمان باقی‌مانده باید برای تجربه کردن فرار از همه زنجیرهای سنگین که تو ساخته‌ای تا روی برادرت بیاندازی اما روی خودت انداختی صرف شود.

بخشایش باید در طول روز تمرین شود، زیرا هنوز زمانهای بسیاری وجود خواهد داشت که معنای آن را فراموش می‌کنی و به خودت حمله می‌کنی. وقتی این رخ می‌دهد، به ذهنت اجازه بده از طریق این وهم ببیند در حالیکه به خودت می‌گویی: بگذار من بخشایش را آنگونه که هست ادراک کنم. آیا من خودم را برای انجام این متهم می‌کردم؟ من این زنجیر را برخودم نمی‌افکنم. در زمان انجام هر کاری این را به یاد داشته باش: هیچ کس به تنهایی مصلوب نمی‌شود، پس هیچ‌کس نمی‌تواند خودش تنها به بهشت* وارد شود.', 'https://acim-farsi.org/workbook/lesson/134', 'https://acim-farsi.org/audio/workbook/lesson/134.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (135, 'اگر من از خودم دفاع کنم، به من حمله می‌شود.', 'اگر من از خودم دفاع کنم، به من حمله می‌شود. اما در بی‌دفاعی من قوی خواهم بود، و خواهم آموخت که دفاعم چه چیز را پنهان می‌کند.

در طول روز، هرگاه که چیزهای کوچک نابخردانه بنظر حالت دفاعی را در تو بر‌ می‌انگیزند و تو را وسوسه می‌کنند که درگیر نقشه کشیدن شوی، به خودت یادآوری کن که امروز روز خاصی برای یادگیری است، و آن را با این تأیید کن:

امروز عید پاک من است. و من آن را مقدس می‌دارم. من از خودم دفاع نخواهم کرد، زیرا فرزند* خداوند* نیازی به دفاع در برابر حقیقتِ واقعیت خود ندارد.', 'اگر من از خودم دفاع کنم، به من حمله می‌شود.

چه کسی از خود دفاع می‌کند مگر اینکه بپندارد به او حمله شده است، حمله واقعی بوده، و اینکه دفاع خودش می‌تواند نجاتش دهد؟ و نابخردانه بودن دفاع در اینجا نهفته است؛ دفاع به اوهام واقعیت تام می‌دهد، و سپس سعی می‌کند مانند واقعیت با اوهام برخورد کند. دفاع کردن اوهام را بر اوهام می‌افزاید، و به این صورت تصحیح را دو برابر مشکل می‌سازد. و این کاری است که تو انجام می‌دهی زمانی که سعی می‌کنی برای آینده نقشه بکشی، گذشته را زنده کنی، یا زمان حال را مطابق میل خود سامان دهی.

تو بر اساس این باور که باید از خودت در برابر آنچه روی می‌دهد محافظت کنی عمل می‌کنی، زیرا آن باید دربردارندهٔ چیزی باشد که تهدیدت می‌کند. احساس تهدید تأییدی بر یک ضعف ذاتی است؛ این باور که خطری وجود دارد که قدرت فرا خواندن تو را به دفاع مناسب در خود دارد. دنیا بر پایهٔ این باور نامعقول بنا شده است. و تمام ساختارهای آن، همهٔ اندیشه‌ها و تردیدهای آن، کیفرها و جنگ‌افزارهای سنگین آن، تعاریف قانونی و قوانین آن، اخلاق آن و رهبران آن و خدایان آن، همگی فقط در خدمت حفظ احساس تهدیدش هستند. زیرا هیچ‌کس با سلاح در دنیا قدم نمی‌زند مگر اینکه در قلبش احساس وحشت چنگ زند.

دفاع وحشت‌انگیز است. آن از ترس برمی‌آید، و ترس را با هر دفاع افزایش می‌دهد. تو می‌پنداری که آن امنیت را به ارمغان می‌آورد. اما آن از ترسِ واقعی شده و وحشتِ موجه شده صحبت می‌کند. آیا این عجیب نیست که وقتی نقشه‌های خود را بسط می‌دهی و زره خود را ضخیم‌تر می‌کنی و قفل‌های خود را محکم‌تر، تو درنگ نمی‌کنی تا بپرسی که از چه ‌دفاع می‌کنی، و چگونه، و در برابر چه؟

بگذار ابتدا بررسی کنیم که تو از چه دفاع می‌کنی. آن باید چيز بسیار ضعيفی باشد که به آسانی مورد حمله قرار می‌گیرد. آن بايد چيزی باشد كه به آسانی شكار می‌شود، چیزی که نمی‌تواند از خودش محافظت کند و نیاز به دفاع تو دارد. چه چیزی جز بدن آنقدر ضعف دارد که مراقبت مداوم و دقیق و نگرانی عمیق برای محافظت از زندگی کوچک او ضروری است؟ چه چیزی‌ جز بدن متزلزل می‌شود و قطعا نمی‌تواند به عنوان یک میزبان شایسته‌ به فرزند* خداوند* خدمت کند؟

اما این بدن نیست که می‌تواند بترسد، یا چیزی باشد که بتوان از آن ترسید. بدن هیچ نيازي ندارد جز آن‌ها كه تو به آن نسبت می‌دهی. بدن هیچ نیازی به ساختار پیچیدهٔ دفاعی ندارد، نه دارو‌های القا کنندهٔ بهبودی، نه مواظبت و نه نگرانی. از زندگی آن دفاع کن، یا به آن هدیه‌ها بده تا آن را زیبا کنی یا دیوارهایی بساز تا امنیتش را تامین کنی، و آنگاه تو فقط چنین می‌گویی که خانه‌ات به روی دزد زمان باز است، در معرض فساد و تباهی، چنان ناامن که باید تمام عمرت محافظت شود.

آیا این تصویر ترسناک نیست؟ آیا تو می‌توانی با چنین مفهومی از خانه‌ات در صلح باشی؟ اما چه چیزی به بدن این حق را داده که به تو اینگونه خدمت کند جز باور خودت؟ ذهن تو است که به بدن همه‌ی وظایفی را که در آن می‌بینی داده است، و ارزش آن را بسیار فراتر از توده‌ای از خاک و آب قرار داده است. چه کسی می‌خواهد از چیزی دفاع کند که آن را با این عنوان شناخته است؟

بدن نیازمند هیچ دفاعی نیست. این نمی‌تواند بیش از حد تاکید شود. اگر ذهن از بدن برای نقش‌هایی که نمی‌تواند ایفا کند، سو استفاده نکند، برای اهدافی که فراتر از توان آن هستند، و برای منظورهایی که نمی‌تواند برآورده سازد، بدن قوی و سالم خواهد بود. چنین تلاش‌هایی، مضحک اما عمیقاً پرورده شده، منبع بسیاری از حمله‌های دیوانه‌وار هستند که تو بر روی بدن انجام می‌دهی. زیرا آن به نظر می‌رسد در برآورده کردن امیدها، نیازها، ارزشها و رؤیاهای تو شکست خورده است.

آن «خودی» که نیاز به مراقبت دارد، واقعی نیست. بدن که بی‌ارزش و به سختی لایق کمترین دفاع است، صرفاً نیاز دارد که به عنوان چیزی‌ کاملا جدا از تو درک شود، و آنگاه تبدیل به یک ابزار سالم و خدمتگزار می‌شود که ذهن از طریق آن عمل می‌کند تا زمانی که مفید بودن آن به پایان برسد. چه کسی می‌خواهد آن را نگه دارد وقتی که مفید بودنش به پایان رسیده است؟

اگر از بدنت دفاع کنی، به ذهنت حمله کرده‌ای. زیرا در آن خطا، ضعف، محدودیتها و فقدانهایی را دیده‌ای که فکر می‌کنی بدن باید از آنها نجات یابد. در این صورت تو ذهن را مجزا از شرایط بدنی نمی‌بینی. و تو به بدن همهٔ دردی را که از درک ذهن به عنوان محدود و شکننده ناشی می‌شود، جدا از ذهن‌های دیگر و جدا از سرچشمه خود، تحمیل خواهی کرد.

اینها افکاری هستند که نیاز به شفا دارند، و وقتی که تصحیح شوند و با حقیقت جایگزین گردند، بدن با سلامتی پاسخ خواهد داد. این تنها دفاع واقعی بدن است. اما آیا این جایی است که تو بدنبال دفاع آن می‌گردی؟ تو به آن‌ نوعی از محافظت عرضه می‌کنی که از آن هیچ سودی نمی‌برد، بلکه فقط بر پریشانی ذهنی تو می‌افزاید. تو شفا نمی‌دهی، بلکه فقط امید شفا را از میان می‌بری، زیرا تو نمی‌توانی ببینی که امید باید کجا باشد اگر قرار است دارای معنا باشد.

یک ذهن شفا یافته نقشه نمی‌کشد. این ذهن نقشه‌هایی را اجرا می‌کند که از طریق گوش دادن به خردی که از آن خودش نیست، دریافت می‌کند. این ذهن منتظر می‌ماند تا به او آموخته شود چه کاری باید انجام شود، و سپس به پیش می‌رود تا آن را انجام‌ دهد. آن برای هیچ چیزی به خودش متکی نیست جز شایستگی خود برای به انجام رساندن نقشه‌های مقرر شده برای خود. این ذهن در این اطمینان ایمن است که موانع نمی‌توانند مانع توفیق آن در رسیدن به اهدافی شوند که به نقشهٔ عظیم‌تر تعیین شده برای خیر همگان خدمت می‌کنند.

یک ذهن شفا یافته از این باور که باید نقشه بکشد رها است، اگر‌چه نمی‌‌داند بهترین نتیجه چیست، با چه وسایلی به انجام می‌رسد، و نیز نمی‌داند که چگونه این مسأله‌ را تشخیص دهد که این نقشه ساخته شده تا آن را حل کند. آن باید در نقشه‌های خود از بدن سؤاستفاده کند تا زمانی که تشخیص دهد چنین است. اما وقتی که ذهن این را به عنوان درست پذیرفته باشد، آنگاه شفا می‌یابد و بدن را رها می‌کند.

بردگی بدن برای نقشه‌های یک ذهن شفا نیافته در جهت نجات دادن خودش، باید بدن را بیمار سازد. بدن آزاد نیست تا وسیله‌ی کمک در نقشه‌ای باشد که از حفاظت خودش فراتر می‌رود، و به خدمتش برای مدت کوتاهی نیاز دارد. در این مقام از سلامت اطمینان حاصل می‌شود زیرا هر چیزی که ذهن برای این به کار می‌برد بدون نقص عمل خواهد کرد، با قدرتی که به آن داده شده است و نمی‌تواند شکست بخورد.

احتمالا آسان نیست درک شود که نقشه‌های خودساخته صرفاً دفاع هستند، همهٔ آن‌ها ساخته شدند تا این قصد را تحقق بخشند. آن‌ها وسایلی هستند که با آن‌ها یک ذهن هراسان به بهای حقیقت از خودش محافظت می‌کند. در برخی از شکل‌هایی که این خود‌فریبی‌ها می‌گیرند ‌این برای فهم دشوار نیست، جایی که انکار واقعیت بسیار آشکار است. اما طرح نقشه اغلب به عنوان یک دفاع تشخیص داده نمی‌شود.

ذهنی که مشغول نقشه کشیدن برای خودش است درگیر کنترل کردن رویدادهای آینده است. آن فکر نمی‌کند که نیازهایش تأمین می‌شود، مگر آنکه تدارکات خودش را انجام‌ دهد. زمان تبدیل به تأکید آینده می‌شود، که با یادگیری و تجربه به دست آمده از رویدادهای گذشته و باورهای پیشین کنترل می‌شود. از زمان حال چشم‌پوشی می‌کند، زیرا بر این عقیده است که گذشته آنقدر آموزش داده است که به ذهن اجازه دهد مسیر آیندهٔ خود را هدایت کند.

پس ذهنی که نقشه می‌کشد اجازه تغییر را نمی‌دهد. آنچه از پیش آموخته است مبنای اهداف آینده‌اش است. تحربه گذشته‌اش انتخاب او را در این مورد که چه چیزی رخ خواهد داد، هدایت می‌کند. و نمی‌بیند که اینجا و اکنون هرچیزی که او نیاز دارد موجود است، برای تضمین یک آینده کاملا متفاوت با گذشته، بدون تداوم هیچ ایدهٔ کهنه و باورهای بیمارگونه. انتظار هرگز هیچ نقشی ندارد، زیرا اطمینانِ کنونی، مسیر را هدایت می‌کند.

دفاع‌ها نقشه‌هایی هستند که تو بر علیه حقیقت طرح می‌کنی. هدف آنها این است که آنچه را که تو تأیید می‌کنی انتخاب کنند، و آنچه را که با باورهای ‌تو از واقعیت خودت ناسازگار هستند، نادیده بگیرند. با این حال آنچه که باقی می‌ماند، در واقع بی‌معنی است. زیرا این واقعیت تو است که «تهدیدی» است که دفاع‌های تو می‌خواهند به آن حمله کنند، بپوشانند، جدا کنند و مصلوب کنند.

اگر فقط می‌دانستی که همه چیز که رخ می‌دهد، همهٔ رویدادها، گذشته، حال، و آینده، با لطافت توسط آن یگانه* طراحی شده است که تنها هدفش* خیر تو است، آنگاه چه چیز را می‌پذیرفتی؟ شاید تو نقشه‌های او* را اشتباه فهمیده‌ای، او* هرگز رنج را به تو عرضه نمی‌کند. اما دفاع تو اجازه نمی‌دهد ببینی چگونه تبرک عاشقانه‌اش* در هر گامی که تو بر می‌داری می‌تابد. در حالی که تو برای مرگ نقشه می‌کشیدی، او* تو را با ملایمت به زندگی ابدی راهنمایی کرد.

اعتماد کنونی تو به او* دفاعی است که آینده‌ای بی‌خلل، بدون هیچ ردی از اندوه، و با شادمانی که مدام افزایش می‌یابد را نوید می‌دهد، با تبدیل این زندگی به لحظه‌ای مقدس، مقرر شده در زمان، که اما فقط به فناناپذیری توجه دارد. اجازه نده هیچ دفاعی جز اعتماد کنونی تو آینده را هدایت کند، و آنگاه این زندگی به یک دیدار معنادار با حقیقت تبدیل می‌شود که فقط دفاع‌های تو آن را پنهان می‌کنند.

بدون دفاع، تو به نوری تبدیل می‌شوی که بهشت* با سپاس‌گذاری آن را از آن خود می‌داند. و این تو را در راههایی هدایت می‌کند که برای شادمانی تو مقرر شدند، مطابق نقشه‌ی دیرین، که از وقتی که زمان زاده شد آغاز شده بود. آنها که تو را دنبال می‌کنند نورشان را با نور تو پیوند می‌زنند، و آن نور افزایش می‌یابد تا زمانی که دنیا با سرور روشن شود. و برادران ما با خوشحالی دفاع‌های سنگین خود را کنار می‌گذارند، که هیچ سودی برای آنها نداشت و فقط وحشت ایجاد می‌کرد.

امروز ما آن زمان را با اطمینان کنونی انتظار می‌کشیم، زیرا این بخشی از نقشه‌ای است که برای ما طرح‌ریزی بود. امروز ما مطمئن خواهیم بود که هرچیزی که برای به انجام رساندن این لازم داریم به ما داده شده است. ما هیچ نقشه‌ای برای چگونگی انجام آن نمی‌کشیم، اما می‌فهمیم که بی‌دفاعی ما همه‌ی آن چیزی است که نیاز داریم تا حقیقت با اطمینان بر ذهن‌های ما طلوع کند.

امروز دو بار به مدت پانزده دقیقه از نقشه کشیدن بیهوده دست می‌کشیم، و از همه‌ی افکاری که ورود حقیقت را به ذهنمان مسدود می‌کنند. امروز ما به جای نقشه کشیدن دریافت خواهیم کرد، چیزی را که می توانیم در عوض سازماندهی کردن، بدهیم. و به ما حقیقتا داده می شود، زمانی که می‌گوییم: اگر من از خودم دفاع کنم، به من حمله می‌شود. اما در بی‌دفاعی من قوی خواهم بود، و خواهم آموخت که دفاعم چه چیز را پنهان می‌کند.

فقط همین. اگر نقشه‌هایی باشند، از آنها به تو گفته خواهد شد. آنها ممکن است آن نقشه‌هایی نباشند که تو می‌پنداشتی نیاز داری، و نه در واقع پاسخ به مسائلی که می‌پنداشتی با آنها مواجه شده‌ای. اما آنها پاسخ‌هایی به نوع دیگری از پرسش هستند، که هنوز پاسخ داده نشده و نیازمند پاسخ باقی مانده تا سرانجام پاسخ به تو برسد.

هدف همهٔ دفاع‌های تو این است که تو آنچه را که امروز دریافت خواهی کرد، دریافت نکنی. و در نو و شادمانی اعتماد ساده، تو فقط تعجب خواهی کرد چرا هرگز می‌پنداشتی که تو باید در برابر رهایی از خود دفاع کنی؟ بهشت* هیچ‌چیزی درخواست نمی‌کند. این دوزخ است که درخواست‌های زیاده‌خواهانه برای قربانی دادن دارد. تو امروز در این زمانها هیچ چیزی را رها نخواهی کرد، وقتی که تو، دفاع نشده، خودت را به آفریدگارت* همانطور که واقعاً هستی، تقدیم می‌کنی.

او* تو را به یاد دارد. امروز ما او* را به یاد خواهیم آورد. زیرا این زمان عید* پاک* تو در رستگاری‌ات است. و تو دوباره از آنچه که به نظر می‌رسید مرگ و ناامیدی بود برمی‌خیزی. اینک نور امید دوباره در تو زاده شده است، زیرا اینک تو بدون دفاع می‌آیی، تا نقش خود را در نقشهٔ خداوند* بیاموزی. کدام نقشه‌های کوچک و باورهای جادویی هنوز می‌توانند دارای ارزش باشند، وقتی که تو وظیفه‌‌ات را از آوای* برای خود* خداوند* دریافت کرده‌ای؟

تلاش نکن امروز را بگونه‌ای شکل دهی که باور داری بیشترین منفعت را برایت دارد. زیرا تو نمی‌توانی همهٔ شادمانی را که بدون نقشه کشیدن تو به سویت می‌آید، تصور کنی. امروز بیاموز و همهٔ دنیا این گام بزرگ را خواهد برداشت و عید* پاکت* را با تو جشن خواهد گرفت. در طول روز، هرگاه که چیزهای کوچک نابخردانه بنظر حالت دفاعی را در تو بر‌ می‌انگیزند و تو را وسوسه می‌کنند که درگیر نقشه کشیدن شوی، به خودت یادآوری کن که امروز روز خاصی برای یادگیری است، و آن را با این تأیید کن: امروز عید پاک من است. و من آن را مقدس می‌دارم. من از خودم دفاع نخواهم کرد، زیرا فرزند* خداوند* نیازی به دفاع در برابر حقیقتِ واقعیت خود ندارد.', 'https://acim-farsi.org/workbook/lesson/135', 'https://acim-farsi.org/audio/workbook/lesson/135.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (136, 'بیماری دفاعی در مقابل حقیقت است.', 'من فراموش کرده‌ام که واقعا چه هستم، زیرا بدنم را با خودم اشتباه گرفتم. بیماری دفاعی در برابر حقیقت است. اما من یک بدن نیستم. و ذهن من نمی‌تواند حمله کند. پس من نمی‌توانم بیمار باشم.', 'بیماری دفاعی در مقابل حقیقت است.

هیچ‌کس نمی‌تواند شفا دهد مگر اینکه بفهمد که هدف بیماری احتمالا چه می‌تواند باشد. زیرا آن زمان همچنین می‌فهمد که این هدف هیچ معنایی ندارد. بدون هیچ علتی و بدون هیچگونه قصد با معنایی، بیماری اساساً نمی‌تواند وجود داشته باشد. وقتی که این ملاحظه شود، شفا خودبخودی است. شفا این وهم بی‌معنا را رفع می‌کند، با همان رویکردی که همه اوهام را به حقیقت می‌رساند، و صرفا آنها را در آنجا رها می‌کند تا ناپدید شوند.

بیماری یک تصادف نیست. مانند همهٔ دفاع‌ها، بیماری یک وسیله دیوانه‌وار برای خودفریبی است. و مانند همه چنین وسایلی، قصد آن پنهان ساختن واقعیت، حمله به آن، تغییر آن، عرضه کردن ناکارآمدی آن، مغشوش کردن آن، کج کردن آن، یا کاهش آن به توده کوچکی از اجزای ناپیوسته است. قصد همهٔ دفاع‌ها، بازداشتن حقیقت از تمام بودن است. این بخش‌ها آنگونه دیده می‌شوند که انگار هر یک از آن‌ها در خودشان تمام هستند.

دفاع‌ها، غیرعمدی نیستند، و نیز بدون آگاهی ساخته نشده‌اند. آنها چوبهای مخفی جادویی هستند که تو زمانی که به نظر می‌رسد حقیقت آنچه را که می‌خواهی باور کنی مورد تهدید قرار می‌دهد، به حرکت در می‌آوری. به نظر می‌رسد که ناخودآگاه هستند فقط به دلیل سرعتی که تو برای استفاده از آنها انتخاب می‌کنی. در آن ثانیه، یا حتی کمتر از ثانیه، که این انتخاب انجام می‌شود، تو دقیقاً تشخیص می‌دهی که سعی داری چه کنی، و سپس به این فکر پیش می‌روی که انجام شده است.

چه کسی به جز خودت یک تهدید را ارزیابی می‌کند، تصمیم می‌گیرد که فرار ضرورت دارد، و مجموعه ای از دفاع را فراهم می‌کند تا تهدیدی را که واقعی دانسته است کاهش دهد؟ همهٔ این نمی‌تواند ناخودآگاه انجام شود. اما سپس، نقشه تو مستلزم این است که باید فراموش کنی خودت آن را ساختی، تا به نظر برسد از اراده خود تو بیرون است؛ رویدادی ورای وضعیت ذهنی تو، نتیجه‌ای که تاثیر واقعی بر تو دارد، به جای اینکه خودت بر آن تاثیر‌گذار باشی.

این از یاد بردن سریع نقش تو در ساختن «واقعیت» خودت است که موجب می‌شود به نظر برسد دفاع‌ها ورای کنترل خود تو هستند. اما آنچه تو از یاد برده‌ای می‌تواند به یاد آورده شود، و می‌تواند تو را مصمم کند که در تصمیمت تجدید نظر کنی، تصمیمی که توسط فراموشی به طرز مضاعفی پنهان شده است. به یاد نیاوردن تو تنها نشانه‌ای است که این تصمیم هنوز قدرت دارد، تا آنجا که به خواسته‌های تو مربوط است. این را با واقعیت اشتباه نگیر. دفاع‌ها باید واقعیت‌ها را نشناختنی جلوه دهند. هدف آن‌ها این است، و این کاری است که انجام می‌دهند.

هر دفاعی قطعاتی از کل را می‌گیرد، آنها را بدون توجه به ارتباط حقیقی‌شان به هم متصل می‌کند، و از این طریق اوهامی را از تمامیتی که وجود ندارد می‌سازد. این فرایند است که تهدید را تحمیل می‌کند، و نه هر نتیجه‌ای که حاصل می‌شود. زمانی که بخش‌ها از تمامیت غصب شوند و جداگانه و هر کدام در خودشان تمام دیده شوند، تبدیل به نمادهایی می‌شوند که آماده حمله به تمامیت هستند؛ موفق در تاثیرگذاری، و دیگر هرگز دیگر همانند کل دیده نمی‌شوند. و اما تو فراموش کرده‌ای که آنها فقط به خاطر تصمیم خود تو در مورد اینکه واقعیت چه باید باشد برپا شده‌اند، تا جای آنچه واقعی است را بگیرند.

بیماری یک تصمیم است. چیزی نیست که برای تو اتفاق بیفتد، کاملا غیر‌قابل پیش‌بینی، که تو را ضعیف می‌کند و برایت رنج می‌آورد. بیماری یک انتخاب است که تو انجام می‌دهی، نقشه‌ای که می‌کشی، زمانی که برای لحظه‌ای حقیقت در ذهن توهمی خود تو ظهور می‌کند، و به نظر می‌رسد که همه دنیایت متزلزل می‌شود و آماده فروریختن می‌گردد. اینک که تو بیمار هستی، آن حقیقت می‌تواند دور شود و آنچه تو ساخته‌ای را دیگر تهدید نکند.

چگونه فکر می‌کنی که بیماری می‌تواند در ایجاد سپر برای تو در مقابل حقیقت توفیق یابد؟ زیرا بیماری اثبات می‌کند که بدن از تو جدا نیست، پس تو باید از حقیقت جدا باشی. تو از درد رنج می‌بری زیرا بدن از درد رنج می‌برد، و در این درد تو با آن یکی می‌شوی. چنین است که هویت «حقیقی» تو مکتوم می‌ماند، و این پندار عجیب ماندگار که تو می‌توانی چیزی ورای این توده غبار باشی، ساکت و صامت می‌شود. زیرا می‌بینی، این غبار می‌تواند موجب رنج تو شود، اندام‌هایت را خمیده کند و قلبت را از کار بیاندازد، به تو فرمان مردن بدهد و اینکه دیگر نباشی.

در چنین صورتی بدن قوی‌تر از حقیقت است، بدنی که از تو می‌خواهد زنده بمانی اما نمی‌تواند بر انتخاب تو در مورد مردن غالب شود. این چنین، بدن بسیار قوی‌تر از حیات ابدی است، بهشت* شکننده‌تر از دوزخ، و طرح خداوند* برای رستگاری فرزندش* با تصمیمی معارض می‌شود که قوی‌تر از ارادهٔ* او* است. فرزند* خداوند* غبار است، و پدرش* ناکامل، و آشوب پیروزمندانه بر تخت او* نشسته است.

برنامه‌ریزی تو برای دفاع خودت اینگونه است. و تو باور داری که بهشت* در مقابل حمله‌های دیوانه‌واری مانند این، خود را می‌بازد، زیرا خداوند* با اوهام تو کور شده است، حقیقت به دروغ تبدیل شده است، و تمام جهان برده قانون‌هایی شده است که دفاع‌های تو می‌خواهند بر آن تحمیل کنند. اما چه کسی به اوهام باور دارد جز کسی که آن‌ها را ساخت؟ چه کسی جز او می‌تواند آن‌ها را ببیند و به آن‌ها واکنش نشان دهد، گویی که آن‌ها حقیقت هستند؟

خداوند* از نقشه‌های تو برای تغییر دادن اراده‌‌اش* نمی‌داند. جهان از قانون‌هایی که تو می‌پنداشتی با آن‌ها بر آن حکمرانی می‌کنی پیروی نمی‌کند. و بهشت* به دوزخ تعظیم نکرده است، و زندگی به مرگ کرنش نکرده است. تو فقط می‌توانی انتخاب کنی بیندیشی که بمیری، یا از بیماری رنج ببری یا حقیقت را در هر شکلی مغشوش کنی. آنچه آفریده شده از همه اینها دور است. دفاع‌ها نقشه‌هایی هستند برای شکست دادن آنچه نمی‌تواند مورد حمله قرار گیرد. آنچه تغییر‌ناپذیر است نمی‌تواند تغییر کند. و آنچه که تماماً بی‌گناه است نمی‌تواند گناه کند.

چنین است حقیقت ساده. آن نیز تمایلی به قدرت یا پیروزی ندارد. حقیقت فرمان اطاعت نمی‌دهد، و نیز نمی‌خواهد اثبات کند که تلاشهای تو برای طرح روشهای دفاع که می‌خواهد تغییرش دهد چقدر رقت‌انگیز و بیهوده است. حقیقت صرفاً می‌خواهد به تو شادمانی بدهد، زیرا هدف آن همین است. شاید کمی آه بکشد زمانی که تو هدایای آن را دور می‌اندازی، اما می‌داند، با اطمینان کامل، که آنچه خداوند* برای تو اراده می‌کند باید دریافت شود.

همین واقعیت است که نشان می‌دهد زمان یک وهم است. زیرا زمان به تو اجازه می‌دهد بپنداری آنچه خداوند* به تو داده است همین حالا حقیقت نیست، آنگونه که باید باشد. اندیشه‌های* خداوند* کاملا از زمان جدا هستند. زیرا زمان فقط دفاع بی‌معنای دیگری است که تو بر علیه حقیقت ساخته‌ای . اما آنچه او* اراده می‌کند اینجا است، و تو آنگونه که او* تو را آفرید باقی می‌مانی.

حقیقت دارای قدرتی بسیار فراتر از دفاع است، زیرا هیچ وهمی نمی‌تواند در جایی باقی بماند که حقیقت به آنجا اجازه ورود یافته است. و حقیقت به هر ذهنی می‌آید که سلاح‌های خود را بر زمین بگذارد، و از بازی با حماقت دست بردارد. آن در هر زمانی؛ امروز یافت می‌شود، اگر تو انتخاب کنی که استقبال کردن از حقیقت را تمرین کنی.

امروز این هدف ما است. و ما یک ربع ساعت را دو بار در روز به این اختصاص می‌دهیم آنگونه که بخواهیم حقیقت به سمتمان بیاید و ما را آزاد کند. و حقیقت خواهد آمد، زیرا هرگز جدا از ما نبوده است. حقیقت صرفاً منتظر چنین دعوتی است که ما امروز انجام می‌دهیم. ما تمرین خود را با یک دعای شفا آغاز می‌کنیم، تا کمک کند به فراتر از حالت تدافعی برویم، و اجازه دهیم حقیقت همانگونه باشد که همیشه بوده است: بیماری، دفاعی در مقابل حقیقت است. من حقیقت آنچه را که هستم خواهم پذیرفت، و بگذار ذهن من امروز تماماً شفا یابد.

شفا در ذهن بازِ تو خواهد درخشید، همچنانکه صلح و حقیقت بر می‌خیزند تا جای جنگ و تصورات پوچ را بگیرند. هیچ گوشه‌ی تاریکی باقی نخواهد ماند که بیماری بتواند پنهان کند، و در مقابل نور حقیقت از آن دفاع کند. هیچ شمایل‌های تیره‌ای از رؤیاهای تو وجود نخواهند داشت که در ذهن تو باقی بمانند، و نه تعقیب مبهم و بی‌معنای آن‌ها با قصدهای دوگانه که به طرز دیوانه‌واری طلب شوند. ذهن تو از تمام آرزوهای بیما‌رگونه‌ای که تلاش می‌کرد به بدن اختیار اطاعت از آن‌ها را بدهد، شفا خواهد یافت.

اینک بدن شفا می‌یابد، زیرا سرچشمه بیماری به بهبودی باز شده است. و تو از این طریق تشخیص می‌دهی که به خوبی تمرین کرده‌ای: بدن نباید هیچ احساسی داشته باشد. اگر توفیق یافته باشی، هیچ احساس ناخوشی یا خوب بودن، درد یا لذت نخواهد بود. اصلا هیچ پاسخی در ذهن به آنچه بدن انجام می‌دهد نخواهد بود. فقط فایده آن باقی می‌ماند و نه هیچ چیز دیگری.

شاید تشخیص ندهی که این رویداد محدودیتهایی که تو با دادن اهداف به بدنت به آن تحمیل کرده‌ای را بر طرف می‌کند. با بر طرف شدن اینها، قدرتی که بدن دارد همیشه برای خدمت به همه اهداف واقعاً مفید کافی خواهد بود. سلامتی بدن کاملاً تضمین می‌شود، زیرا دیگر توسط زمان، آب و هوا یا ضعف، توسط غذا و نوشیدنی، یا هر قانونی که تو قبلاً آن را برایش به خدمت گرفته‌ای، محدود نمی‌شود. اینک نیازی نداری هیچ کاری انجام دهی تا حالش خوب شود، زیرا بیماری ناممکن شده است.

اما این محافظت باید با مراقبت دقیق حفظ گردد. اگر اجازه دهی در ذهنت پندارهای حمله مستقر شود، به قضاوت تن دهی یا در برابر بی‌اطمینانیهای آینده نقشه بکشی، دوباره خودت را گم می‌کنی، و یک هویت جسمانی می‌سازی که به بدن حمله خواهد کرد، زیرا ذهن بیمار است.

اگر چنین رخ داد سریعا آن را شفا بده، با این شیوه که اجازه ندهی حالت دفاعی‌ات بیشتر آزارت دهد. در مورد آنچه باید شفا یابد سردرگم نباش، بلکه به خودت بگو: من فراموش کرده‌ام که واقعا چه هستم، زیرا بدنم را با خودم اشتباه گرفتم. بیماری دفاعی در برابر حقیقت است. اما من یک بدن نیستم. و ذهن من نمی‌تواند حمله کند. پس من نمی‌توانم بیمار باشم.', 'https://acim-farsi.org/workbook/lesson/136', 'https://acim-farsi.org/audio/workbook/lesson/136.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (137, 'زمانی که من شفا می‌یابم، به تنهایی شفا نمی‌یابم.', 'زمانی که من شفا می‌یابم، به تنهایی شفا نمی‌یابم. و من برادرانم را برکت می‌دهم، زیرا می‌خواهم به همراه آن‌ها شفا یابم، همان‌گونه که آن‌ها به همراه من شفا می‌یابند.', 'زمانی که من شفا می‌یابم، به تنهایی شفا نمی‌یابم.

ایدهٔ امروز، آن اندیشهٔ محوری باقی می‌ماند که رستگاری بر آن استوار است. زیرا شفا متضاد همهٔ ایده‌های دنیا است، ایده‌هایی که بر بیماری و جدا بودن وضعیت‌ها تأکید دارند. بیماری نوعی کناره‌گیری از دیگران، و امتناع از پیوستن است. بیماری به دری تبدیل می‌شود که به روی یک خود جداگانه بسته می‌شود، و آن را منزوی و تنها نگه می‌دارد.

بیماری یعنی انزوا. زیرا به نظر می‌رسد که بیماری یک فرد را از همهٔ دیگران جدا نگه می‌دارد، تا از آن چیزی رنج ببرد که دیگران احساس نمی‌کنند. آن به بدن قدرت نهایی را می‌دهد که به جدایی واقعیت ببخشد، و ذهن را در زندان انفرادی نگه دارد، تقسیم شده و بازداشته شده به صورت تکه‌تکه پشت دیوار محکمی از جسم بیمار شده، دیواری که نمی‌تواند از آن عبور کند.

دنیا از قوانینی پیروی می‌کند که بیماری در خدمت آن‌ها است، اما شفا از این دو جدا عمل می‌کند. ناممکن است که هیچ کسی بتواند به تنهایی شفا یابد. در بیماری باید جدا و مجزا بود. اما شفا تصمیم خود فرد است تا دوباره یگانه گردد، و خویشتن* خود را با همه‌ی بخشهایش دست نخورده و فارغ از تهاجم بپذیرد. در بیماری به نظر می‌رسد که خویشتن* او چند‌پاره است، و بدون آن وحدتی که به آن حیات می‌بخشد. اما شفا زمانی حاصل می‌شود که او ببیند بدن قدرتی برای حمله به یگانگی* کیهانی فرزند* خداوند* ندارد.

بیماری می‌خواهد اثبات کند که دروغها باید حقیقت باشند. اما شفا نشان می‌دهد که حقیقت، حقیقی است. آن جدایی که بیماری می‌خواهد تحمیل کند، هرگز واقعا رخ نداده است. شفا یافتن صرفاً پذیرفتن آن‌چیزی است که همیشه حقیقت ساده بود، و همیشه دقیقاً آنگونه باقی خواهد ماند که تا ابد بوده است. باید به چشمانی که به اوهام عادت کرده‌اند نشان داده شود که آنچه مشاهده می کرده‌اند نادرست است. پس شفا که حقیقت هرگز به آن نیازی ندارد، باید نشان دهد که بیماری واقعی نیست.

بنابراین شفا را می‌توان یک ضد رؤیا خواند، که رؤیای بیماری را به نام حقیقت منتفی می‌کند، اما نه در خود حقیقت. درست همان‌گونه که بخشایش از همهٔ گناهانی که هرگز انجام نشده‌اند چشم‌پوشی می‌کند، شفا فقط اوهامی را برطرف می‌سازد که رخ نداده‌اند. درست همانگونه که دنیای واقعی بپا می‌خیزد تا جای آنچه که اصلاً هرگز نبوده است را بگیرد، شفا نیز فقط بازیابی را عرضه می‌کند، برای حالتهای تصور شده و ایده‌های اشتباهی که رؤیاها به تصویر حقیقت دوخته‌اند.

اما مپندار که شفا شایسته این نیست که وظیفه تو در این جا باشد. زیرا برای آنانی که در رؤیا می‌بینند که این دنیا واقعی است، ضد-مسیحا از مسیحا قدرتمندتر است. بدن به نظر می‌رسد که محکم‌تر و پایدارتر از ذهن است. و عشق تبدیل به یک رؤیا می‌شود، در حالی که ترس به عنوان یگانه واقعیتی باقی می‌ماند که می‌تواند دیده شود و موجه شود و به طور کامل درک شود.

درست همان‌گونه که بخشایش گناهان را محو می‌کند و دنیای واقعی جای آنچه تو ساختی را می‌گیرد، شفا نیز باید جایگزین تخیلات بیماری شود که تو در مقابل حقیقت ساده قرار داده‌ای. زمانی که دیده شود که بیماری به رغم همهٔ قانون‌هایی که آن را نگه می‌دارند و نمی‌توانند واقعی باشند ناپدید شده است، آنگاه پرسش‌ها پاسخ داده شده‌اند. و آن قوانین دیگر نمی‌توانند بیش از این دنبال شوند و اطاعت شوند.

شفا آزادی است. زیرا شفا نشان می‌دهد که رؤیاها در برابر حقیقت باقی نمی‌مانند. شفا تسهیم می‌شود. و با این ویژگی ثابت می‌کند که قوانینی که برخلاف قوانین معتقد به اجتناب‌ناپذیر بودن بیماری هستند، قوی‌تر از قوانین بیمارگونهٔ ضد خود هستند. شفا قدرت است. زیرا با دست مهربان آن ضعف مغلوب می‌شود، و ذهن‌هایی که درون یک بدن محبوس بودند، آزاد می‌شوند تا به ذهن‌های دیگر بپیوندند و برای همیشه نیرومند باشند.

شفا، بخشایش، و جایگزینی شادمان همهٔ دنیای اندوه با دنیایی که غم نمی‌تواند به آن وارد شود، وسایلی هستند که توسط آنها روح‌القدس* تو را هدایت می‌کند تا از او* پیروی کنی. آموزه‌های مهربانانهٔ او* یاد می‌دهند که به چه راحتی رستگاری می‌تواند از آن تو باشد؛ چقدر تمرین کمی مورد نیاز است تا اجازه دهی قانون‌های او* جایگزین قانون‌هایی شوند که تو ساخته‌ای تا خودت را زندانی مرگ نگه داری. زندگی او* زندگی خود تو می‌شود، آنگاه که تو آن یاری اندکی را گسترش دهی که او* در آزادسازی تو از هرچیزی که هرگز باعث رنجت شده بود، می‌طلبد.

و همچنان که تو به خودت اجازه می‌دهی شفا یابی، می‌بینی که همهٔ کسانی که پیرامون تو هستند، یا هر کسی که به ذهنت بیایید یا هر کسی که تو لمس کنی یا آنان که به نظر می‌رسد هیچ تماسی با تو ندارند، به همراه تو شفا می‌یابند. شاید تو همهٔ آن‌ها را نشناسی، یا تشخیص ندهی که آنچه به همهٔ دنیا عرضه می‌کنی چقدر عظیم است، زمانی که اجازه می‌دهی شفا به سوی تو بیاید. اما تو هرگز به تنهایی شفا نمی‌یابی. و وقتی که تو شفا می‌یابی، گروه پس از گروه آن هدیه را که تو دریافت می‌کنی دریافت خواهند کرد.

آنان که شفا می‌یابند به وسیلهٔ شفا تبدیل می‌شوند. همچنین بین لحظهٔ شفا یافتن آن‌ها زمان نمی‌گذرد، و تمام فیضِ شفا به آن‌ها داده می‌شود تا بدهند. آنچه که ضد خداوند است* وجود ندارد، و آن کس که ضد خداوند* را درون ذهن خود نمی‌پذیرد تبدیل به پناهگاهی می‌شود که خستگان می‌توانند در آن بمانند و آرام بگیرند. زیرا در اینجا حقیقت عطا شده است، و در اینجا همه‌ی اوهام به نزد حقیقت آورده شده‌اند.

آیا نمی‌خواهی پناهگاهی به ارادهٔ* خداوند* عرضه کنی؟ تو تنها خویشتن* خود را دعوت می‌کنی تا در خانه باشد. و آیا این دعوت می‌تواند پذیرفته نشود؟ از آنچه که اجتناب‌ناپذیر است بخواه که رخ دهد، و تو هرگز شکست نخواهی خورد. انتخاب دیگر فقط این است که از آنچه که نمی‌تواند باشد بخواهی که باشد، و این نمی‌تواند به نتیجه برسد. امروز ما می‌طلبیم که فقط حقیقت ذهنمان را اشغال کند؛ تا آن اندیشه‌های شفا امروز از آنچه شفا یافته به سمت آنچه که هنوز باید شفا یابد پیش روند، آگاه از این که هر دوی آن‌ها با هم رخ خواهند داد.

سر هر ساعت به یاد خواهیم آورد که وظیفهٔ ما اجازه دادن به شفای ذهنمان است، و این که می‌توانیم شفا را به دنیا بیاوریم، نفرین را با برکت، درد را با سرور و جدایی را با صلح خداوند* جایگزین کنیم. آیا ارزش ندارد هر ساعت یک دقیقه را به دریافت هدیه‌ای این چنین اختصاص دهیم؟ آیا چنین زمان کمی هزینهٔ ناچیزی برای پرداختن به خاطر موهبت همه‌چیز نیست؟

اما باید برای چنین هدیه‌ای آماده شویم. پس روز را با جمله‌های زیر آغاز می‌کنیم، و ده دقیقه در صبح و شب را به اندیشه درمورد این موضوعات اختصاص می‌دهیم: زمانی که من شفا می‌یابم، به تنهایی شفا نمی‌یابم. و من می‌خواهم شفایم را با دنیا سهیم شوم، تا بیماری بتواند از ذهن فرزند* یگانهٔ خداوند* محو شود، که تنها خویشتن* من است.

بگذار همین امروز شفا در تو جاری شود. و همچنان که در سکوت آرام می‌گیری، آماده شو تا بدهی در حالی که دریافت می‌کنی، تا تنها آنچه را که می‌دهی نگه داری، و کلام* خداوند* را دریافت کنی تا جایگزین تمامی پندارهای نابخردانه‌ای شود که تا به حال تصور شده بودند. اینک ما گرد هم می‌آییم تا هر آنچه را که بیمار بود بهبود ببخشیم، و در جایی که حمله بود برکت را تقدیم کنیم. و اجازه نخواهیم داد که این وظیفه‌ فراموش شود، همان‌گونه که هر ساعت از روز سپری می‌شود، هدف‌مان را با این اندیشه به یاد می‌آوریم: زمانی که من شفا می‌یابم، به تنهایی شفا نمی‌یابم. و من برادرانم را برکت می‌دهم، زیرا می‌خواهم به همراه آن‌ها شفا یابم، همان‌گونه که آن‌ها به همراه من شفا می‌یابند.', 'https://acim-farsi.org/workbook/lesson/137', 'https://acim-farsi.org/audio/workbook/lesson/137.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (138, 'بهشت* آن تصمیم است که من باید بگیرم.', 'بهشت* آن تصمیم است که من باید بگیرم. من اکنون این تصمیم را می‌گیرم، و نظرم را تغییر نخواهم داد، زیرا این تنها چیزی است که می‌خواهم.', 'بهشت* آن تصمیم است که من باید بگیرم.

در این دنیا، بهشت* یک انتخاب است، زیرا ما اینجا باور داریم چیزهای متفاوتی وجود دارند که بین آن‌ها انتخاب کنیم. ما می‌پنداریم که همهٔ چیزها متضاد دارند، و ما آنچه را که می‌خواهیم انتخاب می‌کنیم. اگر بهشت* وجود دارد، دوزخ نیز باید باشد، زیرا ما از طریق تضاد، ادراکمان و آنچه که می‌پنداریم واقعی است را می‌سازیم.

آفرینش هیچ متضادی نمی‌شناسد. اما اینجا بخش متضاد با بودن «واقعی» است. همین ادراک غریب از حقیقت است که موجب می‌شود انتخاب بهشت* مانند انصراف از دوزخ به نظر برسد. واقعا چنین نیست. اما آنچه در آفرینش خداوند* حقیقی است نمی‌تواند وارد اینجا شود مگر اینکه در شکلی انعکاس یابد که دنیا بتواند بفهمد. حقیقت نمی‌تواند به جایی بیاید که فقط می‌تواند با ترس درک شود. زیرا این خطا است که حقیقت می‌تواند به نزد اوهام آورده شود. تضاد مانع استقبال از حقیقت می‌شود، و نمی‌تواند بیاید.

انتخاب ظاهراً فرار از چیزی است که تضاد به نظر می‌رسد. تصمیم اجازه می‌دهد که یکی از اهداف متضاد، هدف تلاش و صرف وقت شود. بدون تصمیم، زمان فقط اتلاف، و تلاش فقط اسراف است. آن در عوض هیچ‌چیز صرف می‌شود، و زمان بدون نتیجه سپری می‌شود. هیچ فایده‌ای وجود ندارد، زیرا هیچ دستاوردی وجود ندارد؛ و هیچ چیزی آموخته نمی‌شود.

تو نیاز داری که به یاد بیاوری که واقعا فقط یک انتخاب وجود دارد، در حالیکه می‌پنداری با هزار انتخاب روبرو هستی. و این یکی هم فقط به نظر می‌رسد یک انتخاب است. خود را با همهٔ تردیدهایی که تصمیم‌های بی‌شمار القا می‌کنند به اشتباه نیانداز. تو تنها یک تصمیم می‌گیری. و وقتی که آن یک تصمیم گرفته شود، تو درک خواهی کرد که آن هرگز انتخاب نبوده است. زیرا حقیقت، حقیقی است و هیچ چیز دیگری حقیقی نیست. هیچ متضادی برای انتخاب جایگزین وجود ندارد. هیچ متضادی برای حقیقت وجود ندارد.

انتخاب به آموختن بستگی دارد. و حقیقت را نمی‌توان آموخت، فقط می‌توان شناخت. در شناختن پذیرفته می‌شود، و با پذیرش دانسته می‌شود. اما معرفت ورای اهدافی است که ما می‌خواهیم در چهارچوب این دوره آموزش دهیم. اهداف ما اهداف آموزشی هستند، که باید از طریق یادگیری نحوه‌ی رسیدن به آن‌ها، آنچه که هستند، و آنچه که به تو ارائه می‌دهند، به دست آیند. تصمیم‌ها نتیجه‌ی یادگیری تو هستند، زیرا آن‌ها بر آن چیزی استوارند که تو به عنوان حقیقتِ آنچه که هستی پذیرفته‌ای، و این که نیازهای تو چه باید باشند.

در این دنیای پیچیده از دیوانگی، به نظر می‌رسد که بهشت* شکل انتخاب را گرفته، به جای این که صرفاً چیزی باشد که هست. از میان همه‌ی انتخاب‌هایی که تو کوشیده‌ای انجام دهی این آسانترین است، قطعی‌ترین و اصلی‌ترین از همهٔ انتخاب‌های دیگر، انتخابی که همه‌ی تصمیم‌ها را معین می‌کند. اگر تو می‌توانستی بقیه را تصمیم بگیری، این یکی حل نشده باقی می‌ماند. اما وقتی این یکی را حل کنی، بقیه هم به همراه آن حل می‌شوند، زیرا همهٔ تصمیم‌ها فقط این یکی را با گرفتن شکل‌های متفاوت به خود پنهان می‌کنند. اینجا آخرین و تنها انتخاب وجود دارد که در آن حقیقت یا پذیرفته می‌شود، یا انکار.

پس امروز توجه کردن به انتخابی را آغاز می‌کنیم که زمان در اصل برای کمک به ما در انجام آن، ساخته شد. این هدفِ مقدسِ آن است، که اینک از قصدی که تو به آن دادی تغییر می‌کند؛ که ابزار واقعی نشان دادن دوزخ، تبدیل امید به یأس، و در پایان غلبهٔ مرگ بر خود زندگی بود. فقط در مرگ متضادها حل می‌شوند، زیرا تضاد پایانی مردن است. و اینگونه رستگاری باید همانند مرگ دیده شود، زیرا زندگی همانند تعارض دیده شده است. حل کردن تعارض پایان دادن به زندگی تو نیز هست.

این باورهای دیوانه‌وار می‌توانند موفق به کنترل ناخودآگاه بسیار شدید شوند، و ذهن را به چنان وحشت و‌ اضطراب نیرومندی دچار کنند که آن نتواند ایده‌های خود را درباره‌ی محافظت از خودش رها کند. ذهن باید از رستگاری نجات یابد، تهدید شود تا امنیت یابد، و به طرزی جادویی در برابر حقیقت زره‌پوش شود. و این تصمیم‌ها به صورت ناآگاهانه گرفته می‌شوند، تا بدون هیچ مزاحمتی محافظت شوند؛ دور از پرسش و دور از خرد و دور از تردید.

بهشت* آگاهانه انتخاب می‌شود. تا زمانی که جایگزین‌ها به طور دقیق دیده و درک نشوند، انتخاب نمی‌تواند انجام شود. هر آنچه که در سایه‌ها پوشانده شده باید به فهم آید، تا دوباره قضاوت شود، این بار با کمک یاریگر بهشتی*. و همههٔ اشتباهاتی که ذهن در قضاوت انجام داده بود قابل اصلاح هستند، با رد شدن توسط حقیقت به عنوان آنچه که بی‌علت است. اینک آن‌ها بدون اثر هستند. آن‌ها نمی‌توانند پنهان کرده شوند، زیرا هیچ بودنشان تشخیص داده شده است.

انتخاب آگاهانهٔ بهشت* به همان اندازه قطعی است که پایان ترس از دوزخ، زمانی که از پوشش محافظتی ناآگاهی در آورده شود، و به نور آورده شود. چه کسی می‌تواند بین آنچه که به روشنی دیده می‌شود و آنچه که ناشناخته است تصمیم بگیرد؟ با این حال چه کسی می‌تواند در انتخاب میان جایگزین‌ها شکست بخورد وقتی که تنها یکی از آن‌ها با ارزش دیده شود؛ و دیگری به عنوان یک چیز به تمامی بی‌ارزش دیده شود، فقط یک منبع خیالی از احساس گناه و درد؟ چه کسی در انجام انتخابی مانند این تردید می‌کند؟ و آیا امروز ما باید در انتخاب کردن تردید کنیم؟

با بیدار شدن انتخاب بهشت* را انجام می‌دهیم و پنج دقیقه را صرف می‌کنیم تا مطمئن شویم تنها تصمیم عاقلانه را گرفته‌ایم. تشخیص می‌دهیم که انتخابی آگاهانه انجام داده‌ایم بین یک چیز موجود و چیزی که فقط ظاهر حقیقت را دارد. وجود کاذب آن، به نزد آنچه که حقیقی است آورده شده، در نور سست و شفاف است. اکنون آن هیچ وحشتی ندارد، زیرا آنچه که عظیم، انتقامجو، بی‌رحم با نفرت ساخته شده بود، اینک مبهم بودن را می‌طلبد تا ترس در آنجا نهاده شود. اینک آن به عنوان یک اشتباه احمقانه و ناچیز تشخیص داده می‌شود.

شب پیش از بستن چشمانمان برای خواب، برای پنج دقیقه باز بر انتخابی که در هر ساعت روز انجام داده‌ایم، تاکید می‌کنیم. و اکنون ما پنج دقیقه آخر روز بیداری خود را به آن تصمیم اختصاص می‌دهیم که با آن بیدار شدیم. سر ساعت، انتخابمان را دوباره در سکوتی مختصر که وقف داشتن عقلانیت کرده‌ایم، اعلام می‌کنیم. و سرانجام روزمان را با این جملات به پایان می‌بریم، با تشخیص اینکه ما فقط آنچه را که می‌خواهیم انتخاب کرده‌ایم: بهشت* آن تصمیم است که من باید بگیرم. من اکنون این تصمیم را می‌گیرم، و نظرم را تغییر نخواهم داد، زیرا این تنها چیزی است که می‌خواهم.', 'https://acim-farsi.org/workbook/lesson/138', 'https://acim-farsi.org/audio/workbook/lesson/138.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (139, 'من آمرزش* را برای خودم می‌پذیرم.', 'من آمرزش* را برای خودم خواهم پذیرفت، زیرامن آنگونه که خداوند* مرا آفرید باقی می‌مانم.', 'من آمرزش* را برای خودم می‌پذیرم.

اینجا پایان انتخاب است. زیرا اینجا ما به تصمیمی می‌رسیم که خودمان را همانگونه که خداوند* ما را آفرید، بپذیرم. و انتخاب چیست جز عدم اطمینان به آنچه ما هستیم؟ هیچ شکی نیست که ریشه‌اش اینجا نباشد. هیچ پرسشی نیست که این یک پرسش را انعکاس ندهد. هیچ تعارضی نیست که در پی این تک پرسش ساده نیاید، «من چه هستم؟»

اما چه کسی می‌تواند این پرسش را بپرسد مگر او که از شناختن خودش سر باز زده است؟ فقط سر باز زدن از پذیرش خودت می‌تواند این پرسش را خالصانه جلوه دهد. تنها چیزی که می‌تواند با اطمینان توسط هر چیز زنده شناخته شود این است که چیست. از همین نقطه‌ی اطمینان، این وجود به وجودهای دیگر به اندازه‌ی خودش با اطمینان می‌نگرد.

عدم اطمینان در مورد آنچه تو باید باشی، خودفریبی در چنان مقیاسی است که بزرگی آن را به سختی می‌توان درک کرد. زنده بودن و نشناختن خودت باور داشتن به این است که تو واقعاً مرده‌ای. زیرا زندگی چیست جز اینکه خودت باشی، و چه چیزی جز تو می‌تواند در عوضِ مردن زنده باشد؟ آن‌کس که شک می‌کند کیست؟ او به چه چیزی شک دارد؟ از چه کسی می‌پرسد ؟ چه کسی می‌تواند به او پاسخ دهد؟

او صرفا بیان می‌کند که خودش نیست، بنابراین، در حالی که چیز دیگری است، به یک پرسشگر تبدیل می‌شود که آن چیز دیگر چیست. اما او هرگز نمی‌توانست اصلا زنده باشد مگر آنکه پاسخ را می‌دانست. اگر او می‌پرسد انگار که نمی‌داند، این پرسش صرفا نشان می‌دهد که نمی‌خواهد چیزی باشد که هست. او این را پذیرفته است زیرا زندگی می‌کند؛ بر علیه آن قضاوت کرده است و ارزشش را انکار کرده است، و تصمیم گرفته است که تنها مایه‌ی اطمینانی را که توسط آن زنده است را نداند.

اینچنین او از زندگی خود نامطمئن می‌شود، زیرا آنچه که زندگی هست توسط وی انکار شده است. به دلیل این انکار است که تو نیاز به آمرزش* داری. انکار تو هیچ تغییری در آنچه که هستی ایجاد نکرده است. اما تو ذهنت را تقسیم کرده‌ای به بخشی که حقیقت را می‌داند و بخشی که حقیقت را نمی‌داند. تو خودت هستی. هیچ شکی در این نیست. اما تو به آن شک می‌کنی. اما تو نمی‌پرسی کدام بخش از تو می‌تواند واقعا به خودت شک کند. واقعا هیچ بخشی از تو نمی‌تواند این پرسش را بپرسد. زیرا از کسی می‌پرسد که پاسخ را می‌داند. اگر بخشی از تو بود، آنگاه اطمینان ناممکن می‌شد.

آمرزش* این ایده غریب را که شک داشتن به خودت ممکن است، شفا می‌دهد، و بی‌اطمینانی از اینکه تو واقعا چه هستی. این عمق دیوانگی است. اما این پرسش فراگیر دنیا است. این چه معنایی دارد به جز دیوانه بودن دنیا ؟ چرا دیوانگی دنیا را در باور غمگنانه به حقیقت داشتن آنچه در اینجا فراگیر است، بپذیریم؟

هیچ چیزی که دنیا باور دارد حقیقت ندارد. این دنیا مکانی است با این هدف که خانه‌ای باشد تا در آن کسانی که مدعی هستند خودشان را نمی‌شناسند بتوانند بیایند و بپرسند که چه هستند. و آن‌ها باز خواهند آمد تا زمانی که آمرزش* پذیرفته شود، و بیاموزند ناممکن است که به خودت شک داشته باشی، و از آنچه که هستی آگاه نباشی.

از تو فقط می‌توان انتظار پذیرش داشت، زیرا آنچه که تو هستی قطعی است. آنچه که تو هستی برای همیشه در ذهن* مقدس خداوند*، و در ذهن خودت درج است. آنچه که تو هستی بسیار فراتر از هر گونه شک و تردید است، آنقدر که پرسیدن این که آن چه باید باشد تمام مدرکی است که تو نیاز داری تا نشان دهی که تو تضادی را باور داری که تو آنچه را که نمی‌توانی در شناختنش شکست بخوری را نمی‌شناسی. آیا این یک پرسش است، یا جمله‌ای که با بیان شدنش خود را انکار می‌کند؟ بگذار اجازه ندهیم ذهن‌های مقدس ما خود را با مشغولیتهای بیهوده مانند این مشغول کنند.

ما اینجا یک مأموریت داریم. ما نیامدیم تا آن دیوانگی را که زمانی به آن باور داشتیم تقویت کنیم. بگذار از یاد نبریم هدفی را که پذیرفتیم. این بیش از صرفاً شادی ما به تنهایی است که آمده‌ایم تا کسب کنیم. آنچه می‌پذیریم که هستیم، اعلان این است که همگان، به همراه ما چه باید باشند. موجب شکست برادران خود نشو، که خودت را به شکست می‌کشانی. به آنها عاشقانه بنگر، تا بلکه بدانند بخشی از تو هستند، و تو بخشی از آنان.

آمرزش* چنین می‌آموزد، و نشان می‌دهد که یگانگی فرزند* خداوند* توسط این باورش که نمی‌داند چیست، مورد تهاجم قرار نمی‌گیرد. امروز آمرزش* را بپذیر، واقعیت را تغییر نده، بلکه صرفاً حقیقت را در مورد خودت بپذیر، و طریق خود را در شادمانی کردن با عشق* بی‌پایان خداوند* دنبال کن. تنها انجام این از ما خواسته شده است. و ما امروز فقط این را انجام خواهیم داد.

پنج دقیقه در صبح و در شب را اختصاص می‌دهیم به پیشکش کردن ذهن‌هایمان به مأموریت امروز. با این مرور مأموریت خود آغاز می‌کنیم: من آمرزش* را برای خودم خواهم پذیرفت، زیرامن آنگونه که خداوند* مرا آفرید باقی می‌مانم. ما آن معرفت را که خداوند* زمانی که ما را مانند خودش* آفرید به ما داد، گم نکرده‌ایم . می توانیم آن را برای همگان به یاد آوریم، زیرا در آفرینش همه ذهن‌ها یکی هستند. ودر حافظهٔ ما فراخوان اینکه برادرانمان در حقیقت چقدر برای ما عزیز هستند وجود دارد، و اینکه هر ذهنی تا چه اندازه بخشی از ما است، آن‌ها واقعا چقدر به ما وفادار بوده‌اند، عشق* پدرمان* چقدر تمامی آنان را در بر می‌گیرد.

در سپاس برای همهٔ آفرینش، به نام* آفریدگارش* و یگانگی او* با همه جنبه‌های آفرینش، ما ایثار خود را برای وظیفهٔ امروزمان هر ساعت تکرار می‌کنیم، در حالی که همهٔ افکاری را که ما را از هدف مقدسمان دور می‌سازند کنار می‌گذاریم. برای چند دقیقه اجازه بده ذهنت ازهمه تار عنکبوتهای احمقانه‌ای که دنیا می‌خواهد پیرامون فرزند* خداوند* بتند، پاک شود. و ماهیت شکننده زنجیرهایی را که به نظر می‌رسد شناخت تو را از خودت، از آگاهی تو دور نگه می‌دارند بیاموز، در حالی که می‌گویی: من آمرزش* را برای خودم می‌پذیرم، زیرا من آنگونه که خداوند* مرا آفرید باقی می‌مانم.', 'https://acim-farsi.org/workbook/lesson/139', 'https://acim-farsi.org/audio/workbook/lesson/139.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (140, 'فقط رستگاری است که می‌تواند شفا شمرده شود.', 'فقط رستگاری را می‌توان شفا دهنده خواند. پدر* با ما سخن بگو، تا بتوانیم شفا یابیم.', 'فقط رستگاری است که می‌تواند شفا شمرده شود.

«شفا» کلمه‌ای است که نمی‌تواند به هر دارویی که دنیا مفید می‌داند اطلاق گردد. آنچه که دنیا درمانی درک می‌کند، صرفا چیزی است که بدن را «بهتر» می‌کند. زمانی که آن تلاش کند ذهن را شفا بخشد، هیچ جدایی از بدن نخواهد دید، جایی که می‌اندیشد ذهن وجود دارد. در این صورت شکل‌های شفاگری آن باید وهم را با وهم جایگزین سازد. یک باور به بیماری شکل دیگری را به خود می‌گیرد، و از این رو بیمار خودش را بهبود یافته می‌داند.

او شفا نیافته است. او صرفا رؤیایی داشته است که بیمار بود، و در رؤیا یک فرمول جادویی یافته است که او را بهتر می‌کند. اما او از رؤیا بیدار نشده است، بنابر این ذهنش دقیقاً همانطور مانده که قبلا بوده. او آن نوری را که می‌خواهد بیدارش کند و به رؤیا پایان دهد را ندیده است. محتوای یک رؤیا چه تغییری را می‌تواند در واقعیت ایجاد کند؟ یک نفر یا می‌خوابد یا بیدار می‌شود. چیزی میان این دو وجود ندارد.

رؤیاهای شادمان که روح‌القدس* به ارمغان می‌آورد با رؤیا‌پروری دنیا متفاوت هستند، دنیایی که در آن فقط می‌توان رؤیای بیدار بودن را داشت. رؤیاهایی که بخشایش به ذهن اجازه می‌دهد آن‌ها را ادراک کند، نوع دیگری از خواب را موجب نمی‌شود، چنانکه رؤیابین رؤیای دیگر را ببیند. رؤیاهای شادمان او، منادیان طلوع حقیقت در ذهن هستند. آنها خواب را به سمت بیداری ملایم هدایت می‌کنند، چنانکه رؤیاها بروند. و در این صورت آنها برای همهٔ ابدیت شفا می‌بخشند.

آمرزش* با اطمینان شفا می‌دهد، و همه بیماری‌ها را به شفا می‌رساند. زیرا ذهنی که می‌فهمد بیماری نمی‌تواند چیزی جز یک رؤیا باشد، توسط شکل‌هایی که رؤیا به خود می‌گیرد، فریب نمی‌خورد. بیماری نمی‌تواند در جایی که احساس گناه غایب است بیاید، زیرا بیماری صرفاً شکل دیگری از احساس گناه است. تاوان*، بیمار را شفا نمی‌دهد، زیرا شفا چنین نیست. آمرزش* احساس گناه را بر طرف می‌سازد، احساس گناهی که بیماری را ممکن می‌کند. و آن در حقیقت شفا است. زیرا در این حال بیماری رفته است، بدون هیچ چیزی که باقی مانده باشد تا بتواند به آن برگردد.

صلح نثار تو باد که در خداوند* شفا یافته‌ای، و نه در رؤیاهای پوچ. زیرا شفا باید از قداست بیاید، و قداست را نمی‌توان در جایی یافت که گناه پرورده می‌شود. خداوند* در معبدهای مقدس ساکن است. زمانی که گناه وارد شده باشد، جلوی او گرفته می‌شود. اما هیچ مکانی نیست که او آنجا نباشد. بنابراین گناه هیچ مکانی نمی‌تواند داشته باشد تا در آن از فضل خداوند* پنهان شود. هیچ مکانی نیست که در آن قداست نباشد، هیچ مکانی برای اسکان گناه و بیماری نیست.

این آن اندیشه است که شفا می‌دهد. فکری که تمایزی بین غیر واقعیت‌ها قائل نمی‌شود. و نیز نمی‌طلبد چیزی را شفا دهد که بیمار نیست، بدون توجه به اینکه نیاز به شفا در کجا است. این جادو نیست. این صرفاً درخواستی برای حقیقت است، که قطعاً شفا می‌دهد و برای همیشه شفا می‌دهد. این فکری نیست که یک وهم را براساس اندازه آن، وزن ظاهری آن، یا هرچیزی مربوط به شکلش قضاوت می‌کند. این فکر صرفاً بر آنچه که هست تمرکز می‌کند، و می‌داند که هیچ وهمی نمی‌تواند واقعی باشد.

بگذار امروز تلاش نکنیم شفا را برای آنچه نمی‌تواند از بیماری رنج ببرد، طلب کنیم. به دنبال شفا باید فقط در جایی گشت که وجود دارد، و سپس آن را برای آنچه بیمار است اِعمال کرد، تا بتواند شفا یابد. دنیا هیچ دارویی را نمی‌تواند فراهم آورد که بتواند تغییر در چیزی را تحت تاثیر قرار دهد. آن ذهنی که اوهام را نزد حقیقت می‌آورد، واقعاً تغییر می‌کند. هیچ تغییری جز این وجود ندارد. زیرا چگونه یک وهم می‌تواند از وهم دیگر به جز در صفاتی که هیچ موجودیت، هیچ واقعیت، هیچ پایه و هیچ چیز حقیقتا متفاوتی ندارند، متفاوت باشد؟

امروز ما می‌طلبیم ذهن خودمان را در مورد سرچشمهٔ بیماری تغییر دهیم، زیرا ما طالب شفایی برای همه اوهام هستیم، نه تغییر دیگری در میان آن‌ها. امروز ما تلاش می‌کنیم سرچشمهٔ شفا را بیابیم، که در ذهن ما هست زیرا پدرمان* آن را برایمان در آنجا نهاده است. شفا از ما دورتر از خودمان نیست. شفا به اندازهٔ اندیشه‌های خودمان به ما نزدیک است؛ آنچنان نزدیک که گم کردنش ناممکن است. ما فقط نیاز داریم آن را بطلبیم، و قطعا یافت می‌شود.

امروز ما با آنچه ظاهراً برایمان بیمار شمرده می‌شود، گمراه نخواهیم شد. امروز ما فراتر از ظواهر می‌رویم و به سرچشمهٔ شفا دست می‌یابیم، که هیچ چیز از آن مستثنی نیست. ما تا آن حد موفق خواهیم شد که متوجه می‌شویم هرگز تمایز معناداری بین آنچه که غیرحقیقی است و آنچه که به همان اندازه غیرحقیقی است، نمی‌تواند وجود داشته باشد. اینجا هیچ درجاتی وجود ندارد، و هیچ نوع باوری وجود ندارد که آنچه وجود ندارد به شکلی حقیقی‌تر از دیگر چیزها است. همهٔ آن‌ها غیرحقیقی هستند، و می‌توانند شفا یابند زیرا حقیقی نیستند.

سپس ما همهٔ باطل و سحرهای خود، افسون و داروهای خود، ذکرهایمان به قطعات جادویی که هر شکلی به خود می‌گیرند را کنار می‌گذاریم. ما آرام خواهیم بود و به آوای* شفا گوش فرا خواهیم داد، که همهٔ بیماری‌های ما را یک‌جا علاج خواهد کرد، و خردمندی را به فرزند* خداوند* باز خواهد گرداند. هیچ آوایی جز این نمی‌تواند شفا دهد. امروز ما آوای* یگانه‌ای را می‌شنویم که از حقیقت با ما می‌گوید، جایی که همهٔ اوهام پایان می‌یابند، و صلح به منزل ابدی و آرام خداوند*، باز می‌گردد.

ما با شنیدن او* از خواب بر خواهیم خاست، و به او* اجازه می‌دهیم در آغاز روز پنج دقیقه با ما سخن بگوید، و دوباره روز را با پنج دقیقه دیگر گوش کردن به او* پیش از خواب به پایان می‌بریم . تنها آمادگی ما این است که اجازه دهیم افکار مداخله‌گر ما کنار گذاشته شوند، نه جدا جدا، بلکه همهٔ آن‌ها یک‌جا. آن‌ها همه یکسان هستند. ما نیازی نداریم تفاوتی بینشان قائل شویم، و از این طریق زمانی را که می‌توانیم به شنیدن سخن پدرمان* اختصاص دهیم به عقب بیاندازیم. ما او* را اکنون می‌شنویم. امروز ما به نزد او* می‌آییم.

بدون هیچ چیزی در دستان ما که به آن آویزان شویم، با قلبهایی برانگیخته و ذهن‌هایی شنوا نیایش می‌کنیم: فقط رستگاری را می‌توان شفا دهنده خواند. پدر* با ما سخن بگو، تا بتوانیم شفا یابیم. و ما احساس خواهیم کرد که رستگاری با حفاظت لطیف خود ما را در بر می‌گیرد، و با صلحی آنچنان عمیق که هیچ وهمی نمی‌تواند ذهن‌های ما را آشفته سازد، و نتواند هیچ گواهی را به ما ارائه کند که واقعیت دارد. امروز ما این را خواهیم آموخت. و نیایش شفای خود را هر ساعت انجام خواهیم داد، و سر هر ساعت یک دقیقه را به شنیدن پاسخ نیایش‌مان در سکوت و سرور اختصاص خواهیم داد. امروز آن روز است که شفا به سوی ما می‌آید. امروز آن روز است که جدایی پایان می‌یابد، و به یاد می‌آوریم که واقعا که* هستیم.', 'https://acim-farsi.org/workbook/lesson/140', 'https://acim-farsi.org/audio/workbook/lesson/140.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
