INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (151, 'همهٔ چیزها بازتاب‌های آوای* خداوند* هستند.', 'همهٔ چیزها بازتاب‌های آوای* خداوند* هستند.', 'همهٔ چیزها بازتاب‌های آوای* خداوند* هستند.

هیچ‌کس نمی‌تواند بر اساس شواهد نسبی قضاوت کند. این قضاوت نیست. این صرفا نظری است بر اساس جهل و تردید. اطمینان ظاهری آن صرفا لفافی است برای بی‌اطمینانی‌ای که می‌خواهد پنهان کند. این نیاز به دفاع غیر‌منطقی دارد زیرا غیرمنطقی است. و دفاع آن به نظر قوی و قانع کننده و بدون تردید می‌رسد زیرا همه تردیدها در زیر آن پنهان هستند.

به نظر نمی‌رسد که تو به دنیایی که می‌بینی تردید کنی. تو واقعا آنچه را که از طریق چشمان بدن به تو نشان داده می‌شود مورد پرسش قرار نمی‌دهی. همچنین نمی‌پرسی که چرا آن را باور می‌کنی، اگر چه تو از زمانی که فهمیدی حواست فریب می‌دهند بسیار آموخته‌ای. اینکه تو آن‌ها را با دقیق‌ترین جزئیاتی که به تو عرضه می‌کنند باور داری حتی عجیب‌تر است، زمانی که کافی است درنگ کنی تا به یاد آوری که بارها و بارها آن‌ها حقیقتاً شواهد نادرست را ارائه داده‌اند! چرا می‌خواهی اینچنین بی قید و شرط به آنها اعتماد کنی؟ چرا؟ جز به دلیل تردید بنیادینت، که می‌خواهی با نمایش اطمینان پنهان کنی؟.

چگونه می‌توانی قضاوت کنی؟ قضاوت تو بر مبنای شواهدی انجام می‌گیرد که حواست به تو عرضه کرده‌اند. اما شواهدِ نادرست‌تر از این وجود نداشته است. اما تو دیگر چگونه دنیایی را که می‌بینی قضاوت می‌کنی؟ تو ایمان رقَت‌آمیزی به آنچه که چشم‌ها و گوشهایت به تو گزارش می‌کنند داری. تو می‌پنداری انگشتانت واقعیت را لمس می‌کنند، و چیزی نزدیک به حقیقت. این آگاهی است که تو درک می‌کنی، و می‌پنداری که واقعی‌تر است از آنچه توسط آوای* ابدی خود* خداوند* بر آن گواهی داده می‌شود.

آیا این می‌تواند قضاوت باشد؟ تو اغلب هدایت می‌شوی که از قضاوت کردن خودداری کنی، نه به خاطر اینکه قضاوت حقی است که از تو سلب شود. تو نمی‌توانی قضاوت کنی. تو صرفاً می‌توانی قضاوت‌های نفس را باور کنی، که همهٔ آن‌ها غیرحقیقی هستند. نفس حواس تو را به دقت هدایت می‌کند تا ثابت کند که تو چقدر ضعیف هستی؛ چقدر درمانده و هراسان، چقدر نگران مجازات عادلانه، چقدر تیره با گناه، چقدر پست در احساس گناهت.

نفس از این سخن می‌گوید، اما می‌خواهد دفاع کند، می‌گوید خویشتن تو است. و تو این را با اطمینانی لجوجانه باور می‌کنی. اما در زیر این اطمینان، تردیدِ پنهان باقی می‌ماند که آنچه نفس به عنوان واقعیت با چنین اعتقاد راسخی به تو نشان می‌دهد، خودش باور ندارد. نفس فقط خودش را محکوم می‌کند. در خودش است که احساس گناه را می‌بیند. ناامیدی خودش است که آن را در تو می‌بیند.

به آوای او گوش نده. گواهانی که به تو عرضه می‌کند تا اثبات کند شرارت او از آن خود تو است نادرست هستند، و با اطمینان از چیزی سخن می‌گویند که نمی‌دانند. ایمان تو به آنان کور است زیرا تو نمی‌خواهی در تردید‌هایی سهیم شوی که اربابشان نمی‌تواند آن‌ها را کاملا مغلوب کند. تو باور می‌کنی که شک کردن به این رعیت‌های نفس شک کردن به خودت است.

اما تو باید بیاموزی به اینکه گواهی آن‌ها راه شناختن خودت را آشکار خواهد کرد تردید کنی، و اجازه دهی آوای* خداوند* به تنهایی قضاوت کند که چه چیزی برای باور خود تو ارزشمند است. او* به تو نخواهد گفت که برادرت را باید توسط آنچه چشمانت در او می‌بیند قضاوت کنی، و نه توسط آنچه دهان بدن او به گوشهایت می‌گوید، و نه توسط آنچه لمس انگشتانت از او گزارش می‌کند. او* فراتر از چنین گواهان بیهوده‌ای است، که صرفا گواهی نادرستی را از فرزند* خداوند* می‌دهند. او* فقط آنچه را که خداوند* به آن عشق می‌ورزد تشخیص می‌دهد، و در نور مقدس آنچه خداوند* می‌بیند، همهٔ رؤیاهای نفس از اینکه تو چه هستی در برابر شکوهی که او می‌بیند ناپدید می‌شوند.

بگذار او* قاضی* آنچه تو هستی باشد، زیرا او* اطمینانی دارد که در آن هیچ تردیدی نیست، زیرا او* در اطمینان* چنان عظیمی ساکن است که پیش چهره‌اش* تردید بی‌معنا است. مسیحا* نمی‌تواند به خودش* تردید کند. آوای* خداوند* تنها می‌تواند او را گرامی بدارد، سرخوش از بی‌گناهی کامل جاودانش. آنکس که او* قضاوتش کرده باشد، فقط می‌تواند به احساس گناه بخندد، در حالی که اکنون از بازی کردن با بازیچه‌های گناه پرهیز می‌کند؛ بی‌اعتنا به گواهان بدن در برابر جذبهٔ چهرهٔ* مسیحا*.

و این چنین او* تو را قضاوت می‌کند. کلام* او* را درمورد آنچه هستی بپذیر، زیرا او* گواهانی از آفرینش زیبای تو را حمل می‌کند، و آن ذهن* که اندیشههٔ* آن* واقعیت تو را آفرید. بدن چه معنایی می‌تواند داشته باشد برای کسی که شکوه پدر* و فرزندش* را می‌داند؟ او* کدام نجواهای نفس را می‌تواند بشنود؟ چه چیزی می‌تواند او* را قانع کند که گناهان تو واقعی هستند؟ اجازه بده او* قاضی* همهٔ چیزهایی باشد که به نظر می‌رسد در این دنیا برایت رخ می‌دهد. درس‌های او* تو را قادر خواهند کرد بر فاصلهٔ بین اوهام و حقیقت پل بزنی.

او* همهٔ ایمانی را که تو به درد، فلاکت، رنج و فقدان داری برطرف خواهد کرد. او* به تو رؤیتی را می‌دهد که می‌تواند به ورای این ظواهر ترسناک نگاه کند، و می‌تواند چهرهٔ مهربان مسیحا* را در همهٔ آن‌ها ببیند. تو دیگر تردیدی نخواهی داشت که تنها خیر می‌تواند به نزد تو بیاید که معشوق خداوند* هستی، زیرا او* قاضی همهٔ رخدادها خواهد بود، و درس یگانه‌ای را که همهٔ آنان در خود دارند آموزش خواهد داد.

او* در آن‌ها اجزایی را که حقیقت را متجلی می‌کنند انتخاب خواهد کرد، و آن جنبه‌هایی را که فقط رؤیاهای پوچ را منعکس می‌سازند، نادیده خواهد گرفت. و او* همهٔ آنچه را که تو می‌بینی، و همهٔ رویدادها، همهٔ شرایط، همهٔ رخدادهایی که به نظر می‌رسد تو را به هر شکلی لمس می‌کنند را از قالب یگانه مرجع خود باز‌تفسیر خواهد کرد، قالبی تماماً یگانه و مطمئن. و تو عشق را ورای نفرت خواهی دید، ثبات را در تغییر، خلوص را در گناه، و فقط تبرک بهشت* را در دنیا.

چنین است رستاخیز تو، زیرا زندگی تو بخشی از هر چیزی که می‌بینی نیست. زندگی تو فراتر از بدن و دنیا، فراتر از هر گواهی بر نامقدس بودن قرار دارد، درون حوزهٔ قدسی، در حالی که خودش* مقدس است. در هر کس و هر چیزی، آوای* او* می‌خواهد با تو تنها و تنها از خویشتن* تو و آفریدگارت* سخن بگوید، که با او* یگانه است. این‌چنین تو چهرهٔ مقدس مسیحا* را در همه چیز خواهی دید، و در همه چیز تنها و تنها بازتاب آوای* خداوند* را خواهی شنید.

امروز ما بی‌کلام تمرین می‌کنیم، جز در آغاز زمانی که به همراه خداوند* می‌گذرانیم. ما این زمان‌ها را فقط با یک بار تکرار آهسته از آن اندیشه که روز را با آن آغاز می‌کنیم، شروع می‌کنیم. و سپس افکارمان را نظاره می‌کنیم، و در سکوت جذب او* می‌شویم که عناصر حقیقت را در این افکار می‌بیند. اجازه بده که او* هر اندیشه‌ای را که به ذهنت می‌آید ارزیابی کند، عناصر رؤیاها را حذف کند، و اندیشه‌هایت را دوباره در شکل ایده‌هایی پاک که با ارادهٔ* خداوند* مخالفت نمی‌کنند، به تو باز گرداند

اندیشه‌هایت را به او* بده، و او* آن‌ها را به تو به صورت معجزاتی پس خواهد داد که تمامیت و شادمانی را که خداوند* برای فرزندش* اراده می‌کند، شادمانه علنی می‌سازند، به عنوان گواهی از عشق* ابدی او*. و در حالی که هر اندیشه‌ای این چنین دگرگون می‌شود، از آن ذهن* قدرت شفا را دریافت می‌کند که حقیقت را در آن دید، و نمی‌تواند توسط آنچه به نادرستی به آن اضافه شده است فریب بخورد . همه بندهای تخیل محو می‌شود . و آنچه باقی می‌ماند به شکل یک اندیشهٔ* بی‌نقص وحدت می‌یابد که بی‌نقصی خود را همه جا عرضه می‌کند.

این‌چنین پانزده دقیقه را پس از بیداری سپری کن، و شادمانه پانزده دقیقه دیگر را پیش از به خواب رفتن بگذران. مأموریت تو با خالص شدن همه افکارت آغاز می‌شود. این‌چنین به تو آموخته می‌شود که به فرزند* خداوند* درس مقدس تعالی او* را بیاموزی. هیچ‌کس نمی‌تواند گوش فرا ندهد، زمانی که تو آوای* خداوند* را که فرزند* خداوند* را تکریم می‌کند، می‌شنوی. همگان در این اندیشه‌ها با تو سهیم می‌شوند، اندیشه‌هایی که او* در ذهن تو بازترجمه کرده است.

چنین است عید* پاک* تو. و چنین تو هدیهٔ سوسن سفیدِ برفی را به دنیا می‌دهی، تا جایگزین شواهد گناه و مرگ شود. از طریق دگرگونی تو این دنیا نجات می‌یابد، و شادمانه از احساس گناه خلاص می‌شود. اینک ما ذهن‌های رستاخیز یافته خود را از شادمانی و در سپاس برای او* که عقلانیت را به ما بازگرداند، بر می‌افرازیم.

و ما هر ساعت او* را که رستگاری و رهایی است به یاد خواهیم آورد. با سپاسگزاری از او*، دنیا با ما یگانه می‌شود و شادمان افکار مقدسمان را می‌پذیرد، افکاری که بهشت* تصحیح کرده و خالص ساخته است . اینک سرانجام دورهٔ مأموریت ما آغاز شده، تا این اخبار شادمان را که حقیقت هیچ وهمی ندارد، و صلح خداوند*، از طریق ما، متعلق به همگان است را به سراسر دنیا برسانیم.', 'https://acim-farsi.org/workbook/lesson/151', 'https://acim-farsi.org/audio/workbook/lesson/151.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (152, 'قدرت تصمیم‌گیری از آن خود من است.', 'قدرت تصمیم‌گیری از آن خود من است.
امروز من خودم را آنگونه که ارادهٔ پدرم* آفرید تا باشم، خواهم پذیرفت.
امروز من خودم را آنگونه که ارادهٔ پدرم* آفرید تا باشم، خواهم پذیرفت.', 'قدرت تصمیم‌گیری از آن خود من است.

هیچ‌کس نمی‌تواند از فقدان رنج ببرد مگر اینکه این تصمیم خودش باشد. هیچ‌کس از درد رنج نمی‌برد مگر اینکه انتخاب او این وضعیت را برایش برگزیده باشد. هیچ کس نمی‌تواند غمگین شود یا بترسد یا بپندارد که بیمار است مگر اینکه اینها نتایج خواسته‌های خودش باشند. و هیچ کس بدون رضایت خودش نمی‌میرد. هیچ‌ چیزی رخ نمی‌دهد مگر اینکه تجلی خواستهٔ تو باشد، و هیچ چیزی که تو انتخاب می‌کنی حذف نمی‌شود. اینجا دنیای تو است، کاملا با همه جزئیات . اینجا همهٔ واقعیتش برای تو است. و فقط در اینجا رستگاری وجود دارد.

ممکن است باور کنی که این شرایط افراطی است، و بیش از آن فراگیر که بتواند حقیقی باشد. اما آیا حقیقت می‌تواند استثنا داشته باشد؟ اگر تو موهبت همه‌ چیز را داری، آیا فقدان می‌تواند واقعی باشد؟ آیا درد می‌تواند بخشی از صلح باشد، یا ماتم بخشی از شادی؟ آیا ترس و بیماری می‌توانند به ذهنی وارد شوند که در آن عشق و قداست مطلق ساکن است؟ حقیقت باید فراگیر عام باشد، اگر اصلا حقیقت باشد. هیچ متضاد و هیچ استثنایی را نپذیر، زیرا در این صورت با تمامی حقیقت ضدیت می‌کنی.

رستگاری یعنی این تشخیص که حقیقت حقیقی است، و هیچ چیز دیگری حقیقی نیست. این را پیش‌تر شنیده‌ای، اما شاید هنوز هر دو بخش آن را نپذیرفته باشی. بدون بخش اول، بخش دوم هیچ معنایی ندارد. اما بدون بخش دوم، بخش اول دیگر حقیقی نیست. حقیقت نمی‌تواند متضادی داشته باشد. هر چقدر در این مورد بگوییم و بیاندیشیم باز هم کم است. زیرا اگر آنچه حقیقی نیست حقیقی باشد، مانند آنچه حقیقی است، آنگاه بخشی از حقیقت غیرحقیقی است. و حقیقت معنای خود را از دست داده است. هیچ چیز به جز حقیقت حقیقی نیست، و آنچه غیرحقیقی است، غیرحقیقی است.

این آسان‌ترین تمایز است، اما مبهم‌ترین نیز هست. نه به این دلیل که برای درک کردن تمایزی سخت است. بلکه به این دلیل که در پس صف وسیعی از انتخاب‌ها که به نظر نمی‌رسد کاملآ از آ ن خود تو باشند، پنهان است. و چنین است که به نظر می‌رسد حقیقت جنبه‌هایی دارد که با یکپارچگی آن نمی‌خواند، اما چنین به نظر نمی‌رسد که اینها فقط تضادهایی هستند که توسط تو ایجاد شده‌اند.

آنگونه که خداوند* تو را آفرید، باید تغییر‌ناپذیر بمانی، با حالت‌های گذرایی که طبق تعریف غیرحقیقی هستند. و این شامل همه تغییرات در احساس، تغییرات در شرایط بدنی و ذهنی می‌شود؛ تغییر در همه آگاهی‌ها و در همه پاسخ‌ها. این فراگیری عام است که حقیقت را به دور از غیرحقیقی بودن نگه می‌دارد، و غیرحقیقی را از حقیقت جدا می‌کند، آنگونه که هست.

آیا این عجیب نیست که باور داری این فکر که تو دنیایی را که می‌بینی ساختی گستاخی است؟ خداوند* آن را نساخت. از این می‌توانی مطمئن باشی. او* چه می‌تواند بداند از آنچه که فانی، گناهکار و مقصر، هراسان، رنجور و تنها است، و از ذهنی که درون بدنی زندگی می‌کند که باید بمیرد؟ تو با این فکر که او* دنیایی را ساخته که چنین چیزهایی ظاهراً در آن واقعیت دارند، تنها او* را به بی‌عقلی متهم می‌کنی. او* دیوانه نیست. با این وجود تنها دیوانگی چنین دنیایی را می‌سازد.

این اندیشه که خداوند* آشوب را ساخت، با ارادهٔ* او* ضدیت می‌کند، این اندیشه که او متضادهای حقیقت را ابداع کرد، و رنج بردن از مرگ را برای پیروزی بر زندگی؛ همهٔ این گستاخی است. فروتنی می‌تواند فوراً ببیند که این چیزها از او* نیست. و آیا تو می‌توانی چیزی را که خداوند* نیافرید ببینی؟ این پندار که می‌توانی، تو را صرفاً به این باور را می‌رساند که تو می‌توانی آنچه را که خداوند* بودنش را اراده نکرد درک کنی. و چه چیزی می‌تواند گستاخانه‌تر از این باشد؟

بگذارید امروز حقیقتاً فروتن باشیم، و آنچه را که ساخته‌ایم آنگونه که هست بپذیریم. قدرت تصمیم از آن خود ما است. تصمیم بگیر که فقط جایگاه درست خود را به عنوان هم-آفرینندهٔ جهان بپذیری، و همهٔ آنچه می‌پنداری که ساخته‌ای، ناپدید خواهد شد. آنگاه همهٔ آنچه به آگاهی تو می‌رسد، چیزی خواهد بود که همیشه بوده است، ابدی همانگونه که اکنون هست . و آن جایگزین خودفریبی‌هایی خواهد شد که فقط ساخته شدند تا محراب پدر* و فرزند* را غصب کنند .

امروز ما تواضع حقیقی را تمرین می‌کنیم، با نادیده گرفتن تظاهر کاذبی که نفس می‌طلبد تا با آن گستاخی‌اش را اثبات کند. فقط نفس می‌تواند گستاخ باشد. اما حقیقت در داشتن آگاهی به قدرتش، تغییر ناپذیری‌اش و تمامیت ابدیش که همه چیز را در بر می‌گیرد، فروتن است، در حالی که هدیهٔ بی‌نقص خداوند* به فرزند* محبوبش* است. ما آن گستاخی را که می‌گوید ما گناهکار، دارای احساس گناه و هراسان، شرمنده از آنچه هستیم، کنار می‌گذاریم؛ و در عوض قلبهایمان را در فروتنی حقیقی برای او* می‌افرازیم که ما را پاک آفرید، مانند خودش* در قدرت و در عشق.

قدرت تصمیم از آن خود ما است. و ما از او* می‌پذیریم که چه هستیم، و فروتنانه فرزند* خداوند* را می‌شناسیم. شناختن فرزند* خداوند* همچنین ایجاب می‌کند که همهٔ خود‌فریبی‌ها رها شده باشند، و نادرست شمرده شده باشند. گستاخانه بودن آن‌ها درک شده باشد. و در فروتنی، درخشندگی فرزند* خداوند*، مهربانی او، بی‌گناهی کامل او، عشق پدر* او، حق او برای بهشت و رها شدنش از دوزخ با شادمانی به عنوان آنچه از آن خود ماست پذیرفته می‌شود.

اینک ما در این تصدیق شادمانه به هم می‌پیوندیم که دروغها غیرحقیقی هستند، و تنها حقیقت حقیقی است. ما زمانی که از خواب برمی‌خیزیم فقط به حقیقت می‌اندیشیم، و پنج دقیقه را برای تمرین روش‌های آن صرف می‌کنیم، در حالیکه ذهن‌های هراسان خود را با این جملات تشویق می‌کنیم: قدرت تصمیم‌گیری از آن خود من است. امروز من خودم را آنگونه که ارادهٔ پدرم* آفرید تا باشم، خواهم پذیرفت. سپس در سکوت منتظر خواهیم شد، در حالیکه همه‌ی خودفریبی‌ها را رها می‌کنیم، و فروتنانه از خویشتنمان* می‌خواهیم که خودش* را بر ما آشکار کند. و او* که هرگز ما را ترک نکرده است دوباره به آگاهی‌مان خواهد آمد، سپاسگزار از برگرداندن منزل خداوند* به او*، آنگونه که قرار بوده باشد.

در سراسر روز با شکیبایی او* را انتظار بکش، و هر ساعت او* را با کلماتی که روز را با آن آغاز کردی بخوان، و روز را با همین دعوت به خویشتنت* به پایان برسان. آوای* خداوند* پاسخ خواهد داد، زیرا او* از جانب تو و از جانب پدرت* سخن می‌گوید. او صلح خداوندی* را جایگزین همهٔ افکار پرتنش تو خواهد کرد، حقیقت خداوند* را جایگزین خودفریبی‌ها می‌کند، و فرزند* خداوند* را به جای اوهام تو از خودت می‌نشاند.', 'https://acim-farsi.org/workbook/lesson/152', 'https://acim-farsi.org/audio/workbook/lesson/152.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (153, 'امنیت من در بی‌دفاعی من نهفته است.', 'امنیت من در بی‌دفاعی من نهفته است.', 'امنیت من در بی‌دفاعی من نهفته است.

تو که توسط این دنیای در حال تغییر احساس تهدید می‌کنی، از پیچ و تابهای سرنوشت در آن، از کنایه‌های تلخش، از روابط موقتی آن و همه‌ی «هدایایی» که صرفاً به تو وام می‌دهد تا دوباره پس بگیرد؛ به این درس خوب توجه کن. دنیا هیچ امنیتی فراهم نمی‌کند. ریشه دنیا در حمله است و همه‌ی «هدایای» آن از امنیت ظاهری، فریب‌های توهمی هستند. حمله می‌کند، و سپس باز حمله می‌کند. در جایی که خطر این‌چنین تهدید می‌کند هیچ صلح ذهنی ممکن نیست.

دنیا فقط تدافع را می‌پرورد. زیرا تهدید خشم می‌آورد، خشم موجب می‌شود تهدید منطقی به نظر برسد، چیزی که شرافتمندانه برانگیخته شده، و به نام دفاع از خود، حق آن وجود دارد. اما تدافع یک تهدید دوگانه است. زیرا ضعف را تصدیق می‌کند، و سیستمی از دفاع را ایجاد می‌کند که نمی‌تواند عمل کند. از این طریق فرد ضعیف باز بیشتر تضعیف می‌شود، زیرا در بیرونش خیانت هست و نیز خیانتی عظیم‌تر در درون. اینچنین ذهن سردرگم می‌شود، و نمی‌داند که برای یافتن راه فراری از تخیلاتش به کجا رو کند.

انگار حلقه‌ای آن را تنگ گرفته است، که در درون حلقهٔ دیگری آن را اسیر کرده است و حلقهٔ دیگری باز در درونش ، تا آنجا که دیگر نمی‌توان امید فرار داشت یا به آن دست یافت. حمله، دفاع؛ دفاع، حمله، به حلقه‌هایی از ساعت‌ها و روزهایی تبدیل می‌شود که ذهن را در بندهای سنگین پولادی با آذین آهنین اسیر می‌کند، ذهنی که برنمی‌گردد مگر برای آغاز دوباره. به نظر می‌رسد هیچ وقفه یا پایانی در اسارت فزاینده‌ی ذهن در این زندان نیست.

انواع دفاع گران‌ترین هزینه‌هایی هستند که نفس می‌تواند مطالبه کند. در انواع دفاع، دیوانگی در شکلی چنان شوم نهفته است که امید عقلانیت صرفاً یک رؤیای پوچ به نظر می‌رسد، فراتر از امکان. حس تهدیدی که دنیا آن را ترغیب می‌کند بسیار عمیق‌تر است، و بسیار فراتر از دیوانگی و آشفتگی که تو می‌توانی درک کنی، تا آنجا که هیچ ایده‌ای از تمام ویرانی که ایجاد کرده است نمی‌توانی داشته باشی.

تو برده آن هستی. تو نمی‌دانی چه کنی، در هراس از آن. تو درک نمی‌کنی که چقدر برای آن قربانی داده‌ای، تو که حلقه فلزی آن را به تنگی بر قلبت احساس می‌کنی. تو تشخیص نمی‌دهی که با تدافع خود برای تخریب صلح مقدس خداوند*، چه کرده‌ای. زیرا تو فرزند* خداوند* را فقط یک قربانی حمله توسط تخیلات، توسط رؤیاها، و توسط اوهامی که ساخته است می‌دانی؛ اما او را در حضور آن‌ها درمانده می‌بینی، فقط نیازمند دفاع توسط تخیلاتِ باز هم بیشتر، و رؤیاهایی که توسط آن‌ها اوهامِ امنیتش به او آرامش ببخشند.

بی‌دفاعی قدرت است. بی‌دفاعی به تشخیص مسیحا* در درون تو شهادت می‌دهد. احتمالا تو به یاد خواهی آورد قسمت متن را که اشاره می‌کند انتخاب همیشه بین قدرت مسیحایی* و ضعف خود تو صورت می‌گیرد، که خود را از او* جدا می‌بینی. بی‌دفاعی هرگز نمی‌تواند مورد حمله قرار گیرد، زیرا قدرتی آنچنان عظیم را تشخیص می‌دهد که حمله به آن خطا است، یا بازی احمقانه‌ای است که یک کودک خسته می‌تواند انجام دهد، زمانی که خواب‌آلوده‌تر از آن است که به یاد آورد چه می‌خواهد.

تدافع ضعف است. تدافع اعلام می‌کند که تو مسیحا* را انکار کرده‌ای و از خشم پدرش* به هراس افتاده‌ای. حال چه چیز می‌تواند تو را از توهم خود در مورد یک خدای خشمگین که تو باور داری تصویر هراسناکش را می‌بینی که در همۀ شرارتهای دنیا مشغول کار است، نجات بخشد؟ چه چیزی به جز اوهام در این حالت می‌تواند از تو دفاع کند، زمانی که تو فقط در حال جنگ با اوهام هستی؟

امروز ما چنین بازی‌های کودکانه‌ای را انجام نخواهیم داد. زیرا هدف حقیقی ما نجات دنیا است، و ما لذت بی‌پایانی را که وظیفه‌مان به ما ارزانی می‌کند، با حماقت معاوضه نمی‌کنیم. ما نمی‌خواهیم اجازه دهیم شادمانی ما از دست برود به دلیل اینکه قطعه‌ای از رؤیای بی‌معنا از ذهنمان گذشته است، و ما تصاویر درون این رؤیای بی‌معنا را با فرزند* خداوند* اشتباه گرفته‌ایم ؛ لحظهٔ ناچیز آن را با ابدیت.

امروز ما به ورای رؤیاها نگاه می‌کنیم، و تشخیص می‌دهیم که ما نیاز به هیچ دفاعی نداریم زیرا هجوم‌ناپذیر آفریده شده‌ایم، بدون هیچ فکر یا آرزو یا رؤیایی که در آن حمله بتواند هیچ معنایی داشته باشد. از این رو ما نمی‌توانیم بترسیم زیرا همهٔ پندارهای ترسناک را پشت سر گذاشته‌ایم. و در بی‌دفاعی، ما در امنیت می‌ایستیم، اینک با متانت و اطمینان از امنیتی که داریم، مطمئن از رستگاری؛ مطمئن از این که هدفی که برایمان برگزیده شده است را به انجام خواهیم رساند، هم چنان که مأموریت ما تبرک مقدس خود را به دنیا گسترش می‌دهد.

لحظه‌ای آرام باش، و در سکوت بیندیش که قصد تو چقدر مقدس است، چه‌قدر ایمن و دست‌نیافتنی درون نور آن می‌آسایی. خادمان خداوند* انتخاب کرده‌اند که حقیقت با آن‌ها همراه باشد. چه کسی از آنان مقدس‌تر است؟ چه کسی می‌تواند از آنان مطمئن‌تر باشد که شادمانی‌اش کاملا تضمین می‌شود؟ و چه کسی می‌تواند قدرتمندانه‌تر محافظت گردد؟ چه دفاعی می‌تواند احتمالا برای کسانی نیاز باشد که در بین برگزیدگان خداوند* هستند، با انتخاب او* و هم‌چنین انتخاب خودشان؟

وظیفهٔ خا‌دمان خداوند* است که برادرانشان را یاری دهند تا همان‌گونه که آنان انتخاب را انجام داده‌اند، انتخاب کنند. خداوند* همه را انتخاب کرده است اما شمار اندکی به این نتیجه رسیده‌اند که تشخیص دهند ارادهٔ* او* فقط ارادهٔ خود آنهاست. و در حالی که تو در آموزش دادن آنچه که آموخته‌ای شکست می‌خوری، رستگاری منتظر می‌ماند و تاریکی دنیا را در زندان دهشتناکش نگه می‌دارد. هم‌چنین تو نخواهی آموخت که نور به سمتت آمده است، و فرار تو به انجام رسیده است. زیرا تو نور را نخواهی دید مادامی که آن را به همهٔ برادران خود عرضه نکنی. در حالی که آنان نور را از دستان تو دریافت می‌کنند، تو آن را از آن خود تشخیص خواهی داد.

رستگاری را می‌توان به عنوان یک بازی که کودکان شاد انجام می‌دهند آموخت. رستگاری توسط آن یگانه* که* به فرزندانش* عشق می‌ورزد طراحی شد، که* می‌خواهد بازیچه‌های ترسناک آن‌ها را با بازی‌های شاد جایگزین کند، که به آن‌ها می‌آموزند بازی ترس رفته است. دستورالعمل بازی او شادمانی است زیرا هیچ بازنده‌ای وجود ندارد. هرکسی که بازی می‌کند باید برنده باشد، و در برنده بودن او، بُرد همگان تضمین می‌شود. بازی ترس با شادمانی کنار گذاشته می‌شود، زمانی که کودکان منافعی را که رستگاری عرضه می‌کند ببینند.

تو که آن بازی را انجام داده‌ای که ناامید شده‌ای، توسط پدر متعالت طرد شده‌ای، در وحشت و در دنیایی ترسناک که با خطا‌کاری و احساس گناه دیوانه شده است، تنها مانده‌ای؛ اینک شاد باش. آن بازی تمام شد. اینک زمان سکوت آمده است که در آن ما بازیچه‌های احساس گناه را کنار می‌گذاریم، و افکار عجیب و کودکانه خود را درمورد گناه برای همیشه از اذهان خالص و مقدس کودکان بهشت و فرزند قدسی‌ خداوند پاک می‌کنیم.

فقط برای لحظه‌ای دیگر درنگ می‌کنیم، تا بازی نهایی شادمان خود را بر این زمین بازی کنیم. و سپس می‌رویم تا جایگاه برحق خود را اشغال کنیم که در آن حقیقت ساکن است و بازی‌ها بی‌معنا هستند. این چنین داستان پایان می‌یابد. بگذار امروز فصل آخر را به دنیا نزدیک‌تر کند، تا همگان بتوانند بیاموزند افسانه‌ایی که از سرنوشت وحشتناک می‌خوانند، شکست همۀ امیدهایشان، دفاع رقت‌انگیز آنان در برابر انتقامی که نمی‌توانند از آن فرار کنند، صرفاً تخیل فریب خوردۀ خود آنان است. خا‌دمان خداوند* آمده‌اند تا او را از رؤیاهای تاریک این قصه که در حافظۀ سردرگم، و سرگردان او از این افسانهٔ تحریف شده برانگیخته شده است، بیدار کنند. فرزند* خداوند* سرانجام می‌تواند لبخند بزند، با آموختن اینکه این قصه حقیقی نیست.

امروز ما به شکلی تمرین می‌کنیم که برای مدتی به آن ادامه خواهیم داد. ما هر روز را با معطوف کردن توجه‌مان به اندیشه‌ی آن روز تا هر زمان که ممکن باشد آغاز خواهیم کرد. دست‌کم پنج دقیقه را به آماده شدن برای روزی اختصاص می‌دهیم که در آن رستگاری تنها هدف ما است. ده دقیقه بهتر است، پانزده دقیقه باز هم بهتر. و زمانی که پراکندگی کاهش یابد تا نتواند ما را از هدفمان منحرف کند، درخواهیم یافت که نیم ساعت زمان بسیار کوتاهی است که با خداوند* بگذرانیم. و اراده‌مندانه همین را در شب اختصاص می‌دهیم، در سپاسگزاری و سرور.

هر ساعت تمرین به صلح فزاینده‌ی ما خواهد افزود مادامی که به یاد می‌آوریم به اراده‌ای* که با خداوند* سهیم هستیم وفادار باشیم. گاهی شاید یک دقیقه یا حتی کمتر، بیشترین زمانی است که در یک ساعت می‌توانیم اختصاص دهیم. گاهی فراموش خواهیم کرد. در زمانهای دیگر مشغولیتهای دنیا آنچنان به ما نزدیک می‌شوند که ما حتی زمان کوتاهی نمی‌توانیم رها شویم، و افکارمان را به خداوند* معطوف کنیم.

اما هر زمان که می‌توانیم، مسئولیت خودمان را به عنوان خادمان خداوند* مشاهده خواهیم کرد، در بیاد آوردن هر ساعت ماموریتمان و عشق او*. و ما در سکوت کنار خواهیم نشست و منتظر او* خواهیم شد و به آوایش* گوش خواهیم داد، و خواهیم آموخت که او* می‌خواهد ما در ساعتی که پیش رو داریم چه کنیم؛ در حالی که از او* برای همه‌ی هدایایی که به ما در ساعت گذشته داد تشکر می‌کنیم.

در زمان، با تمرین، تو هرگز اندیشیدن به او را ترک نخواهی کرد، و آوای عاشقانۀ او* را می‌شنوی که گام‌های تو را در مسیرهای ساکت هدایت می‌کند، جایی که تو در بی‌دفاعی حقیقی قدم خواهی زد. زیرا تو خواهی دانست که بهشت* با تو می‌آید. و نیز تو لحظه‌ای ذهنت را از او* دور نگه نخواهی داشت، اگرچه زمانت در نثار کردن رستگاری به دنیا سپری می‌شود. آیا فکر می‌کنی که او* این را ممکن نخواهد ساخت، برای تو که انتخاب کردی تا نقشهٔ او* را برای رستگاری دنیا و رستگاری خودت به انجام رسانی؟

موضوع امروز ما، بی‌دفاعی ما است. ما خودمان را در آن خواهیم پوشاند، زمانی که برای آغاز کردن روز آماده می‌شویم. ما قدرتمندانه در مسیحا* بر می‌خیزیم، و اجازه می‌دهیم ضعفمان ناپدید شود، همچنان که به یاد می‌آوریم قدرت او* در ما ساکن است. ما به یاد خودمان خواهیم آورد که او* در طول روز در کنار ما می‌ماند، و هرگز با قدرتش* از حمایت از ضعف ما دست نمی‌کشد. ما قدرت او* را هر زمان که احساس می‌کنیم انواع دفاع در ما اطمینان به هدف را تهدید می‌کنند فرامی‌خوانیم. ما لحظه‌ای درنگ خواهیم کرد، در حالی که او* به ما می‌گوید، «من این جا هستم».

اینک تمرین تو شوق عشق را به خود می‌گیرد، تا به تو کمک کند ذهنت را از سردرگمی در مورد قصدت محافظت کنی. هراسان و خجالتی نباش. هیچ تردیدی نمی‌تواند باشد که تو به هدف نهایی خود خواهی رسید. خادمان خداوند* هرگز نمی‌توانند شکست بخورند، زیرا عشق و قدرت و صلحی که از آن‌ها به همهٔ برادران‌شان تابش می‌کند، از او* می‌آید. اینها هدایای خداوند* به تو هستند. بی‌دفاعی، تمام چیزی است که تو نیاز داری در عوض به او* بدهی. تو فقط چیزی را رها می‌کنی که هرگز واقعی نبوده است، تا به مسیحا* بنگری و بی‌گناهی او* را ببینی.', 'https://acim-farsi.org/workbook/lesson/153', 'https://acim-farsi.org/audio/workbook/lesson/153.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (154, 'من در میان خادمان خداوند* هستم.', 'من در میان خادمان خداوند* هستم، و من سپاسگزارم که ابزاری را دارم که توسط آن تشخیص دهم که آزاد هستم.
من در میان خادمان خداوند* هستم، و من سپاسگزارم که ابزاری را دارم که توسط آن تشخیص دهم که آزاد هستم.', 'من در میان خادمان خداوند* هستم.

بگذارید امروز نه گستاخ باشیم و نه به نادرستی فروتن. ما از این حماقت‌ها فراتر رفته‌ایم. ما نمی‌توانیم خودمان را قضاوت کنیم، و نیازی به این کار نداریم. اینها فقط تلاش‌هایی هستند برای اینکه تصمیم‌گیری را متوقف کنند، و ما را در تعهد به وظیفه‌مان به تاخیر بیاندازند. نقش ما این نیست که ارزش خودمان را قضاوت کنیم، و نیز ما نمی‌توانیم بدانیم بهترین نقش برایمان چیست؛ آنچه می‌توانیم در قالب یک نقشه بزرگ انجام دهیم که قادر به دیدن تمامیت آن نیستیم. نقش ما در بهشت* شکل گرفته است، نه در دوزخ. و آنچه که ما می‌اندیشیم ضعف است می‌تواند قدرت باشد؛ آنچه ما باور داریم قدرت ما است اغلب گستاخی است.

نقش تعیین شده تو هر چه بتواند باشد، توسط آوای* خداوند* انتخاب شده است، آوایی* که وظیفه‌اش سخن گفتن برای تو نیز هست. دیدن قدرت‌هایت دقیقاً آنگونه که هستند، و به همان اندازه آگاهی از اینکه این قدرت‌ها در کجا می‌توانند به بهترین شکل عملی شوند، به چه منظوری، برای چه کسی و در چه زمانی، همه را او* انتخاب می‌کند و نقش تو را برایت می‌پذیرد. او* بدون رضایت خود تو کاری انجام نمی‌دهد. اما او* در آنچه که تو هستی فریب نمی‌خورد، و فقط به آوای* او* در تو گوش فرا می‌دهد.

از طریق توانایی او در شنیدن آن آوای* یگانه که از آن خود* او* است، تو سرانجام آگاه می‌شوی که آوای* یگانه‌ در تو وجود دارد. و اینکه این آوای* یگانه به وظیفه تو اشاره می‌کند، و آن را بر عهده تو می‌گذارد، با دادن توانایی به تو برای فهم آن، انجام آنچه که ایجاب می‌کند، و توفیق یافتن در هر چیزی که تو انجام می‌دهی و مربوط به آن است. خداوند* به فرزندش* در این پیوسته است، و چنین است که فرزندش* پیام‌آور او* از وحدت با وی* می‌شود.

این پیوند است، از طریق آوای* خداوند*، از طریق آوای پدر* و فرزندش*، که رستگاری را از این دنیا جدا می‌سازد. این آوا* است که از قانون‌هایی سخن می‌گوید که دنیا از آن‌ها پیروی نمی‌کند؛ این آوا* است که وعده رستگاری از همه گناهان را می‌دهد، و احساس گناه را در ذهنی که خداوند* آن را بی‌گناه آفرید منسوخ می‌کند. اینک این ذهن از اینکه چه کسی* آن را آفریده است، و از اتحاد همیشگی وی* با خودش دوباره آگاه می‌شود. چنین است که خویشتن* او* واقعیت یگانه‌ای است که در آن اراده‌اش و ارادهٔ* خداوند* به هم می‌پیوندند.

یک پیام‌آور آن کسی نیست که پیامی را که حمل می‌کند، می‌نویسد. همچنین او حق کسی را که پیام را می‌نویسد مورد پرسش قرار نمی‌دهد، و نمی‌پرسد که چرا او دریافت کنندگان پیامی را که می‌آورد،انتخاب کرده است. فقط کافی است که آن را بپذیرد، آن را به کسانی بدهد که برای آنها مقرر است، و نقش خود را در رساندن آن به انجام برساند. اگر او تعیین کند که پیام‌ها چه باید باشند، یا تعیین کند که هدف آنها چیست، یا باید به کجا حمل شوند، او در انجام دادن نقش مناسب خود به عنوان آورنده کلام* شکست می‌خورد.

یک تفاوت عمده در نقش پیام‌آوران بهشت* وجود دارد، که آن‌ها را از پیام‌آورانی که دنیا تعیین می‌کند، جدا می‌کند. پیام‌هایی که حمل می‌کنند نخست برای خود آن‌ها در نظر گرفته شده است. و فقط اگر آن‌ها بتوانند این پیامها را برای خودشان بپذیرند، قادر می‌شوند تا آن‌ها را منتشر کنند، و آن‌ها را به هر کجا که قرار بوده باشند بدهند. مانند پیام‌آوران زمینی، آنها پیامی را که حمل می‌کنند ننوشته‌اند، اما به اولین دریافت کننده آن در حقیقی‌ترین مفهوم تبدیل می‌شوند، و آن را دریافت می‌کنند تا خودشان را برای دادنش آماده کنند.

یک پیام‌آور زمینی نقش خود را با منتشر کردن همهٔ پیام‌هایش تکمیل می‌کند. پیام‌آوران* خداوند* نقش خود با پذیرش پیام‌های او* برای خودشان ایفا می‌کنند، و با منتشر کردن پیام‌ها نشان می‌دهند که آن‌ها را فهمیده‌اند. آن‌ها هیچ نقشی را که توسط اقتدار او داده نشده باشد نمی‌پذیرند. و چنین است که با هر پیامی که منتشر می‌کنند، بدست می‌آورند.

آیا می‌خواهی پیام‌های خداوند* را دریافت کنی؟ زیرا اینگونه تو به پیام‌آور او* تبدیل می‌شوی. تو اینک تعیین شده‌ای. اما تو منتظر هستی پیام‌هایی را که گرفته‌ای، بدهی. و بنابراین تو نمی‌دانی که آن‌ها از آن تو هستند، و آن‌ها را تشخیص نمی‌دهی. هیچ‌کس نمی‌تواند دریافت کند و درک کند که دریافت کرده است، مادامی که نداده است. زیرا در دادن پذیرش او از آنچه دریافت کرده است، نهفته است.

تو که اکنون پیام‌آور خداوند* هستی، پیام‌های او را دریافت کن. زیرا این بخشی از نقش تعیین شدهٔ تو است. خداوند در عرضه آنچه نیاز داری، شکست نخورده است، و آنچه تو نیاز داری پذیرفته نشده باقی نمانده است. اما بخش دیگری از وظیفه تعیین شده تو هنوز باید انجام شود. او* که پیام‌های خداوند* را برای تو دریافت کرد، می‌خواهد که آن‌ها توسط تو نیز دریافت شوند. زیرا از این طریق با او* یگانه می‌شوی و او* را خودت می‌دانی.

این پیوستن است که ما امروز بر عهده می‌گیریم تا تشخیص دهیم . ما نخواهیم طلبید که ذهن‌هایمان را جدا از آن او* نگه داریم که برای ما سخن می‌گوید، زیرا این فقط آوای خودمان است که در محضر او* می‌شنویم. فقط او* می‌تواند با ما و به سود ما سخن بگوید، با پیوستن در یک آوا* که کلام* خداوند* را دریافت می‌کند و می‌دهد؛ دادن و دریافت کردن ارادهٔ* وی*.

ما تمرین می‌کنیم به او* چیزی را بدهیم که او* می‌خواهد داشته باشد، چنانکه بتوانیم هدیه‌اش را به خودمان بشناسیم. او* نیاز به آوای ما دارد که بتواند از طریق ما سخن بگوید. او* به دستان ما نیاز دارد تا پیام‌هایش را نگه دارد، و آن‌ها را به کسانی برساند که او* تعیین می‌کند. او* به پاهای ما نیاز دارد تا ما را به جایی ببرد که اراده می‌کند، تا آنان که در فلاکت انتظار می‌کشند سرانجام بتوانند رستگار شوند. و او* به اراده ما نیاز دارد تا با ارادهٔ* خودش* یگانه شود، تا بتوانیم دریافت کننده‌های حقیقی هدایایی باشیم که او* می‌دهد.

بگذارید فقط این درس را برای امروز بیاموزیم: ما تشخیص نخواهیم داد چه چیز را دریافت می‌کنیم تا زمانی که آن را نداده باشیم. تو این را که گفته شده به صد شیوه شنیده‌ای، صد بار، و اما هنوز باور به آن نقص دارد. اما این حتمی است؛ زمانی که به آن باور داده شود، تو هزار معجزه دریافت خواهی کرد و سپس هزار معجزه دیگر دریافت می‌کنی، اما نخواهی دانست که خود* خداوند* هیچ هدیه‌ای را فراتر از آنچه که تو تاکنون داری نگه نداشته است؛ و خداوند* از کوچکترین تبرک‌ها برای فرزندش* دریغ نکرده است. این چه معنایی می‌تواند برای تو داشته باشد، تا زمانی که خودت را با او* و با خود او* یکی ندانی؟

پس درس امروز ما چنین بیان می‌شود: من در میان خادمان خداوند* هستم، و من سپاسگزارم که ابزاری را دارم که توسط آن تشخیص دهم که آزاد هستم.

با روشن کردن اذهان ما، دنیا عقب‌نشینی می‌کند، و با تشخیص دادن اینکه این سخنان مقدس حقیقی هستند. آن‌ها پیامهایی هستند که امروز از آفریدگارمان* برایمان فرستاده شده‌اند. اینک ما نشان می‌دهیم که چگونه آن‌ها ذهن‌هایمان را در مورد خودمان و وظیفه‌ای که داریم تغییر داده‌اند. زیرا همچنانکه ما اثبات می‌کنیم که هیچ اراده‌ای را جز آنکه با او سهیم هستیم نمی‌پذیریم، هدایای فراوان ما از آفریدگارمان*، به رؤیت ما می‌آیند و به درون دستمان می‌جهند، و ما آنچه را دریافت کرده‌ایم، تشخیص خواهیم داد.', 'https://acim-farsi.org/workbook/lesson/154', 'https://acim-farsi.org/audio/workbook/lesson/154.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (155, 'من عقب خواهم ایستاد و اجازه می‌دهم او* طریق را راهبری کند.', 'من عقب خواهم ایستاد و اجازه می‌دهم او* طریق را راهبری کند.
من عقب خواهم ایستاد و اجازه می‌دهم او* طریق را راهبری کند، زیرا من می‌خواهم در راستای این راه به سمت او* گام بردارم.', 'من عقب خواهم ایستاد و اجازه می‌دهم او* طریق را راهبری کند.

راهی برای زیستن وجود دارد در دنیایی که اینجا نیست، اگرچه به نظر می‌رسد که هست. تو ظاهر را تغییر نمی‌دهی، گرچه بیشتر لبخند می‌زنی. پیشانی‌ات آرام است؛ چشمانت ساکت است. و کسانی که مانند تو دنیا را می‌پیمایند طریق خود را تشخیص می‌دهند. با این حال کسانی که هنوز طریق را ادراک نکرده‌اند نیز تو را خواهند شناخت، و باور می‌کنند که تو مانند آن‌ها هستی، همانگونه که در گذشته بودی.

دنیا یک توهُّم است. کسانی که انتخاب می‌کنند به آن بیایند، در جستجوی مکانی هستند که بتوانند توهُّم باشند و از واقعیت خود دوری کنند. با این وجود وقتی آن‌ها درمی‌یابند که واقعیت خودشان حتی در اینجا هست، آنگاه عقب می‌ایستند و اجازه می‌دهند واقعیتشان این طریق را رهبری کند. واقعاً چه انتخاب دیگری برای آن‌ها وجود دارد؟ اجازه دادن به اوهام برای اینکه جلوتر از حقیقت گام بردارند، دیوانگی است. اما اجازه دادن به اینکه توهُّم در پشت حقیقت فرو ریزد و حقیقت همانطور که هست پیشگام باشد، عقلانیت محض است.

این همان انتخاب ساده‌ای است که ما امروز انجام می‌دهیم. وهم دیوانه‌وار برای مدت کوتاهی در نظر خواهد ماند، برای مشاهده توسط آنان که انتخاب کردند که بیایند، و هنوز درنیافته‌اند که باید خطا بودن انتخابشان را جشن بگیرند. آنان نمی‌توانند مستقیماً از حقیقت بیاموزند، زیرا انکار کرده‌اند که چنین است. بنابراین آنان نیاز به آموزگاری* دارند که* دیوانگی آنان را درک کند، اما هنوز بتواند ورای وهم به حقیقت ساده در آنان بنگرد.

اگر حقیقت از آنان طلب می‌کرد که دنیا را کنار بگذارند، برای آنان به نظر می‌رسید انگار حقیقت خواهان قربانی کردن چیزی است که واقعی است. بسیاری انتخاب کرده‌اند دنیا را ترک کنند در حالی که هنوز به واقعیت آن باور دارند. و آنان از احساس فقدان رنج برده‌اند، و به همین دلیل آزاد نشده‌اند. دیگران هیچ‌چیز به غیر از دنیا را انتخاب نکرده‌اند، و آنان از احساس فقدانی حتی عمیق‌تر رنج برده‌اند، که درکش نکرده‌اند.

در میانه این مسیرها طریق دیگری وجود دارد که ما را از هر نوع فقدان بیرون می‌برد، زیرا قربانی کردن و محرومیت هر دو به سرعت پشت سر گذاشته می‌شوند. این طریقی است که اینک برای تو مقرر است. تو دراین طریق همانگونه که دیگران گام برمی‌دارند می‌روی، به نظر نمی‌رسد که از آن‌ها متمایز باشی، اگرچه حقیقتاً هستی. از این رو تو می‌توانی به آنان خدمت کنی در حالی که به خودت خدمت می‌کنی، و گامهایشان را بر مسیری تنظیم کنی که خداوند* برای تو گشوده است، و برای آنان از طریق تو.

هنوز به نظر می‌رسد وهم به تو آویخته است، اینک تو ممکن است به آنان برسی. اما وهم عقب نشسته است. و این وهم نیست که آنان می‌شنوند تو از آن سخن می‌گویی، و این وهم نیست که تو به نزد چشمان آنان می‌آوری که ببینند و ذهن‌هایشان که دریافت کنند. حقیقت که تو را راهبری می‌کند، نیز نمی‌تواند با آنان از طریق اوهام سخن بگوید، زیرا طریق اینک از وهم فراتر می‌رود، طریقی را که تو آنان را به آن فرا می‌خوانی، و آنان می‌توانند تو را دنبال کنند.

همه طریق‌ها در نهایت به این یک طریق می‌انجامند. زیرا قربانی کردن و محرومیت مسیرهایی هستند که به هیچ جایی منتهی نمی‌شوند، انتخابهایی برای شکست، و اهدافی که ناممکن باقی خواهند ماند. تمامی اینها باز می‌مانند زمانی که حقیقت در تو پیش می‌آید، تا برادرانت را از مسیرهای مرگ خارج کند، و آنان را به طریق شادمانی هدایت نماید. رنج آنان فقط وهم است. اما آنان نیاز به یک راهنما دارند که از آن به بیرون هدایتشان کند، زیرا وهم را با حقیقت اشتباه می‌گیرند.

چنین است فراخوان رستگاری، و نه چیزی بیشتر. رستگاری می‌خواهد که تو حقیقت را بپذیری، و اجازه بدهی پیشاپیشِ تو برود، و مسیر رهایی از وهم را روشن سازد. این رهایی، بهایی ندارد. هیچ هزینه‌ای وجود ندارد، فقط سود است. اوهام فقط می‌توانند ظاهراً فرزند* مقدس خداوند* را در زنجیر نگه دارند. او فقط از اوهام نجات می‌یابد. زمانی که اوهام عقب بنشینند، او خودش را دوباره می‌یابد.

اینک در امنیت گام بردار، اما با دقت، زیرا این مسیر برای تو تازه است. و تو ممکن است دریابی که هنوز وسوسه می‌شوی پیش‌تر از حقیقت گام برداری، و اجازه دهی اوهام راهنمایت باشند. برادران مقدست به تو داده شده‌اند، تا گامهای تو را دنبال کنند، مادامی که با اطمینان از هدف به سمت حقیقت گام برمی‌داری. حقیقت اینک پیش‌تر از تو می‌رود، تا آنان بتوانند چیزی را ببینید که می‌توانند خود را با آن یکی بدانند؛ چیزی که تشخیص می‌دهند راهنمای طریق است.

اما در پایان سفر هیچ فاصله‌ای نخواهد بود، هیچ شکافی بین حقیقت و تو. و همه اوهامی که در طریق سفر تو می‌آمدند، نیز تو را ترک خواهند کرد، تا هیچ چیزی نماند که حقیقت را جدا از کمال خداوندی* نگاه دارد، مقدس همچون خودش*. با ایمان عقب بایست و اجازه بده حقیقت راهنمای طریق باشد. تو نمی‌دانی که به کجا می‌روی. اما آن یگانه* که* می‌داند، با تو می‌آید. بگذار او* تو را به همراه بقیه هدایت کند.

هنگامی که رؤیاها به پایان می‌رسند، زمان در را بر همهٔ چیزهایی که گذرا هستند می‌بندد، و معجزات بی‌هدف می‌شوند، فرزند* مقدس خداوند* هیچ سفری نخواهد کرد. هیچ آرزویی برای وهم بودن به جای حقیقت وجود نخواهد داشت. و ما به سوی این گام برمی‌داریم، در حالی که در طریقی که حقیقت به ما نشان می‌دهد پیش می‌رویم. این سفر نهایی ما است، که ما برای همگان انجام می‌دهیم. ما نباید راهمان را گم کنیم. زیرا مادامی که حقیقت پیشاپیش ما می‌رود، پیشاپیش برادرانمان که ما را دنبال خواهند کرد نیز می‌رود.

ما به سمت خداوند* گام برمی‌داریم. درنگ کن و بر این تعمق کن. آیا طریق دیگری می‌تواند مقدس‌تر باشد، یا سزاوارتر برای تلاش تو، برای عشق تو و نیّت کامل تو؟ چه طریقی می‌تواند به تو بیش از همه چیز را بدهد، یا کم‌تر عرضه کند و باز فرزند* مقدس خداوند* را راضی نماید؟ ما به سمت خداوند* گام بر می‌داریم. حقیقت که پیشاپیش ما می‌رود اینک با او* یگانه است، و ما را به جایی راهنمایی می‌کند که او* همیشه بوده است. چه طریقی جز این می‌تواند مسیری باشد که تو بخواهی به جای این انتخاب کنی؟

پاهای تو با امنیت در آن طریق که دنیا را به خداوند* می‌رساند استوار می‌شود. به راههایی که به نظر می‌رسد که تو را به هر جای دیگری می‌رسانند، نگاه نکن. رؤیاها راهنمای ارزشمندی برای تو که فرزند* خداوند* هستی نیستند. از یاد نبر که او دستش را در دستان تو گذاشته است، و با اطمینانش به تو و برادرانت* اعلام می‌دارد که ارزش اعتماد او* را دارید. نمی‌توان او* را فریب داد. اعتماد او* طریق تو را قطعی ساخته و هدفت را مسلم می‌کند. تو موجب شکست برادرانت و خودت نخواهی شد.

و اینک او ققط می‌خواهد که تو هر روز زمانی به او* بیاندیشی، تا بتواند با تو سخن بگوید و از عشقش* به تو بگوید، و به یادت بیاورد که اعتمادش* چقدر عظیم است؛ و عشقش* چه بی‌پایان است. به نام خودت و به نام خود* او*، که با هم یکی هستند، امروز ما شادمان با این اندیشه تمرین می‌کنیم: من عقب خواهم ایستاد و اجازه می‌دهم او* طریق را راهبری کند، زیرا من می‌خواهم در راستای این راه به سمت او* گام بردارم.', 'https://acim-farsi.org/workbook/lesson/155', 'https://acim-farsi.org/audio/workbook/lesson/155.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (156, 'من با خداوند* در قداست کامل گام بر‌می‌دارم.', 'من با خداوند* در قداست کامل گام بر‌می‌دارم. من دنیا را روشن می‌کنم، من ذهنم و همهٔ ذهن‌هایی را که خداوند* با من یگانه آفرید روشن می‌کنم.
من دنیا را روشن می‌کنم، من ذهنم و همهٔ ذهن‌هایی را که خداوند* با من یگانه آفرید روشن می‌کنم.
من دنیا را روشن می‌کنم، من ذهنم و همهٔ ذهن‌هایی را که خداوند* با من یگانه آفرید روشن می‌کنم.', 'من با خداوند* در قداست کامل گام بر‌می‌دارم.

ایدهٔ امروز صرفاً حقیقت ساده را بیان می‌کند که پندار گناه را ناممکن می‌سازد. این ایده نوید می‌دهد که هیچ علتی برای احساس گناه وجود ندارد، و بدون علت، احساس گناهی وجود ندارد. این ایده مطمئناً از این اندیشهٔ بنیادی که بارها در متن ذکر شده است پیروی می‌کند؛ ایده‌ها سرچشمهٔ خود را ترک نمی‌کنند. اگر این حقیقی باشد، تو چگونه می‌توانی از خداوند* جدا باشی؟ تو چگونه می‌توانی در دنیا تنها و جدا از سرچشمهٔ* خود گام برداری؟

اندیشه‌هایی که ما در برنامه دورهٔ آموزشی خود معرفی می‌کنیم با یکدیگر ناپیوسته نیستند. حقیقت باید همواره حقیقی باشد، اگر حقیقی است. حقیقت نمی‌تواند با خودش در تضاد باشد، یا در بخش‌هایی نامطمئن و در بخش‌هایی مطمئن باشد. تو نمی‌توانی جدا از خداوند* در دنیا گام برداری، زیرا نمی‌توانی بدون او* باشی. او* زندگی تو است. جایی که تو هستی او* هست. یک زندگی وجود دارد. تو آن زندگی را با او* سهیم هستی. هیچ چیزی نمی‌تواند جدا از او* باشد و زندگی کند .

اما هر جا که او* هست، باید قداست در کنار زندگی باشد. همهٔ صفات او* توسط هر چیزی که زنده است به اشتراک گذاشته می‌شود. آنچه زندگی می‌کند مانند خودش* مقدس است، زیرا آنچه در زندگی او* سهیم می‌شود، بخشی از قداست است، و دیگر نمی‌تواند بیش از آن گناهکار باشد که خورشید هست زمانی که انتخاب کند از یخ باشد؛ دریا هست زمانی که انتخاب کند از آب جدا باشد، یا چمن هست زمانی که انتخاب کند با ریشه‌هایی آویخته در هوا رشد نماید.

نوری در تو وجود دارد که نمی‌تواند خاموش شود؛ حضور آن چنان مقدس است که دنیا به خاطر تو تطهیر می‌شود. همهٔ چیزهایی که زندگی می‌کنند برای تو هدایایی می‌آورند، و آن‌ها را در سپاسگزاری و شادمانی به پای تو نثار می‌کنند. رایحهٔ گل‌ها هدیهٔ آن‌ها به تو است. موج‌ها پیش روی تو کرنش می‌کنند، و درختان بازوانشان را برای حفاظت از تو در برابر گرما می‌گشایند، و برگ‌هایشان را پیش روی تو بر زمین می‌ریزند تا تو بتوانی به نرمی گام برداری، در حالی که باد پیرامون سر مقدس تو به نجوا می‌پردازد.

آن نور که در درون تو است، چیزی است که جهان طالب دیدن آن است. همه‌ی چیزهای زنده در برابر تو ساکن هستند، زیرا آنها تشخیص می‌دهند که چه کسی* با تو گام بر می‌دارد. نوری که تو حمل می‌کنی از آن خود آن‌ها است. و این چنین آنان در تو قداست خود را می‌بینند، و به تو به عنوان منجی و به عنوان خداوند* درود می‌فرستند. تکریم آنان را بپذیر، زیرا مربوط به خود* قداست* است، که با تو گام بر می‌دارد، و در نور مهربانش همهٔ چیزها را به یگانگی و خلوصش متحول می‌سازد.

این شیوهٔ عمل رستگاری است. زمانی که تو عقب می‌نشینی، نور درون تو به پیش می‌آید و دنیا را فرا می‌گیرد. این نور، پایان گناه را در مجازات و مرگ اعلام نمی‌کند. گناه در سبکی و در خنده برطرف می‌شود، زیرا پوچی عجیب آن دیده می‌شود. گناه یک پندار نابخردانه است، یک رؤیای ابلهانه، غیرهراسناک، احتمالا مسخره، اینک چه کسی می‌خواهد یک لحظه را در رسیدن به خود* خداوند* با چنین هوس بی‌معنایی تلف کند؟

اما تو سالهای بسیار زیادی را فقط با این پندار نابخردانه تلف کرده‌ای. گذشته سپری شده است، با همه ی تخیلاتش. آن‌ها دیگر تو را در بند نگه نمی‌دارند. رسیدن به خداوند* نزدیک است. و در وقفهٔ کوچک از تردید که هنوز باقی مانده است، ممکن است تو دیدن همدم* خود را گم کنی، و او* را با رؤیای بی‌معنای دیرینی که اکنون سپری شده است اشتباه بگیری.

«چه کسی* با من گام بر می‌دارد؟» این پرسش را باید هزار مرتبه در هر روز پرسید، تا زمانی که اطمینان به تردید پایان دهد و صلح را مستقر سازد. امروز اجازه بده تردید از میان برود . خداوند* برای تو سخن می‌گوید با پاسخ دادن به پرسشت با این کلام: من با خداوند* در قداست کامل گام بر‌می‌دارم. من دنیا را روشن می‌کنم، من ذهنم و همهٔ ذهن‌هایی را که خداوند* با من یگانه آفرید روشن می‌کنم.', 'https://acim-farsi.org/workbook/lesson/156', 'https://acim-farsi.org/audio/workbook/lesson/156.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (157, 'من می‌خواهم اکنون به محضر او* وارد شوم.', 'من می‌خواهم اکنون به محضر او* وارد شوم.', 'من می‌خواهم اکنون به محضر او* وارد شوم.

امروز روز سکوت و اطمینان است. این زمان ویژه‌ای از نوید در تقویم روزهای تو است. این زمانی است که بهشت* برای تابش بر تو برگزیده است، و امروز نور بی‌زمانی را می‌تاباند، زمانی که پژواک‌های ابدیت شنیده می‌شوند. امروز مقدس است، زیرا طلیعهٔ یک تجربهٔ جدید است؛ نوع متفاوتی از احساس و آگاهی. تو روزها و شب‌های طولانی را در جشن گرفتن مرگ گذرانده‌ای. امروز می‌آموزی که سرور زندگی را احساس کنی.

این نقطه‌ی عطف سرنوشت‌ساز دیگری در این برنامه آموزشی است. اینک ما بعد جدیدی را اضافه می‌کنیم؛ تجربه‌ی تازه‌ای که نوری را بر همه‌ی آنچه که تا حال آموخته‌ایم می‌تاباند و ما را برای آنچه قرار است بیاموزیم آماده می‌کند. این تجربه ما را به سوی دری می‌برد که آموختن محو می‌شود، و ما نگاهی خواهیم انداخت به آنچه ورای بالاترین دستاوردهایی که آموختن می‌تواند داشته باشد، قرار دارد. این تجربه ما را در اینجا لحظه‌ای ترک می‌کند، و ما به ورای آن می‌رویم، مطمئن از مسیر و تنها هدف خودمان.

امروز لمسی از بهشت* به تو داده خواهد شد، اگرچه سپس به مسیرهای آموختن بر خواهی گشت. اما تو به اندازه کافی در طول طریق سیر کرده‌ای تا زمان را تغییر دهی و به ماورای قانون‌های آن بروی، و لحظه‌ای به درون ابدیت گام برداری. تو انجام این کار را بیشتر و بیشتر خواهی آموخت، زمانی که با وفاداری هر درس را تمرین کنی، و هر درس تو را سریع‌تر به این مکان مقدس می‌آورد و برای لحظه‌ای با خویشتنت* تنها می‌‌گذارد.

او* امروز به تمرین تو جهت خواهد داد، زیرا آنچه اکنون می‌خواهی، چیزی است که او* اراده می‌کند. و امروز با پیوند دادن اراده‌ات با ارادهٔ* او*، آنچه تو می‌خواهی باید به تو داده شود. به هیچ چیزی جز ایدهٔ امروز نیازی نیست تا ذهن تو را روشن کند و اجازه دهد آن در صبری ساکن و سروری ساکت آرام بگیرد، جایی که در آن به سرعت دنیا را پشت سر می‌گذاری.

از امروز به بعد، مأموریت تو یک سرسپردگی خالص را شامل می‌شود، و گرمایی را که از نوک انگشتانت به سمت آنان که لمسشان می‌کنی می‌رود، و هر آنچه به آن نگاه می‌کنی را متبرک می‌کند. هر کسی که با او ملاقات می‌کنی به رؤیتی دست می‌یابد و هرکس که به او می‌اندیشی، یا به تو می‌اندیشد. زیرا تجربهٔ امروز تو آنچنان ذهنت را دگرگون می‌کند که به سنگ محک برای اندیشه‌های* مقدس خداوند* تبدیل می‌شود.

امروز بدن تو تطهیر خواهد شد، که اینک تنها قصد آن آوردن رؤیت تو از تجربه‌ی امروزت به دنیا برای نورافشانی است. ما نمی‌توانیم تجربه‌ی این‌چنین را مستقیماً منتقل کنیم. اما رؤیتی را در چشمانمان بر جای می‌گذارد که می‌توانیم به همگان عرضه کنیم، تا او بتواند زودتر به همین تجربه دست یابد که در آن دنیا در سکوت فراموش می‌شود و بهشت* برای لحظه‌ای به یاد آورده می‌شود.

با افزایش این تجربه و کم‌ارزش شدن همه‌ی اهداف به جز این، دنیایی که به آن بر خواهی گشت کمی بیشتر به پایان زمان نزدیک خواهد شد؛ کمی بیشتر در شیوه‌هایش شبیه بهشت* می‌شود؛ کمی به رستگاریش نزدیک می‌شود. و تو که نور را به آن می‌آوری با اطمینان بیشتری نور را می‌بینی؛ و رؤیت تو واضح‌تر می‌شود. آن زمان خواهد آمد که تو در همین شکلی که اکنون ظاهرا داری بر نخواهی گشت، زیرا تو نیازی به آن نخواهی داشت. اما اکنون این شکل دارای یک قصد است، و به آن به خوبی خدمت خواهد کرد.

امروز ما دوره‌ای را آغاز خواهیم کرد که تو رؤیای آن را نداشته‌ای. اما آن یگانهٔ مقدس، دهندهٔ رؤیاهای شاد زندگی، ترجمه کنندهٔ ادارک به حقیقت، راهنمای* مقدس به سوی بهشت* که به تو داده شده است، برایت این سفر را که امروز انجام می‌دهی و آغاز می‌کنی، رؤیا دیده است، با تجربه‌ای که امروز به تو داده می‌شود تا متعلق به خودت باشد.

اینک ما به محضر مسیحا* وارد خواهیم شد، به آرامی ناآگاه از هر چیزی به جز چهرهٔ تابنده و عشق کامل او. رؤیت چهرهٔ او با تو خواهد ماند، اما لحظه‌ای خواهد بود که از همهٔ رؤیت‌ها فراتر خواهد رفت، حتی این، مقدس‌ترین. تو این را هرگز تعلیم نخواهی داد، زیرا تو از طریق آموختن به آن دست نیافته‌ای. اما این رؤیت از به یاد آوردن آنچه در آن لحظه می‌دانستی، و آنچه مطمئناً دوباره خواهی دانست سخن می‌گوید.', 'https://acim-farsi.org/workbook/lesson/157', 'https://acim-farsi.org/audio/workbook/lesson/157.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (158, 'امروز من می‌آموزم همانگونه که دریافت می‌کنم بدهم.', 'امروز من می‌آموزم همانگونه که دریافت می‌کنم بدهم.', 'امروز من می‌آموزم همانگونه که دریافت می‌کنم بدهم.

چه چیزی به تو داده شده است؟ این معرفت که تو یک ذهن هستی، در ذهن و ذهن خالص، تا ابد بی‌گناه، کاملا بی‌هراس، زیرا از درون عشق آفریده شده‌ای. تو سرچشمه خود را ترک نکرده‌ای، همانگونه باقی مانده‌ای که آفریده شدی. این به عنوان معرفتی به تو داده شده که نمی‌توانی آن را از دست بدهی. این معرفت همچنین به همه چیزهای زنده داده شد، زیرا فقط با این معرفت است که زنده هستند.

تو همه‌ی این را دریافت کرده‌ای. هر کسی که در دنیا گام برمی‌دارد قطعا این را دریافت کرده است. این معرفت نیست که تو عرضه می‌کنی، زیرا این معرفت را آفرینش عرضه کرد. همه‌ی این را نمی‌توان آموخت. پس امروز می‌آموزی که چه چیزی را بدهی؟ درس دیروز ما موضوعی را به یاد آورد که در اوایل متن یافت می‌شد. تجربیات را نمی‌توان مستقیما در میان گذاشت، آنگونه که رؤیت را می‌توان. این مکاشفه که پدر* و فرزند* یگانه هستند در زمانش به هر ذهنی خطور می‌کند. اما این زمان توسط خود ذهن تعیین می‌شود، تعلیم داده نمی‌شود.

این زمان پیشاپیش تعیین شده است. به نظر می‌رسد که کاملا اختیاری است. اما هیچ گامی در طول طریق نیست که فقط با اقبال برداشته شود. همه گام‌ها پیشاپیش توسط او برداشته شده‌اند، اگرچه هنوز تصمیمش را نگرفته است. زیرا فقط به نظر می‌رسد که زمان در یک راستا پیش می‌رود. اما ما فقط سفری را انجام می‌دهیم که به پایان رسیده است. با این حال به نظر می‌رسد این سفر آینده‌ای دارد که هنوز برای ما ناشناخته است.

زمان یک نیرنگ است، یک تردستی، یک وهم فراگیر که در آن شمایل‌ها گویی به صورتی جادویی می‌آیند و می‌روند. اما نقشه‌ای در پس ظواهر هست که تغییر نمی‌کند. نمایشنامه نوشته شده است. زمان آمدن تجربه برای پایان دادن به به تردید تو مقرر شده است. زیرا ما تنها این سفر را از آن نقطه‌ای می‌بینیم که پایان یافت، و به عقب به آن می‌نگریم، با تصور اینکه آن را یک بار دیگر انجام می‌دهیم؛ در حالیکه در ذهن آنچه که گذشته است را مرور می‌کنیم.

یک آموزگار تجربه را نمی‌دهد، زیرا آن را نیاموخته است. تجربه، خود را در زمان مقررش بر وی آشکار کرده است. اما هدیه او رؤیت است. این را می‌تواند مستقیماً بدهد، زیرا معرفت مسیحا* گم نشده است، زیرا او* رؤیتی دارد که می‌تواند به هر کسی که درخواست می‌کند بدهد. ارادهٔ* پدر* و ارادهٔ* او* در معرفت به هم پیوسته است. رؤیتی وجود دارد که روح‌القدس* می‌بیند زیرا ذهن* مسیحا* نیز آن را مشاهده می‌کند.

در اینجا پیوند بین دنیای تردید و سایه‌ها با دنیای ناملموس برقرار می‌شود. اینجا مکان ساکتی است در دنیا که توسط بخشایش و توسط عشق تقدیس می‌شود. در اینجا همه تعارض‌ها به آشتی می رسند، زیرا در اینجا سفر پایان می‌یابد. تجربهٔ- آموخته نشده، تعلیم داده نشده- فقط در اینجا است. این فراتر از هدف ما است، زیرا این فراتر از آن چیزی است که نیاز به دستیابی به آن هست. دلبستگی ما با رؤیت مسیحایی* است. ما می‌توانیم به این دست یابیم.

رؤیت مسیحا یک قانون دارد. به بدن نمی‌نگرد، و آن را با فرزندی* که خداوند* آفرید اشتباه نمی‌گیرد. آن نوری را ورای بدن می‌بیند؛ ایده‌ای ورای آنچه می‌تواند لمس شود، خلوصی که با خطاها، اشتباهات رقت‌انگیز، و پندارهای ترسناکِ احساس گناهِ ناشی از رؤیاهای گناه، کم‌سو نمی‌شود. آن هیچ جدایی را نمی‌بیند. و به هر کس، در هر شرایط، اتفاق و رویداد بدون کوچکترین کاهش در نوری که می‌بیند می‌نگرد.

این را می‌توان تعلیم داد؛ و باید توسط همه آنانکه به آن دست می‌یابند تعلیم داده شود. فقط به این تشخیص نیاز است که دنیا توان عرضه هیچ چیزی را ندارد که بتواند در ارزش، ذره‌ای با این مقایسه شود؛ یا هدفی را تعیین کند که با این ادراک، صرفا ناپدید نشود. و امروز تو این را عرضه می‌کنی: هیچ کس را به عنوان یک بدن نبین. به او به عنوان فرزند* خداوند* که هست درود بفرست، با تصدیق اینکه او* در قداست با تو یگانه است.

چنین است که گناهانش به او بخشیده می‌شود، زیرا مسیحا* رؤیتی دارد که توان چشم‌پوشی از همهٔ آن‌ها را دارد. در بخشایشِ او* آن‌ها ناپدید می‌شوند. با دیده نشدن توسط آن یگانه* آن‌ها فقط ناپدید می‌شوند، زیرا رؤیتی از قداست که ورای آن‌ها نهفته است می‌آید تا جایگزینشان شود. اهمیتی ندارد که چه شکلی گرفته‌اند، یا ظاهراً چقدر بزرگ هستند، یا به نظر می‌رسد چه کسی توسط آنها آسیب دیده است. آنها دیگر وجود ندارند. و همه‌ی تأثیراتی که به نظر می‌آمد دارند با آنها محو می‌شوند، باطل شده و دیگر هرگز انجام نمی‌شوند.

چنین است که تو می‌آموزی بدهی آنچنانکه دریافت می‌کنی. و چنین است که رؤیت مسیحایی* به تو نیز نظر می‌کند. آموختن این درس دشوار نیست، اگر به یاد بیاوری که تو در برادرت فقط خودت را می‌بینی. اگر او در گناه گم شده باشد، تو هم باید چنین باشی؛ اگر در او نور را ببینی، گناهان تو توسط خودت بخشوده شده‌اند. هر برادری را که امروز ملاقات می‌کنی فرصت دیگری را فراهم می‌کند تا اجازه دهی رؤیت مسیحایی* بر تو بتابد، و صلح خداوند* را به تو عرضه کند.

اهمیتی ندارد که چه زمان مکاشفه پیش می‌آید، زیرا مکاشفه زمان ندارد. اما زمان هنوز یک هدیه برای دادن دارد، که در آن معرفت حقیقی آنچنان به دقت بازتاب می‌یابد که تصاویرش قداست نادیدنی آن را سهیم می‌شوند؛ آنچه با آن مشابه است با عشق نامیرایش می‌درخشد. امروز ما دیدن با چشمان مسیحا* را تمرین می‌کنیم. و با هدایای مقدسی که می‌دهیم، رؤیت مسیحایی* بر خود ما نیز نظر می‌کند.', 'https://acim-farsi.org/workbook/lesson/158', 'https://acim-farsi.org/audio/workbook/lesson/158.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (159, 'من معجزاتی را که دریافت کرده‌ام می‌دهم.', 'من معجزاتی را که دریافت کرده‌ام می‌دهم.', 'من معجزاتی را که دریافت کرده‌ام می‌دهم.

هیچ‌کس نمی‌تواند چیزی را بدهد که دریافت نکرده است. دادن چیزی ابتدا مستلزم این است که آن را در مالکیت خود داشته باشی. در اینجا قانون‌های بهشت* و دنیا توافق دارند. اما اینجا از یکدیگر جدا نیز هستند. دنیا باور دارد که برای مالکیت چیزی باید آن را نگه داشت. رستگاری چیز دیگری را تعلیم می‌دهد. دادن شیوه‌ای است برای تشخیص اینکه تو دریافت کرده‌ای. دادن گواه این است که آنچه دادی از آن تو است.

تو زمانی که شفا را عرضه می‌کنی می‌فهمی که شفا یافته‌ای. تو زمانی که می‌بخشی می‌پذیری که بخشایش در تو مستقر شده است. برادرت را به عنوان خودت می‌شناسی، و این‌چنین درک می‌کنی که کامل هستی. هیچ معجزه‌ای نیست که تو نتوانی بدهی، زیرا همه معجزات به تو داده شده‌اند. اینک آنها را با گشودن انبار ذهنت، جایی که قرار دارند دریافت کن و آن‌ها را اهدا کن.

رؤیت مسیحایی* یک معجزه است. این رؤیت از بسیار فراتر از خودش می‌آید، زیرا این رؤیت عشق ابدی و تولد دوباره عشق را بازتاب می‌دهد که هرگز نمی‌میرد، اما مبهم نگه داشته شده است. رؤیت مسیحایی* بهشت* را تصویر می‌کند، زیرا دنیایی را می‌بینید آنچنان همانند با بهشت*، که آنچه خداوند* کامل آفرید می‌تواند در آن بازتاب یابد. شیشه تیره‌ای که دنیا ارائه می‌کند فقط می‌تواند تصاویر مغشوش را در قطعه‌های شکسته نشان دهد. دنیای واقعی، بی‌گناهی بهشت* را به تصویر می‌کشد.

رؤیت مسیحایی* آن معجزه است که در آن تمامی معجزات متولد می‌شوند. این رؤیت سرچشمه آنان است، با هر معجزه‌ای که عرضه می‌کنی باقی می‌ماند، و در عین حال از آن خود تو می‌ماند. این پیوندی است که توسط آن دهنده و دریافت کننده اینجا در روی زمین با وجود فاصله با هم یگانه می‌شوند، آنچنان که در بهشت* با هم یگانه هستند. مسیحا* هیچ گناهی را در هیچ‌کس نمی‌بیند. و در بینش او* بی‌گناهان با هم یگانه هستند. قداست آنان توسط پدرش* و خودش* عطا شده است.

رؤیت مسیحایی* پل بین دنیاها است. و در قدرت آن تو می‌توانی با امنیت اعتماد کنی که از این دنیا به دنیایی برده شوی که توسط بخشایش تقدیس شده است. چیزهایی که در اینجا به نظر جامد می‌رسند در آنجا صرفا سایه‌هایی هستند؛ نیمه واضح، به سختی قابل دیدن، گاهی فراموش شده، و هرگز توان جلوگیری از نوری را که در ورایشان می‌تابد ندارند. قداست به رؤیت بازگردانده می‌شود، و نابینا می‌تواند ببیند.

این یگانه هدیهٔ روح‌القدس* است؛ خزانه گنجی که تو می‌توانی به آن با اطمینان کامل به همه چیزهایی که حاضر هستند به شادمانی‌ات کمک کنند، پناه ببری. همه این چیزها اینک در اینجا قرار دارند. همه آنها را می‌توان صرفا با خواستن دریافت کرد. در اینجا در هرگز قفل نیست، و کوچکترین درخواست یا ضروری‌ترین نیاز هیچ‌کس نادیده گرفته نمی‌شود. هیچ بیماری وجود ندارد که پیشاپیش شفا نیافته باشد، هیچ فقدانی که جبران نشده باشد، هیچ نیازی که در این گنج زرین مسیحایی* برآورده نشده باشد.

در اینجا دنیا به یاد می‌آورد که در زمان ساخته شدنش، چه چیزی مفقود شد. زیرا اینجا ترمیم می‌یابد، دوباره نو می‌شود، اما در نوری متفاوت. آنچه که قرار بود خانه گناه باشد، به مرکز نجات و قلب رحمت تبدیل می‌شود، جایی که رنج‌دیدگان شفا می‌یابند واز آن‌ها استقبال می‌گردد. هیچ‌کس از این خانه جدید، جایی که رستگاری‌اش منتظر است رانده نخواهد شد. هیچ‌کس برای او بیگانه نیست. هیچ‌کس چیزی را از او نخواهد خواست به جز هدیه پذیرش او از استقبالش.

رؤیت مسیحایی* آن زمین مقدس است که در آن گل‌های سوسن بخشایش ریشه می‌کنند. این خانه آنان است. آنها را می‌توان از اینجا به دنیا باز آورد، اما هرگز نمی‌توانند در خاک نامغذی و کم‌عمق آن رشد کنند. آنها نیاز به نور و گرما و مراقبت مهربانانه‌ای دارند که خیرخواهی مسیحایی* تأمین می‌کند. آن‌ها نیاز به عشقی دارند که او* با آن عشق به ایشان نظر می‌کند. و آنها به پیام‌آوران او* تبدیل می‌شوند، که آنچه را که دریافت می‌کنند، می‌دهند.

از خزانه مقدس او* دریافت کن، تا گنجینه‌هایش بتوانند افزون شوند. سوسن‌های او زمانی که به دنیا باز آورده شوند خانه خود را ترک نمی‌کنند. ریشه‌هایشان باقی می‌ماند. سرچشمه خود را ترک نمی‌کنند، اما خیر آن را با خود حمل می کنند، و دنیا را به باغی تبدیل می‌کنند مانند آن باغ که از آنجا آمده‌اند، و با رایحه‌ای افزون به آن باز می‌گردند. این‌چنین آنها به طرز مضاعفی متبرک می‌شوند. پیام‌هایی که از سوی مسیحا* آوردند منتقل شده است، و به آنان باز گشته است. و آن‌ها شادمانه این پیام‌ها را به سمت او باز می‌گردانند.

گنجینه‌ی معجزات را که برای دادن به تو ارزانی شده است، ببین. آیا تو شایسته این هدیه نیستی، زمانی که خداوند* دادن آن را به تو مقرر کرد؟ فرزند* خداوند* را قضاوت نکن، بلکه طریقی را که او* مقرر کرده است دنبال کن. مسیحا* رؤیای یک دنیای بخشوده شده را رؤیا دیده است. این هدیه او* است، که از طریق آن تبدیل لذت‌بخش مرگ به زندگی می‌تواند انجام پذیرد؛ تبدیل ناامیدی به امید. بگذار لحظه‌ای با او* رؤیا ببینیم. رؤیای او* ما را به حقیقت بیدار می‌کند. رؤیت او* ابزاری را عرضه می‌کند برای بازگشت به قداست مفقود نشده و ابدی ما نزد خداوند*.', 'https://acim-farsi.org/workbook/lesson/159', 'https://acim-farsi.org/audio/workbook/lesson/159.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (160, 'من در خانه هستم. ترس در اینجا بیگانه است.', 'من در خانه هستم. ترس در اینجا بیگانه است.', 'من در خانه هستم. ترس در اینجا بیگانه است.

ترس برای طریق عشق بیگانه است. خود را با ترس یکی بدان، و تو با خودت بیگانه خواهی بود. و در این صورت برای خودت ناشناخته می‌شوی. آنچه که خویشتن* تو است برای بخشی از تو که می‌اندیشد واقعی است اما با خودت متفاوت است، یک بیگانه باقی می‌ماند. چه کسی در چنین شرایطی می‌تواند عاقل باشد؟ چه کسی به جز یک دیوانه می‌تواند باور کند چیزی هست که نیست، و بر علیه خودش قضاوت نماید؟

بیگانه‌ای در میان ماست، که از عقیده‌ای آن‌چنان بیگانه با حقیقت می‌آید که به زبان متفاوتی سخن می‌گوید، به دنیایی می‌نگرد که حقیقت را نمی‌داند، و چیزی را درک می‌کند که حقیقت آن را بی‌معنا می‌بینید. با وجود بیگانه بودن، او تشخیص نمی‌دهد به نزد چه کسی آمده است، و می‌اندیشد که خانهٔ او از آن وی است، در حالی که آن کسی که در خانه است بیگانه شمرده می‌شود. و با این وجود چه آسان می‌توان گفت، «این خانهٔ من است. من به اینجا تعلق دارم، و اینجا را ترک نخواهم کرد زیرا یک دیوانه می‌گوید باید چنین کنم.»

چه دلیلی دارد که این چنین سخن نگویی؟ چه دلیلی می‌تواند باشد به جز اینکه تو این بیگانه را فراخوانده بودی تا جایت را بگیرد، و اجازه دهد تو با خودت بیگانه شوی؟ هیچ کس نمی‌خواهد به خودش اجازه دهد چنین بیهوده مالکیتش سلب شود، مگر چنین اندیشیده باشد که خانه‌ی دیگری هست که برای سلیقه او مناسب‌تر است.

بیگانه کیست؟ آیا برای منزلی که خداوند* برای فرزندش* فراهم کرد ترس نامناسب است یا تو؟ آیا ترس از آن خود* او* است، که در همانندی با او* آفریده شد؟ آیا این ترس است که عشق آن را کامل می‌کند، و توسط آن کامل می‌شود؟ هیچ خانه‌ای وجود ندارد که بتواند عشق و ترس را زیر یک سقف داشته باشد. آنها نمی‌توانند همراه با یکدیگر وجود داشته باشند. اگر تو واقعی هستی، آنگاه ترس باید وهم باشد. و اگر ترس واقعی است، آنگاه تو اصلاً وجود نداری.

پس چه آسان پرسش حل می‌شود. کسی که می‌ترسد فقط خودش را انکار کرده و گفته است، «من اینجا بیگانه هستم. و خانه‌‌ام را برای او که به خودم از من شبیه‌تر است ترک می‌کنم، و به او همه آنچه را که می‌اندیشیدم به من تعلق دارد می‌دهم.» حال او از آنچه برای او ضروری است تبعید می‌شود، بدون اینکه بداند کیست، نامطمئن از هر چیزی به جز این؛ که او خودش نیست، و خانه‌اش از او دریغ شده است.

اینک او در جستجوی چیست؟ چه چیزی می‌تواند بیاید؟ یک بیگانه برای خود نمی‌تواند هیچ خانه‌ای در هر جا که می‌نگرد پیدا کند، زیرا او بازگشت را ناممکن کرده است. راه او گم شده است، فقط یک معجزه به جستجویش پایان خواهد داد و به او نشان می‌دهد که دیگر یک بیگانه نیست. این معجزه خواهد آمد. زیرا در خانه‌اش، خویشتن* او باقی می‌ماند. این خویشتن* هیچ بیگانه‌ای را به درون راه نداد، و هیچ فکر بیگانه‌ای را با خودش* اشتباه نگرفت. و این خویشتن*، خودش* را به سمت خودش* فرا خواهد خواند تا تشخیص دهد که این خود* چیست.

بیگانه کیست؟ آیا بیگانه او نیست که خویشتن* تو فرا نمی‌خواند؟ تو در حال حاضر از شناسایی این بیگانه در دل خود ناتوان هستی، زیرا جایگاه برحق خود را به او داده‌ای. اما خویشتن* تو از خودش چنان مطمئن است که خداوند* به فرزندش* اطمینان دارد. او* نمی‌تواند در مورد آفرینش به خطا بیفتد. او* از آنچه به خودش* تعلق دارد مطمئن است. هیچ بیگانه‌ای نمی‌تواند بین معرفت او* و واقعیت فرزندش* قرار گیرد. او* بیگانگان را نمی‌شناسد. او* از فرزند* خود* مطمئن است.

اطمینان خداوند* کفایت می‌کند. او* که می‌داند فرزندش* به کجا تعلق دارد و آن را برای همیشه برایش مقرر کرده است. او به تو که می‌پرسی، «بیگانه کیست؟» پاسخ داده است. آوای* او* را بشنو که به تو اطمینان می‌دهد، در سکوت و با قاطعیت، که تو برای پدرت* بیگانه نیستی، همچنین آفریدگارت* تو را بیگانه با خود نساخت. آنکس که خداوند* به او پیوسته است همیشه یگانه می‌ماند، در منزلش نزد او*، که هرگز بیگانه با خودش* نیست.

امروز ما سپاس خود را نثار می‌کنیم که مسیحا* برای جستجوی دنیا جهت یافتن آنچه به خودش* تعلق دارد، آمد. رؤیت او* هیچ بیگانه‌ای نمی‌بیند، بلکه خود* او* را می‌بیند و با آنان مسرورانه یگانه می‌شود. آنان او* را مانند یک بیگانه می‌بینند، زیرا خودشان را نمی‌شناسند. اما با استقبال از او*، آن‌ها به یاد می‌آورند. و او* دوباره آنان را مهربانانه به خانه راهنمایی می‌کند، جایی که به آن تعلق دارند.

مسیحا* هیچ‌کس را فراموش نمی‌کند. بی‌شک همه را به یاد تو می‌آورد، تا منزل تو بتواند کامل و بی‌نقص باشد آنگونه که مقرر شد. او* تو را فراموش نکرده است. اما تو او* را به یاد نخواهی آورد تا زمانی که مانند او* به همه چیز نگاه کنی. کسی که برادر خود را نادیده می‌گیرد، خود را نادیده می‌گیرد، و در این صورت از پذیرفتن هدیهٔ بینایی سرباز می‌زند، بینایی‌ای که توسط آن خویشتن* او به روشنی شناخته می‌شود، منزلش به یاد آورده می‌شود و رستگاری می‌آید.', 'https://acim-farsi.org/workbook/lesson/160', 'https://acim-farsi.org/audio/workbook/lesson/160.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (161, 'مرا تبرک کن، فرزند* مقدس خداوند*.', 'مرا تبرک کن، فرزند* مقدس خداوند*.
من می‌خواهم تو را با چشمان مسیحا* ببینم، و بی‌گناهی کامل خود را در تو ببینم.
من می‌خواهم تو را با چشمان مسیحا* ببینم، و بی‌گناهی کامل خود را در تو ببینم.', 'مرا تبرک کن، فرزند* مقدس خداوند*.

امروز ما به طرز متفاوتی تمرین می‌کنیم، و در برابر خشم خود می‌ایستیم، تا ترس‌هایمان بتوانند ناپدید شوند و برای عشق جا باز شود. در اینجا رستگاری در کلمات ساده حضور می‌یابد و با این کلمات ایدهٔ امروز را تمرین می‌کنیم. در اینجا پاسخی است به این وسوسه که ترس و خشم پیشاپیش غالب شده‌اند، وسوسه‌ای که بی‌گمان با استقبال از مسیحا* از بین می‌رود. در اینجا آمرزش* کامل می‌شود، از دنیا در امنیت عبور کرده می‌شود و بهشت* اینک اعاده می‌شود. در اینجا پاسخ آوای* برای خداوند* حضور دارد.

انتزاع کامل حالت طبیعی ذهن است. اما در حال حاضر بخشی از آن طبیعی نیست. ذهن در حال حاضر به همه چیز در یگانگی نمی‌نگرد. در عوض فقط بخش‌هایی از تمامیت را می‌بیند، زیرا فقط در این صورت می‌تواند دنیای قطعه قطعه را که تو می‌بینی ابداع کند. قصد هر دیدنی این است که آنچه را که می‌خواهی ببینی به تو نشان دهد. هر شنیدنی تنها صداهایی را که می‌خواهد بشنود به ذهن تو می‌آورد.

ویژگی‌ها چنین ساخته شده‌اند. و اینک ما باید در تمرین خود از ویژگی‌ها استفاده کنیم. ما آن‌ها را به روح‌القدس* می‌دهیم، تا او بتواند آن‌ها را برای قصدی مورد استفاده قرار دهد که با آن قصد که ما به آن‌ها داده‌ایم، متفاوت است. اما او* فقط می‌تواند از چیزی که ما ساختیم، برای آموزش دادن به ما از نقطه نظر دیگری استفاده کند، تا ما بتوانیم استفاده متفاوتی را در همه چیز ببینیم.

یک برادر، همهٔ برادران است. هر ذهنی حاوی همهٔ ذهن‌ها است، زیرا هر ذهنی یگانه است. حقیقت چنین است. اما آیا این اندیشه‌های ما معنای آفرینش را واضح می‌سازند؟ آیا این کلمات با خود وضوح کاملی را برای تو می‌آورند؟ آیا چه می‌توانند به نظر برسند جز صداهای خالی؛ شاید زیبا، و از نظر احساسی درست، اما اساساً نه درک شده و نه قابل درک. ذهنی که به خودش آموزش‌ دهد بر اساس ویژگی‌ها بیاندیشد دیگر نمی‌تواند انتزاع را در مفهومی دریابد که فراگیر عام باشد. ما نیاز داریم کمی ببینیم، تا بسیار زیاد بیاموزیم.

به نظر می‌رسد آنچه احساس می‌کنیم محدود کنندهٔ آزادی ماست، موجب رنج ما می‌شود، و سرانجام به زندگی پایان می‌دهد، بدن ما باشد. اما بدن‌ها صرفاً نماد‌هایی برای شکل قابل لمس از ترس هستند. ترس بدون نماد‌هایش هیچ پاسخی را در پی نخواهد داشت، زیرا این نمادها می‌توانند از آنچه بی‌معناست دفاع کنند. عشق نیازمند هیچ نمادی نیست، زیرا حقیقی است. اما ترس به ویژگی‌ها متصل می‌شود، زیرا دروغین است.

بدن‌ها حمله می‌کنند، اما ذهن‌ها چنین نمی‌کنند. این اندیشه مطمئنا یادآور مطالب بخش متن ما است، جایی که بارها بر آن تاکید نمودیم. این دلیل تبدیل شدن آسان بدن‌ها به نمادهای ترس است. بارها از تو خواسته شد به ورای بدن نظر کنی، زیرا منظرهٔ بدن تجلی «دشمن» عشق است که رؤیت مسیحایی* آن را نمی‌بیند. بدن هدف حمله است، زیرا هیچ‌کس نمی‌اندیشد که از یک ذهن متنفر است. اما چه چیز جز ذهن بدن را به سمت حمله هدایت می‌کند؟ چه چیز دیگری می‌تواند جایگاه ترس باشد مگر آنچه به ترس می‌اندیشد؟

نفرت خاصیت ویژه بودن دارد. چیزی باید باشد که به آن حمله شود. باید دشمن را در چنان شکلی درک کرد که بتواند لمس شود و دیده شود و شنیده شود، و نهایتا کشته شود. وقتی نفرت متوجه چیزی می‌شود، مرگ را می‌خواهد با همان اطمینان که آوای* خداوند* اعلام می‌کند مرگی وجود ندارد. ترس سیری‌ناپذیر است، همه چیزهایی را که چشمانش می‌بیند از پا در می‌آورد، خودش را در همه چیز می‌بیند، ناچار می‌شود به سمت خودش برگردد و تخریب کند.

آنکس که برادر خود را به عنوان یک بدن می‌بیند، او را به عنوان نماد ترس می‌بینید. و حمله خواهد کرد، زیرا آنچه می‌بیند ترس خود اوست در بیرون از خودش، آماده برای حمله، و در حال فریاد زدن برای اینکه دوباره با او یکی شود. از شدت خشمی که ترس باید برای تکثیر خود فرافکن کند، دچار اشتباه نشو. با غضب فریاد می‌کشد، و پنجه‌هایش را در هوا با امید خشمگینانه به اینکه بتواند سازندهٔ خود را بیابد و آن را قطعه قطعه کند تکان می‌دهد.

این‌ها را چشمان بدن در او که بهشت* گرامی‌اش می‌دارد می‌بیند، او که فرشتگان عاشقش هستند و خداوند* کاملش آفرید. واقعیت او این است. و در رؤیت مسیحایی* عاشقانه بودن او در شکلی چنان مقدس و چنان زیبا بازتاب می‌یابد که تو به سختی می‌توانی از زانو زدن پیش پاهایش خودداری کنی. اما تو به جای این دست او را خواهی گرفت، زیرا در بینشی که چنین به او می‌نگرد مانند او هستی. حمله کردن به او دشمن تو است، زیرا تو درک نخواهی کرد که رستگاری‌ات در دستان اوست. فقط این را از او بخواه، و او آن را به تو خواهد داد. از او نخواه نماد ترس تو باشد. آیا می‌خواهی درخواست کنی که عشق خودش را تخریب کند؟ یا می‌خواهی عشق بر تو آشکار شود و تو را آزاد کند؟

امروز ما به شکلی تمرین می‌کنیم که قبلا هم انجام داده‌ایم. اینک تو آماده‌تر هستی، و امروز به رؤیت مسیحایی* نزدیکتر خواهی شد. اگر مصممم هستی به آن دست یابی، امروز توفیق خواهی یافت. و به محض توفیق یافتن، دیگر نخواهی خواست که شواهدی را که چشمان بدنت ارائه می‌کنند بپذیری. آنچه خواهی دید نغمه‌های دیرینی را برای تو ترنم خواهد کرد که به یاد خواهی آورد. تو در بهشت* فراموش نشده‌ای. آیا نمی‌خواهی آن را به یاد بیاوری؟

یک برادر خود را انتخاب کن، نمادی از بقیه، و رستگاری را از او بخواه. او را ابتدا با نهایت وضوحی که می‌توانی ببین، به همان شکلی به آن عادت کرده‌ای. چهره‌اش را ببین، دستانش و پاهایش، لباسش. ببین که لبخند می‌زند، و حالتهای آشنایی را که بیشتر اوقات از او دیده می‌شود، ببین. سپس به این بیاندیش: آنچه تو اکنون می‌بینی منظرهٔ کسی را که می‌تواند تو و همه گناهانت را ببخشد، پنهان می‌کند؛ کسی که دستان مقدسش می‌توانند میخ‌ها را از مشت دردناک تو باز کنند، و تاج خاری را که تو بر سر خون‌آلود خود نهاده‌ای، بردارند. این را از او بخواه، که بتواند تو را آزاد کند: برکت خود را به من عطا کن، فرزند* مقدس خداوند*. من می‌خواهم تو را با چشمان مسیحا* ببینم، و بی‌گناهی کامل خود را در تو ببینم.

و او* به آنکس* که تو فرا خوانده‌ای پاسخ خواهد داد. زیرا او آوای* برای خداوند* را در تو خواهد شنید، و با آوای خود تو به آن پاسخ می‌دهد. او را اینک ببین، او را که فقط به صورت گوشت و استخوان دیده‌ای، و تشخیص بده که مسیحا* به سمت تو آمده است. ایدهٔ امروز فرار امن تو از خشم و از ترس است. مطمئن شو که هر زمان که وسوسه می‌شوی به برادر خود حمله کنی، و در او نماد ترس خود را ادراک کنی، آن را فوراً مورد استفاده قرار می‌دهی. و خواهی دید که او ناگهان از دشمن به منجی تبدیل می‌شود؛ از شیطان به مسیحا*.', 'https://acim-farsi.org/workbook/lesson/161', 'https://acim-farsi.org/audio/workbook/lesson/161.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (162, 'من آنگونه هستم که خداوند* مرا آفرید.', 'من آنگونه هستم که خداوند* مرا آفرید.', 'من آنگونه هستم که خداوند* مرا آفرید.

این اندیشه واحد، اگر به استواری در ذهن نگه داشته شود، دنیا را نجات می‌دهد. گاه به گاه ما آن را تکرار خواهیم کرد، زمانی که به مرحله دیگری در آموختن می‌رسیم. همچنانکه تو پیشرفت می‌کنی معنای آن برایت وسیع‌تر خواهد شد. این کلمات مقدس هستند، زیرا کلماتی هستند که خداوند* در پاسخ به دنیایی که تو ساخته‌ای عرضه کرده است. با این کلمات، این دنیا ناپدید می‌شود، و همه چیزهایی که در ابرهای ابهام‌آمیز و اوهام بخارگونه آن دیده می‌شوند، با گفته شدن این کلمات محو می‌گردند. زیرا این کلمات از خداوند* می‌آیند.

اینجا کلامی هست که با آن فرزند* به شادمانی پدر* خود تبدیل شد، عشق او* و تکمیل او*. در اینجا آفرینش علنی می‌گردد، و آنگونه که هست گرامی داشته می‌شود. هیچ رؤیایی نیست که این کلمات نتوانند برطرف کنند؛ هیچ پنداری از گناهکاری و هیچ وهمی که در رؤیا حضور داشته باشد نخواهد توانست در برابر توان این کلمات مقاومت کند و محو نشود. این کلمات شیپور بیداری هستند که در سراسر دنیا به صدا در می‌آید. مردگان در پاسخ به فراخوان آن برمی‌خیزند. و آنان که زنده هستند و صدای آن را می‌شنوند هرگز به مرگ نمی‌نگرند.

حقیقتا مقدس است او که این کلمات را از آن خود می‌سازد؛ با این کلمات در ذهنش از خواب برمی‌خیزد، کلمات را در طول روز به یاد می‌آورد، در شب این کلمات را زمانی که به خواب می‌رود با خود می‌برد. رؤیاهای او شاد هستند و آرامش او تأمین است، امنیت او قطعی است و بدنش شفا می‌یابد، زیرا او با حقیقتی که همیشه پیش روی خود دارد می‌خوابد و بیدار می‌شود. او دنیا را نجات خواهد داد، زیرا به دنیا چیزی را می‌دهد که هر بار کلمات حقیقت را تمرین می‌کند، دریافت می‌نماید.

امروز ما به سادگی تمرین می‌کنیم. زیرا کلماتی که استفاده می‌کنیم توانا هستند، و به هیچ اندیشه‌ای فراتر از خودشان نیاز ندارند تا ذهن کسی را که از آنها استفاده می‌کند، تغییر دهند. این ذهن آن‌چنان به طور کامل تغییر می‌کند که گنجینه‌ای می‌شود تا در آن خداوند* همه هدایای خود* را و همه عشق* خود* را قرار دهد، تا به همه منتشر گردد، و با دادن افزون شود؛ در حالی که کامل نگه داشته می‌شود زیرا انتشار آن نامحدود است. و این‌چنین تو می‌آموزی که با خداوند* بیاندیشی. رؤیت مسیحا* بینایی تو را با نجات دادن ذهنت، ترمیم کرده است.

ما امروز به تو افتخار می‌کنیم. قداست کامل که تو اینک می‌پذیری، حق تو است. با این پذیرش، رستگاری به همگان عطا می‌شود، زیرا چه کسی می‌تواند گناه را گرامی بدارد زمانی که قداستی مانند این دنیا را تبرک کرده باشد؟ چه کسی می‌تواند ناامید باشد زمانی که شادمانی کامل از آن تو است، در دسترس همگان به عنوان نوش دارویی برای ماتم و فلاکت، همه احساس فقدان، و برای فرار کامل از گناهکاری و احساس گناه؟

و چه کسی می‌تواند اینک برادر تو نباشد؛ تو، رها کننده و نجات دهندهٔ او. چه کسی می‌تواند از تو در قلبش با دعوت عاشقانه استقبال نکند، که مشتاق یگانگی با کسی مانند او در قداست هستی؟ تو آنگونه هستی که خداوند* تو را آفرید. این کلمات شب را می‌رانند، و دیگر تاریکی نخواهد بود. امروز نور می‌آید تا دنیا را تبرک کند. زیرا تو فرزند* خداوند* را شناخته‌ای، و در این شناخت، شناخت دنیا حضور دارد.', 'https://acim-farsi.org/workbook/lesson/162', 'https://acim-farsi.org/audio/workbook/lesson/162.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (163, 'هیچ مرگی وجود ندارد. فرزند* خداوند* آزاد است.', 'هیچ مرگی وجود ندارد. فرزند* خداوند* آزاد است.', 'هیچ مرگی وجود ندارد. فرزند* خداوند* آزاد است.

مرگ پنداری است که شکل‌های بسیاری به خود می‌گیرد، که اغلب ناشناخته هستند. مرگ ممکن است به صورت غم، ترس، اضطراب یا تردید تظاهر کند؛ به صورت خشم، بی‌ایمانی و فقدان اعتماد، نگرانی برای بدن‌ها، حسادت، و همه شکل‌هایی که در آن‌ها این آرزو که تو چیزی غیر از آن باشی که هستی برای وسوسه کردن تو می‌آید. همهٔ چنین پندارهایی فقط بازتاب‌هایی از پرستش مرگ به عنوان منجی و دهندهٔ آزادی هستند.

تجسم ترس، میزبان گناه، خدایِ گناهکاران و ارباب همهٔ اوهام و فریب‌ها، پندار مرگ نیرومند جلوه می‌کند. زیرا به نظر می‌رسد که این پندار همهٔ چیزهای زنده را در دست چروکیده خود نگه می‌دارد؛ همهٔ امیدها و آرزوها در چنگال پژمرده او هستند؛ همه هدف‌ها فقط در چشمان بی‌فروغ او درک می‌شوند. موجودات شکننده، درمانده و بیمار در پیشگاه تصویر او تعظیم می‌کنند، با این فکر که فقط او واقعی است، گریزناپذیر و شایستهٔ اعتماد آنان. زیرا تنها او مطمئناً خواهد آمد.

همهٔ چیزها به جز مرگ به نظر نامطمئن می‌رسند، به سرعت از دست می‌روند اگرچه سخت بدست می‌آیند، نامطمئن در نتیجه‌شان، و مستعد به شکست کشاندن امیدهایی که زمانی ایجاد کرده بودند و باقی گذاشتن طعم گرد و غبار در زمان برانگیخته شدن، به جای الهام و رؤیا. اما می‌توان روی مرگ حساب کرد. زیرا با گام‌هایی مطمئن زمانی که وقت رسیدنش فرا برسد، خواهد آمد. مرگ بدون شک همه زندگانی را به اسارت خودش خواهد برد.

آیا تو می‌خواهی به خدایان دروغینی همچون این تعظیم کنی؟ در اینجا قدرت و توان خود* خداوند* در خدای دروغینی که از غبار ساخته شد ادراک می‌شود. در اینجا خلاف آنچه خداوند* به عنوان ارباب همه آفرینش اعلام کرد پذیرفته می‌شود، چیزی قوی‌تر از ارادهٔ* خداوند* برای زندگی، بی‌پایان بودن عشق و کامل بودن بهشت*، تداوم بی‌تغییر. در اینجا اراده پدر* و فرزندش* نهایتاً شکست خورده قلمداد می‌شود، و در زیر سنگ قبری نهاده می‌شود که مرگ بر روی بدن فرزند* مقدس خداوند* می‌گذارد.

نامقدس و شکست خورده، و به آن چیزی تبدیل شده است که مرگ از او می‌خواهد. سنگ قبر او، که مرگ خود بر آن نوشته است، به او هیچ نامی نمی‌دهد، زیرا او به غبار تبدیل شده است. این نوشته فقط می‌گوید: «در اینجا گواهی بر مرگ خداوند* غنوده است.» و این را باز می‌نویسد و باز می‌نویسد، در حالی که هر زمان پرستندگان او با آن موافقت می‌کنند، و با پیشانی‌هایی که بر زمین می‌سایند پیش او تعظیم می‌کنند، در حالی که هراسان زمزمه می‌کنند که چنین است.

ناممکن است که بتوان مرگ را در هر شکلی پرستش کرد، و باز انتخاب کرد که بعضی از این شکل‌ها را گرامی نداشت و از آنها پرهیز کرد، در حالی که به بقیه باور داشت. زیرا مرگ عام است. یا همه چیز می‌میرد، یا اینکه زندگی می‌کند و نمی‌تواند بمیرد. هیچ سازشی ممکن نیست. زیرا در اینجا باز ما یک وضعیت آشکار را می‌بینیم، که باید بپذیریم اگر عاقل باشیم؛ آنچه کاملا با یک اندیشه مخالفت می‌ورزد نمی‌تواند حقیقی باشد، مگر اثبات شده باشد که متضاد آن نادرست است.

ایدهٔ مرگ خداوند* چنان مهمل است که حتی دیوانگان در باور کردن آن مشکل دارند. زیرا به این دلالت می‌کند که خداوند* زمانی زنده بوده است و به نحوی از بین رفته است؛ ظاهرا کشته شده، توسط آنان که نمی‌خواستند باقی بماند. ارادهٔ قوی‌تر آنان توانست بر ارادهٔ* او* پیروز شود، و این‌چنین حیات ابدی جای خود را به مرگ واگذار کرده. و همراه با پدر*، فرزندش* نیز مرد.

پرستندگان مرگ ممکن است هراسان باشند. و اما، آیا پندارهایی مانند این می‌توانند هراسناک باشند؟ اگر ایشان می‌دیدند که این تنها چیزی است که به آن باور دارند‌، فوراً آزاد می‌شدند. و امروز تو این را به آنان نشان خواهی داد. هیچ مرگی وجود ندارد، و ما اینک از آن به هر شکلی دست می‌کشیم، برای رستگاری آنان و نیز رستگاری خودمان. خداوند* مرگ را نساخت. هر شکلی که به خود بگیرد باید وهم باشد. این جایگاهی است که ما امروز در آن قرار می‌گیریم. و این جایگاه به ما داده شده است تا به ورای مرگ بنگریم، و زندگی را فراتر از آن ببینیم.

پدر* ما، امروز چشمانمان را تبرک کن. ما پیام‌آوران تو* هستیم، و می‌خواهیم به بازتاب باشکوه عشق* تو* که در همه چیز می‌تابد بنگریم. ما تنها در تو* زندگی و حرکت می‌کنیم. ما از زندگی جاوید تو جدا نیستیم. هیچ مرگی وجود ندارد، زیرا مرگ ارادهٔ* تو* نیست. ما در آنجا ساکن می‌شویم که تو* قرارمان داده‌ای، در آن حیات که با تو* و با همهٔ چیزهای زنده سهیم هستیم، تا مانند تو* باشیم و برای همیشه بخشی از تو* باشیم. ما اندیشه‌های* تو* را به عنوان اندیشه‌های خود می‌پذیریم، و ارادهٔ ما تا ابد با ارادهٔ* تو* یگانه است. آمین.', 'https://acim-farsi.org/workbook/lesson/163', 'https://acim-farsi.org/audio/workbook/lesson/163.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (164, 'اینک ما با او* که* سرچشمهٔ* ما است، یگانه هستیم.', 'اینک ما با او* که* سرچشمهٔ* ما است، یگانه هستیم.', 'اینک ما با او* که* سرچشمهٔ* ما است، یگانه هستیم.

چه زمانی به جز اکنون حقیقت می‌تواند شناخته شود؟ زمان حال تنها زمانی است که وجود دارد. و این‌چنین امروز، این لحظه، اکنون، ما به چیزی می‌نگریم که همیشه وجود دارد؛ نه در بینایی ما، بلکه در چشمان مسیحا*. او* به ورای زمان می‌نگرد، و ابدیت را می‌بیند چنان‌که در آنجا تجلی می‌کند. او* صداهایی را می‌شنود که این دنیای بی‌معنای شلوغ ایجاد می‌کند، اما او* این صداها را بسیار ضعیف می‌شنود. زیرا ورای همه این صداها، او* نغمهٔ بهشت* را می‌شنود، و آوای* برای خداوند* را با وضوح تمام، بامعناتر، نزدیک‌تر.

در برابر بینایی او* دنیا به آسانی محو می‌شود. صداهای آن مبهم می‌شوند. نغمه‌ای از بسیار فراتر از دنیا به طرز فزاینده‌ای وضوح بیشتر و بیشتری می‌یابد؛ فراخوانی دیرین که مسیحا* به آن یک پاسخ دیرین می‌دهد. تو هر دوی آن‌ها را خواهی شناخت، زیرا آن‌ها فقط پاسخ تو به فراخوان پدرت* هستند. مسیحا* برای تو پاسخ می‌گوید، در حالی که خویشتن* تو را پژواک می‌دهد، از آوای تو برای اعلام شادمانی رضایت خود استفاده می‌کند؛ در حالیکه رستگاری تو را برایت می‌پذیرد.

تمرین امروز تو چقدر مقدس است، در حالیکه مسیحا* بینایی خود* را به تو می‌دهد و برای تو می‌شنود، و به نام تو به فراخوانی* که می‌شنود پاسخ می‌گوید! چقدر زمانی که تو برای گذراندن با او* صرف می‌کنی ساکت است، فراتر از دنیا. چقدر ساده همه گناهان ظاهری تو فراموش می‌شوند، و همه غم‌های تو دیگر به یاد نمی‌آیند. امروز ماتم کنار گذاشته می‌شود، زیرا نماها و نواهایی که از نزدیک‌تر از دنیا می‌آیند برای تو واضح می‌شوند، تو که امروز موهبت‌هایی را که او* می‌دهد خواهی پذیرفت.

سکوتی وجود دارد که دنیا نمی‌تواند مزاحم آن شود. صلحی دیرین وجود دارد که تو در قلب خود حمل می‌کنی و گم نکرده‌ای. حسی از قداست در تو وجود دارد که پندار گناه هرگز آن را لمس نکرده است. امروز تو همه این را به یاد خواهی آورد. امروز تمرین وفادارانه پاداش‌هایی چنان عظیم و کاملا متفاوت با همه آنچه تو قبلا دیده‌ای خواهد داشت، که تو خواهی دانست که گنجت در اینجا است، و در اینجا آرام می‌گیری.

این روزی است که تصورات پوچ مانند پرده‌ای کنار می‌روند، تا آنچه را که ورایشان قرار دارد آشکار کنند. اینک آنچه واقعا وجود دارد قابل دیدن می‌شود، در حالیکه همه سایه‌هایی که ظاهرا آن‌ را پنهان می‌کردند دور می‌شوند. اینک تعادل برقرار می‌شود، و ترازوی عدالت به او* که* به درستی قضاوت می‌کند واگذار می‌گردد. و در قضاوت او* دنیایی در پیش چشمانت آشکار می‌شود در بی‌گناهی کامل. اینک تو آن را با چشمان مسیحا* خواهی دید. اینک دگرگونه شدن آن برای تو واضح می‌گردد.

برادر، این روز برای دنیا مقدس است. رؤیت تو، که از بسیار فراتر از همهٔ چیزها در دنیا به تو داده شده است، به این چیزها در نوری تازه می‌نگرد. و آنچه تو می‌بینی تبدیل به شفا و رستگاری دنیا می‌گردد. با ارزش و بی‌ارزش هر دو آنگونه که هستند درک و شناخته می‌شوند. و آنچه ارزش عشق تو را دارد، عشقت را دریافت می‌کند، در حالی که هیچ چیز ترسناکی باقی نمی‌ماند.

امروز ما قضاوت نخواهیم کرد. ما فقط آنچه را که از قضاوت انجام شدهٔ فراتر از این دنیا داده می‌شود، دریافت خواهیم کرد. امروز تمرینمان به هدیهٔ شکرگزاری ما برای رهایی از کوری و از فلاکت تبدیل می‌شود. همه آنچه را که می‌بینیم فقط سرور ما را افزون خواهد کرد، زیرا قداست آن قداست خود ما را بازتاب می‌دهد. ما در نگاه مسیحا* بخشوده شده می‌ایستیم، در حالی که همهٔ دنیا در نگاه خود ما بخشوده شده است. ما دنیا را تبرک می‌کنیم، در حالی که آن را در نوری می‌بینیم که در آن منجی* ما به ما می‌نگرد، و به دنیا آن آزادی را عرضه می‌کنیم که از طریق رؤیت بخشایشگر او* به ما داده شد، نه رؤیت خودمان.

پرده را در تمرین خود بگشا، صرفا با رها کردن همه چیزهایی که فکر می‌کنی می‌خواهی. گنجهای ناچیزت را کنار بگذار، و مکانی پاک و باز در ذهنت بگشای، تا مسیحا* بتواند بیاید، و به تو گنج رستگاری را عرضه کند. او* نیاز به مقدس‌ترین ذهنت دارد تا دنیا را نجات دهد. آیا این هدف آن‌قدر ارزشمند نیست تا هدف تو باشد؟ آیا رؤیت مسیحایی* آنقدر ارزشمند نیست که بالاتر از اهداف دنیا که رضایت‌بخش نیستند، طلبیده شود؟

نگذار امروز بدون موهبت‌هایی که برای تو دارد تا آن‌ها را با رضایت و پذیرش خود دریافت کنی، سپری شود. ما می‌توانیم دنیا را تغییر دهیم، اگر این موهبت‌ها را تصدیق کنی. تو ممکن است ارزشی را که پذیرش تو به دنیا می‌دهد، نبینی. اما این را حتما می‌خواهی؛ تو می‌توانی همین امروز همهٔ رنج را با سرور جایگزین کنی. مشتاقانه تمرین کن، و موهبت از آن تو است. آیا خداوند* می‌خواهد فریبت دهد؟ آیا وعدهٔ او* می‌تواند شکست بخورد؟ آیا تو می‌توانی این اندک را دریغ کنی، زمانی که دست او* رستگاری کامل را به فرزندش* عطا می‌کند؟', 'https://acim-farsi.org/workbook/lesson/164', 'https://acim-farsi.org/audio/workbook/lesson/164.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (165, 'بگذار ذهن من اندیشهٔ* خداوند* را انکار نکند.', 'بگذار ذهن من اندیشهٔ* خداوند* را انکار نکند.', 'بگذار ذهن من اندیشهٔ* خداوند* را انکار نکند.

چه چیزی موجب می‌شود که این دنیا واقعی به نظر برسد به جز انکار خود تو از حقیقتی که ورای دنیا قرار دارد؟ چه چیز به جز پندارهای تو از فلاکت و مرگ شادمانی کامل و زندگی جاوید را که پدرت* برایت اراده می‌کند، پنهان می‌نماید؟ و چه چیزی می‌تواند آنچه را که نمی‌توان پنهان کرد را پنهان کند به جز وهم؟ چه چیزی می‌تواند تو را از آنچه که هم اکنون داری دور کند به جز انتخاب تو در ندیدن آن، انکار تو از اینکه آن وجود دارد؟

اندیشهٔ* خداوند* تو را آفرید. آن تو را ترک نکرد، و تو هرگز حتی لحظه‌ای از آن جدا نبوده‌ای. به تو تعلق دارد. تو با آن زندگی می‌کنی. و سرچشمهٔ* حیات تو است، و تو را با آن یگانه می‌دارد، و همه چیز با تو یگانه است زیرا ترکت نکرده است. اندیشهٔ* خداوند* تو را محافظت می‌کند، از تو مواظبت می‌کند، مکان استراحتت را نرم می‌سازد و مسیرت را هموار می‌سازد، ذهنت را با شادمانی و عشق روشن می‌سازد. ابدیت و حیات جاوید در ذهنت می‌درخشند، زیرا اندیشهٔ* خداوند* ترکت نکرده است، و هنوز با تو ساکن است.

چه کسی می‌خواهد امنیت خود و صلح خود، شادمانی خود، شفای خود و صلح ذهن خود، استراحت آرام خود، بیداری خود را در آرامش نادیده بگیرد، اگر فقط تشخیص دهد که همهٔ اینها در کجا ساکن هستند؟ آیا بی‌درنگ خود را آماده نمی‌کند به جایی برود که می‌توان اینها را یافت، همه چیزهای دیگر را درمقایسه با اینها بی‌ارزش نخواهد شمرد؟ و زمانی که آن‌ها را بیابد، آیا مطمئن نخواهد شد که با او می‌مانند، و او با آن‌ها می‌ماند؟

بهشت را انکار نکن. امروز از آن تو است، اما اگر بخواهی. نیازی نداری که درک کنی این هدیه چقدر عظیم است، چقدر ذهنت پیش از اینکه دریافتش کنی تغییر خواهد کرد. بخواه که دریافت کنی، و به تو داده می‌شود. یقین در آن نهفته است. و تا زمانی که از آن به عنوان صاحبش استقبال نکنی، بی‌اطمینانی باقی می‌ماند. اما خداوند* مهربان است. برای دریافت کردن چیزی‌ که فقط پذیرش تو می‌تواند هدیه دهد، اطمینان ضروری نیست.

با میل بخواه. نیازی نیست مطمئن باشی که در حال خواستن تنها چیزی هستی که می‌خواهی. اما زمانی که دریافت کرده باشی، مطمئن خواهی شد گنجی را که همیشه در جستجویش بوده‌ای به تو ارزانی شده است. آنگاه چه چیز را با آن جایگزین می‌کنی؟ چه چیزی می‌تواند تو را اینک وادارد که به آن اجازه دهی از نگاه پرنشاط تو محو شود؟ زیرا این نگاه ثابت می‌کند که تو کوری خود را با چشمان بینای مسیحا* جایگزین کرده‌ای؛ ذهن تو انکار را کنار گذاشته است، و اندیشهٔ* خداوند* را به عنوان میراثت پذیرفته است.

اینک همه تردیدها پشت سر گذاشته می‌شود، پایان سفر قطعی شده و رستگاری به تو ارزانی می‌شود. اینک قدرت مسیحا* در ذهن تو است، تا آنگونه که شفا یافتی شفا دهی. زیرا اینک تو در میان منجیان دنیا هستی. سرنوشت تو در آنجاست و نه در هیچ جای دیگر. آیا خداوند* رضایت می‌دهد که اجازه دهد فرزندش* یرای همیشه با انکار کردن تغذیه‌ای که برای حیات به آن نیاز دارد، در قحطی بماند؟ فراوانی در او ساکن است، و محرومیت نمی‌تواند فرزندش* را از عشق* جاری خداوند* و از منزل او جدا سازد.

امروز با امید تمرین کن. زیرا امید حقیقتا موجه است. تردیدهای تو بی‌معنا هستند، زیرا خداوند* مطئمن است. و اندیشهٔ* او* هرگز غایب نیست. اطمینان باید در تو ساکن شود که میزبان او* هستی. این دوره همه تردید‌هایی را که تو میان او* و اطمینانت از او* قرار داده‌ای، برطرف می‌سازد.

ما به خداوند* اعتماد می‌کنیم، و نه به خودمان، که به ما اطمینان بخشد. و به نام او* ما چنان تمرین می‌کنیم که کلامش* هدایتمان می‌کند. اطمینان او* ورای هر تردید ما قرار دارد. عشق* او* ورای همه ترس‌های ما باقی می‌ماند. اندیشهٔ* او* همواره فراتر از همهٔ رؤیاها و در ذهن‌های ما حضور دارد، بر طبق اراده‌اش*.', 'https://acim-farsi.org/workbook/lesson/165', 'https://acim-farsi.org/audio/workbook/lesson/165.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (166, 'من امانت‌دار هدایای خداوند* هستم.', 'من امانت‌دار هدایای خداوند* هستم.', 'من امانت‌دار هدایای خداوند* هستم.

همه چیز به تو داده شده است. اعتماد خداوند* به تو بی‌حد است. او* فرزندش* را می‌شناسد. او* بدون استثناء عطا می‌کند، و از هیچ چیزی که می‌تواند به شادمانی تو کمک کند فروگذار نمی‌نماید. و اما، مادامی که ارادهٔ تو با ارادهٔ* او* یگانه نشده باشد، هدایای او* دریافت نمی‌شوند. اما چه چیزی می‌تواند موجب شود که تو بپنداری اراده‌ای جز ارادهٔ* او* وجود دارد؟

در اینجا تناقصی وجود دارد که زمینه‌ساز ساخته شدن این دنیا است. این دنیا ارادهٔ* خداوند* نیست، پس واقعی نیست. اما آنان که آن را واقعی می‌پندارند باید باور داشته باشند که اراده دیگری وجود دارد، و اراده‌ای که منجر به تاثیرات متضادی با ارادهٔ* او* می‌گردد. حقیقتا ناممکن است؛ اما هر ذهنی که به دنیا می‌نگرد و آن را قطعی، جامد، قابل اعتماد و حقیقی قلمداد می‌کند، به دو آفریدگار باور دارد؛ یا فقط به یکی، خودش به تنهایی. اما هرگز به یک خداوند* باور ندارد.

هدایای خداوند* برای هر کسی که چنین باورهای عجیبی را نگه می‌دارد، قابل پذیرش نیستند. او باید باورداشته باشد که پذیرفتن هدایای خداوند*، هر چقدر واضح شوند، هرچقدر او به فوریت فراخوانده شود تا آن‌ها را از آن خود بخواند، خیانت به خودش محسوب می‌شود. او باید وجود آن‌ها را انکار کرده باشد، با حقیقت مخالف باشد، و برای حفظ کردن دنیایی که ساخته است رنج ببرد.

در اینجا تنها خانه‌ای که او می‌پندارد که می‌شناسد، قرار دارد. در اینجا تنها امنیتی که او به یافتن آن باور دارد، نهفته است. بدون دنیایی که ساخته است، او یک رانده شدهٔ بی‌خانمان و هراسان است. او تشخیص نمی‌دهد که حقیقتا اینجا است که در آن می‌ترسد، بی‌خانمان است؛ رانده شده‌ای سرگردان و چنان دور از خانه، چنان در فاصلهٔ دور، که تشخیص نمی‌دهد آنجا را که از آن آمده است فراموش کرده است، آنجا را که می‌رود، و حتی اینکه واقعا کیست.

اما در سرگردانی تنها و بی‌معنای او، هدایای خداوند* با او می‌آیند، در حالی که همهٔ آن‌ها برایش ناشناخته هستند. او نمی‌تواند آن‌ها را گم کند. اما به آنچه به او ارزانی شده است نگاه نخواهد کرد. او سرگردانی می‌کشد، آگاه از پوچی آنچه در همه جا پیرامونش می‌بیند، در حالی که درک می‌کند سهم کوچکش چقدر ناچیز است، در حالی که روانه ناکجا‌آباد است. اما باز در فلاکت و فقر و سرگردانی‌اش ادامه می‌دهد، تنها، گرچه خداوند* با او است، و گنج او آنچنان عظیم است که همه چیزهایی که دنیا در خود دارد، در برابر عظمت آن بی‌ارزش هستند.

به نظر می‌رسد که او یک وجود اندوهگین است؛ نگران، فرسوده، در لباس نخ‌نما، و با پاهایی که از مسیر سنگلاخی که می‌پیماید، خون‌چکان هستند. اما هیچ‌کس نیست جز اینکه خودش را با او یکی می‌داند، زیرا هر کسی که به اینجا می‌آید مسیر او را دنبال می‌کند، و ناکامی و ناامیدی را که او احساس می‌کند، احساس کرده است. اما آیا او واقعا رقت‌انگیز است، زمانی که می‌بینی که در حال دنبال کردن مسیری است که انتخاب کرده، و فقط نیاز دارد تشخیص دهد که چه کسی* با او گام برمی‌دارد و گنج‌هایش را بگشاید تا آزاد شود؟

این خودی است که تو انتخاب کرده‌ای، چیزی که تو ساختی تا جایگزین واقعیت باشد. این همان خودی است که تو با خشونت از آن در برابر همهٔ عقلانیت دفاع می‌کنی، همه شواهد، و همه گواهانی که قاطعانه نشان می‌دهند این تو نیستی. تو به آن‌ها توجه نمی‌کنی. تو در مسیر تعیین شده خود می‌روی، با چشمانی به زیر افکنده مبادا بتوانی نظری به حقیقت بیفکنی، و از خود‌فریبی رها شوی و آزاد گردی.

تو هراسان خم می‌شوی مبادا بتوانی لمس مسیحا* را بر شانه خود احساس کنی، و دست مهربانش را که تو را به سمت نظر انداختن به هدایایت هدایت می‌کند، درک کنی. آنگاه چگونه می‌توانستی اعلام کنی که در تبعید و فقر هستی؟ او* موجب خواهد شد که تو به این درک از خودت بخندی. در آن صورت ناراحتی برای خود کجاست؟ و بر سر همهٔ این فاجعه که تو خواستی برای او بسازی، که خداوند* برایش تنها شادمانی را مقرر کرد، چه می‌آید؟

اینک ترس دیرین تو به سمتت آمده است، و عدالت سرانجام به سراغت می‌آید. دست مسیحا* شانه تو را لمس کرده است، و احساس می‌کنی که تنها نیستی. تو حتی می‌اندیشی که آن خود بدبختی که می‌پنداشتی تو است، می‌تواند هویت تو نباشد. شاید کلام* خداوند* حقیقی‌تر از کلام خود تو باشد. شاید هدایای او* به تو واقعی باشند. شاید او* کاملا توسط نقشه تو کنار گذاشته نشده باشد، نقشه‌ای که می‌خواهد فرزند* او* را در فراموشی عمیق نگه دارد، تا او به راهی برود که تو بدون خویشتن* خود انتخاب کرده‌ای.

ارادهٔ* خداوند* مخالفی ندارد. صرفا هست. تو خداوند* را در نقشه خود زندانی نکرده‌ای تا خویشتنت* را گم کنی. او* چیزی در مورد نقشه‌ای که چنین با اراده‌اش* بیگانه است، نمی‌داند. نیازی وجود داشت که او* درک نکرد، و پاسخی* به آن داد. فقط همین. و تو که این پاسخ* ارزانی‌ات شده است، نیاز به هیچ چیز دیگری به جز این نداری.

اینک ما زندگی می‌کنیم، زیرا اینک نمی‌توانیم بمیریم. به آرزوی مرگ پاسخ داده شده است، و نگاهی که به آن نظر می‌کرد، اینک با رؤیتی جایگزین شده است که درک می‌کند تو آنچه تظاهر می‌کنی هستی، نیستی. یگانه‌ای* با تو گام بر می‌دارد که با مهربانی به همه ترس‌های تو فقط با این سخن رحمت‌آمیز پاسخ می‌گوید، «چنین نیست.» او* به همهٔ هدایایی اشاره می‌کند که تو هر زمان که پندار فقر به تنگنایت می‌اندازد، داری، و از همراهی‌اش با تو سخن می‌گوید زمانی که خودت را تنها و هراسان درک می‌کنی.

اما او* همچنین یک چیز دیگر را که فراموش کرده‌ای به یادت می‌آورد. زیرا لمس او* تو را مانند خودش* کرده است. هدایایی که تو داری تنها برای تو نیستند. آنچه او* به تو ارزانی می‌دارد، اینک باید بیاموزی که بدهی. این درسی است که در دادن او* نهفته است، زیرا او* تو را از آن تنهایی که خواستی بسازی تا در آن از خداوند* پنهان شوی نجات داده است. او* همه هدایایی را که خداوند* به تو داده است، به یادت آورده است. او* همچنین از آنچه به ارادهٔ تو تبدیل می‌شود زمانی که این هدایا را می‌پذیری و آن‌ها را از آن خودت می‌شناسی، سخن می‌گوید.

این هدایا از آن تو هستند، به امانت سپرده برای مراقبت تو، تا به همهٔ آنان که راه تنهایی را انتخاب کرده‌اند که تو از آن فرار کرده‌ای، عرضه کنی. آنان درک نمی‌کنند که فقط آرزوهایشان را دنبال می‌کنند. این تو هستی که اینک به آنان تعلیم می‌دهی. زیرا تو از مسیحا* آموخته‌ای که راه دیگری برای پیمودن برای آنان وجود دارد. به آنان تعلیم بده با نشان دادن آن شادمانی که به سوی آنان که لمس مسیحا* را احساس می‌کنند و هدایای خداوند* را می‌شناسند، عطا می‌شود. نگذار اندوه تو را وسوسه کند تا در اطمینان خود بی‌ایمان باشی.

آه‌های تو اینک امید آنان را که برای رهایی خود به تو می‌نگرند ویران خواهد کرد. اشک‌های تو متعلق به آن‌ها است. اگر تو بیمار باشی، تو فقط در حال دریغ کردن شفای آن‌ها هستی. آنچه تو از آن می‌ترسی فقط به آن‌ها می‌آموزد که ترس‌هایشان موجه هستند. دست تو دهندهٔ لمس مسیحا* می‌شود؛ تغییر ذهن تو گواه این می‌شود که آن‌کس که هدایای خداوند* را می‌پذیرد هرگز و از هیچ چیزی نمی‌تواند رنج ببرد. رها شدن دنیا از درد به تو سپرده شده است.

به آن خیانت نکن. به گواه زنده این تبدیل شو که لمس مسیحا* چه چیزی را می‌تواند به همگان ارزانی کند. خداوند* همه هدایایش را به تو سپرده است. شاهد شادمانی خود باش که چقدر ذهنی که انتخاب می‌کند هدایای او* را بپذیرد و لمس مسیحا* را احساس کند، متحول می‌شود. اینک ماموریت تو این است. زیرا خداوند*، دادن هدایای خود* را به همه آنان که آن‌ها را دریافت کرده‌اند، می‌سپارد. او* سرورش را با تو سهیم می‌شود. و اینک تو می‌روی تا آن را با دنیا سهیم شوی.', 'https://acim-farsi.org/workbook/lesson/166', 'https://acim-farsi.org/audio/workbook/lesson/166.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (167, 'یک زندگی وجود دارد و من آن را با خداوند* سهیم می‌شوم.', 'یک زندگی وجود دارد و من آن را با خداوند* سهیم می‌شوم.', 'یک زندگی وجود دارد و من آن را با خداوند* سهیم می‌شوم.

انواع مختلف زندگی وجود ندارند، زیرا زندگی مانند حقیقت است. زندگی درجاتی ندارد. این یک شرایط واحد است که در آن همهٔ آفریده‌های خداوند* سهیم هستند. مانند همهٔ اندیشه‌های او*، هیچ متضادی ندارد. هیچ مرگی وجود ندارد زیرا آنچه خداوند* آفرید در زندگی او* سهیم است. هیچ مرگی وجود ندارد زیرا متضادی برای خداوند* وجود ندارد. هیچ مرگی وجود ندارد زیرا پدر* و فرزند* یگانه هستند.

دراین دنیا به نظر می‌رسد حالتی وجود دارد که متضاد زندگی است. تو آن را مرگ می‌خوانی. اما ما آموخته‌ایم که ایدهٔ مرگ شکل‌های مختلف می‌گیرد. همین یک ایده است که زمینه‌ساز همهٔ احساساتی است که بطور کامل شاد نیستند. این زنگ خطری است که تو به آن پاسخ از هر نوعی می‌دهی که سرور کامل نیست. همه تاسف‌ها، فقدان‌ها، اضطراب‌ها و رنج‌ها و دردها، حتی آه کوچکی از سر بیزاری، کوچکترین ناخرسندی یا کمترین اخم، مرگ را تایید می‌کنند. و اینچنین، زندگی تو را نادیده می‌گیرند.

تو می‌اندیشی که مرگ مربوط به بدن است. اما مرگ فقط یک ایده است، نامربوط به آنچه به عنوان وجود جسمانی دیده می‌شود. یک پندار در ذهن مستقر است. پس این پندار می‌تواند به نحوی استفاده شود که ذهن به آن جهت می‌دهد. اما سرچشمهٔ آن جایی است که باید از آنجا تغییر کند، اگر تغییری اتفاق بیفتد. ایده‌ها سرچشمهٔ خودرا ترک نمی‌کنند. این دوره تاکید خود را بر آن ایده گذاشته است که به دلیل محوری بودن خود در تلاش ما برای تغییر دادن ذهنت درباره خودت، مهم است. به همین دلیل است که تو می‌توانی شفا دهی. همین، علت شفا یافتن است. به همین دلیل تو نمی‌توانی بمیری. حقیقتِ همین ایده است که یگانگی تو را با خداوند اثبات می‌کند.

مرگ این پندار است که تو از آفریدگار* خود جدا هستی. این باور است که شرایط تغییر می‌کنند، احساسات بنابر عللی تغییر می‌کنند که تو نمی‌توانی آن‌ها را کنترل کنی، تو آن‌ها را نساخته‌ای، و تو هرگز نمی‌توانی تغییرشان دهی. این باورِ ثابت است که ایده‌ها می‌توانند سرچشمهٔ خود را ترک کنند، و کیفیت‌هایی را داشته باشند که سرچشمه حاوی آنها نیست، با منشاء خود متفاوت شوند، از آن در نوع و همچنین فاصله، زمان و شکل جدا شوند.

مرگ نمی‌تواند از زندگی پدید آید. ایده‌ها یگانه با سرچشمه خود باقی می‌مانند. آنها می‌توانند به همه چیز که سرچشمه آن‌ها در خود دارد، گسترش یابند. از این رو، آنها می‌توانند بسیار فراتر از خودشان بروند. اما نمی‌توانند زاینده چیزی شوند که هرگز به آن‌ها داده نشده بود. آنگونه که ساخته شده‌اند، همانگونه خواهند ساخت. همانگونه که زاده شدند، پس همانگونه می‌زایند. و از هر جا آمده‌اند، به همان‌جا برخواهند گشت.

ذهن می‌تواند بپندارد که می‌خوابد، اما این فقط یک پندار است. ذهن نمی‌تواند آنچه را که حالت بیداری آن است تغییر دهد. ذهن نمی‌تواند یک بدن بسازد، یا در یک بدن ساکن شود. آنچه برای ذهن بیگانه است وجود ندارد، زیرا سرچشمه‌ای ندارد. زیرا ذهن همه چیزهایی را می‌آفریند که هستند، و نمی‌تواند صفاتی را به آنها بدهد که فاقد آنهاست، و نمی‌تواند حالت ابدی هوشمند خود را تغییر دهد. ذهن نمی‌تواند دنیای جسمانی را بسازد. آنچه که به نظر می‌رسد می‌میرد، فقط نشانهٔ خفته بودن ذهن است.

متضاد زندگی فقط می‌تواند شکل دیگری از زندگی باشد. اینچنین، می‌تواند با آنچه آن را آفریده است آشتی کند، زیرا در حقیقت با آن متضاد نیست. شکل آن ممکن است تغییر کند. ممکن است به نظر برسد که چیزی هست که نیست. اما ذهن، ذهن است، بیدار یا خفته. در هیچ چیزی که آفریده شده است متضاد آن نیست، و نه در چیزی که به نظر می‌رسد می‌سازد زمانی که باور می‌کند خفته است.

خداوند* فقط ذهن را بیدار آفرید. او* نمی‌خوابد، و آفریده‌هایش نمی‌توانند درچیزی سهیم شوند که او* عطا نکرده باشد، یا نمی‌توانند شرایطی را بسازند که او* با آنان سهیم نشده باشد. پندار مرگ، متضاد پندارهای زندگی نیست. برای همیشه بدون مخالفت توسط هیچ متضادی از هیچ نوع، اندیشه‌های* خداوند* همواره بی‌تغییر می‌مانند، با این قدرت که برای همیشه بی‌تغییر گسترش یابند، اما فقط درون خودشان، زیرا در همه جا هستند.

آنچه به نظر می‌رسد متضاد زندگی باشد، صرفا خفتن است. زمانی که ذهن انتخاب می‌کند چیزی باشد که نیست، و فرض می‌کند یک قدرت بیگانه هست که او فاقد آن است، یک حالت بیگانه هست که نمی‌تواند به آن وارد شود، یا یک شرایط نادرست هست که در سرچشمهٔ آن نیست، صرفا به نظر می‌رسد برای مدتی به خواب رفته است. ذهن در مورد زمان رؤیا می‌بیند؛ فاصله‌ای که در آن هر چه به نظر می‌رسد رخ می‌دهد، هرگز رخ نداده است، تغییراتی که دیده می‌شوند بی‌معنا هستند، و همه رویدادها نابجا هستند. زمانی که ذهن بیدار می‌شود، فقط آنگونه که همیشه بوده است ادامه می‌دهد.

بگذارید امروز فرزندان حقیقت باشیم، و میراث مقدس خود را انکار نکنیم. زندگی ما آنگونه نیست که آن را تصور می‌کنیم. چه کسی زندگیش را تغییر می‌دهد زیرا چشمانش را می‌بندد، یا خود را به چیزی تبدیل می‌کند که نیست زیرا می‌خوابد، و در رؤیاهایش متضاد آنچه را که هست می‌بینید؟ امروز مرگ را در هیچ شکلی نخواهیم خواست. همچنینن اجازه نخواهیم داد متضادهای خیالی برای زندگی حتی یک لحظه در جایی که اندیشهٔ* مقدس حیات جاوید توسط خود* خداوند* نهاده شده است، ساکن شوند.

خانهٔ مقدس او است که ما امروز تلاش می‌کنیم آنگونه که او* مقرر کرد حفظ کنیم، آنگونه که او* اراده می‌کند برای همیشه و همیشه باشد. او* خداوندگار* آن چیزی است که ما امروز می‌اندیشیم. و در اندیشه‌های* او* که هیچ متضادی ندارند، ما درک می‌کنیم که یک زندگی وجود دارد، زندگی‌ای که ما با او* سهیم هستیم، با همهٔ آفرینش، همچنین با اندیشه‌های آنان، آنان که او* در وحدتِ زندگی آفرید و نمی‌نوانند در مرگ جدا شوند و سرچشمهٔ زندگی را که از آن آمده‌اند ترک کنند.

ما یک زندگی را با هم سهیم هستیم زیرا یک سرچشمه داریم، سرچشمه‌ای که از آن کمال به سمتمان می‌آید، سرچشمه‌ای که همیشه در ذهن‌های مقدسی که او* بی‌نقص آفرید، باقی می‌ماند. آنگونه که بودیم، اینک نیز همانگونه هستیم و همواره خواهیم بود. ذهن خفته باید بیدار شود، همانگونه که کمال خود را آیینهٔ خداوندگار* زندگی می‌بیند، چنان کامل که در آنچه که در آن بازتاب یافته محو می‌شود. و اکنون این دیگر صرفا یک بازتاب نیست. به چیزی تبدیل می‌شود که بازتاب می‌یابد، و به نوری تبدیل می‌شود که بازتاب را ممکن می‌سازد. اینک هیچ رؤیتی لازم نیست. زیرا ذهنِ بیدار شده، ذهنی است که سرچشمه‌اش* را می‌شناسد، خویشتنش* را و قداستش* را.', 'https://acim-farsi.org/workbook/lesson/167', 'https://acim-farsi.org/audio/workbook/lesson/167.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (168, 'فیض تو به من ارزانی شده است. اینک من آن را می‌طلبم.', 'فیض تو* به من ارزانی شده است. من اینک آن را می‌طلبم. پدر*، من به سمت تو می‌آیم.
پدر*، من به سمت تو می‌آیم. و تو* به سمت من خواهی آمد که می‌طلبم.
من آن فرزند* هستم که تو* به او عشق می‌ورزی.', 'فیض تو به من ارزانی شده است. اینک من آن را می‌طلبم.

خداوند* با ما سخن می‌گوید. آیا ما نباید با او* سخن بگوییم؟ او* دور نیست. او* هیچ تلاشی نمی‌کند که از ما پنهان شود. ما سعی می‌کنیم از او* پنهان شویم، و از فریب رنج ببریم. او* کاملا قابل دسترسی باقی می‌ماند. او* به فرزندش* عشق می‌ورزد. هیچ چیز قابل اطمینانی به جز این وجود ندارد، اما همین کفایت می‌کند. او* همیشه به فرزندش* عشق خواهد ورزید. او* زمانی که ذهن فرزندش* خفته می‌ماند، همچنان به او عشق می‌ورزد. و زمانی که ذهن فرزندش* بیدار می‌شود، با عشق بی‌تغییر همیشگی به او عشق می‌ورزد.

اگر فقط معنای عشق* او* را می‌دانستی، امید و ناامیدی ناممکن می‌شد. زیرا امید برای همیشه برآورده می‌شد؛ و دیگر نمی‌شد به ناامیدی اندیشید. فیض او* پاسخش* به همه ناامیدی است، زیرا در فیضش یادآوری عشقش* نهفته است. آیا او* شادمانه وسیله‌ای را عطا نمی‌کند که با آن بتوان اراده‌اش* را شناخت؟ فیض او* با تصدیق تو، از آن تو می‌شود. و خاطرهٔ* او* در ذهنی بیدار می‌شود که ابزار پایان یافتن خواب خود را از او* می‌طلبد.

امروز ما از خداوند* موهبتی را می‌خواهیم که با دقت تمام در قلب‌های ما حفظ کرده است، در انتظار شناخته شدن. این موهبتی است که توسط آن خداوند* به سمت ما خم می‌شود و ما را بالا می‌کشد، و گام نهایی به سمت رستگاری را خودش* بر می‌دارد. همه گام‌ها به جز این را می‌آموزیم، در حالی که توسط آوای* او* هدایت می‌شویم. اما در نهایت او* خودش* می‌آید، و ما را در بازوانش می‌گیرد و تار عنکبوت خواب ما را می‌زداید. موهبت فیض او* بیش از یک پاسخ صرف است. این موهبت همه خاطراتی را که ذهن خفته فراموش کرده است زنده می‌کند؛ همه اطمینانی را که معنای عشق است.

خداوند* به فرزندش* عشق می‌ورزد. اینک از او* بخواه وسیله‌ای را به تو ارزانی دارد که توسط آن، این دنیا ناپدید خواهد شد، و ابتدا رؤیت خواهد آمد، و تنها لحظه‌ای بعد معرفت می‌آید. زیرا در فیض، تو نوری را می‌بینی که همه دنیا را در عشق می‌پوشاند و مشاهده می‌کنی که ترس از همه چهره‌ها ناپدید می‌شود، زمانی که قلب‌ها بر می‌خیزند و نور را برای خود طلب می‌کنند. چه چیز باقی می‌ماند که بتواند بهشت* را برای لحظه‌ای دیگر به تاخیر بیاندازد؟ چه کاری ناتمام می‌ماند زمانی که بخشایش تو بر همه چیز جاری شود؟

امروز یک روز تازه و مقدس است، زیرا ما آنچه به ما عطا شده است را دریافت می‌کنیم. ما به دهندهٔ* فیض ایمان داریم، نه به پذیرش خودمان. ما خطاهای خودمان را تصدیق می‌کنیم، اما او* که برایش همه خطاها ناشناخته هستند، اوست یگانه‌ای* که به خطاهای ما با دادن وسیله‌ای برای کنار گذاشتن آنها پاسخ می‌دهد، و برخاستن به پایش در سپاس و عشق.

و او* فرود می‌آید تا ما را ملاقات کند، همچنان که ما به سمتش می‌آییم. زیرا او* آنچه را که برای ما آماده کرده است ارزانی می‌کند و ما دریافت می‌کنیم. ارادهٔ* او* چنین است. زیرا او* به فرزندش* عشق می‌ورزد. امروز او* را دعا می‌کنیم، و فقط کلامی را به او* باز می‌گردانیم که از طریق آوای* خودش* به ما داد، کلام* او*، عشق* او*: فیض تو* به من ارزانی شده است. من اینک آن را می‌طلبم. پدر*، من به سمت تو می‌آیم. و تو* به سمت من خواهی آمد که می‌طلبم. من آن فرزند* هستم که تو* به او عشق می‌ورزی.', 'https://acim-farsi.org/workbook/lesson/168', 'https://acim-farsi.org/audio/workbook/lesson/168.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (169, 'من توسط فیض زندگی می‌کنم. من توسط فیض رهایی می‌یابم.', 'من توسط فیض زندگی می‌کنم. من توسط فیض رهایی می‌یابم.
من توسط فیض می‌دهم. من توسط فیض رهایی خواهم بخشید.', 'من توسط فیض زندگی می‌کنم. من توسط فیض رهایی می‌یابم.

فیض جنبه‌ای از عشق* خداوند* است که بیشترین شباهت را به حالت حاکم در یگانه بودن حقیقت دارد. فیض، رفیع‌ترین الهام دنیا است، زیرا تماماً به ورای دنیا هدایت می‌کند. فیض فراتر از آموختن است، اما هدف آن است، زیرا فیضی نمی‌تواند بیاید مادامی که ذهن خودش را برای پذیرش حقیقی آماده نکرده باشد. برای آنان که میزی را آماده کرده باشند تا فیض بتواند به آرامی بر آن قرار گیرد و اراده‌مندانه دریافت شود، فیض ناگزیر است؛ محرابی پاک و مقدس برای این موهبت.

فیض پذیرش عشق* خداوند* است در دنیایی از نفرت و ترس ظاهری. فقط توسط فیض، نفرت و ترس رانده می‌شوند، زیرا فیض حالتی چنان متضاد با هر چیزی که دنیا در خود دارد ارائه می‌کند، چنانکه آنان که ذهن‌هایشان توسط موهبت فیض نورانی می‌شوند نمی‌توانند باور کنند که دنیای ترس واقعی است.

فیض آموخته نمی‌شود. گام نهایی باید فراتر از همه آموخته‌ها برود. فیض آن هدف نیست که این دوره الهام‌بخش رسیدن به آن باشد. اما ما برای فیض آماده می‌شویم زیرا یک ذهن باز می‌تواند فراخوان بیداری را بشنود. یک ذهن باز در مقابل آوای* خداوند* خود را بسته و محکم نگه نمی‌دارد. یک ذهن باز آگاه می‌شود از اینکه چیزهایی هست که نمی‌داند، و این‌چنین برای پذیرش حالتی کاملا متفاوت با تجربه‌ای که در خانه با آن آشنا است، آماده می‌شود.

شاید به نظر می‌رسد ما در تضاد با این بیان خود هستیم که مکاشفهٔ یگانه* بودن پدر* و فرزند* پیشاپیش مقرر شده است. اما ما همچنین گفته‌ایم که ذهن زمان آن‌ را تعیین می‌کند، و این زمان را تعیین کرده است. با این حال ما تو را به پیش می‌رانیم تا بر کلام* خداوند* گواهی دهی تا تجربه حقیقت را تسریع کنی، و ظهور آن را در همهٔ ذهن‌هایی که تاثیرات حقیقت بر تو را تشخیص می‌دهند سرعت بخشی.

یگانگی به سادگی ایدهٔ وجود خداوند* است. و او* در وجودش، همهٔ چیزها را در بر می‌گیرد. هیچ ذهنی چیزی به جز او* را نگه نمی‌دارد. ما می‌گوییم «خداوند هست» و سپس از سخن باز می‌ایستیم، زیرا در این معرفت کلمات بی‌معنا هستند. هیچ لبی برای سخن گفتن از آنها وجود ندارد، و هیچ بخشی از ذهن نمی‌تواند به حد کافی متمایز از او* باشد که احساس کند توان آگاه شدن به چیزی غیر از او* را دارد. ذهن با سرچشمهٔ* خود یگانه شده است. و مانند خود* سرچشمه‌اش*، صرفا هست.

ما اصلا نمی‌توانیم از این بگوییم یا بنویسیم یا حتی به آن بیاندیشیم. این به هر ذهنی خطور می‌کند، زمانی که تشخیص کامل اینکه اراده‌اش از آن خداوند* است به طور کامل داده شده باشد و به طور کامل دریافت شده باشد. این تشخیص کامل، ذهن را به زمان حال بی‌پایان باز می‌گرداند، جایی که گذشته و آینده قابل ادراک نیستند. این فراتر از رستگاری قرار دارد؛ فراتر از همهٔ پندار زمان، بخشایش و چهره مقدس مسیحا*. فرزند* خداوند* صرفا در پدرش* ناپدید شده است، همانگونه که پدرش* در او محو شده است. دنیا اصلا هرگز نبوده است. ابدیت حالتی پایدار باقی می‌ماند.

این فراتر از تجربه‌ای است که ما سعی در تسریع آن داریم. اما بخشایش، در صورتی که تعلیم داده شده و آموخته شود، با خود تجربیاتی را می‌آورد که گواهی می‌دهند آن زمانی که خود ذهن برای رها کردن همه چیز جز این تعیین کرده است، اینک در دسترس است. ما آن را تسریع نمی‌کنیم، زیرا آنچه تو عرضه خواهی کرد از او* که آموزگار* معنای بخشایش است پنهان نگه داشته شده بود.

همه آموخته‌ها پیشاپیش در ذهن* او* بوده است، به عمل رسیده و کامل. او* همهٔ آنچه را که زمان نگه می‌دارد شناخت، و آن را به همهٔ ذهن‌هایی داد که هر یک بتواند از نقطه‌ای که زمان پایان یافت تعیین کند، چه زمانی در مکاشفه و ابدیت رها می‌شود. ما پیش‌تر این را چندین بار تکرار کرده‌ایم که تو فقط سفری را انجام می‌دهی که به انجام رسیده است.

زیرا یگانگی باید در اینجا باشد. هر زمانی که ذهن برای مکاشفه تعیین کرده باشد، کاملا با آنچه باید حالتی پایدار باشد بی‌ربط است، حالت پایدار همیشگی همانگونه که همواره بوده است؛ همیشگی همانگونه که اینک نیز هست. ما فقط نقشی را ایفا می‌کنیم که مدتها پیش تعیین شده است، و توسط او* کاملا تشخیص داده شده و تماما ایفا شده است، او* که تقریر رستگاری را به نام* آفریدگارش* نوشت، و به نام فرزند* آفریدگارش*.

نیازی نیست که آن چیزی را که هیچ‌کس در این دنیا نمی‌تواند درک کند، بیشتر واضح سازیم. زمانی که مکاشفه‌ی یگانگی تو پیش بیاید، این را خواهی دانست و کاملا درک خواهی کرد. اکنون ما کارهایی برای انجام داریم، زیرا آنان که در زمان هستند می‌توانند از چیزهایی فراتر سخن بگویند، و به کلماتی گوش کنند که توضیح می‌دهند آنچه قرار است پیش بیاید در واقع گذشته است. اما کلمات چه معنایی را می‌توانند برای کسانی در بر داشته باشند که هنوز ساعت‌ها را می‌شمرند، و با ساعت‌ها بیدار می‌شوند و کار می‌کنند و به خواب می‌روند؟

پس همین کفایت می‌کند که تو باید کارهایی انجام دهی تا نقشت را ایفا کنی. پایان باید بر تو پنهان بماند تا زمانی که نقشت ایفا شده باشد. این اهمیتی ندارد. زیرا نقش تو هنوز همان چیزی است که همه چیزهای دیگر به آن بستگی دارند. زمانی که تو نقشی را ایفا می‌کنی که برایت مقرر شده است، رستگاری به هر قلب نامطمئنی که هنوز در هماهنگی با خداوند* نمی‌تپد، کمی نزدیکتر می‌شود.

بخشایش موضوع محوری است که در سراسر رستگاری جریان دارد، و همه بخش‌های آن را در روابط بامعنا نگه می‌دارد، به مسیر آن جهت می‌دهد و نتیجه‌اش را قطعی می‌سازد. و اینک ما خواهان فیض می‌شویم، موهبت نهایی که رستگاری می‌تواند ارزانی دارد. تجربه‌ای که فیض با خود می‌آورد، در زمان پایان می‌یابد، زیرا فیض پیش‌درآمد بهشت* است، اما جز برای مدت کوتاهی جایگزین پندار زمان نمی‌شود.

همین فاصله زمانی کفایت می‌کند. در همین جا معجزات نهفته هستند؛ معجزاتی که باید توسط تو از آن لحظات مقدسی که دریافتشان می‌کنی بازگردانیده شوند، از طریق فیض در تجربهٔ تو، برای همهٔ آنان که تابش نور را در چهرهٔ تو می‌بینند. چهرهٔ مسیحا* چیست به جز چهرهٔ او که لحظه‌ای به درون بی‌زمانی رفت، و بازتابی روشن از وحدتی را که لحظه‌ای حس کرده بود، بازگرداند تا دنیا را متبرک کند؟ چگونه می‌توانستی نهایتا برای همیشه به آن دست یابی، در حالی که بخشی از تو در بیرون، ناآگاه، نابیدار، و نیازمند به تو به عنوان شاهد حقیقت باقی می‌ماند؟

سپاسگزار بازگشت باش، همانگونه که شادمان لحظه‌ای از رفتن بودی، و موهبت‌هایی را که فیض برایت فراهم کرده است بپذیر. تو آن‌ها را به خودت باز می‌آوری. و مکاشفه چندان دور نمی‌ایستد. رسیدن آن قطعی است. ما فیض را طلب می‌کنیم، و تجربه‌ای را که از فیض حاصل می‌شود. ما از رهای‌ای که فیض به همگان عرضه می‌کند استقبال می‌کنیم. ما چیزی را که نمی‌توان طلب کرد طلب نمی‌کنیم. ما به ورای آنچه فیض می‌تواند ارزانی کند، نمی‌نگریم. زیرا اینچنین تسلیم فیض می‌شویم که به ما عطا شده است.

هدف آموختن امروز ما از این دعا فراتر نمی‌رود. اما در این دنیا ، چه چیز می‌تواند بالاتر از آن چیزی باشد که ما امروز از او* که ارزانی کنندهٔ فیض است طلب می‌کنیم، همانگونه که فیض به او* عطا شد؟ من توسط فیض زندگی می‌کنم. من توسط فیض رهایی می‌یابم. من توسط فیض می‌دهم. من توسط فیض رهایی خواهم بخشید.', 'https://acim-farsi.org/workbook/lesson/169', 'https://acim-farsi.org/audio/workbook/lesson/169.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (170, 'هیچ بی‌رحمی در خداوند* وجود ندارد و در من نیز بی‌رحمی نیست.', 'هیچ بی‌رحمی در خداوند* وجود ندارد و در من نیز بی‌رحمی نیست.

تو آنچه را که در برابرش دفاع می‌کنی می‌سازی، و با دفاع خود تو در برابرش آن واقعی و گریز‌ناپذیر است.
تو آنچه را که در برابرش دفاع می‌کنی می‌سازی، و با دفاع خود تو در برابرش آن واقعی و گریز‌ناپذیر است. سلاح‌هایت را زمین بگذار، و تنها آنگاه آن را غیرحقیقی ادراک خواهی کرد.
سلاح‌هایت را زمین بگذار، و تنها آنگاه آن را غیرحقیقی ادراک خواهی کرد.', 'هیچ بی‌رحمی در خداوند* وجود ندارد و در من نیز بی‌رحمی نیست.

هیچ‌ کس بدون قصد آسیب رساندن، حمله نمی‌کند. این نمی‌تواند هیچ استثنایی داشته باشد. زمانی که می‌پنداری حمله تو دفاع از خود است، منظورت این است که بی‌رحم بودن محافظت است؛ تو به دلیل بی‌رحمی ایمن هستی. منظورت این است که باور داری آسیب رساندن به دیگری برای تو آزادی می‌آورد. و منطورت این است که حمله کردن تبدیل وضعیت به وضعیتی است به نحوی بهتر، امن‌تر، با محافظت بیشتر از تهاجم خطرناک و از ترس.

چقدر کاملا دیوانه‌وار است این ایده که دفاع در برابر ترس، حمله کردن است! زیرا در اینجا ترس است که تولید شده و با خون تغذیه کرده است، تا باعث رشد آن و متورم شدن و غضبناک شدن آن گردد. و این چنین ترس محافظت می‌شود، از آن گریخته نمی‌شود. امروز ما درسی را می‌آموزیم که می‌تواند تو را از تاخیر بیشتر و احساس بدبختی بیهوده، بیش از آنچه احتمالا می‌توانی تصور کنی، باز دارد. آن درس این است: تو آنچه را که در برابرش دفاع می‌کنی می‌سازی، و با دفاع خود تو در برابرش آن واقعی و گریز‌ناپذیر است. سلاح‌هایت را زمین بگذار، و تنها آنگاه آن را غیرحقیقی ادراک خواهی کرد.

به نظر می‌رسد این دشمن بیرونی است که تو به آن حمله می‌کنی. اما دفاع تو دشمن را در درون بر می‌انگیزد، پندار بیگانه‌ای که با تو در جنگ است، تو را از صلح محروم می‌کند، ذهنت را به دو اردوگاه تقسیم می‌کند که به نظر می‌رسد کاملا آشتی‌ناپذیر هستند. زیرا عشق اینک یک «دشمن» دارد، یک متضاد؛ و ترس، آن بیگانه، اینک نیاز به دفاع تو دارد در برابر تهدید آنچه که واقعا هستی.

اگر به دقت به وسایلی توجه کنی که توسط آن‌ها دفاع از خودِ تخیلی تو، مسیر تصوری خود را طی می‌کند، پیش‌فرض‌هایی را که این ایده بر آن‌ها استوار است درک خواهی کرد. ابتدا، این واضح است که ایده‌ها باید سرچشمه خود را ترک کنند، زیرا تو هستی که حمله را می‌سازی، و باید ابتدا آن را درک کرده باشی. اما تو به بیرون از خودت حمله می‌کنی، و ذهنت را از او که مورد حمله قرار می‌گیرد جدا می‌کنی، با یقین کامل به اینکه این جداسازی که انجام می‌دهی واقعی است.

سپس، صفت‌های عشق به «دشمن» او عطا می‌شود. زیرا ترس به امنیت تو و محافظ صلح تو تبدیل می‌شود، به چیزی که تو برای تسلی و فرار کردن از تردید‌ها در مورد قدرت خود به آن رو می‌کنی، و امید آرامش در سکون بدون رؤیا. و از آنجا که عشق از آنچه فقط و فقط متعلق به آن است مجزا می‌شود، به عشق صفت‌های ترس داده می‌شود. زیرا عشق از تو می‌خواهد همه دفاع خود را که صرفا احمقانه است رها کنی. و سلاح‌های تو در حقیقت به غبار تبدیل می‌شوند. زیرا چنین هستند.

با عشق به عنوان دشمن، بی‌رحمی باید به یک خدا بدل شود. و خدایان می‌طلبند که آنان که پرستش‌گرانشان هستند از فرمان‌های آن‌ها اطاعت کنند، و آنان را مورد پرسش قرار ندهند. مجازات خشونت‌آمیز بدون بخشایش سهم آنان است که در مورد واقعی بودن یا حتی عاقلانه بودن خواسته‌ها سوال می‌کنند. این دشمنان آنان هستند که بی‌منطق و دیوانه می‌باشند، در حالی که آن‌ها همیشه بخشنده و عادل هستند.

امروز ما بی‌اشتیاق به این خدای بی‌رحم نظر می‌کنیم. و توجه می‌کنیم که اگر چه لب‌های او آغشته به خون است، و به نظر می‌رسد آتش از او زبانه می‌کشد، او فقط از سنگ ساخته شده است. او هیچ کاری نمی‌تواند بکند. ما نیاز نداریم با قدرت او مقابله کنیم. او هیچ قدرتی ندارد. و آنان که امنیتشان را در او می‌بینند، هیچ محافظی ندارند، هیچ قدرتی که در خطر آن را فرا بخوانند، و هیچ جنگجوی توانمندی که برایشان بجنگد.

این لحظه می‌تواند وحشتناک باشد. اما همچنین می‌تواند زمانی باشد برای رهایی تو از بردگی تحقیر کننده. تو انتخابی را انجام می‌دهی، با ایستادن در برابر این خدای دروغین، با دیدن او دقیقا همانگونه که هست. آیا تو آنچه را که خواستی از عشق سلب کنی و در پیش این تکه سنگ بی‌ذهن بگذاری، به عشق بر خواهی گرداند؟ یا خدای دروغینی دیگری خواهی ساخت تا جایگزین این شود! زیرا خدای بی‌رحمی شکل‌های بسیاری به خود می‌گیرد. می‌توان یکی دیگر را یافت.

اما نپندار که ترس، فرار از ترس است. بگذارید یادآوری کنیم آنچه را که متن در مورد موانع صلح تاکید کرد. مانع نهایی، و مانعی که باور به هیچ بودنش دشوارترین است، و مانع ظاهری که جلوه‌ی یک سد محکم، غیر قابل نفوذ، ترسناک و فراتر از غلبه را دارد، ترس از خود* خداوند* است. این همان فرض بنیادین است که بر سر پندار ترس، تاج خدایی می‌نشاند. زیرا آنان که ترس را پرستش می‌کنند، به آن عشق می‌ورزند، و در اینجا به نظر می‌رسد که عشق با بی‌رحمی آمیخته است.

این باور کاملا نامعقول به خدایانِ انتقام از کجا می‌آید؟ عشق صفات خود را با صفات ترس اشتباه نگرفته است. اما پرستش‌گران ترس، باید سردرگمی خود را درمورد «دشمن» ترس؛ و بی‌رحمی آن را اینک به عنوان بخشی از عشق ادراک کنند. و چه چیزی ترسناک‌تر از خود* قلب* عشق* می‌شود؟ به نظر می‌رسد خون بر لب‌های او*ست؛ آتش از او سرچشمه می‌گیرد. و او* بیش از هر چیزی وحشتناک است، بی‌رحم‌تر از حد تصور، همه آنان را که خداوند*ی‌اش را تصدیق می‌کنند به زمین می‌کوبد.

انتخابی که تو امروز انجام می‌دهی، مطمئن است. زیرا تو برای آخرین بار به این قطعه سنگ کنده‌کاری شده که ساخته‌ای می‌نگری، و دیگر آن را خدا خطاب نمی‌کنی. تو قبلا به اینجا رسیده‌ای، اما انتخاب کرده‌ای که این خدای بی‌رحم هنوز در شکل دیگری با تو بماند. و این چنین ترس از خداوند* به تو بازگشت. اینک تو آن را در اینجا رها می‌کنی. و به دنیای جدیدی باز می‌گردی، دنیایی که توسط وزنش تحت فشار قرار نمی‌گیرد؛ از چشمان بی‌فروغ آن نگاه نمی‌شود، بلکه از نگاهی که انتخاب تو برایت باز ساخته است دیده می‌شود.

اینک چشمان تو به مسیحا* تعلق دارد، و از طریق آن‌ها می‌نگرد. اینک آوای تو به خداوند* تعلق دارد و آوای* او* را پژواک می‌کند. و اینک قلب تو برای همیشه در صلح باقی می‌ماند. تو او* را به جای خدایان دروغین انتخاب کرده‌ای، و صفات تو، که توسط آفریدگارت* به تو عطا شده سرانجام به تو باز گردانده می‌شود. فراخوان* برای خداوند* شنیده شده و پاسخ داده می‌شود. اینک ترس جای خود را به عشق می‌دهد، و خود* خداوند* جایگزین بی‌رحمی می‌شود.

پدر*، ما همانند تو* هستیم. هیچ بی‌رحمی در ما ساکن نیست، زیرا هیچ بی‌رحمی در تو* نیست. صلح تو* از آن ما است. و ما دنیا را با آنچه فقط از تو* دریافت کرده‌ایم تبرک می‌کنیم. ما دوباره انتخاب می‌کنیم، و برای همه برادرانمان این انتخاب را انجام می‌دهیم، در حالی که می‌دانیم آن‌ها با ما یگانه هستند. ما رستگاری تو* را برای آنان می‌آوریم آنچنان که اینک آن را دریافت کرده‌ایم. و از آنان که ما را کامل می‌کنند، سپاسگزاری می‌کنیم. ما شکوه تو را در آنان می‌بینیم، و در آنان صلح خود را می‌یابیم. ما مقدس هستیم زیرا قداست تو* ما را آزاد کرده است. و ما سپاسگزاریم. آمین.', 'https://acim-farsi.org/workbook/lesson/170', 'https://acim-farsi.org/audio/workbook/lesson/170.mp3', 'interval', '[{"kind":"interval","minutes":60}]');
