INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (181, 'من به برادرانم اعتماد می‌کنم، آنان که با من یگانه هستند.', 'این، آن چیزی نیست که من می‌خواهم نگاهش کنم.
من به برادرانم اعتماد می‌کنم، آنان که با من یگانه هستند.', 'من به برادرانم اعتماد می‌کنم، آنان که با من یگانه هستند.

اعتماد کردن به برادرانت برای استقرار و تقویت ایمان تو به توانمند بودن در عبور از تردید و فقدان اعتماد قطعی به خودت، اساسی است. زمانی که به برادری حمله می‌کنی، اعلام می‌کنی که او توسط آنچه تو از او درک می‌کنی محدود شده است. تو به فراتر از خطاهای او نگاه نمی‌کنی. بلکه، این خطاها برجسته می‌شوند، به سدهایی در برابر آگاهی تو از آن خویشتن* که ورای اشتباهات خودت نهفته است تبدیل می‌شوند، و مانع عبور از گناهان ظاهری او و نیز خودت می‌گردند.

ادراک دارای یک تمرکز است. این است که به آنچه تو می‌بینی یکپارچگی می‌دهد. فقط این تمرکز را تغییر بده، و آنچه می‌بینی مطابق با آن تغییر خواهد کرد. رؤیت تو اینک متحول خواهد شد، تا از قصدی حمایت کند که جایگزین قصد قبلی تو شده است. تمرکز خود را از گناهان برادر خود بردار، و آنگاه صلحی را تجربه خواهی کرد که از ایمان به بی‌گناهی می‌آید. این ایمان تنها حمایت مطمئن خود را از آنچه تو در دیگران فراتر از گناهانشان می‌بینی، دریافت می‌کند. زیرا خطاهای آنان، اگر بر رویشان تمرکز کنی، شاهدان گناهان در تو هستند. و تو از منظر آن‌ها عبور نخواهی کرد و بی‌گناهی‌ای را که در ورایشان نهفته است نخواهی دید.

بنابراین در تمرین امروز، ابتدا ما اجازه می‌دهیم همهٔ چنین تمرکزهای ناچیزی جای خود را به نیاز عظیم ما برای اجازه دادن به ظهور بی‌گناهی‌مان بدهند. ما ذهن‌هایمان را هدایت می‌کنیم که در جستجوی این هستیم، و فقط این، فقط برای مدتی کوتاه. ما به هدف‌های آینده‌مان اهمیتی نمی‌دهیم. و آنچه لحظه‌ای پیش دیدیم، در این فاصله زمانی که در حال تمرین برای تغییر قصدمان هستیم، برای ما هیچ اهمیتی ندارد. ما بی‌گناهی را طلب می‌کنیم و نه هیچ چیز دیگری. ما بی‌گناهی را فقط اینک بدون هیچ نگرانی طلب می‌کنیم.

یک آسیب عمده به موفقیت، درگیری با هدف‌های گذشته و آینده‌ات بوده است. تو بسیار به این موضوع مشغول بوده‌ای که تا چه اندازه زیادی هدف‌های تعیین شده توسط این دوره با هدف‌هایی که تو پیش‌تر داشته‌ای متفاوت هستند. و تو همچنین با این پندار افسرده کننده و محدود کننده تضعیف شده‌ای که حتی اگر توفیق یابی، ناگزیر راه خود را دوباره گم خواهی کرد.

این چه اهمیتی می‌تواند داشته باشد؟ زیرا گذشته رفته است؛ آینده فقط تصور است. این نگرانی‌ها فقط دفاع‌هایی هستند در برابر تغییر تمرکز ادراک در زمان حال. نه چیزی بیشتر. ما این محدودیت‌های بیهوده را فقط برای مدت کوتاهی کنار می‌گذاریم. ما به باورهای گذشته نگاه نمی‌کنیم، و آنچه باور خواهیم کرد در این زمان نگرانمان نمی‌کند. ما به زمان تمرین با یک قصد وارد می‌شویم؛ نظر کردن به بی‌گناهی درون.

ما تشخیص می‌دهیم که این هدف را از دست داده‌ایم اگر خشم، طریقمان را در هر شکلی مسدود کند. و اگر گناهان برادری برایمان پیش بیاید، تمرکز تنگ شدهٔ ما نگاهمان را محدود خواهد کرد، و چشمانمان را به سمت خطاهای خودمان بر می‌گرداند، خطاهایی که ما بزرگ خواهیم کرد و آن‌ها را «گناهانمان» خواهیم خواند. پس، برای مدت کوتاه، بدون نظر کردن به گذشته یا آینده، اگر چنین سدهایی بروز کردند ما از آن‌ها با هدایت کردن ذهنمان برای تغییر تمرکز آن عبور خواهیم کرد، در حالی که می‌گوییم: این، آن چیزی نیست که من می‌خواهم نگاهش کنم. من به برادرانم اعتماد می‌کنم، آنان که با من یگانه هستند.

و ما همچنین از این اندیشه استفاده خواهیم کرد تا در طول روز از ما محافظت کند. ما در پی هدف‌های دراز مدت نیستیم. همانطور که به نظر می‌رسد هر انسدادی نگاه ما را به بی‌گناهی‌مان مسدود می‌کند، ما فقط در پی لحظه‌ای آزادی از آن فلاکت هستیم که تمرکز بر گناه پیش می‌آورد، و اگر این تمرکز تصحیح نشود، باقی می‌ماند.

همچنین ما خواستار تخیلات نمی‌شویم. زیرا آنچه نظر کردن به آن را می‌طلبیم، واقعا وجود دارد. و همچنانکه تمرکز ما به فراتر از خطاها می‌رود، ما یک دنیای تماماً بی‌گناه را خواهیم دید. زمانی که دیدن این دنیا همه چیزی است که ما می‌خواهیم، زمانی که این همهٔ چیزی است که ما به نام ادراک حقیقی می‌طلبیم، چشمان مسیحا* ناگزیر از آن ما می‌شوند. و آن عشق* که او* برای ما احساس می‌کند، از آن ما نیز می‌گردد. این تنها چیزی خواهد شد که ما می‌بینیم در دنیا و در خودمان بازتاب می‌کند.

دنیایی که زمانی گناهان ما را ادعا می‌کرد، به گواه این تبدیل می‌شود که ما بی‌گناه هستیم. و عشق ما برای همه آنان که نگاهشان می‌کنیم، به یاد‌آوری ما از آن خویشتن* مقدسی شهادت می‌دهد که هیچ گناهی نمی‌شناسد، و هرگز نمی‌تواند چیزی را بدون بی‌گناهی او* درک کند. ما درحالی که امروز تمرین می‌کنیم، طالب این یادآوری هستیم. ما نه به پیش نگاه می‌کنیم نه به پس. ما مستقیماً به حال نگاه می‌کنیم. و به آن تجربه که اینک می‌طلبیم، اعتماد می‌کنیم. بی‌گناهی ما، فقط ارادهٔ* خداوند* است. در این لحظه ارادهٔ ما با ارادهٔ* او* یگانه است.', 'https://acim-farsi.org/workbook/lesson/181', 'https://acim-farsi.org/audio/workbook/lesson/181.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (182, 'من لحظه‌ای آرام خواهم بود و به منزل خواهم رفت.', 'من لحظه‌ای آرام خواهم بود و به منزل خواهم رفت.', 'من لحظه‌ای آرام خواهم بود و به منزل خواهم رفت.

این دنیا که به نظر می‌رسد تو در آن زندگی می‌کنی، منزل تو نیست. و جایی در ذهنت می‌دانی که این حقیقت است. خاطره‌ای از منزل در ذهنت مدام خطور می‌کند، گویا مکانی بوده است که تو را به بازگشت فرا می‌خواند، گرچه تو نه این آوا را می‌شناسی، و نه آنچه را که این آوا به تو یادآوری می‌کند. اما هنوز احساس می‌کنی که اینجا یک بیگانه‌ هستی، از جایی کاملا ناشناخته. هیچ چیز را نمی‌توانستی به این وضوح با اطمینان بگویی که تو در اینجا یک تبعیدی هستی. فقط احساسی ماندگار، که گاهی چیزی بیش از یک لرزش کوچک نیست، در زمان‌های دیگر به سختی به یاد آورده می‌شود، فعالانه رد می‌شود، اما بی‌شک دوباره به ذهن باز می‌گردد.

هیچ‌کس نیست که نداند ما از چه سخن می‌گوییم. با این حال برخی تلاش می‌کنند از رنجشان در بازی‌هایی که وقتشان را با آن‌ها پر می‌کنند، رها شوند، و غمشان را از خود دور کنند. دیگران انکار خواهند کرد که غمگین هستند، و اصلا اشک‌هایشان را نمی‌شناسند. برخی دیگر نیز بر این باور می‌مانند که آنچه ما از آن سخن می‌گوییم وهم است، و نباید بیش از یک رؤیا شمرده شود. اما چه کسی، با صداقتی ساده، بدون حالت تدافعی و خودفریبی، می‌تواند درک کردن کلماتی را که ما می‌گوییم انکار کند؟

امروز ما از سوی هر کسی که در این دنیا گام بر می‌دارد سخن می‌گوییم، زیرا او در منزل نیست. او بی‌اطمینان در جستجویی بی‌پایان حرکت می‌کند، در حالی که در تاریکی آنچه را نمی‌تواند بیابد می‌طلبد؛ و تشخیص نمی‌دهد که چه چیز را می‌خواهد. او هزاران منزل می‌سازد، اما هیچ‌کدام ذهن بی‌قرارش را راضی نمی‌کنند. او درک نمی‌کند که این ساختن پوچ است. منزلی که او می‌جوید نمی‌تواند توسط خودش ساخته شود. هیچ جایگزینی برای بهشت* وجود ندارد. همهٔ آنچه که او تاکنون ساخته دوزخ بود.

شاید بپنداری که آن چیزی که می‌خواهی دوباره بیابی منزل کودکی تو است. کودکی بدن تو، و مکانی که سرپناه آن بوده، اینک آنچنان خاطره‌ای مغشوش است که تو صرفاً تصویری از گذشته را نگاه می‌داری که هرگز رخ نداده است. اما در تو یک کودک* مقدس وجود دارد که منزل پدرش* را جستجو می‌کند، و می‌داند که او* در اینجا بیگانه است. این کودکی، ابدی است، با بی‌گناهی که برای همیشه دوام دارد. جایی که این کودک* باید به آن برود، سرزمینی مقدس است. قداست این کودک* است که بهشت* را نورانی می‌کند، و این قداست بازتاب خالص نور عالم بالا را به زمین می‌آورد، نوری را که در آن زمین و بهشت* به هم پیوسته و یگانه می‌شوند.

این کودک* مقدس در تو است که پدرت* به عنوان فرزند* خودش* می‌شناسد. این کودک* است که پدرش* را می‌شناسد. او* میل دارد به منزل برود، میلی چنان عمیق، چنان تسلی‌ناپذیر که آوایش را بر سرت فریاد می‌کشد تا اجازه دهی مدت زمانی کوتاه بیاساید. او* بیش از چند لحظه مهلت نمی‌خواهد، صرفاً فاصله‌ای را می‌خواهد که در آن فاصله بتواند به تنفس دوباره‌ی هوای مقدسی باز گردد که منزل پدرش* را پر کرده است. تو نیز منزل او* هستی. او* باز خواهد گشت. اما فقط زمان کوتاهی به او* اجازه بده که خودش* باشد، در صلحی که منزلش است، تا در سکوت و در صلح و عشق آنجا بیاساید.

این کودک* نیاز به محافظت تو دارد. او* از منزل دور است. او* آن‌چنان کوچک است که به نظر می‌رسد به آسانی خفه می‌شود، و آوای ظریفش به آسانی محو می‌گردد، درخواست کمکش تقریباً در میانه‌ی صداهای نزاع و شلوغی‌های خشن و گوش‌خراش دنیا شنیده نمی‌شود. اما او* می‌داند که در تو هنوز محافظت اطمینان‌بخش از او* ساکن است. تو او* را رها نمی‌کنی. او* به منزل خواهد رفت، و تو همراه با او* می‌روی.

این کودک*، بی‌دفاعی تو است؛ قدرت تو. او* به تو اعتماد دارد. او* آمد زیرا می‌دانست که تو بی‌شک شکست نمی‌خوری. او* بی‌وقفه از منزلش با تو زمزمه می‌کند. زیرا او* می‌خواهد تو را با خودش باز گرداند، تا او* خودش* بتواند بماند، و دوباره به جایی که به آن تعلق ندارد باز نگردد، جایی که مانند یک تبعیدی در دنیای پندارهای بیگانه زندگی می‌کند. شکیبایی او* حدی ندارد. او* صبر خواهد کرد تا زمانی که تو* آوای* مهربانانه‌اش را درونت بشنوی، که تو را فرا می‌خواند تا به او* اجازه دهی در صلح برود، همراه با تو، به آنجا که او* در منزل است و تو همراهش.

زمانی که تو لحظه‌ای آرام هستی، زمانی که دنیا از تو عقب‌نشینی می‌کند، زمانی که ایده‌های بی‌ارزش، ارزش خود را در ذهن بی‌قرار تو از دست می‌دهند، آنگاه تو آوای* او* را خواهی شنید. فراخوان او* برای تو چنان تکان دهنده است که نخواهی توانست بیشتر در برابر او* مقاومت کنی. در آن لحظه او* تو را به منزلش خواهد برد، و تو با او* در سکون کامل خواهی ماند، ساکت و در صلح، فراتر از همه واژ‌ه‌ها، در حالی که ترس و تردید به تو دست نمی‌یابند، و عمیقاً مطمئن هستی که درمنزل هستی.

امروز بارها به همراه او* بیاسای. زیرا او* اراده کرد که کودک* کوچکی شود تا تو بتوانی از او* بیاموزی که آن‌‌کس که بدون هیچ دفاعی می‌آید چقدر نیرومند است، کسی که فقط پیام‌های عشق را به آنان که می‌پندارند او دشمنشان است، عرضه می‌کند. او* قدرت بهشت* را در دستانش دارد و آنان را دوست می‌خواند، و قدرتش را به آنان می‌دهد، تا آنان بتوانند ببیند که او* می‌خواهد دوست* آنان باشد. او* می‌خواهد که آن‌ها از او* حفاظت کنند، زیرا منزلش بسیار دور است، و او* به تنهایی به آن باز نخواهد گشت.

مسیحا* فقط بسان کودک* کوچکی دوباره زاده می‌شود هر زمان که یک سرگردان می‌خواهد منزلش را ترک کند. زیرا او* باید بیاموزد که آنچه می‌خواهد از آن محافظت کند فقط همین کودک* است، که بی‌دفاع می‌آید و توسط بی‌دفاعی محافظت می‌گردد. گه‌گاهی امروز با او* به منزل برو. تو هم به اندازهٔ او* در اینجا بیگانه هستی.

امروز وقت صرف کن تا سپر خود را که هیچ سودی ندارد کنار بگذاری، و نیزه و شمشیری را که در برابر دشمنی که وجود ندارد بلند کرده‌ای بر زمین بیاندازی. مسیحا* تو را دوست و برادر خوانده است. او* حتی آمده است که یاری تو را بطلبد تا اجازه دهی امروز به منزل برود، تکمیل شده و به طور کامل. او* مانند یک کودک کوچک آمده است، که باید از پدرش حفاظت و عشق تقاضا کند. او* بر جهان فرمان می‌راند، اما بی‌وقفه می‌خواهد که تو به همراه او* باز گردی، و بیش از این اوهام را خدایان خود محسوب نکنی.

تو بی‌گناهی خود را گم نکرده‌ای. و تو برای این مشتاق هستی. این خواست قلبی تو است. این همان آوا است که تو می‌شنوی، و این همان فراخوانی است که نمی‌توان انکارش کرد. این کودک* مقدس با تو می‌ماند. منزل او* از آن تو است. امروز او* بی‌دفاعی‌اش را به تو ارزانی می‌کند، و تو آن را می‌پذیری به جای همهٔ بازیچه‌های جنگ که ساخته‌ای. و اینک طریق باز است، و این سفر سرانجام پایانی قابل مشاهده دارد. لحظه‌ای آرام باش و با او* به منزل برو، و مدتی در صلح باش.', 'https://acim-farsi.org/workbook/lesson/182', 'https://acim-farsi.org/audio/workbook/lesson/182.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (183, 'من نام* خداوند* را می‌خوانم و نام خودم را.', 'من نام* خداوند* را می‌خوانم و نام خودم را.', 'من نام* خداوند* را می‌خوانم و نام خودم را.

نام* خداوند* مقدس است، اما مقدس‌تر از نام تو نیست. خواندن نام* او* فقط خواندن نام خود تو است. یک پدر نام خود را به فرزندش می‌دهد، و از این طریق فرزندش را با خود یگانه می‌سازد. برادرانش در نام او سهیم هستند، و از این طریق آن‌ها در پیوندی که برای هویتشان به آن رو می‌کنند با یکدیگر یگانه می‌شوند. نام* پدرت* به تو یادآوری می‌کند که چه کسی هستی، حتی در دنیایی که نمی‌داند؛ حتی اگر تو آن نام را به یاد نداشته باشی.

نام* خداوند* نمی‌تواند بدون پاسخ شنیده شود، و نیز نمی‌تواند بدون پژواکی در آن ذهن که تو را به یادآوری فرا می‌خواند، گفته شود. نام* مقدس او* را بگو، و تو فرشتگان را دعوت می‌کنی تا زمینی را که بر آن می‌ایستی احاطه کنند، و برایت نغمه‌خوانی کنند در حالی که بالهایشان را برای محافظت از تو می‌گشایند، و تو را از همهٔ پندارهای دنیوی که دنیا با آن‌ها به قداست تو تهاجم می‌کند، حفاظت می‌کند.

نام* خداوند* را تکرار کن، و همهٔ دنیا با رها کردن اوهام پاسخ می‌دهد. همه‌ی رؤیاهایی که دنیا عزیز می‌دارد ناگهان کنار گذاشته می‌شوند، و در جایی که به نظر می‌رسید این رؤیاها ایستاده‌اند تو ستاره‌ای را می‌یابی؛ معجزه‌ای از فیض. بیماران از جا برمی‌خیزند، شفا یافته از پندارهای بیمار خود. کوران می‌توانند ببینند؛ ناشنوایان می‌توانند بشنوند. ماتم‌زدگان سوگواری خود را کنار می‌گذارند، و اشک‌های درد خشک می‌شوند در حالی که خندهٔ شادمان می‌آید تا دنیا را متبرک سازد.

نام* خداوند* را تکرار کن، و نام‌های کوچک معنای خود را از دست می‌دهند. هیچ وسوسه‌ای نیست جز این که در برابر نام* خداوند* به یک چیز بی‌نام و ناخواسته تبدیل می‌شود. نام* او* را تکرار کن، و ببین که چه آسان نام‌های همهٔ خدایانی را که با ارزش می‌پنداشتی فراموش خواهی کرد. آن‌ها نام خدایی را که تو به آن‌ها دادی گم می‌کنند. آن‌ها برای تو بی‌نام و بی‌ارزش می‌شوند، اگر چه پیش از اینکه اجازه دهی نام* خداوند* جایگزین نام‌های کوچکشان شود، پرستشگرانه در پیشگاهشان می‌ایستادی و خدا خطابشان می‌کردی.

نام* خداوند* را تکرار کن و خویشتنت* را فرا بخوان، که نامش* از آن او* است. نام* او* را تکرار کن، و همهٔ چیزهای ناچیز و بی‌نام بر زمین به دورنمای درست خواهند لغزید. آنان که نام* خداوند* را می‌خوانند نمی‌توانند بی‌نام را با نام* اشتباه بگیرند، و نه گناه را با فیض، و نه بدن‌ها را با فرزند* مقدس خداوند*. و اگر به برادری بپیوندی در حالی‌ که با او در سکوت می‌نشینی، و در ذهن ساکت خود همراه با او نام* خداوند* را تکرار می‌کنی، محرابی را ساخته‌ای که به خود* خداوند* و به فرزندش* می‌رسد.

امروز فقط این را تمرین کن؛ به آهستگی نام* خداوند* را بارها و بارها تکرار کن. به هر نامی به جز نام* او* بی‌توجه شو. هیچ چیز دیگری را نشنو. اجازه بده همهٔ اندیشه‌های تو بر این متمرکز شوند. هیچ کلمه دیگری را استفاده نمی‌کنیم به جز در آغاز، زمانی که فقط یک‌ بار ایده امروز را می‌گوییم. و سپس نام* خداوند* تنها اندیشهٔ ما می‌شود، تنها کلمهٔ ما، تنها چیزی که ذهن‌های ما را اشغال می‌کند، تنها آرزویی که داریم، تنها صدا با هر معنا و تنها نام* همه چیز، که ما می‌خواهیم ببینیم؛ نام* همهٔ چیزهایی که ما می‌خواهیم از آن خودمان بخوانیم.

این چنین ما دعوتی را عرضه می‌کنیم که هرگز نمی‌تواند رد شود. و خداوند* خواهد آمد، و خودش* به آن پاسخ خواهد داد. نیندیش که او* دعاهای کوچک کسانی را می‌شنود که او* را با نام‌های خدایان دروغینی می‌خوانند که توسط این دنیا گرامی داشته می‌شوند. آنان نمی‌توانند این چنین به او* دست یابند. او* نمی‌تواند تقاضاهایی را بشنود که از او* می‌خواهند خودش* نباشد، یا می‌خواهند که فرزندش* نامی جز نام* او* را دریافت کند.

نام* خداوند* را تکرار کن، و تو او* را به عنوان تنها آفریدگار* واقعیت تصدیق می‌کنی. و تو همچنین تصدیق می‌کنی که فرزندش* بخشی از او* است، در حالی که به نام* او* می‌آفریند. ساکت بنشین و اجازه بده نام* او* ایدهٔ کاملا فراگیری شود که ذهن تو را کاملا اشغال می‌کند. بگذار همهٔ اندیشه‌ها به جز این اندیشه آرام گیرند. و به همه‌ی پندارهای دیگر با این اندیشه پاسخ بده و ببین که نام* خداوند* جایگزین هزار نام کوچکی می‌شود که تو به افکارت داده‌ای، در حالیکه نمی‌دانستی یک نام* برای همهٔ آنچه که هست وجود دارد، و برای همهٔ آنچه که خواهد بود.

امروز تو می‌توانی به حالی دست یابی که در آن موهبت فیض را تجربه خواهی کرد. تو می‌توانی از همهٔ اسارت دنیا بگریزی، و به دنیا همان رهایی را عرضه کنی که یافته‌ای. تو می‌توانی آنچه را که دنیا فراموش کرده به یاد بیاوری، و به دنیا یادآوری خود را عرضه کنی. تو امروز می‌توانی آن نقش را که در رستگاری دنیا داری بپذیری، و نیز نقشی را که در رستگاری خودت داری. و هر دوی اینها می‌توانند کاملاً به انجام برسند.

برای رهایی خود به نام* خداوند* رو کن، و رهایی به تو عطا می‌شود. به هیچ نیایشی به جز این نیاز نیست، زیرا این نیایش همهٔ نیایش‌ها را در خود در بر می‌گیرد. واژه‌ها بی‌اهمیت هستند، و همهٔ درخواست‌ها غیرضروری زمانی که فرزند* خداوند* نام* پدرش* را فرا می‌خواند. اندیشه‌های* پدرش* به اندیشه‌های خود او تبدیل می‌شوند. او مدعی همهٔ آن چیزی می‌شود که پدرش* عطا کرد، هنوز عطا می‌کند، و برای همیشه عطا خواهد کرد. او پدرش* را فرا می‌خواند تا بگذارد همهٔ چیزهایی که می‌پنداشت ساخته است اینک بی‌نام شوند، و به جای آن‌ها نام* مقدس خداوند* به قضاوت او در مورد بی‌ارزشی آن‌ها تبدیل شود.

همهٔ چیزهای کوچک ساکت هستند. اینک صداهای کوچک بی‌صدا هستند. چیزهای کوچک زمین ناپدید شده‌اند. جهان شامل هیچ چیزی نیست به جز فرزند* خداوند*، که پدرش* را می‌خواند. و آوای* پدرش* به نام* مقدس پدرش* پاسخ می‌دهد. در این رابطهٔ ابدی آرام، که در آن ارتباط بسیار فراتر از همهٔ کلمات است، و با این حال در عمق و ارتفاع از هر کلامی که بتوان بیان کرد فراتر است، صلح ابدی است. به نام* پدرمان* ما امروز می‌خواهیم این صلح را تجربه کنیم. و به نام* او*، این صلح به ما عطا خواهد شد.', 'https://acim-farsi.org/workbook/lesson/183', 'https://acim-farsi.org/audio/workbook/lesson/183.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (184, 'نام* خداوند* میراث من است.', 'پدر*، نام* ما از آن تو است. در این نام ما با همهٔ چیزهای زنده یگانه هستیم، و با تو* که آفریدگار* یگانه آن‌هایی. آن چه ما ساختیم و با نام‌های گوناگون بسیار خواندیم، تنها سایه‌ای است که تلاش کرده‌ایم بر واقعیت خود* تو* بیاندازیم. و شادمان هستیم و سپاسگزار از اینکه در اشتباه بودیم. همه خطاهایمان را به نزد تو* می‌آوریم، باشد تا بتوانیم از همه تاثیراتی که به نظرمان می‌آید خطاهایمان دارند آمرزیده شویم. و ما آن حقیقت را که تو* عطا می‌کنی می‌پذیریم، به جای هر یک از آن‌ها. نام* تو* رستگاری ما است و فرار ما از آنچه ساختیم. نام* تو* ما را در آن یگانگی که میراث و صلح ما است، متحد می‌سازد. آمین.', 'نام* خداوند* میراث من است.

تو با نمادها زندگی می‌کنی. تو نام‌هایی را برای هر آنچه که می‌بینی ساخته‌ای. هر نامی به یک هویت جدا تبدیل می‌شود، که توسط نامش شناخته می‌شود. با این کار تو آن را از وحدت جدا می‌کنی. با این کار تو صفت‌های ویژهٔ آن را معین می‌کنی، و آن را از چیزهای دیگر با تاکید بر فضای پیرامونش جدا می‌سازی. این فضا را تو میان همهٔ چیزهایی که به آن‌ها نام‌های متفاوت می‌دهی؛ همهٔ رویدادها بر حسب مکان و زمان؛ همهٔ بدن‌هایی که با نامی خوانده می‌شوند، قرار می‌دهی.

این فضایی که تو آن را جداکنندهٔ همه چیز از یکدیگر می‌بینی، وسیله‌ای است که توسط آن ادراک دنیا ایجاد می‌گردد. تو چیزی را می‌بینی در جایی که هیچ چیزی نیست، و همچنین هیچ چیزی را نمی‌بینی در جایی که وحدت است؛ فضایی میان همهٔ چیزها، میان همهٔ چیزها و تو. این‌چنین تو می‌پنداری که در جدایی، حیات بخشیده‌ای. توسط این شکاف تو می‌پنداری که به عنوان یک وحدتی ساخته شده‌‌ای که با اراده‌‌ای مستقل عمل می‌کند.

این نام‌ها چیست که توسط آن‌ها دنیا به مجموعه‌ای از رویدادهای گسسته تبدیل می‌شود، مجموعه‌ای از چیزهای غیریگانه با هم، مجموعه‌ای از بدن‌هایی که جدا نگه داشته می‌شوند و پاره‌هایی از ذهن را به عنوان آگاهی‌های جداگانه حمل می‌کنند؟ تو این نام‌ها را به آن‌ها دادی، تا ادراک را بسازی آن‌چنان که می‌خواستی باشد. به چیزهایی بی‌نام نام داده شد، و این چنین به آن‌ها واقعیت نیز داده شد. زیرا آنچه نامیده شود به آن معنا داده شده و سپس بامعنا دیده خواهد شد؛ علتی دارای اثر حقیقی، که در خودش دارای پیامد ذاتی است.

این همان شیوه است که واقعیت توسط رؤیت نسبی ساخته می‌شود، کاری که عمدا بر علیه حقیقتِ عطا شده انجام می‌گیرد. دشمن این روش، تمامیت است. آن چیزهای کوچک را درک کرده و به آنان نظر می‌کند. و فقدان فضا، احساسی از وحدت یا رؤیتی که متفاوت می‌بیند، به تهدیدهایی تبدیل می‌شوند که این روش باید بر آنها غالب گردد، با آنها بستیزد و انکارشان کند.

اما این رؤیتِ دیگر، هنوز یک مسیر طبیعی برای ذهن باقی می‌ماند تا ادراکِ خود را هدایت کند. سخت است به ذهن هزار نام بیگانه آموخته شود، و هزاران نام بیگانهٔ دیگر. اما تو باور داری که معنای آموختن این است؛ یگانه هدف اساسی آن که از این طریق ارتباط ایجاد می‌شود، و می‌توان مفاهیم را به طرز با معنایی در میان گذاشت.

این مجموعِ میراثی است که دنیا ارزانی می‌کند. هر کسی که می‌آموزد بیاندیشد که چنین است، نشانه‌ها و نمادهایی را که اطمینان می‌دهند این دنیا واقعی است می‌پذیرد. نشانه‌ها و نمادها مدافع این واقعی بودن هستند. آن‌ها هیچ شکی را باقی نمی‌گذارند که آنچه نامیده می‌شود وجود دارد. می‌توان آن را دید، آنگونه که مورد انتظار است. آنچه حقیقی بودنش را انکار می‌کند فقط وهم است، زیرا این نهایت واقعیت است. مورد پرسش قرار دادن آن دیوانگی است؛ پذیرش حضورش گواه عقلانیت است.

چنین است آموزش این دنیا. این مرحله‌ای از آموختن است که هر کسی می‌آید باید آن را بگذراند. اما به محض اینکه او درک می‌کند که مبنایش چیست، فرضهای آن چقدر مورد پرسش هستند، نتایج آن چقدر مورد تردید هستند، بلافاصله اثرات آن را مورد پرسش قرار می‌دهد. آموختنی که با آنچه این دنیا می‌خواهد بیاموزد متوقف می‌شود، فاقد معنا می‌شود. در جایگاه درستش، این آموختن فقط به عنوان نقطه آغازی خدمت می‌کند که از آن نوع دیگری از آموختن می‌تواند آغاز شود، ادراک جدیدی می‌تواند بدست آید، و همهٔ نام های ساختگی که این دنیا ارائه می‌کند می‌توانند با مورد تردید قرار گرفتن، رها گردند.

نپندار که تو این دنیا را ساخته‌ای. اوهام، بله! اما آنچه در زمین و بهشت* حقیقی است، فراتر از نام‌گذاری تو است. زمانی که تو برادری را فرا می‌خوانی، بدنش را خطاب می‌کنی. هویت حقیقی او توسط آنچه که باور داری او واقعا هست، پنهان است. بدنش به آنچه تو او را می‌خوانی پاسخ می‌دهد، زیرا ذهنش به پذیرش نامی که به او دادی به عنوان نام خودش رضایت می‌دهد. و این‌چنین وحدت او دو بار انکار می‌شود، زیرا تو او را جدا از خودت ادراک می‌کنی، و او این نام جداگانه‌ را به عنوان نام خود می‌پذیرد.

حقیقتأ عجیب می‌شد اگر از تو خواسته می‌شد به ورای همه‌ی نمادهای این دنیا بروی، آن‌ها را برای همیشه فراموش کنی؛ اما از تو خواسته می‌شود یک کار آموزشی انجام دهی. تو نیاز داری نمادهای این دنیا را برای مدتی مورد استفاده قرار دهی. اما همچنین نباید توسط آن‌ها فریب بخوری. آن‌ها هیچ معنایی ندارند، و در تمرین تو این اندیشه است که تو را از آن‌ها رها خواهد ساخت. آن‌ها فقط به ابزارهایی تبدیل می‌شوند که توسطشان تو می‌توانی به روش‌هایی ارتباط برقرار کنی که دنیا بتواند بفهمد، که اما تو تشخیص می‌دهی آن وحدتی نیست که در آن بتوان ارتباط حقیقی را یافت.

از این رو آنچه تو نیاز داری فاصله‌های زمانی در هر روز است که در آن آموختن این دنیا به یک مرحلهٔ گذرا تبدیل می‌شود؛ یک زندان خانگی که از آن تو به درون آفتاب می‌روی و تاریکی را فراموش می‌کنی. در اینجا تو آن کلام* و آن نام* را که خداوند* به تو عطا کرده است؛ آن هویت* یگانه‌ای که همهٔ چیزها با هم سهیم هستند؛ آن تصدیق یگانهٔ چیزی که حقیقی است. و سپس به تاریکی بر می‌گردی نه به این دلیل که می‌پنداری واقعیت است، بلکه فقط برای اعلام غیرواقعی بودن آن با لفظ‌هایی که هنوز در این دنیا که تاریکی بر آن فرمان می‌راند، معنا دارند.

از همهٔ نام‌ها و نمادهای کوچکی که دنیای تاریکی را ترسیم می‌کنند استفاده کن. اما آن‌ها را به عنوان واقعیت خود نپذیر. روح‌القدس* از همه آنها استفاده می‌کند، اما از یاد نمی‌برد که آفرینش یک نام*، یک معنا، و یک سرچشمهٔ* واحد دارد که همهٔ چیزها را درون خودش به یگانگی می‌رساند. از همهٔ آن نام‌هایی که دنیا به آن چیزها ارزانی کرده است استفاده کن فقط برای آسودگی، اما از یاد نبر که آن‌ها همراه با تو نام* خداوند* را سهیم هستند.

خداوند* هیچ نامی ندارد. و با این حال نام* او* به این درس نهایی تبدیل می‌شود که همهٔ چیزها یگانه هستند، و در این درس همهٔ آموختن پایان می‌یابد. همهٔ نام‌ها یگانه می‌شوند؛ همهٔ فضا با بازتاب حقیقت پر می‌شود. همهٔ فاصله‌ها بسته می‌شوند، و جدایی شفا می‌یابد. نام* خداوند* آن میراث است که او به کسانی ارزانی کرد که انتخاب کردند آموزش دنیا را جایگزین بهشت* کنند. در تمرینمان، قصدمان این است که اجازه دهیم ذهن‌های ما پاسخ خداوند* را بپذیرند، پاسخی که خداوند* به میراث ناچیزی داد که تو فرزندش* را که به او عشق می‌ورزد، لایق آن می‌دانی.

هیچ کس که معنای نام* خداوند* را می‌طلبد شکست نخواهد خورد. تجربه باید بیاید تا کلام* را تکمیل کند. اما ابتدا تو باید نام* همهٔ واقعیت را بپذیری، و تشخیص دهی که نام‌های متعددی که تو به جنبه‌های آن داده‌ای، آنچه را که می‌بینی مغشوش کرده است، اما به هیچ وجه با حقیقت تداخل نکرده است. این نام* یگانه را ما به تمرین خود می‌آوریم. ما از این نام* یگانه برای به وحدت رساندن بینایی‌مان استفاده می‌کنیم.

و با اینکه ما برای هر آگاهی از جنبه‌ای از فرزند* خداوند* نام متفاوتی را استفاده می‌کنیم، می‌فهمیم که این جنبه‌ها فقط یک نام* دارند، که او* به آنها عطا کرد. ما از این نام* در تمرین استفاده می‌کنیم. و از طریق استفاده از آن، همه جدایی‌های احمقانه که ما را کور نگه می‌داشتند، ناپدید می‌شوند. و به ما قدرت دیدن ورای آنها داده می‌شود. اینک نگاه ما با برکت‌هایی متبرک می‌شود که می‌توانیم همان‌گونه که دریافت می‌کنیم، بدهیم.

پدر*، نام* ما از آن تو است. در این نام ما با همهٔ چیزهای زنده یگانه هستیم، و با تو* که آفریدگار* یگانه آن‌هایی. آن چه ما ساختیم و با نام‌های گوناگون بسیار خواندیم، تنها سایه‌ای است که تلاش کرده‌ایم بر واقعیت خود* تو* بیاندازیم. و شادمان هستیم و سپاسگزار از اینکه در اشتباه بودیم. همه خطاهایمان را به نزد تو* می‌آوریم، باشد تا بتوانیم از همه تاثیراتی که به نظرمان می‌آید خطاهایمان دارند آمرزیده شویم. و ما آن حقیقت را که تو* عطا می‌کنی می‌پذیریم، به جای هر یک از آن‌ها. نام* تو* رستگاری ما است و فرار ما از آنچه ساختیم. نام* تو* ما را در آن یگانگی که میراث و صلح ما است، متحد می‌سازد. آمین.', 'https://acim-farsi.org/workbook/lesson/184', 'https://acim-farsi.org/audio/workbook/lesson/184.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (185, 'من صلح خداوند* را می‌خواهم.', 'من صلح خداوند* را می‌خواهم.', 'من صلح خداوند* را می‌خواهم.

گفتن این واژه‌ها هیچ است. اما مصمم بودن به این واژه‌ها همه چیز است. اگر می‌توانستی تنها برای لحظه‌ای به آن‌ها مصمم باشی، دیگر هیچ تاسفی در هیچ شکلی برای تو ممکن نبود؛ در هیچ مکان یا زمانی. بهشت* به تمامی به آگاهی کامل بازگردانده می‌شد، خاطرهٔ خداوند* کاملاً بازیافت می‌شد، رستاخیز همهٔ آفرینش کاملا شناخته می‌شد.

هیچ کس نمی‌تواند به این کلمات مصمم باشد و شفا نیابد. او نمی‌تواند با رؤیاها بازی کند، یا بپندارد خودش یک رؤیا است. او نمی‌تواند یک دوزخ بسازد و آن را واقعی بپندارد. او صلح خداوند* را می‌خواهد، و به او داده می‌شود. زیرا این همهٔ چیزی است که می‌خواهد، و همهٔ چیزی است که دریافت خواهد کرد. بسیاری این کلمات را گفته‌اند. اما حقیقتا تعداد کمی به آن‌ها مصمم بوده‌اند. فقط لازم است به دنیای پیرامونت که می‌بینی نظر کنی تا مطمئن شوی که آن‌ها چقدر اندک هستند. این دنیا کاملا تغییر می‌کرد، اگر دو نفر با هم موافقت می‌کردند که این کلمات تنها چیزی را که می‌خواهند، بیان می‌کنند.

دو ذهن با یک قصد آنچنان نیرومند می‌شوند که آنچه اراده می‌کنند به ارادهٔ* خداوند* تبدیل می‌گردد. زیرا ذهن‌ها فقط می‌توانند در حقیقت به هم بپیوندند. در رؤیاها، هیچ دو ذهنی نمی‌توانند در یک قصد واحد سهیم شوند. برای هر یک، قهرمان رؤیا متفاوت است؛ نتیجه‌ای که می‌خواهند برای هر دو یکی نیست. بازنده و برنده صرفاً در الگوی متغیر با هم جابجا می‌شوند، در حالی که نسبت بردن به باختن و باختن به بردن جنبه‌ای متفاوت یا شکل دیگری را به خود می‌گیرد.

با این حال یک رؤیا می‌تواند فقط سازش را به همراه داشته باشد. گاهی سازش شکل اتحاد را به خود می‌گیرد، اما فقط شکل آن را. معنا باید از رؤیا بگریزد، زیرا سازش هدف رؤیاپردازی است. ذهن‌ها نمی‌توانند در رؤیاها متحد شوند. آنها صرفا سوداگری می‌کنند. و کدام سوداگری می‌تواند به آنان صلح خداوند* را عرضه کند؟ اوهام جای او* را می‌گیرد. و آنچه مقصود او* است، برای ذهن‌های خفته‌ای که قصد سازش دارند گم می‌شود، هر یک به سود خود و به زیان دیگری.

مصمم بودن به اینکه تو صلح خداوند* را می‌خواهی، چشم‌پوشی از همه رؤیاها است. زیرا هیچ کسی که اوهام را می‌خواهد معنای این کلمات را درک نمی‌کند، و بنابراین ابزاری را طلب می‌کند که اوهام را به ارمغان بیاورد. او به اوهام نظر کرده است، و آن‌ها را ناقص یافته است. حال او می‌طلبد که به ورای آن‌ها برود، با تشخیص اینکه یک رؤیای دیگر هیچ چیزی بیش از همهٔ رؤیاها عرضه نمی‌کند. رؤیاها برای او یکی هستند. و او آموخته است که تنها تفاوت آن‌ها، تفاوت در شکل است، زیرا هر یک همان ناامیدی و فلاکتی را موجب می‌شوند که بقیه.

آن ذهن که مصمم است که همه آنچه می‌خواهد صلح است، باید با ذهن‌های دیگر بپیوندد، زیرا از این طریق است که صلح به دست می‌آید. و زمانی که آرزوی صلح خالصانه است، وسیله برای یافتن آن عطا می‌شود، در شکلی که هر ذهنی که صادقانه طالب آن است بتواند درک کند. هر شکلی که این درس به خود بگیرد به چنان شیوه‌ای برای او طراحی می‌شود که نمی‌تواند اشتباه کند، اگر از صمیم قلب خواستار آن است. اما اگر او بدون خلوص خواهان باشد، هیچ شکلی وجود ندارد که در آن این درس بتواند قابل پذیرش باشد و حقیقتا آموخته شود.

بگذارید امروز تمرین خود را برای تشخیص اینکه ما واقعا به کلماتی که می‌گوییم مصمم هستیم، اختصاص دهیم. ما صلح خداوند* را می‌خواهیم. این آرزوی بیهوده نیست. این کلمات طالب این نیستند که رؤیای دیگری به ما داده شود. آن‌ها خواهان سازش نیستند، و تلاش نمی‌کنند سوداگری دیگری انجام دهند با این امید که هنوز یک سوداگری هست که بتواند موفق شود در جایی که بقیه همه شکست خورده‌اند. مصمم بودن به معنای این کلمات، تصدیق می‌کند که اوهام بیهوده هستند، و طلب می‌کند که آنچه ابدی است جای رؤیاهای تغییر کننده‌ای را بگیرد که به نظر می‌رسد در آنچه عرضه می‌کنند متغیر هستند، رؤیاهایی که فقط در هیچ بودن با هم یکی هستند.

امروز زمانهای تمرین خود را به جستجوی دقیق ذهنت اختصاص بده، به یافتن آن رؤیاهایی که هنوز ستایش می‌کنی. تو در قلبت چه چیزی را می‌خواهی؟ کلماتی را که از آن‌ها در اعلام خواسته‌هایت استفاده می‌کنی فراموش کن. فقط توجه کن به آنچه باور داری به تو آرامش می‌دهد، و برایت شادی می‌آورد. اما توسط اوهامی که باقی می‌مانند ناامید نشو، زیرا شکل آنها چیزی نیست که اینک اهمیت دارد. اجازه نده برخی رؤیاها بیشتر قابل پذیرش باشند، در حالی‌ که شرم و پنهان‌کاری را برای بقیه حفظ می‌کنی. آن‌ها با هم یکی هستند. و با یکی بودن، باید در مورد همهٔ آن‌ها یک پرسش را پرسید: «آیا این چیزی است که من می‌خواهم داشته باشم، به جای بهشت* و صلح خداوند*؟»

این انتخاب است که انجام می‌دهی. فریب نخور که اینگونه نیست. در این انتخاب هیچ سازشی ممکن نیست. یا تو صلح خداوند* را انتخاب می‌کنی، یا رؤیاها را خواسته‌ای. همه رؤیاها آن‌ گونه که تو درخواستشان می‌کنی، خواهند آمد. اما صلح خداوند* نیز دقیقا با همان اطمینان خواهد آمد، و با تو برای همیشه خواهد ماند. صلح خداوند* با هر پیچ و خم راه تو را ترک نخواهد کرد، تا دوباره نمایان شود، شناخته نشده، در شکل‌هایی که با هر گامی که بر می‌داری جابجا شوند و تغییر کنند.

تو صلح خداوند* را می‌خواهی. و همه آنان که به نظر می‌رسد طالب رؤیاها هستند چنین می‌خواهند. برای آنها نیز همانند خودت، فقط این را می‌خواهی زمانی که این خواسته را با خلوص عمیق اعلام می‌کنی. زیرا از این طریق تو به آنچه آنان واقعا می‌خواهند دست می‌یابی، و قصد خودت را با آنچه آنان بیش از هر چیز می‌طلبند پیوند می‌زنی، که شاید برای آنان ناشناخته باشد، اما برای تو قطعی است. تو گاهی ضعیف بوده‌ای، نامطمئن به هدفت، و نامطمئن به آنچه می‌خواستی، و جایی که جستجویش کنی، و جایی که در تلاشت برای کمک به آنجا رو کنی. کمک به تو داده شده است. و آیا تو نمی‌خواهی با سهیم شدنش خودت از آن بهره‌مند شوی؟

هیچ کس که حقیقتا صلح خداوند* را می‌جوید هرگز در یافتن آن شکست نمی‌خورد. زیرا او صرفا می‌خواهد که بیش از این خودش را فریب ندهد، فریبی که با انکار ارادهٔ* خداوند* برای خودش صورت می‌گیرد. آیا کسی که پاسخی را می‌طلبد که پیشاپیش از آن خودش است می‌تواند ناراضی بماند؟ چه کسی می‌تواند بی‌پاسخ باشد که پاسخی را درخواست می‌کند که از آن خودش است برای دادن؟ صلح خداوند* از آن تو است.

زیرا صلح برای تو آفریده شد، توسط آفریدگارش* به تو داده شد، و به عنوان هدیهٔ ابدی خود* او* استقرار یافت. چگونه می‌توانی شکست بخوری، وقتی که فقط چیزی را می‌خواهی که او* برایت اراده می‌کند؟ و چگونه خواستهٔ تو می‌تواند تنها به خودت محدود شود؟ هیچ هدیه‌ای از خداوند* نمی‌تواند سهیم نشده باقی بماند. این خصلت است که هدایای خداوند* را از همهٔ رؤیاهایی که تا حال به نظر رسیده جای حقیقت را می‌گیرند، متمایز می‌کند.

هیچ‌کس نمی‌تواند بازنده باشد و همگان باید برنده باشند هر زمان که هر هدیه‌ای از خداوند* توسط هر کسی درخواست و دریافت شده باشد. خداوند* تنها برای وحدت بخشیدن عطا می‌کند. سلب کردن برای او* بی‌معنا است. و زمانی که به همین اندازه برای تو بی‌معنا باشد، می‌توانی مطمئن باشی که یک اراده* را با او سهیم هستی، و او* با تو سهیم است. و هم چنین تو خواهی دانست که یک اراده‌* را با همه برادرانت سهیم هستی، که قصدشان قصد تو است.

امروز ما خواستار همین یک قصد هستیم، که خواسته‌های ما را با نیاز هر قلبی به وحدت می‌رساند، با فراخوان همهٔ ذهن‌ها، با آن امید که فراتر از ناامیدی نهفته است، با آن عشق که حمله می‌خواهد پنهانش کند، با آن پیوند برادری که نفرت خواسته است آن را بشکند، اما همهٔ این‌ها هنوز آنگونه باقی مانده‌اند که خداوند* آفریدشان. با کمکی* مانند این در کنارمان، آیا امروز می‌توانیم شکست بخوریم در حالی که درخواست می‌کنیم صلح خداوند* به ما داده شود؟', 'https://acim-farsi.org/workbook/lesson/185', 'https://acim-farsi.org/audio/workbook/lesson/185.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (186, 'رستگاری دنیا به من بستگی دارد.', 'رستگاری دنیا به من بستگی دارد.', 'رستگاری دنیا به من بستگی دارد.

در اینجا جمله‌ای هست که روزی همهٔ گستاخی را از هر ذهنی خواهد برد. در اینجا اندیشهٔ فروتنی حقیقی قرار دارد، که هیچ وظیفه‌ای را که از آن خود تو است نگه نمی‌دارد جز آن وظیفه‌ای که به تو عطا شده است. این اندیشه به تو پذیرش نقشی را که برایت تعیین شده، عرضه می‌کند، بدون اصرار بر نقشی دیگر. این اندیشه نقش مناسب تو را مورد قضاوت قرار نمی‌دهد. این اندیشه فقط تصدیق می‌کند که ارادهٔ* خداوند* بر زمین نیز همانند بهشت* انجام شده است. این اندیشه همهٔ اراده‌های روی زمین را در نقشهٔ بهشت* برای نجات دنیا با هم متحد می‌سازد، که صلح بهشت* را در آن بازیابی می‌کند.

بیایید با وظیفهٔ خودمان نجنگیم. ما آن را تعیین نکردیم. این وظیفه ایدهٔ ما نیست. وسایلی به ما داده شده که توسط آن‌ها، این وظیفه کاملا به انجام خواهد رسید. همهٔ آنچه از ما خواسته شده انجام دهیم، پذیرش نقشمان در فروتنی خالصانه است، و انکار نکردن شایستگی‌مان با گستاخی خودفریبانه. آنچه به ما داده شده که انجام دهیم، قدرت انجامش را داریم. ذهن‌های ما برای ایفای نقشی که توسط آن یگانه* که* ما را خوب می‌شناسد برایمان تعیین شده است، کاملا مناسب هستند.

ایدهٔ امروز ممکن است بسیار سنگین به نظر برسد، تا زمانی که تو معنای آن را ببینی. همهٔ آنچه این ایده می‌گوید این است که پدرت* هنوز تو را به یاد دارد، و اعتماد کاملی را که نسبت به تو دارد ارزانی‌ات می‌کند، تو که فرزندش* هستی. این ایده نمی‌خواهد تو به هیچ روی از آنچه که هستی متفاوت باشی. فروتنی چه چیزی جز این را می‌تواند بخواهد؟ و گستاخی چه چیزی را جز این می‌تواند انکار کند؟ امروز ما از تعهد خود بر این زمین فریبنده که در آن فروتنی بی‌حرمت می‌شود، شانه خالی نخواهیم کرد. این غرور است که می‌خواهد فراخوان* برای خود* خداوند* را انکار کند.

امروز ما همهٔ فروتنی کاذب را کنار می‌گذاریم، تا بتوانیم به آوای* خود* خداوند* که برای ما روشن می‌سازد چه کاری را از ما می‌خواهد، گوش فرا دهیم. ما شایستگی خود را برای وظیفه‌ای که او* به ما عرضه خواهد کرد، مورد تردید قرار نمی‌دهیم. ما فقط از این مطمئن خواهیم بود که او* توان ما را می‌شناسد، خرد ما و قداست ما را. و اگر او* ما را شایسته می‌پندارد، پس ما چنین هستیم. تنها گستاخی است که قضاوتی دیگرگونه دارد.

یک راه، و فقط یک راه وجود دارد تا بتوانی از زندان نقشهٔ خودت برای اثبات اینکه غیرحقیقی حقیقی است، آزاد شوی. در عوض آن نقشه را که نساختی بپذیر. در مورد ارزش خودت برای آن قضاوت نکن. اگر آوای* خداوند* به تو اطمینان می‌دهد که رستگاری نیاز به نقش تو دارد، و اینکه همه چیز به تو بستگی دارد، مطمئن باش که چنین است. افراد گستاخ باید به کلمات بیاویزند، هراسان از رفتن به ورای آن‌ها برای تجربه کردن آنچه که ممکن است به موقعیتشان بی‌حرمتی کند. اما فروتنان برای شنیدن آن آوا* که به ایشان می‌گوید چه هستند و چه باید بکنند، آزاد هستند.

گستاخی تصویری از خودت می‌سازد که واقعی نیست. این تصویر است که در وحشت می‌لرزد و عقب می‌نشیند، در حالی که آوای* خداوند* تو را مطمئن می‌سازد که قدرت داری و خرد و قداست، تا بتوانی به ورای همهٔ تصویرها بروی. تو ضعیف نیستی، آنگونه که تصویرت از تو هست. تو نادان و درمانده نیستی. گناه نمی‌تواند حقیقت را در تو تیره گرداند، و فلاکت نمی‌تواند به خانهٔ مقدس خداوند* نزدیک شود.

همهٔ این را آوای* برای خداوند* به تو مربوط می‌سازد. و همچنان که* او سخن می‌گوید، آن تصویر می‌لرزد و می‌خواهد به تهدیدی حمله کند که آن را نمی‌شناسد، در حالی که حس می‌کند بنیادش فرو می‌ریزد. رهایش کن. رستگاری دنیا به تو بستگی دارد و نه به این تودهٔ کوچک غبار. این توده کوچک غبار چه چیزی می‌تواند به فرزند* مقدس خداوند* بگوید؟ چرا اصلا باید نیازی باشد که او* نگرانش باشد؟

و اینچنین ما صلحمان را می‌یابیم. ما آن وظیفه را که خداوند* به ما داده است خواهیم پذیرفت، زیرا همهٔ اوهام بر این باور عجیب و غریب استوار هستند که ما می‌توانیم وظیفهٔ دیگری را برای خودمان بسازیم. نقش‌های خودساختهٔ ما در حال جابجایی هستند، و به نظر می‌رسد که این نقش‌ها از ماتم‌زدگی تا سرور شوق‌آمیز عشق و عشق‌ورزی تغییر می‌کنند. ما می‌توانیم بخندیم یا گریه کنیم، و از روز با خوش‌آمدگویی یا اشک استقبال کنیم. به نظر می‌رسد که موجودیت ما با تجربه کردن هزار جابجایی در خُلقمان، تغییر می‌کند، و در حقیقت احساساتمان ما را بالا می‌برند، یا در نومیدی به زمین می‌کوبند.

آیا این فرزند* خداوند* است؟ آیا او* می‌توانست چنین بی‌ثباتی را بیافریند و آن را فرزند* بخواند؟ او* که* بی‌تغییر است، صفات خود* را با آفرینش خود* سهیم می‌شود. همهٔ تصویرهای که به نظر می‌رسد فرزندش* می‌سازد، هیچ تأثیری بر آنچه که او* هست نمی‌گذارد. این تصویرها از ذهن فرزندش* مانند برگ‌هایی که باد آن‌ها را جارو می‌زند عبور می‌کنند در حالی که یک لحظه الگویی را شکل می‌دهند، پراکنده می‌شوند تا دوباره گرد هم آیند، و پراکنده گردند. یا مانند سراب‌های که بر صحرا دیده می‌شوند، و از غبار بر می‌خیزند.

این تصویرهای بی‌اساس خواهند رفت، و ذهن تو را صاف و روشن باقی خواهند گذاشت، زمانی که آن وظیفه را که به تو عطا شده است بپذیری. تصویرهایی که تو می‌سازی فقط منجر به هدف‌های متعارض می‌شوند، هدف‌های بی‌دوام و مبهم، نامطمئن و دوپهلو . چه کسی می‌تواند در تلاشهایش ثابت قدم باشد، یا انرژی‌ها و انگیزش متمرکز خود را به سمت چنین هدف‌هایی متوجه کند؟ آن وظیفه‌هایی که دنیا محترم می‌شمارد چنان نامطمئن هستند که هر ساعت ده مرتبه در بهترین حالت تغییر می‌کنند. از این هدف‌ها چه امید سود بردن را می‌توان داشت؟

درست در نقطهٔ مقابل، مطمئن همچون بازگشت خورشید در هر صبح برای راندن شب، وظیفهٔ حقیقی که به تو داده شده است قرار دارد، روشن و کاملا واضح. هیچ تردیدی در مورد اعتبار آن وجود ندارد. این وظیفه از سوی کسی* می‌آید که هیچ خطایی نمی‌شناسد، و آوای* او* درمورد پیامهایش مطمئن است. این پیامها تغییر نخواهند کرد، و در تعارض نخواهند بود. همهٔ این پیام‌ها به یک هدف اشاره دارند، آن هدفی که تو می‌توانی بدست آوری. نقشهٔ تو ممکن است ناممکن باشد، اما نقشهٔ خداوند* هرگز نمی‌تواند شکست بخورد زیرا او* سرچشمهٔ آن است.

آنگونه انجام بده که آوای* خداوند* هدایت می‌کند. و اگر این آوا* چیزی را از تو می‌خواهد که به نظر ناممکن به نظر می‌رسد، به یاد آور که چه کسی در حال خواستن است، و چه کسی می‌خواهد انکار کند. و سپس به این توجه کن؛ کدام یک بیشتر احتمال دارد برحق باشد؟ آن آوا* که از سوی آفریدگار* همه چیز سخن می‌گوید، او* که همه چیز را دقیقا آنگونه که هست می‌شناسد، یا تصویری مغشوش از خودت، سردرگم، سرگردان، ناپایدار و نامطمئن از همه چیز؟ اجازه نده که صدای آن تو را هدایت کند. در عوض یک آوای* مطمئن را بشنو که از وظیفه‌ای که توسط آفریدگارت* به تو داده شده است به تو می‌گوید، او* که تو را به یاد دارد، و می‌طلبد که تو اینک او* را به یاد بیاوری.

آوای* مهربان او* تو را از شناخته به نشناخته می‌خواند. او می‌خواهد به تو دلداری دهد، اگر چه هیچ اندوهی را نمی‌شناسد. او* می‌خواهد جبران کند، اگرچه او* کامل است؛ هدیه‌ای به تو، اگرچه او* می‌داند که تو در حال حاضر همه چیز داری. او* اندیشه‌هایی* دارد که به هر نیازی که فرزندش* درک می‌کند، پاسخ می‌دهد، اگر چه او* آن نیازها را نمی‌بیند. زیرا عشق* باید بدهد، و آنچه به نام او* داده می‌شود در دنیایی از شکل، مفیدترین شکل را به خود می‌گیرد.

اینها شکل‌هایی هستند که هرگز نمی‌توانند فریب دهند، زیرا آنان از خودِ بی‌شکلی می‌آیند. بخشایش یک شکل زمینی از عشق است، این عشق آنچنان که در بهشت* است هیچ شکلی ندارد. اما آنچه در اینجا مورد نیاز است، همانطور که مورد نیاز است داده می‌شود. در این شکل تو می‌توانی وظیفهٔ خود را حتی در اینجا ایفا کنی، اگر چه آنچه عشق برای تو معنا خواهد داشت زمانی که بی‌شکلی برایت اعاده شده باشد، بسیار عظیم‌تر است. رستگاری دنیا به تو بستگی دارد که می‌توانی ببخشی. چنین است وظیفهٔ تو در اینجا.', 'https://acim-farsi.org/workbook/lesson/186', 'https://acim-farsi.org/audio/workbook/lesson/186.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (187, 'من دنیا را تبرک می‌کنم زیرا خودم را تبرک می‌کنم.', 'من دنیا را تبرک می‌کنم زیرا خودم را تبرک می‌کنم.', 'من دنیا را تبرک می‌کنم زیرا خودم را تبرک می‌کنم.

هیچ کس نمی‌تواند بدهد مگر داشته باشد. در واقع، دادن گواه داشتن است. ما این نکته را پیش‌تر گفته‌ایم. آنچه تایید را به نظر مشکل می‌سازد، این نیست. هیچ کس نمی‌تواند تردید کند که تو باید ابتدا آن چیزی را که می‌خواهی بدهی داشته باشی. این دومین مرحله‌ای است که در آن دنیا و ادراک حقیقی با هم تفاوت دارند. اگر چیزی داشته شود و داده شود، آن گاه این دنیا گواهی می‌دهد که تو آن چه را که مالک بوده‌ای از دست داده‌ای. حقیقت معتقد است که دادن، آنچه را که تو مالکش هستی افزایش خواهد داد.

این چگونه ممکن است؟ زیرا قطعی است که اگر تو یک چیز محدود را بدهی، چشمان بدن تو درک نخواهند کرد که از آن تو است. اما ما آموخته‌ایم که چیزها فقط تجلی اندیشه‌هایی هستند که آن‌ها را می‌سازند. و تو فاقد این گواه نیستی که هر زمان ایده‌ها را می‌دهی، آن‌ها را در ذهنت تقویت می‌کنی. احتمالا شکلی که در آن اندیشه ظاهرا متجلی می‌شود، با دادن تغییر می‌کند. اما آن اندیشه باید به کسی که می‌دهد، برگردد. شکلی که به خود می‌گیرد نمی‌تواند کمتر قابل پذیرش باشد. باید بیشتر پذیرفتنی باشد.

ایده‌ها نخست باید از آن تو باشند، پیش از آن که آن‌ها را بدهی. اگر بنا است که تو این دنیا را نجات دهی، تو ابتدا رستگاری را برای خودت می‌پذیری. اما تو باور نخواهی کرد که این به انجام رسیده است، تا زمانی که آن معجزاتی را ببینی که به هر کسی که تو به او نظر می‌کنی، ارزانی می‌کند. اینجاست که ایدهٔ دادن روشن می‌شود و معنا می‌گیرد. اینک تو می‌توانی درک کنی که با دادن، اندوختهٔ تو افزایش می‌یابد.

از همهٔ چیزهایی که برایت ارزش دارند، با اقدام به دادن آن‌ها محافظت کن، و مطمئن می‌شوی که هرگز آن‌ها را از دست نخواهی داد. آن چه که می‌پنداشتی نداری، از این طریق به عنوان داشتهٔ تو اثبات می‌شود. اما به شکل آن ارزش نده. زیرا این شکل تغییر خواهد کرد و گاه شناخت‌ناپذیر می‌شود، اگر چه تو بسیار تلاش می‌کنی آن را امن نگه داری. هیچ شکلی باقی نمی‌ماند. این اندیشهٔ موجود در پس شکل چیزها است که تغییرناپذیر باقی می‌ماند.

با شادمانی بده. تو از این طریق فقط می‌توانی دریافت کنی. اندیشه باقی می‌ماند، و زمانی که با دادن تقویت می‌گردد، قدرت آن افزایش می‌یابد. اندیشه‌ها با سهیم شدن گسترش می‌یابند، زیرا نمی‌توانند از دست بروند. هیچ دهنده و گیرنده‌ای آنگونه که این دنیا تصور می‌کند، وجود ندارد. یک دهنده وجود دارد که از دست نمی‌دهد، و دهندهٔ دیگری که او نیز خواهد داد. و هر دوی آن‌ها باید در این تبادل سود کنند، زیرا هر یک این اندیشه را در شکلی دارند که برای ایشان بیشترین فایده را دارد. آن چیزی که به نظر می‌رسد کسی از دست می‌دهد، همیشه چیزی است که ارزش آن را کمتر از آن چیز می‌داند که قطعا بازگردانده خواهد شد.

هرگز فراموش نکن که تو تنها به خودت می‌دهی. آن کس که معنای دادن را می‌فهمد، باید به ایدهٔ قربانی دادن بخندد. و او قطعا شکل‌های بسیاری را که قربانی دادن می‌تواند به خود بگیرد، تشخیص می‌دهد. همچنین او به رنج و فقدان می‌خندد، به بیماری و به سوگواری، به فقر، گرسنگی کشیدن و به مرگ. او تشخیص می‌دهد که قربانی دادن ایدهٔ واحدی است که در پس همه این‌ها ایستاده است، و در خنده آرام او، تمام اینها شفا می‌یابند.

وهمی که شناخته شود باید ناپدید گردد. رنج را نپذیر، و آنگاه اندیشه رنج را حذف می‌کنی. تبرک تو هر کسی را که رنج می‌برد متبرک می‌کند، زمانی که انتخاب می‌کنی همه رنج‌ها را آنگونه که هستند ببینی. اندیشه قربانی دادن باعث به وجود آمدن همه شکل‌هایی می‌شود که به نظر می‌رسد رنج به خود می‌گیرد. و قربانی دادن ایده‌ای است چنان دیوانه‌وار که عقلانیت یکباره آن را از میان بر می‌دارد.

هرگز باور نکن که می‌توانی قربانی بدهی. هیچ جایی برای قربانی دادن در چیزی که ارزش داشته باشد، وجود ندارد. اگر این اندیشه پیش آید، خود حضور آن اثبات می‌کند که خطایی رخ افتاده است و باید تصحیح انجام شود. تبرک تو آن را تصحیح خواهد کرد. چون ابتدا به تو داده شد، اینک از آن تو است تا تو نیز آن را بدهی. هیچ شکلی از قربانی دادن و رنج نمی‌تواند در برابر چهرهٔ فردی که خودش را بخشیده و تبرک کرده است، برای مدت طولانی باقی بماند.

آن گل‌های سوسنی که برادرت به تو عرضه می‌کند، بر محراب تو قرار می‌گیرد، با آن گل‌هایی که تو به او عرضه می‌کنی و در کنارشان می‌گذاری. چه کسی می‌تواند از نظر کردن به چنین قداست عاشقانه‌ای بهراسد؟ وهم عظیم هراس از خداوند* در برابر خلوصی که تو در اینجا به آن نظر خواهی کرد، به هیچی محو می‌شود. از نگاه کردن نهراس. آن تبرکی که تو خواهی دید، همهٔ پندار شکل را برطرف خواهد کرد، و در عوض موهبت کامل را برای همیشه باقی می‌گذارد، برای همیشه که افزون شود، برای همیشه از آن تو، برای همیشه که داده شود.

اینک ما در اندیشه با هم یگانه هستیم، زیرا ترس برطرف شده است. و اینجا، در برابر محراب خداوند* یگانه، پدر* یگانه، آفریدگار* یگانه و اندیشهٔ* یگانه، ما با هم می‌ایستیم به عنوان فرزند* یگانهٔ خداوند*. در حالی که جدا از او* که سرچشمۀ* ما است نیستیم؛ و نه دور از برادر یگانه ما که بخشی از خویشتن* یگانهٔ ما است که معصومیتش همهٔ ما را به هم پیوسته است تا یگانه شویم، ما در تبرک می‌ایستیم، و می‌دهیم همانگونه که دریافت می‌کنیم. نام* خداوند* بر لبان ما است. و هنگامی که به درون می‌نگریم، خلوص بهشت* را می‌بینیم که در بازتاب ما از عشق* پدرمان* می‌درخشد.

اینک ما متبرک هستیم، و اینک ما دنیا را تبرک می‌کنیم. آنچه ما به آن نظر کرده‌ایم، می‌خواهیم که گسترش یابد، زیرا می‌خواهیم آن را همه جا ببینیم. ما می‌خواهیم آن را ببینیم که با فیض خداوند* در همگان می‌درخشد. ما نمی‌خواهیم هیچ چیزی که به آن نظر می‌کنیم، از این تبرک محروم بماند. و برای اطمینان از اینکه این بینایی مقدس از آن ما است، ما آن را به همه چیزهایی که می‌بینیم، عرضه می‌کنیم. زیرا هر جا که آن را ببینیم، در شکل سوسن‌هایی که می‌توانیم بر محرابمان بگذاریم به ما برخواهد گشت، و آن را به منزلی برای خود* بی‌گناهی* مقدس تبدیل می‌کند، که در ما ساکن است و قداست خود را به ما عرضه می‌کند تا از آن خود سازیم.', 'https://acim-farsi.org/workbook/lesson/187', 'https://acim-farsi.org/audio/workbook/lesson/187.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (188, 'صلح خداوند* اکنون درون من تابنده است.', 'صلح خداوند* اکنون درون من تابنده است.
بگذار همهٔ چیزها در این صلح بر من بتابند، و بگذار من آن‌ها را با نور درونم متبرک کنم.
بگذار همهٔ چیزها در این صلح بر من بتابند، و بگذار من آن‌ها را با نور درونم متبرک کنم.', 'صلح خداوند* اکنون درون من تابنده است.

چرا برای بهشت* انتظار بکشیم؟ آنان که نور را جستجو می‌کنند صرفا در حال پوشاندن چشمانشان هستند. اینک نور در درون آنها است. روشن‌ضمیری، فقط یک تشخیص است، اصلا یک تغییر نیست. نور* از این دنیا نیست، اما تو که این نور* را درونت حمل می‌کنی نیز در اینجا بیگانه هستی. این نور با تو از خانه زادگاهت آمده است، و با تو باقی مانده زیرا از آن تو است. این تنها چیزی است که از سوی او* که* سرچشمهٔ* تو است با خود آورده‌ای. این نور در تو می‌تابد زیرا خانه تو را روشن می‌کند، و تو را به سرچشمه‌اش راهنمایی می‌کند تا برگردی و در منزل باشی.

این نور را نمی‌توان گم کرد. چرا انتظار بکشی تا آن را در آینده بیابی، یا باور کنی که آن را پیشاپیش گم کرده‌ای، یا باور کنی که هرگز وجود نداشته است؟ نظر کردن به آن چنان آسان است که بحث در مورد اثبات وجود نداشتنش، مسخره می‌شود. چه کسی می‌تواند حضور چیزی را که در درونش می‌بیند انکار کند؟ نگاه کردن به درون دشوار نیست، زیرا از آنجا تمامی رؤیت آغاز می‌شود. هیچ منظره‌ای وجود ندارد، چه سرچشمه‌اش از رؤیاها باشد یا چه از یک منبع حقیقی‌تر، که فقط سایهٔ آن چیزی که از طریق رؤیت درون مشاهده می‌شود محسوب نگردد. از اینجا است که ادراک آغاز می‌گردد، و در اینجا پایان می‌یابد. ادراک هیچ سرچشمه‌ای به جز این ندارد.

صلح خداوند* اینک درون تو می‌تابد، و از قلب تو به سراسر دنیا گسترش می‌یابد. متوقف می‌شود تا هر چیز زنده‌ای را نوازش کند، و تبرکی را با آن باقی می‌گذارد که برای همیشه و همیشه ماندگار است. آن چه که ارزانی می‌کند باید ابدی باشد. این صلح همه پندارهای زودگذر و بی‌ارزش را برطرف می‌کند. این صلح برای همهٔ قلب‌های خسته، بازسازی را به ارمغان می‌آورد، و همه رؤیت را با عبورش روشن می‌کند. همه موهبت‌های آن به همگان داده می‌شود، و همه با هم در سپاسگزاری از تو که آن را ارزانی می‌کنی، و تو که آن را دریافت کرده‌ای یگانه می‌شوند.

این تابش در ذهن تو به دنیا یادآوری می‌کند آنچه را که فراموش کرده است، و دنیا نیز این خاطره را به تو بازمی‌گرداند. رستگاری از طریق تو می‌تابد، با موهبت‌هایی فراتر از هر اندازه‌گیری، که داده می‌شود و بازگردانده می‌شود. از تو، دهندهٔ موهبت، خود* خداوند* سپاسگزاری می‌کند. و در تبرک او*، نور درون تو درخشنده‌تر می‌تابد، و به موهبت‌هایی که تو برای عرضه کردن به این دنیا داری، می‌افزاید.

صلح خداوند* هرگز نمی‌تواند بازداشته شود. کسی که آن را درونش تشخیص می‌دهد، باید عرضه‌اش کند. و ابزارهای عرضه کردن آن، در فهم او هستند. او می‌بخشد زیرا حقیقت را درونش تشخیص داده است. صلح خداوند* اینک درون تو می‌تابد، و در همه چیزهای زنده. در سکوت، در تمام جهان تصدیق می‌شود. زیرا چیزی که رؤیت درونی تو به آن نظر می‌کند، ادراک تو از جهان است.

در سکوت بنشین و چشمانت را ببند. نور درون تو، کفایت می‌کند. این نور به تنهایی قدرت ارزانی کردن موهبت بینش به تو را دارد. دنیای بیرونی را نادیده بگیر، و اجازه بده افکارت به سمت صلح درون پرواز کنند. این افکار راه را می‌شناسند. زیرا افکار خالصانه، که توسط رؤیای چیزهای دنیوی بیرون از تو مغشوش نشوند، به پیام‌آوران مقدس خود* خداوند* تبدیل می‌گردند.

تو با او* این افکار را می‌اندیشی. این افکار منزلشان را می‌شناسند. و مطمئناً به سرچشمه خود اشاره می‌کنند، جایی که خداوند* پدر و فرزندش* یگانه هستند. صلح خداوند* بر آن‌ها می‌تابد، اما این افکار نیز باید با تو باقی بمانند، زیرا آن‌ها در ذهنت متولد شده‌اند، همان گونه که افکار تو در ذهن* خداوند* متولد شدند. این افکار تو را به بازگشت به صلح راهنمایی می‌کنند، به جایی که از آن آمده‌اند، فقط برای یادآوری به تو که چگونه باید برگردی.

این افکار به آوای پدرت* گوش فرا می‌دهند زمانی که تو از شنیدن اجتناب می‌کنی. و آن‌ها مهربانانه تو را هدایت می‌کنند تا کلام* مقدس او* را در مورد آنچه هستی بپذیری، به جای تخیلات و سایه‌ها. آن‌ها به یاد تو می‌آورند که هم-آفرینندهٔ تمامی چیزهای زنده هستی. زیرا همان‌گونه که صلح خداوند* بر تو می‌تابد، باید بر آن‌ها نیز بتابد.

امروز تمرین می‌کنیم تا به این نور درونمان نزدیکتر شویم. ما افکار سرگردانمان را در نظر می‌گیریم، و با ملایمت آن‌ها را به جایی باز می‌گردانیم، تا با تمامی اندیشه‌هایی که با خداوند* سهیم هستیم، همسو گردند. اجازه نمی‌دهیم که این افکار سرگردان شوند. ما به نور درون ذهنمان اجازه می‌دهیم که آنها را به سمت منزل هدایت کند. ما به این اندیشه‌ها خیانت کرده‌ایم، با فرمان دادن به آنان که از ما جدا شوند. اما اینک ما آن‌ها را فرا می‌خوانیم، واین افکار را از خواسته‌های عجیب و آرزوهای آشفته، پاک می‌شوییم. ما تقدس موروثی آن‌ها را، به آنان باز می‌گردانیم.

این چنین است که ذهن ما به همراه این افکار نجات می‌یابد، و ما تصدیق می‌کنیم که صلح خداوند* هنوز در ما می‌تابد، و از طریق ما به تمامی چیزهای زنده که در حیات با ما سهیم هستند. ما همه آنان را خواهم بخشید، و تمامی این دنیا را ازآنچه می‌پنداشتیم در مورد ما انجام داده است، مبرا می‌کنیم. زیرا این ما هستیم که دنیا را آنگونه که می‌خواهیم داشته باشیم، می‌سازیم. اینک ما انتخاب می‌کنیم که دنیا معصوم باشد، عاری از گناه و گشاده به رستگاری. و ما تبرک نجات‌بخش خود را نثار آن می‌کنیم، با گفتن جملات زیر: صلح خداوند* اینک درون من تابنده است. بگذار همهٔ چیزها در این صلح بر من بتابند، و بگذار من آن‌ها را با نور درونم متبرک کنم.', 'https://acim-farsi.org/workbook/lesson/188', 'https://acim-farsi.org/audio/workbook/lesson/188.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (189, 'من اینک عشق خداوند* را درونم احساس می‌کنم.', 'پدر*، ما طریق به سوی تو* را نمی‌شناسیم. اما ما تو* را خوانده‌ایم، و تو* به ما پاسخ گفته‌ای. ما مداخله نخواهیم کرد. طریق‌های رستگاری از آن خود ما نیستند، زیرا آن‌ها به تو* تعلق دارند. و ما برای آن‌ها به تو* نگاه می‌کنیم. دستان ما گشوده هستند تا موهبتهای تو* را دریافت کنیم. ما هیچ اندیشه‌ای نداریم که جدا از تو* بیاندیشیم، و هیچ باوری را از اینکه چه کسی هستیم یا اینکه چه کسی ما را آفرید، نمی‌پروریم. طریق تو* آن طریق است که ما می‌خواهیم بیابیم و دنبال کنیم. و ما فقط می‌خواهیم که ارادهٔ* تو*، که ارادهٔ ما نیز هست، در ما و در این دنیا به عمل درآید، تا اینک این دنیا به بخشی از بهشت* تبدیل گردد. آمین.', 'من اینک عشق خداوند* را درونم احساس می‌کنم.

نوری در تو وجود دارد که این دنیا نمی‌تواند ادراک کند. و با چشمان این دنیا این نور را نخواهی دید، زیرا تو توسط دنیا کور شده‌ای. اما تو چشمانی داری که این نور را ببینی. این نور برایت وجود دارد تا به آن نظر کنی. این نور در تو قرار داده نشده تا از دید تو پنهان بماند. این نور بازتابی از اندیشه‌ای است که ما اینک تمرین می‌کنیم. احساس کردن عشق خداوند* درونت، دیدن این دنیا به طرزی جدید است، در حالی که در بی‌گناهی می‌درخشد، با امید زنده است، و با خیر و عشق مطلق تبرک شده است.

چه کسی می‌تواند در دنیایی این چنین احساس ترس کند؟ این دنیا از تو استقبال می‌کند، از آمدن تو شادمانی می‌کند، و در ستایش تو می‌خواند در حالی که تو را از هر شکلی از خطر و درد محافظت می‌کند. این دنیا به تو یک منزل گرم و مهربان عرضه می‌کند که در آن مدتی بمانی. این دنیا تو را در طول روز تبرک می‌کند، و در طول شب مانند نگاهبان ساکت خواب مقدس تو، از تو مراقبت می‌کند. این دنیا رستگاری را در تو می‌بیند، و از نور در تو محافظت می‌کند، نوری که در آن نورِ خودش را می‌بیند. این دنیا به تو گل‌ها و برفش را ارزانی می‌کند، در سپاسگذاری برای نیک‌خواهی‌ای که داری.

این دنیایی است که عشق* خداوند* آشکار می‌سازد. این دنیا چنان با دنیایی که تو از طریق چشمان تاریک شده از کینه‌توزی و از ترس می‌بینی متفاوت است، که یکی دیگری را تکذیب می‌کند. در اصل فقط یکی از این دو دنیا را می‌توان ادراک کرد. آن دیگری کاملا بی‌معنا است. دنیایی که در آن بخشایش بر همه چیز می‌تابد، و صلح نور مهربان خود را بر همگان عرضه می‌دارد، برای کسانی که دنیایی از نفرت می‌بینند که از حمله ساخته شده، با انتقام مسموم شده، برای قتل و ویرانی، درک‌ناپذیر است.

اما دنیای نفرت به همان اندازه برای آنان که صلح خداوند* را درونشان احساس می‌کنند نادیدنی و درک‌ناپذیر است. دنیای آنان سکوت و صلحی را که درونشان می‌تابد، منعکس می‌کند؛ مهربانی و بی‌گناهی که آنان پیرامونشان می‌بینند؛ آن شادمانی که از چشمه‌های بی‌پایان شادمانی درون می‌جوشد و با آن به بیرون نگاه می‌کند. آنچه که درونشان احساس کرده‌اند، به آن نظر می‌کنند و بازتاب قظعی آن را در همه جا می‌بینند.

تو می‌خواهی چه چیز را ببینی؟ این انتخاب به تو داده شده است. اما این قانون دیدن را بیاموز و اجازه نده ذهنت این قانون را فراموش کند: تو به چیزی خواهی نگریست که درونت احساس می‌کنی. اگر نفرت درون قلبت جای گیرد، دنیایی ترسناک را ادراک خواهی کرد، که با بی‌رحمی در انگشتان تیز و استخوانی مرگ نگه داشته شده است. اگر عشق* خداوند* را درونت احساس کنی، به دنیایی از رحمت و عشق خواهی نگریست.

امروز ما از اوهام عبور می‌کنیم، همچنان که دستیابی به آنچه درونمان حقیقی است را می‌طلبیم، و مهربانی فراگیر آن را احساس می‌کنیم، عشق* آن را که ما را مانند خودش* کامل می‌شناسد، بینش آن را که موهبتی است که عشقش* بر ما ارزانی می‌کند. امروز ما طریق را می‌آموزیم. این طریق به اندازه خود عشق* قطعی است، عشقی که ما را به سوی آن می‌برد. زیرا سادگی آن از دامهای پهن شده توسط پیچیدگیهای احمقانه این دنیا اجتناب می‌کند، پیچیدگی استدلال ظاهری این دنیا که فقط می‌خواهد سادگی را پنهان کند.

به سادگی این را انجام بده: آرام باش، و تمام افکار را دربارهٔ اینکه چه هستی و خداوند* چیست؛ تمام مفاهیمی که دربارهٔ دنیا آموخته‌ای؛ همهٔ تصویرهایی که دربارهٔ خودت داری را کنار بگذار. ذهنت را از هر آنچه فکر می‌کند درست یا نادرست، یا خوب یا بد است، از هر فکری که شایسته می‌داند، و از تمام ایده‌هایی که از آن‌ها شرمنده است خالی کن. هیچ چیز را نگه ندار. هیچ فکری را که گذشته به تو آموخته است، و هیچ باوری را که قبلاً از هر چیزی یاد گرفته‌ای را با خودت نیاور. این دنیا را فراموش کن، این دوره را فراموش کن، و با دستانی کاملاً خالی به سوی خداوندت* بیا.

آیا او* همان نیست که طریق تو را می‌شناسد؟ تو نیازی نیست که طریق به سمت او* را بشناسی. نقش تو به سادگی این است که اجازه دهی تا همه موانعی که میان فرزند* و خداوندِ* پدر* قرار داده‌ای، به آرامی برای همیشه برداشته شوند. خداوند* نقش خود* را با پاسخ سرور‌آمیز و فوری ایفا خواهد کرد. بخواه و دریافت کن. اما خواسته نساز، و راه را برای خداوند* مشخص نکن که چگونه باید بر تو ظهور کند. راه رسیدن به او* صرفا این است که اجازه دهی او* باشد. زیرا به این روش واقعیت تو نیز اعلام می‌شود.

بنابراین امروز ما انتخاب نمی‌کنیم از چه طریق به سمت او* برویم. بلکه انتخاب می‌کنیم اجازه دهیم او* به سمت ما بیاید. و با این انتخاب ما آرام می‌گیریم. و در قلب‌های ساکت و ذهن‌های گشادهٔ ما، عشق* او* مسیر خود را روشن خواهد کرد. آنچه که انکار نشده است قطعا وجود دارد، اگر حقیقی باشد و بتوان با اطمینان به آن رسید. خداوند* فرزندش* را می‌شناسد، و راه به سوی او* را می‌داند. او* نیازی ندارد که فرزندش* به او نشان دهد چگونه راهش را بیابد. از طریق هر در گشوده‌، عشق* او* از منزلی که درونمان دارد، به بیرون تابش می‌کند، و این دنیا را در بی‌گناهی روشن می‌کند.

پدر*، ما طریق به سوی تو* را نمی‌شناسیم. اما ما تو* را خوانده‌ایم، و تو* به ما پاسخ گفته‌ای. ما مداخله نخواهیم کرد. طریق‌های رستگاری از آن خود ما نیستند، زیرا آن‌ها به تو* تعلق دارند. و ما برای آن‌ها به تو* نگاه می‌کنیم. دستان ما گشوده هستند تا موهبتهای تو* را دریافت کنیم. ما هیچ اندیشه‌ای نداریم که جدا از تو* بیاندیشیم، و هیچ باوری را از اینکه چه کسی هستیم یا اینکه چه کسی ما را آفرید، نمی‌پروریم. طریق تو* آن طریق است که ما می‌خواهیم بیابیم و دنبال کنیم. و ما فقط می‌خواهیم که ارادهٔ* تو*، که ارادهٔ ما نیز هست، در ما و در این دنیا به عمل درآید، تا اینک این دنیا به بخشی از بهشت* تبدیل گردد. آمین.', 'https://acim-farsi.org/workbook/lesson/189', 'https://acim-farsi.org/audio/workbook/lesson/189.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (190, 'من سرور خداوند* را به جای درد انتخاب می‌کنم.', 'من سرور خداوند* را به جای درد انتخاب می‌کنم.', 'من سرور خداوند* را به جای درد انتخاب می‌کنم.

درد یک تصور نادرست است. وقتی درد در هر شکلی تجربه می‌شود، گواهی از خودفریبی است. درد به هیچ وجه یک حقیقت نیست. هیچ شکلی نمی‌تواند به خود بگیرد که در صورت صحیح دیده شدن ناپدید نگردد. زیرا درد مدعی بی‌رحمی خداوند* است. درد چگونه می‌تواند در هیچ شکلی واقعی باشد؟ درد گواهی بر نفرت خداوندِ* پدر* از فرزندش* است، گناهکاری که در او* می‌بینید، و تمایل نامعقولش برای انتقام و مرگ.

آیا می‌توان چنین فرافکنی‌هایی را تصدیق کرد؟ آیا اینها می‌توانند چیزی باشند به جز نادرستی کامل؟ درد فقط خطاهای فرزند* خداوند* را گواهی می‌دهد در این اندیشه، که چه کسی است. درد رؤیای یک تلافی خشمگینانه برای جنایتی است که نمی‌توانست انجام شود؛ برای حمله به چیزی که کاملا آسیب‌ناپذیر است. درد کابوس طرد شدن توسط یک عشق* ابدی* است، عشقی* که نمی‌تواند فرزندی* را رها کند که در عشق* آفریدش.

درد نشانه‌ای است از اینکه اوهام در جای حقیقت حکمرانی می‌کنند. درد نشان می‌دهد که خداوند* انکار می‌شود، با ترس اشتباه گرفته می‌شود، دیوانه ادراک می‌شود، و خائن به خودش* دیده می‌شود. اگر خداوند* واقعی است، درد وجود ندارد. اگر درد واقعی است، خداوند* وجود ندارد. زیرا انتقام بخشی از عشق نیست. و ترس، که عشق را انکار می‌کند و از درد استفاده می‌کند تا اثبات کند خداوند* مرده است، نشان داده است که مرگ بر زندگی پیروز است. نشان داده است که این بدن، فرزند* خداوند* است و می‌تواند در مرگ فاسد شود، به اندازهٔ پدرش* میرنده است همان که توسط وی کشته شد.

صلح نثار چنین حماقتی باد! زمان آن فرا رسیده است که به چنین ایده‌های دیوانه‌واری بخندیم. نیازی نیست که به این ایده‌ها به عنوان جنایت‌های وحشیانه اندیشه شود، یا گناهانی پنهانی با عقوبت سنگین. چه کسی جز یک دیوانه می‌تواند آنها را علت چیزی به حساب آورد؟ گواه این ایده ها، درد، به اندازه اینها دیوانه‌وار است، و چیز بیشتری برای ترسیدن وجود ندارد، چیزی بیش از اوهام دیوانه‌وار که پنهان می‌سازد، و تلاش می‌کند نشان دهد که این اوهام باید حقیقی باشند.

فقط پندارهای تو هستند که موجب دردت می‌شوند. هیچ چیزی خارج از ذهن تو نمی‌تواند به هیچ وجه تو را آزار دهد یا به تو آسیب رساند. هیچ علتی فراتر از خودت نیست که بتواند به تو دست یابد و موجب ستم به تو شود. هیچ کس به جز خودت بر تو تاثیر نمی‌گذارد. هیچ چیزی در دنیا وجود ندارد که قدرت بیمار کردن یا غمگین کردن تو را داشته باشد، یا قدرت ضعیف و شکننده کردنت را. اما این تو هستی که قدرت غلبهٔ به همه چیزهایی را که می‌بینی داری، صرفا با تشخیص دادن اینکه چه هستی. به محض اینکه تو بی‌ضرر بودن آن‌ها را می‌پذیری، ارادهٔ مقدس تو را مانند اراده خودشان می‌پذیرند. و آنچه که ترسناک دیده می‌شد، اینک به سرچشمه‌ای از بی‌گناهی و قداست تبدیل می‌شود.

برادر مقدس من، لحظه‌ای به این بیاندیش: این دنیا که می‌بینی هیچ کاری نمی‌کند. به هیچ وجه تاثیری ندارد. این دنیا صرفاً پندارهای تو را متجلی می‌کند. و تماماً تعبیر خواهد کرد زمانی که تو انتخاب کنی ذهنت را تغییر دهی، و سرور خداوند* را به عنوان چیزی که واقعا می‌خواهی، انتخاب کنی. خویشتن* تو با این سرور مقدس درخشان است، تغییر نیافته، بی‌تغییر و تغییرناپذیر، برای همیشه و همیشه. و آیا می‌خواهی از گوشه کوچکی از ذهنت، میراثش را دریغ کنی، و آن گوشه را میزبان درد نمایی؛ مکانی بیمار که چیزهای زنده باید سرانجام برای مردن به آنجا بیایند؟

ممکن است به نظر بیاید که این دنیا موجب درد تو می‌شود. و اما این دنیا، که بی‌علت است، هیچ قدرتی برای علت شدن ندارد. به عنوان یک معلول، نمی‌تواند معلول بسازد. به عنوان یک وهم، این همان است که تو می‌خواهی. آرزوهای بیهوده تو در دردهایش متجلی می‌شود. خواسته‌های عجیب تو برایش رؤیاهای شرورانه ایجاد می‌کنند. پندارهای تو در مورد مرگ آن را در ترس می‌پیچند، اما در بخشایش مهربانانه تو، دنیا زندگی می‌کند.

درد پندار شر است که شکل می‌گیرد، و در ذهن مقدس تو خرابکاری می‌کند. درد باجی است که تو با رضایت پرداخته‌ای تا آزاد نباشی. در درد فرزند* محبوب خداوند* از وی* دریغ می‌شود. در درد، به نظر می‌رسد که ترس بر عشق پیروز می‌شود، و زمان جایگزین ابدیت و بهشت* می‌گردد. و این دنیا به یک مکان بی‌رحمانه و تلخ تبدیل می‌شود، که اندوه بر آن فرمان می‌راند و شادمانی‌های کوچک از بین می‌روند پیش از آنکه طوفان درد خشونت‌آمیزی که در انتظار است همه شادمانی‌ها را در فلاکت به پایان برساند.

سلاح‌های خود را زمین بگذار، و بدون دفاع به مکان ساکتی وارد شو که صلح بهشت* سرانجام همه چیزها را ساکن می‌کند. همه پندارهای خطر و ترس را کنار بگذار. اجازه نده هیچ حمله‌ای همراه با تو وارد شود. شمشیر بی‌رحم قضاوت را بر زمین بگذار که روی گلویت گذاشته‌ای، و حمله‌های ویرانگری را که از طریق آنها می‌کوشی قداست خود را پنهان کنی، کنار بگذار.

در اینجا تو خواهی فهمید که دردی وجود ندارد. در اینجا سرور خداوند* متعلق به تو است. امروز همان روز است که به تو ارزانی شده آن درس را بشناسی که همه قدرت رستگاری را در خود دارد. آن درس این است؛ درد وهم است؛ سرور، واقعیت است. درد فقط خواب است؛ سرور، بیداری است. درد فریب است؛ تنها سرور حقیقت است.

از این رو ما دوباره امروز تنها انتخابی را انجام می‌دهیم که هرگز می‌توان داشت؛ ما بین اوهام و حقیقت انتخاب می‌کنیم، یا بین درد و سرور، یا دوزخ و بهشت*. باشد تا سپاسگزاری ما از آموزگارمان قلب‌هایمان را آکنده سازد، در حالی که آزاد هستیم تا سرور خود را به جای درد انتخاب کنیم، قداست خود را به جای گناه، صلح خداوند* را به جای تعارض، و نور بهشت* را به جای تاریکی این دنیا.', 'https://acim-farsi.org/workbook/lesson/190', 'https://acim-farsi.org/audio/workbook/lesson/190.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (191, 'من فرزند* مقدس خود* خداوند* هستم.', 'من فرزند* مقدس خود* خداوند* هستم. من نمی‌توانم رنج بکشم، نمی‌توانم در درد باشم، من نمی‌توانم از فقدان رنج بکشم، و نمی‌توانم در انجام تمامی آنچه رستگاری نیازمند آن است شکست بخورم.
من نمی‌توانم رنج بکشم، نمی‌توانم در درد باشم، من نمی‌توانم از فقدان رنج بکشم، و نمی‌توانم در انجام تمامی آنچه رستگاری نیازمند آن است شکست بخورم.
من نمی‌توانم رنج بکشم، نمی‌توانم در درد باشم، من نمی‌توانم از فقدان رنج بکشم، و نمی‌توانم در انجام تمامی آنچه رستگاری نیازمند آن است شکست بخورم.', 'من فرزند* مقدس خود* خداوند* هستم.

در اینجا اعلام رهایی تو از اسارت دنیا قرار دارد. و در اینجا همچنین همۀ دنیا آزاد می‌گردد. تو نمی‌بینی که با دادن نقش زندانبان فرزند* خداوند* به این دنیا، چه کرده‌ای. این دنیا چه می‌تواند باشد به جز خبیث و هراسان، ترسان از سایه‌ها، تنبیه‌گر و وحشی، فاقد عقل، نابینا، دیوانه از نفرت؟

تو چه کرده‌ای که این باید دنیای تو باشد؟ تو چه کرده‌ای که این چیزی است که می‌بینی؟ هویت* خود را نادیده بگیر، و آنچه باقی می‌ماند همین است. تو به آشوب نظر می‌کنی و آن را خودت می‌دانی. هیچ منظری نیست که چنین گواهی را به تو ندهد. هیچ صدایی نیست که از شکنندگی درون و برون تو سخن نگوید؛ هیچ نفَسی نیست که با کشیدن آن به نظر نرسد تو به مرگ نزدیکتر می‌شوی؛ هیچ امیدی نیست که تو بتوانی آن را حفظ کنی و در اشک‌ها نابود نگردد.

هویت* خود را انکار کن و آنگاه از دیوانگی این پندار عجیب و غریب غیرطبیعی و خیالی فرار نخواهی کرد که آفرینش را به سُخره می‌گیرد و به خداوند* می‌خندد. هویت* خود را انکار کن و تو به تنهایی به جهان حمله خواهی برد بدون یک دوست، ذرۀ کوچکی از غبار بر علیه فوجهای دشمنانت. هویت* خود را نادیده بگیر و آنگاه به شرارت، گناه و مرگ نگاه می‌کنی و مشاهده می‌کنی که ناامیدی هر ذرۀ امید را از انگشتانت می‌شوید در حالیکه هیچ چیز جز آرزوی مرگ را برایت باقی نمی‌گذارد .

اما این چیست جز یک بازی که تو به آن می‌پردازی و در این بازی می‌توان هویت* خود را انکار کرد؟ تو آنگونه هستی که خداوندت* آفرید. باور کردن هر چیز دیگری به جز این یک چیز خطا است. در همین یک اندیشه همگان آزاد می‌شوند. در همین یک حقیقت همۀ اوهام برطرف می‌گردند . در همین یک واقعیت، بی‌گناهی برای همیشه بخشی از همه چیز اعلام می‌گردد، هستۀ مرکزی موجودیت آن‌ و تضمین نامیرایی آن.

فقط اجازه بده ایدهٔ امروز جایی در میان افکارت بیابد و آنگاه بسیار بالاتر از این دنیا اوج می‌گیری، و همۀ پندارهای دنیوی، که این دنیا را زندانی می‌کنند. و از این مکان امن و گریز، تو برخواهی گشت و این دنیا را آزاد خواهی کرد. زیرا آن کس که می‌تواند هویت* حقیقی خود را بپذیرد حقیقتأ نجات می‌یابد. و رستگاری او موهبتی است که به همگان ارزانی می‌کند، در سپاسگزاری از او* که* مسیر خروج به سمت شادمانی را نشان داد، شادمانی که تمامی دیدگاه وی را از دنیا دگرگون کرد.

یک اندیشهٔ مقدس مانند این و آنگاه تو آزاد هستی: تو فرزند* مقدس خود* خداوند* هستی. و با این اندیشه مقدس تو همچنین می‌آموزی که این دنیا را آزاد کرده‌ای. تو نیازی نداری که از آن با بی‌رحمی استفاده کنی، و سپس نیاز به خشونت را در آن ادراک نمائی. تو آن را از زندانی که برایش ساخته‌ای آزاد می‌کنی. تو تصویری ویرانگر از خودت را نخواهی دید در حالیکه با وحشت در این دنیا گام بر می‌دارد، در حالیکه به همراه این تصویر دنیا در رنج به خود می‌پیچد زیرا ترس‌های تو مُهر مرگ را بر قلبش زده است.

امروز شادمان باش که چقدر آسان دوزخ فرو می‌پاشد. تنها نیاز داری به خودت بگوئی: من فرزند* مقدس خود* خداوند* هستم. من نمی‌توانم رنج بکشم، نمی‌توانم در درد باشم، من نمی‌توانم از فقدان رنج بکشم، و نمی‌توانم در انجام تمامی آنچه رستگاری نیازمند آن است شکست بخورم. و در این اندیشه تمامی چیزهایی که تو می‌بینی کاملا تغییر می‌کنند.

معجزه‌ای تمامی حفره‌های تاریک و قدیمی را روشن کرده است، مکانهایی که از آغاز زمان، مرگ در آنها طنین‌انداز بوده است. زیرا زمان بند خود را از این دنیا برداشته است. فرزند* خداوند* در شکوه آمده است تا گمشدگان را آزاد کند، تا بینوایان را نجات دهد، و موهبت بخشایش خود را به این دنیا ارزانی دارد. چه کسی می‌تواند این دنیا را چنین تاریک و گناه‌آلود ببیند، در حالیکه فرزند* خداوند* سرانجام باز آمده است تا آن را آزاد کند؟

تو که خودت را ضعیف و شکننده، با امیدهای عبث و رؤیاهای ویران شده، زاده شده تنها برای مردن، گریستن و درد کشیدن ادراک می‌کنی، این را بشنو: همۀ قدرت در زمین و بهشت* به تو داده شده است. هیچ کاری نیست که تو نتوانی انجام دهی. تو بازی مرگ را بازی می‌کنی، بازی بیچارگی، به طرز رقت‌آمیزی گره‌خورده به فروپاشی در دنیایی که هیچ شفقتی به تو نشان نمی‌دهد. اما زمانی که تو شفقت را با آن همراه کنی، شفقت آن بر تو خواهد تابید.

پس بگذار فرزند* خداوند* از خوابش برخیزد، و در حالیکه چشمان مقدسش را می‌گشاید، بار دیگر بازگردد تا دنیایی را که ساخته متبرک کند. دنیا در خطا آغاز شد، اما در بازتاب قداست او به پایان خواهد رسید. و او دیگر بیش از این نخواهد خفت و رؤیای مرگ نخواهد دید. پس امروز به من بپیوند. شکوه تو آن نور است که دنیا را نجات می‌دهد. بیش از این رستگاری را دریغ نکن. به پیرامون این دنیا بنگر، و رنج‌های آن را ببین. آیا قلبت مایل نیست که به برادران خسته‌ات آسایش بخشد؟

آن‌ها باید منتظر رهایی خود تو باشند. آنان در زنجیرها باقی می‌مانند تا زمانی که تو آزاد گردی. آنان نمی‌توانند شفقت این دنیا را ببینند تا زمانی که تو آن را در خودت نیافته باشی. آن‌ها رنج می‌کشند تا زمانی که تو بند آن را از خود برداری. آنان می‌میرند تا زمانی که تو حیات ابدی خود را بپذیری. تو فرزند* مقدس خود* خداوند* هستی. این را به یاد بسپار، و همه‌ی دنیا آزاد می‌شود. این را به یاد بسپار، و زمین و بهشت* یگانه می‌شوند.', 'https://acim-farsi.org/workbook/lesson/191', 'https://acim-farsi.org/audio/workbook/lesson/191.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (192, 'من وظیفه‌ای دارم که خداوند* می‌خواهد به انجام برسانم.', 'من وظیفه‌ای دارم که خداوند* می‌خواهد به انجام برسانم.', 'من وظیفه‌ای دارم که خداوند* می‌خواهد به انجام برسانم.

این ارادۀ* مقدس پدرت* است که تو خودش* را تکمیل کنی، و اینکه خویشتن* تو باید فرزند* مقدس او* باشد، برای همیشه خالص همچون او*، آفریده شده از عشق و محافظت شده در عشق، در حالیکه عشق را می‌گستراند و به نام عشق می‌آفریند، برای همیشه یگانه با خداوند* و با خویشتن* تو. اما چنین وظیفه‌ای چه معنایی می‌تواند داشته باشد دردنیایی از حسرت، نفرت و حمله.

بنابراین، تو دارای یک وظیفه در این دنیا بر حسب درونیات آن هستی. زیرا چه کسی می‌تواند زبانی را بفهمد که از درک ساده‌اش بسیار فراتر باشد؟ بخشایش تجلی وظیفهٔ تو در اینجا است. بخشایش آفریدهٔ خداوند* نیست زیرا صرفا وظیفه‌ای است که توسط آن می‌توان غیرحقیقی را فرو ریخت. و چه کسی می‌تواند بهشت* را ببخشد؟ اما در زمین تو نیاز به وسیله‌ای داری که اجازه‌ی برطرف شدن اوهام را بدهد. آفرینش صرفاً در انتظار بازگشت تو است تا تصدیق شود، نه برای این که کامل شود.

آفرینش حتی نمی‌تواند در این دنیا ادراک گردد. آفرینش در اینجا هیچ معنایی ندارد. بخشایش نزدیکترین مسیر آمدن آن به زمین است. زیرا زادهٔ بهشت* است، و اصلا هیچ شکلی ندارد. اما خداوند* آن یگانه* را آفرید که* قدرت ترجمه کردن بی‌شکل تام را به شکل دارد. آنچه که او* می‌سازد رؤیا است اما از نوعی چنان نزدیک به بیداری که نور روز نیز در آن‌ها می‌تابد، و چشمان در حال باز شدن، مناظر سرور‌آمیزی را می‌بیند که موهبت ارزانی شده توسط آن‌ها در خود دارد.

بخشایش مهربانانه به همههٔ چیزهایی نظر می‌کند که در بهشت* ناشناخته هستند، می‌بیند که آنها ناپدید می‌شوند، و دنیا تبدیل به لوحی پاک و بدون نشان می‌گردد که اینک بر روی آن کلام* خداوند* می‌تواند جایگزین نمادهای بی‌معنایی شود که قبلا نوشته شده بود. بخشایش وسیله‌ای است که توسط آن بر ترس از مرگ غلبه می‌شود، زیرا دیگر مرگ هیچ جذابیت درنده‌خویانه‌ای ندارد و احساس گناه بر طرف شده است. بخشایش اجازه می‌دهد که بدن آنگونه که هست ادراک گردد؛ یک ابزار کمک آموزشی ساده، که با تکمیل آموختن کنار گذاشته می‌شود، اما به سختی کسی را که اصلا چیزی را می‌آموزد تغییر می‌دهد.

ذهن بدون بدن نمی‌تواند اشتباه کند. نمی‌تواند بپندارد که خواهد مرد، و نیز نمی‌تواند بپندارد که طعمۀ حمله بی‌رحمانه باشد. خشم ناممکن می‌شود، و آنگاه وحشت کجا می‌تواند باشد؟ کدام ترس‌ها می‌توانند باز بر آنان که سرچشمهٔ تمامی حمله‌ها را گم کرده‌اند هجوم آورند؟ بر آنان که هستۀ نگرانی و مکان ترس را از دست داده‌اند؟ فقط بخشایش می‌تواند ذهن را از این پندار که بدن منزل آن است تسکین دهد. فقط بخشایش می‌تواند آن صلح را بازسازی کند که خداوند* برای فرزند* مقدسش قصد کرد. فقط بخشایش می‌تواند این فرزند* را ترغیب کند که دوباره به قداست خویش* نظر بیفکند.

با برطرف شدن خشم، تو حقیقتأ ادراک خواهی کرد که برای رؤیت مسیحایی* و موهبت دیدن، هیچ قربانی درخواست نشد، و فقط درد از یک ذهن بیمار و آسیب دیده برداشته شد. آیا این ناخوشایند است؟ آیا باید از این ترسید؟ یا باید آرزویش را داشت، از آن با سپاس استقبال کرد و آن را شادمانه پذیرفت؟ ما با هم یگانه هستیم ، و بنابراین هیچ چیز را رها نمی‌کنیم. اما حقیقتأ همه چیز توسط خداوند* به ما داده شده است.

با این حال ما نیاز به بخشایش داریم تا درک کنیم که چنین است. بدون نور مهربان آن ما در تاریکی کورمال می‌رویم، و از عقلمان فقط برای توجیه خشم و حمله استفاده می‌کنیم. فهم ما چنان محدود است که آنچه می‌پنداریم می‌فهمیم، فقط سردرگمی است که از خطا ناشی می‌شود. ما در مه غلیظ رؤیاهای متغیر و پندارهای ترسناک گم شده‌ایم، چشمان ما محکم در مقابل نور بسته‌اند، ذهن‌های ما درگیر پرستش چیزی هستند که وجود ندارد.

چه کسی می‌تواند دوباره در مسیحا* متولد شود جز او که همۀ آن‌هایی را که می‌بیند یا می‌پندارد یا تصور می‌کند را بخشیده است؟ چه کسی می‌تواند آزاد گردد در حالی که دیگری را زندانی می‌کند؟ یک زندانبان آزاد نیست، زیرا به همراه زندانی خود در بند است. او باید مطمئن شود که زندانی نمی‌گریزد، پس زمانش را در نگاهبانی از او سپری می‌کند. میله‌های زندان که او را محبوس می‌کنند به دنیایی تبدیل می‌شوند که زندانبانش در آن زندگی می‌کند، به همراه او. و راه آزادی برای هر دوی آن‌ها وابسته به آزادی او است.

بنابراین، هیچ‌کس را زندانی نگه ندار. به جای در بند کردن رهایی بخش، چرا که اینگونه آزاد می‌شوی. این طریق ساده است. هر زمان که نیش خشمی را احساس می‌کنی، بدان که شمشیری را بالای سرت گرفته‌ای. و این شمشیر یا فرو خواهد افتاد یا برداشته می‌شود، بسته به اینکه انتخاب کنی محکوم شوی یا آزاد. در این صورت هر کسی که به نظر می‌رسد تو را به خشمگین بودن وسوسه می‌کند، منجی تو از زندان‌خانهٔ مرگ است. و بنابراین تو به او سپاس بدهکار هستی و نه درد.

امروز شفیق باش. فرزند* خداوند* لیاقت شفقت تو را دارد. اینک اوست که از تو می‌خواهد مسیر به سوی آزادی را بپذیری. نادیده‌اش نگیر. عشق* پدرش* برای او به تو تعلق دارد. وظیفهٔ تو اینجا در زمین فقط این است که او را ببخشی، تا بتوانی او را باز به عنوان هویت خود بپذیری. او آنگونه است که خداوندش* آفرید. و تو چیزی هستی که او هست. اینک گناهانش را به او ببخش، و خواهی دید که با او یگانه هستی.', 'https://acim-farsi.org/workbook/lesson/192', 'https://acim-farsi.org/audio/workbook/lesson/192.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (193, 'همهٔ چیزها، درس‌هایی هستند که خداوند* می‌خواهد من بیاموزم.', 'ببخش، و تو این را متفاوت خواهی دید.

من خواهم بخشید، و این ناپدید خواهد شد.', 'همهٔ چیزها، درس‌هایی هستند که خداوند* می‌خواهد من بیاموزم.

خداوند* چیزی از آموختن نمی‌داند. اما ارادهٔ او به آنچه درک نمی‌کند گسترش می‌یابد، زیرا او اراده می‌کند شادمانی که میراث فرزندش* از او* است، دست نخورده بماند؛ ابدی و برای همیشه در حال افزایش، و تا ابد در سرور همهٔ آفرینش گسترش یابد، و تا ابد در او* مفتوح و کاملاً بدون محدودیت. این ارادهٔ* او* است. و در این صورت ارادهٔ* او* وسیله‌ای را فراهم می‌آورد برای تضمین به انجام رسیدن آن.

خداوند* هیچ تعارضی را نمی‌بیند. اما فرزند* او* باور دارد که تعارض‌ها را می‌بیند. بنابراین او نیاز به کسی* دارد که بتواند نگاه نادرستش را تصحیح کند، و به او رؤیتی عطا کند که او را به آنجا هدایت خواهد کرد که ادراک منتفی می‌گردد. خداوند* به هیچ وجه ادراک نمی‌کند. اما او* همان وجودی است که* ابزاری را ارزانی می‌کند که توسط آن ادراک حقیقی می‌شود و به اندازه کافی زیبا می‌گردد تا به نور بهشت* اجازه دهد که بر آن بتابد. او* همان وجود است که به آنچه فرزندش* می‌خواهد با آن ضدیت کند پاسخ می‌گوید، و بی‌گناهی او را برای همیشه ایمن می‌دارد.

این‌ها درس‌هایی هستند که خداوند* می‌خواهد تو بیاموزی. ارادهٔ* او* تمامی آن‌ها را بازتاب می‌دهد، و آن‌ها درس‌ها محبت عاشقانهٔ او* را به فرزند* محبوبش بازتاب می‌دهند. هر درس یک اندیشه محوری دارد، که در تمامی آن‌ها یکسان است. فقط شکل درس عوض می‌شود، با شرایط و رویدادهای مختلف؛ با شخصیت‌ها و موضوعات مختلف، که ظاهری هستند اما واقعی نیستند. آن‌ها در محتوای بنیادین با هم یکی هستند. آن محتوا چنین است: ببخش، و تو این را متفاوت خواهی دید.

قطعی است که به نظر نمی‌رسد که همه پریشانی‌ها فقط عدم بخشایش است. اما این محتوای نهفته در زیر شکل است. همین یکسانی آموختن را قطعی می‌سازد، زیرا این درس چنان ساده است که در پایان نمی‌توان آن را رد کرد. هیچکس نمی‌تواند از حقیقتی چنین آشکار که در شکل‌های بی‌شمار ظاهر می‌شود پنهان گردد، اما همین حقیقت به آسانی در همه این شکل‌ها قابل شناسایی است، اگر فقط کسی بخواهد این درس ساده را در اینجا ببیند.

ببخش، و تو این را متفاوت خواهی دید. اینها کلماتی هستند که روح‌القدس* در تمامی محنت‌هایت با تو می‌گوید، تمامی دردهایت، تمامی رنج‌هایت فارغ از شکلی که به خود می‌گیرند. این‌ها کلماتی هستند که وسوسه با آن‌ها پایان می‌یابد، و احساس گناه، رها می‌شود، دیگر بر نمی‌گردد. اینها کلماتی هستند که به رؤیای گناه پایان می‌دهند، و ذهن را از ترس خلاص می‌کنند. اینها کلماتی هستند که توسط آنها رستگاری به همهٔ دنیا می‌آید.

آیا نباید گفتن این کلمات را بیاموزیم زمانی که وسوسه می‌شویم باور کنیم درد واقعی است، و زمانی که مرگ را به جای زندگی انتخاب می‌کنیم؟ آیا نباید بیاموزیم این کلمات را بگوییم زمانی که قدرت آنها را در آزاد کردن همه اذهان از اسارت می‌فهمیم؟ اینها کلماتی هستند که به تو فراتر از همه رویداهایی که به نظر می‌رسد بر تو غالب هستند، قدرت می‌دهند. تو این کلمات را به درستی می‌بینی زمانی که آن‌ها را در آگاهی کامل نگه داری، و ازیاد نبری که این کلمات برای همه چیزهایی که می‌بینی یا هر برادری که اشتباه می‌کند مصداق دارند.

چگونه می‌توانی بگویی که در حال دیدن به نادرستی هستی، یا کس دیگری نمی‌تواند درسی را که باید بیاموزد درک کند؟ آیا درد در این ادراک به نظر واقعی می‌رسد؟ اگر چنین باشد، مطمئن باش که این درس آموخته نشده است. و عدم بخشایش باقی مانده است، پنهان شده در آن ذهن که درد را از طریق چشمانی که هدایت می‌کند می‌بیند.

خداوند* مقرر نکرد که تو این‌چنین رنج بکشی. او می‌خواهد به تو کمک کند تا خودت را ببخشی. فرزند* او* به یاد نمی‌آورد که کیست. و خداوند* می‌خواهد که او عشقش* را فراموش نکند، و همه موهبت‌هایی را که عشق* او* ارزانی‌اش می‌دارد. آیا تو می‌خواهی اکنون رستگاری خودت را انکار کنی؟ آیا می‌خواهی در آموختن درس‌های ساده‌ای که آموزگار* بهشت* پیش رویت می‌گذارد شکست بخوری، درس‌هایی که داده می‌شوند تا تمامی درد بتواند محو گردد و خداوند* بتواند توسط فرزندش* به یاد آورده شود؟

همه چیزها درس‌هایی هستند که خداوند* می‌خواهد تو بیاموزی. او نمی‌خواهد حتی یک اندیشه عاری از بخشایش تصحیح نشده باقی بماند، و نمی‌خواهد هیچ خار یا میخی به هیچ شکلی فرزند* مقدسش* را آزار دهد. او می‌خواهد مطمئن شود که آرامش مقدس این فرزند* بی‌خدشه و بدون آسیب باقی می‌ماند، بدون هیچ مراقبتی، در منزلی ابدی که از او مراقبت می‌کند. و خداوند* می‌خواهد همه اشک‌ها پاک شوند، بدون اینکه هیچ اشک نریخته‌ای باقی بماند، و هیچ اشکی در انتظار زمان ریزش باشد. زیرا خداوند* اراده کرده است که خنده باید جای هر اشک را بگیرد، و فرزندش* باید دوباره آزاد باشد.

امروز تلاش خواهیم کرد به هزار مانع ظاهری در مسیر صلح فقط در یک روز فائق شویم. بگذار شفقت با سرعت بیشتری به سوی تو بیاید. تلاش نکن حتی یک روز دیگر جلوی آن را بگیری، حتی یک دقیقه یا حتی یک لحظه دیگر. زمان برای این ساخته شد. امروز از زمان به قصدی که ساخته شد استفاده کن. صبح و شب، هر زمانی را که می‌توانی اختصاص بده تا به هدف مناسبش خدمت کند، و اجازه نده این زمان کمتر از آن باشد که ژرف‌ترین نیازت را برآورده کند.

همه تلاشت را بکار ببر، و کمی بیشتر تلاش کن. زیرا اینک ما می‌خواهیم با شتاب برخیزیم و به سمت منزل پدرمان* برویم. ما زمانی بسیار طولانی است که رفته‌ایم، و نمی‌خواهیم دیگر در اینجا درنگ کنیم. و با تمرین کردن، بگذار درباره همه چیزهایی که توسط خود ما حفظ شده‌اند تا مانع ما شوند و از شفا دورمان کنند، بیندیشیم. بگذار همه آن‌ها را به او بدهیم که می‌داند چگونه باید نگاهشان کرد تا ناپدید گردند. پیام او حقیقت است؛ آموزش او حقیقت است. درس‌های او*، درس‌هایی هستند که خداوند* می‌خواهد ما بیاموزیم.

امروز هر ساعت زمان کمی را صرف کن، و همچنین در روزهای بعدی، برای تمرین کردن درس بخشایش به آن شکلی که برای امروز تعیین شده است. و سعی کن آن را برای رویداهایی که در ساعت بعدی پیش می‌آیند بکار ببری، چنانکه رویدادهای هر ساعت از ساعت قبل رها باشند. زنجیرهای زمان به سادگی از این طریق سست می‌شوند. اجازه نده هیچ ساعتی سایه خود را بر ساعت بعدی بیاندازد، و زمانی که آن ساعت سپری شد، اجازه بده همه چیزهایی که در آن مدت رخ دادند با آن بروند. این‌چنین تو رها باقی خواهی ماند، در صلح ابدی در دنیای زمان.

این همان درس است که خداوند* می‌خواهد تو بیاموزی: برای نگاه کردن به همه چیزها راهی وجود دارد که اجازه می‌دهد آن چیز برای تو گامی دیگر به سمت او باشد، و به سمت رستگاری این دنیا. به هر چه که از وحشت سخن می‌گوید، چنین پاسخ بده: من خواهم بخشید، و این ناپدید خواهد شد. برای هر نگرانی، هر دلواپسی و هر شکل از رنج همین کلمات را با خود تکرار کن. و آنگاه کلیدی را در دست داری که دروازهٔ بهشت* را می‌گشاید، و سرانجام عشق خداوندِ* پدر* را به روی زمین می‌آورد، تا آن را تا بهشت* برافرازد. خداوند* این گام نهایی را خودش برخواهد داشت. گام‌های کوچکی را که او می‌خواهد بسویش برداری، دریغ نکن.', 'https://acim-farsi.org/workbook/lesson/193', 'https://acim-farsi.org/audio/workbook/lesson/193.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (194, 'من آینده را در دستان* خداوند* قرار می‌دهم.', 'من آینده را در دستان* خداوند* قرار می‌دهم.', 'من آینده را در دستان* خداوند* قرار می‌دهم.

ایده امروز گام دیگری به سوی رستگاری سریع برمی‌دارد، و این حقیقتا گامی غول‌آسا است. فاصله‌ای که این گام پر می‌کند بسیار عظیم است، این گام تو را دقیقا در نزدیکی بهشت* قرار می‌دهد، در حالیکه هدف در دید است و موانع پشت سر گذاشته شده‌اند. پای تو به چمنزاری رسیده است که از تو در دروازهٔ بهشت* استقبال می‌کند، مکان آرام صلح، جایی که تو با اطمینان منتظر گام نهایی خداوند* می‌شوی. اینک ما از زمین چقدر پیش آمده و دور شده‌ایم! ما چقدر به هدفمان نزدیک هستیم! چقدر سفری که هنوز باید پی بگیریم کوتاه است!

ایده امروز را بپذیر، و تو از همهٔ اضطراب‌ها عبور کرده‌ای، همهٔ چاله‌های دوزخ، همه تاریکی غم، پندارهای گناه، و ویرانگی‌ای که احساس گناه ایجاد می‌کند. ایدهٔ امروز را بپذیر، و تو این دنیا را از همهٔ اسارتش آزاد کرده‌ای، با سست کردن زنجیرهای سنگینی که درب آزادی را به رویش قفل کردند. تو نجات می‌یابی، و رستگاری تو این چنین به موهبتی تبدیل می‌شود که به دنیا ارزانی می‌کنی، زیرا تو آن را دریافت کرده‌ای.

در هیچ لحظه‌ای افسردگی احساس نمی‌شود، یا درد تجربه نمی‌گردد یا فقدان ادراک نمی‌شود. در هیچ لحظه‌ای اندوه نمی‌تواند بر تخت بنشیند، و با ایمان پرستش گردد. در هیچ لحظه‌ای کسی حتی نمی‌تواند بمیرد. و از این رو هر لحظه‌ای که گذر آن به خداوند* تقدیم شود، در حالی که لحظه بعد نیز به او تقدیم شده است، زمانی است برای آزادی تو از غم، درد و حتی خود مرگ.

خداوند* آیندهٔ تو را همانگونه نگه می‌دارد که گذشته و حالت را. این‌ها برای او* یکی هستند، پس باید برای تو یکی باشند. اما در این دنیا، پیشرفت زمانی هنوز واقعی به نظر می‌رسد. بنابراین از تو خواسته نمی‌شود فقدان توالی را که واقعا در زمان یافت می‌شود، بفهمی. از تو فقط خواسته می‌شود آینده را رها کنی، و آن را در دستان خداوند* قرار دهی. و تو با تجربه خود خواهی دید که گذشته و حال را نیز در دستان او* قرار داده‌ای، زیرا گذشته تو را مجازات نخواهد کرد، و هراس از آینده دیگر بی‌معنا خواهد شد.

آینده را رها کن. زیرا گذشته رفته است، و آنچه حاضر است، آزاد شده از میراث غم و فلاکت، میراث درد و فقدان، به آن لحظه تبدیل می‌شود که زمان از اسارت اوهام می‌گریزد، اوهامی که مسیر بی‌رحمانه و گریز‌ناپذیر خود را در آن می‌گذراند. سپس هر لحظه که بردهٔ زمان بود، به یک لحظهٔ مقدس تبدیل می‌شود، زمانی که آن نور که در فرزند* خداوند* مخفی نگه داشته شد، آزاد می‌شود، تا این دنیا را متبرک کند. اینک او آزاد است، و همه شکوه او به دنیایی می‌تابد که با او آزاد شده است، تا در قداستش شریک گردد.

اگر بتوانی درس امروز را به عنوان موهبتی که واقعا هست ببینی، تو در صرف تلاش مصرانه بسیار زیاد تا آن حد که می‌توانی برای آن درنگ نخواهی کرد، تا آن را به بخشی از خود تبدیل کنی. تا به اندیشه‌ای تبدیل شود که بر ذهنت فرمان می‌راند، عادتی در مجموعه‌ی ابزارهای تو برای حل کردن مسئله، شیوه‌ای برای واکنش سریع به وسوسه، تو آموختهٔ خود را به این دنیا گسترش می‌دهی. و با آموختن اینکه رستگاری را در همهٔ چیزها ببینی، این دنیا درک خواهد کرد که نجات یافته است.

کدام نگرانی می‌تواند به آن کس که آینده‌اش را به دستان* عاشق خداوند* می‌سپارد حمله‌ور شود؟ او از چه چیزی می‌تواند رنج ببرد؟ چه چیزی می‌تواند موجب درد او شود، یا تجربه فقدان را برایش پدید آورد؟ او از چه چیزی می‌تواند بترسد؟ و به چه چیز می‌تواند بنگرد مگر با نگاه عشق؟ زیرا آنکس که از همه‌ی هراس درد آینده گریخته، طریقش را به سوی صلحِ اکنون یافته است، و به مراقبتی اطمینان دارد، که این دنیا هرگز نمی‌تواند آن را تهدید کند. او مطمئن است که ادراکش شاید خطا باشد، اما هرگز فاقد تصحیح نخواهد بود. زمانی که فریب می‌خورد، او آزاد است که دوباره انتخاب کند؛ زمانی که خطا می‌کند او آزاد است که ذهنش را تغییر دهد.

پس آیندهٔ خود را در دستان* خداوند* قرار بده. زیرا اینچنین تو یاد او* را فرا می‌خوانی تا باز گردد، و همهٔ پندارهای گناه و شرارت را با حقیقت عشق جایگزین سازد. آیا می‌پنداری که دنیا نمی‌تواند از این طریق سود ببرد، و آیا هر مخلوق زنده به این اندیشه با ادراک شفا یافته پاسخ نخواهد داد؟ آن‌کس که خود را به خداوند* می‌سپارد همچنین این دنیا را در دستانی* قرار می‌دهد که خودش برای آسایش و امنیت آن را می‌طلبد. او اوهام بیمار این دنیا را به همراه اوهام خودش رها می‌کند، و صلح را به هر دو ارزانی می‌دارد.

حال حقیقتا ما نجات می‌یابیم. زیرا در دستان* خداوند*، بی‌‌مشکل و بی‌نگرانی آرامش می‌یابیم، مطمئن از اینکه تنها خیر می‌تواند به سوی ما بیاید. اگر فراموش کنیم با مهربانی به ما اطمینان داده خواهد شد. اگر ما یک پندار عاری از بخشایش را بپذیریم، به زودی با بازتاب عشق جایگزین خواهد شد. و اگر ما به حمله وسوسه شویم، به او* توکل خواهیم کرد که از آرامش ما نگهبانی می‌کند تا انتخابی را برای ما میسر سازد که وسوسه را بسیار پشت سر می‌گذارد. دیگر این دنیا دشمن ما نیست، زیرا ما انتخاب کرده‌ایم که دوست آن باشیم.', 'https://acim-farsi.org/workbook/lesson/194', 'https://acim-farsi.org/audio/workbook/lesson/194.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (195, 'عشق آن راه است که من در سپاسگزاری می‌پیمایم.', 'عشق آن راه است که من در سپاسگزاری می‌پیمایم.', 'عشق آن راه است که من در سپاسگزاری می‌پیمایم.

سپاسگزاری درسی است که یادگیری آن برای آنان که به دنیا نگاهی اشتباه دارند، دشوار است. بیشترین کاری که آنان می‌توانند انجام دهند، دیدن خودشان بهتر از دیگران است. و سپس برای راضی بودن تلاش می‌کنند، زیرا به نظر می رسد دیگری بیشتر از آنان رنج می‌برد. چقدر چنین افکاری رقت‌انگیز و تحقیرآمیز هستند! زیرا چه کسی می‌تواند علتی برای تشکر داشته باشد در حالی که دیگری علت کمتری را دارد؟ و چه کسی می‌تواند کمتر رنج بکشد زیرا می‌بیند دیگری بیشتر رنج می‌کشد؟ سپاسگزاری تو فقط مربوط به او* می‌شود که همه‌ی دلایل محو شدن غصه از سراسر دنیا را ساخت.

دیوانگی است اگر به دلیل رنج شکرگزاری کنیم. اما به همین اندازه سپاسگزاری نکردن از او* که وسایل خاصی را به تو ارزانی می‌دارد که از طریق آنها تمامی درد شفا یابد، و رنج با خنده و شادمانی جایگزین گردد، دیوانه‌وار است. حتی کسی که ذره‌ای عقل داشته باشد نمی‌تواند از گام برداشتن در مسیری که او* هدایت می‌کند، سر باز زند، و مسیری را که او* پیش رویش می‌گذارد دنبال نکند، و از زندانی که می‌اندیشید هیچ دری به سوی آزادی در آن نیست و اینک آن را تشخیص می‌دهد، فرار نکند.

برادر تو می‌تواند «دشمن» تو باشد زیرا در او هماورد صلح خود را می‌بینی؛ تاراج‌گری که شادمانی را از تو می‌رباید و برای تو هیچ چیزی باقی نمی‌گذارد به جز یک ناامیدی تاریک که آنچنان تلخ و آنچنان بی‌رحمانه است که در آن هیچ امیدی باقی نمی‌ماند. در این حال تنها چیزی که آرزویش وجود دارد انتقام است. در این حال تو فقط می‌توانی تلاش کنی او را پایین بیاوری تا در مرگ کنار تو قرار گیرد، به اندازه‌ی خودت بی‌فایده؛ آنچنان که انگشتان غارتگرش مانند انگشتان تو تهی گردند.

تو به این دلیل که برادرت از تو برده‌تر است سپاسگزاری را نثار خداوند* نمی‌کنی، و هم‌چنین نمی‌توانی عاقلانه خشمگین شوی اگر او آزادتر به نظر می‌رسد. عشق* هیچ مقایسه‌ای انجام نمی‌دهد. و سپاسگزاری تنها زمانی می‌تواند خالص باشد که به عشق متصل گردد. ما سپاس خود را نثار خداوند* پدرمان* می‌کنیم تا همه‌ی چیزها بتوانند آزادی‌شان را در ما بیابند. هرگز چنین نخواهد بود که برخی آزاد شوند در حالی که برخی دیگر هنوز اسیر هستند. زیرا چه کسی می‌تواند به نام خداوند* داد و ستد کند؟

پس سپاسگزاری کن، اما در خلوص. و اجازه بده سپاسگزاری تو برای همهٔ آنان که همراهت خواهند گریخت جا باز کند؛ بیماران، ضعفا، نیازمندان و آنان که می‌ترسند، و آنان که برای یک فقدان ظاهری سوگواری می‌کنند یا ظاهرا دردی را احساس می‌کنند، آنان که از سرما یا گرسنگی رنج می‌برند، یا آنان که مسیر نفرت و راه مرگ را می‌پیمایند. همه‌ی این‌ها با تو خواهند آمد. بگذارید خودمان را با آنان مقایسه نکنیم، زیرا در این صورت آن‌ها را از آگاهی یگانگی‌ای که با ایشان داریم جدا می‌کنیم، آن آگاهی که آنان نیز با ما سهیم هستند.

ما از پدرمان* فقط به خاطر یک چیز سپاسگزاری می‌کنیم؛ این که ما از هیچ چیز زنده‌ای جدا نیستیم، و از این رو با او* یگانه هستیم. و ما این را جشن می‌گیریم که هیچ استثنایی هرگز نمی‌تواند گذاشته شود که بخواهد تمام بودن ما را کاهش دهد، یا وظیفهٔ ما را برای کامل کردن آن یگانه* که خودش کمال است، مختل کرده یا کاهش دهد. ما برای همهٔ چیزهای زنده سپاسگزاری می‌کنیم، زیرا در غیر این صورت سپاسگزار هیچ چیز نیستیم، و نخواهیم توانست موهبت‌های خداوند* برای خودمان را تشخیص دهیم.

پس بگذاریم برادرانمان سرهای خسته‌ی خود را بر شانه‌های ما بگذارند تا لختی بیاسایند. ما از بابت آنان سپاسگزاری می‌کنیم. زیرا اگر ما بتوانیم آنان را به صلحی که می‌خواهیم بیابیم راهنمایی کنیم، سرانجام راه برای خودمان گشوده می‌شود. یک در باستانی دوباره آزادانه در حال باز شدن است؛ یک کلام* که مدت‌ها فراموش شده، در خاطرهٔ ما باز در حال پژواک است، و با خواست دوبارهٔ ما برای شنیدن، واضح تر می‌گردد.

پس، در سپاسگزاری طریق عشق را بپیما. زیرا نفرت فراموش می‌شود زمانی که ما مقایسه‌ها را کنار می‌گذاریم. دیگر چه مانعی برای صلح باقی می‌ماند؟ این زمان ترس از خداوند* فرو می‌ریزد، و ما بدون مقایسه می‌بخشیم. در این صورت نمی‌توانیم گذشت کردن از برخی چیزها را انتخاب کنیم، و با این حال برخی چیزهای دیگر را که هنوز به عنوان «گناهان» محبوس کرده‌ایم، نگه داریم. زمانی که بخشایش تو کامل باشد، تو سپاسگزاری کامل را خواهی داشت، زیرا تو خواهی دید که همه چیز حق عشق ورزیدن را با معشوق بودن کسب کرده است، حتی به عنوان خویشتن* تو.

امروز ما می‌آموزیم به جای خشم، بدخواهی و انتقام، به سپاسگزاری بیندیشیم. همه چیز به ما داده شده است. اگر ما از تشخیص آن سر باز زنیم، این ما را مستحق تلخ کامی نمی‌سازد، و مستحق آن خود‌فریبی که ما را در مکانی می‌بیند که بی‌رحمانه تعقیب می‌شویم، جایی که بی‌وقفه آزار می‌بینیم، و رانده می‌شویم بدون اندیشه‌ای یا مراقبتی برای ما یا برای آیندهٔ ما. سپاسگزاری به اندیشه‌ی یگانه‌ای تبدیل می‌شود که ما جایگزین این ادراکهای دیوانه‌وار می‌کنیم. خداوند مراقب ما بوده است و ما را فرزندش می‌خواند. آیا چیزی بیش از این می‌تواند وجود داشته باشد؟

سپاسگزاری ما راه را به سوی او* صاف خواهد کرد، و زمان فراگیری ما را بیش از آنکه تو بتوانی هرگز تصورش را بکنی کاهش خواهد داد. سپاسگزاری دست در دست با عشق می‌رود، و جایی که یکی از آن‌ها هست، دیگری باید یافت شود. زیرا سپاسگزاری فقط جنبه‌ای از آن عشق* است که سرچشمهٔ* تمام آفرینش است. خداوند* از تو، فرزندش*، تشکر می‌کند، برای آنچه که هستی؛ تکمیل کنندهٔ خود* او* و سرچشمهٔ* عشق، به همراه او*. سپاسگزاری تو برای او* با سپاس او* برای تو یگانه است. زیرا عشق نمی‌تواند هیچ راهی را بپیماید بجز راه سپاسگزاری، و از این طریق ما می‌رویم، ما که راه به سوی خداوند* را می‌پیماییم.', 'https://acim-farsi.org/workbook/lesson/195', 'https://acim-farsi.org/audio/workbook/lesson/195.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (196, 'من فقط می‌توانم خودم را به صلیب بکشم.', 'من فقط می‌توانم خودم را به صلیب بکشم.', 'من فقط می‌توانم خودم را به صلیب بکشم.

وقتی این موضوع را به خوبی بفهمی و در آگاهی کاملت نگه داری، تو تلاش نخواهی کرد به خودت آسیب بزنی، یا بدنت را بردهٔ انتقام سازی. تو به خودت حمله نخواهی کرد، و تشخیص خواهی داد که حمله کردن به دیگری، فقط حمله کردن به خودت است. تو از این باور دیوانه‌وار آزاد خواهی شد که حمله کردن به یک برادر، خودت را نجات می‌دهد. و تو خواهی فهمید که امنیت او، امنیت خود تو است، و با شفای وی تو شفا می‌یابی.

احتمالا ابتدا درک نخواهی کرد که چگونه شفقت، بی‌حد و محافظت کنندهٔ مطمئن تمامی چیزها، می‌تواند در ایده‌ای که امروز تمرین می‌کنیم یافت شود. ممکن است در واقع به نظر برسد ایدهٔ امروز نشانه‌ای است از آنکه هرگز نمی‌توان از عقوبت گریخت، زیرا نفس تحت تسلط چیزی که آن را تهدید می‌بیند، به سرعت به دنبال حقیقتی است تا دروغهایش را نجات دهد. اما از این طریق باید در درک حقیقتی که از آن استفاده می‌کند، شکست بخورد. اما تو می‌توانی بیاموزی که این کارکردهای احمقانه را ببینی، و معنای ظاهری آن‌ها را نادیده بگیری.

از این طریق تو همچنین به ذهنت تعلیم می‌دهی که یک نفس نیستی. زیرا روش‌هایی که نفس می‌خواهد با آن‌ها حقیقت را مغشوش کند، دیگر تو را فریب نخواهند داد. تو باور نخواهی کرد که یک بدن مستحق مصلوب شدن هستی. و در ایده امروز، نور رستاخیز را خواهی دید، و ورای همه‌ی پندارهای مصلوب شدن و مرگ، به اندیشه‌های آزادی و زندگی خواهی نگریست.

ایده امروز گامی یگانه است که ما در هدایت شدن از اسارت به وضعیت آزادی کامل برمی‌داریم. بیایید این گام را امروز برداریم، تا بتوانیم به سرعت طریقی را طی کنیم که رستگاری به ما نشان می‌دهد، در حالی که هر گام را در ترتیب مقرر خود برمی‌داریم، و ذهن بارهای سنگین خود را یکی پس از دیگری رها می کند. ما برای این کار به زمان نیاز نداریم. فقط به اراده‌مندی نیاز داریم. زیرا آنچه ممکن است به نظر برسد به هزاران سال نیازمند است، به سادگی می‌تواند توسط فیض خداوند* فقط در یک لحظه انجام شود.

این پندار اندوهبار و نومیدانه که تو می‌توانی به دیگران حمله کنی و خودت بگریزی، تو را به صلیب میخکوب کرده است. احتمالا این رستگاری به نظر می‌رسیده است. اما این پندار صرفا محافظ این باور بوده است که ترس از خداوند* واقعیت دارد. و این پندار چیست جز دوزخ؟ چه کسی می‌تواند باور کند که پدرش* دشمن جان او است، جدا از او و در انتظار نابودی زندگی وی و محو کردنش از جهان، بدون اینکه ترس از دوزخ بر قلبش سایه افکنده باشد؟

چنین است شکل آن دیوانگی که تو باورش داری، اگر تو این پندار ترسناک را بپذیری که تو می‌توانی به دیگری حمله کنی و خودت آزاد باشی. تا زمانی که این شکل تغییر نکند، هیچ امیدی وجود ندارد. تا زمانی که ببینی این، دست‌کم بایستی کاملا ناممکن باشد، چگونه می‌تواند گریزی وجود داشته باشد؟ ترس از خداوند* برای هر کسی که می‌پندارد این اندیشه حقیقی است، واقعی می‌نماید. و او نخواهد توانست حماقت‌آمیز بودن این ترس را ادراک کند، یا حتی و جود داشتن آن را ببیند، آنچنان که پرسش در مورد آن ممکن باشد.

برای زیر سوال بردن این ترس در اصل، ابتدا باید شکل آن تغییر کند، دست‌کم تا آن اندازه که اجازه دهد ترس از تلافی کاهش یابد، و مسئولیت تا اندازه‌ای به تو بازگردانده شود. از آنجا تو حداقل می‌توانی بررسی کنی که آیا می‌خواهی در طول این مسیر دردناک حرکت کنی یا خیر. تا زمانی که این تبدیل انجام نشده باشد، تو نمی‌توانی ادراک کنی که این فقط پندارهای تو هستند که موجب ترست می‌شوند، و رهایی تو به خودت بستگی دارد.

گام بعدی ما آسان خواهد بود، اگر تو این گام را امروز برداری. از آنجا ما سریع‌تر حرکت خواهیم کرد. زیرا به محض اینکه تو بفهمی ناممکن است بتوانی جز توسط پندارهای خودت آسیب ببینی، ترس از خداوند* باید ناپدید شود. آنگاه تو نمی‌توانی باور کنی که ترس علت بیرونی دارد. و خداوند*، که تو در پندار تبعید او بودی، می‌تواند به درون آن ذهن مقدسی که هرگز ترکش نکرد با استقبال بازگردد.

نغمه‌ی رستگاری مطمئنا می‌تواند در ایده‌ای که امروز تمرین می‌کنیم، شنیده شود. اگر فقط تو بتوانی خودت را مصلوب کنی، پس به دنیا آسیبی نرسانده‌ای، و نیازی به ترس از انتقام و عقوبت دنیا نیست. و همچنین نیازی نیست که تو در وحشت و ترس وحشتناک از خداوند* که در پس این انتقام‌ها می‌بینی، پنهان شوی. آنچه بیش از همه از آن وحشت داری، رستگاری‌ات است. تو قدرتمند هستی، و این قدرت است که می‌خواهی. و تو آزاد هستی، و شادمان از آزادی. تو خواسته‌ای که هم ضعیف باشی و هم اسیر، زیرا از قدرت و آزادی خود ترسیده‌ای. اما رستگاری در آن‌ها نهفته است.

لحظه‌ای وجود دارد که در آن به نظر می‌رسد وحشت آنچنان تمامی ذهن تو را در بر می‌گیرد که ظاهرا به گریختن از آن هیچ امیدی نیست. زمانی که تشخیص دهی، یکبار و برای همیشه، که تو از خودت می‌ترسی، ذهن شکاف خود را ادراک می کند. و این شکاف زمانی مخفی شد که تو باور کردی می‌توان حمله را به بیرون هدایت کرد، و آن را از بیرون به درون بازگرداند. به نظر رسید در بیرون دشمنی وجود دارد که تو باید از آن بترسی. و اینچنین، خدای کوچکی در بیرون از خودت به دشمن جانی تو تبدیل شد؛ سرچشمهٔ ترس.

اینک، برای لحظه‌ای، قاتلی در درون تو ادراک می‌شود، حریص برای مرگ تو، مصمم برای مجازات کردن تو تا آن زمان که بتواند سرانجام تو را بکشد. اما در این لحظه، آن زمان نیز هست که در آن رستگاری فرا می‌رسد. زیرا ترس از خداوند* ناپدید شده است. و می‌توانی او* را فرا بخوانی تا با عشقش* تو را از اوهام نجات دهد، درحالی که او را پدر* و خودت را فرزندش* می‌خوانی. دعا کن که این لحظه بتواند زودتر روی دهد، همین امروز. از ترس عقب بنشین، و به سمت عشق پیش‌روی کن.

هیچ اندیشهٔ* خداوندی* وجود ندارد که برای کمک به تو در دستیابی به آن لحظه همراهت نشود، و برای اینکه به سرعت از آن عبور کنی، قطعی و برای همیشه. زمانی که ترس از خداوند* برطرف شده باشد، هیچ مانعی وجود ندارد که هنوز بین تو و صلح مقدس خداوند* باقی مانده باشد. این ایده که ما تمرین می‌کنیم چقدر مهربانانه و شفقت‌آمیز است! از آن استقبال کن، آنچنان که باید، زیرا رهایی تو است. حقیقتا فقط تو هستی که ذهنت می‌تواند برای مصلوب کردنش تلاش کند. اما رستگاری تو نیز از خود تو ناشی خواهد شد.', 'https://acim-farsi.org/workbook/lesson/196', 'https://acim-farsi.org/audio/workbook/lesson/196.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (197, 'من فقط می‌توانم سپاسگزاری‌ام را کسب کنم.', 'من فقط می‌توانم سپاسگزاری‌ام را کسب کنم.', 'من فقط می‌توانم سپاسگزاری‌ام را کسب کنم.

در اینجا ما دومین گام را برخواهیم داشت تا ذهنت را از این باور که نیرویی بیرونی بر نیروی خود تو تحمیل شده، آزاد کنیم. تو تلاشهایی برای محبت و بخشایش انجام می‌دهی. اما تو باز آن‌ها را به حمله تبدیل می‌کنی، تا زمانی که سپاسگزاری را در بیرون نیابی و تشکر خود را هدر ندهی. هدایای تو باید با افتخار دریافت شوند، مبادا نادیده گرفته شوند. و اینچنین است که تو می‌پنداری هدایای خداوند* در بهترین حالت وام هستند؛ و در بدترین حالت فریب‌هایی که می‌خواهند با تقلب بر دفاع‌های تو غلبه کنند، تا او* مطمئن شود که در صورت حمله به تو در کشتنت شکست نمی‌خورد.

چقدر آسان خداوند* می‌تواند با احساس گناه اشتباه گرفته شود، توسط آنان که نمی‌دانند پندارهایشان چه می‌تواند بکند. قدرت خود را نادیده بگیر، و آنگاه ضعف باید برایت به رستگاری تبدیل شود. خود را اسیر ببین، و میله‌های زندان به خانه تو تبدیل می‌شوند. تو از زندان خانگی فرار نخواهی کرد، یا به قدرت خود پی نخواهی برد، تا زمانی که احساس گناه و رستگاری را با هم یگانه می‌پنداری، تا زمانی که پیوند آزادی و رستگاری را ادراک نمی‌کنی، در حالی که قدرت در کنار آنها قرار دارد، قدرتی که باید طلبیده و آشکار شود، یافت شود و کاملا تشخیص داده شود.

این دنیا باید از تو سپاسگزاری کند زمانی که آزادی‌اش را از اوهامت به آن ارزانی می‌کنی. اما سپاس تو به خود تو نیز تعلق دارد، زیرا آزادی دنیا تنها می‌تواند بازتاب آزادی خود تو باشد. سپاسگزاری تو همهٔ چیزی است که موهبتهایت به آن نیاز دارد، اینکه این موهبتها ارزانی ماندگار از یک قلب سپاسگزار باشد، قلبی که برای همیشه از دوزخ رها شده است. آیا این وضعیت نیست که تو با بازگرداندن موهبتهایت خرابش می‌کنی، زیرا آن موهبتها موجب افتخارت نمی‌شوند؟ این تو هستی که به این موهبتها افتخار می‌دهی و بابت آنها به طرز مناسبی سپاسگزاری می‌کنی، زیرا این تو هستی که این موهبتها را دریافت کرده‌ای.

هیچ اهمیتی ندارد اگر کس دیگری بپندارد که هدایای تو ناشایسته هستند. در ذهن او بخشی وجود دارد که با ذهن تو در سپاسگزاری‌ات می‌پیوندد. هیچ اهمیتی ندارد اگر هدایای تو از دست رفته و بی‌تاثیر به نظر می‌رسند. آنها در جایی که داده می‌شوند، دریافت می‌گردند. در سپاسگزاری تو این موهبتها تماما پذیرفته می‌شوند، و با سپاس توسط قلب خود خداوند تصدیق می‌گردند. و آیا تو می‌خواهی آنها را پس بگیری، زمانی که او* با سپاس آن‌ها را پذیرفته است؟

خداوند* هر موهبتی را که تو به او* می‌دهی تبرک می‌کند، و هر موهبتی به او* داده می‌شود، زیرا هر موهبتی فقط می‌تواند به خود تو داده شود. و آنچه به خداوند* تعلق دارد، باید از آن او باشد. اما تو هرگز تا زمانی که فقط می‌بخشی تا دوباره حمله کنی، تشخیص نخواهی داد که موهبتهای او*، قطعی، ابدی، بی‌تغییر، بی‌حد، برای همیشه جاری، گسترش دهندهٔ عشق و افزون کنندهٔ سرور بی‌پایان تو هستند.

اگر هدایایی را که می‌دهی پس بگیری، خواهی پنداشت که آنچه به تو داده شده است از تو پس گرفته شده. اما بیاموز که اجازه دهی بخشایش آن گناهانی را که تو می‌پنداری بیرون از خودت می‌بینی برطرف سازد، و آنگاه تو هرگز نمی‌توانی بپنداری که هدایای خداوند* فقط برای مدتی کوتاه به تو قرض داده شده، مدتی کوتاه پیش از آنکه او* دوباره آن‌ها را در مرگ از تو برباید. زیرا آنگاه مرگ هیچ معنایی برای تو نخواهد داشت.

و با پایان یافتن این باور، ترس برای همیشه پایان می‌یابد. از خویشتن* خود برای این تشکر کن، زیرا او فقط سپاسگزار خداوند* است ، و او* برای تو از خودش* سپاسگزاری می‌کند. اما برای همهٔ آنان که زندگی می‌کنند، مسیحا* خواهد آمد، زیرا همهٔ آنان باید در او* زندگی و حرکت کنند. بودن او* در پدرش* امن است زیرا ارادهٔ* آنان با هم یگانه* است. سپاسگزاری آنان* برای همهٔ آنچه که آفریده‌اند پایانی ندارد، زیرا سپاسگزاری بخشی از عشق* می‌ماند.

سپاس از تو، فرزند* مقدس خداوند*. زیرا آنگاه که آفریده شدی، همهٔ چیزها در خویشتن* تو نهاده بود. و تو هنوز همانگونه هستی که خداوند* تو را آفرید. تو نمی‌توانی نور کمال خود را تاریک گردانی. درون قلبت، قلب* خداوند* نهاده شده. او* تو را عزیز می‌دارد، زیرا تو خودش* هستی. همه‌ی سپاسگزاری به تو تعلق دارد، به دلیل آنچه هستی.

سپاس را ارزانی کن همانگونه که دریافتش می‌کنی. باشد تا از همهٔ ناسپاسی نسبت به هر کسی که خویشتن* تو را کامل می‌سازد آزاد گردی. و از این خویشتن*، هیچ وجودی بیرون نیست. از همه‌ی کانالهای بی‌شماری که این خویشتن* را گسترش می‌دهند سپاسگزاری کن. همهٔ آنچه تو انجام می‌دهی به او* تقدیم می‌شود. همهٔ آنچه تو می‌اندیشی فقط می‌تواند اندیشه‌های* او* باشد، که با او* اندیشه‌های* مقدس خداوند* را سهیم هستی. اینک آن سپاسگزاری را که از خودت دریغ کرده‌ای، دریافت کن، آن سپاسگزاری که دریغش کردی زمانی که آن وظیفه را خداوند* به تو داده است، از یاد بردی. اما هرگز مپندار که او* زمانی ذره‌ای از سپاسگزاری کردن از تو فروگذار کرده است.', 'https://acim-farsi.org/workbook/lesson/197', 'https://acim-farsi.org/audio/workbook/lesson/197.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (198, 'تنها نکوهش من است که به من آسیب می‌زند.', 'تنها نکوهش من است که به من آسیب می‌زند.
تنها بخشایش خودم مرا آزاد می‌کند.', 'تنها نکوهش من است که به من آسیب می‌زند.

آسیب دیدن ناممکن است. و اما وهم، وهم می‌سازد. اگر تو می‌توانی نکوهش کنی، می‌توانی آسیب ببینی. زیرا باور کرده‌ای که می‌توانی آسیب بزنی، و حقی که برای خودت قائل شده‌ای اینک می‌تواند بر ضد تو استفاده شود، تا زمانی که آن را به عنوان یک چیز بی‌ارزش، نخواستنی و غیرواقعی کنار بگذاری. آنگاه تاثیر وهم متوقف می‌شود، و اثراتی که به نظر می‌رسید دارد باطل خواهد شد. آنگاه تو آزاد هستی، زیرا آزادی موهبت توست، و اکنون می‌توانی موهبتی را که داری دریافت کنی.

نکوهش کن و تو یک زندانی می‌شوی. ببخش و تو آزاد می‌شوی. چنین است قانونی که بر ادراک حکومت می‌کند. این قانونی نیست که معرفت آن را می‌شناسد، زیرا آزادی بخشی از معرفت است. بنابراین نکوهیدن در حقیقت ناممکن است. آنچه به نظر می‌رسد اثر و معلول آن است اصلا رخ نداده است. با این حال ما باید مدتی با آن‌ها برخورد کنیم گویی که رخ داده‌اند. وهم، وهم می‌سازد. جز یکی. بخشایش وهمی است که پاسخ به بقیهٔ اوهام است.

بخشایش همه رؤیاهای دیگر را از بین می‌برد، و اگرچه خودش یک رؤیا است، اما هیچ رؤیاهای دیگری را نمی‌پرورد. همه اوهام به جز این قطعا هزار برابر می‌شوند. اما این جایی است که اوهام به پایان می‌رسند. بخشایش پایان رؤیاهاست، زیرا رؤیای بیداری است. بخشایش خودش حقیقت نیست. با این حال به جایی اشاره می‌کند که حقیقت باید باشد و با یقین خود* خداوند* هدایت می‌کند. این رؤیایی است که در آن فرزند* خداوند* به خویشتنش* و پدرش* بیدار می‌شود، در حالیکه می‌داند که آن‌ها* یکی هستند.

بخشایش تنها مسیری است که به خروج از مصیبت، به فراتر از همه رنج‌ها و در نهایت دور شدن از مرگ، هدایت می‌کند. چگونه ممکن است راه دیگری وجود داشته باشد، در حالی که این نقشهٔ خود* خداوند* است؟ و چرا تو بخواهی با آن مخالفت کنی، با آن ستیز کنی، هزار راه بجویی که بخشایش باید در آن‌ها اشتباه باشد؟ هزار احتمال دیگر؟

آیا عاقلانه‌تر نیست که از اینکه پاسخ مشکلات خود را در دست داری خوشحال باشی؟ آیا هوشمندانه‌تر نیست که از آن یگانه* که رستگاری را عطا می‌کند تشکر کنی و هدیهٔ او* را با شکرگزاری بپذیری؟ و آیا این مهربانی با خودت نیست که آوای* او* را بشنوی و درس‌های ساده‌ای را که او* می‌خواهد تعلیم دهد بیاموزی، به‌ جای اینکه سعی کنی کلام* او* را نادیده بگیری، و کلام خود را به جای آن جایگزین کنی؟

کلام او کارساز است. کلام او نجات خواهد داد. کلام او دربردارنده همهٔ امید، همهٔ برکت و همهٔ سروری است که می‌توان روی این زمین یافت. کلام او* در خداوند* متولد شده و با عشق بهشت* به سوی تو می‌آید. کسانی که کلام او* را می شنوند سرود بهشت* را شنیده‌اند. زیرا این‌ها کلماتی هستند که در آن‌ها همه در نهایت به عنوان یک وجود پیوسته می‌شوند. و همانطور که این یکی محو خواهد شد، کلام* خداوند* به جای آن خواهد آمد، زیرا در آن زمان به یاد آورده خواهد شد و به آن عشق ورزیده خواهد شد.

این دنیا مکان‌های به ظاهر جداگانه بسیاری دارد که شفقت هیچ معنایی در آن‌ها ندارد و حمله موجه به نظر می‌رسد. با این حال همه یکی هستند؛ جایی که در آن مرگ به فرزند* خداوند* و پدرش* پیشکش می‌شود. ممکن است فکر کنی آن‌ها این پیشکش را پذیرفته‌اند. اما اگر دوباره به جایی که خون آن‌ها را دیدی نگاه کنی، در عوض معجزه‌ای را درک خواهی کرد. چقدر احمقانه است که باور کنی آن‌ها می‌توانند بمیرند! چقدر احمقانه است که باور کنی می‌توانی حمله کنی! چقدر دیوانه‌وار است که فکر کنی می‌توانی محکوم شوی و فرزند* مقدس خداوند* می‌تواند بمیرد!

سکون خویشتن* تو از پندارهایی مانند‌ این بی‌حرکت و دست نخورده باقی می‌ماند، و از هرگونه محکومیتی که ممکن است نیاز به بخشایش داشته باشد بی‌خبر است. رؤیاها از هر نوعی که باشند غریب و بیگانه با حقیقت هستند. و چه چیزی جز حقیقت می‌تواند اندیشه‌ای* داشته باشد که پلی به سوی آن بسازد که اوهام را به سوی دیگر بیاورد؟

امروز ما تمرین می‌کنیم که اجازه دهیم آزادی بیاید تا با تو خانهٔ خود را بسازد. حقیقت این کلمات را به ذهن تو می‌بخشد، تا کلید نور را بیابی و بگذاری تاریکی پایان یابد: تنها نکوهش من به من آسیب می‌زند. تنها بخشایش خودم مرا آزاد می‌کند. امروز فراموش نکن که هیچ شکلی از رنج وجود ندارد که نتواند یک فکر نابخشاینده را پنهان کند. همچنین هیچ شکلی از درد نمی‌تواند وجود داشته باشد که بخشایش نتواند آن را شفا دهد.

تنها توهمی را بپذیر که اعلام می‌کند در فرزند* خداوند* هیچ محکومیتی وجود ندارد و بهشت* فوراً به یاد می‌آید؛ دنیا فراموش شده، تمام باورهای عجیب و غریبش با آن فراموش شده، همانطور که چهرهٔ* مسیحا* سرانجام در این یک رؤیا بی‌حجاب آشکار می‌شود. این هدیه‌ای است که روح‌القدس* از طرف خداوند* پدرت* برای تو آورده است. بگذار امروز هم در زمین و هم در خانهٔ مقدس تو جشن گرفته شود. با هر دو مهربان باش، همانطور که گناهانی را که در آن، آنان را مقصر می‌پنداشتی می‌بخشی، و بی‌گناهی خود را می‌بینی که از چهرهٔ مسیحا* بر تو می‌تابد.

اکنون در سراسر دنیا سکوت حاکم است. اکنون در جایی سکون است که قبلاً هجوم دیوانه‌وار افکار بی‌معنا بود. اکنون نوری آرام در سراسر روی زمین وجود دارد که در خوابی بی‌رؤیا ساکت شده است. و اکنون کلام* خداوند* تنها بر آن باقی مانده است. فقط آن را می‌توان یک لحظهٔ دیگر ادراک کرد. سپس نمادها به پایان می‌رسند، و هر چیزی که تا به حال فکر می‌کردی ساخته‌ای، کاملاً از ذهنت پاک می‌شود، ذهنی که خداوند* برای همیشه می‌داند که تنها فرزندش* است.

هیچ نکوهشی در او نیست. او در قداست خود کامل است. او نیازی به افکار ترحم‌آمیز ندارد. چه کسی می‌تواند به او هدیه بدهد در حالی که همه چیز از آن اوست؟ و چه کسی می‌تواند رؤیا ببیند که به فرزندِ* خودِ* بی‌گناهی* بخشایش را عرضه می‌کند، او که چنان همانند اوست که فرزندش* اوست، که دیدن فرزند* به معنای درک نکردن هیچ چیز دیگر است، و فقط شناختن پدر*؟ در این رؤیتِ فرزند*، آنقدر کوتاه که حتی یک لحظه بین این بینایی و خود بی‌زمانی قرار نمی‌گیرد، تو رؤیت خود را می‌بینی و سپس برای همیشه در خداوند* ناپدید می‌شوی.

امروز ما به پایان هر چیزی که هنوز بین این رؤیت و بینایی ما قرار دارد نزدیک‌تر شده‌ایم. و ما خوشحالیم که تا اینجا پیش رفته‌ایم و می‌دانیم که او* که ما را به اینجا رساند، اکنون ما را رها نخواهد کرد. زیرا او* هدیه‌ای را که امروز خداوند* از طریق او* به ما عطا کرده است به ما خواهد داد. اکنون زمان رستگاری تو است. زمان آن رسیده است. امروز زمان آن فرا رسیده است.', 'https://acim-farsi.org/workbook/lesson/198', 'https://acim-farsi.org/audio/workbook/lesson/198.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (199, 'من یک بدن نیستم. من آزاد هستم.', 'من یک بدن نیستم. من آزاد هستم.
من آن آوا* را که خداوند* به من عطا کرده است می‌شنوم، و ذهنم تنها از این اطاعت می‌کند.
من آن آوا* را که خداوند* به من عطا کرده است می‌شنوم، و ذهنم تنها از این اطاعت می‌کند.', 'من یک بدن نیستم. من آزاد هستم.

آزادی باید ناممکن باشد مادامی که تو یک بدن را به عنوان خودت ادراک می‌کنی. بدن یک محدودیت است. آن کس که می‌خواهد آزادی را در یک بدن جستجو کند، جایی به دنبال آن می‌گردد که نمی‌تواند یافت شود. ذهن می‌تواند آزاد شود زمانی که دیگر خود را محبوس در یک بدن نبیند، به سختی بسته به آن و در سایه‌ی حضورش. اگر این حقیقت بود، ذهن حقیقتا آسیب‌پذیر می‌بود!

آن ذهن که به روح‌القدس* خدمت می‌کند برای همیشه نامحدود است، از همه نظر، ورای قانون‌های زمان و مکان، در حالی که توسط هیچ پیش‌دریافتی اسیر نیست، و با اقتدار و توانایی برای انجام هرچه که از او خواسته شود. افکار حمله نمی‌توانند وارد چنین ذهنی شوند، زیرا این ذهن به سرچشمهٔ* عشق داده شده، و ترس هرگز نمی‌تواند در ذهنی وارد شود که خودش را به عشق پیوسته است. این ذهن در خداوند* آرام می‌گیرد. و چه کسی می‌تواند هراسان باشد اگر در بی‌گناهی می‌زید، و فقط عشق می‌ورزد؟

برای پیشرفت تو در این دوره، اساسی است که ایده‌ی امروز را بپذیری و آن را بسیار گرامی بداری. نگران نباش که این ایده برای نفس چنین دیوانه‌وار می‌نماید. نفس بدن را عزیز می‌دارد زیرا در آن ساکن است، و در اتحاد با منزلی می‌زید که آن را ساخته است. بدن بخشی از آن وهم است که نفس را از یافت شدن اینکه خودش توهمی است حفاظت می‌کند.

نفس در بدن پنهان می‌شود، و در اینجا است که می‌توان آن را همان گونه که هست دید. بی‌گناهی خود را اعلام کن و آزاد می‌شوی. این بدن ناپدید می‌شود، زیرا تو هیچ نیازی به آن نداری به جز آن نیاز که روح‌القدس* می‌بیند. برای این نیاز، به نظر خواهد آمد که بدن شکل مناسبی برای آن کار است که ذهن باید انجام دهد. در این صورت بدن به وسیله نقلیه‌ای تبدیل می‌شود که کمک می‌کند بخشایش به یک هدف فراگیر عام گسترش یابد، که بر طبق نقشهٔ خداوند* باید به آن برسد.

ایده‌ی امروز را گرامی بدار، و آن را امروز و هر روز تمرین کن. آن را بخشی از هر برنامه‌ی تمرین که انجام می‌دهی بساز. هیچ اندیشه‌ای وجود ندارد که نتواند از این طریق به قدرت کمک کردن به این دنیا دست یابد، و همچنین هیچ اندیشه‌ای نیست که از این طریق نتواند به افزایش موهبت‌های تو دست یابد. ما با این ایده، فراخوان آزادی را در سراسر این دنیا به صدا در می‌آوریم. و آیا تو می‌خواهی از پذیرش موهبت‌هایی که عطا می‌کنی، مستثنی شوی؟

روح‌القدس* منزل ذهن‌هایی است که آزادی را می‌جویند. ایشان در او* آن چه را که جسته‌اند، یافته‌اند. اینک هدف بدن مبهم نیست. و بدن در قابلیت برای خدمت به یک هدف واحد کامل می‌شود. در پاسخ بدون تعارض و صریح به ذهن، فقط در حالی که هدفش را اندیشه‌ی آزادی می‌داند، این بدن خدمت می‌کند، و به خوبی به هدفش خدمت می‌کند. بدون قدرت اسیر کردن، بدن خدمتگزار ارزشمندی برای آن آزادی است که ذهن در روح‌القدس* می‌جوید.

امروز آزاد باش. و آزادی را به عنوان هدیه‌ی خود نزد کسانی بیاور که هنوز باور دارند درون یک بدن اسیر هستند. آزاد باش، آن چنان که روح‌القدس* بتواند از گریز تو از اسارت استفاده کند، برای آزاد کردن آن بسیاری که خودشان را اسیر و درمانده و هراسان ادراک می‌کنند. بگذار عشق از طریق تو جایگزین ترس‌های آنان گردد. اینک رستگاری را بپذیر، و ذهنت را به او* بده که* تو را فرا می‌خواند تا این هدیه را برای او* بسازی. زیرا او می‌خواهد به تو آزادی کامل را عطا کند، سرور کامل، و امید را که تحقق کاملش را در خداوند* می‌یابد.

تو فرزند* خداوند* هستی. تو برای همیشه در نامیرایی زندگی می‌کنی. آیا نمی‌خواهی ذهنت را به این سو برگردانی؟ پس خوب این اندیشه را که روح‌القدس* برای امروز به تو می‌دهد تمرین کن. برادرانت در آزادی به همراه تو با این اندیشه می‌ایستند؛ دنیا به همراه تو متبرک می‌شود، فرزند* خداوند* بیش از این نمی‌گرید، و بهشت* از بابت افزایش سروری که تمرین تو حتی برای آن پیش می‌آورد، سپاسگزاری می‌کند. و خود* خداوند* عشق* و شادمانی‌اش را هر زمان که تو چنین می‌گویی گسترش می‌دهد: من یک بدن نیستم. من آزاد هستم. من آن آوا* را که خداوند* به من عطا کرده است می‌شنوم، و ذهنم تنها از این اطاعت می‌کند.', 'https://acim-farsi.org/workbook/lesson/199', 'https://acim-farsi.org/audio/workbook/lesson/199.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (200, 'هیچ صلحی جز صلح خداوند* وجود ندارد.', 'هیچ صلحی جز صلح خداوند* وجود ندارد.
هیچ صلحی جز صلح خداوند* وجود ندارد، و من خوشحالم و شکرگزارم که چنین است.', 'هیچ صلحی جز صلح خداوند* وجود ندارد.

بیش از این جستجو نکن. تو صلحی جز صلح خداوند* نخواهی یافت. این واقعیت را بپذیر و خود را از رنج ناامیدی‌های تلخ‌تر، یأس غم‌افزا و احساس ناامیدی سرد و تردید نجات بده. بیش از این جستجو نکن. هیچ چیز دیگری جز صلح خداوند* برای تو وجود ندارد تا بیابی، مگر اینکه به دنبال بدبختی و درد باشی.

این آخرین نقطه‌ای است که هر کس باید در نهایت به آن برسد، تا تمام امید به یافتن خوشحالی را در جایی که وجود ندارد کنار بگذارد؛ نجات توسط چیزی که فقط می‌تواند آسیب بزند؛ ساختن صلح از هرج و مرج، لذت از درد، و بهشت* از دوزخ. دیگر سعی نکن از طریق باخت پیروز شوی، و نیز برای زندگی کردن بمیری. زیرا اینگونه تو نمی‌توانی جز در حال درخواست برای شکست باشی.

با این حال می‌توانی به همین آسانی عشق، شادمانی، و زندگی ابدی در صلحی که پایانی ندارد را بخواهی. این را بخواه و فقط می‌توانی برنده شوی. خواستن آنچه که پیشاپیش داری قطعاً موفقیت‌آمیز است. خواستن اینکه آنچه غیرحقیقی است حقیقی باشد فقط می‌تواند شکست بخورد. خودت را به خاطر تصورات بیهوده ببخش، و دیگر به دنبال چیزی نباش که نمی‌توانی بیابی. زیرا چه چیزی احمقانه‌تر از جستجو و جستجو و جستجوی دوباره برای دوزخ است، در حالی که فقط باید با چشمان باز نگاه کنی تا متوجه شوی که بهشت/ در مقابل تو قرار دارد، از طریق دری که به راحتی برای استقبال از تو باز می‌شود؟

به خانه بیا. تو شادمانی خود را در مکان‌های خارجی و در شکل‌های بیگانه‌ای که برایت هیچ معنایی ندارند پیدا نکرده‌ای، هر چند به دنبال معنا بخشیدن به آنها بوده‌ای. این دنیا جایی نیست که تو به آن تعلق داری. تو اینجا یک غریبه‌ای. اما این امکان به تو داده شده تا ابزاری را بیابی که به وسیله آن دنیا دیگر برای کسی زندان یا محبس نباشد.

آزادی در جایی که فقط زنجیرها و درهای آهنی دیدی به تو داده شده است. اما اگر می‌خواهی گریز را پیدا کنی، باید ذهن خود را در مورد هدف دنیا تغییر دهی. تو در بند خواهی بود تا زمانی که همه دنیا را متبرک ببینی، و همگان از اشتباهات تو آزاد شوند و هر کس آنگونه که هست گرامی داشته شود. تو او را نساختی؛ همانطور که خودت را نساختی. و هنگامی که یکی را آزاد کنی، دیگری همانگونه که هست پذیرفته می‌شود.

بخشایش چه کاری انجام می‌دهد؟ در حقیقت بخشایش هیچ وظیفه‌ای ندارد، و هیچ کاری انجام نمی‌دهد. زیرا در بهشت* ناشناخته است. تنها در دوزخ است که به آن نیاز است، و جایی که باید به وظیفه‌ای نیرومند خدمت کند. آیا گریز فرزند* محبوب خداوند* از رؤیاهای شرورانه‌ای که تصور می‌کند، اما باور دارد که حقیقت دارند، هدف شایسته‌ای نیست؟ چه کسی می‌تواند امید به بیشتر از این داشته باشد، در حالی که به نظر می‌رسد بین موفقیت و شکست انتخابی وجود دارد؛ بین عشق و ترس؟

هیچ صلحی جز صلح خداوند* وجود ندارد، زیرا او* یک فرزند* دارد که نمی‌تواند دنیایی را در مخالفت با ارادهٔ* خداوند* و ارادهٔ خودش که همان ارادهٔ* خداوند* است, بسازد. او می‌تواند به یافتن چه چیزی در چنین دنیایی امیدوار باشد؟ این دنیا نمی‌تواند واقعیت داشته باشد، زیرا هرگز افریده نشد. آیا اینجاست که او به دنبال صلح است؟ یا همانطور که به آن نگاه می‌کند باید ببیند که، دنیا فقط می‌تواند فریب دهد؟ با این حال او می‌تواند بیاموزد که به آن به روش دیگری نگاه کند و صلح خداوند* را بیابد.

صلح پلی است که همگان از آن عبور خواهند کرد، تا این دنیا را پشت سر بگذارند. اما صلح در درون دنیایی آغاز می‌شود که متفاوت ادراک می‌شود، و از این درک تازه به دروازهٔ بهشت* و طریق ورای آن منتهی می‌شود. صلح پاسخی است به اهداف متضاد، سفرهای بی‌معنا، تعقیب‌های بیهوده و پوچ و کوشش‌های بی‌معنا. اکنون طریق آسان است، با شیب ملایم به سمت پلی که در آن آزادی در صلح خداوند* نهفته است.

بگذارید امروز دیگر طریقمان را گم نکنیم. ما به بهشت* می رویم و مسیر سرراست است. فقط اگر بخواهیم سرگردان باشیم، می‌تواند تأخیر به وجود آید و زمان بیهوده در راه‌های خارآلود فرعی تلف شود. تنها خداوند* قطعی است و او* گام‌های ما را هدایت می‌کند. او* فرزند* خود را در نیازمندی رها نخواهد کرد و اجازه نخواهد داد او برای همیشه از خانه خود دور باشد. پدر* فرا می‌خواند؛ فرزند* خواهد شنید. و این تمام چیزی است که به نظر می رسد دنیایی جدا از خداوند* است، جایی که بدن‌ها واقعیت دارند.

اکنون آنجا سکوت است. دیگر جستجو نکن. تو به جایی رسیده‌ای که مسیر با برگ‌های آرزوهای دروغین فرش شده است، که از درختان ناامیدی که قبلاً در جستجوی آن‌ها بودی فرو افتاده‌اند. اینک آنها زیر پای تو هستند. و تو به بالا و به سمت بهشت* نگاه می‌کنی، با چشمان بدن که اکنون فقط برای یک لحظه بیشتر در حال خدمت کردن هستند. صلح در نهایت سرانجام شناخته شده است، و تو می‌توانی آغوش لطیف آن را احساس کنی که قلب و ذهنت را با آسودگی و با عشق احاطه کرده است.

امروز ما به دنبال هیچ خدای دروغینی نیستیم. صلح را نمی‌توان در آن‌ها یافت. صلح خداوند* از آن ماست و فقط این را می‌پذیریم و می‌خواهیم. امروز صلح بر ما باد. زیرا ما راه ساده و شادی را یافته‌ایم تا دنیای ابهام را ترک کنیم و هدف‌های متغیر و رؤیاهای فردی خود را با هدف واحد و همراهی جایگزین کنیم. زیرا صلح وحدت است، اگر از جانب خداوند* باشد. ما بیش از این جستجو نمی‌کنیم. ما به خانه نزدیک هستیم، و هر بار که این کلمات را می‌گوییم باز هم نزدیک‌تر می‌شویم: هیچ صلحی جز صلح خداوند* وجود ندارد، و من خوشحالم و شکرگزارم که چنین است.', 'https://acim-farsi.org/workbook/lesson/200', 'https://acim-farsi.org/audio/workbook/lesson/200.mp3', 'user_specified', '[]');
INSERT INTO lessons (lesson_number, title_fa, reminder_fa, full_text_fa, text_url_fa, audio_url_fa, schedule_type, schedule_options_json) VALUES (201, 'مرور (۱۸۱)', 'من یک بدن نیستم. من آزاد هستم. زیرا هنوز آن‌گونه هستم که خداوند* مرا آفرید.

(۱۸۱) من به برادرانم اعتماد می‌کنم، که با من یگانه هستند. هیچ‌ کس نیست که برادر من نباشد. من با یگانگی با جهان و خداوند*، پدرم*، یگانه آفرینندهٔ* کمال که خویشتن* من است و برای همیشه با من یگانه* است، متبرک هستم.

من یک بدن نیستم. من آزاد هستم.
زیرا هنوز آن‌گونه هستم که خداوند* مرا آفرید.', 'من یک بدن نیستم. من آزاد هستم. زیرا هنوز آن‌گونه هستم که خداوند* مرا آفرید.

